INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('adara', '{"Endon":{"aff":90,"type":"familial","relation":"father and mentor","note":"Adara is apprenticed to her father and deeply admired by him for her natural silversmithing talent.","best":"Endon praises that she bends silver so naturally their grandmother would have cried seeing it."},"Kerah":{"aff":85,"type":"familial","relation":"mother","note":"Adara helps at her mother''s jewelry stall and shares a warm, proud bond with her.","best":"Kerah sells Adara''s necklaces and tells her how proud she is of her craftsmanship."},"Cade":{"aff":70,"type":"familial","relation":"older brother","note":"Adara misses her brother and anxiously awaits his return from fighting with the Stormcloaks.","worst":"She repeatedly asks when Cade is coming home, not understanding why he must stay away at war."}}')
