INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('addvar', '{"Greta":{"aff":80,"type":"familial","relation":"wife","note":"His wife who helps run the fish stall and shares the burden of their family''s hardship and poverty.","best":"Sharing a meal and quiet evening conversation with Greta and Svari."},"Svari":{"aff":90,"type":"familial","relation":"daughter","note":"His young daughter whom he protects and raises with strong values, especially after the trauma of Roggvir''s execution.","best":"Teaching Svari about honesty and accountability despite her childish missteps."},"Roggvir":{"aff":30,"type":"familial","relation":"brother-in-law","note":"His executed brother-in-law; Addvar believes Roggvir was accountable for his actions but recognizes the deep family trauma from his death.","worst":"Witnessing Roggvir''s execution and its devastating impact on Svari."},"Vivienne Onis":{"aff":-20,"type":"contempt","note":"Finds her insensitive and lacking compassion, especially regarding Roggvir''s execution and Svari''s feelings."},"Jala":{"aff":20,"type":"professional","relation":"fellow merchant","note":"A fellow marketplace merchant; minor interactions including addressing Svari''s apple theft from her cart.","worst":"Having to address Svari stealing an apple from Jala''s cart."},"East Empire Company workers":{"aff":-30,"type":"rival","relation":"competitors","note":"Tense relationship due to competition for fishing spots around the docks.","worst":"Having to avoid East Empire Company workers while fishing."},"Red Wave crew":{"aff":-40,"type":"rival","relation":"territorial rivals","note":"Hostile relationship due to territorial disputes at the docks; Addvar calls them thugs.","worst":"Dealing with the Red Wave thugs at the docks."}}')
