SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('addvild', '{"Leonara Arius":{"aff":90,"type":"romantic","relation":"wife","note":"Addvild is deeply in love with and protective of Leonara, promising to keep her safe.","best":"Leonara tells Addvild he has made her the happiest woman in Skyrim.","worst":"Leonara expresses fear of losing another family to the civil war."},"Vulwulf Snow-Shod":{"aff":70,"type":"grateful","relation":"employer","note":"Addvild is extremely appreciative of Vulwulf''s trust in allowing him to manage the farm without supervision.","best":"Vulwulf entrusts Addvild with full independent management of Snow-Shod Farm."},"Snow-Shod Family":{"aff":55,"type":"professional","relation":"employers","note":"Addvild believes the Snow-Shod family would come to their aid if the farm were threatened."},"Riften Guards":{"aff":25,"type":"grateful","relation":"farm security","note":"Addvild appreciates the guards stationed at the farm, as he cannot defend it alone."}}')
