INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('adrianne_avenicci', '{"Ulfberth War-Bear":{"aff":85,"type":"romantic","relation":"husband and business partner","note":"They co-own and operate Warmaiden''s; she credits their marriage with keeping the business afloat under Stormcloak rule.","best":"Building Warmaiden''s into a successful armory together."},"Proventus Avenicci":{"aff":70,"type":"familial","relation":"father","note":"She secretly advises her father, the Jarl''s steward, indirectly shaping Whiterun''s governance.","best":"Influencing policy through her father that benefited the common folk."},"Eorlund Gray-Mane":{"aff":45,"type":"admirer","relation":"fellow blacksmith","note":"She acknowledges his legendary skill and only asks for a fair chance alongside him.","best":"A moment of mutual respect over a particularly well-crafted piece of steel."},"Jarl Balgruuf the Greater":{"aff":40,"type":"professional","relation":"jarl","note":"She respects his leadership and influences his decisions indirectly through her father."}}')
