INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ahtar', '{"Jala":{"aff":65,"type":"romantic","relation":"romantic interest","note":"Shares her home and is marked internally as courting her, though neither speaks of it openly"},"Jaree-Ra":{"aff":-80,"type":"contempt","relation":"despised criminal","note":"Openly wishes to execute him and blames his presence on Torygg''s death","worst":"Filthy Argonian set foot in the city under Torygg''s watch"},"Sybille Stentor":{"aff":-15,"type":"suspicious","relation":"dungeon visitor","note":"Uneasy about her occasional requests for ''volunteers'' from the prison"},"Captain Aldis":{"aff":35,"type":"professional","relation":"colleague","note":"Fellow law enforcement official in Solitude"},"Legate Rikke":{"aff":45,"type":"platonic","relation":"friend","note":"Marked as a friend though the relationship is never publicly acknowledged"},"Captain Hargar":{"aff":-70,"type":"enemy","relation":"escaped prisoner","note":"Bandit leader who escaped on his watch; Ahtar covered it up and wants him silenced","worst":"Prisoner escaped during his custody, forcing him to falsify records"}}')
