INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aia_arria', '{"Pantea Ateia":{"aff":75,"type":"mentor","relation":"vocal instructor","note":"Respects her mentor deeply while secretly believing she will soon surpass her abilities.","best":"Being declared the only student at the College with actual talent.","worst":"Being told she still needs training when she believes her voice already rivals Pantea''s."},"Jorn":{"aff":-20,"type":"dismissive","relation":"fellow student","note":"Looks down on him for wanting to join the Imperial Legion, believing soldiers cannot appreciate music."},"Illdi":{"aff":-15,"type":"dismissive","relation":"classmate","note":"Considers her naive and beneath her talents; Illdi has called her mean."},"Jarl of Falkreath":{"aff":30,"type":"professional","relation":"future patron","note":"Pantea has arranged for her to perform in his court after graduation."},"Inge Six-Fingers":{"aff":15,"type":"professional","relation":"instructor","note":"Accepts instruction but believes her solo performances are already flawless."}}')
