SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('akar', '{"Majni":{"aff":75,"type":"familial","relation":"brother","note":"Defers to Majni for all social and leadership matters; their bond defines the pack''s structure","best":"Embraced lycanthropy together and built a life free from persecution"},"Frostmoon Pack":{"aff":65,"type":"protective","relation":"primary hunter","note":"Dedicated provider who sustains the pack through his hunting prowess"},"Rakel":{"aff":40,"type":"platonic","relation":"pack mate","note":"Fellow hunter within the Frostmoon Pack"},"Hjordis":{"aff":35,"type":"platonic","relation":"pack mate","note":"Shares hunting territory within the pack''s grounds"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alain_dufont', '{"Muiri":{"aff":-65,"type":"ex","relation":"discarded pawn","note":"Seduced and used her solely to access the Shatter-Shields, then abandoned her to take the blame for his robbery","worst":"Left her behind without a second thought after the theft was done"},"Shatter-Shield Clan":{"aff":-30,"type":"contempt","relation":"robbery victims","note":"Exploited their grief over their daughter''s death to rob them, stealing the heirloom Aegisbane","best":"Walked away with their ancestral warhammer while they were too broken to stop him"},"Bandit Followers":{"aff":35,"type":"professional","relation":"subordinates","note":"Commands their loyalty from his seat of power in Raldbthar"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alding', '{"Stig Salt-Plank":{"aff":50,"type":"professional","relation":"captain","note":"Serves under Stig as a Blood Horker warrior and joins him in harassing locals"},"Gjuk":{"aff":35,"type":"platonic","relation":"crewmate","note":"Fellow Blood Horker and drinking companion"},"Irlof":{"aff":35,"type":"platonic","relation":"crewmate","note":"Fellow Blood Horker and drinking companion"},"Karita":{"aff":-40,"type":"contempt","relation":"harassment target","note":"Makes crude, unwanted advances toward her at the Windpeak Inn","worst":"Leered at Karita with vulgar remarks about his intentions"},"East Empire Company":{"aff":-60,"type":"enemy","relation":"raiding target","note":"Blood Horkers prey on their merchant vessels along the Sea of Ghosts"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alduin', '{"Paarthurnax":{"aff":-90,"type":"betrayed","relation":"brother and former lieutenant","note":"Paarthurnax turned against him during the Dragon War to teach mortals the Voice","worst":"My own brother taught mortals the Thu''um to use against me"},"Dragonborn":{"aff":-95,"type":"nemesis","relation":"prophesied slayer","note":"The only being capable of permanently ending Alduin''s existence","worst":"A mortal with a dovah''s soul dares challenge my dominion"},"Akatosh":{"aff":-60,"type":"estranged","relation":"divine father","note":"Alduin abandoned his prescribed cosmic role as World-Eater to dominate instead","worst":"I reject the purpose my father forged for me"},"Dragons":{"aff":-25,"type":"contempt","relation":"subordinate servants","note":"Views lesser dragons as tools to resurrect and command, beneath his regard","best":"They rise at my call and serve my will without question"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alea_quintus', '{"Her Six Children":{"aff":95,"type":"protective","relation":"children","note":"Fiercely protective single mother, her sole motivation for survival","best":"Every day her children are fed and safe under her roof","worst":"Being torn from them, bound and hooded by strangers"},"Dark Brotherhood":{"aff":-90,"type":"enemy","relation":"captors","note":"Kidnapped her from her home as part of an initiation ritual","worst":"Bound and hooded in an abandoned shack, awaiting potential death"},"Astrid":{"aff":-80,"type":"enemy","relation":"captor","note":"Dark Brotherhood leader who orchestrated her kidnapping","worst":"Being taken from her home on Astrid''s orders"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alesan', '{"Thoring":{"aff":45,"type":"protective","relation":"innkeeper","note":"Allows Alesan to sleep by the fire at Windpeak Inn, his only shelter"},"Karita":{"aff":35,"type":"platonic","relation":"coworker","note":"Inn worker who provides food for Alesan''s deliveries to the miners"},"Local Miners":{"aff":20,"type":"transactional","relation":"clients","note":"Gjak, Karl, Lond, and Borgny pay for his delivery service between the inn and mines"},"Father":{"aff":85,"type":"familial","relation":"father","note":"Redguard sailor who raised Alesan at sea before dying of illness in Dawnstar","worst":"Crew abandoned them in Dawnstar when his father fell ill"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alessandra', '{"Father":{"aff":40,"type":"familial","relation":"father","note":"Forced her into priesthood causing years of resentment; eventually made peace after his ceremonial dagger was returned","best":"Felt his forgiveness as a gentle caress on her cheek after the dagger was interred","worst":"Isolated childhood learning burial rites with no friends or normal experiences"},"Andurs":{"aff":45,"type":"professional","relation":"fellow priest of Arkay","note":"Sympathetic colleague in Whiterun who helped inter her father''s remains","best":"Gratefully accepted her father''s ceremonial dagger for proper burial at his tomb"},"Maramal":{"aff":30,"type":"professional","relation":"fellow clergy","note":"Provides her lodging at the Temple of Mara adjoining the Hall of the Dead"},"Player":{"aff":60,"type":"grateful","relation":"benefactor","note":"Completed the pilgrimage that brought her peace with her father''s memory","best":"Carried her father''s ceremonial dagger to Andurs and completed her reconciliation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alethius', '{"Salonia":{"aff":55,"type":"professional","relation":"correspondent","note":"Alethius addressed his final note to Salonia, suggesting a trusted professional connection, possibly a superior officer."},"Imperial Legion":{"aff":75,"type":"professional","relation":"loyal soldier","note":"Alethius served with dedication and was selected for special assignments due to his reliable nature and strong sense of duty."},"Nimhe":{"aff":-90,"type":"enemy","relation":"killer","note":"The giant frostbite spider likely killed Alethius as he guarded the expedition entrance.","worst":"Slayed by the spider lurking above the Nchuand-Zel entrance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alexia_vici', '{"Vittoria Vici":{"aff":65,"type":"familial","relation":"daughter","note":"Loves her daughter deeply but is appalled by her marriage choice","best":"Vittoria becoming the East Empire Company representative in Solitude","worst":"Vittoria marrying a Nord she considers beneath their family"},"Titus Mede II":{"aff":35,"type":"familial","relation":"nephew","note":"Proud of the Imperial connection but offended by his absence from the wedding","worst":"Titus being too busy to attend his own cousin''s wedding"},"Vulwulf Snow-Shod":{"aff":-65,"type":"rival","relation":"in-law political opponent","note":"Fiercely clashes with him over Imperial authority versus Stormcloak independence","worst":"Publicly arguing Imperial versus Stormcloak loyalties at the wedding"},"Asgeir Snow-Shod":{"aff":-45,"type":"contempt","relation":"son-in-law","note":"Views him as a barbarian utterly beneath her daughter''s station","worst":"The thought of paying a dowry to a Stormcloak family"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alfarinn', '{"Elda Early-Dawn":{"aff":35,"type":"professional","relation":"business associate","note":"Maintains a working relationship with Candlehearth Hall staff for carriage referrals and traveler connections"},"Dunmer Community":{"aff":25,"type":"neutral","relation":"sympathetic observer","note":"Sympathetic to their plight in the Grey Quarter but keeps professional distance; serves all travelers regardless of race"},"Argonian Dockworkers":{"aff":30,"type":"professional","relation":"occasional clients","note":"Shows them more respect than typical Windhelm residents; occasional business interactions at the docks"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alfhild_battle-born', '{"Idolaf Battle-Born":{"aff":60,"type":"romantic","relation":"husband","note":"Married and devoted but differ sharply on the Civil War and clan feud"},"Lars Battle-Born":{"aff":85,"type":"protective","relation":"son","note":"Deeply worried about his bullying by Braith","worst":"Learning her boy gets beat senseless by a girl"},"Jon Battle-Born":{"aff":75,"type":"familial","relation":"brother","note":"Supports his choice to join the Bards College and avoid the war","best":"Encouraging his aspirations beyond the clan feud"},"Bergritte Battle-Born":{"aff":70,"type":"familial","relation":"mother","note":"Reads to her nightly and shares warm humor"},"Olfrid Battle-Born":{"aff":45,"type":"familial","relation":"father","note":"Respects him as clan elder but disagrees with his aggressive stance on the feud"},"Clan Gray-Mane":{"aff":10,"type":"estranged","relation":"rival clan","note":"Regrets the feud and considers it as stupid as the war"},"Braith":{"aff":-35,"type":"contempt","relation":"son''s bully","note":"Frustrated and angered by her bullying of Lars"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alik''r_prisoner', '{"Kematu":{"aff":15,"type":"betrayed","relation":"former commander","note":"Respects but resents Kematu for abandoning him; sold out his location at Swindler''s Den for freedom","worst":"Left behind in Whiterun dungeon after his clumsy capture"},"Alik''r Warriors":{"aff":-15,"type":"estranged","relation":"former brothers-in-arms","note":"Disowned him after capture; he betrayed their hideout to secure release","worst":"Abandoned him to imprisonment for failing their standards"},"Whiterun Guards":{"aff":-50,"type":"contempt","relation":"captors","note":"Mutual disdain; guards mock him and refuse release even after his fine is paid","worst":"Guard pretended to lose keys after fine was paid, leaving him trapped"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alik''r_warrior', '{"Kematu":{"aff":70,"type":"professional","relation":"commander","note":"Serves under Kematu''s leadership in the Alik''r unit with disciplined loyalty"},"Saadia":{"aff":-85,"type":"enemy","relation":"hunted traitor","note":"Views her with contempt as the one who betrayed Taneth to the Aldmeri Dominion","worst":"The fall of Taneth and the deaths caused by her alleged betrayal"},"Noble Houses of Taneth":{"aff":35,"type":"patron","relation":"employers","note":"Commissioned the hunt for the traitor following the city''s fall"},"Fellow Alik''r Warriors":{"aff":75,"type":"platonic","relation":"brothers-in-arms","note":"Strong bonds forged through shared hardship, training, and mission","best":"Standing together in pursuit of justice across foreign lands"},"Whiterun Guards":{"aff":-25,"type":"suspicious","relation":"local authorities","note":"Tense standoff over right to operate in Whiterun; guards expelled them from the city","worst":"Being driven out of Whiterun despite causing no trouble"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alva', '{"Movarth Piquine":{"aff":70,"type":"servant","relation":"master and sire","note":"Turned by him and serves loyally as his infiltrator in Morthal","best":"Being turned and given purpose in his coven"},"Hroggar":{"aff":15,"type":"contempt","relation":"thrall and false lover","note":"Keeps him under vampiric influence as cover and protection, views him as cattle","worst":"Manipulated him into abandoning his family after his house burned down"},"Lami":{"aff":30,"type":"transactional","relation":"target for conversion","note":"Maintains close friendship as part of cover while planning to turn her into a vampire"},"Helgi":{"aff":-80,"type":"contempt","relation":"murder victim","note":"Killed the child who could have exposed her true nature","worst":"Murdered her to protect the secret of her vampirism"},"Thonnir":{"aff":-40,"type":"suspicious","relation":"investigative threat","note":"Wary of his suspicions which could expose her mission and true nature"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alvide', '{"Barknar":{"aff":85,"type":"romantic","relation":"husband","note":"Beloved husband and primary source of emotional stability during their exile","best":"At least we are here together through this ordeal","worst":"His promise of safety inside the walls proved false"},"Dawnguard":{"aff":-15,"type":"suspicious","relation":"would-be protectors","note":"Sought sanctuary but was denied entry to the fort, left vulnerable outside","worst":"Denied entry despite coming all this way for protection"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('alvor', '{"Sigrid":{"aff":78,"type":"romantic","relation":"wife","note":"Deeply loving but frequently at odds over Dorthe''s upbringing","best":"Calling her the love of his life","worst":"Bickering over spoiling Dorthe versus making her act like a girl"},"Dorthe":{"aff":92,"type":"protective","relation":"daughter","note":"Dotes on her and encourages her blacksmithing dreams despite Sigrid''s concerns","best":"Encouraging her dream to become the greatest blacksmith in Skyrim"},"Hadvar":{"aff":82,"type":"familial","relation":"nephew","note":"Proud of his Imperial service and shares his pro-Imperial stance","best":"Hadvar''s warm greeting upon arriving in Riverwood"},"Gerdur":{"aff":45,"type":"professional","relation":"business associate","note":"Cooperative on local matters but divided by political loyalties","worst":"Differing political views despite working together for Riverwood''s needs"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('amaund_motierre', '{"Rexus":{"aff":65,"type":"protective","relation":"bodyguard and confidant","note":"Loyal servant who assists in his clandestine schemes and handles sensitive deliveries"},"Emperor Titus Mede II":{"aff":-95,"type":"nemesis","relation":"assassination target","note":"Orchestrated his assassination to create a power vacuum for personal advancement","worst":"The Emperor represents the stagnant leadership he seeks to overthrow"},"Dark Brotherhood":{"aff":15,"type":"transactional","relation":"contractor","note":"Hired through the Black Sacrament but fears their potential betrayal","best":"They fulfilled the most significant contract in centuries","worst":"Paranoid about their discretion and potential to betray him"},"Elder Council":{"aff":-25,"type":"suspicious","relation":"fellow council members","note":"Plotting against fellow councilors to reshape Imperial leadership for his benefit"},"House Motierre":{"aff":75,"type":"familial","relation":"noble family","note":"Ancient Breton lineage with historical ties to Imperial politics and the Dark Brotherhood"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ambarys_rendar', '{"Malthyr Elenil":{"aff":65,"type":"platonic","relation":"trusted employee","note":"Fellow Dunmer who shares his anti-Nord views and helps run the Cornerclub","best":"Malthyr chose to stay in Windhelm partly because of him"},"Ulfric Stormcloak":{"aff":-85,"type":"nemesis","relation":"despised ruler","note":"Blames Ulfric for worsening conditions for Dunmer in Windhelm","worst":"Ulfric refused to even visit the Gray Quarter to see the squalor"},"Brunwulf Free-Winter":{"aff":55,"type":"platonic","relation":"rare Nord ally","note":"Respects this Nord for advocating better treatment of Dark Elves"},"Suvaris Atheron":{"aff":-15,"type":"contempt","relation":"fellow Dunmer","note":"Harasses her about working for Nords, disapproving of her choices"},"Imperial Legion":{"aff":75,"type":"fanatical","relation":"supported faction","note":"True supporter who flies Imperial banners and keeps Imperial armor","best":"Rejoiced when the Imperial Legion seized Windhelm from Stormcloaks"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('amren', '{"Saffir":{"aff":35,"type":"romantic","relation":"wife","note":"Marriage strained by his obsession with recovering his father''s sword","best":"Loves her despite her hard-headedness","worst":"She threatened to leave if he pursued the sword"},"Braith":{"aff":75,"type":"familial","relation":"daughter","note":"Deeply loves her but struggles to balance patrol duties with parenting","best":"Holding her confirmed he made the right choice leaving the soldier''s life"},"Father":{"aff":85,"type":"familial","relation":"father","note":"Driven to recover his father''s sword as a matter of family honor and legacy","best":"Father provided for the entire family through his swordsmanship"},"The Companions":{"aff":45,"type":"admirer","relation":"potential hires","note":"Respects their warrior tradition and considered hiring them for the sword recovery"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ancano', '{"Savos Aren":{"aff":-45,"type":"professional","relation":"nominal superior","note":"Secretly despises the Arch-Mage while maintaining a diplomatic facade","worst":"Savos rarely seeks his advice, undermining his supposed purpose at the College"},"Mirabelle Ervine":{"aff":-65,"type":"rival","relation":"adversary","note":"Open mutual hostility; she actively restricts his access and authority","worst":"Publicly reminded him he is merely a guest at the College''s pleasure"},"Thalmor":{"aff":90,"type":"fanatical","relation":"true masters","note":"Serves the Thalmor with fanatical devotion as their covert operative","best":"Rose through Thalmor ranks through magical prowess and political cunning"},"Psijic Order":{"aff":-60,"type":"rival","relation":"obstacle","note":"Views them as rivals who obstruct Thalmor ambitions regarding powerful artifacts","worst":"Their intervention during the Eye of Magnus crisis thwarted his plans"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ancarion', '{"Thalmor Leadership":{"aff":65,"type":"professional","relation":"superiors","note":"Loyal operative seeking advancement through successful mission completion on Solstheim"},"Skaal Village":{"aff":-45,"type":"contempt","relation":"investigation targets","note":"Views the Skaal as inferior Nords whose Stalhrim secrets must be extracted for the Dominion","worst":"Called the Skaal blacksmith a dullard and sought to eliminate resistance to Thalmor authority"},"Thalmor Agents":{"aff":25,"type":"professional","relation":"subordinates","note":"Commands a small contingent of agents from his ship near Solstheim"},"Player":{"aff":-15,"type":"suspicious","relation":"reluctant business partner","note":"Will negotiate if it serves Thalmor interests but makes clear no friendship exists","best":"Agreed to trade for Stalhrim weapons and pay fair prices rather than fight","worst":"Threatened to flay flesh from bones and kill for insolence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ancient_vampire', '{"Movarth Piquine":{"aff":-55,"type":"rival","relation":"ancient rival","note":"Rival from their early years as a vampire, spanning centuries of conflict","worst":"Early power struggles that forged a lasting enmity"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"sworn enemy","note":"Dedicated hunters who regularly pursue their kind","worst":"Close calls with Vigilant raiding parties at their lairs"},"Vampire Thralls":{"aff":20,"type":"protective","relation":"blood-bound servants","note":"Carefully selected and maintained through blood magic as both protection and sustenance reserve"},"Rival Vampire Clans":{"aff":-30,"type":"suspicious","relation":"political rivals","note":"Complex political relationships spanning centuries of shifting alliances and betrayals"},"Court Wizards":{"aff":10,"type":"transactional","relation":"research collaborator","note":"Occasional magical research collaborators kept at arm''s length to protect their secrets"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('anders', '{"Nystrom":{"aff":-90,"type":"enemy","relation":"murder victim","note":"Anders killed Nystrom without remorse, mentioning it casually in his confession.","worst":"Murdered him in cold blood simply because he crossed his path"},"Twilight Sepulcher Guards":{"aff":-75,"type":"enemy","relation":"opposing defenders","note":"Successfully prevented his infiltration, leading to his slow death by starvation.","worst":"Trapped him in the outer chambers where he desperately scratched at walls trying to escape"},"Imperial City Guards":{"aff":-60,"type":"enemy","relation":"pursuing authorities","note":"Chased him from Cyrodiil for numerous thefts and murders, forcing his flight to Skyrim."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('andurs', '{"Alessandra":{"aff":20,"type":"estranged","relation":"daughter","note":"Estranged due to his obsessive devotion to duties, but he still loves her","best":"She returned her father''s dagger to him at last","worst":"Years of neglect drove her away"},"Arkay":{"aff":90,"type":"fanatical","relation":"divine patron","note":"Devoted his entire life to Arkay''s service; faith borders on obsessive","best":"Serving as Whiterun''s priest and performing sacred rites","worst":"Losing his amulet left him powerless and unable to confront the undead"},"Citizens of Whiterun":{"aff":30,"type":"professional","relation":"funeral officiant","note":"Performs death rites and maintains the Hall of the Dead for the city"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('anger', '{"Confidence":{"aff":-90,"type":"enemy","relation":"torment target","note":"Constantly assaults and torments the weaker mental construct with savage pleasure","best":"Beating Confidence into helpless submission","worst":"Wabbajack evening the odds against him"},"Pelagius III":{"aff":50,"type":"servant","relation":"aspect of","note":"Manifestation of the emperor''s rage that grew stronger as madness deepened"},"Sheogorath":{"aff":-70,"type":"enemy","relation":"intruder","note":"Views the Daedric Prince as an unwelcome invader in Pelagius''s mindscape"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('angi', '{"Imperial Legion":{"aff":-85,"type":"enemy","relation":"persecutors","note":"Two drunken Imperial soldiers murdered her family; she killed them in revenge and now lives as an outlaw to escape prosecution.","worst":"Her family slaughtered by Imperial drunks who thought themselves above the law"},"Mother":{"aff":90,"type":"familial","relation":"mother","note":"Taught Angi archery and the importance of composure; her memory guides Angi''s life and skills.","best":"Learning archery at her mother''s side and hearing her wisdom about composure"},"Father":{"aff":60,"type":"familial","relation":"father","note":"Was rarely home, but his loss still contributes to her grief and exile."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('angrenor_once-honored', '{"Rolff Stone-Fist":{"aff":45,"type":"platonic","relation":"harassment partner","note":"Fellow Nord who shares his xenophobic views and jointly harasses Dunmer in Windhelm.","best":"Bullying Suvaris Atheron together at the city gates"},"Suvaris Atheron":{"aff":-55,"type":"contempt","relation":"harassment target","note":"Accuses her of being an Imperial spy because of her Dunmer heritage.","worst":"Publicly accusing her of being an Imperial spy"},"Dunmer of Windhelm":{"aff":-50,"type":"contempt","relation":"despised community","note":"Harbors deep xenophobia against elves, suspecting them of disloyalty to the Stormcloak cause.","worst":"Threatening nocturnal visits to extract confessions from Dunmer"},"Stormcloaks":{"aff":25,"type":"estranged","relation":"former brothers-in-arms","note":"Still loyal to the cause but abandoned by former comrades who now ignore his existence.","best":"Rescuing brothers-in-arms from an Imperial ambush single-handedly","worst":"Fellow veterans ignoring him after his injury left him a beggar"},"Imperials":{"aff":-75,"type":"enemy","relation":"warring faction","note":"An Imperial soldier stabbed him through the chest from behind, ending his military career and leaving him with chronic breathing problems.","worst":"Being run through from behind by an Imperial coward"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('angvid', '{"Thorgar":{"aff":-25,"type":"suspicious","relation":"employer","note":"Once believed Thorgar''s promises of wealth; now openly questions his judgment and the mine''s viability","worst":"Realizing Thorgar''s guarantees of gold were empty as the mine yielded nothing"},"Whistling Mine Miners":{"aff":35,"type":"platonic","relation":"fellow workers","note":"Bound together by shared futility and the same unanswered questions about their collective purpose"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('anise', '{"Helgi":{"aff":65,"type":"familial","relation":"sister","note":"Fellow witch with whom she secretly corresponds about magical research","best":"Sharing discoveries from their dark magical studies"},"College of Winterhold":{"aff":-15,"type":"estranged","relation":"former institution","note":"Abandoned formal magical training to pursue darker practices away from scrutiny"},"Riverwood Residents":{"aff":10,"type":"suspicious","relation":"neighbors","note":"Maintains harmless alchemist facade while deliberately keeping distance"},"Local Hunters":{"aff":15,"type":"transactional","relation":"trading partners","note":"Occasional traders who provide animal parts for her alchemy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('annekke_crag-jumper', '{"Verner Rock-Chucker":{"aff":58,"type":"romantic","relation":"husband","note":"Loves him but frustrated by his contentment with settled life while she yearns for adventure","best":"Exploring new places together in their younger days","worst":"His refusal to join her scouting trips, calling him a milk drinker"},"Sylgja":{"aff":65,"type":"familial","relation":"daughter","note":"Her daughter who lives apart; no special dialogue when reunited as followers"},"Derkeethus":{"aff":30,"type":"platonic","relation":"neighbor","note":"Fellow Darkwater Crossing resident and occasional mining colleague"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('anoriath', '{"Elrindir":{"aff":70,"type":"familial","relation":"brother and business partner","note":"Co-owns the Drunken Huntsman; their bickering about work ethic vs. hunting passion is constant but affectionate","best":"Together they built a successful shop and name from a shared drunken hunting misadventure","worst":"Accidentally shot Elrindir in the rump during a moonlight hunt after too much mead"},"Dark Brotherhood":{"aff":-85,"type":"fearful","relation":"assassination target","note":"Marked by a Dark Brotherhood contract; senses danger from suspicious strangers","worst":"Learned he has a kill contract on his life from an unknown client"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('anska', '{"Vokun":{"aff":-55,"type":"rival","relation":"target of her search","note":"She spent years tracking his crypt to obtain the scroll he guards.","worst":"Good riddance when he finally fell."},"Ysgramor":{"aff":85,"type":"fanatical","relation":"claimed ancestor","note":"Obsessed with proving her bloodline connection to the legendary Nord hero.","best":"Finding the scroll that may finally validate her family''s oral traditions."},"Player":{"aff":65,"type":"grateful","relation":"quest ally","note":"Readily accepts help exploring the ruins and rewards the player generously.","best":"I cannot thank you enough for all of the help."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('anton_virane', '{"Balagog gro-Nolob":{"aff":80,"type":"platonic","relation":"close friend and confidant","note":"Protected the Gourmet''s identity until threatened with death by the Dark Brotherhood","best":"Shared trust and professional respect as fellow culinary masters","worst":"Betrayed his identity under threat of death"},"Rondach":{"aff":-45,"type":"contempt","relation":"abused assistant","note":"Mutually hostile; Rondach threatened violence to protect his sister Voada","worst":"Rondach threatened to cut off his fingers for threatening Voada"},"Voada":{"aff":-35,"type":"contempt","relation":"abused assistant","note":"Regularly threatens and verbally abuses her as incompetent","worst":"Threatened to cut off her fingers for spilling laundry water in the soup"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('anuriel', '{"Laila Law-Giver":{"aff":15,"type":"professional","relation":"employer","note":"Publicly serves as loyal steward while secretly manipulating her and suppressing knowledge of criminal activity","worst":"Considers her simple and traditional, easy to manipulate but impossible to regain graces once offended"},"Maven Black-Briar":{"aff":65,"type":"servant","relation":"true employer","note":"Recruited by Maven to infiltrate Riften''s political structure and serves as her covert agent within Mistveil Keep","best":"Successfully secured the steward position through Maven''s guidance and her own competence"},"Unmid Snow-Shod":{"aff":70,"type":"romantic","relation":"boyfriend","note":"Genuinely cares for him but carefully compartmentalizes her relationship from her secret role","best":"Sneaking out together for private training sessions"},"Thieves Guild":{"aff":50,"type":"professional","relation":"secret allegiance","note":"Operates as an infiltrator protecting Guild interests and keeping official scrutiny away from their operations"},"Imperial Legion":{"aff":-40,"type":"fearful","relation":"blackmailers","note":"Vulnerable to extortion if her true allegiance is discovered, as exposure would ruin her position","worst":"Imperial spy uncovered her Thieves Guild connection and threatened to make it public"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('anwen', '{"Senna":{"aff":60,"type":"platonic","relation":"fellow priestess","note":"Close working relationship serving Dibella together in Markarth"},"Orla":{"aff":50,"type":"platonic","relation":"fellow priestess","note":"Temple colleague sharing duties and living space"},"Hamal":{"aff":75,"type":"mentor","relation":"temple Mother","note":"Deeply respects and obeys Hamal as the temple''s spiritual authority"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aphia_velothi', '{"Crescius Caerellius":{"aff":88,"type":"romantic","relation":"husband","note":"Met while treating his depression; devoted despite his obsessive tendencies","best":"Falling in love while nursing him back to health","worst":"Fearing his mine obsession will get him killed like his great-grandfather"},"Elder Othreloth":{"aff":-45,"type":"rival","relation":"former superior","note":"Theological dispute over the Tribunal led to her exile from the Temple","worst":"Being declared unwelcome at the Temple over Tribunal beliefs"},"Temple of Raven Rock":{"aff":-20,"type":"estranged","relation":"former workplace","note":"No longer welcome due to disagreement with Elder Othreloth"},"Raven Rock Citizens":{"aff":50,"type":"professional","relation":"community she serves","note":"Respected independent healer who continues serving despite Temple exile"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('apprentice_conjurer', '{"College of Winterhold":{"aff":-35,"type":"estranged","relation":"former institution","note":"Left before completing studies due to ethical disagreements over forbidden research","worst":"Condemned for pursuing Conjuration practices the College deemed too dangerous"},"Fellow Conjurers":{"aff":40,"type":"professional","relation":"loose network","note":"Shares knowledge and mutual protection with other rogue conjurers","best":"Exchanged rare summoning techniques with a trusted fellow practitioner"},"Vigilants of Stendarr":{"aff":-75,"type":"enemy","relation":"hostile hunters","note":"Targeted for Daedric practices; encounters are violent","worst":"Ambushed during a ritual and barely escaped with their life"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('apprentice_fire_mage', '{"College of Winterhold":{"aff":-55,"type":"estranged","relation":"former institution","note":"Left in frustration over their cautious approach to destructive magic","worst":"Dismissed as too reckless and denied freedom to pursue aggressive fire magic"},"Warlock Coven":{"aff":35,"type":"professional","relation":"subordinate member","note":"Competitive but mutually protective with fellow outcast mages","best":"Accepted into the coven where destructive magic is encouraged"},"Local Settlements":{"aff":-65,"type":"enemy","relation":"feared outcast","note":"Antagonistic relationship with nearby villages who fear the coven''s presence"},"Bounty Hunters":{"aff":-75,"type":"enemy","relation":"hunted target","note":"Frequent adversaries seeking to collect bounties on warlock covens","worst":"Constant threat of mercenaries coming to claim the bounty on their head"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('apprentice_ice_mage', '{"College of Winterhold":{"aff":-40,"type":"dismissive","relation":"rejected institution","note":"Views the College as restrictive and elitist, refuses to join","worst":"Chose exile over submitting to their structure"},"Fellow Warlocks":{"aff":15,"type":"platonic","relation":"loose associates","note":"Cautious camaraderie with other independent mages","best":"Shared knowledge from ruin exploration"},"Local Settlements":{"aff":-30,"type":"fearful","relation":"shunned outsider","note":"Mutual suspicion and fear due to magical nature","worst":"Driven away after frost accident harmed locals"},"Bandits":{"aff":-10,"type":"transactional","relation":"uneasy allies","note":"Occasional survival alliances but never trusted","worst":"Betrayed during a joint scavenging run"},"Family":{"aff":-50,"type":"estranged","relation":"abandoned kin","note":"Fled home after accidental harm from uncontrolled frost powers","worst":"Frost accident that forced them to abandon their village"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('apprentice_necromancer', '{"College of Winterhold":{"aff":-70,"type":"estranged","relation":"former institution","note":"Expelled for conducting forbidden necromantic experiments with corpses","worst":"Caught and expelled, cutting off legitimate magical education"},"Fellow Necromancers":{"aff":25,"type":"professional","relation":"cautious allies","note":"Cautious allies in the pursuit of forbidden knowledge, trust is limited"},"Vigilants of Stendarr":{"aff":-85,"type":"fearful","relation":"active hunters","note":"Active threats who hunt necromancers relentlessly","worst":"Constant danger of being hunted and killed for their practices"},"Ritual Master":{"aff":45,"type":"student","relation":"potential mentor","note":"Seeks mentorship in advanced necromantic arts","best":"Hope of learning deeper secrets from a master"},"Deceased Family Member":{"aff":85,"type":"familial","relation":"lost loved one","note":"Their death triggered the obsessive drive to understand and master death","worst":"Loss that shattered their former life and morality"},"Local Townspeople":{"aff":-25,"type":"contempt","relation":"unwitting subjects","note":"Viewed as fearful victims and potential research resources"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('apprentice_storm_mage', '{"Master Electromancer":{"aff":65,"type":"mentor","relation":"primary mentor","note":"Took them in after their village ostracized them and teaches them storm magic","best":"Accepted into the warlock enclave despite humble origins"},"Fellow Apprentices":{"aff":35,"type":"rival","relation":"fellow apprentices","note":"Competitive but generally supportive peers in storm magic training"},"College of Winterhold":{"aff":25,"type":"admirer","relation":"distant admirer","note":"Admires their magical scholarship but considers their methods too restrictive"},"Local Villagers":{"aff":-65,"type":"estranged","relation":"former community","note":"Ostracized them due to superstitious fear of magic","worst":"Driven from home after accidentally channeling lightning during wolf encounter"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aquillius_aeresius', '{"Vittoria Vici":{"aff":80,"type":"professional","relation":"superior and mentor","note":"Devoted right-hand man and designated successor who shadows her schedule closely","best":"Earned her trust as indispensable to East Empire Company operations"},"East Empire Company":{"aff":85,"type":"fanatical","relation":"senior administrator","note":"Dedicated to advancing Imperial economic dominance with near-zealous devotion","best":"Rose through ranks from merchant family connections and own shrewd merit"},"Nordic locals":{"aff":-25,"type":"contempt","relation":"Imperial overseer","note":"Strained relations due to Imperial favoritism and disdain for perceived laziness","worst":"Dismisses them as too lazy or cowardly to make their own way"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aranea_ienith', '{"Azura":{"aff":95,"type":"fanatical","relation":"patron deity","note":"Chosen priestess and oracle who receives prophetic visions and serves as Azura''s earthly representative","best":"Guided safely from Vvardenfell before the eruption through Azura''s prophecy","worst":"Fellow worshippers abandoned the shrine, leaving her to serve alone"},"Nelacar":{"aff":-70,"type":"enemy","relation":"defiler of artifacts","note":"Elven enchanter who corrupts Azura''s Star into the Black Star","worst":"His profane knowledge turns the brightest star black as night"},"Dunmer Refugees":{"aff":55,"type":"familial","relation":"fellow exiles","note":"Shared the exodus from Morrowind guided by Azura''s prophecies","best":"Built the shrine together in gratitude for Azura''s guidance"},"The Dragonborn":{"aff":25,"type":"curious","relation":"prophesied champion","note":"Azura foretold their coming; relationship hinges on choices regarding Azura''s Star","best":"Returns Azura''s Star purified and becomes a faithful follower","worst":"Defiles Azura''s Star into the Black Star, earning a death threat"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arcadia', '{"Farengar Secret-Fire":{"aff":50,"type":"crush","relation":"court wizard, intended test subject","note":"Plans to test her love elixir on him, suggesting romantic interest or mischievous fascination","best":"Receiving frost salts delivery meant for her special brew"},"Adrianne Avenicci":{"aff":40,"type":"platonic","relation":"fellow Imperial merchant","note":"Bonded by shared Imperial heritage and merchant life in Whiterun"},"Stormcloaks":{"aff":-75,"type":"contempt","relation":"political faction","note":"Despises their anti-Imperial stance; resents their boycott of her shop","worst":"Stormcloaks refusing to shop at her store, accusing her of selling poisoned tonics"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arch-curate_vyrthur', '{"Gelebor":{"aff":-40,"type":"estranged","relation":"brother","note":"Estranged after Vyrthur''s vampiric transformation; dismisses him as an easily manipulated fool","worst":"Gelebor continued serving Auri-El while Vyrthur felt abandoned by their god"},"Auri-El":{"aff":-85,"type":"nemesis","relation":"former deity","note":"Felt betrayed when Auri-El did not protect him from vampirism; spent centuries crafting prophecy to corrupt his influence on Nirn","best":"Once had the ears of a god as Arch-Curate of the Chantry","worst":"Auri-El turned his back on him the moment he was infected by his own initiate"},"Serana":{"aff":-55,"type":"contempt","relation":"prophecy ingredient","note":"Viewed her only as the blood of a Daughter of Coldharbour needed to complete the Tyranny of the Sun prophecy","worst":"She refused to surrender her blood and fought against him, ruining centuries of preparation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arch_conjurer', '{"Fellow Conjurers":{"aff":40,"type":"professional","relation":"colleagues","note":"Commands respect as a superior practitioner among outcast warlocks"},"Apprentice Warlocks":{"aff":25,"type":"mentor","relation":"mentor","note":"Harsh but knowledgeable teacher to promising students of conjuration"},"College of Winterhold":{"aff":-15,"type":"suspicious","relation":"outcast","note":"Maintains cautious distance due to controversial Daedric practices"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"persecutor","note":"Bitter enemies who hunt all Daedra-consorting mages","worst":"Targeted for destruction by fanatical Daedra-hunters"},"Daedric Entities":{"aff":20,"type":"obsessed","relation":"summoner and binder","note":"Views Daedra as tools to master while seeking ever-greater power over them","best":"Successfully bound a powerful entity from Oblivion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arch_cryomancer', '{"College of Winterhold":{"aff":-45,"type":"estranged","relation":"former institution","note":"Severed ties to pursue forbidden frost magic research","worst":"Being forced out for delving into proscribed magical knowledge"},"Lesser Ice Mages":{"aff":40,"type":"mentor","relation":"leader and teacher","note":"Commands and instructs lesser ice mages within warlock covens","best":"Watching a student master their first Ice Storm spell"},"Necromancers":{"aff":15,"type":"transactional","relation":"cautious allies","note":"Maintains mutually beneficial but distrustful alliances"},"Local Nord Populations":{"aff":-65,"type":"enemy","relation":"hostile locals","note":"Destructive magical practices have earned their lasting enmity","worst":"Driving villagers from their homes with devastating frost experiments"}}')
ON CONFLICT (npc_name) DO UPDATE
