INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arch_cultist', '{"Miraak":{"aff":95,"type":"fanatical","relation":"supreme master","note":"Absolute devotion to the First Dragonborn; rose through trials to become his trusted servant","best":"Received direct teachings and commands from Miraak after proving worth"},"Lesser Cultists":{"aff":25,"type":"professional","relation":"commander","note":"Directs subordinates with cruel efficiency and demands unwavering dedication"},"Seekers":{"aff":15,"type":"professional","relation":"co-servants","note":"Frequently works alongside Hermaeus Mora''s servants in Miraak''s temple"},"Last Dragonborn":{"aff":-90,"type":"nemesis","relation":"sworn enemy","note":"Views them as a false pretender who must be eliminated to protect Miraak''s plans","worst":"The false Dragonborn threatens everything Miraak seeks to accomplish"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arch_electromancer', '{"Lesser Storm Mages":{"aff":25,"type":"professional","relation":"subordinates","note":"Commands lesser storm mages who both fear and revere their mastery","best":"Subordinates execute orders without question","worst":"Their weakness limits usefulness"},"College of Winterhold":{"aff":-55,"type":"estranged","relation":"former institution","note":"Exiled for pursuing forbidden shock magic applications and unethical experiments","best":"Received foundational magical training there","worst":"Severed ties and expelled over ethical violations"},"Necromancers":{"aff":20,"type":"transactional","relation":"occasional allies","note":"Cooperate when forbidden knowledge pursuits align","best":"Shared research advances understanding of dark practices"},"Local Nord Populations":{"aff":-75,"type":"contempt","relation":"obstacles and test subjects","note":"Views Nords as threats to be eliminated or material for experiments","worst":"Nord interference disrupts research and territorial control"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arch_necromancer', '{"Vigilants of Stendarr":{"aff":-90,"type":"nemesis","relation":"sworn enemies","note":"Actively hunted by the Vigilants for practicing forbidden death magic.","worst":"Their hunters have disrupted rituals and destroyed valuable undead thralls."},"College of Winterhold":{"aff":-35,"type":"estranged","relation":"former institution","note":"Severed ties after turning from conventional study to forbidden necromantic research.","best":"Once learned the foundational arts of magic within its halls."},"Lesser Necromancers":{"aff":20,"type":"professional","relation":"subordinates","note":"Commands lesser practitioners who seek to learn from their mastery."},"Fellow Arch Necromancers":{"aff":5,"type":"rival","relation":"cautious peers","note":"Maintains wary alliances with rare equals in the necromantic hierarchy."}}')
