INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arch_pyromancer', '{"Warlock Covens":{"aff":25,"type":"rival","relation":"competitive peer","note":"Competitive but respectful with other high-ranking mages; seeks dominance over rival covens"},"Apprentice Fire Mages":{"aff":5,"type":"mentor","relation":"intimidating exemplar","note":"Serves as intimidating example of power rather than nurturing guide"},"College of Winterhold":{"aff":-75,"type":"enemy","relation":"rejected outcast","note":"Hostile due to College''s rejection of their destructive practices"},"Local Settlements":{"aff":-40,"type":"contempt","relation":"feared outsider","note":"Views common folk as inferior beings unworthy of attention"}}')
