INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arcturus', '{"Commander Maro":{"aff":75,"type":"mentor","relation":"superior officer and mentor","note":"Maro appointed Arcturus as field commander for special operations based on his exceptional performance."},"Emperor Titus Mede II":{"aff":90,"type":"fanatical","relation":"ultimate commander","note":"Arcturus shows unwavering loyalty bordering on zealotry toward the Emperor."},"Dark Brotherhood":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Arcturus leads the assault to eliminate the Dark Brotherhood entirely.","worst":"Leading the raid on their Sanctuary to wipe them out"},"Nazir":{"aff":-80,"type":"enemy","relation":"combatant","note":"Arcturus battles the weakened Nazir inside the Dark Brotherhood Sanctuary during the assault.","worst":"Fighting Nazir near the dinner table before being slain"}}')
ON CONFLICT (npc_name) DO UPDATE
