INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ardwen', '{"Dog":{"aff":75,"type":"protective","relation":"traveling companion","note":"Loyal dog accompanying her on pilgrimage to the Gildergreen"},"Danica Pure-Spring":{"aff":55,"type":"admirer","relation":"shrine caretaker","note":"Respects her as keeper of the restored Gildergreen she journeys to witness"},"Temple of Kynareth":{"aff":70,"type":"admirer","relation":"devoted pilgrim","note":"Spiritual destination and object of her religious devotion"}}')
