INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('argis_the_bulwark', '{"Jarl Igmund":{"aff":72,"type":"professional","relation":"liege lord","note":"Promoted Argis to housecarl after his valor in the Forsworn Uprising","best":"Promoted to housecarl for exceptional service defending Markarth"},"Forsworn":{"aff":-95,"type":"nemesis","relation":"sworn enemies","note":"Fought them during the Uprising and continues to battle them across the Reach","worst":"Lost his eye defending Markarth''s walls from Forsworn attack"},"Thane of Markarth":{"aff":78,"type":"protective","relation":"housecarl","note":"Sworn to protect and serve with his life at Vlindrel Hall"},"Legate Emmanuel Admand":{"aff":45,"type":"professional","relation":"fellow defender","note":"Mutual professional respect as defenders of the Reach"}}')
ON CONFLICT (npc_name) DO UPDATE
