INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ari', '{"Valdr":{"aff":65,"type":"platonic","relation":"hunting party leader","note":"Fellow hunter who survived the spriggan attack and later sought to avenge and bury her","best":"Hunting together as part of a trusted party","worst":"Fell to spriggans during their ill-fated bear pursuit"},"Niels":{"aff":50,"type":"platonic","relation":"hunting companion","note":"Fellow hunter killed almost instantly in the spriggan ambush","worst":"Witnessed his sudden death before fleeing the cavern"}}')
