INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aringoth', '{"Maven Black-Briar":{"aff":-85,"type":"enemy","relation":"former business partner","note":"Broke their honey supply arrangement for a better offer, now faces her retribution","worst":"Stopped all shipments to Black-Briar Meadery, making a lethal enemy"},"Thieves Guild":{"aff":-65,"type":"enemy","relation":"former extortion target","note":"Refused further payments and fortified Goldenglow against them","worst":"Guild sent agents to burn hives and ransack his safe"},"Unknown Buyer":{"aff":10,"type":"fearful","relation":"new owner of Goldenglow","note":"Sold estate to mysterious figure, terrified of consequences if he reveals anything","best":"Received an offer too profitable to refuse","worst":"Fears death if new owner learns he surrendered the safe key"},"Mercenary Guards":{"aff":-15,"type":"transactional","relation":"hired protection","note":"Paid handsomely for security but finds them worthless against Guild infiltration","worst":"Mercenaries failed to stop thieves from reaching him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arivanya', '{"Ulundil":{"aff":70,"type":"romantic","relation":"husband","note":"She loves him despite their mismatched interests and his dull demeanor","best":"Their romance led her to leave Summerset and build a life with him","worst":"She finds his preoccupation with horses and rustic lifestyle stifling"},"Viola Giordano":{"aff":55,"type":"platonic","relation":"friend","note":"Marked as friends; Arivanya trusts her judgment about the Butcher","best":"She publicly vouches that the guards should listen to Viola about the killer"},"Tova Shatter-Shield":{"aff":45,"type":"platonic","relation":"friend","note":"Marked as friends; connected through the Butcher investigation circle"},"Calixto Corrium":{"aff":-80,"type":"fearful","relation":"potential murder victim","note":"He may target her as part of the Butcher killings","worst":"Can fall prey to Calixto''s ritual murder outside Candlehearth Hall"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arnbjorn', '{"Astrid":{"aff":95,"type":"romantic","relation":"wife","note":"Deeply loves and trusts Astrid, follows her judgment even with people he dislikes","best":"Finding acceptance and love within the Dark Brotherhood alongside Astrid","worst":"Losing Astrid during the Penitus Oculatus assault on the Sanctuary"},"Cicero":{"aff":-75,"type":"enemy","relation":"fellow Brotherhood member","note":"Despises Cicero as a witless fool and deeply distrusts him","worst":"Cicero''s disruptive arrival and challenge to Astrid''s leadership"},"The Companions":{"aff":-30,"type":"estranged","relation":"former guild","note":"Left after they found his brutal methods too unsettling even for them","worst":"Being rejected by the Companions for his violent nature"},"Night Mother":{"aff":-40,"type":"contempt","relation":"Brotherhood deity","note":"Views the Night Mother with skepticism, dismissing her as a pet corpse"},"Dark Brotherhood":{"aff":60,"type":"protective","relation":"family","note":"Considers them family and maintains their weapons, though keeps emotional distance","best":"Finding acceptance for his violent nature and werewolf abilities among assassins"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arngeir', '{"Paarthurnax":{"aff":90,"type":"protective","relation":"master","note":"Serves as Paarthurnax''s right hand and zealously guards the path to the Throat of the World","best":"Decades of devoted service and spiritual communion at High Hrothgar","worst":"The Blades'' demand for Paarthurnax''s death forces him into a desperate defense"},"Borri":{"aff":70,"type":"platonic","relation":"brother","note":"Fellow Greybeard who assists in the Dragonborn''s trials"},"Einarth":{"aff":70,"type":"platonic","relation":"brother","note":"Fellow Greybeard elder who speaks only in the Voice"},"Wulfgar":{"aff":70,"type":"platonic","relation":"brother","note":"Fellow Greybeard who greets the Dragonborn with Unrelenting Force"},"Dragonborn":{"aff":55,"type":"mentor","relation":"student","note":"Guides the Dragonborn in the Way of the Voice but struggles when their path diverges from tradition","best":"Welcoming the Dragonborn to High Hrothgar and recognizing their gift","worst":"Tension when the Dragonborn chooses to use the Voice for worldly purposes"},"Blades":{"aff":-50,"type":"suspicious","relation":"adversaries","note":"Distrusts the Blades for their ancient vendetta against Paarthurnax","worst":"Their insistence on killing Paarthurnax threatens everything he protects"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arniel''s_shade', '{"College of Winterhold":{"aff":40,"type":"professional","relation":"former institution","note":"Still follows College routines as a shade, visiting old haunts"},"Phinis Gestor":{"aff":35,"type":"professional","relation":"former colleague","note":"Shade persists in visiting him for three hours each evening","best":"Collaborated on conjuration research as living colleagues"},"The Dragonborn":{"aff":20,"type":"servant","relation":"summoner","note":"Bound to service after the Dragonborn completed his fatal experiment"},"Dwemer":{"aff":65,"type":"obsessed","relation":"research subject","note":"Fatal obsession whose secrets consumed him literally and figuratively","worst":"Dwemer artifact Keening triggered his transformation into a shade"}}')
ON CONFLICT (npc_name) DO UPDATE
