INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arniel_gane', '{"Phinis Gestor":{"aff":55,"type":"platonic","relation":"close friend and colleague","note":"One of the few people Arniel seeks out regularly, sharing an interest in Conjuration magic","best":"Evening conversations in the Arcanaeum discussing magical theory"},"Tolfdir":{"aff":25,"type":"professional","relation":"senior colleague","note":"Respected but somewhat dismissive of Arniel''s secretive obsessions"},"Ancano":{"aff":-60,"type":"suspicious","relation":"distrusted Thalmor advisor","note":"Fears Ancano is trying to steal his research and refuses to share any details with him","worst":"Ancano''s relentless probing questions about his work"},"Enthir":{"aff":20,"type":"transactional","relation":"supplier of rare materials","note":"Provides hard-to-find Dwemer artifacts and research materials, though Arniel keeps the true purpose hidden"}}')
