INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arondil', '{"Citizens of Dawnstar":{"aff":-80,"type":"estranged","relation":"exilers","note":"Drove him from Dawnstar after discovering his necromantic experiments"},"Yngvild Draugr":{"aff":85,"type":"obsessed","relation":"creations and obsession","note":"His ''lovelies'' â€” reanimated female corpses he treats with disturbing affection and possessiveness"},"Milk Maid of Dawnstar":{"aff":-30,"type":"contempt","relation":"victim","note":"Stalked and had her killed, dismissing her as unremarkable while relishing her fresh corpse for experiments"},"Journal Buyer":{"aff":15,"type":"transactional","relation":"client","note":"Unknown party interested in acquiring his four-part experimental journal"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arrald_frozen-heart', '{"Ulfric Stormcloak":{"aff":95,"type":"fanatical","relation":"supreme commander","note":"Believes absolutely in Ulfric''s cause and considers him the only true High King","best":"Hearing Ulfric''s call to war and knowing his purpose"},"Stormcloak Soldiers":{"aff":75,"type":"protective","relation":"brothers-in-arms","note":"Maintains strong bonds of brotherhood with troops under his command","best":"Sharing the cloak of true brotherhood before battle"},"Imperial Legion":{"aff":-85,"type":"enemy","relation":"bitter foes","note":"Views them as snowbacked cowards who sold out Skyrim''s heritage","worst":"The Empire laying down before the Thalmor and selling Talos worship"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"hated oppressors","note":"Intense hatred for suppressing Talos worship and enslaving Skyrim","worst":"The damn elves taking Talos from the Nordic people"},"Jarl of Morthal":{"aff":-60,"type":"rival","relation":"opposing ruler","note":"Antagonistic relationship with the Imperial-aligned Jarl prior to Stormcloak takeover"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arvak', '{"Previous Owner":{"aff":90,"type":"protective","relation":"beloved master","note":"Shared a deep bond in life; master died searching for Arvak in the Soul Cairn","best":"Galloping together across Skyrim in life","worst":"Torn apart by soul trapping, master perished searching endlessly"},"Dragonborn":{"aff":75,"type":"protective","relation":"new master","note":"Freed Arvak from eternal wandering by returning his skull","best":"Freed from the Soul Cairn and given renewed purpose"},"Durnehviir":{"aff":30,"type":"neutral","relation":"fellow soul-bound inhabitant","note":"Both are trapped entities bound to the Soul Cairn"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('arvel_the_swift', '{"Lucan Valerius":{"aff":-50,"type":"contempt","relation":"theft victim","note":"Stole the Golden Claw from his shop without remorse, seeing him only as an easy mark"},"Camilla Valerius":{"aff":-25,"type":"dismissive","relation":"collateral victim","note":"Indirectly harmed by the theft; of no concern to him"},"Bleak Falls Barrow Bandits":{"aff":-20,"type":"betrayed","relation":"abandoned accomplices","note":"Recruited them for the expedition but never intended to share any findings","worst":"Ran ahead with the claw, leaving them to guard the entrance with empty promises"},"Player":{"aff":-40,"type":"betrayed","relation":"double-crossed rescuer","note":"Begged for rescue from the spider, promised to share the treasure, then fled with the claw","best":"Pleaded desperately for help when trapped in the spider''s web","worst":"Called rescuer a fool and ran off laughing"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('asbjorn_fire-tamer', '{"Balimund":{"aff":92,"type":"mentor","relation":"mentor and father figure","note":"Rescued from orphanage and gave him purpose; deeply loyal and strives to make him proud","best":"First time picking up a hammer it just felt right, confirming Balimund''s faith in him","worst":"Constant fear of never living up to Balimund''s legendary reputation"},"Grelod the Kind":{"aff":-75,"type":"contempt","relation":"former caretaker","note":"Endured her harsh care at Honorhall; she told him his parents never wanted him","worst":"Being told as a child that his parents abandoned him because they didn''t want him"},"Honorhall Orphans":{"aff":55,"type":"pitying","relation":"former fellow orphans","note":"Sympathizes with current residents, having survived the same harsh conditions"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ascendant_cultist', '{"Miraak":{"aff":98,"type":"fanatical","relation":"revered master","note":"Object of absolute religious devotion since youth, considers him divine","best":"First vivid dream of Miraak''s power that called them to the temple","worst":"Any failure that might displease Miraak or weaken his influence"},"Lesser Cultists":{"aff":25,"type":"professional","relation":"subordinates","note":"Maintains authority over them through both respect and fear"},"Temple Priests":{"aff":40,"type":"professional","relation":"fellow inner circle","note":"Coordinates with other high-ranking cultists to maintain temple order"},"Skaal Village":{"aff":-60,"type":"contempt","relation":"resistant natives","note":"Views them with contempt for resisting Miraak''s influence over Solstheim"},"Last Dragonborn":{"aff":-90,"type":"nemesis","relation":"blasphemous usurper","note":"Considers them a heretical pretender to be eliminated at all costs","worst":"Learning of this false Dragonborn''s existence and growing power"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ascendant_necromancer', '{"College of Winterhold":{"aff":-45,"type":"estranged","relation":"expelled former member","note":"Expelled for pursuing forbidden necromantic research beyond acceptable boundaries","worst":"Being banished from the College for their transgressive studies"},"Vigilants of Stendarr":{"aff":-85,"type":"nemesis","relation":"sworn enemies","note":"Actively hunted by these zealous undead-slayers","worst":"Constant pursuit and disruption of rituals by Vigilant patrols"},"Lesser Necromancers":{"aff":15,"type":"professional","relation":"subordinates","note":"Commands a small cult who assist with rituals and protect territory","best":"Successful large-scale rituals enabled by subordinate assistance"},"Ideal Masters":{"aff":50,"type":"mentor","relation":"spiritual mentors","note":"Communes with these entities for advanced necromantic knowledge","best":"Receiving hidden knowledge of soul manipulation from the Masters"},"Local Nord Population":{"aff":-70,"type":"contempt","relation":"specimen source","note":"Views living beings primarily as future specimens for study","worst":"Desecration of Nordic burial sites for experimental materials"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('asendant_conjurer', '{"Apprentice Conjurers":{"aff":55,"type":"mentor","relation":"apprentices","note":"Loyal followers who assist in Daedric summoning research"},"Local Necromancers":{"aff":25,"type":"transactional","relation":"collaborators","note":"Occasional collaborators in dark magical arts"},"College of Winterhold":{"aff":-40,"type":"estranged","relation":"suspicious institution","note":"Strained relations due to ethical concerns about their research"},"Vigilants of Stendarr":{"aff":-90,"type":"enemy","relation":"sworn enemies","note":"Seek to destroy their Daedric work and coven","worst":"Vigilants raiding ritual sites and destroying summons"},"Daedric Entities":{"aff":40,"type":"obsessed","relation":"summoned entities","note":"Speaks of them as close confidants; relationships range from servant to master","best":"Successfully binding a powerful Daedric entity to their will","worst":"A summoning turning hostile and scarring their hands"},"Mages Guild":{"aff":-55,"type":"estranged","relation":"expelled institution","note":"Expelled for unauthorized Daedric summoning experiments","worst":"Being expelled and forced to flee High Rock"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('asgeir_snow-shod', '{"Maven Black-Briar":{"aff":60,"type":"professional","relation":"business partner","note":"Invested gold to launch the meadery; impressed by her rapid success"},"Vulwulf Snow-Shod":{"aff":45,"type":"familial","relation":"father","note":"Loves him but sees his Stormcloak zeal as misguided hatred","worst":"Father''s outrage at his Imperial marriage"},"Nura Snow-Shod":{"aff":65,"type":"familial","relation":"mother","note":"Loves her dearly but doubts her Talos preaching delivers the right message"},"Lilija Snow-Shod":{"aff":90,"type":"familial","relation":"sister","note":"Her death as a Stormcloak Battle Maiden left him grieving and politically disillusioned","worst":"Learning of Lilija''s death in the war"},"Vittoria Vici":{"aff":85,"type":"romantic","relation":"bride","note":"Deeply in love; their marriage symbolized Stormcloak-Imperial reconciliation","best":"Their wedding day in Solitude","worst":"Vittoria assassinated at the wedding"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aslfur', '{"Idgrod Ravencrone":{"aff":92,"type":"romantic","relation":"wife","note":"Devoted husband and steward who shields her from petty concerns and supports her mystical gifts without question","best":"She affirmed she has never doubted his guidance and support","worst":"Watching her doubted by the very people she leads and protects"},"Idgrod the Younger":{"aff":78,"type":"familial","relation":"daughter","note":"Supports her patiently in learning to handle her inherited prophetic abilities"},"Joric":{"aff":80,"type":"protective","relation":"son","note":"Carefully monitors his well-being and fears his condition is worsening","worst":"Hearing Joric call out Falion''s name in his sleep and suspecting a dark connection"},"Falion":{"aff":20,"type":"suspicious","note":"Troubled by rumors surrounding the wizard and his possible connection to Joric''s affliction"},"Morthal Citizens":{"aff":35,"type":"professional","relation":"constituents","note":"Serves as diplomatic intermediary between the restless townsfolk and the Jarl, managing their concerns with firm patience"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aspiring_mage', '{"Father":{"aff":-55,"type":"estranged","relation":"father","note":"Refuses to discuss his grandfather''s magical legacy and disapproves of his pursuit of magic","worst":"Father would not talk about his grandfather or his wizard past"},"Grandfather":{"aff":80,"type":"admirer","relation":"grandfather","note":"Idolizes the magical legacy of a man he never knew, found his artifacts in the attic","best":"Discovered his grandfather''s staff and magical artifacts, sparking hope he could be a wizard too","worst":"Never knew him and can never learn from him directly"},"College of Winterhold":{"aff":-70,"type":"contempt","relation":"rejected institution","note":"Rejected his application and humiliated him, yet he still desperately wants to prove himself worthy","worst":"They laughed at him and told him the magic was in the staff, not in him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('assassin', '{"Dark Brotherhood":{"aff":35,"type":"professional","relation":"faction member","note":"Maintains formal ties while keeping emotional distance from fellow assassins"},"Sithis":{"aff":85,"type":"fanatical","relation":"devotee","note":"Views murder as sacred duty to the Dread Father and the void"},"Night Mother":{"aff":75,"type":"servant","relation":"devoted servant","note":"Serves her will through contracts and ritual killings"},"Player":{"aff":-80,"type":"enemy","relation":"target","note":"Sent to assassinate via Black Sacrament contract","worst":"Contract ordered through the Black Sacrament"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('assur', '{"Jarl Korir":{"aff":90,"type":"familial","relation":"father","note":"Primary influence and role model; Assur parrots his anti-elf and anti-College views","best":"Korir''s proud affirmation ''That''s my boy'' when expressing hatred for the College"},"Thaena":{"aff":70,"type":"familial","relation":"mother","note":"Caretaker in the jarl''s longhouse; less prominent influence than his father"},"Eirid":{"aff":40,"type":"platonic","relation":"only friend and playmate","note":"Strained by his mean behavior and insistence she play the elf in their games","worst":"Always makes her be the elf in ''Hunt the Elf'' and can be mean to her"},"College of Winterhold":{"aff":-75,"type":"contempt","relation":"distrusted institution","note":"Learned hatred from his father; believes they destroyed Winterhold and look down on Nords","worst":"Internalized belief that the College is responsible for destroying his home"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('asta', '{"Sond":{"aff":75,"type":"platonic","relation":"closest companion and fellow worshipper","note":"Only company during worship of Eldergleam in the sanctuary"},"Eldergleam":{"aff":95,"type":"protective","relation":"sacred charge","note":"Sworn to protect and serve the ancient tree above all else","worst":"Someone bringing Nettlebane to harm the tree"},"Danica Pure-Spring":{"aff":25,"type":"professional","relation":"fellow Kynareth devotee","note":"Distant connection through shared devotion to Kynareth"},"Kynareth":{"aff":85,"type":"fanatical","relation":"deity","note":"Abandoned Nordic warrior culture to pursue spiritual devotion to Kynareth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('astrid', '{"Arnbjorn":{"aff":75,"type":"romantic","relation":"husband","note":"Genuine love rare in her calculating life, yet ultimately sacrificed to her need for control","best":"Finding partnership and belonging within the Brotherhood together","worst":"Betraying the Sanctuary led to his death defending it"},"Cicero":{"aff":-65,"type":"rival","relation":"distrusted keeper","note":"Views his arrival and devotion to the Night Mother as direct threat to her authority","worst":"His attempt to murder her after she disrespected the Night Mother"},"Nazir":{"aff":55,"type":"professional","relation":"trusted lieutenant","note":"Relied on him as steady enforcer and voice of reason within the Sanctuary"},"The Night Mother":{"aff":-55,"type":"contempt","relation":"rejected spiritual authority","note":"Actively undermines traditional Brotherhood hierarchy the Night Mother represents","worst":"Her open disrespect provoked Cicero''s violence"},"Commander Maro":{"aff":-85,"type":"betrayed","relation":"failed conspirator","note":"Made a desperate deal to surrender the Brotherhood but he attacked the Sanctuary anyway","worst":"He burned the Sanctuary and slaughtered her family despite their bargain"},"Gabriella":{"aff":45,"type":"platonic","relation":"confidante","note":"Loyal family member she trusted for counsel"},"Babette":{"aff":40,"type":"professional","relation":"respected colleague","note":"Values the ancient vampire''s centuries of experience despite the childlike form"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ataf', '{"Pantea Ateia":{"aff":65,"type":"mentor","relation":"vocal instructor","note":"Respects her guidance and performs eagerly in her class","best":"Received encouraging feedback on his rendition of Ragnar the Red"},"Inge Six Fingers":{"aff":60,"type":"mentor","relation":"instrumental instructor","note":"Values her technical instruction on performance delivery","best":"Was complimented on his playing during class"},"Giraud Gemane":{"aff":55,"type":"mentor","relation":"history professor","note":"Attends his bardic lore classes regularly"},"Illdi":{"aff":80,"type":"crush","relation":"fellow student","note":"Harbors romantic feelings and admires her hidden talent","best":"Defended her singing ability to others","worst":"Gets flustered and embarrassed when his feelings are noticed"},"Jorn":{"aff":45,"type":"platonic","relation":"fellow student","note":"Teases him about his crush on Illdi","worst":"Embarrassed by Jorn calling out his crush publicly"},"Jala":{"aff":35,"type":"transactional","relation":"local merchant","note":"Friendly exchanges about food and fishing"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('atahbah', '{"Ri''saad":{"aff":65,"type":"protective","relation":"caravan leader, possible husband","note":"He attempts to help manage her moon sugar addiction; the Prima Guide identifies her as his wife","best":"He watches over this one when the cravings grow fierce","worst":"His concern sometimes feels like a cage"},"Ma''randru-jo":{"aff":50,"type":"platonic","relation":"confidant","note":"Fellow caravan member who shares her longing for Elsweyr''s warm sands","best":"Quiet nights speaking of home under Skyrim''s cold stars"},"Thieves Guild":{"aff":25,"type":"professional","relation":"fence client","note":"Provides fencing services after the Caravan Fence quest establishes trust"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('atar', '{"Silver-Blood Family":{"aff":65,"type":"patron","relation":"employer","note":"Trusted with sensitive operations and property acquisition contracts","best":"Caught their attention through effective leadership and unwavering dedication"},"Ainethach":{"aff":-70,"type":"contempt","relation":"coercion target","note":"Views the native mine owner with disdain while trying to force a sale","worst":"Dismissed his homeland as a pile of dirt and mocked his resistance"},"Mercenary Band":{"aff":50,"type":"professional","relation":"subordinates","note":"Leads a loyal group of sellswords under his command"},"Karthwasten Locals":{"aff":-40,"type":"contempt","relation":"oppressed populace","note":"Hostile presence who shut down their mine and intimidates them","worst":"Told townsfolk the mine is closed and to get lost"},"Forsworn":{"aff":-80,"type":"enemy","relation":"mutual enemies","note":"Uses their attacks as justification for seizing property","worst":"Forsworn attacks gave him pretext to occupy Sanuarach Mine"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('athis', '{"Njada Stonearm":{"aff":15,"type":"rival","relation":"rival","note":"Frequently brawls with her upon first entering Jorrvaskr, and always loses","worst":"Never manages to beat her in their recurring fights"},"Kodlak Whitemane":{"aff":55,"type":"professional","relation":"Harbinger","note":"Shows deference to his wisdom and leadership of the Companions"},"Skjor":{"aff":60,"type":"professional","relation":"senior Companion","note":"Skjor welcomed him with words about having the heart of a Nord; Athis mourned his fall","best":"Skjor''s compliment when Athis joined the Companions","worst":"Skjor fell to the Silver Hand"},"Torvar":{"aff":35,"type":"platonic","relation":"fellow Companion","note":"Discusses weapon styles and future ambitions together"},"Farkas":{"aff":20,"type":"platonic","relation":"fellow Companion","note":"Friendly banter about weapon preferences, though Farkas dismisses his shortsword style"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('atmah', '{"Arch-Mage of Winterhold":{"aff":85,"type":"mentor","relation":"mentor and star pupil","note":"The Arch-Mage considered Atmah his favorite student; she sought to prove worthy of his faith.","best":"Being chosen as the Arch-Mage''s favorite student"},"Savos Aren":{"aff":15,"type":"betrayed","relation":"close friend turned betrayer","note":"Expedition companion who enthralled Atmah and Hafnar to contain Morokei, sacrificing them so he alone could escape.","best":"Sharing optimism and camaraderie before the expedition turned dire","worst":"Being enthralled and abandoned as an eternal warden containing the dragon priest"},"Hafnar Ice-Fist":{"aff":70,"type":"platonic","relation":"fellow victim and companion","note":"Companion who shared her fate, pledging to stay together no matter what in their final moments.","best":"Pledging to stay together through the final chamber","worst":"Both enthralled and left behind as eternal wardens"},"Takes-In-Light":{"aff":40,"type":"platonic","relation":"expedition member","note":"Atmah carried guilt for leaving her behind when she refused to go on.","worst":"Abandoning her to die alone in Labyrinthian"},"Morokei":{"aff":-90,"type":"enemy","relation":"cause of the expedition''s doom","note":"The dragon priest whose power forced Savos to sacrifice Atmah and Hafnar as eternal wardens.","worst":"Being enthralled to eternally contain Morokei"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('attendant', '{"Venarus Vulpin":{"aff":-45,"type":"servant","relation":"vampire thrall","note":"Controlled through thralldom, serves with compliant submissiveness","worst":"Subjugated into vampire thralldom"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('atub', '{"Yamarz":{"aff":-15,"type":"professional","relation":"chief","note":"Frustrated by his weakness and stubborn pride but bound by duty to advise him","worst":"He dismisses her counsel and refuses outside help while the tribe suffers"},"Ugor":{"aff":15,"type":"professional","relation":"tribeswoman","note":"Tense dynamic as Ugor questions her decisions but ultimately yields","worst":"Ugor challenges her judgment and front of outsiders"},"Malacath":{"aff":75,"type":"servant","relation":"patron deity","note":"Devoted spiritual intermediary who performs rituals to petition him","best":"Malacath answered her ritual and spoke directly to the tribe"},"Largashbur Tribe":{"aff":65,"type":"protective","relation":"her tribe","note":"Respected wise woman determined to lift the curse and ensure their survival"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('augur_of_dunlain', '{"Tolfdir":{"aff":65,"type":"platonic","relation":"former colleague","note":"One of the few who still regularly seeks his counsel","best":"Remembers him as a brilliant student and accomplished wizard"},"Savos Aren":{"aff":35,"type":"professional","relation":"former colleague","note":"Maintained cautious respect for the Augur''s knowledge and power"},"Colette Marence":{"aff":45,"type":"professional","relation":"former colleague","note":"Respects his Restoration mastery and sends students for his approval"},"Ancano":{"aff":-55,"type":"suspicious","relation":"Thalmor agent","note":"Warns that his pursuit of the Eye will lead to his undoing","worst":"Ancano sought his knowledge for dangerous ends"},"College of Winterhold":{"aff":55,"type":"protective","relation":"former member","note":"Seeks to guide and protect the College from magical threats it may not understand"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aval_atheron', '{"Faryl Atheron":{"aff":35,"type":"familial","relation":"brother","note":"Family bond strained by Faryl''s decision to work for a Nord farmer, which Aval finds embarrassing","worst":"Ashamed that his brother chose to labor under Nords rather than maintain Dunmer independence"},"Suvaris Atheron":{"aff":35,"type":"familial","relation":"sister","note":"Loves his sister but views her employment with Clan Shatter-Shield as settling for Nord servitude","worst":"Frustrated that Suvaris accepted a position serving a Nord family rather than pursuing independence"},"Brunwulf Free-Winter":{"aff":75,"type":"grateful","relation":"advocate and friend","note":"Deeply admires Brunwulf for speaking to Ulfric on behalf of the Dunmer and Argonians","best":"Offered Brunwulf a discount at his stall in gratitude for advocating for Dunmer rights"},"Ambarys Rendar":{"aff":45,"type":"platonic","relation":"acquaintance","note":"Respects Ambarys but considers his anti-Nord views too extreme for practical life in Windhelm"},"Revyn Sadri":{"aff":65,"type":"platonic","relation":"friend and fellow merchant","note":"Actively promotes Revyn''s used wares business to customers, showing genuine camaraderie","best":"Regularly directs customers to Sadri''s Used Wares in the Gray Quarter"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('aventus_aretino', '{"Naalia Aretino":{"aff":90,"type":"familial","relation":"mother","note":"Died from illness last winter; deeply loved and missed","best":"Lived a normal, happy life with her before her death"},"Grelod the Kind":{"aff":-95,"type":"nemesis","relation":"tormentor","note":"Cruel headmistress whose murder he contracted via Black Sacrament","worst":"Endured severe abuse and mistreatment at Honorhall"},"Constance Michel":{"aff":70,"type":"protective","relation":"kind caretaker","note":"The one kind person at Honorhall; specifically asked for her to be spared","best":"Showed genuine kindness to the orphans amid Grelod''s cruelty"},"Dark Brotherhood":{"aff":75,"type":"admirer","relation":"would-be saviors","note":"Performed the Black Sacrament to contact them; wants to become an assassin someday","best":"Believed they would come save him from Grelod"},"Honorhall Orphans":{"aff":60,"type":"platonic","relation":"fellow orphans","note":"Fellow victims he misses and sought to protect by eliminating Grelod"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('avrusa_sarethi', '{"Aduri Sarethi":{"aff":55,"type":"protective","relation":"younger sister","note":"Constantly tries to guide and discipline her wayward sister while worrying about her safety","best":"Sharing breakfast together each morning before farm work","worst":"Aduri''s free-spirited nature causing constant worry and extra supervision"},"Sinderion":{"aff":85,"type":"mentor","relation":"mentor and friend","note":"Deceased alchemist who taught her the secret of cultivating Nirnroot, whose legacy she preserves","best":"Learning the impossible art of growing Nirnroot from seeds","worst":"Losing touch with him before his death, never learning his final fate"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('avulstein_gray-mane', '{"Thorald Gray-Mane":{"aff":95,"type":"familial","relation":"brother","note":"Desperately seeks to rescue him from Imperial captivity","best":"Growing up together as proud Gray-Mane warriors","worst":"Learning of Thorald''s capture and reported death"},"Fralia Gray-Mane":{"aff":85,"type":"familial","relation":"mother","note":"She maintains his secrecy and shares his grief over Thorald"},"Eorlund Gray-Mane":{"aff":80,"type":"familial","relation":"father","note":"Respected patriarch whose Skyforge craft Avulstein learned"},"Olfina Gray-Mane":{"aff":75,"type":"familial","relation":"sister","note":"Trusted confidante during his seclusion"},"Vignar Gray-Mane":{"aff":70,"type":"familial","relation":"uncle","note":"Political ally and family patriarch who shares Stormcloak sympathies"},"Idolaf Battle-Born":{"aff":-85,"type":"enemy","relation":"former friend","note":"Childhood best friends turned bitter enemies by the Civil War","best":"Growing up together as best friends in peaceful times","worst":"Idolaf threatening to throw him in jail as a traitor"},"Battle-Born Clan":{"aff":-75,"type":"enemy","relation":"rival clan","note":"Once-close families torn apart by opposing Civil War allegiances","best":"Shared history tracing back to Ysgramor''s companions","worst":"Their Imperial loyalty and suspected knowledge of Thorald''s fate"},"Imperial Legion":{"aff":-90,"type":"nemesis","relation":"hated foe","note":"Blames them for Thorald''s capture and lives in fear of detention","worst":"Thorald seized by Imperials and handed to the Thalmor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('azzada_lylvieve', '{"Michel Lylvieve":{"aff":95,"type":"romantic","relation":"wife","note":"Credits her with saving him from a Markarth gutter death","best":"Meeting Michel and knowing he finally belonged somewhere"},"Clinton Lylvieve":{"aff":75,"type":"familial","relation":"son","note":"Strives to protect him and provide the stable childhood he never had"},"Julienne Lylvieve":{"aff":80,"type":"protective","relation":"daughter","note":"Fiercely guards her after soldiers threatened her","worst":"A soldier tried to have his way with Julienne"},"Logrolf the Bent":{"aff":85,"type":"mentor","relation":"savior, father figure","note":"Rescued him from the streets and gave him money to escape Markarth","best":"Logrolf pulled him off the streets and gave him a chance at life","worst":"Logrolf now sleeps on the street believing his house is haunted"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('azzadal', '{"Madanach":{"aff":60,"type":"professional","relation":"patron","note":"Served as his court bard during his rule of The Reach","best":"Madanach arranged allies to help complete my legendary performance"},"The Sheathed Blades":{"aff":55,"type":"grateful","relation":"allies","note":"Attempted to help him complete his poetic leap from Bard''s Leap Summit","best":"They supported my attempt at the legendary leap"},"Player":{"aff":40,"type":"admirer","relation":"fellow leaper","note":"Rewards those who survive the leap at Bard''s Leap Summit","best":"Witnessed another survive the legendary leap"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('babette', '{"Astrid":{"aff":80,"type":"platonic","relation":"matron and leader","note":"Considers Astrid her matron over the Night Mother, showing deep personal loyalty","best":"Declared Astrid as her matron, choosing her over ancient tradition"},"Nazir":{"aff":65,"type":"platonic","relation":"fellow assassin and friend","note":"Shares camaraderie and mutual respect within the sanctuary"},"Festus Krex":{"aff":55,"type":"professional","relation":"colleague","note":"Bonds over shared interest in magical and alchemical arts"},"Dark Brotherhood":{"aff":85,"type":"fanatical","relation":"family","note":"Treats fellow members as extended family and has served loyally for centuries","best":"Survived multiple eras of the Brotherhood''s history while remaining devoted"},"Cicero":{"aff":25,"type":"neutral","relation":"fellow assassin","note":"Indifferent toward his fanaticism for the Night Mother and old ways"},"Night Mother":{"aff":15,"type":"estranged","relation":"former deity","note":"Would have died for her two centuries ago, but now considers that age long past","worst":"Abandoned devotion to the Unholy Matron in favor of Astrid''s leadership"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('badnir', '{"Thorgar":{"aff":75,"type":"professional","relation":"employee","note":"Blindly loyal to his employer and mentor figure, endures harsh conditions because Thorgar needs him","best":"Thorgar praised him as the best at breaking rocks"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bagrak', '{"Sharamph":{"aff":85,"type":"familial","relation":"mother","note":"Deeply respects her as the stronghold''s wise-woman and refers others to her for cures and poisons"},"Chief Larak":{"aff":70,"type":"familial","relation":"brother","note":"Supports him as chief but acknowledges he still has much to prove"},"Shuftharz":{"aff":40,"type":"professional","relation":"fellow stronghold member","note":"Refers travelers to her as the stronghold''s blacksmith"},"Late Husband":{"aff":55,"type":"familial","relation":"late husband","note":"Deceased warrior from another stronghold; she returned home after his death","worst":"Lost him and had to return to Mor Khazgur as a widow"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('balagog_gro-nolob', '{"Anton Virane":{"aff":65,"type":"platonic","relation":"former friend and confidant","note":"Fellow student from training days in High Rock who knows his true identity","best":"Studying Breton cuisine together in their youth","worst":"Having to sever ties to protect his secret"},"Emperor Titus Mede II":{"aff":55,"type":"professional","relation":"employer","note":"Knows him only as The Gourmet, not by his real name or race","best":"Being chosen as the Emperor''s personal chef for Skyrim visits","worst":"The imperial association marking him for assassination"},"Hadring":{"aff":25,"type":"transactional","relation":"landlord","note":"Respects his privacy and asks no questions as long as rent is paid","best":"Never prying into his identity or business"},"Dark Brotherhood":{"aff":-95,"type":"nemesis","relation":"assassins targeting him","note":"Marked for death due to his connection to the Emperor","worst":"Being hunted as a stepping stone to imperial assassination"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('balbus', '{"The Gourmet":{"aff":92,"type":"fanatical","relation":"culinary idol","note":"Abandoned warrior life after reading Uncommon Taste; wanders Skyrim seeking the Gourmet''s identity","best":"Meeting the Gourmet and presenting his collected rare ingredients and prized fork","worst":"May never discover the Gourmet''s true identity"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('baldor_iron-shaper', '{"Deor Woodcutter":{"aff":60,"type":"platonic","relation":"friend","note":"Fellow Skaal villager and trusted companion"},"Fanari Strong-Voice":{"aff":50,"type":"professional","relation":"village leader","note":"Respects her leadership of the Skaal"},"Ancarion":{"aff":-85,"type":"enemy","relation":"abductor","note":"Thalmor elf who abducted him to steal sacred Stalhrim forging secrets","worst":"Dragged from his home and interrogated for the ancient knowledge"},"The Skaal":{"aff":80,"type":"protective","relation":"his people","note":"Serves as their trusted smith and keeper of ancient forge-craft"},"Storn Crag-Strider":{"aff":70,"type":"platonic","relation":"village elder","note":"Revered shaman and the strong center of the Skaal","worst":"Witnessed his sacrificial death during the stand against Miraak"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('balgruuf_the_greater', '{"Irileth":{"aff":80,"type":"protective","relation":"housecarl and closest advisor","note":"Trusts his Dunmer housecarl above all others at court"},"Proventus Avenicci":{"aff":55,"type":"professional","relation":"steward","note":"Relies on him for political counsel though sometimes dismissive"},"Ulfric Stormcloak":{"aff":-30,"type":"rival","relation":"longstanding rival","note":"Has carried on a rivalry with Ulfric since they were both young","worst":"Ulfric''s murder of the High King forces him toward an impossible choice"},"Vignar Gray-Mane":{"aff":-20,"type":"rival","relation":"political rival","note":"Old Whiterun family rival competing for influence in the hold"},"Farengar Secret-Fire":{"aff":60,"type":"professional","relation":"court wizard","note":"Respects his expertise on magical and dragon-related matters"},"The Greybeards":{"aff":75,"type":"admirer","relation":"spiritual influence","note":"Made pilgrimage to High Hrothgar in youth and holds them in high regard","best":"The pilgrimage to High Hrothgar deeply shaped his spiritual outlook"},"Nelkir":{"aff":40,"type":"familial","relation":"youngest son","note":"Complex relationship with his troubled youngest son","worst":"Nelkir''s dark whispers from the Whispering Door suggest something deeply wrong"},"Hrongar":{"aff":65,"type":"familial","relation":"brother","note":"His brother serves as an advisor at court"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('balimund', '{"Asbjorn Fire-Tamer":{"aff":85,"type":"familial","relation":"adopted son and apprentice","note":"Raised and trained him as his own; Asbjorn inherits the forge if Balimund dies","best":"Passing down the family smithing traditions"},"Maven Black-Briar":{"aff":15,"type":"suspicious","relation":"business acquaintance","note":"Maintains independence from her influence despite operating in her city","worst":"Her creeping control over Riften''s economy"},"Harrald Law-Giver":{"aff":25,"type":"professional","relation":"client","note":"Regular client from the Jarl''s court whom Balimund considers lazy","worst":"Harrald sending others to fetch his sword instead of coming himself"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bandit', '{"Fellow Bandits":{"aff":65,"type":"protective","relation":"gang mates","note":"Close-knit survival bond forged through shared hardship and mutual dependence"},"Bandit Chief":{"aff":40,"type":"professional","relation":"superior","note":"Follows the chief''s leadership, which is maintained through strength and cunning"},"Hold Guards":{"aff":-85,"type":"enemy","relation":"pursuers","note":"Sworn enemies who will arrest or kill on sight","worst":"Hunted like animals across the holds"},"Merchants and Travelers":{"aff":-30,"type":"contempt","relation":"prey","note":"Viewed as targets for robbery and extortion rather than people"},"Local Settlements":{"aff":-60,"type":"enemy","relation":"raiding targets","note":"Hostile relationship maintained through raids and plundering"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bandit_highwayman', '{"Fellow Bandits":{"aff":55,"type":"professional","relation":"gang subordinates","note":"Commands loyalty through fair treatment and even distribution of spoils"},"Merchants":{"aff":10,"type":"transactional","relation":"targets","note":"Known as ''The Reasonable Raider'' for preferring negotiation over violence"},"Corrupt Guards":{"aff":25,"type":"transactional","relation":"bribed contacts","note":"Network of guards who ignore his activities in exchange for a cut"},"Rival Bandit Chiefs":{"aff":-15,"type":"rival","relation":"territorial rivals","note":"Maintains uneasy truces to avoid costly conflicts","worst":"Skirmishes over prime ambush territory"},"Forsworn":{"aff":-70,"type":"enemy","relation":"destroyers of family livelihood","note":"Forsworn Uprising destroyed his family''s farm and drove him to banditry","worst":"Family farm destroyed during the uprising"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bandit_marauder', '{"Fellow Bandits":{"aff":15,"type":"professional","relation":"subordinates","note":"Commands through fear and proven success rather than genuine loyalty"},"Guard Informants":{"aff":10,"type":"transactional","relation":"paid informants","note":"Corrupt guards who provide advance warning of patrols for coin"},"Rival Bandit Leaders":{"aff":-40,"type":"rival","relation":"competitors","note":"Occasional uneasy alliances but frequent betrayals and territorial disputes","worst":"A rival gang ambushed one of our raids and took the haul"},"Fence Contacts":{"aff":20,"type":"transactional","relation":"business partners","note":"Essential for converting stolen goods into spendable gold across the holds"},"Family":{"aff":25,"type":"estranged","relation":"estranged kin","note":"Poor farmers outside Windhelm who lost everything; the marauder left that life behind","worst":"The winter that took everything from us"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bandit_outlaw', '{"Bandit Chief":{"aff":15,"type":"rival","relation":"superior","note":"Respects their authority but secretly plots to overthrow them and take control","best":"Acknowledged for successful raid planning","worst":"Humiliated in front of the crew after a failed shakedown"},"Fellow Bandits":{"aff":10,"type":"suspicious","relation":"crew members","note":"Maintains cautious alliances while constantly watching for betrayal","worst":"Lost a good fighter to a knife in the back over loot disputes"},"Whiterun Guards":{"aff":-75,"type":"enemy","relation":"hunters of the clan","note":"Particular hatred for guards who have killed several crew members","worst":"Watched comrades cut down in a botched ambush near Whiterun"},"Traveling Merchants":{"aff":-25,"type":"contempt","relation":"targets","note":"Regular shakedown targets; some pay protection money, viewed as part of a corrupt system","best":"A merchant who paid up without fuss and shared useful road intelligence"},"Rival Bandit Clans":{"aff":-45,"type":"rival","relation":"competitors","note":"Territorial disputes and competitive hostility over prime raiding grounds","worst":"Lost a cache of stolen goods to a rival clan''s raid on the camp"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bandit_plunderer', '{"Fellow Bandits":{"aff":45,"type":"professional","relation":"respected comrade","note":"Commands respect through competence rather than intimidation among fellow bandits"},"Merchant Fences":{"aff":25,"type":"transactional","relation":"business contact","note":"Maintains hidden contacts who fence stolen goods for mutual profit"},"Hold Guards":{"aff":-80,"type":"enemy","relation":"pursuers","note":"Known to several holds'' patrols with standing orders for their capture"},"Rival Bandit Leaders":{"aff":-10,"type":"rival","relation":"uneasy competitor","note":"Mix of tense alliances and bitter feuds with other bandit leaders"},"Former Family":{"aff":40,"type":"estranged","relation":"estranged family","note":"Severed all ties years ago to protect them from association with banditry","worst":"The devastating drought that destroyed the family farm and left them destitute"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bandit_thug', '{"Bandit Chief":{"aff":25,"type":"professional","relation":"leader","note":"Shows deference while harboring ambitions of advancement","best":"Promoted from lookout to thug under chief''s gang","worst":"Passed over or disciplined by chief"},"Fellow Bandits":{"aff":35,"type":"platonic","relation":"comrades","note":"Crude loyalty based on mutual survival and benefit","best":"Sharing spoils and watching each other''s backs in raids","worst":"Betrayal or abandonment during a skirmish"},"Hold Guards":{"aff":-70,"type":"enemy","relation":"law enforcement","note":"Frequent violent encounters and ongoing hostility","worst":"Narrow escape or injury during a guard ambush"},"Merchants":{"aff":-40,"type":"contempt","relation":"targets","note":"Views them purely as prey for robbery and extortion"},"Traveling Mercenaries":{"aff":-25,"type":"rival","relation":"competition","note":"Seen as both competition and potential threats"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('banning', '{"Cedran":{"aff":45,"type":"professional","relation":"business partner","note":"Lives and works with him at Markarth Stables; expressed genuine fondness when Cedran died"},"Eola":{"aff":55,"type":"platonic","relation":"fellow cultist","note":"Respects her as hostess who keeps Namira''s faithful together","best":"Shared the feast of Namira together"},"Voada":{"aff":25,"type":"professional","relation":"delivery contact","note":"Receives his spiced beef deliveries for the Jarl''s dogs"},"Hogni Red-Arm":{"aff":35,"type":"platonic","relation":"fellow cultist","note":"Fellow guest at Namira''s feast with shared dark history"},"Marex":{"aff":0,"type":"betrayed","relation":"former friend","note":"Accidentally killed while hunting together","worst":"Mistook him for an elk, then brought him back as meat"},"Namira":{"aff":60,"type":"fanatical","relation":"patron deity","note":"Devoted cultist of the Lady of Decay"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('baral_sendu', '{"Fort Dunstad Guards":{"aff":35,"type":"professional","relation":"protectors","note":"Military personnel whose presence initially provided security for his farming operation"},"The Stumbling Sabrecat Innkeeper":{"aff":40,"type":"platonic","relation":"neighbor","note":"Regular patron and neighbor at the inn where he ultimately died"},"Fellow Farmers":{"aff":30,"type":"platonic","relation":"colleagues","note":"Collaborative agricultural workers sharing knowledge and labor"},"Bandits":{"aff":-100,"type":"enemy","relation":"killers","worst":"Overrun Fort Dunstad and murdered him in his bed"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('barbas', '{"Clavicus Vile":{"aff":35,"type":"protective","relation":"other half","note":"Bound together as halves of the same power; Barbas serves as Vile''s conscience and moderating influence","best":"Working in harmony to balance the Prince''s deals","worst":"Banished by Vile when his counsel becomes inconvenient"},"Dragonborn":{"aff":30,"type":"platonic","relation":"reluctant ally","note":"Seeks the Dragonborn''s aid to reunite with Clavicus Vile and retrieve the Rueful Axe","best":"Fought alongside at Haemar''s Shame against cultists and vampires"},"Lod":{"aff":10,"type":"neutral","relation":"would-be keeper","note":"Falkreath blacksmith who unknowingly wishes to adopt him as a mere pet dog"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('barknar', '{"Wilhelm":{"aff":45,"type":"professional","relation":"innkeeper","note":"Regular patron who depends on Vilemyr Inn for lodging and meals between pilgrimages"},"Klimmek":{"aff":35,"type":"platonic","relation":"fellow traveler","note":"Share the 7000 Steps path, though Klimmek''s journeys serve more practical ends"},"Greybeards":{"aff":65,"type":"awed","relation":"spiritual exemplars","note":"Honors them through pilgrimage and meditation on the etched tablets, though they do not receive visitors"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bashnag', '{"Selveni Nethri":{"aff":-85,"type":"betrayed","relation":"exiled former coven member","note":"Cursed and drove her out for challenging his authority","worst":"Chased her into a spider web and left her to die"},"Spellsword Coven Members":{"aff":25,"type":"professional","relation":"coven leader","note":"Maintains strict control through fear and intimidation","best":"Coven follows his orders without question"},"Local Necromancers":{"aff":15,"type":"transactional","relation":"loose allies","note":"Maintains informal alliances with fellow dark magic practitioners"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bassianus_axius', '{"Fastred":{"aff":80,"type":"romantic","relation":"lover","note":"Desperately wants to elope with her to Riften against her father''s wishes","best":"She called him sweetie when he came to speak with her","worst":"She remains torn between him and Klimmek"},"Klimmek":{"aff":-25,"type":"rival","relation":"employer and housemate","note":"Romantic rival for Fastred; frequent arguments about business and personal life","worst":"Klimmek accused him of spending more time with Fastred than fishing"},"Jofthor":{"aff":-55,"type":"contempt","relation":"lover''s father","note":"Calls him a brute; fears his opposition and retaliation if they elope","worst":"Jofthor will come after them if they run away together"},"Boti":{"aff":60,"type":"grateful","relation":"lover''s mother","note":"She favors him over Klimmek and offered to handle Jofthor so they can elope","best":"She offered to deal with Jofthor so he and Fastred could be together"},"Wilhelm":{"aff":35,"type":"platonic","relation":"innkeeper","note":"Friendly confidant who encourages him to follow his heart regarding Fastred"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('batum_gra-bar', '{"Sinding":{"aff":-85,"type":"enemy","relation":"final quarry","note":"Werewolf she was hunting as part of Hircine''s Great Hunt","worst":"Killed by Sinding in Bloated Man''s Grotto"},"Hircine":{"aff":40,"type":"servant","relation":"hunt participant","note":"Member of Hircine''s hunting faction, participated in the Great Hunt"},"Stronghold Family":{"aff":-15,"type":"estranged","relation":"estranged kin","note":"Left behind when she rejected the forge-wife tradition"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bear', '{"Cubs":{"aff":70,"type":"familial","relation":"offspring","note":"Fiercely protective of young during and beyond breeding season"},"Spriggans":{"aff":40,"type":"platonic","relation":"natural ally","note":"Share guardianship of wilderness domains"},"Hunters":{"aff":-25,"type":"rival","relation":"worthy opponent","note":"Respected adversaries who encroach on territory","worst":"Encounters ending in bloodshed over hunting grounds"},"Other Bears":{"aff":25,"type":"platonic","relation":"kin","note":"Loose social bonds maintained, stronger with mates during breeding season"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('beautiful_barbarian', '{"Dark Brotherhood":{"aff":-100,"type":"enemy","relation":"assassination target","note":"Unknowingly marked for death by their recurring contracts","worst":"Contract placed on her life without her knowledge"},"Vilemyr Inn Staff":{"aff":30,"type":"platonic","relation":"regular patron","note":"Cordial relationships with staff, occasionally helps with security","best":"Welcomed at the inn as a familiar and helpful face"},"Ivarstead Residents":{"aff":15,"type":"neutral","relation":"neighbors","note":"Respected locally but deliberately keeps her distance"},"Former Mercenary Contacts":{"aff":5,"type":"estranged","relation":"former colleagues","note":"Distant connections from her violent past she wishes to leave behind"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('beem-ja', '{"Salma":{"aff":-85,"type":"betrayed","relation":"false protector","note":"Maintained faÃ§ade of protective guidance while secretly planning to sacrifice her for power","best":"Appeared to offer wise counsel and caution during their travels","worst":"Revealed he always viewed her as too weak for his sacrifice plans"},"Salma''s Father":{"aff":-15,"type":"transactional","relation":"former retainer","note":"Served the family while exploiting the position to gather forbidden knowledge","worst":"Used family''s trust and resources to further his dark ambitions"},"Gathrik":{"aff":40,"type":"obsessed","relation":"power target","note":"Extensively studied the ancient warrior''s tomb and planned to absorb his power through blood sacrifice","best":"Years of careful research finally led to reaching Gathrik''s resting place"},"Player":{"aff":-90,"type":"betrayed","relation":"sacrifice target","note":"Used player to defeat Gathrik then attempted to sacrifice them for power absorption","best":"Initially cooperated as ally in exploring Ironbind Barrow","worst":"Declared player as blood sacrifice and attacked to absorb Gathrik''s power"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('beirand', '{"Sayma":{"aff":90,"type":"romantic","relation":"wife","note":"Beloved wife who keeps him from the battlefield; he jokes she''s more dangerous than soldiers","best":"Building a family and life together in Solitude"},"Kayd":{"aff":85,"type":"familial","relation":"son","note":"Raising him to value hard work; his main reason for staying off the front lines","best":"Teaching Kayd the value of honest labor"},"Heimvar":{"aff":65,"type":"mentor","relation":"apprentice","note":"Trains him with a balance of strict standards and friendly guidance"},"Imperial Legion":{"aff":55,"type":"professional","relation":"primary client","note":"Keeps him constantly busy supplying arms and armor; he respects their cause"},"Roggvir":{"aff":-40,"type":"contempt","relation":"executed traitor","note":"Watched his execution and called him a traitor to the end","worst":"Witnessing Roggvir''s public execution for treason"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('beitild', '{"Leigelf":{"aff":-20,"type":"estranged","relation":"estranged husband","note":"Bitter business rivalry masks unresolved feelings beneath hostility","best":"Marriage once united two of Dawnstar''s mining operations","worst":"Declared war on each other''s mines while still legally married"},"Karl":{"aff":-15,"type":"contempt","relation":"employee","note":"Drives her workers hard with frequent harsh criticism and threats","worst":"Threatened Karl''s employment for questioning her war rhetoric"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('belchimac', '{"Ragnar":{"aff":-25,"type":"fearful","relation":"fellow miner","note":"Threatened by Ragnar and quickly submits, though Ragnar sometimes apologizes afterward","worst":"Ragnar threatened to cut his throat for complaining about Nords"},"Lash":{"aff":-35,"type":"contempt","relation":"fellow miner","note":"Harbors bigoted views toward Orcs but backs down immediately when confronted","worst":"Made prejudiced remarks about bunking with Orcs, then groveled when Lash threatened him"},"Enmon":{"aff":25,"type":"platonic","relation":"fellow miner","note":"Shares grievances about the mine and Silver-Blood oppression","best":"Commiserates with Enmon about their shared troubles and the Silver-Bloods"},"Silver-Blood Family":{"aff":-75,"type":"enemy","relation":"oppressors","note":"Views them as tyrants who will eventually enslave the miners at Cidhna Mine","worst":"Convinced the Silver-Bloods will find a way to send them all to Cidhna Mine as slaves"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('belethor', '{"Sigurd":{"aff":20,"type":"professional","relation":"shop assistant","note":"Reliable help around the shop, valued as labor if not as company"},"Ysolda":{"aff":-10,"type":"rival","relation":"competitor","note":"Dismissive of her merchant aspirations, sees her as an upstart threat to his dominance"},"Arcadia":{"aff":15,"type":"transactional","relation":"fellow merchant","note":"Occasional business dealings, cordial but ultimately self-interested"},"Hulda":{"aff":25,"type":"professional","relation":"drinking companion","note":"Business associate at The Bannered Mare where he unwinds after hours"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('beleval', '{"Isran":{"aff":30,"type":"professional","relation":"leader","note":"Respects his mission against vampires despite openly disliking him personally","best":"Joined his cause to protect Skyrim''s people from monsters","worst":"Cannot stand his personality but endures it for the mission"},"Dawnguard":{"aff":65,"type":"protective","relation":"faction","note":"Abandoned her bandit past to serve a greater cause and seek redemption","best":"Found purpose and redemption through honorable service"},"Vampires":{"aff":-90,"type":"enemy","relation":"sworn enemy","note":"Dedicated herself to destroying them after witnessing their predation on innocents","worst":"Witnessed vampires preying upon innocent civilians"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('belrand', '{"Corpulus Vinius":{"aff":35,"type":"transactional","relation":"innkeeper","note":"Belrand resides at the Winking Skeever and relies on Corpulus for lodging"},"College of Winterhold":{"aff":20,"type":"professional","relation":"presumed alma mater","note":"Likely received magical training there, though connections remain loose"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('belyn_hlaalu', '{"Adisla":{"aff":40,"type":"professional","relation":"employee","note":"Stern but fair employer who values her work despite occasional criticism","worst":"She burns through too much firewood keeping the cabin warm"},"Captain Lonely-Gale":{"aff":55,"type":"admirer","relation":"admired figure","note":"Shows particular fascination with the retired captain and his story","best":"His story is something remarkable"},"Endario":{"aff":-30,"type":"professional","relation":"supplier","note":"Frustrated with his failure to deliver frostwheat shipments on time","worst":"Called him a fool and threatened to thrash him over the delayed shipment"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bendt', '{"Viarmo":{"aff":35,"type":"professional","relation":"employer","note":"Viarmo respects Bendt''s need for solitude, a rare accommodation Bendt values"},"College Students":{"aff":-35,"type":"contempt","relation":"nuisance","note":"Views them as intrusive disruptions to his carefully maintained kitchen routine","worst":"Students barging into his kitchen uninvited"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('benor', '{"Gorm":{"aff":65,"type":"platonic","relation":"close friend","note":"Drinking companion who shares secret dissatisfaction with Jarl''s rule","best":"Sharing drinks and trusted talks at Moorside Inn"},"Jarl Idgrod Ravencrone":{"aff":-40,"type":"contempt","relation":"Jarl","note":"Distrusts her passive governance and failure to protect Morthal","worst":"Her inaction leaves the town vulnerable"},"Falion":{"aff":-50,"type":"suspicious","relation":"court wizard","note":"Deeply suspicious of his magical practices and presence in town","worst":"His magic threatens Morthal''s traditional ways"},"Alva":{"aff":25,"type":"crush","relation":"temptress","note":"Tempted by her advances but refuses to cuckold Hroggar on principle","best":"She seeks his company openly","worst":"She stays with a kinslayer"},"Hroggar":{"aff":-60,"type":"contempt","relation":"kinslayer","note":"Views him as a murderer who killed his own family","worst":"His kinslaying crimes against his own household"},"Morthal Guard":{"aff":40,"type":"professional","relation":"unofficial auxiliary","note":"Cooperates with guards on patrols despite lacking formal appointment","best":"Allowed to sleep in the guardhouse"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bergritte_battle-born', '{"Olfrid Battle-Born":{"aff":80,"type":"familial","relation":"husband","note":"Long-married patriarch and matriarch of Clan Battle-Born"},"Lars Battle-Born":{"aff":90,"type":"protective","relation":"grandson","note":"Fiercely protects him from bullying and hardship","worst":"Lars being bullied by Braith"},"Alfhild Battle-Born":{"aff":80,"type":"familial","relation":"daughter","best":"Shared humorous moments reading together"},"Jon Battle-Born":{"aff":75,"type":"familial","relation":"son","note":"Worries about his secret romance with Olfina Gray-Mane"},"Idolaf Battle-Born":{"aff":55,"type":"familial","relation":"son-in-law"},"Gray-Mane Family":{"aff":-50,"type":"rival","relation":"rival clan","note":"Former friends for generations, now bitter enemies due to civil war","worst":"Generations of friendship destroyed by civil war rivalry"},"Braith":{"aff":-35,"type":"contempt","relation":"grandson''s bully","note":"Wants to confront her mother about the bullying"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bersi_honey-hand', '{"Drifa":{"aff":90,"type":"romantic","relation":"wife","note":"Loving and supportive wife who helps run The Pawned Prawn"},"Thieves Guild":{"aff":-75,"type":"enemy","relation":"extortionists","note":"Extorts protection money from his shop; he resents their parasitic grip on Riften''s merchants","worst":"Being forced to pay protection money after a brawl or the destruction of his prized Dwemer urn"},"Brynjolf":{"aff":-65,"type":"contempt","relation":"extortionist","note":"Thieves Guild fixer who sends collectors to demand payment; Bersi views him as cowardly for delegating the dirty work"},"Temple of Mara":{"aff":75,"type":"platonic","relation":"devoted worshipper","note":"Believes devout worship at the Temple can cure Riften''s moral decay, despite ridicule from other citizens"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('betrid_silver-blood', '{"Thonar Silver-Blood":{"aff":20,"type":"transactional","relation":"husband","note":"Married him solely for wealth and influence; frustrated by his reluctance to challenge Thongvor","best":"The luxurious life his money provides","worst":"His refusal to seize control of the family from Thongvor"},"Thongvor Silver-Blood":{"aff":-40,"type":"rival","relation":"brother-in-law","note":"Views him as an obstacle preventing Thonar from leading the Silver-Bloods","worst":"His continued dominance over family affairs"},"Rhiada":{"aff":-30,"type":"contempt","relation":"servant","note":"Treats her with disdain; nearly revealed her own Dibella temple past while berating her","worst":"Almost exposed her secret past while scolding her"},"Nana Ildene":{"aff":-25,"type":"contempt","relation":"servant","note":"Dismissed as just another servant; ultimately murdered by her during the Forsworn plot","worst":"Killed by her in a Forsworn-orchestrated assassination"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('big_laborer', '{"Katla":{"aff":35,"type":"professional","relation":"employer","note":"She values his work ethic despite his gruff demeanor, and he maintains a strong sense of duty to her farm","best":"Proved his worth as an invaluable worker through strength and expertise","worst":"Lost his independence and must labor for another after his own farm was destroyed"},"Solitude Guards":{"aff":-15,"type":"suspicious","relation":"local authorities","note":"Occasional tension arises from his aggressive demeanor and irritable disposition toward outsiders"}}')
