INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('birna', '{"Ranmir":{"aff":25,"type":"familial","relation":"brother","note":"Reluctantly supports her alcoholic brother despite deep frustration with his self-destruction","best":"When Ranmir stops drinking and starts contributing again","worst":"Constant arguments about him drinking away their earnings"},"Thaena":{"aff":10,"type":"transactional","relation":"customer","note":"Only regular customer but the relationship is strained and purely business"},"Isabella":{"aff":-15,"type":"contempt","relation":"brother''s ex-girlfriend","note":"Her disappearance triggered Ranmir''s alcoholism and burdened Birna"},"College of Winterhold":{"aff":15,"type":"professional","relation":"business client","note":"Maintains a distant but necessary trade relationship with the institution"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bjartur', '{"Ahtar":{"aff":-65,"type":"enemy","relation":"jailor","note":"Antagonistic exchanges through the cell bars; he threatens execution, she challenges his Imperial allegiance","worst":"He taunts her about her friends being executed and promises she''s next"},"Ulfric Stormcloak":{"aff":85,"type":"fanatical","relation":"rebel leader","note":"Deep devotion to his leadership and vision for an independent Skyrim"},"Legate Rikke":{"aff":-55,"type":"rival","relation":"Imperial officer","note":"Marked as rivals in the game''s relationship data"},"Stormcloak Rebels":{"aff":75,"type":"platonic","relation":"fellow rebels","note":"Unwavering loyalty to her comrades and the cause, even facing execution"},"Imperial Legion":{"aff":-70,"type":"contempt","relation":"captors","note":"Views them as oppressive occupiers; refuses to break under their imprisonment"}}')
ON CONFLICT (npc_name) DO UPDATE
