INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bjorlam', '{"Skulvar Sable-Hilt":{"aff":45,"type":"professional","relation":"colleague","note":"Fellow businessman at Whiterun Stables with whom he coordinates carriage services"},"Father":{"aff":70,"type":"familial","relation":"father","note":"Taught Bjorlam the carriage trade and passed down the family business"}}')
