INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bjornolfr', '{"Hrodulf":{"aff":85,"type":"romantic","relation":"lover","note":"Devoted partner who followed Hrodulf to Solstheim despite his warning letter, resulting in Bjornolfr''s death","best":"Their quiet life together in Solitude before Dwemer obsession","worst":"Hrodulf''s growing obsession that separated them and led to Bjornolfr''s fatal journey"}}')
