INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('black-briar_mercenary', '{"Maven Black-Briar":{"aff":65,"type":"professional","relation":"employer","note":"Respected and feared commander; years of steady service earned trusted position"},"Black-Briar Mercenaries":{"aff":78,"type":"platonic","relation":"comrades","note":"Tight-knit brotherhood forged through shared duty and combat"},"Riften Guard":{"aff":10,"type":"rival","relation":"rival security force","note":"Professional rivalry tempered by mutual understanding of respective roles"},"Thieves Guild":{"aff":12,"type":"transactional","relation":"cautious cooperator","note":"Cooperate only due to Maven''s alliance; no personal investment in the relationship"}}')
