INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('blaise', '{"Katla":{"aff":20,"type":"transactional","relation":"employer","note":"Took him in after his parents died, but only provides food for labor and makes him sleep in the stables","best":"Offered food and shelter when he had nowhere else to go","worst":"Treats him as a farmhand rather than a proper ward, relegating him to sleep with the horses"},"Geimund":{"aff":15,"type":"neutral","relation":"co-worker","note":"Fellow worker at Katla''s Farm who handles horse sales"},"Deceased Parents":{"aff":85,"type":"familial","relation":"parents","note":"Imperial Legion soldiers whose memory and values he strives to honor","worst":"Killed in an ambush while serving in the Legion, leaving him orphaned"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('blasphemous_priest', '{"Danica Pure-Spring":{"aff":-15,"type":"suspicious","relation":"superior","note":"She has growing suspicions about his behavior and unexplained absences","worst":"Her probing questions about his late-night activities"},"Temple of Kynareth":{"aff":-20,"type":"estranged","relation":"fellow priests","note":"Maintains a strained facade with colleagues who sense something amiss"},"Dark Brotherhood":{"aff":35,"type":"transactional","relation":"client","note":"Performed the Black Sacrament and awaits fulfillment of the contract","best":"The Night Mother heard his prayer at last"},"Unknown Target":{"aff":-90,"type":"nemesis","relation":"intended victim","note":"The object of his desperate murderous intentions, identity varies","worst":"Whatever drove him to perform the Black Sacrament"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('blood_horker', '{"Haldyn":{"aff":80,"type":"mentor","relation":"commander","note":"Respected battlemage leader, shows unwavering loyalty to his vision","best":"Proving worth in raids under Haldyn''s command"},"Stig Salt-Plank":{"aff":75,"type":"professional","relation":"captain","note":"Direct captain and tactical superior under whom they serve","best":"Joining the crew under Stig''s leadership"},"Clan Shatter-Shield":{"aff":55,"type":"transactional","relation":"business partners","note":"Secret arrangement protects their shipping in exchange for gold"},"Suvaris Atheron":{"aff":45,"type":"transactional","relation":"contact","note":"Key contact coordinating protected shipping routes for the clan"},"East Empire Company":{"aff":-85,"type":"enemy","relation":"target","note":"Primary targets whose operations they raid and interfere with","worst":"East Empire assault on Japhet''s Folly"}}')
ON CONFLICT (npc_name) DO UPDATE
