INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('blooded_vampire', '{"Master Vampire":{"aff":30,"type":"servant","relation":"sire and coven leader","note":"Subservient to the master who turned them, but ambitions may eventually conflict","best":"survived the turning and was accepted into the coven","worst":"remains trapped in a subordinate position despite growing power"},"Vampire Coven":{"aff":25,"type":"platonic","relation":"coven member","note":"Loose alliance with fellow vampires sharing lair and territory","best":"found belonging and protection after the difficult transition","worst":"constant subtle competition for standing and the master''s favor"},"Vampire''s Thralls":{"aff":-10,"type":"contempt","relation":"dominated servants","note":"Viewed as useful tools for blood and protection, nothing more","best":"reliable source of sustenance without risky hunting","worst":"thralls are weak and provide no real challenge or satisfaction"},"Vigilants of Stendarr":{"aff":-80,"type":"fearful","relation":"sworn enemies","note":"Active threat that forces constant vigilance and secrecy","best":"escaped an encounter with a patrol undetected","worst":"lost coven mates to a Vigilant raid"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bodil', '{"Beitild":{"aff":25,"type":"professional","relation":"employer","note":"Works under Beitild at Iron-Breaker Mine with a strictly professional arrangement"},"Gjak":{"aff":45,"type":"platonic","relation":"fellow miner","note":"Her only regular companion, both sharing the same reclusive dedication to mining life underground"}}')
ON CONFLICT (npc_name) DO UPDATE
