INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('boethiah_cultist', '{"Boethiah":{"aff":95,"type":"fanatical","relation":"deity","note":"Fanatically devoted, seeks to become Boethiah''s most favored mortal servant","best":"Earned place at the Sacellum through acts of cunning and betrayal in Boethiah''s name"},"Fellow Cultists":{"aff":15,"type":"suspicious","relation":"cautious allies","note":"Maintains alliances while expecting eventual betrayal as sacred practice","worst":"Anticipates betrayal from those she works alongside"},"Potential Initiates":{"aff":-5,"type":"contempt","relation":"tools","note":"Views them as instruments for advancing Boethiah''s will, potential sacrifices"},"Vigilants of Stendarr":{"aff":-80,"type":"enemy","relation":"natural enemies","note":"Seek to destroy Daedric cults and all who worship the Princes"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bolar', '{"Mauhulakh":{"aff":45,"type":"protective","relation":"nephew, chieftain","note":"Raised him from childhood and maintains deep psychological influence while masking manipulation with maternal care","best":"Nurtured him as a darling boy and remains one of the two women he truly loves","worst":"Likely complicit in the deaths of his wives to keep him dependent on her and Yatul"},"Yatul":{"aff":60,"type":"platonic","relation":"sister, co-conspirator","note":"Schemes together to eliminate threats to their shared influence over Mauhulakh and Narzulbur","best":"United as the two women Mauhulakh truly loves and depends upon","worst":"Clashes over methods; Yatul pushes for ruthlessness while Bolar refuses to harm pregnant women"},"Urog":{"aff":55,"type":"protective","relation":"niece, ward","note":"Raised her after her mother died in childbirth; genuinely considers her a good, loyal child","best":"Held her as an infant and raised her with maternal care","worst":"Her mother''s death under Bolar''s care as midwife was likely not accidental"},"Dushnamub":{"aff":55,"type":"protective","relation":"nephew, ward","note":"Raised him after his mother died in childbirth; genuinely considers him a good, loyal child","best":"Held him as an infant and raised him with maternal care","worst":"His mother''s death under Bolar''s care as midwife was likely not accidental"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bolfrida_brandy-mug', '{"Faryl Atheron":{"aff":45,"type":"professional","relation":"employee","note":"Values his work but routinely dismisses his practical warnings with misplaced optimism","best":"Engages eagerly with him about farming techniques and regional agriculture","worst":"Ignores his sound advice about permafrost and fire salts, leading to failed experiments"},"Windhelm Merchants":{"aff":30,"type":"transactional","relation":"trading partners","note":"Regular buyers of her wheat and snowberries, maintaining positive business ties"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bolgeir_bearclaw', '{"Jarl Elisif the Fair":{"aff":85,"type":"protective","relation":"housecarl","note":"Sworn protector who never leaves her side and voices practical concerns for her safety","best":"She told him his loyalty comforts her","worst":"When she makes decisions that put her at risk despite his warnings"},"Falk Firebeard":{"aff":45,"type":"professional","relation":"fellow advisor","note":"Directs inquiries to Falk as steward; cooperative working relationship"},"General Tullius":{"aff":-25,"type":"suspicious","relation":"Imperial general","note":"Questions whether Tullius has Elisif''s best interests at heart; resents conscription of Solitude''s guards","worst":"Lost five guardsmen to Tullius''s conscription"},"Solitude Guards":{"aff":55,"type":"protective","relation":"overseer","note":"Reports guard losses and advocates for adequate staffing to protect the city"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bolli', '{"Nivenor":{"aff":35,"type":"estranged","relation":"wife","note":"Marriage strained by opposing values and mutual infidelity","best":"Calling her a gorgeous creature and life''s mystery","worst":"Her disapproval of his charity and her unfaithfulness"},"Haelga":{"aff":10,"type":"ex","relation":"former lover","note":"One-night affair he deeply regrets and wants forgotten","worst":"Being confronted with the Mark of Dibella and the shame of the affair"},"Maramal":{"aff":55,"type":"mentor","relation":"spiritual advisor","note":"Provides religious guidance at the Temple of Mara","best":"Learning compassion and charity through Maramal''s teachings"},"Svana Far-Shield":{"aff":5,"type":"suspicious","relation":"secret-holder","note":"Knows of his affair with Haelga and used it as leverage","worst":"Being confronted about his infidelity through her investigation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bolund', '{"Solaf":{"aff":45,"type":"familial","relation":"brother and business partner","note":"They live and work together, but Bolund resents Solaf''s refusal to leave Falkreath and fight","best":"Running the lumber mill and store together as family","worst":"Arguing about staying in Falkreath instead of taking back Nord land"},"Valga Vinicia":{"aff":-55,"type":"contempt","relation":"despised innkeeper","note":"Considers her a gossip and troublemaker","worst":"Calling her a gossip and troublemaker to anyone who will listen"},"Narri":{"aff":-35,"type":"dismissive","relation":"serving girl he insults","note":"Calls her ''gossip'' and treats her with consistent rudeness","worst":"Refusing to stop calling her gossip even when she threatens to let him die of thirst"},"Lod":{"aff":-30,"type":"contempt","relation":"mocked farmer","note":"Openly mocks and disrespects him","worst":"Calling him the worst farmer in the hold"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bor', '{"Mauhulakh":{"aff":45,"type":"professional","relation":"chief","note":"Serves the chief through her dedicated mining work at Gloombound Mine"},"Dushnamub":{"aff":35,"type":"platonic","relation":"fellow miner","note":"Works alongside in the ebony mines"},"Yatul":{"aff":50,"type":"mentor","relation":"wise woman","note":"Provides spiritual guidance connected to Malacath devotion"}}')
