INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('borgakh_the_steel_heart', '{"Chief Larak":{"aff":55,"type":"familial","relation":"father and chief","note":"Respects him deeply but feels trapped by his traditional expectations for her marriage","worst":"Being promised away to a distant chief she has never met"},"Unnamed Distant Chief":{"aff":-25,"type":"estranged","relation":"betrothed","note":"Arranged marriage she has never looked forward to, now feels like a cage","worst":"Realizing her coming of age means being traded for goods to a stranger"},"Mor Khazgur":{"aff":40,"type":"platonic","relation":"tribe","note":"Fellow tribespeople who respect her position as the chief''s daughter","best":"Years of training alongside stronghold warriors"},"Malacath":{"aff":65,"type":"admirer","relation":"patron deity","note":"Draws strength from his teachings about meeting one''s fate","best":"Finding resolve in Malacath''s wisdom when facing her uncertain future"}}')
