INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('borgny', '{"Leigelf":{"aff":35,"type":"professional","relation":"supervisor","note":"Appreciates Borgny''s dedication but worries about his compulsive behavior","best":"Recognized as one of the mine''s most productive workers","worst":"Concern over Borgny''s refusal to rest or eat"},"Beitild":{"aff":20,"type":"transactional","relation":"employer","note":"Values his productivity but keeps interactions strictly professional"}}')
