INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('borkul_the_beast', '{"Madanach":{"aff":75,"type":"protective","relation":"bodyguard","note":"Serves as personal guard to the King in Rags with unwavering loyalty","best":"Chosen as Madanach''s personal bodyguard in recognition of his strength"},"Forsworn":{"aff":65,"type":"platonic","relation":"comrade","note":"Shares their cause, seeing parallels between Forsworn and Orcish persecution","best":"Shouting ''The Reach belongs to the Forsworn!'' during the escape"},"Mine Guards":{"aff":-70,"type":"enemy","relation":"jailers","note":"Mutual distrust and contempt born from years of imprisonment","worst":"Twelve years imprisoned under their watch"},"Cidhna Mine Prisoners":{"aff":10,"type":"contempt","relation":"subordinates","note":"Maintains dominance as the toughest prisoner through intimidation"}}')
