INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('borri', '{"Arngeir":{"aff":75,"type":"platonic","relation":"fellow Greybeard","note":"Brother in the order who serves as its speaker and public voice"},"Wulfgar":{"aff":75,"type":"platonic","relation":"brother Greybeard","note":"Fellow master of the Voice, one of only two level 100 monks alongside Borri"},"Einarth":{"aff":75,"type":"platonic","relation":"fellow Greybeard","note":"Longtime companion in meditation and study at High Hrothgar"},"Paarthurnax":{"aff":90,"type":"student","relation":"master","note":"Revered ancient dragon who guides the Greybeards from the summit","best":"Receiving wisdom from Paarthurnax atop the Throat of the World"},"Dragonborn":{"aff":55,"type":"mentor","relation":"student","note":"Promising student he helps test and train in the Way of the Voice","best":"Teaching the word of Whirlwind Sprint during the Way of the Voice"}}')
