INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('borvir', '{"Rundi":{"aff":65,"type":"familial","relation":"twin brother","note":"Research partner sharing passion for frost-magic mead brewing, though they rarely agreed on anything","best":"Establishing their joint research site at Journeyman''s Nook","worst":"Frequent disagreements despite shared goals and twin bond"},"Phinis Gestor":{"aff":25,"type":"professional","relation":"former instructor","note":"Disapproved of their mead research, calling it a waste of magical potential","worst":"Dismissed their frost-magic brewing work as a waste"},"Arch-Mage":{"aff":75,"type":"patron","relation":"supporter","note":"Allowed their unconventional research to proceed despite faculty skepticism","best":"Supported their frost-magic mead research when others dismissed it"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bothela', '{"Muiri":{"aff":65,"type":"mentor","relation":"assistant and friend","note":"Runs the Hag''s Cure together; Bothela offers worldly wisdom and guidance"},"Odvan":{"aff":85,"type":"familial","relation":"grandson","note":"Imprisoned in Cidhna Mine; Bothela risks Forsworn entanglement to help him","worst":"Grandson trapped in Cidhna Mine"},"Silver-Blood Family":{"aff":-60,"type":"rival","relation":"oppressors","note":"Yngvar shakes her down for coins; Betrid demands potions fueling Thonar''s ambitions"},"Yngvar the Singer":{"aff":-55,"type":"enemy","relation":"enforcer","note":"Silver-Blood brute who extorts coins from her every few days"},"Nana Ildene":{"aff":40,"type":"platonic","relation":"fellow conspirator","note":"Exchanges notes with Bothela regarding Forsworn activities and Odvan''s situation"},"Forsworn":{"aff":30,"type":"estranged","relation":"former associates","note":"Lost many friends and kin; maintains discrete sympathies while heartbroken by their cause","worst":"So many friends and kin lost trying to rebuild a past that was over"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('boti', '{"Jofthor":{"aff":55,"type":"romantic","relation":"husband","note":"Farming partner who frequently disagrees about their daughter''s future","worst":"Arguments over whether to let Fastred follow her heart"},"Fastred":{"aff":85,"type":"protective","relation":"daughter","note":"Wants her happy even if it means leaving Ivarstead","best":"Secretly supporting her romance with Bassianus"},"Bassianus Axius":{"aff":45,"type":"protective","relation":"daughter''s suitor","note":"Secretly supports his courtship and promises to shield him from Jofthor"},"Greybeards":{"aff":15,"type":"suspicious","relation":"customer","note":"Supplies them food but questions what they have ever done for Ivarstead","worst":"Frightening thunder-like sounds from the monastery with no rain"},"Wylandriah":{"aff":65,"type":"platonic","relation":"friend","note":"Dear friend who visits Fellstar Farm"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bottar', '{"Sond":{"aff":85,"type":"platonic","relation":"close friend and traveling companion","note":"They roam Skyrim''s wilderness together, with Sond handling social interactions while Bottar follows loyally","best":"Exploring hidden paths and discovering locations like Deep Folk Crossing side by side","worst":"Facing the dangers of the wilderness alone if ever separated from Sond"}}')
