INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bouncer', '{"Cragslane Cavern Operators":{"aff":45,"type":"professional","relation":"employer","note":"Steady employment as muscle; loyal so long as the gold flows"},"Fellow Bandits":{"aff":25,"type":"professional","relation":"colleagues","note":"Working relationship with other Cragslane guards"},"Riften Guard":{"aff":-65,"type":"enemy","relation":"law enforcement","note":"Actively avoids detection; will fight to protect the ring''s secrecy","worst":"Constant threat of raids shutting down the operation"},"Local Criminals":{"aff":20,"type":"transactional","relation":"informants","note":"Maintains connections for early warning of potential raids"}}')
ON CONFLICT (npc_name) DO UPDATE
