INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bounty_collector', '{"Imperial Legion":{"aff":20,"type":"professional","relation":"former employer","note":"Left the Legion to pursue freelance bounty collection but retains military skills and discipline"},"Hold Guards":{"aff":35,"type":"transactional","relation":"informants","note":"Guards tip him off about high-value bounties; mutually beneficial arrangement","best":"A guard''s timely tip led to a lucrative 3000-gold bounty capture"},"Jarl''s Stewards":{"aff":25,"type":"transactional","relation":"business contacts","note":"Handles bounty verification and payment processing, always taking his 20% cut"},"Criminal Underground":{"aff":-65,"type":"enemy","relation":"adversaries","note":"Mutual distrust and occasional violent encounters with those he hunts","worst":"Ambushed by smugglers who recognized him as the one who collected their associate"}}')
