INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bradyn', '{"Ralis Sedarys":{"aff":15,"type":"professional","relation":"employer","note":"Hired Bradyn for the Kolbjorn Barrow excavation where he ultimately died"},"Kolbjorn Miners":{"aff":35,"type":"platonic","relation":"fellow workers","note":"Labored alongside other miners in the dangerous Nordic ruins"}}')
