INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('braig', '{"Aethra":{"aff":95,"type":"familial","relation":"daughter","note":"Executed after pleading to take his place; her memory haunts him daily","worst":"Forced to watch her head roll off the block"},"Madanach":{"aff":-10,"type":"suspicious","relation":"fellow prisoner","note":"A single conversation with Madanach led to his implication in the Forsworn Uprising","worst":"One conversation was enough to destroy his family"},"Duach":{"aff":45,"type":"platonic","relation":"fellow prisoner","note":"Shares anti-Nord sentiments and prison camaraderie","best":"Some day, brother. Some day."},"Grisvar":{"aff":15,"type":"transactional","relation":"skooma source","note":"Prison acquaintance involved in skooma trade"},"Nords":{"aff":-90,"type":"enemy","relation":"oppressors","note":"Blames them collectively for his daughter''s execution and his decades of imprisonment","worst":"They executed Aethra and forced him to watch"}}')
ON CONFLICT (npc_name) DO UPDATE
