INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('braith', '{"Amren":{"aff":-15,"type":"estranged","relation":"father","note":"Emotionally distant father preoccupied with his lost sword","best":"Calls her ''blossom'' and engages briefly when she asks to squire","worst":"Deflects her questions about boys back to her dismissive mother"},"Saffir":{"aff":-30,"type":"estranged","relation":"mother","note":"Neglectful mother absorbed in books who constantly dismisses her","worst":"Repeatedly told ''Not now, Braith'' without even looking up"},"Lars Battle-Born":{"aff":35,"type":"crush","relation":"bullying target","note":"Bullies him relentlessly but secretly harbors feelings for him","best":"Secretly wishes to be closer to him","worst":"Threatens to bloody his nose and lip if he doesn''t pay her"},"Mila Valentia":{"aff":15,"type":"platonic","relation":"playmate","note":"Occasional playmate in Whiterun streets"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bralsa_drel', '{"Geldis Sadri":{"aff":-15,"type":"estranged","relation":"innkeeper","note":"Banned her from the Retching Netch due to her drinking, though she desperately wants back in","worst":"Being kicked out of the only cornerclub in town"},"Rirns Llervu":{"aff":20,"type":"platonic","relation":"fellow beggar","note":"Share the Abandoned Building as homeless Dunmer, both unable to help each other"},"Councilor Morvayn":{"aff":50,"type":"grateful","relation":"benefactor","note":"Allowed Bralsa and Rirns to live in the abandoned building despite their poverty","best":"Being given shelter when she had lost everything"},"Crescius":{"aff":40,"type":"admirer","relation":"fellow miner","note":"Respects his mining instincts and believes the town would have been spared if they had listened to him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brand-shei', '{"Argonian Foster Parents":{"aff":80,"type":"familial","relation":"adoptive parents","note":"Rescued and raised him in Black Marsh with genuine love","best":"Being welcomed into their family as an orphaned infant"},"Brynjolf":{"aff":-60,"type":"enemy","relation":"Thieves Guild antagonist","note":"Brynjolf runs scams targeting him and ultimately frames him for theft","worst":"Being framed for Madesi''s stolen ring and arrested"},"Haelga":{"aff":10,"type":"transactional","relation":"landlord","note":"Permanent resident at Haelga''s Bunkhouse"},"House Telvanni":{"aff":40,"type":"curious","relation":"ancestral house","note":"Unaware of his true birthright as the last heir","best":"Discovering clues connecting him to his noble heritage"},"Madesi":{"aff":-10,"type":"suspicious","relation":"fellow vendor","note":"Madesi accused him of theft after the framing incident","worst":"Madesi reporting the planted ring to the guards"},"Thieves Guild":{"aff":-70,"type":"enemy","relation":"target of Guild schemes","note":"Holds their ire for his suspicion of their activities","worst":"Being set up and imprisoned through their conspiracy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brandish', '{"Bandit Chief":{"aff":35,"type":"transactional","relation":"employer","note":"Mutually beneficial arrangement providing magical support in exchange for autonomy and library access"},"Fort Neugrad Bandits":{"aff":15,"type":"contempt","relation":"pawns","note":"Views them as useful but inferior tools for his own purposes"},"College of Winterhold":{"aff":-40,"type":"estranged","relation":"former institution","note":"Left after becoming disillusioned with rigid structures and research limitations","worst":"Constrained and stifled by institutional restrictions on magical research"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brelas', '{"Malborn":{"aff":45,"type":"platonic","relation":"traveling companion","note":"Fellow escapee from the Thalmor Embassy; fled together to Morrowind","best":"Escaped the Embassy together"},"Erikur":{"aff":-85,"type":"enemy","relation":"harasser","note":"Noble who made unwanted advances then falsely accused her to Elenwen","worst":"Had her thrown into the Embassy dungeons after she refused him"},"Elenwen":{"aff":-65,"type":"fearful","relation":"former employer","note":"Ambassador who dismissed her pleas of innocence and sent her to interrogation","worst":"Ignored her innocence and ordered her taken to Master Rulindil"},"Thalmor":{"aff":-75,"type":"fearful","relation":"former employers","note":"Oppressive regime she served under duress; now hunting her after escape","worst":"Imprisoned and pursued her after she fled"},"Etienne Rarnis":{"aff":15,"type":"platonic","relation":"fellow prisoner","note":"Shared a cell in the Embassy dungeons briefly"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brelyna_maryon', '{"J''zargo":{"aff":25,"type":"rival","relation":"academic rival","note":"Fellow student whose competitiveness grates on her"},"Onmund":{"aff":45,"type":"platonic","relation":"study partner","note":"Classmate she occasionally studies with, one of the few she tolerates"},"House Telvanni":{"aff":30,"type":"familial","relation":"ancestral house","note":"Proud of the legacy but burdened by its expectations","worst":"A lifetime of pressure to be great before she even chose her own path"},"Tolfdir":{"aff":55,"type":"mentor","relation":"primary mentor","note":"Respectful but reserved toward her most trusted teacher"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brenuin', '{"Heimskr":{"aff":-20,"type":"dismissive","relation":"reluctant audience","note":"Finds his Talos preaching insufferable but endures it for warmth near the Gildergreen","worst":"Wish he''d just shut up"},"Ysolda":{"aff":-10,"type":"transactional","relation":"charity target","note":"Contentious begging dynamic; she refuses coin knowing he''ll buy drink"},"Anoriath":{"aff":5,"type":"transactional","relation":"charity target","note":"Tolerates his browsing and begging with mild patience"},"Carlotta Valentia":{"aff":15,"type":"transactional","relation":"charity source","note":"Harsh on the surface but secretly saves him leftovers; he calls her heart of Mara","best":"She said I could have what''s left over tomorrow"},"Hulda":{"aff":-5,"type":"suspicious","relation":"innkeeper","note":"Harbors the Argonian Ale he covets; he schemes to steal from her stock"},"Lucia":{"aff":45,"type":"protective","relation":"fellow beggar","note":"Shows the orphan rare kindness and advice; she says he''s the only one nice to her","best":"Giving the girl what guidance I can"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('breya', '{"Roots":{"aff":20,"type":"transactional","relation":"employer","note":"Hired her for the Lexicon heist; she followed but grew increasingly wary of his obsession","best":"Promised significant payment for completing the job","worst":"Rushed ahead ignoring her warning, leading to his doom"},"Drennen":{"aff":45,"type":"platonic","relation":"teammate","note":"Bonded over shared caution about the ruins; she called out when he fled","best":"Validated her concerns and shared her wariness of the dangers","worst":"Abandoned the group when the dangers became overwhelming"},"Fathoms":{"aff":-25,"type":"rival","relation":"antagonistic teammate","note":"Constantly dismissed her concerns and called her a fool; friction throughout the expedition","worst":"Called her a fool and dismissed her warnings at every turn"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('briehl', '{"Maramal":{"aff":70,"type":"mentor","relation":"superior and mentor","note":"Respected priest who guided Briehl into Mara''s service","best":"Earned his position as acolyte under Maramal''s guidance"},"Dinya Balu":{"aff":55,"type":"professional","relation":"fellow servant of Mara","note":"Works under Dinya Balu and assists her with temple duties"},"Mara":{"aff":95,"type":"fanatical","relation":"patron goddess","note":"Devoted his life to Mara''s service after experiencing her blessing","best":"Received Mara''s blessing during personal hardship in his youth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brina_merilis', '{"Horik Halfhand":{"aff":85,"type":"protective","relation":"lifelong companion","note":"Former subordinate who remains devoted; shares daily routines and deep mutual trust","best":"Horik''s hidden grin when she became Jarl"},"Skald the Elder":{"aff":-50,"type":"rival","relation":"political rival","note":"Stormcloak-supporting Jarl who resents her Imperial presence in Dawnstar","worst":"Public heated argument outside the White Hall"},"Imperial Legion":{"aff":75,"type":"professional","relation":"retired legate","note":"Served with distinction in the Great War; loyal despite acknowledging the Empire''s problems","best":"Rising to legate through successful campaigns"},"Dawnstar Citizens":{"aff":45,"type":"protective","relation":"protector","note":"Respected by Imperial-leaning populace; committed to their safety and order","worst":"Unable to secure adequate defenses against dragon attacks"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('britte', '{"Lemkil":{"aff":-35,"type":"estranged","relation":"father","note":"Blames his daughters for their mother''s death and shows them no affection","worst":"Called useless and blamed for mother''s death in childbirth"},"Sissel":{"aff":-50,"type":"rival","relation":"twin sister","note":"Dominates and bullies Sissel relentlessly, unconsciously mimicking their father''s hostility","best":"Born just five minutes apart, sharing their first moments together","worst":"Spends twelve hours every day chasing and tormenting her sister"},"Jouane Manette":{"aff":-25,"type":"jealous","relation":"Sissel''s teacher","note":"Resents that the mage teaches Sissel but shows no interest in her","worst":"Excluded from lessons while Sissel receives attention and knowledge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brother_verulus', '{"Thongvor Silver-Blood":{"aff":-55,"type":"rival","relation":"accuser","note":"Thongvor suspects him of desecrating Nord ancestors and demands access to the Hall of the Dead","worst":"Publicly accused of hiding Imperial crimes behind closed doors"},"Jarl Igmund":{"aff":30,"type":"professional","relation":"superior","note":"Jarl who oversees his position and ordered the Hall closed during the crisis"},"Eola":{"aff":-85,"type":"enemy","relation":"desecrator","note":"Cannibal who fed on the honored dead under his care","worst":"Discovered the dead had been eaten, flesh chewed off and bones snapped for marrow"},"Priests of Arkay":{"aff":55,"type":"platonic","relation":"fellow clergy","note":"Maintains correspondence with fellow priests of the order"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brunwulf_free-winter', '{"Malthyr Elenil":{"aff":55,"type":"protective","relation":"Dunmer advocate","note":"Malthyr seeks Brunwulf''s help improving conditions in the Gray Quarter","best":"Agreed to speak to Ulfric on the Dunmer''s behalf despite slim odds"},"Ulfric Stormcloak":{"aff":-65,"type":"rival","relation":"political opponent","note":"Opposes Ulfric''s Nord-first policies and prejudice against outsiders","worst":"Knows Ulfric will never trust anyone who isn''t a Nord"},"Rolff Stone-Fist":{"aff":-55,"type":"contempt","relation":"racist antagonist","note":"Openly opposes Rolff''s bigoted behavior toward Dunmer and Argonians"},"Angrenor Once-Honored":{"aff":-40,"type":"contempt","relation":"bigoted Nord","note":"Opposes his prejudiced views alongside Rolff Stone-Fist"},"Imperial Legion":{"aff":60,"type":"grateful","relation":"former allegiance","note":"Served with distinction in the Great War; becomes Jarl if Imperials take Windhelm"},"Argonian Assemblage":{"aff":50,"type":"protective","relation":"protected workers","note":"Advocates for better conditions for Argonian dock workers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brutius', '{"Bandit Accomplices":{"aff":35,"type":"professional","relation":"criminal partners","note":"Coordinates ambushes with them using his fishing contest ruse"},"Hold Guards":{"aff":-25,"type":"suspicious","relation":"avoided authorities","note":"Keeps his distance to prevent detection of his criminal operation"},"Player":{"aff":-60,"type":"betrayed","relation":"ambush target","note":"Lures with fishing contest then attacks alongside accomplices","worst":"Revealed the fishing contest was a deadly trap"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bryling', '{"Falk Firebeard":{"aff":85,"type":"romantic","relation":"secret lover","note":"Their relationship must remain hidden to protect Falk''s position as steward","best":"Dreaming of a future together after the war ends","worst":"Constant fear that Erikur will discover them and force Falk''s resignation"},"Erikur":{"aff":-45,"type":"rival","relation":"political rival","note":"Fellow Thane who would exploit knowledge of her secret relationship to gain influence over the Jarl","worst":"Knowing he would force Falk to resign and bend Elisif to his will"},"Sybille Stentor":{"aff":-30,"type":"suspicious","relation":"court wizard","note":"Subtly threatens to expose the secret relationship with mocking insinuations","worst":"Implying their private meetings are not court business"},"Jarl Elisif":{"aff":55,"type":"professional","relation":"liege lord","note":"Serves loyally as Thane and advisor in the Blue Palace"},"Pactur":{"aff":40,"type":"professional","relation":"mine overseer","note":"Manages Rockwallow Mine and delivers reports on operations","best":"Receiving word that the mine and its people are safe"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('brynjolf', '{"Mercer Frey":{"aff":-85,"type":"betrayed","relation":"former mentor and Guildmaster","note":"Served loyally as second-in-command until Mercer''s treachery against the Guild was revealed","worst":"Discovered Mercer had been stealing from the Guild and murdered Gallus"},"Maven Black-Briar":{"aff":45,"type":"patron","relation":"business associate and Guild patron","note":"Maintains a mutually beneficial professional relationship with the Guild''s most powerful ally in Riften"},"Delvin Mallory":{"aff":65,"type":"platonic","relation":"close friend and fellow Guild member","note":"Long-standing friendship built on years of working together in the Guild"},"Vex":{"aff":45,"type":"professional","relation":"fellow Guild officer","note":"Respected colleague despite occasional friction over Guild operations"},"Madesi":{"aff":-25,"type":"rival","relation":"marketplace competitor","note":"Public rivalry as fellow merchants; Madesi openly doubts Brynjolf''s elixirs are real"},"Karliah":{"aff":55,"type":"platonic","relation":"trusted ally","note":"Initially distrusted her as Gallus''s suspected murderer, later became allies after Mercer''s betrayal was exposed","best":"Fought alongside her to avenge the Guild and stop Mercer in Irkngthand"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bujold_the_unworthy', '{"Kuvar":{"aff":50,"type":"romantic","relation":"husband","note":"Married but strained by shared shame and tension over when to retake the hall","best":"Still believes in her leadership when others doubt","worst":"Openly challenges her indecision in front of the warriors"},"Thirsk Warriors":{"aff":45,"type":"professional","relation":"followers","note":"Loyal but demoralized exiles who still look to her despite the disgrace"},"Rieklings":{"aff":-85,"type":"enemy","relation":"invaders","note":"Overran Thirsk during her negligent leadership and stole their home","worst":"The night she fought alongside them at the Beast Stone, unaware"},"Hrothmund the Red":{"aff":75,"type":"awed","relation":"legendary founder","note":"Desperately seeks his posthumous blessing to validate her worthiness as leader","best":"Imagining earning his approval and casting off her shameful title"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('bulfrek', '{"Jarl Skald the Elder":{"aff":-65,"type":"contempt","relation":"master","note":"Trapped in ancestral servitude; Skald openly mocks and demeans him","worst":"Skald laughed in his face when he asked to enlist, calling him good for a laugh"},"Stormcloaks":{"aff":70,"type":"admirer","relation":"aspiring recruit","note":"Yearns to join the rebellion to earn an honorable death and reach Sovngarde","best":"Dreams of proving himself a true Nordic warrior in their ranks"},"Imperial Legion":{"aff":-50,"type":"enemy","relation":"hated foe","note":"Despises the Imperials as obstacles to Nordic freedom and his personal glory","worst":"Exiled from Dawnstar when the Legion took the Pale"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cairine', '{"Vingalmo":{"aff":75,"type":"servant","relation":"vampire superior","note":"Orchestrated her transformation; she serves as his eyes and ears in Markarth","best":"receiving the gift of vampirism from him"},"Omluag":{"aff":15,"type":"platonic","relation":"former coworker","note":"Remembers her from the smelter; one of few who acknowledges her existence"},"Volkihar Vampires":{"aff":65,"type":"fanatical","relation":"clan","note":"Her new supernatural family; serves with dark devotion after transformation","best":"being embraced into the clan"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('calcelmo', '{"Aicantar":{"aff":55,"type":"familial","relation":"nephew and research assistant","note":"Works closely together on Dwemer research and museum oversight"},"Faleen":{"aff":75,"type":"crush","relation":"romantic interest","note":"Harbors deep feelings but struggles to express them due to academic awkwardness","best":"Finally sharing meals together after being encouraged to pursue her"},"Ondolemar":{"aff":25,"type":"professional","relation":"fellow High Elf in Markarth","note":"Thalmor-aligned acquaintance with purely professional interactions"},"Igmund":{"aff":35,"type":"professional","relation":"Jarl and employer","note":"Serves as court mage in exchange for access to Dwemer ruins"}}')
ON CONFLICT (npc_name) DO UPDATE
