INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('calder', '{"Jarl Ulfric Stormcloak":{"aff":45,"type":"professional","relation":"jarl","note":"Serves Ulfric''s interests indirectly through protecting the Thane of Windhelm"},"Jorleif":{"aff":40,"type":"professional","relation":"steward","note":"Appointed Calder to the housecarl position","best":"Selected Calder for the prestigious housecarl appointment"},"Windhelm City Guard":{"aff":35,"type":"platonic","relation":"former comrades","note":"Maintains connections with former colleagues from his guard service days"},"Thane of Windhelm":{"aff":75,"type":"protective","relation":"housecarl","note":"Sworn to protect and serve with his life; waits loyally at Hjerim","best":"Pledged his life and service upon appointment"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('calixto_corrium', '{"Lucilla Corrium":{"aff":95,"type":"obsessed","relation":"sister","note":"Her death shattered his sanity and drives his necromantic murder spree to resurrect her.","best":"Traveling Tamriel together collecting curiosities and seeking adventures.","worst":"Her passing, which plunged him into irreversible madness."},"Viola Giordano":{"aff":-55,"type":"suspicious","relation":"threat to secrecy","note":"She investigates the Butcher killings and could expose him."},"Susanna the Wicked":{"aff":-90,"type":"neutral","relation":"murder victim","note":"Killed as a component in his necromantic resurrection ritual."},"Nilsine Shatter-Shield":{"aff":-80,"type":"neutral","relation":"intended victim","note":"Targeted as another ritual sacrifice for the Butcher''s spree."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('camilla_valerius', '{"Lucan Valerius":{"aff":72,"type":"familial","relation":"brother and business partner","note":"Protective bond tempered by frustration with his caution; she challenges him when action is needed","best":"Building the Riverwood Trader into a cornerstone of local commerce together","worst":"Arguing over his refusal to pursue the thieves who stole the Golden Claw"},"Faendal":{"aff":28,"type":"platonic","relation":"admirer","note":"Maintains patient but firm professional boundaries with the Wood Elf suitor","worst":"Receiving a forged letter meant to manipulate her feelings"},"Sven":{"aff":28,"type":"platonic","relation":"admirer","note":"Diplomatic toward the Nordic bard but keeps him at arm''s length romantically","worst":"Navigating the awkward love triangle without damaging local relationships"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('captain_aldis', '{"General Tullius":{"aff":65,"type":"professional","relation":"commanding officer","note":"Serves under Tullius as captain of the Solitude guards and Legion trainer"},"Legate Rikke":{"aff":55,"type":"professional","relation":"fellow Nord officer","note":"Fellow Nord serving the Imperial cause in Skyrim"},"Roggvir":{"aff":25,"type":"neutral","relation":"executed prisoner","note":"Called him a fine and honorable man but believed the execution was justified and necessary","worst":"Oversaw Roggvir''s execution at Solitude"},"Angeline Morrard":{"aff":30,"type":"pitying","relation":"bereaved mother to notify","note":"Knew her daughter''s fate but struggled to find the right time and place to tell her"},"Gorm":{"aff":45,"type":"platonic","relation":"old friend","note":"Corresponded before the war; considers Gorm''s current scheme impossible","best":"Maintained correspondence with Gorm before the war"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('captain_aquilius', '{"Aicantar":{"aff":40,"type":"professional","relation":"direct superior","note":"Follows orders with professional dedication but suggested informing Calcelmo when Aicantar did not","worst":"Overruled when suggesting they inform Master Calcelmo about the intrusion"},"Calcelmo":{"aff":55,"type":"professional","relation":"charge","note":"Respects his authority and advocates proper protocol regarding his research"},"Guard Subordinates":{"aff":30,"type":"professional","relation":"subordinates","note":"Commands firmly and coordinates their search efforts"},"Former Bandit Associates":{"aff":-20,"type":"estranged","relation":"former associates","note":"Distances himself from his outlaw past to maintain his legitimate position"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('captain_avidius', '{"Emperor Titus Mede II":{"aff":90,"type":"protective","relation":"charge","note":"One of the Emperor''s most trusted protectors aboard The Katariah","best":"Being selected for the Emperor''s personal security detail","worst":"Failing to prevent the Emperor''s assassination by the Dark Brotherhood"},"Commander Maro":{"aff":65,"type":"professional","relation":"commanding officer","note":"Superior officer in the Penitus Oculatus chain of command"},"Dark Brotherhood":{"aff":-95,"type":"nemesis","relation":"enemy assassins","note":"Deadly enemies of the Empire who infiltrated The Katariah to kill the Emperor","worst":"Their successful assassination of Emperor Titus Mede II under his watch"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('captain_hargar', '{"Jaree-Ra":{"aff":45,"type":"professional","relation":"co-conspirator","note":"Working together on a major raid scheme; Hargar will fight to protect him."},"Deeja":{"aff":35,"type":"professional","relation":"ally","note":"Trusted secondary contact through Jaree-Ra, cooperating on current operations."},"Blackblood Marauders":{"aff":60,"type":"protective","relation":"crew","note":"Fiercely loyal to his men; values their respect and maintains iron discipline."},"Ahtar":{"aff":-85,"type":"nemesis","relation":"pursuer","note":"Solitude''s executioner hunting him for escaping Castle Dour Dungeon.","worst":"Imprisoned in Castle Dour Dungeon and now hunted by the man seeking revenge for the escape."},"East Empire Company":{"aff":-70,"type":"enemy","relation":"raid target","note":"Primary target of piracy operations and sworn enemy of the Marauders."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('captain_lonely-gale', '{"Viola Giordano":{"aff":-25,"type":"dismissive","relation":"unwanted suitor","note":"Actively avoids her persistent romantic advances and nosy interference","worst":"Her relentless pursuit that won''t leave him alone"},"Brunwulf Free-Winter":{"aff":45,"type":"professional","relation":"potential employer","note":"Respected peer intended to serve as his steward if Ulfric is deposed"},"Niranye":{"aff":15,"type":"suspicious","relation":"marketplace acquaintance","note":"Rejects her business propositions, suspecting smuggling involvement","worst":"Her suggestion that his sailor associates engage in smuggling"},"Elda Early-Dawn":{"aff":25,"type":"platonic","relation":"innkeeper","note":"Friendly conversational partner at Candlehearth Hall who seeks his counsel"},"Deceased Wife and Family":{"aff":85,"type":"familial","relation":"lost family","note":"Lost them years ago; their memory still defines his emotional life","worst":"Their loss to unknown circumstances leaving him without purpose"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('captain_valmir', '{"Thalmor":{"aff":45,"type":"professional","relation":"covert agent","note":"Serves as operative seeking advancement through successful artifact retrieval","best":"Mission success would elevate his standing in the hierarchy"},"Player":{"aff":-15,"type":"transactional","relation":"manipulated asset","note":"Sends them into dangerous ruins while he waits in safety","worst":"Exposed as fraud when soldier catches him playing both sides"},"Imperial Legion":{"aff":-25,"type":"contempt","relation":"impersonated faction","note":"Wears their uniform as disguise to manipulate their soldiers"},"Stormcloaks":{"aff":-25,"type":"contempt","relation":"impersonated faction","note":"Wears their uniform as disguise to manipulate their soldiers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('captain_veleth', '{"Dreyla Alor":{"aff":78,"type":"romantic","relation":"secret lover","note":"Meets her daily at the Retching Netch; relationship kept hidden from public knowledge","best":"Quiet mornings together at the Netch away from duty''s demands","worst":"The strain of keeping their bond concealed from Raven Rock"},"Councilor Morvayn":{"aff":82,"type":"protective","relation":"primary protectee","note":"Specially chosen to guard Morvayn due to exceptional record and unwavering loyalty to House Redoran","best":"Being entrusted with the Councilor''s safety by House Redoran itself","worst":"The assassination plot that nearly succeeded in Served Cold"},"Second Councilor Arano":{"aff":55,"type":"professional","relation":"fellow protector of the Councilor","note":"Close working relationship coordinating security for Councilor Morvayn"},"Redoran Guard":{"aff":65,"type":"protective","relation":"subordinates","note":"Trains and leads them with stern but fair discipline; takes their welfare seriously","best":"Giving his men well-deserved rest after the ash spawn threat ended","worst":"Losing a guard to ash spawn at Old Attius Farm"},"House Redoran":{"aff":75,"type":"professional","relation":"sworn house","note":"Unwavering loyalty to the House that gave him purpose after the Red Mountain catastrophe"},"Ash Spawn":{"aff":-85,"type":"enemy","relation":"persistent threat","note":"Constant danger to Raven Rock; Veleth personally fights them on the front lines","worst":"Being nearly overwhelmed at Old Attius Farm and losing a guard to them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('captain_wayfinder', '{"Mother":{"aff":85,"type":"familial","relation":"mother","note":"Inherited the Sea Squall from her; strives to prove himself worthy of her legacy","best":"Learning navigation and starcharting aboard the Sea Squall together","worst":"Her unexpected death leaving him unprepared for command"},"Guthrum":{"aff":45,"type":"professional","relation":"crew member","note":"One of the few crew members who accepts his casual leadership style"},"Ravam Verethi":{"aff":-25,"type":"rival","relation":"disgruntled crew member","note":"Particularly bitter crewman who openly questions his authority and right to command","worst":"Openly mocking his inherited captaincy"},"College of Winterhold":{"aff":20,"type":"transactional","relation":"trading partner","note":"Business contact for alchemical ingredients; crew lost their void salts shipment","worst":"Crew losing the Fine-Cut Void Salts shipment"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('carlotta_valentia', '{"Mila Valentia":{"aff":95,"type":"familial","relation":"daughter","note":"Fiercely devoted to raising her alone; refuses to let any man come between them"},"Mikael":{"aff":-65,"type":"enemy","relation":"unwanted suitor","note":"Harasses her with persistent advances and vulgar boasts","worst":"His boasting at the Bannered Mare about conquering her like a true Nord conquers a harsh beast"},"Severio Pelagia":{"aff":45,"type":"professional","relation":"produce supplier","note":"Supplies most of her wares from his farm; reliable business partnership"},"Brenuin":{"aff":25,"type":"pitying","relation":"local beggar","note":"Occasionally gives him food out of kindness despite her own hardships"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cave_bear', '{"Lesser Bears":{"aff":-15,"type":"rival","relation":"subordinates","note":"Maintains dominance over regular bears that enter its territory"},"Spriggans":{"aff":35,"type":"platonic","relation":"ally","note":"Shares mutual respect and occasional alliance with these forest guardians"},"Hunters":{"aff":-75,"type":"enemy","relation":"intruders","note":"Viewed with hostile contempt as territorial invaders","worst":"Every incursion by armed mortals seeking its hide"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cedran', '{"Banning":{"aff":45,"type":"professional","relation":"stable assistant","note":"Trusted colleague whose loss would double Cedran''s workload","best":"Collaborating smoothly on stable operations and horse trading","worst":"Banning''s death leaving him to manage the stables alone"},"Forsworn":{"aff":5,"type":"suspicious","relation":"shared heritage","note":"Sympathizes with Breton grievances but refuses to aid criminal activity","worst":"Refused Madanach''s request for escape horses despite shared distrust of Nords"},"Jarl Igmund":{"aff":10,"type":"professional","relation":"ruling authority","note":"Operates stables under Imperial-aligned Jarl''s governance"},"Thongvor Silver-Blood":{"aff":-15,"type":"suspicious","relation":"ruling authority","note":"Doubts the Reach will fare well under Silver-Blood rule"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('celann', '{"Isran":{"aff":55,"type":"professional","relation":"commander and former colleague","note":"Rejoined the Dawnguard despite past disagreements over Isran''s extreme methods","best":"Isran reached out to recruit him for the reformed Dawnguard","worst":"Parted ways years ago over Isran''s harsh tactics"},"Durak":{"aff":50,"type":"professional","relation":"comrade","note":"Fellow senior Dawnguard member who fights alongside him defending Fort Dawnguard"},"Vigilants of Stendarr":{"aff":25,"type":"estranged","relation":"former order","note":"Left due to dissatisfaction with their methods but respects their intentions","best":"Shared purpose in opposing the undead","worst":"Their ineffectiveness forced him to seek a better way"},"Volkihar Vampires":{"aff":-85,"type":"enemy","relation":"sworn enemies","note":"Dedicated vampire hunter who stormed Castle Volkihar to destroy them","worst":"Vampire attack on Fort Dawnguard gate"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('challenger', '{"College of Winterhold":{"aff":-25,"type":"estranged","relation":"likely former student","note":"Probably expelled or left under duress due to aggressive behavior","worst":"Forced out for combative conduct"},"Court Wizards":{"aff":-15,"type":"rival","relation":"duel targets","note":"Views them as opponents to challenge and defeat to build reputation"},"Player":{"aff":-30,"type":"rival","relation":"challenged duelist","note":"Challenges any wizard to magical duel on sight","worst":"Becomes enraged when opponent ignores his dueling rules"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('champion_of_boethiah', '{"Boethiah":{"aff":-90,"type":"nemesis","relation":"former patron","note":"Rejected her after a moral awakening; she now seeks his death through her cultists and new champions","worst":"Knowing she will eventually send someone to kill him for his defiance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('chicken', '{"Other Chickens":{"aff":35,"type":"protective","relation":"claimed subjects","note":"Views them as loyal subjects awaiting their future overlord; refuses to harm them per peculiar code of honor"},"Local Farmers":{"aff":-15,"type":"contempt","relation":"unwitting pawns","note":"Sees farmers as easily manipulated tools for its grandiose schemes"},"Guards":{"aff":-35,"type":"rival","relation":"antagonists","note":"Constantly orchestrates chaos that guards fail to recognize as deliberate"},"Cats":{"aff":-55,"type":"enemy","relation":"natural enemy","note":"Considers cats constant threats and persistent obstacles to its plans"},"Dragons":{"aff":40,"type":"fanatical","relation":"claimed cousins","note":"Delusionally believes chickens are the true descendants of dragons due to shared reptilian ancestry"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('chief_burguk', '{"Shel":{"aff":85,"type":"romantic","relation":"favorite wife","note":"Openly favors and protects her from manual labor","best":"Promised to intervene when Gharol threatened to send Shel to the mines"},"Gharol":{"aff":35,"type":"romantic","relation":"forge-wife","note":"Dismissive of her jealousy toward Shel; values her smithing but not her demands","worst":"Shut down her challenge to replace Shel at the feast"},"Arob":{"aff":50,"type":"romantic","relation":"hunt-wife","note":"Functional marriage; she provides food for the stronghold"},"Murbul":{"aff":75,"type":"familial","relation":"mother","note":"Seeks her spiritual counsel regarding Malacath''s favor","best":"Murbul confirmed Malacath was pleased with their tribe"},"Nagrub":{"aff":55,"type":"familial","relation":"son","note":"Serves the stronghold"},"Ghorbash the Iron Hand":{"aff":60,"type":"familial","relation":"brother","note":"Fellow warrior of the stronghold"},"Lurbuk":{"aff":-30,"type":"estranged","relation":"estranged son","note":"Marked as rivals; would thank his killer","worst":"Lurbuk became a disgraced bard in Morthal instead of a proper Orc warrior"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('chief_larak', '{"Sharamph":{"aff":75,"type":"familial","relation":"mother","note":"Deeply respects his mother and the wise-woman''s spiritual guidance","best":"Sharamph declared Malacath was pleased with his strength"},"Shuftharz":{"aff":80,"type":"romantic","relation":"forge-wife","note":"Openly admires her craftsmanship and physical strength at the forge","best":"Praised her rippling muscles and smithing skill to her face"},"Borgakh the Steel Heart":{"aff":60,"type":"familial","relation":"daughter","note":"Father to the stronghold''s warrior daughter"},"Olur":{"aff":65,"type":"familial","relation":"son","note":"Proud of Olur''s forge work and intends to share Legion techniques with him","best":"Complimented his forging and offered to teach him Imperial military methods"},"Bagrak":{"aff":40,"type":"familial","relation":"sister","note":"Sister who remains at the stronghold but doubts he has fully proven himself as chief","worst":"Bagrak stated Larak has much to prove as chief"},"Imperial Legion":{"aff":30,"type":"neutral","relation":"former service","note":"Served in the Legion gaining combat experience, now maintains neutral relations"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('chief_mauhulakh', '{"Bolar":{"aff":65,"type":"familial","relation":"aunt and spiritual advisor","note":"Deeply dependent on her counsel; she and Yatul control when he may seek a new wife","best":"She reassured him the curse might be a sign of the gods'' love","worst":"She dismisses his need for children and a worthy mate"},"Yatul":{"aff":55,"type":"familial","relation":"aunt and caretaker","note":"Defers to her and Bolar''s judgment on personal matters; they decide when he is ready","best":"She said they just want him to be happy","worst":"She told him he is not ready for a new wife"},"Dushnamub":{"aff":45,"type":"familial","relation":"son","note":"Strained by Dushnamub''s suspicion of the aunts; Mauhulakh refuses to hear ill of them","worst":"Dushnamub implied his aunts'' midwifery may have caused the wives'' deaths"},"Urog":{"aff":20,"type":"estranged","relation":"daughter","note":"She blames him for her mother''s death and resents his perceived inaction as chief","worst":"Urog said his ill fortune means she has no mother and told him to stay out of the way"},"Galka":{"aff":75,"type":"romantic","relation":"deceased wife","note":"Still mourns her; her loss deeply affected him and Bolar","worst":"She died, another victim of the curse"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('chief_yamarz', '{"Atub":{"aff":-15,"type":"dismissive","relation":"wise woman","note":"Dismisses her counsel while she persists in trying to save the tribe from Malacath''s curse"},"Malacath":{"aff":-60,"type":"fearful","relation":"Daedric patron","note":"Cursed by Malacath for his weak leadership; publicly shamed as a pathetic weakling and embarrassment","worst":"Called a pathetic weakling and embarrassment before his entire tribe"},"Largashbur Tribe":{"aff":-20,"type":"contempt","relation":"his tribe","note":"Mutual distrust; tribe has lost faith in him while he shows them arrogance"},"Giants":{"aff":-75,"type":"enemy","relation":"invaders","note":"Defiled Malacath''s shrine and repeatedly attack the stronghold; Yamarz refuses to fight them"},"Player":{"aff":-45,"type":"betrayed","relation":"manipulated outsider","note":"Manipulates player into clearing path and killing the giant, then attempts to murder them to cover his cowardice","worst":"Attempted to kill the player after they killed the giant for him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('christer', '{"Fjola":{"aff":90,"type":"romantic","relation":"wife","note":"Abandoned his farm and spent months searching for her","best":"Their wedding day when he gave her the ring","worst":"She vanished during errands and never came home"},"Bandits of Mistwatch":{"aff":-70,"type":"enemy","relation":"perceived captors","note":"Believes they kidnapped Fjola and are ransoming captives","worst":"Their kidnappings began around when Fjola disappeared"},"The Last Dragonborn":{"aff":55,"type":"grateful","relation":"hired helper","note":"Pleads for help searching Mistwatch and offers coin reward","best":"Agreed to search for Fjola when no one else would"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cicero', '{"Night Mother":{"aff":100,"type":"fanatical","relation":"sacred charge","note":"Serves as her Keeper with absolute devotion, his entire identity built around her service","best":"Hearing her voice speak after years of silence","worst":"Any disrespect shown to her or her traditions"},"Astrid":{"aff":-70,"type":"rival","relation":"opposing faction leader","note":"Despises her rejection of traditional Dark Brotherhood ways and usurpation of the old hierarchy","worst":"Her abandonment of the Five Tenets and traditional Listener system"},"The Listener":{"aff":95,"type":"servant","relation":"devoted servant","note":"Absolute loyalty to whoever is proven as the true Listener","best":"Finally finding the anointed Listener after years of searching"},"Loreius":{"aff":-30,"type":"contempt","relation":"obstinate farmer","note":"Frustrated by his refusal to help fix the wagon wheel carrying the Night Mother","worst":"Being stranded with the Night Mother''s body due to his stubbornness"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cindiri_arano', '{"Adril Arano":{"aff":90,"type":"romantic","relation":"husband","note":"Deeply loves him and constantly fears for his safety due to his dangerous position","best":"Decades of devoted marriage and shared endurance through hardship","worst":"He refuses to leave Councilor Morvayn''s side and return to Blacklight with her"},"Lleril Morvayn":{"aff":25,"type":"professional","relation":"husband''s superior","note":"Maintains formal courtesy but resents that his presence keeps Adril in danger","worst":"His hold on Adril traps her in isolated Raven Rock far from Blacklight"},"Neloth":{"aff":-45,"type":"contempt","relation":"Telvanni wizard","note":"Refuses outright to work for him, disturbed by his rumored cruelty","worst":"He cut the heart out of his former apprentice"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('clinton_lylvieve', '{"Azzada Lylvieve":{"aff":70,"type":"familial","relation":"father","note":"Clinton looks up to his father but sometimes chafes at being told to stay out of adult matters","worst":"Told to mind his own business when asking about Olda and Lodvar"},"Michel Lylvieve":{"aff":75,"type":"familial","relation":"mother","note":"Supportive parent who encourages his daily activities"},"Julienne Lylvieve":{"aff":55,"type":"familial","relation":"sister","note":"Shares family life in Dragon Bridge"},"Lucky":{"aff":85,"type":"protective","relation":"pet goat","note":"Beloved companion who joins him on all his town patrols","best":"Patrolling the town together every day"},"Town Guards":{"aff":50,"type":"admirer","relation":"role models","note":"Clinton idolizes soldiers and guards, dreaming of becoming one himself"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('coldhearted_gravedigger', '{"Helgird":{"aff":25,"type":"professional","relation":"fellow caretaker of the dead","note":"Professional acquaintance who shares the same solemn trade in other cities"},"Priests of Arkay":{"aff":40,"type":"professional","relation":"religious overseers","note":"She views her funerary work as sacred duty aligned with Arkay''s domain"},"Windhelm Guards":{"aff":10,"type":"neutral","relation":"city guards","note":"Maintain respectful distance due to superstition about her occupation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('colette_marence', '{"Tolfdir":{"aff":65,"type":"professional","relation":"senior colleague","note":"One of the few colleagues who treats Restoration with proper respect","best":"He listens when she speaks about Restoration without dismissing it"},"Mirabelle Ervine":{"aff":35,"type":"professional","relation":"superior","note":"Maintains professional oversight; Colette likely feels scrutinized under her authority"},"Augur of Dunlain":{"aff":55,"type":"curious","relation":"deferred authority on Restoration","note":"Respects his mastery deeply but approaches with caution; refers advanced students to him","best":"Acknowledges his brilliance and inspired mastery of Restoration"},"College Faculty":{"aff":-25,"type":"suspicious","relation":"colleagues","note":"Perceives widespread dismissal and ridicule of Restoration as a legitimate school","worst":"Constantly anticipates criticism and feels blamed for speaking out of place"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('commander_caius', '{"Jarl Balgruuf the Greater":{"aff":80,"type":"protective","relation":"direct superior","note":"Unwavering loyalty; chose exile over serving Stormcloaks","best":"Appointed Commander of the Whiterun Guard","worst":"Exiled together when Stormcloaks seized Whiterun"},"Irileth":{"aff":55,"type":"professional","relation":"fellow protector of Whiterun","note":"Shares dedication to duty and loyalty to Balgruuf"},"Sinmir":{"aff":-65,"type":"rival","relation":"usurper","note":"Takes his position if Stormcloaks capture Whiterun","worst":"Stripped of rank and replaced by a Stormcloak sympathizer"},"Proventus Avenicci":{"aff":40,"type":"professional","relation":"administrative colleague","note":"Serve together in Whiterun''s governance under Balgruuf"},"Sabjorn":{"aff":-55,"type":"contempt","relation":"arrested meadery owner","note":"Was poisoned at Honningbrew and threw Sabjorn in irons","worst":"Drank poisoned Honningbrew Reserve and fell violently ill"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('commander_maro', '{"Gaius Maro":{"aff":95,"type":"familial","relation":"son","note":"Trained him personally for Penitus Oculatus service; his murder consumes Maro with grief and vengeance","best":"Sharing a final farewell before Gaius departed on his security inspection","worst":"Learning his son was assassinated by the Dark Brotherhood"},"Titus Mede II":{"aff":75,"type":"protective","relation":"sworn charge","note":"Duty-bound to protect the Emperor at all costs; his primary mission in Skyrim"},"Dark Brotherhood":{"aff":-100,"type":"nemesis","relation":"sworn enemy","note":"Destroyed their sanctuary in brutal retaliation for Gaius''s murder","worst":"Their assassination of his son Gaius"},"Penitus Oculatus Agents":{"aff":60,"type":"professional","relation":"subordinates","note":"Commands their loyalty and leads their operations in Skyrim"},"Astrid":{"aff":-30,"type":"transactional","relation":"informant","note":"She betrayed the Dark Brotherhood to him, but he reneged on their deal to destroy them all anyway"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('companion_ghost', '{"Ysgramor":{"aff":95,"type":"fanatical","relation":"liege","note":"Served in life as one of the Five Hundred Companions; guards his tomb eternally in death","best":"Earned the honor of burial beside Ysgramor after the war against the Snow Elves","worst":"Centuries of undeath have stripped away all memory save duty to him"},"Fellow Companion Ghosts":{"aff":60,"type":"familial","relation":"shield-siblings","note":"Bound together in eternal service, maintaining their vigil side by side"},"Frostbite Spiders":{"aff":0,"type":"neutral","relation":"co-inhabitants","note":"Unusual peaceful coexistence within the tomb; neither side attacks the other"},"Living Companions":{"aff":-40,"type":"suspicious","relation":"potential intruders","note":"Viewed as threats to the tomb''s sanctity despite shared heritage"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('conjurer', '{"Fellow Conjurers":{"aff":30,"type":"platonic","relation":"colleagues","note":"Loose alliance of secretive practitioners who occasionally share forbidden knowledge"},"College of Winterhold":{"aff":-50,"type":"rival","relation":"rival institution","note":"Rejected their structure and limitations; hostile over ethical disagreements","worst":"Cast out or left in disgust at their restrictive teachings"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"hunters","note":"Sworn enemies who actively hunt practitioners of Daedric magic","worst":"Ambushed and killed fellow conjurers in their lairs"},"Daedra":{"aff":10,"type":"transactional","relation":"bound servants","note":"Complex master-servant dynamic; summon and bind them yet risk corruption from prolonged contact","best":"Successfully bound a powerful atronach to their will","worst":"Nearly consumed by a Daedric entity losing control of a summoning"},"Local Populations":{"aff":-20,"type":"dismissive","relation":"common folk","note":"Viewed with disdain as inferior beings who cannot comprehend conjuration"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('conjurer_adept', '{"College of Winterhold":{"aff":-30,"type":"estranged","relation":"former institution","note":"Left due to ethical disagreements over conjuration research","worst":"Confrontation over forbidden conjuration practices"},"Fellow Conjurers":{"aff":40,"type":"professional","relation":"colleague network","note":"Loose network sharing knowledge and mutual protection","best":"Successful knowledge exchange on Daedric summoning"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"hunters","note":"Hostile encounters due to Daedric practices","worst":"Violent confrontation over Daedric summoning"},"Common Folk":{"aff":-45,"type":"contempt","relation":"locals","note":"Views non-magical people as inferior; feared by them in return","worst":"Being driven from settlements by fearful villagers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('constance_michel', '{"Grelod the Kind":{"aff":-55,"type":"fearful","relation":"oppressive headmistress","note":"Endures Grelod''s constant abuse to remain near and protect the children","worst":"Forced to sit silently while Grelod berates and beats the orphans"},"Orphaned Children":{"aff":85,"type":"protective","relation":"surrogate mother","note":"Dedicates her life to making the children feel safe and loved despite conditions","best":"Moments when a child smiles or finds comfort in her care"},"Maven Black-Briar":{"aff":15,"type":"transactional","relation":"distant benefactor","note":"Maven partially funds the orphanage; relationship is purely professional and distant"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('corpulus_vinius', '{"Sorex Vinius":{"aff":45,"type":"familial","relation":"son","note":"Tension over succession; Sorex is eager but ambivalent, and Corpulus refuses to retire","worst":"Heated arguments about who will run the Skeever and when"},"Minette Vinius":{"aff":50,"type":"familial","relation":"daughter","note":"Dismissive of her ambitions to run the inn despite her eagerness and aptitude","worst":"Told her running a bar is no job for a young lady"},"Faida":{"aff":65,"type":"familial","relation":"cousin","note":"Mutual respect as fellow tavern proprietors and kin","best":"Considers her one of his favorite girls in the family"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('corrupt_agent', '{"Commander Maro":{"aff":-35,"type":"betrayed","relation":"commander","note":"Maintains facade of loyalty while secretly undermining his organization","worst":"Decided to collaborate with Dark Brotherhood against Imperial interests"},"Dark Brotherhood":{"aff":40,"type":"transactional","relation":"collaborator","note":"Provides contracts and intelligence as recurring contact","best":"Established covert working relationship for pragmatic justice"},"Penitus Oculatus":{"aff":-20,"type":"contempt","relation":"employer","note":"Disillusioned with organization''s corruption, secretly works against it","worst":"Witnessed corruption that shattered faith in Imperial methods"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cosnach', '{"Lisbet":{"aff":15,"type":"professional","relation":"employer","note":"Tolerates his drinking only because his cousin is her assistant","worst":"Constantly complains about his drinking and threatens to fire him"},"Imedhnain":{"aff":50,"type":"familial","relation":"cousin","note":"Vouches for Cosnach to keep his position at the trading company"},"Degaine":{"aff":20,"type":"platonic","relation":"drinking companion","note":"Fellow drunk at the Silver-Blood Inn who bickers with him over coin"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('courier', '{"Bandits":{"aff":-45,"type":"enemy","relation":"road adversaries","note":"Bandits frequently target couriers on Skyrim''s dangerous roads","worst":"Ambushed on a lonely stretch of road, letters scattered to the wind"},"Jarl Courts":{"aff":25,"type":"transactional","relation":"official clients","note":"Regular business delivering official communications for hold governments"},"Merchants":{"aff":20,"type":"transactional","relation":"frequent clients","note":"Merchants rely on couriers for business correspondence across holds"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cow', '{"Local Farmer":{"aff":60,"type":"protective","relation":"caretaker","note":"Depends on farmer for daily care, shelter, and survival in Skyrim''s harsh climate","best":"Gentle hands during milking sessions and fresh hay in winter"},"Giants":{"aff":5,"type":"curious","relation":"ceremonial recipients","note":"Cows painted with blue symbols are offered to giants as peace offerings to maintain harmony","worst":"Being chosen as the offering means leaving the only life and herd it has known"},"Farm Guard Dogs":{"aff":45,"type":"protective","relation":"herd guardians","note":"Dogs watch over the herd and alert to approaching threats or storms"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('crescius_caerellius', '{"Aphia Velothi":{"aff":95,"type":"romantic","relation":"wife","note":"Saved him from depression and gave him renewed purpose","best":"Meeting Aphia pulled him out of bitter hermitude"},"Gratian Caerellius":{"aff":75,"type":"familial","relation":"great-grandfather","note":"Obsessed with uncovering the truth about his mysterious death","worst":"Gratian''s death dismissed as a simple tunnel collapse"},"East Empire Company":{"aff":-50,"type":"rival","relation":"former mine operators","note":"Resents their dismissal of his theories and abandonment of the mine","worst":"Declared the mine dry and covered up Gratian''s true cause of death"},"Councilor Morvayn":{"aff":45,"type":"professional","relation":"councilor","note":"Appointed Crescius as mine foreman after the mine reopened"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cryomancer', '{"College of Winterhold":{"aff":-55,"type":"estranged","relation":"former institution","note":"Left due to frustration with their cautious approach to destructive magic","worst":"Abandoned the College after their restrictions stifled frost magic research"},"Fellow Warlocks":{"aff":30,"type":"professional","relation":"covenant allies","note":"Cautious allies in the secretive warlock covenant united by unrestricted magical pursuit"},"Vigilants of Stendarr":{"aff":-90,"type":"enemy","relation":"persecutors","note":"Sworn enemies who hunt dangerous magic users","worst":"Live in constant threat of being hunted and eliminated for practicing forbidden arts"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cultist', '{"Miraak":{"aff":95,"type":"fanatical","relation":"supreme master","note":"Mind and former identity erased and replaced with absolute devotion to Miraak''s cause","best":"Serving Miraak''s will without question","worst":"Failing to fulfill his commands"},"Last Dragonborn":{"aff":-90,"type":"enemy","relation":"false pretender","note":"Sent to hunt and kill the Last Dragonborn for challenging Miraak''s divine right"},"Temple Priests":{"aff":55,"type":"servant","relation":"superior officers","note":"Higher-ranking cultists who direct activities and enforce Miraak''s will"},"Citizens of Solstheim":{"aff":-35,"type":"contempt","relation":"lesser beings","note":"Former fellow citizens now treated with dismissive superiority and hostility"},"Fellow Cultists":{"aff":15,"type":"neutral","relation":"extensions of will","note":"Not seen as individuals, merely instruments of Miraak''s purpose"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cultist_adept', '{"Miraak":{"aff":95,"type":"fanatical","relation":"devoted worshipper","note":"Experienced visions confirming Miraak''s divine purpose; willing to sacrifice everything for his return","best":"receiving visions confirming Miraak''s divinity during shrine construction","worst":"the long centuries of their master''s absence and imprisonment"},"Cult of Miraak":{"aff":55,"type":"professional","relation":"adept and spiritual guide","note":"Holds authority over initiates while serving under higher-ranking members"},"Skaal":{"aff":-55,"type":"contempt","relation":"unbelievers","note":"Views them with contempt for resisting Miraak''s influence on Solstheim"},"Dragonborn":{"aff":-80,"type":"enemy","relation":"heretical pretender","note":"Considers them a false Dragonborn whose existence threatens Miraak''s divine purpose","worst":"learning of another claiming the title of Dragonborn"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('curwe', '{"Vantus Loreius":{"aff":65,"type":"romantic","relation":"husband","note":"Farming partner with whom she shares a generally positive but occasionally contentious relationship","best":"Debating agricultural plans and herb garden expansion together","worst":"Disagreements over farm space allocation and her visits to the boneyard"},"Cicero":{"aff":-35,"type":"suspicious","relation":"stranded jester","note":"Disruptive stranger whose wagon trouble threatens the farm''s stability","worst":"If betrayed to the guards, he will murder her and Vantus"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('cynric_endell', '{"Brynjolf":{"aff":45,"type":"professional","relation":"guild colleague","note":"Joined the Guild shortly after him and respects his leadership","best":"Recognizes Brynjolf''s leadership as the right fit for the Guild"},"Vex":{"aff":30,"type":"professional","relation":"guild superior","note":"Accepts her authority as Guild Third despite his longer tenure"},"Mercer Frey":{"aff":-55,"type":"betrayed","relation":"former guildmaster","note":"Was loyal until Mercer''s treachery was revealed","worst":"Discovered Mercer had been betraying the Guild all along"},"Karliah":{"aff":35,"type":"professional","relation":"guild sister","note":"Initially believed her a traitor, came to trust her after the truth emerged","best":"Accepted her innocence once Mercer''s betrayal was proven"},"Delvin Mallory":{"aff":45,"type":"professional","relation":"guild contact","note":"Knew Delvin before joining the Guild; his introduction to the organization"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dagny', '{"Jarl Balgruuf the Greater":{"aff":80,"type":"familial","relation":"father","note":"Indulgent father whose promises she eagerly invokes to get her way","best":"Father promised her a new dress from Solitude","worst":"Father won''t let her go see the captured dragon"},"Frothar":{"aff":30,"type":"familial","relation":"elder brother","note":"Constantly clashes with him over her spoiled demands","worst":"He called her a spoiled baby when she complained about her dress"},"Nelkir":{"aff":45,"type":"familial","relation":"younger brother","note":"Shares the children''s quarters with him in Dragonsreach"},"Palace Staff":{"aff":-15,"type":"contempt","relation":"servants","note":"Treats them as beneath her and issues peremptory demands","worst":"Mistakes newcomers for servants and orders her meat rare"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dagur', '{"Haran":{"aff":85,"type":"romantic","relation":"wife","note":"Loving wife and co-proprietor who shares the burden of running the inn","best":"Standing together against Korir''s complaints about their customers"},"Eirid":{"aff":90,"type":"protective","relation":"daughter","note":"Strives to protect and provide a stable future for his young daughter"},"Ranmir":{"aff":45,"type":"protective","relation":"patron","note":"Genuinely wants to help the drunk recover and find closure about Isabelle","best":"Remembering Ranmir as happy and outgoing before his loss","worst":"Watching him waste away in alcoholism day after day"},"Nelacar":{"aff":20,"type":"professional","relation":"tenant","note":"Tolerates the former College mage as a permanent resident despite local prejudices","worst":"Nelacar''s magical experiment filled the inn with a horrible smell"},"College of Winterhold":{"aff":35,"type":"professional","relation":"business partner","note":"Values College visitors as crucial customers and refuses to share local prejudices"},"Korir":{"aff":-15,"type":"rival","relation":"local leader","note":"Korir complains about College visitors at the inn, creating ongoing tension"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('daighre', '{"Erith":{"aff":90,"type":"familial","relation":"daughter","note":"Fiercely protective single mother raising her alone","best":"Sharing tender memories of her father with her","worst":"Having to scold her for bothering Skaggi"},"Skaggi Scar-Face":{"aff":45,"type":"professional","relation":"employer","note":"Mutual respect between hardworking miner and fair boss","best":"Being told she works hard and he''s glad she stayed"},"Late Husband":{"aff":75,"type":"romantic","relation":"late husband","note":"Keeps his memory alive for their daughter","best":"Remembering his soft face and silly grin","worst":"Losing him and facing life alone with Erith"},"Pavo":{"aff":35,"type":"platonic","relation":"fellow miner","note":"Sympathizes after the Forsworn attack on Kolskeggr"},"Gat":{"aff":35,"type":"platonic","relation":"fellow miner","note":"Sympathizes after the Forsworn attack on Kolskeggr"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dalan_merchad', '{"Kjar":{"aff":35,"type":"professional","relation":"captain","note":"Serves under Captain Kjar aboard The North Wind, maintaining loyalty and duties despite frustration with the ship''s permanent dockage"},"Windhelm":{"aff":-70,"type":"contempt","relation":"resented city","note":"Despises Windhelm and finds it depressing, preferring the ship''s deck to the city streets","worst":"Trapped indefinitely in a city he loathes with no prospect of leaving"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('danica_pure-spring', '{"Ahlam":{"aff":65,"type":"platonic","relation":"temple assistant","note":"Trusted colleague who shares healing duties and late-night conversations at the temple"},"Maurice Jondrelle":{"aff":45,"type":"platonic","relation":"fellow pilgrim","note":"Shares deep reverence for the Gildergreen and Kynareth''s sacred symbol"},"Jarl Balgruuf":{"aff":50,"type":"professional","relation":"patron","note":"Respected authority who supports the temple''s work in Whiterun"},"Heimskr":{"aff":15,"type":"neutral","relation":"fellow priest","note":"Tolerates his presence despite serving different deities and his loud public preaching"},"Andurs":{"aff":25,"type":"professional","relation":"fellow clergy","note":"Cordial professional relationship with the priest of Arkay at the Hall of the Dead"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dark_brotherhood_assassin', '{"Dark Brotherhood":{"aff":85,"type":"professional","relation":"elite member","note":"Rose through ranks to earn the coveted Ancient Shrouded Armor, indicating senior standing and deep commitment","best":"Trusted with the Ancient Shrouded Armor, a mark of highest distinction"},"Sithis":{"aff":95,"type":"fanatical","relation":"devoted servant","note":"Embodied unwavering dedication to the Dread Father as core to his identity and purpose"},"Night Mother":{"aff":80,"type":"fanatical","relation":"faithful follower","note":"Served under her guidance as all Brotherhood members do, honoring her as the spiritual mother of the order"},"Hag''s End Witches":{"aff":-65,"type":"enemy","relation":"possible killers","note":"Likely adversaries who may have contributed to his mysterious demise at Hag''s End","worst":"Met his end in their remote fortress under unknown circumstances"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dawnguard_novice_hakar', '{"Isran":{"aff":-15,"type":"professional","relation":"commanding officer","note":"Demoted Hakar to courier duty after repeated combat failures","worst":"Being stripped of real duties and reduced to restocking caches"},"Dawnguard":{"aff":-25,"type":"estranged","relation":"former faction","note":"Failed as a hunter and ultimately deserted, abandoning all equipment","worst":"Being viewed as a liability by fellow recruits"},"Vampires":{"aff":-100,"type":"fearful","relation":"mortal enemies","note":"Inspire paralyzing terror that broke his nerve entirely","worst":"Being ambushed by vampires on the road to Valtheim Towers"},"Player":{"aff":50,"type":"grateful","relation":"rescuer","note":"Saved him from vampire attack; he surrendered his gear and fled","best":"Being pulled from certain death by a stranger"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dawnguard_scout', '{"Isran":{"aff":70,"type":"professional","relation":"commander","note":"Respected leader who provides mission directives and embodies the Dawnguard''s purpose"},"Volkihar Clan":{"aff":-95,"type":"nemesis","relation":"sworn enemies","note":"Constant surveillance target; hatred fueled by personal loss to vampire attacks","worst":"Lost family members to vampire attacks"},"Fellow Dawnguard Scouts":{"aff":45,"type":"professional","relation":"comrades","note":"Loose intelligence-sharing network bound by shared purpose"},"Local hunters and trappers":{"aff":15,"type":"transactional","relation":"informants","note":"Occasional sources of intelligence on vampire movements"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dawnguard_vampire_hunter', '{"Isran":{"aff":70,"type":"professional","relation":"commanding officer","note":"Issues his hunting orders and leads the Dawnguard he serves with zeal"},"Gunmar":{"aff":45,"type":"professional","relation":"weapons trainer","note":"Maintains his weaponry and provides crossbow instruction"},"Sorine Jurard":{"aff":40,"type":"professional","relation":"equipment supplier","note":"Supplies enhanced crossbow bolts and technical innovations for hunts"},"Lord Harkon":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"His vampires are specifically marked for elimination","worst":"Lost his family to a vampire attack in Cyrodiil"},"Player":{"aff":-85,"type":"enemy","relation":"hunted target","note":"Carries orders to exact justice if the player accepted Harkon''s vampiric gift","worst":"Sent to kill the player for betraying the Dawnguard to Volkihar"}}')
