INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dawnstar_guard', '{"Jarl Skald":{"aff":75,"type":"servant","relation":"liege lord","note":"Serves with unquestioning loyalty as direct superior and leader of Dawnstar"},"Captain Wayfinder":{"aff":65,"type":"professional","relation":"commanding officer","note":"Direct commanding officer who oversees guard duties"},"Fellow Guards":{"aff":70,"type":"platonic","relation":"brotherhood in arms","note":"Strong bonds forged through shared duty and harsh northern conditions"},"Frida":{"aff":50,"type":"professional","relation":"alchemist and healer","note":"Respected despite her grouchiness for providing healing potions to the guard","best":"Whips up cures that keep the guard on their feet"},"Local Miners":{"aff":40,"type":"protective","relation":"citizens under protection","note":"Professional duty to protect their livelihood and safety"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('daynas_valen', '{"Icerunner Adventurers":{"aff":-40,"type":"transactional","relation":"manipulated pawns","note":"Invited them on his expedition intending to use them as fodder for traps and draugr","worst":"All died together in Folgunthur when his plan went awry"},"Bravil Collector":{"aff":-80,"type":"contempt","relation":"murder victim","note":"Killed and robbed them to obtain the ivory dragon claw after a decade of searching","worst":"Murdered in Bravil for the claw he needed to enter Folgunthur"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dealer', '{"Venarus Vulpin":{"aff":30,"type":"professional","relation":"overseer","note":"Works under his direction distributing skooma for the vampire operation"},"Redwater Den Vampires":{"aff":20,"type":"professional","relation":"allies","note":"Complicit in their scheme to dose skooma and create vampire thralls","best":"Partnership provides steady income and protection","worst":"Listed as vampire thrall faction, suggesting limited autonomy"},"Regular Customers":{"aff":-15,"type":"transactional","relation":"marks","note":"Manipulates their addiction and desperation while leading them to become thralls"}}')
