INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('death_hound', '{"Volkihar Clan":{"aff":85,"type":"servant","relation":"masters and creators","note":"Bred through dark vampire magic to serve as loyal guardians of the clan''s strongholds","best":"Patrolling Castle Volkihar corridors alongside vampire masters"},"CuSith":{"aff":60,"type":"platonic","relation":"pack mate","note":"Notable Death Hound serving the Volkihar clan"},"Garmr":{"aff":60,"type":"platonic","relation":"pack mate","note":"Notable Death Hound serving the Volkihar clan"},"Werewolves":{"aff":-70,"type":"fearful","relation":"natural enemies","note":"Recognized as enemies despite fearing their presence"}}')
ON CONFLICT (npc_name) DO UPDATE
