INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('deeja', '{"Jaree-Ra":{"aff":78,"type":"familial","relation":"brother","note":"Coordinates criminal activities with him; he tempers her impatience","best":"Planning the Hammerfell steel heist together"},"Gulum-Ei":{"aff":72,"type":"familial","relation":"brother","note":"His East Empire Company insider knowledge aids their schemes","best":"Cargo that got lost thanks to his tips"},"Blackbloods":{"aff":80,"type":"professional","relation":"member","note":"Serves with fierce loyalty as enforcer and assassin","best":"Taking the whole whale instead of half a fin"},"Solitude Guards":{"aff":-55,"type":"enemy","relation":"adversaries","worst":"Always sniffing around the docks"},"Greta":{"aff":-25,"type":"dismissive","relation":"nuisance","note":"Threatened her when she begged for work","worst":"Wouldn''t stop begging for a job"},"Player":{"aff":-65,"type":"enemy","relation":"betrayed tool","note":"Used them to run the Icerunner aground then attempted to kill them","worst":"Expected a share of the loot after doing our dirty work"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('deekus', '{"Dark Brotherhood":{"aff":-80,"type":"fearful","relation":"marked target","note":"Former assassin now marked for death; actively avoids detection by them","worst":"Contract placed on his life"},"Local Bandits":{"aff":-40,"type":"rival","relation":"hostile competitors","note":"Compete for shipwreck loot along the northern coast"},"Sailors":{"aff":15,"type":"transactional","relation":"trading partners","note":"Cautious trade for basic supplies"}}')
ON CONFLICT (npc_name) DO UPDATE
