INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('deep-in-his-cups', '{"Sam Guevenne":{"aff":20,"type":"platonic","relation":"drinking companion","note":"Caroused together before Sam dared him to infiltrate a bandit camp","best":"Wild night of drinking together","worst":"Sent him on a near-fatal dare"},"Dragonborn":{"aff":30,"type":"transactional","relation":"debtor","note":"Claims 10,000 gold debt from a drunken promise made during a shared night of revelry","best":"Paid the promised gold fairly","worst":"Refused to honor the debt after he risked his life"},"Bandits":{"aff":-65,"type":"enemy","relation":"adversaries","note":"Infiltrated their camp and stole the leader''s hat on a dare","worst":"Nearly killed him during the infiltration"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('deer', '{"Spriggans":{"aff":45,"type":"protective","relation":"natural ally","note":"Spriggans can command deer to defend sacred groves, and deer become hostile under their influence"},"Herd":{"aff":80,"type":"familial","relation":"herd members","note":"Form close-knit family groups for mutual protection and survival"},"Hunters":{"aff":-85,"type":"fearful","relation":"primary predator","note":"Hunted relentlessly for venison, hides, and antlers","worst":"Fleeing from arrows and poisoned slow-effect bolts"},"Wolves":{"aff":-75,"type":"enemy","relation":"natural predator","note":"Wolves regularly hunt deer as prey"},"Bears":{"aff":-55,"type":"fearful","relation":"dangerous predator","note":"Actively avoided as a significant threat"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('degaine', '{"Mulush gro-Shugurz":{"aff":-55,"type":"estranged","relation":"former employer","note":"Degaine was crippled working the smelter under him and received no support","worst":"Broke bones at the smelter and was left with nothing"},"Cosnach":{"aff":20,"type":"platonic","relation":"drinking companion","note":"Fellow drunk who shares evening mead at the Silver-Blood Inn"},"Hogni Red-Arm":{"aff":-35,"type":"contempt","relation":"target of insults","note":"Degaine routinely mocks him, calling him Hogni Fat-Arm","worst":"Publicly taunts and belittles him at the market stalls"},"Temple of Dibella Priestesses":{"aff":-75,"type":"enemy","relation":"attempted theft target","note":"Caught trying to steal their golden statue; still schemes to take it","worst":"Was caught and thrown out attempting to rob the temple"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('delacourt', '{"Valga Vinicia":{"aff":50,"type":"professional","relation":"employer","note":"Owns Dead Man''s Drink and appreciates his ability to draw customers"},"Narri":{"aff":40,"type":"platonic","relation":"co-worker","note":"Fellow employee at the tavern who enjoys his performances"},"Jarl Siddgeir":{"aff":25,"type":"professional","relation":"patron","note":"Occasionally performs at the Jarl''s longhouse during special occasions"},"Bards College":{"aff":55,"type":"professional","relation":"alma mater","note":"Trained there and hopes to earn recognition for preserving local history","best":"Graduated after pursuing his passion for music"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('delphine', '{"Esbern":{"aff":85,"type":"platonic","relation":"fellow Blade","note":"One of the few people she fully trusts; shared decades of survival and purpose","best":"Reuniting at Riverwood after years believing she was the last Blade","worst":"Knowing the Thalmor nearly broke him before she could find him"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"persecutors","note":"Sworn enemies who destroyed the Blades and hunted survivors for thirty years","worst":"Surviving the purge that killed nearly everyone she served with"},"Orgnar":{"aff":35,"type":"professional","relation":"employee","note":"Loyal barkeeper unaware of her true identity; she keeps him at careful distance","best":"Leaving him the inn when she departed for Sky Haven Temple"},"Greybeards":{"aff":-45,"type":"contempt","relation":"ideological opponents","note":"Views their passive dragon philosophy as cowardice that endangers Tamriel"},"Paarthurnax":{"aff":-80,"type":"enemy","relation":"ancient dragon","note":"Considers him an unrepentant monster regardless of his current actions; demands his death","worst":"Discovering the Greybeards sheltered a dragon responsible for countless deaths"},"Farengar Secret-Fire":{"aff":20,"type":"transactional","relation":"contact","note":"Useful for dragon research but never trusted with her true identity"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('delvin_mallory', '{"Brynjolf":{"aff":70,"type":"platonic","relation":"trusted colleague","note":"Fellow senior Guild member who weathered the Guild''s decline together","best":"Standing side by side through the Guild''s darkest years","worst":"Watching the Guild crumble around them both"},"Astrid":{"aff":65,"type":"platonic","relation":"old friend","note":"Longstanding friendship bridging the Thieves Guild and Dark Brotherhood","best":"Maintaining a trusted cross-faction friendship for decades"},"Vex":{"aff":55,"type":"professional","relation":"colleague","note":"Close colleague who shares special jobs duties in the Guild"},"Mercer Frey":{"aff":30,"type":"professional","relation":"guild master","note":"Serves under Mercer but trusts him less than he should"},"Maven Black-Briar":{"aff":40,"type":"transactional","relation":"patron","note":"Important business associate whose patronage sustains the Guild"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dengeir_of_stuhn', '{"Siddgeir":{"aff":-60,"type":"estranged","relation":"nephew","note":"Views him as an Imperial puppet installed through conspiracy to replace him as Jarl","worst":"Forced from the throne so Siddgeir could take his place"},"Thadgeir":{"aff":50,"type":"familial","relation":"brother","note":"Shares his home in Falkreath"},"Tekla":{"aff":20,"type":"suspicious","relation":"servant","note":"Loyal servant and confidant, yet suspected of passing information to Siddgeir"},"Ulfric Stormcloak":{"aff":55,"type":"professional","relation":"ally","note":"Pragmatic ally in the fight against Imperial influence, despite knowing his flaws","best":"Shares cause for Skyrim''s independence from the Empire"},"Imperial Legion":{"aff":-80,"type":"enemy","relation":"adversary","note":"Sees Imperial plots everywhere and believes they engineered his removal from power","worst":"Bribed Falkreath nobles to orchestrate his downfall as Jarl"},"Vighar":{"aff":-70,"type":"enemy","relation":"ancestor","note":"Risen vampire ancestor who must be destroyed to protect Falkreath"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('deor_woodcutter', '{"Yrsa":{"aff":88,"type":"romantic","relation":"wife","note":"Beloved partner whose presence softens his stoic demeanor","best":"Bringing her small gifts to see her smile","worst":"Worrying her when he stays vigilant late into the night"},"Fanari Strong-Voice":{"aff":45,"type":"professional","relation":"village leader","note":"Respects her authority but frustrated by her cautious inaction when danger threatens","best":"Working together for the village''s daily needs","worst":"She dismissed his instinct about Baldor''s disappearance"},"Baldor Iron-Shaper":{"aff":65,"type":"protective","relation":"fellow Skaal","note":"Valued community member whose kidnapping Deor sensed before anyone believed him","best":"Seeing him safely returned to the village","worst":"Spotting elves dragging something through the woods but thinking nothing of it at first"},"Storn Crag-Strider":{"aff":78,"type":"mentor","relation":"spiritual leader","note":"Deeply respected guide whose loss left him questioning how the Skaal will endure","best":"Receiving wisdom and spiritual counsel over the years","worst":"Watching Storn sacrifice himself and feeling helpless"},"Frea":{"aff":55,"type":"platonic","relation":"fellow Skaal","note":"Offered quiet condolences after Storn''s death","best":"Standing together in grief to honor her father","worst":"Having no words to ease her pain after Storn''s sacrifice"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('derkeethus', '{"Sondas Drenim":{"aff":65,"type":"platonic","relation":"close friend","note":"Fellow miner who expressed worry during his disappearance"},"Hrefna":{"aff":70,"type":"protective","relation":"mentor figure","note":"Used to take her diving deep in the river","best":"Taking Hrefna diving in the river"},"Falmer":{"aff":-95,"type":"nemesis","relation":"captors","note":"Held him captive in Darkwater Pass after he swam too close to the falls","worst":"Being captured and imprisoned by Falmer"},"Player":{"aff":75,"type":"grateful","relation":"rescuer","note":"Rescued him from Falmer captivity; can become loyal follower or spouse","best":"Being freed from the Falmer cave"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dervenin', '{"Sheogorath":{"aff":95,"type":"fanatical","relation":"devoted servant","note":"Desperately loyal despite years of abandonment and dismissal","best":"Reunited with master in Pelagius Wing after long search","worst":"Abandoned and left to wander alone for years while master vacationed"},"Blue Palace Staff":{"aff":-15,"type":"suspicious","relation":"gatekeepers","note":"Prevent his access to Pelagius Wing where his master resides"},"Citizens of Solitude":{"aff":-10,"type":"dismissive","relation":"bystanders","note":"Ignore or avoid him due to his apparent madness and begging"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('desperate_gambler', '{"Creditors":{"aff":-85,"type":"fearful","relation":"debtors","note":"Dangerous individuals he owes substantial debts to and wants killed via the Dark Brotherhood","worst":"Borrowed money he could never repay and now lives in terror of their retribution"},"Gambling Den Operators":{"aff":-40,"type":"estranged","relation":"banned patron","note":"Banned from gambling dens across Skyrim due to unpaid losses"},"Dark Brotherhood":{"aff":35,"type":"client","relation":"contract giver","note":"Performed the Black Sacrament seeking assassins to eliminate his creditors","best":"The Night Mother answered his desperate prayer"},"Fellow Merchants":{"aff":-20,"type":"estranged","relation":"former associates","note":"Former business associates in Windhelm who now shun him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dexion_evicus', '{"Malkus":{"aff":-85,"type":"enemy","relation":"captor","note":"Vampire who imprisoned and attempted to enthrall him at Forebears'' Holdout","worst":"Being forced to submit and call Malkus master after prolonged mental struggle"},"Order of Moth Priests":{"aff":75,"type":"professional","relation":"order","note":"Dedicated his life to the order''s sacred duty of studying Elder Scrolls","best":"Decades of scholarly purpose at White-Gold Tower"},"Imperial Guards":{"aff":20,"type":"professional","relation":"former escorts","note":"Assigned to protect him on his journey to Skyrim but failed to prevent his capture"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dinya_balu', '{"Maramal":{"aff":95,"type":"romantic","relation":"husband","note":"Beloved husband and fellow priest of Mara; together they serve as caretakers of the Temple of Mara in Riften","best":"Establishing their shared life and ministry at the Temple of Mara"},"Mara":{"aff":100,"type":"fanatical","relation":"patron goddess","note":"Deeply devoted priestess who receives prophetic visions from the goddess regarding matters of love","best":"Being graced with divine visions that guide her mission of spreading love"},"Maven Black-Briar":{"aff":15,"type":"suspicious","relation":"wary neighbor","note":"Maintains a cautious distance while remaining outwardly respectful of Riften''s de facto power"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dirge', '{"Maul":{"aff":55,"type":"familial","relation":"brother","note":"Dirge mentions Maul''s advice about his big mouth, suggesting a close bond despite their separate career paths"},"Vekel the Man":{"aff":65,"type":"protective","relation":"employer","note":"Fiercely loyal to Vekel, frequently threatening those who cause trouble for him","best":"Smashing the head of the last person who made trouble for Vekel"},"Tonilia":{"aff":45,"type":"professional","relation":"fellow guild member","note":"One of the few people Dirge is cooperative and friendly with, willingly doing favors for her","best":"Agreeing to handle the guard nosing around the meadery for her"},"Thieves Guild":{"aff":20,"type":"professional","relation":"member","note":"Loyal enough to serve but treats even fellow members with suspicion and hostility","worst":"Threatening to smash skulls of guild members who step out of line"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dishonored_skald', '{"Viarmo":{"aff":25,"type":"professional","relation":"dean","note":"Maintains facade of loyal instructor while concealing his darker affiliations"},"Dark Brotherhood":{"aff":55,"type":"servant","relation":"associate","note":"Joined after they executed his revenge; now serves as occasional contract giver","best":"Delivered vengeance upon the bandits who murdered his family","worst":"The Black Sacramament that bound him to a life of shadows"},"Night Mother":{"aff":70,"type":"fanatical","relation":"spiritual guide","note":"Spiritual anchor since discovering the Brotherhood; carries A Kiss, Sweet Mother"},"Local Guards":{"aff":-15,"type":"suspicious","relation":"watchers","note":"They sense something amiss but cannot prove wrongdoing"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dog', '{"Player Character":{"aff":90,"type":"protective","relation":"master","note":"Devoted companion who judges character before offering loyalty","best":"Chose to follow and stay by their side","worst":"Being dismissed or separated from master"},"Children":{"aff":85,"type":"protective","relation":"family","note":"Especially gentle and watchful with young ones in the household"},"Hostile Wildlife":{"aff":-70,"type":"enemy","relation":"natural adversaries","note":"Wolves and bears are instinctive threats to be driven off","worst":"Vicious encounters in the wilderness"}}')
