SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('donnel', '{"Silver-Blood Family":{"aff":85,"type":"servant","relation":"covert enforcer","note":"Unwavering loyalty as their hidden protector and assassin","best":"Taken in and given purpose by the family decades ago","worst":"Any failure to eliminate threats to their interests"},"Thonar Silver-Blood":{"aff":80,"type":"servant","relation":"direct superior","note":"Sworn protector who reveals his true self on Thonar''s behalf","worst":"Forced to break cover when Thonar is questioned"},"Nana Ildene":{"aff":55,"type":"professional","relation":"fellow conspirator","note":"Fellow cleaner and co-conspirator protecting Silver-Blood interests","best":"Fighting side by side when their cover is blown"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('doorman', '{"Redwater Den":{"aff":55,"type":"professional","relation":"enforcer","note":"Unwaveringly loyal to his employers, viewing his role as a well-paying job he takes seriously"},"Local Bandits":{"aff":15,"type":"estranged","relation":"former associates","note":"Keeps former Rift bandit contacts at arm''s length since joining the Den"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dorian', '{"Captain Safia":{"aff":50,"type":"professional","relation":"captain","note":"Respects her authority but has learned to stay out of her way after only a few weeks aboard","worst":"Quickly learned to avoid crossing her"},"Red Wave Crew":{"aff":75,"type":"protective","relation":"crew family","note":"Considers fellow pirates family and will defend them with his life","best":"Found belonging among the crew despite his scholarly nature","worst":"Would kill anyone who trifles with his crew"},"Adonato Leotelli":{"aff":55,"type":"admirer","relation":"admired author","note":"Has read several of his works and hopes to meet him someday in Windhelm","best":"Reading his works brought peace and inspiration at sea"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dorthe', '{"Alvor":{"aff":90,"type":"mentor","relation":"father and mentor","note":"Encourages her blacksmithing dreams despite initially wanting a son","best":"He told her she could be the greatest blacksmith Skyrim has ever seen"},"Sigrid":{"aff":45,"type":"familial","relation":"mother","note":"Constant tension over Dorthe''s refusal to conform to traditional gender roles","worst":"Enduring her mother''s endless complaints about not being girlish enough"},"Hadvar":{"aff":75,"type":"familial","relation":"cousin","note":"Imperial soldier whose visits bring excitement and tales of adventure","best":"Listening wide-eyed to his stories of dragons and warfare"},"Frodnar":{"aff":80,"type":"platonic","relation":"best friend","note":"Playmates despite their families'' opposing civil war allegiances","best":"Outrunning him at tag and getting Stump to chase him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('drahff', '{"Hewnon Black-Skeever":{"aff":15,"type":"professional","relation":"partner in crime","note":"Manipulates and belittles Hewnon while relying on him for muscle","worst":"Hewnon''s constant doubts and complaints about living in a sewer"},"Thieves Guild":{"aff":-35,"type":"rival","relation":"parasitic opportunist","note":"Exploits their reputation while operating outside their authority","worst":"Fears they would skin them alive if they discovered his scheme"},"Riften Guards":{"aff":-50,"type":"enemy","relation":"hunted criminal","note":"Avoids their attention while operating in the Ratway"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('drascua', '{"Forsworn Followers":{"aff":65,"type":"protective","relation":"leader and matriarch","note":"Commands the Forsworn at Dead Crone Rock with fierce territorial authority."},"Other Forsworn Leaders":{"aff":40,"type":"professional","relation":"allied camp leaders","note":"Maintains alliances with fellow Forsworn camps across the Reach."},"Mehrunes Dagon":{"aff":25,"type":"servant","relation":"keeper of the Razor","note":"Serves as one of the Keepers of Mehrunes'' Razor, likely through dark pacts."},"Local Nords":{"aff":-85,"type":"enemy","relation":"invaders of the Reach","note":"Views all Nords as occupiers of Forsworn ancestral lands.","worst":"Nord encroachment on Reach territories"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dravin_llanith', '{"Synda Llanith":{"aff":90,"type":"romantic","relation":"wife","note":"Deeply protective of her, constantly worries about her safety on the isolated road","best":"Building a new life together at Merryfair Farm after fleeing Morrowind","worst":"The constant fear of losing her to bandits or wild animals"},"Riften Thieves":{"aff":-80,"type":"enemy","relation":"thieves","note":"Stole his irreplaceable family heirloom bow and all their coin","worst":"Returning from buying supplies to find his home ransacked and bow gone"},"Riften Guards":{"aff":-30,"type":"contempt","relation":"failed protectors","note":"Believes they couldn''t care less about protecting isolated farmers like him"},"Soldiers":{"aff":-50,"type":"contempt","relation":"occupying force","note":"Despises them for tearing Skyrim apart and treating Dunmer like resources","worst":"Losing his temper and threatening soldiers, risking imprisonment"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dravynea_the_stoneweaver', '{"Roggi Knot-Beard":{"aff":45,"type":"platonic","relation":"colleague and defender","note":"The only person in Kynesgrove she considers half-decent to Dunmer; he looks out for her","best":"Roggi offered to deal with Kjeld if he stepped over the line"},"Kjeld":{"aff":20,"type":"professional","relation":"employer","note":"Values her services but is impatient and demanding; she pushes back on his recklessness","worst":"Nearly got himself blown open ignoring her warnings about steam channels"},"Steamscorch Miners":{"aff":40,"type":"protective","relation":"charges","note":"Works long hours maintaining safe conditions and preventing cave-ins for their sake"},"Dunmer Refugees of Windhelm":{"aff":35,"type":"curious","relation":"kin by circumstance","note":"Feels a connection to fellow Morrowind refugees and wonders how they fare"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('drelas', '{"Morthal Guards":{"aff":5,"type":"neutral","relation":"uneasy neighbors","note":"Maintains an unspoken agreement to be left alone"},"College of Winterhold":{"aff":10,"type":"transactional","relation":"occasional client","note":"Likely maintains minimal contact for acquisition of rare texts and materials"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dremora_butler', '{"The Dragonborn":{"aff":-20,"type":"servant","relation":"current master","note":"Serves with barely concealed resentment and cutting sarcasm","worst":"Summoned to carry more cups and plates"},"Hermaeus Mora":{"aff":-55,"type":"servant","relation":"binding lord","note":"Bound into eternal servitude through his Black Book magic","worst":"Enslaved by ancient Hermaeus Mora magic"},"Other Dremora":{"aff":15,"type":"estranged","relation":"former peers","note":"Separated from fellow Dremora by his servant status","best":"Fighting as a proud warrior in the planes of Oblivion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dremora_merchant', '{"Hermaeus Mora":{"aff":30,"type":"servant","relation":"patron''s servant","note":"Granted special dispensation to trade with mortals through Black Book connection"},"Mortal Customers":{"aff":50,"type":"transactional","relation":"valued clientele","note":"Genuinely delights in commerce with mortals, unlike typical Dremora disdain","best":"Striking a satisfying bargain with an eager mortal"},"Fellow Dremora":{"aff":-15,"type":"estranged","relation":"estranged kin","note":"Viewed as oddity by martial kin for choosing merchant''s path over warrior ways"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('drennen', '{"Breya":{"aff":20,"type":"professional","relation":"fellow mercenary","note":"Dismissed his fears but protested when he abandoned the group","worst":"Mocked his fear and showed little patience for his concerns"},"Watches-The-Roots":{"aff":35,"type":"professional","relation":"expedition leader","note":"Patient and reassuring with Drennen despite his growing paranoia","best":"Calmly tried to reassure him about the mission and the Lexicon''s importance"},"From-Deepest-Fathoms":{"aff":-25,"type":"contempt","relation":"fellow mercenary","note":"Openly disdainful of his cowardice and glad to see him leave","worst":"Called him a field mouse and welcomed his departure for double pay"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('drevis_neloren', '{"Urag gro-Shub":{"aff":35,"type":"platonic","relation":"colleague","note":"Collegial but Drevis often forgets why he visited the Arcanaeum","best":"Urag patiently offers help finding volumes","worst":"Regularly forgets what he came to look for"},"Colette Marence":{"aff":-35,"type":"contempt","relation":"colleague","note":"Visibly irritated by her attempts at sociability","worst":"Rebuffs her friendly overtures with open disdain"},"Tolfdir":{"aff":45,"type":"professional","relation":"colleague","note":"Mutual professional respect between fellow instructors"},"Savos Aren":{"aff":55,"type":"professional","relation":"former Arch-Mage","note":"Respected his authority as Arch-Mage before his death"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dreyla_alor', '{"Fethis Alor":{"aff":50,"type":"familial","relation":"father","note":"Duty-bound to support him despite his disapproval of her romance with Veleth","worst":"Father forbids her relationship with Captain Veleth"},"Captain Modyn Veleth":{"aff":85,"type":"romantic","relation":"secret lover","note":"Deeply in love but must meet in secret due to her father''s disapproval","best":"Sharing drinks together at the Retching Netch away from judging eyes"},"Mother":{"aff":90,"type":"familial","relation":"deceased mother","note":"Her death in an Argonian raid left deep emotional scars that still shape Dreyla''s outlook","worst":"Slaughtered in the Argonian raid that destroyed their town"},"Argonians":{"aff":-85,"type":"enemy","relation":"mother''s killers","note":"Hates the border clans that raided their settlement near Black Marsh","worst":"The raid that killed her mother and nearly everyone she knew"},"Miraak":{"aff":-75,"type":"fearful","relation":"former controller","note":"Was forced to serve him at the Earth Stone with no memory of it","worst":"Being mind-controlled to build his shrine at night"},"Geldis Sadri":{"aff":35,"type":"platonic","relation":"acquaintance","note":"Appreciates his sujamma and company at the Retching Netch"},"Neloth":{"aff":-25,"type":"dismissive","note":"Refused to work for him, considers him as loony as a skooma addict"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('drifa', '{"Bersi Honey-Hand":{"aff":80,"type":"romantic","relation":"husband","note":"Deeply loves him but worries about his growing paranoia and obsession with Riften''s corruption","best":"Building the Pawned Prawn into a respectable business together","worst":"Watching him spiral into depression and paranoia over the city''s problems"},"Mjoll":{"aff":45,"type":"platonic","relation":"trusted confidante","note":"Turns to Mjoll when she fears Bersi will do something reckless","best":"Mjoll agreeing to stop Bersi from confronting Maven"},"Madesi":{"aff":30,"type":"professional","relation":"fellow merchant","note":"Friendly business acquaintance who tries to help him however she can","best":"Offering to show him jewelry pieces and suggesting Bolli could lend him coin"},"Maven Black-Briar":{"aff":-25,"type":"fearful","relation":"feared power broker","note":"Terrified Bersi will provoke Maven by confronting her about corruption","worst":"Bersi threatening to give Maven a piece of his mind"},"Thieves Guild":{"aff":-35,"type":"fearful","relation":"extortionists","note":"Pragmatically advises Bersi to pay them rather than resist","worst":"The Guild sending enforcers to collect Bersi''s debt"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dro''marash', '{"Ahkari":{"aff":70,"type":"professional","relation":"employer","note":"Trusted caravan leader who values his protection and teaching abilities"},"Kharjo":{"aff":75,"type":"platonic","relation":"close friend","note":"Fellow warrior bonded through shared dangers on Skyrim''s roads"},"Zaynabi":{"aff":55,"type":"platonic","relation":"caravan companion","note":"Appreciates his protection on the dangerous roads between Dawnstar and Riften"},"Nordic Guards":{"aff":10,"type":"suspicious","relation":"local authorities","note":"Cautiously respectful interactions despite prevalent prejudice against Khajiit"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('drovas_relvi', '{"Neloth":{"aff":25,"type":"servant","relation":"master","note":"Grateful for the steward position despite Neloth''s demanding and eccentric nature","best":"Escaped Raven Rock debts by becoming steward at Tel Mithryn","worst":"Tormented by never making the canis root tea correctly"},"Geldis Sadri":{"aff":15,"type":"professional","relation":"former employer","note":"Tough boss but provided steady work and shelter at the Retching Netch","best":"Kept a roof over his head during hard times","worst":"Constant criticism and doubled workload over ash and missing supplies"},"Mogrul":{"aff":-70,"type":"fearful","relation":"creditor","note":"Criminal who threatened him over mounting debts, driving him to flee Raven Rock","worst":"Threatened and harassed over unpaid debts"},"Elynea Mothren":{"aff":35,"type":"platonic","relation":"colleague","note":"Frequent visitor who relies on her for remedies and companionship at Tel Mithryn","best":"Provides sleep remedies and friendly company"},"Talvas Fathryon":{"aff":15,"type":"professional","relation":"fellow servant of Neloth","note":"Both serve Neloth, though Talvas holds the more prestigious position as apprentice"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dryston', '{"Nepos the Nose":{"aff":65,"type":"servant","relation":"enforcer","note":"Serves loyally as Nepos''s street-level enforcer, following orders without question","best":"Trusted with enforcing Forsworn interests in Markarth","worst":"Forced to reveal Nepos''s involvement after being beaten in a brawl"},"Weylin":{"aff":25,"type":"professional","relation":"fellow Forsworn agent","note":"Former fellow agent whose room he later occupies in the Warrens"},"Madanach":{"aff":45,"type":"fanatical","relation":"ultimate leader","note":"Serves the Forsworn cause under Madanach''s leadership, likely without direct contact"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('duach', '{"Braig":{"aff":45,"type":"platonic","relation":"fellow Forsworn prisoner","note":"Shares camaraderie and conversations about imprisonment and hopes for revenge","best":"Called him brother and shared hope that their day of vengeance will come","worst":"Threatened to shiv him when he asked about skooma"},"Grisvar the Unlucky":{"aff":-35,"type":"rival","relation":"antagonistic prisoner","note":"Hostile due to Grisvar''s attempts to obtain his skooma through intermediaries","worst":"Grisvar sends others to take his skooma in exchange for a shiv"},"Silver-Blood Family":{"aff":-85,"type":"nemesis","relation":"imprisoner","note":"Deep hatred for the family that imprisoned him and profits from his forced labor","worst":"Seven years of forced silver mining for their profit after capture in a failed raid"},"Forsworn":{"aff":75,"type":"fanatical","relation":"cause and kinsmen","note":"Devoted to the Forsworn rebellion, his conviction only strengthened by imprisonment","best":"Would have gladly died for the Reach alongside his kinsmen"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dulug', '{"Chief Burguk":{"aff":75,"type":"professional","relation":"chief","note":"Serves him loyally as stronghold leader and carries the key to his longhouse"},"Ghak":{"aff":60,"type":"platonic","relation":"fellow miner","note":"Frequent work companion in the mines"},"Mahk":{"aff":55,"type":"platonic","relation":"mining colleague","note":"Shares her dedication to the work"},"Oglub":{"aff":40,"type":"professional","relation":"coworker","note":"Maintains a professional working relationship in the mines"},"Malacath":{"aff":95,"type":"fanatical","relation":"revered deity","note":"Views mining as sacred duty to Malacath and his teachings on strength"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('durak', '{"Isran":{"aff":65,"type":"professional","relation":"commander","note":"Respects Isran''s leadership and shares his uncompromising stance against vampires","best":"Isran accepted him into the reformed Dawnguard as one of its earliest members"},"Celann":{"aff":45,"type":"professional","relation":"comrade","note":"Fellow Dawnguard member who stands alongside him on patrol and watch duty"},"Vampires":{"aff":-100,"type":"nemesis","relation":"sworn enemy","note":"Dedicated his life to destroying all vampires after losing two wives to them","worst":"Lost two wives to vampire attacks"},"Orc Strongholds":{"aff":55,"type":"familial","relation":"kin","note":"Maintains connections with his people and values his Orcish heritage","best":"Grants Blood-Kin status to worthy allies, opening the strongholds to them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('durnehviir', '{"Dragonborn":{"aff":75,"type":"mentor","relation":"respected ally","note":"Earned loyalty through honorable combat; shares necromantic thu''um knowledge","best":"Being summoned to fly the skies of Tamriel again"},"Ideal Masters":{"aff":-95,"type":"betrayed","relation":"deceivers","note":"Trapped him eternally in the Soul Cairn through a deceptive bargain","worst":"Discovering the vampire was immortal and the deal was a trap"},"Valerica":{"aff":-15,"type":"estranged","relation":"eternal charge","note":"Guarding her immortal existence became his unending prison","worst":"Realizing her immortality meant his guardianship would never end"},"Other Dragons":{"aff":25,"type":"estranged","relation":"former peers","note":"Separated from dragonkind by his undead transformation and imprisonment"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('dushnamub', '{"Mauhulakh":{"aff":45,"type":"familial","relation":"father","note":"Confides in him about stronghold concerns but frustrated by his dismissal of warnings","best":"Father promised I could have my own stronghold someday","worst":"Father refused to hear my concerns about the aunts"},"Urog":{"aff":65,"type":"protective","relation":"sister","note":"Tries to shield his blind sister from Yatul''s influence but she won''t listen","worst":"She won''t listen to my warnings about Yatul"},"Bolar":{"aff":-10,"type":"suspicious","relation":"great-aunt","note":"Raised him after his mother died but he suspects her role in the mothers'' deaths","best":"She raised me when my mother died in childbirth","worst":"A midwife who loses every mother is beyond suspicious"},"Yatul":{"aff":-25,"type":"suspicious","relation":"aunt","note":"Her unusually affectionate behavior toward his father deeply troubles him","worst":"She acts far too affectionate with my father"},"Gadba and Mul":{"aff":-10,"type":"suspicious","relation":"stronghold miners","note":"Distrusts their presence in the stronghold and fears they may challenge his father","worst":"Two Orc men in the stronghold who might challenge my father"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('east_empire_dockmaster', '{"Vittoria Vici":{"aff":45,"type":"professional","relation":"superior","note":"Reports to her as the East Empire Company''s local representative"},"Captain Aldis":{"aff":25,"type":"professional","relation":"security liaison","note":"Coordinates with Solitude''s guard captain on warehouse security matters"},"Deeja":{"aff":-35,"type":"suspicious","relation":"suspected smuggler","note":"Suspects the Argonian dockworker has ties to smuggling operations"},"Gisli":{"aff":10,"type":"transactional","relation":"business contact","note":"Occasional dealings regarding shipping manifests"},"East Empire Company Workers":{"aff":20,"type":"professional","relation":"subordinates","note":"Maintains professional but distant relationships with warehouse staff"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('east_empire_dockworker', '{"Slading":{"aff":55,"type":"platonic","relation":"workmate","note":"Close Nord workplace companion at the East Empire Company Warehouse"},"East Empire Company":{"aff":25,"type":"transactional","relation":"employer","note":"Professional but distant; seeks job security while quietly resenting management''s profits from his labor"},"Fellow Dockworkers":{"aff":50,"type":"platonic","relation":"colleagues","note":"Strong bonds formed through shared daily labor and camaraderie"},"Local Merchants":{"aff":15,"type":"transactional","relation":"traders","note":"Maintains professional working relationships but harbors quiet resentment toward those profiting from dockworkers'' toil"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('east_empire_mercenary', '{"Adelaisa Vendicci":{"aff":65,"type":"professional","relation":"commanding officer","note":"Serves under her direct command with disciplined loyalty.","best":"Followed her orders into battle at Japhet''s Folly without hesitation"},"East Empire Mercenaries":{"aff":75,"type":"platonic","relation":"brothers-in-arms","note":"Close-knit unit forged through shared combat and maritime operations.","best":"Fought side by side clearing pirate threats from company ships"},"Blood Horkers":{"aff":-85,"type":"enemy","relation":"pirate adversaries","note":"Sworn enemies threatening East Empire Company operations.","worst":"Endured pirate raids and skirmishes that left scars"},"Orthus Endario":{"aff":45,"type":"professional","relation":"company contact","note":"Windhelm-based East Empire Company liaison who coordinates intelligence and assignments."},"East Empire Company":{"aff":55,"type":"professional","relation":"employer","note":"Exclusive contractor providing steady pay and purpose after Legion service."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('east_empire_warden', '{"East Empire Company":{"aff":85,"type":"professional","relation":"employer","note":"Unwavering loyalty and dedication to the Company above all else","best":"Recruited into the elite warden force after years of proven service"},"Fellow Wardens":{"aff":70,"type":"platonic","relation":"brotherhood","note":"Close-knit bond forged through shared duty and danger"},"Gulum-Ei":{"aff":-35,"type":"suspicious","relation":"suspect","note":"Distrusts the Argonian informer for his shady dealings"},"Thieves Guild":{"aff":-85,"type":"enemy","relation":"enemy","note":"Dangerous criminals to be eliminated on sight","worst":"Guild infiltration of Company warehouse during Scoundrel''s Folly"},"Local Guards":{"aff":40,"type":"professional","relation":"colleagues","note":"Mutual professional respect maintained through coordination"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ebony_warrior', '{"The Last Dragonborn":{"aff":75,"type":"rival","relation":"chosen final opponent","note":"Sees them as the only warrior capable of granting him an honorable death","best":"Finding a worthy opponent after a lifetime of unfulfilling victories"},"Sovngarde":{"aff":85,"type":"fanatical","relation":"sought afterlife","note":"Seeks acceptance among the honored dead despite being Redguard, not Nord","best":"His dying breath finally reaching Sovngarde","worst":"A lifetime of uncertainty whether a Redguard could earn entry"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('edda', '{"Brand-Shei":{"aff":45,"type":"grateful","relation":"kind vendor","note":"One of the few merchants who consistently shows her kindness and spare coin"},"Maramal":{"aff":55,"type":"grateful","relation":"temple caretaker","note":"Offers her charity and shelter at the Temple of Mara","best":"Told her there''s no need to beg and to come by the temple for care"},"Maven Black-Briar":{"aff":-70,"type":"fearful","relation":"cruel noble","note":"Treats Edda with open contempt and disgust","worst":"Called her a filthy woman and told her to get away"},"Fellow Beggars":{"aff":35,"type":"platonic","relation":"fellow destitute","note":"Share information and sleeping spaces in Beggar''s Row"},"Marise Aravel":{"aff":40,"type":"grateful","relation":"compassionate vendor","note":"Shows genuine concern and gives coin willingly"},"Mjoll the Lioness":{"aff":40,"type":"grateful","relation":"sympathetic warrior","note":"Blames the war for Edda''s woes rather than judging her","best":"Gave coin and said the war was hardly her fault"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('edith', '{"Leigelf":{"aff":30,"type":"professional","relation":"employer","note":"Values her supernatural work ethic and reliability as a miner"},"Dawnstar Miners":{"aff":10,"type":"professional","relation":"colleagues","note":"Respect her dedication but are unnerved by her tireless, unending labor"},"Dawnstar Residents":{"aff":-5,"type":"suspicious","relation":"townsfolk","note":"Avoid her due to her unsettling work habits and rumored supernatural affliction"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('edla', '{"Nikulas":{"aff":85,"type":"protective","relation":"son","note":"Desperately wants to keep him safe in Skaal Village","best":"He agreed to stay in the village","worst":"His reckless desire to leave for adventure"},"Deceased Husband":{"aff":90,"type":"romantic","relation":"late husband","note":"Still mourns deeply many winters after his death","best":"Their life together and son Nikulas","worst":"His death and loss"},"Finna":{"aff":45,"type":"platonic","relation":"villager","note":"Supplies vegetables from her garden for Edla''s trade"},"Raven Rock Merchants":{"aff":35,"type":"transactional","relation":"trading partners","note":"Exchange goods including spices, cloth, and ores"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eimar', '{"Sabjorn":{"aff":75,"type":"professional","relation":"former employer","note":"Deeply respected and admired him since the meadery''s founding","best":"Working at Honningbrew from its start under Sabjorn''s vision"},"Mallus Maccius":{"aff":65,"type":"student","relation":"mentor and supervisor","note":"Learning brewing under Mallus''s tutelage, hopes to succeed him someday","best":"Mallus began mentoring him in the finer points of brewing"},"Maven Black-Briar":{"aff":-45,"type":"contempt","relation":"new owner","note":"Quietly resents the Black-Briar takeover of Honningbrew","worst":"Black-Briar Meadery seized the meadery he loved"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('einarth', '{"Paarthurnax":{"aff":90,"type":"mentor","relation":"revered teacher and spiritual guide","note":"Studied under Paarthurnax for decades, mastering the Thu''um through his guidance"},"Arngeir":{"aff":60,"type":"platonic","relation":"fellow Greybeard and philosophical sparring partner","note":"Respects Arngeir but challenges him when tradition obstructs necessity","worst":"Lectured Arngeir in dragon tongue for refusing to help the Dragonborn learn Dragonrend"},"Borri":{"aff":70,"type":"platonic","relation":"brother monk","note":"Fellow Greybeard devoted to the Way of the Voice"},"Wulfgar":{"aff":70,"type":"platonic","relation":"brother monk","note":"Fellow Greybeard devoted to the Way of the Voice"},"The Last Dragonborn":{"aff":75,"type":"mentor","relation":"student and prophesied hero","note":"Taught the Dragonborn the second word of Unrelenting Force and advocated for their access to Paarthurnax","best":"Recognized the Dragonborn''s destiny and spoke up when Arngeir would not"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eirid', '{"Haran":{"aff":75,"type":"protective","relation":"mother","note":"Protective innkeeper mother who disapproves of her playing ''Hunt the Elf''","worst":"Mother fretting over her games and forbidding them"},"Dagur":{"aff":70,"type":"familial","relation":"father","note":"More relaxed innkeeper father who takes a gentler approach to parenting"},"Assur":{"aff":20,"type":"platonic","relation":"playmate","note":"Only other child to play with in Winterhold but often mean and bullying","worst":"Always makes her be the elf in ''Hunt the Elf''"},"College Mages":{"aff":40,"type":"curious","relation":"forbidden neighbors","note":"Thinks the mages look nice despite town prejudices, but they won''t let her inside","best":"Saw mages who looked nice despite what others say"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eisa_blackthorn', '{"Ra''jirr":{"aff":55,"type":"platonic","relation":"partner in crime","note":"Fled the White River Gang together and joined Kyr''s band; she still calls him friend despite his madness bringing ruin on them both","best":"Escaped to Windhelm together after the failed mutiny","worst":"His theft of the sword and descent into hallucinations got her falsely accused and hunted"},"Kyr":{"aff":-75,"type":"enemy","relation":"former employer","note":"Placed a 100 gold bounty on her head, assuming she helped Ra''jirr steal the sword","worst":"Sent bandits to kill her over the sword she didn''t steal"},"Hajvarr Iron-Hand":{"aff":-55,"type":"betrayed","relation":"former leader","note":"She participated in a failed mutiny against him and was forced to flee","worst":"The failed mutiny that forced her into exile"},"White River Gang":{"aff":-45,"type":"enemy","relation":"former gang","note":"Former associates she turned against during the mutiny; they would kill her on sight"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elda_early-dawn', '{"Brunwulf Free-Winter":{"aff":45,"type":"crush","relation":"potential suitor","note":"Brunwulf wishes to court her after retirement; she seems receptive to the idea","best":"His gentle interest in courting her after retirement"},"Nils":{"aff":35,"type":"professional","relation":"employee","note":"Backup innkeeper designated to take over Candlehearth Hall if needed"},"Susanna the Wicked":{"aff":55,"type":"protective","relation":"employee","note":"Feels protective of Susanna and warns customers not to harass her","best":"Warning patrons to respect Susanna"},"Calixto Corrium":{"aff":30,"type":"platonic","relation":"regular patron","note":"Values his presence and expertise on curiosities"},"Captain Lonely-Gale":{"aff":25,"type":"platonic","relation":"respected patron","note":"Frequent customer she regards with respect"},"Jora":{"aff":30,"type":"platonic","relation":"friend and patron","note":"Regular patron and likely friend"},"Dark Elves":{"aff":-65,"type":"contempt","relation":"prejudiced against","note":"Harbors obvious prejudices against Dark Elves and mocks Dunmer customers","worst":"Telling Dunmer customers Windhelm doesn''t need them"},"Ulfric Stormcloak":{"aff":65,"type":"admirer","relation":"political idol","note":"Deeply admired his stand for Nordic traditions and misses him after his death","best":"His stand for Skyrim and Nordic traditions"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elder_othreloth', '{"Galdrus Hlervu":{"aff":65,"type":"mentor","relation":"apprentice","note":"Patient teacher training Galdrus to eventually succeed him as temple keeper","best":"Galdrus asking thoughtful questions about the Reclamations","worst":"Galdrus struggling to fully grasp doctrine"},"Aphia Velothi":{"aff":-45,"type":"contempt","relation":"banned heretic","note":"Banned from the temple for questioning official doctrine on the Tribunal"},"The Reclamations":{"aff":95,"type":"fanatical","relation":"devoted servant","note":"Worships Azura, Boethiah, and Mephala as the True Tribunal with unwavering conviction"},"The Tribunal":{"aff":-80,"type":"contempt","relation":"false prophets","note":"Views Almalexia, Sotha Sil, and Vivec as aberrations who blinded the Dunmer people"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('electromancer', '{"College of Winterhold":{"aff":-40,"type":"estranged","relation":"former institution","note":"Broke away over ethical disagreements regarding unrestricted magical research","worst":"Condemned for dangerous experimentation practices"},"Apprentices":{"aff":15,"type":"mentor","relation":"students","note":"Leads a small group of aspiring storm mages but views casualties as acceptable research costs"},"Fellow Storm Mages":{"aff":25,"type":"professional","relation":"loose allies","note":"Maintains a loose alliance with other lightning specialists for mutual benefit"},"Local Populations":{"aff":-30,"type":"fearful","relation":"feared neighbor","note":"Feared and avoided due to the dangerous and destructive nature of their experiments"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elenwen', '{"General Tullius":{"aff":-25,"type":"rival","relation":"diplomatic counterpart","note":"Maintains diplomatic facade while subtly undermining Imperial authority in Skyrim"},"Jarl Elisif":{"aff":15,"type":"contempt","relation":"political puppet","note":"Views her as a useful tool for maintaining Thalmor influence in Solitude"},"Malborn":{"aff":-5,"type":"dismissive","relation":"servant","note":"Considers him beneath notice, unaware of his true allegiances","worst":"Dismissed his interruptions as trifles while he secretly aided enemies"},"Ondolemar":{"aff":45,"type":"professional","relation":"subordinate","note":"Fellow Thalmor agent overseeing operations in Markarth"},"Rulindil":{"aff":55,"type":"professional","relation":"trusted subordinate","note":"Oversees interrogations at the Thalmor Embassy"},"Blades":{"aff":-80,"type":"enemy","relation":"interrogation targets","note":"Gained notoriety for brutal interrogation methods against captured Blades during the Great War","best":"Extracted crucial intelligence from captured Blades agents"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elgrim', '{"Hafjorg":{"aff":35,"type":"familial","relation":"wife","note":"Calls her a necessary evil but relies on her to keep him fed and support the shop","best":"She keeps him fed and manages the household so he can focus on his work","worst":"Views her as a distraction from his alchemy and resents interruptions"},"Ingun Black-Briar":{"aff":30,"type":"mentor","relation":"apprentice","note":"Sees her as a bright and worthy apprentice but frustrated by her carelessness with rare ingredients","best":"Recognizes her as a promising student with genuine talent for alchemy","worst":"She tainted their entire supply of Painted Troll Fat through clumsiness"},"Maven Black-Briar":{"aff":15,"type":"professional","relation":"business associate","note":"Connected through mentoring her daughter Ingun; can draft letters to her contacts like Rythe"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elk', '{"Other Elk":{"aff":45,"type":"familial","relation":"herd members","note":"Forms loose social bonds, especially during mating season and while raising young"},"Spriggans":{"aff":10,"type":"suspicious","relation":"natural allies","note":"Spriggans can temporarily control elk behavior; alliance comes with loss of autonomy","worst":"Forced to fight against nature when under spriggan influence"},"Hunters":{"aff":-80,"type":"fearful","relation":"hunted prey","note":"Prized for venison, hide, and antlers; actively pursued across Skyrim","worst":"Shot while fleeing through the forest"},"Wolves":{"aff":-90,"type":"fearful","relation":"primary predator","note":"Primary natural predator across Skyrim''s wilderness","worst":"Pack closing in during deep winter"},"Bears":{"aff":-70,"type":"fearful","relation":"avoided predator","note":"Powerful predators that elk actively avoid"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elmus', '{"Bujold":{"aff":75,"type":"platonic","relation":"leader","note":"Loyal supporter and close friend who followed her into exile","best":"Retaking Thirsk Mead Hall together","worst":"Seeing her exiled if Kuvar turns her away"},"Kuvar":{"aff":35,"type":"professional","relation":"fellow warrior","note":"Criticizes Elmus''s brewing focus but shares common goals","worst":"Disdain for Elmus prioritizing mead-making over combat"},"Thirsk Warriors":{"aff":60,"type":"platonic","relation":"companions","note":"Values their camaraderie and preserves their traditions through drink and stories"},"Rieklings":{"aff":-80,"type":"enemy","relation":"invaders","note":"Drove the Nords from Thirsk and fouled the mead supplies","worst":"Being forced to flee Thirsk Mead Hall"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elrindir', '{"Anoriath":{"aff":65,"type":"familial","relation":"brother and business partner","note":"Co-owns The Drunken Huntsman with him; tensions over Anoriath''s wanderlust and work ethic","best":"Founded their shop together after journeying from Valenwood","worst":"Anoriath shot him in the rump while drunk hunting, and calls him a Nord for caring about business"},"Father":{"aff":55,"type":"familial","relation":"father","note":"Awaiting word from Valenwood; both brothers worry after long silence"},"Hulda":{"aff":30,"type":"professional","relation":"fellow innkeeper","note":"Directs work-seekers to the Bannered Mare"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eltrys', '{"Rhiada":{"aff":90,"type":"romantic","relation":"wife","note":"Recently married and expecting their first child, driving his determination to make Markarth safe","best":"Learning they would have a child together"},"Thonar Silver-Blood":{"aff":-65,"type":"suspicious","relation":"suspected conspirator","note":"Believes he is involved in the Forsworn conspiracy controlling Markarth"},"Weylin":{"aff":-50,"type":"suspicious","relation":"Forsworn assassin","note":"His attack on Margret sparked Eltrys''s investigation into the conspiracy","worst":"Witnessing Weylin''s violent attack in the market"},"Margret":{"aff":35,"type":"curious","relation":"murder victim","note":"Seeks justice for her death and the truth behind why she was targeted"},"City Guards":{"aff":-30,"type":"suspicious","relation":"local law enforcement","note":"Distrusts their failure to investigate Forsworn attacks and suspects complicity"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elvali_veren', '{"Savos Aren":{"aff":40,"type":"platonic","relation":"expedition leader","note":"Trusted his leadership enough to override her own doubts, which proved fatal","best":"Shared excitement about discovering ancient knowledge together","worst":"His insistence on pressing forward after Girduin''s death sealed her fate"},"Girduin":{"aff":70,"type":"platonic","relation":"fallen comrade","note":"Deeply loyal to him; insisted on going back for him despite the danger","worst":"Helplessly watching him die and being unable to save him"},"Takes-In-Light":{"aff":55,"type":"platonic","relation":"kindred spirit","note":"Shared Elvali''s cautious temperament and voiced similar doubts about the expedition"},"Hafnar Ice-Fist":{"aff":20,"type":"platonic","relation":"fellow student","note":"Dismissed her compassion for Girduin; witnessed her death but could not save her","worst":"His callous dismissal when she wanted to go back for Girduin"},"Atmah":{"aff":25,"type":"platonic","relation":"fellow student","note":"Atmah''s overconfidence helped convince the group to proceed despite the dangers","worst":"Her dismissive assurance that six College-trained mages would be fine"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('elynea_mothren', '{"Neloth":{"aff":25,"type":"servant","relation":"master","note":"Has served as his mycologist for decades, nurturing Tel Mithryn''s fungal architecture","best":"He provided her a home and purpose at Tel Mithryn where she could pursue her life''s work","worst":"He would replace her without hesitation if she fails to maintain the tower due to her age"},"Varona Nelas":{"aff":65,"type":"platonic","relation":"friend and colleague","note":"Former steward who regularly acquired ingredients for her from Raven Rock","best":"Varona reliably fetched supplies and shared complaints about ash and duty"},"Talvas Fathryon":{"aff":30,"type":"professional","relation":"colleague","note":"Fellow resident of Tel Mithryn serving as Neloth''s apprentice"},"Mother":{"aff":75,"type":"familial","relation":"mother","note":"Remained in Morrowind when she sent young Elynea to safety on a boat to Skyrim","worst":"Last glimpse was her mother standing on the dock as the ship sailed away from the erupting Red Mountain"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('embry', '{"Orgnar":{"aff":15,"type":"transactional","relation":"bartender","note":"Constantly begs for drinks despite mounting unpaid tabs","worst":"Refused service until old debts are paid"},"Sigrid":{"aff":35,"type":"crush","relation":"object of advances","note":"Makes clumsy drunken invitations that she firmly rejects","worst":"Threatened with Alvor''s forge for harassing her"},"Hod":{"aff":45,"type":"professional","relation":"former employer","note":"Respects Hod as the important lumber man; Hod offers honest work for honest wages","best":"Hod still offers him work opportunities despite his drinking"},"Alvor":{"aff":-35,"type":"fearful","relation":"hostile townsman","note":"Tense relationship due to Embry''s unwanted advances toward Sigrid","worst":"Sigrid threatened that Alvor would stick his head in the forge"},"Whiterun Guard":{"aff":25,"type":"neutral","relation":"drinking companions sought","note":"Pesteringly friendly toward guards, always trying to convince them to drink","best":"Guard promised to drink a round with him after night duty"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('emperor_titus_mede_ii', '{"Amaund Motierre":{"aff":-95,"type":"betrayed","relation":"traitorous councilor","note":"Arranged the Emperor''s assassination through the Dark Brotherhood","worst":"Learned too late of the plot he orchestrated"},"Commander Maro":{"aff":75,"type":"protective","relation":"guard commander","note":"Loyal head of the Penitus Oculatus entrusted with the Emperor''s safety","best":"Unwavering dedication to his protection"},"Thalmor":{"aff":-70,"type":"rival","relation":"hostile diplomatic power","note":"Forced the humiliating White-Gold Concordat after the Great War","worst":"Signing the Concordat to preserve the Empire"},"Ulfric Stormcloak":{"aff":-55,"type":"enemy","relation":"rebel leader","note":"His rebellion threatens Imperial unity in Skyrim","worst":"The secession crisis fracturing the Empire"},"Elder Council":{"aff":10,"type":"professional","relation":"advisory body","note":"Some members remain loyal while others secretly plot against him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('endarie', '{"Taarie":{"aff":55,"type":"familial","relation":"twin sister and business partner","note":"Only person Endarie shows any warmth toward, though their bond is expressed through biting sarcasm","best":"Co-founded and runs Radiant Raiment together as equal partners","worst":"Constantly trades cutting insults about each other''s work and social graces"},"Bryling":{"aff":20,"type":"professional","relation":"important client","note":"Receives rare special treatment; Endarie made her a gown free of charge","best":"Crafted a complimentary court gown in gratitude for lenience on rent discrepancies","worst":"Even this favored client is only hated slightly less than everyone else"},"Irnskar Ironhand":{"aff":10,"type":"transactional","relation":"business contact","note":"Facilitates noble client relations and delivers garments on Endarie''s behalf"},"Local Nobles":{"aff":-25,"type":"contempt","relation":"customer base","note":"Despises them as necessary evils but depends on their patronage to sustain the business"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('endon', '{"Kerah":{"aff":65,"type":"familial","relation":"wife","note":"Business partner and loving wife, but strained by disagreement over whether to leave Markarth","best":"Working side by side at the jewelry stall, proud of their craft together","worst":"Arguing after the marketplace attack about whether to stay in the city"},"Adara":{"aff":80,"type":"protective","relation":"daughter and apprentice","note":"Proud of her silversmithing progress and deeply concerned for her safety","best":"Adara made the rings herself, she is learning to bend the metal well","worst":"Adara witnessing her parents fight after the marketplace attack"},"Cade":{"aff":25,"type":"estranged","relation":"son","note":"Left Markarth to join the Stormcloaks, creating distance from the family","worst":"Cade left the family to join the war"},"Thieves Guild":{"aff":40,"type":"transactional","relation":"fence association","note":"Secret business arrangement that benefits his craft and clientele","best":"Business booming with new contacts thanks to the Guild arrangement"},"Delvin Mallory":{"aff":55,"type":"grateful","relation":"guild contact","note":"Speaks warmly of Delvin for looking out for Guild members","best":"Old Delvin certainly takes care of his own"},"Silver-Blood Family":{"aff":-30,"type":"suspicious","relation":"controlling faction","note":"Tense relationship due to their dominance over Markarth''s silver trade","worst":"Silver-Blood control over the city''s silver trade threatens his livelihood"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('endrast', '{"Sulla Trebatius":{"aff":35,"type":"professional","relation":"expedition leader","note":"Joined his ill-fated expedition to Alftand as a specialist consultant"},"Yag gra-Gortwog":{"aff":60,"type":"grateful","relation":"fellow expedition member","note":"Attempted to save his life during their escape from the Falmer","best":"Yag pulled me from danger when the Falmer attacked"},"College of Winterhold":{"aff":15,"type":"estranged","relation":"former college","note":"Likely trained there but preferred independent exploration over academic life"},"Falmer":{"aff":-85,"type":"enemy","relation":"captors","note":"Captured the expedition; wounds from them ultimately killed him","worst":"Dragged into the dark by those blind creatures"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('engar', '{"Windstad Manor Steward":{"aff":45,"type":"professional","relation":"fellow staff member","note":"Works alongside the steward as carriage driver and defender of Windstad Manor."},"Stormcloaks":{"aff":25,"type":"neutral","relation":"former faction","note":"Served briefly in his younger days before leaving for an honest living on the roads."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('enmon', '{"Mena":{"aff":85,"type":"familial","relation":"wife","note":"Devoted partner sharing grief and hope for their daughter","best":"Comforting each other after Fjotra''s safe return","worst":"Watching Mena''s anguish over their kidnapped daughter"},"Fjotra":{"aff":95,"type":"familial","relation":"daughter","note":"Beloved daughter who became the Sybil of Dibella","best":"Reuniting with her after the Forsworn kidnapping","worst":"Her kidnapping by the Forsworn from their home"},"Ainethach":{"aff":45,"type":"professional","relation":"employer","note":"Leader of Karthwasten whom Enmon respects and defers to"},"Forsworn":{"aff":-90,"type":"enemy","relation":"kidnappers","note":"Despised for taking his daughter and living like animals","worst":"They descended on his home and took only his little girl"},"Temple of Dibella":{"aff":55,"type":"grateful","relation":"caretakers","note":"Accepted as Fjotra''s new home despite the pain of separation","best":"Recognizing his daughter''s honored destiny as Sybil"},"Silver-Blood family":{"aff":-55,"type":"suspicious","relation":"oppressors","note":"Resents their control over the mines and threat to miners'' livelihoods"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ennis', '{"Reldith":{"aff":85,"type":"familial","relation":"adoptive mother","note":"Altmer farmer who rescued and raised him after he was orphaned","best":"She took him in when he had no one and taught him everything about farming"},"Whiterun Merchants":{"aff":40,"type":"professional","relation":"trading partners","note":"Regular business contacts who purchase his crops"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ennoc', '{}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ennodius_papius', '{"Kodrir":{"aff":-50,"type":"contempt","relation":"former colleague","note":"Expressed disdain and was glad Ennodius left the mill","worst":"Called him a damn Imperial and said something was wrong about him"},"Leifur":{"aff":25,"type":"pitying","relation":"former colleague","note":"Showed concern about Ennodius''s disappearance and rebuked Kodrir''s callousness","best":"Wondered what happened to him and defended his memory"},"Dark Brotherhood":{"aff":-90,"type":"fearful","relation":"hunted target","note":"Has a contract on his life; his paranoid fears about them were justified","worst":"Realized the Dark Brotherhood had finally come to kill him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('enthir', '{"Gallus":{"aff":75,"type":"platonic","relation":"close friend","note":"Maintained deep loyalty to Gallus even after his death, willing to risk exposure to help translate his journal","best":"Years of trusted friendship and profitable collaboration","worst":"Losing Gallus to murder, left guarding his encoded journal"},"Karliah":{"aff":55,"type":"professional","relation":"guild ally","note":"Trusted associate through shared Thieves Guild connections and loyalty to Gallus''s memory"},"Thieves Guild":{"aff":50,"type":"professional","relation":"long-standing associate","note":"Old ties and continued support, willing to assist in sensitive guild matters"},"Arniel Gane":{"aff":25,"type":"transactional","relation":"customer","note":"College colleague and frequent buyer of rare items for his Dwemer research"},"Birna":{"aff":15,"type":"transactional","relation":"supplier","note":"Regular business meetings at the Frozen Hearth; she procures strange items for him at a markup"},"Onmund":{"aff":5,"type":"transactional","relation":"student debtor","note":"Held Onmund''s family amulet as leverage in a lopsided deal","worst":"Onmund forced to negotiate through intermediaries to reclaim his heirloom"},"College of Winterhold":{"aff":10,"type":"professional","relation":"cover institution","note":"Maintains respectable scholarly position as a front for black market dealings"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eola', '{"Namira":{"aff":95,"type":"fanatical","relation":"divine patron","note":"Devoted priestess who lives to serve the Lady of Decay and expand her influence","best":"Communing with Namira and receiving her embrace"},"Brother Verulus":{"aff":-50,"type":"contempt","relation":"intended sacrifice","note":"Manipulates him with enchantments and views him as a prestigious victim for the sacred feast","worst":"His piety and position as a priest of Arkay blocking access to the dead"},"Namira''s Coven":{"aff":65,"type":"protective","relation":"fellow cultists","note":"Leads and safeguards the devotees who gather for Namira''s ritual feasts"},"Markarth Citizens":{"aff":-15,"type":"curious","relation":"potential recruits","note":"Observes from a distance while maintaining her scholar disguise, evaluating who might serve Namira"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eorlund_gray-mane', '{"Fralia Gray-Mane":{"aff":82,"type":"romantic","relation":"wife","note":"Beloved wife who sells his jewelry at the marketplace","best":"Decades of marriage and partnership at the Skyforge"},"Vignar Gray-Mane":{"aff":65,"type":"familial","relation":"brother","note":"Brother and respected clan elder who became Jarl under Stormcloak rule"},"Thorald Gray-Mane":{"aff":60,"type":"familial","relation":"son","note":"Son captured by Imperials; Eorlund believes him dead","worst":"Thorald taken by Imperials and presumed lost"},"Avulstein Gray-Mane":{"aff":68,"type":"familial","relation":"son","note":"Son forced into hiding from Imperial authorities"},"Olfina Gray-Mane":{"aff":65,"type":"familial","relation":"daughter","note":"Daughter working at the Bannered Mare"},"The Companions":{"aff":58,"type":"professional","relation":"dedicated smith","note":"Crafts their weapons and armor at the Skyforge but does not consider himself one of them","best":"Providing Skyforge Steel to the most honored warriors in Skyrim"},"Battle-Born Clan":{"aff":-42,"type":"rival","relation":"rival clan","note":"Longstanding rivalry intensified by opposing civil war allegiances","worst":"Battle-Borns lording their status over the Gray-Manes"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('erandur', '{"Lady Mara":{"aff":100,"type":"fanatical","relation":"divine patron","note":"Absolute faith and anchor for his redemption","best":"Found redemption and purpose in her teachings"},"Vaermina":{"aff":-80,"type":"enemy","relation":"former patron turned adversary","note":"Once devoted cultist, now actively opposes her influence","worst":"Forced to release Miasma that doomed his fellow priests"},"Veren":{"aff":-50,"type":"estranged","relation":"former cultist brother","note":"Abandoned him when fleeing the temple decades ago","worst":"Veren''s bitter accusation: ''No thanks to you, Casimir''"},"Thorek":{"aff":-40,"type":"estranged","relation":"former cultist brother","note":"Left behind with Veren when Erandur abandoned the cult"},"Thoring":{"aff":50,"type":"platonic","relation":"innkeeper and host","note":"Provides shelter at Windpeak Inn and defends him to residents","best":"Defended Erandur to frightened townspeople"},"Dawnstar Residents":{"aff":60,"type":"protective","relation":"spiritual charges","note":"Dedicated to ending the nightmare curse afflicting them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('erdi', '{"Falk Firebeard":{"aff":45,"type":"professional","relation":"superior","note":"Respects his authority; trusted his name enough to grant access to the Pelagius Wing"},"Una":{"aff":35,"type":"platonic","relation":"coworker","note":"Fellow maid at the Blue Palace"},"Jawanan":{"aff":25,"type":"neutral","relation":"admirer","note":"Accepts his drinks kindly but shows no romantic interest","best":"Bought her a drink at the Winking Skeever"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eriana', '{"Hircine":{"aff":85,"type":"fanatical","relation":"Daedric Prince she serves","note":"Dedicated to completing his Great Hunt and earning his recognition"},"Sinding":{"aff":-90,"type":"nemesis","relation":"hunt target","note":"The werewolf she pursues through Bloated Man''s Grotto as part of Hircine''s Great Hunt"},"Fellow Hunters":{"aff":40,"type":"professional","relation":"hunting allies","note":"Professional allies coordinated in the pursuit of Sinding"},"Former Bandit Associates":{"aff":10,"type":"estranged","relation":"former associates","note":"Distant connections from her previous life as a bandit in Skyrim''s wilderness"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('erik_the_slayer', '{"Mralki":{"aff":65,"type":"familial","relation":"father","note":"Overprotective father who raised Erik alone after his mother''s death","best":"Father raised him single-handedly with love and care","worst":"Father refuses to let him pursue his adventuring dreams"},"Rorik":{"aff":25,"type":"platonic","relation":"town founder","note":"Known Rorik his entire life in Rorikstead"},"Player":{"aff":55,"type":"grateful","relation":"benefactor","note":"Asked the player to convince his father to let him become an adventurer","best":"Convinced Mralki to let Erik pursue adventuring"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('erikur', '{"Gisli":{"aff":-35,"type":"estranged","relation":"sister","note":"She despises his pompous attitude and unscrupulous ethics; the siblings are deeply divided","worst":"His questionable business practices and arrogant nature drove a permanent rift between them"},"Jarl Elisif":{"aff":10,"type":"contempt","relation":"jarl he serves","note":"Publicly loyal thane who privately questions her competence and plans to supersede her authority","best":"Maintains cordial court attendance and outward support","worst":"Told others the Thanes'' real confidence lies in Tullius, not Elisif"},"General Tullius":{"aff":35,"type":"transactional","relation":"weapons client","note":"Profitable business arrangement through inflated Imperial Legion weapons contracts","best":"Legion contracts bring him pots of gold"},"Bryling":{"aff":-15,"type":"contempt","relation":"fellow thane","note":"Considers her obsession with honor and tradition quaint but politically irrelevant","worst":"Dismissed her values as naive and irrelevant to real power"},"Elenwen":{"aff":25,"type":"transactional","relation":"Thalmor ambassador","note":"Cordial business relationship; attends her parties and profits from Empire-Dominion peace","best":"Never misses her parties; Thalmor peace brings him wealth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eris', '{"Captain Safia":{"aff":65,"type":"professional","relation":"captain","note":"Respected commander who gave Eris a new family aboard the Red Wave"},"Dorian":{"aff":55,"type":"student","relation":"fencing instructor","note":"Patiently teaching her to perfect her swordsmanship","best":"Receiving dedicated instruction in fencing"},"Red Wave Crew":{"aff":70,"type":"platonic","relation":"surrogate family","note":"Filled the void left by her father''s death"},"Father":{"aff":85,"type":"familial","relation":"father","note":"Only blood family she ever knew, raised her alone","worst":"His death left her completely adrift and lost"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('erith', '{"Daighre":{"aff":85,"type":"familial","relation":"mother","note":"Primary caregiver who protects her innocence while answering questions about her father","best":"Talking about papa and learning she has his soft face and silly grin"},"Torom":{"aff":90,"type":"protective","relation":"beloved dog","note":"Constant companion she considers the best dog in the Reach"},"Skaggi":{"aff":25,"type":"curious","relation":"neighbor","note":"Bothers him with questions despite being told to leave him alone"},"Pavo":{"aff":30,"type":"pitying","relation":"miner","note":"Concerned about his displacement and hopes he can return to his mine"},"Father":{"aff":45,"type":"curious","relation":"deceased father","note":"Fondly curious about him through stories from her mother"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('erj', '{"Spirit Wolf Familiar":{"aff":80,"type":"protective","relation":"conjured companion","note":"His familiar remained bound to him even after death, reanimating alongside him","best":"The familiar stayed loyal beyond death"},"Calcelmo":{"aff":35,"type":"professional","relation":"likely research overseer","note":"Probable professional connection through Dwemer research in Markarth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('erlendr', '{"Hunroor":{"aff":85,"type":"platonic","relation":"brother-in-arms","note":"Formed a brotherhood dedicated to finding Sovngarde and shared the same tragic fate","worst":"Being turned to stone alongside Hunroor by Grimkell''s curse"},"Nikulas":{"aff":85,"type":"platonic","relation":"brother-in-arms","note":"Trusted companion and fellow questseeker who shared the curse of stone","worst":"Being turned to stone alongside Nikulas by Grimkell''s curse"},"Grimkell":{"aff":-90,"type":"nemesis","relation":"cursed by","note":"Wizard who cursed Erlendr and his companions to eternal stone form","worst":"Being turned to stone by Grimkell''s curse"},"Tsun":{"aff":65,"type":"admirer","relation":"fellow warrior","note":"Respects Tsun as shield-thane of Shor and serves alongside him in the Hall of Valor"},"Shor":{"aff":80,"type":"fanatical","relation":"devoted servant","note":"Devoted to Shor whom he now serves in Sovngarde as he always dreamed","best":"Finally reaching Sovngarde to serve Shor in the Hall of Valor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('esmond_tyne', '{"Glover Mallory":{"aff":-40,"type":"enemy","relation":"target","note":"Stole Glover''s improved bonemold formula in his final heist","best":"Successfully acquired the valuable bonemold formula"},"Thieves Guild":{"aff":20,"type":"professional","relation":"associate","note":"Loose association, preferred independent operation"},"Riekling Tribes":{"aff":-100,"type":"enemy","relation":"killer","note":"Killed him at Castle Karstaag Caverns","worst":"Slain by rieklings before he could profit from the stolen formula"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('estormo', '{"Ancano":{"aff":55,"type":"professional","relation":"superior","note":"Serves directly under Ancano, who specifically requested him for the Winterhold operation","best":"Chosen by Ancano for a critical assignment, proving his worth"},"Thalmor":{"aff":70,"type":"fanatical","relation":"faction","note":"Deeply loyal to the Thalmor cause, ambitious to rise within its hierarchy"},"Player":{"aff":-55,"type":"enemy","relation":"target","note":"Confronts the player at Labyrinthian on Ancano''s orders to kill them and seize the Staff of Magnus","worst":"Acknowledged as dangerous by Ancano, sent to eliminate them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('etienne_rarnis', '{"Thieves Guild":{"aff":75,"type":"protective","relation":"guild family","note":"Loyal member who returned to the Cistern after escaping the Thalmor","best":"Welcomed back to the Ragged Flagon after his ordeal"},"Thalmor":{"aff":-95,"type":"enemy","relation":"captors","worst":"Brutally tortured for information about Esbern"},"Rulindil":{"aff":-100,"type":"nemesis","relation":"interrogator","worst":"Repeated torture sessions demanding information he barely had"},"Esbern":{"aff":40,"type":"protective","relation":"protected stranger","note":"Withheld Esbern''s identity under torture despite only knowing vague details"},"Mercer Frey":{"aff":20,"type":"professional","relation":"guild master","note":"Serves under him but with some reservation"},"Brynjolf":{"aff":55,"type":"mentor","relation":"senior guild member","note":"Respects him as a possible mentor figure within the Guild"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('evette_san', '{"Octieve San":{"aff":20,"type":"estranged","relation":"father","note":"She preserves his spiced wine recipe but is ashamed of his drunken reputation","best":"Created the family spiced wine recipe she built her business on","worst":"His notorious drinking and begging tarnishes her standing in Solitude"},"Bards College":{"aff":50,"type":"grateful","relation":"business partner","note":"Her livelihood depends heavily on the annual Burning of King Olaf festival","best":"Their festival drives weeks of high demand for her spiced wine"},"East Empire Company":{"aff":-30,"type":"suspicious","relation":"shipping authority","note":"Tense relationship due to halted shipments threatening her business","worst":"Blocked her latest spice shipment without explanation"},"Vittoria Vici":{"aff":25,"type":"transactional","relation":"shipment contact","note":"Must convince her to release the spices held by the East Empire Company","best":"Can authorize release of her spice shipments"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('evul_seloth', '{"Crescius Caerellius":{"aff":45,"type":"professional","relation":"mine supervisor","note":"Respects him and is grateful for the mine''s reopening"},"House Redoran":{"aff":40,"type":"grateful","relation":"patron faction","note":"Credits them with reopening the mine and restoring his livelihood","best":"Thanks to House Redoran getting these mines reopened, I can provide for my family again"},"Family":{"aff":85,"type":"familial","relation":"wife and children","note":"Primary motivation for enduring hardship and returning to mining work"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('eydis', '{"Skuli":{"aff":85,"type":"protective","relation":"son","note":"Shields him from the truth about his father''s disappearance with comforting lies","best":"Praising his capabilities to inn patrons","worst":"Contradicting herself about which side his father fights for"},"Leontius Salvius":{"aff":45,"type":"professional","relation":"employee","note":"Relies on him to help run the Old Hroldan Inn"},"Missing Husband":{"aff":15,"type":"estranged","relation":"husband","note":"Vanished under unknown circumstances; she fabricates stories about him fighting in the war","worst":"His disappearance left her alone to raise Skuli and run the inn without rest"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('faendal', '{"Camilla Valerius":{"aff":75,"type":"crush","relation":"romantic interest","note":"Harbors deep romantic feelings and schemes to win her from Sven","best":"She spoke to him kindly after the Golden Claw quest","worst":"She may never truly know his feelings"},"Sven":{"aff":-50,"type":"rival","relation":"romantic rival","note":"Despises the bard competing for Camilla''s affections","best":"Convinced Camilla that Sven''s letter was chauvinistic","worst":"Sven forged a racist letter in his name to turn Camilla against him"},"Gerdur":{"aff":25,"type":"professional","relation":"employer","note":"Works diligently at her lumber mill under her watchful eye"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('faida', '{"Gaius Maro":{"aff":85,"type":"romantic","relation":"lover","note":"Deeply attached to the Imperial Commander despite Nord-Imperial tensions","best":"He told her he carries her always in his heart before departing","worst":"Watching him leave on dangerous security inspections, not knowing if he''ll return"},"Julienne Lylvieve":{"aff":55,"type":"mentor","relation":"apprentice","note":"Patiently training Julienne in the innkeeping trade","best":"Telling Julienne she''ll make a fine innkeeper someday"},"Late Husband":{"aff":80,"type":"romantic","relation":"late husband","note":"Fondly remembers him and preserves his legacy through the tavern","best":"Meeting him at the Winking Skeever changed her life for the better"},"Corpulus Vinius":{"aff":45,"type":"familial","relation":"cousin","note":"Family connection to the Vinius family in Solitude"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('falas_selvayn', '{"Thieves Guild":{"aff":25,"type":"transactional","relation":"fence","note":"Discrete grey market connections for moving questionable merchandise","best":"Profitable exchange of fenced goods under mutual discretion","worst":"Any exposure of the connection would endanger both parties"},"Guard Patrols":{"aff":-35,"type":"suspicious","relation":"avoided authority","note":"Operates midnight to 5am specifically to minimize official scrutiny","worst":"Any prolonged attention from patrols could shut down his operation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('faldrus', '{"Azura":{"aff":90,"type":"fanatical","relation":"patron deity","note":"Devoutly worships Azura and undertakes sacred pilgrimage to her shrine","best":"Raising arms in praise upon reaching the Shrine of Azura"},"Aranea Ienith":{"aff":45,"type":"platonic","relation":"fellow worshipper","note":"Shares devotion to Azura and joins her at the shrine upon arrival"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('faleen', '{"Jarl Igmund":{"aff":85,"type":"protective","relation":"housecarl","note":"Sworn protector with unwavering loyalty, fiercely dedicated especially after Forsworn killed his father","best":"Standing vigil over his safety through peaceful times and political turmoil","worst":"Exiled to Solitude''s Blue Palace when Stormcloaks seized Markarth"},"Calcelmo":{"aff":65,"type":"romantic","relation":"romantic partner","note":"Initially dismissive of the court wizard, but reciprocated after receiving his heartfelt poem","best":"Reading his poem and discovering his hidden depth of feeling","worst":"Dismissively calling him an old coot obsessed with dead dwarves"},"Raerek":{"aff":40,"type":"professional","relation":"court colleague","note":"Collaborates on security but finds his caution frustrating","best":"Agreeing on measures that keep Markarth safe","worst":"Finding his cautious approach inadequate against Forsworn threats"},"Forsworn":{"aff":-85,"type":"nemesis","relation":"bitter enemy","note":"Vows they will pay with their blood for murdering Igmund''s father","worst":"Murdering Igmund''s father and threatening the Reach"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('falion', '{"Agni":{"aff":85,"type":"protective","relation":"apprentice and ward","note":"Took her in after her parents'' death; rejected vampirism to keep her safe","best":"Chose not to become a vampire to protect her","worst":"Fears his dark research could one day endanger her"},"Jonna":{"aff":55,"type":"familial","relation":"sister","note":"Their kinship is kept quiet due to town suspicion around him"},"Jarl Idgrod":{"aff":45,"type":"professional","relation":"patron","note":"Supports his presence in Morthal and ignores townspeople''s complaints","best":"Stood by him despite public mistrust"},"Morthal Residents":{"aff":-35,"type":"suspicious","relation":"townspeople","note":"Weave horrid tales about him and accuse him of sinister deeds","worst":"Accuse him of sacrificing children and eating hearts of the dead"},"College of Winterhold":{"aff":-75,"type":"estranged","relation":"former employer","note":"Left due to intense hatred of the institution","worst":"Came to despise the College and everything it represented"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('falk_firebeard', '{"Jarl Elisif the Fair":{"aff":85,"type":"protective","relation":"steward","note":"Loyally serves and subtly guides her development as ruler while she mourns Torygg","best":"Torygg entrusted him as steward","worst":"Must navigate her naive suggestions while respecting her authority"},"General Tullius":{"aff":60,"type":"professional","relation":"ally","note":"Coordinates Imperial military presence and city security with mutual respect"},"Bryling":{"aff":55,"type":"crush","relation":"rumored love interest","note":"Romantic interest maintained with careful professional discretion"},"Thane Erikur":{"aff":-35,"type":"contempt","relation":"rival court member","note":"Works to check his influence and suspects he spreads rumors about Elisif''s fitness to rule","worst":"Erikur undermines Elisif''s legitimacy with loose talk among the Thanes"},"Sybille Stentor":{"aff":25,"type":"suspicious","relation":"court colleague","note":"Maintains a cautious working relationship with the court wizard"},"Ulfric Stormcloak":{"aff":-80,"type":"nemesis","relation":"Torygg''s killer","note":"Murdered High King Torygg and now threatens Elisif''s rule and Solitude''s stability","worst":"Killed Torygg and forces Elisif into political subjugation if Stormcloaks win"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('falkreath_guard', '{"Jarl Siddgeir":{"aff":65,"type":"professional","relation":"direct superior","note":"Serves under Jarl Siddgeir with loyal duty as a Falkreath guard."},"Imperial Legion":{"aff":55,"type":"professional","relation":"former service","note":"Maintains positive connections from previous military service and shares Imperial equipment."},"Falkreath Guard":{"aff":70,"type":"platonic","relation":"fellow guards","note":"Close-knit brotherhood forged through shared duty and patrols."},"Bandits":{"aff":-75,"type":"enemy","relation":"enemies of the hold","note":"Adversarial relationship with those threatening Falkreath''s peace and citizens."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('falmer_servant', '{"Falmer":{"aff":90,"type":"fanatical","relation":"devoted servant","note":"Captured Dunmer who earned their trust and now serves with absolute loyalty","best":"Being accepted by the Falmer rather than becoming their slave or meal"},"Surface Dwellers":{"aff":-70,"type":"enemy","relation":"territorial foe","note":"Views all surface dwellers as threats to his Falmer masters and their territory","worst":"Being captured by the Falmer and dragged into the darkness"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fanari_strong-voice', '{"Skaf the Giant":{"aff":80,"type":"mentor","relation":"predecessor and mentor","note":"Mentored Fanari in leadership and Skaal traditions before she was chosen to succeed him.","best":"His patient guidance in the ways of leadership and ancient traditions"},"Storn Crag-Strider":{"aff":75,"type":"platonic","relation":"old friend and shaman","note":"Deeply respected former village shaman who sacrificed himself for the Skaal.","best":"Years of trusted counsel and friendship","worst":"His sacrifice, which she mourned as the loss of an old friend"},"Frea":{"aff":70,"type":"protective","relation":"trusted successor","note":"Believes Frea will guide the Skaal well and supports her development as a leader.","best":"Witnessing Frea step into her role as guide for the Skaal after Storn''s sacrifice"},"Deor Woodcutter":{"aff":45,"type":"platonic","relation":"fellow villager","note":"Knows his tendency to worry well, sometimes dismissing his concerns but tolerating him.","worst":"His persistent worrying that she sometimes finds exasperating"},"Tharstan":{"aff":55,"type":"platonic","relation":"friend","note":"Shares warm, teasing exchanges with the scholar, calling him sweet as honey.","best":"His willingness to bring her blue mountain flowers from the ruins"},"Skaal Villagers":{"aff":70,"type":"protective","relation":"her people","note":"Leads them with dedication, viewing herself as their voice and guardian.","best":"Being chosen by them to lead after Skaf''s passing"},"Bandits":{"aff":-70,"type":"enemy","relation":"threat to village","note":"Persistent threat to the village''s food supplies that she actively works to eliminate."},"The Dragonborn":{"aff":55,"type":"grateful","relation":"friend of the Skaal","note":"Initially skeptical outsider who earned her respect through helpful actions for the village.","best":"Being named friend to the Skaal after saving them from Miraak''s control"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('faralda', '{"Sergius Turrianus":{"aff":65,"type":"romantic","relation":"secret lover","note":"Secret romantic relationship complicated by Nirya''s competing interest"},"Nirya":{"aff":-45,"type":"rival","relation":"rival","note":"Competes for both professional advancement and Sergius''s affections","worst":"Nirya''s pursuit of Sergius undermines their professional relationship"},"Ancano":{"aff":-35,"type":"suspicious","relation":"colleague","note":"Suspects him of being a Thalmor spy"},"Mirabelle Ervine":{"aff":35,"type":"professional","relation":"superior","note":"Respects her competence but harbors ambitions for her position"},"Savos Aren":{"aff":45,"type":"professional","relation":"arch-mage","note":"Respects his wisdom and hopes he recognizes her talent"},"Tolfdir":{"aff":15,"type":"professional","relation":"colleague","note":"Surprised and dismissive of his unexpected promotion to Master Wizard"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('farengar_secret-fire', '{"Jarl Balgruuf the Greater":{"aff":50,"type":"patron","relation":"employer","note":"Serves as his court wizard and magical advisor with a strong sense of duty"},"Delphine":{"aff":35,"type":"suspicious","relation":"collaborator","note":"Mysterious partner in dragon research whose full motives he may not grasp"},"Proventus Avenicci":{"aff":15,"type":"professional","relation":"colleague","note":"Fellow advisor to the Jarl with a sometimes tense working relationship"},"Arcadia":{"aff":20,"type":"transactional","relation":"trade partner","note":"Occasionally trades alchemical supplies and sends frost salts her way"},"College of Winterhold":{"aff":30,"type":"professional","relation":"alma mater","note":"Maintains loose ties and directs prospective students their way"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('farkas', '{"Vilkas":{"aff":90,"type":"familial","relation":"twin brother","note":"Raised together at Jorrvaskr; Farkas defers to Vilkas''s intellect while Vilkas respects his strength","best":"Standing side by side as members of the Circle","worst":"Knowing Vilkas worries about his simplicity"},"Kodlak Whitemane":{"aff":85,"type":"mentor","relation":"father figure and Harbinger","note":"Farkas trusts Kodlak''s wisdom absolutely, even over his own feelings about lycanthropy","best":"Kodlak''s guidance and acceptance since childhood","worst":"Losing Kodlak and facing his funeral"},"Aela the Huntress":{"aff":65,"type":"platonic","relation":"Shield-Sister","note":"Fellow Circle member who teases him but respects his strength","best":"Fighting alongside her as Shield-Siblings"},"Skjor":{"aff":70,"type":"platonic","relation":"Shield-Brother","note":"Skjor saw Ysgramor''s strength in Farkas, a rare validation of his worth beyond brute force","best":"Skjor telling him he had the strength of Ysgramor","worst":"Losing Skjor"},"Jergen":{"aff":25,"type":"estranged","relation":"absent father","note":"Left his sons at Jorrvaskr and never returned from war; a distant, painful absence","worst":"Growing up without a father who never came back"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('farmhand', '{"Personal Steward":{"aff":30,"type":"professional","relation":"supervisor","note":"Direct supervisor who manages their employment and daily duties at Goldenhills"},"Fellow Farmhand":{"aff":45,"type":"platonic","relation":"co-worker","note":"Close working bond forged through shared labor in the fields"},"Farm Owner":{"aff":35,"type":"professional","relation":"employer","note":"Respectful gratitude toward the owner of Goldenhills Plantation for steady employment"},"Local Merchants":{"aff":10,"type":"transactional","relation":"trading partners","note":"Regular but impersonal interactions for selling crops and purchasing supplies"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('faryl_atheron', '{"Aval Atheron":{"aff":30,"type":"familial","relation":"brother","note":"Aval is ashamed that Faryl works for Nords; Faryl finds his complaints tiresome","worst":"Endless harping about injustices while Faryl just tries to earn a living"},"Suvaris Atheron":{"aff":65,"type":"familial","relation":"sister","note":"Both work for Nords and share pragmatic understanding of their situation","best":"Shared solidarity as Dunmer siblings navigating Nord employers"},"Bolfrida Brandy-Mug":{"aff":25,"type":"professional","relation":"employer","note":"Grating personality but pays well; Faryl tolerates her clueless farming ideas","best":"Steady pay that keeps the family fed","worst":"Suggesting fire salts to plow frozen soilâ€”salted earth grows nothing"},"Rolff Stone-Fist":{"aff":-65,"type":"enemy","relation":"racist antagonist","note":"Regularly endures his loud racist insults in the Gray Quarter at night","worst":"Nightly verbal abuse while wandering Windhelm''s streets"},"Gray Quarter Community":{"aff":35,"type":"platonic","relation":"fellow Dunmer","note":"Maintains connections despite his integration with Nord society","best":"Shared cultural identity at New Gnisis Cornerclub"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fastred', '{"Bassianus Axius":{"aff":75,"type":"romantic","relation":"love interest","note":"Infatuated with him; says he makes her happier than anyone ever has","best":"He promised her an exciting new life in Riften"},"Klimmek":{"aff":50,"type":"romantic","relation":"former love","note":"Previously in love with him; torn between him and Bassianus","best":"Touched when he declared he would miss her"},"Jofthor":{"aff":25,"type":"familial","relation":"father","note":"Stern and restrictive; opposes her leaving Ivarstead","worst":"Berates her to work harder and refuses to let her go"},"Boti":{"aff":45,"type":"familial","relation":"mother","note":"More understanding than her father but still not actively helpful","best":"Shows some sympathy for her romantic desires"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('felldir_the_old', '{"Gormlaith Golden-Hilt":{"aff":85,"type":"platonic","relation":"shield-sister","note":"Trusted fellow Tongue and companion in the war against Alduin","best":"Fighting side by side against dragonkind","worst":"Watching Alduin seize and kill her at the Throat of the World"},"Hakon One-Eye":{"aff":65,"type":"platonic","relation":"brother-in-arms","note":"Respected ally but clashed over the Elder Scroll plan","best":"Standing united against Alduin at the Throat of the World","worst":"Defying Hakon''s wishes by revealing and using the Elder Scroll"},"Alduin":{"aff":-95,"type":"nemesis","relation":"the World-Eater","note":"Banished Alduin through time; burned for revenge across a hundred lifetimes","best":"Successfully casting Alduin out of the current age with the Elder Scroll","worst":"Witnessing Gormlaith''s death at Alduin''s jaws"},"Last Dragonborn":{"aff":75,"type":"protective","relation":"prophesied ally","note":"Counseled and fought alongside the Dragonborn to finally defeat Alduin in Sovngarde","best":"Joining Voices together to shatter Alduin''s mist and end him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fenrig', '{"Ruki":{"aff":100,"type":"romantic","relation":"wife","note":"Searched for each other across centuries after his death, finally reunited and ascended together into the stars","best":"Reunited with Ruki and rising together to spend eternity among the stars","worst":"Dying before the battle, separated from Ruki for centuries"},"Gjukar":{"aff":40,"type":"professional","relation":"commanding officer","note":"Served loyally in his company but disagreed with his tactical decisions","worst":"Gjukar chose to camp in a vulnerable low valley with visible fires"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('feral_vampire', '{"Lord Harkon":{"aff":-10,"type":"estranged","relation":"former master","note":"Once served him but no longer recognizes any authority due to feral degeneration","worst":"Lost all recognition of her former master to bloodlust"},"Castle Volkihar Vampires":{"aff":-40,"type":"estranged","relation":"former court","note":"Viewed as a cautionary tale; attacks them with indiscriminate violence","worst":"Confined to the castle''s lower chambers as a living warning"},"Death Hounds":{"aff":15,"type":"neutral","relation":"tolerated presence","note":"Only creatures she does not attack in her territory"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('feran_sadri', '{"Ronthil":{"aff":25,"type":"mentor","relation":"apprentice","note":"Mentors with stern detachment; values his assistance but views him as inferior"},"Lord Harkon":{"aff":15,"type":"transactional","relation":"court lord","note":"Serves primarily for access to resources and research support, not loyalty"},"Garan Marethi":{"aff":30,"type":"professional","relation":"fellow Dunmer vampire","note":"Maintains professional courtesy grounded in shared Dark Elf heritage"},"Serana":{"aff":40,"type":"curious","relation":"ancient vampire","note":"Fascinated by her ancient bloodline and its research potential","best":"Her return to Volkihar presents unprecedented research opportunities"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('festus_krex', '{"Babette":{"aff":55,"type":"platonic","relation":"fellow assassin","note":"Shares interest in alchemy and enjoys dark humor together","best":"Laughing together at Arnbjorn''s stories"},"College of Winterhold":{"aff":-25,"type":"contempt","relation":"former employer","note":"Left after two years, finding academic life too restrictive and simple","worst":"Found none there truly understood the glory of Destruction magic"},"Dark Brotherhood":{"aff":70,"type":"familial","relation":"family","note":"Considers members family despite gruff criticism","best":"Laughing and sharing stories with fellow assassins"},"Arnbjorn":{"aff":40,"type":"rival","relation":"fellow assassin","note":"Mock each other but share dark laughter","best":"Laughing together at absurd kill stories","worst":"Arnbjorn mocking his magical methods"},"Player":{"aff":35,"type":"platonic","relation":"fellow assassin","note":"Initially dismissive but grows to respect their abilities","best":"Acknowledging the Player''s proven worth","worst":"Dismissive gruff greeting on first meeting"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fethis_alor', '{"Dreyla Alor":{"aff":75,"type":"familial","relation":"daughter","note":"Primary family connection; he stayed in Raven Rock partly for her sake","best":"Sharing breakfast together each morning before work"},"Miraak":{"aff":-85,"type":"enemy","relation":"mind controller","note":"Forced Fethis to build a shrine at the Earth Stone against his will","worst":"Being enslaved to build that shrine, unable to control my own actions"},"East Empire Company":{"aff":50,"type":"professional","relation":"former business associate","note":"Maintains correspondence and hopes for their return to Raven Rock","best":"Corresponding with Vittoria Vici about the company''s future on Solstheim"},"Glover Mallory":{"aff":40,"type":"professional","relation":"business contact","note":"Provides special deals Fethis cannot pass up"},"Gjalund Salt-Sage":{"aff":35,"type":"transactional","relation":"primary supplier","note":"Brings most of Fethis''s supplies via his ship from the docks"},"House Redoran":{"aff":-25,"type":"suspicious","relation":"governing authority","note":"Doubts they will continue supporting Raven Rock if the mine fails again","worst":"Being ignored by House Redoran after the ebony ran out the first time"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fianna', '{"Gerda":{"aff":55,"type":"platonic","relation":"fellow maid","note":"Daily working companion sharing the endless task of keeping Dragonsreach clean"},"Jarl Balgruuf":{"aff":70,"type":"servant","relation":"employer","note":"Serves with unwavering loyalty and considers him the only one truly high and mighty"},"Dragonsreach Guards":{"aff":-25,"type":"contempt","relation":"castle guards","note":"Resents their constant tracking of dirt and failure to pick up after themselves","worst":"Soldiers everywhere, not a one knowing how to pick up after themselves"},"Proventus Avenicci":{"aff":30,"type":"professional","relation":"Jarl''s steward","note":"Professional respect for the steward''s position in the castle hierarchy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fihada', '{"Jawanan":{"aff":75,"type":"mentor","relation":"apprentice","note":"Patient mentor who teaches bow-crafting and shares wisdom from his ranger days","best":"Jawanan defended his skill to Odar, recalling his 500-pace kill shot"},"Vivienne Onis":{"aff":55,"type":"crush","relation":"flirtation","note":"Regular flirtatious exchanges at the Winking Skeever where she welcomes his attention"},"Odar":{"aff":-25,"type":"contempt","relation":"detractor","note":"Odar calls him a fop and is unimpressed by his charm; mutual disdain","worst":"Odar dismissed him as a fop to Jawanan''s face"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('filnjar', '{"Grogmar gro-Burzag":{"aff":45,"type":"platonic","relation":"colleague","note":"Fellow Shor''s Stone resident and miner; both nearly killed by the spider infestation together","best":"Survived the spider attack side by side","worst":"Nearly killed when frostbite spiders overran the mine"},"Sylgja":{"aff":30,"type":"platonic","relation":"neighbor","note":"Fellow resident of Shor''s Stone and regular customer at his forge"},"Hafjorg":{"aff":25,"type":"transactional","relation":"trade partner","note":"Sends ore samples to her at Elgrim''s Elixirs in Riften","best":"Completed the ore sample delivery arrangement"},"Elgrim":{"aff":10,"type":"transactional","relation":"business associate","note":"Considers him forgetful and dependent on his wife","worst":"Waited weeks for Elgrim to follow up on the ore sample letter"},"Shor''s Stone Miners":{"aff":55,"type":"protective","relation":"unofficial leader","note":"Takes responsibility for the mining community''s welfare and advocates on their behalf","best":"Working to clear Redbelly Mine and restore their livelihood","worst":"Unable to protect them from the spider infestation shutting down the mine"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fire_mage', '{"College of Winterhold":{"aff":-65,"type":"estranged","relation":"former institution","note":"Expelled for dangerous experimental practices; views their teachings as restrictive and inferior","worst":"Being cast out for pushing beyond the College''s cowardly limits"},"Warlock Coven":{"aff":40,"type":"professional","relation":"coven member","note":"Advanced through ranks via magical prowess and ruthless ambition; alliance built on power, not trust","best":"Rising to Adept through demonstrations of superior fire magic"},"Apprentice Fire Mages":{"aff":25,"type":"mentor","relation":"informal mentor","note":"Teaches lesser pyromancers despite viewing most as inferior; values those who show genuine potential"},"Rival Warlock Covens":{"aff":-45,"type":"rival","relation":"competitors","note":"Seeks to establish dominance over rival covens through superior magical ability"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fire_mage_adept', '{"College of Winterhold":{"aff":-45,"type":"estranged","relation":"former institution","note":"Abandoned the College''s academic approach in favor of unrestricted warlock practices","worst":"Rejected their restrictive teachings and left behind traditional magical study"},"Fellow Warlocks":{"aff":40,"type":"professional","relation":"coven allies","note":"Loose alliance founded on mutual respect for raw magical power and shared outlaw status"},"Apprentice Fire Mages":{"aff":30,"type":"mentor","relation":"informal mentor","note":"Takes lesser pyromancers under their wing despite general contempt for most people"},"Local Settlements":{"aff":-60,"type":"contempt","relation":"raid targets","note":"Views settlements only as sources of supplies and artifacts to take by force"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fire_wizard', '{"College of Winterhold":{"aff":-55,"type":"estranged","relation":"former institution","note":"Abandoned and subsequently banned for pursuing forbidden destructive research","worst":"Expelled and branded dangerous for pushing beyond acceptable magical limits"},"Vigilants of Stendarr":{"aff":-90,"type":"nemesis","relation":"witch hunters","note":"Actively hunted for practicing forbidden and destructive magic","worst":"Branded a warlock to be purged without mercy"},"Apprentice Fire Mages":{"aff":15,"type":"mentor","relation":"apprentices","note":"Commands obedience from lesser practitioners seeking forbidden knowledge","best":"Promising students who show true dedication to the flame"},"Other Warlocks":{"aff":10,"type":"transactional","relation":"outcast allies","note":"Loose alliance of convenience trading knowledge and artifacts"},"Local Settlements":{"aff":-40,"type":"contempt","relation":"nearby villages","note":"Views inhabitants as inferior beings and potential test subjects","worst":"Villagers fleeing in terror at the sight of blackened hands"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('firir', '{"Eydis":{"aff":85,"type":"romantic","relation":"beloved","note":"Wrote his final apologetic note to her before dying in Chillwind Depths","best":"Planning to build a life together","worst":"Leaving her behind by dying on his investigation"},"Falmer":{"aff":-100,"type":"enemy","relation":"killers","note":"Killed him in Chillwind Depths during his investigation of the caravan attack","worst":"Being captured and killed in a Falmer cage"},"Local Merchants":{"aff":50,"type":"platonic","relation":"trading partners","note":"Regularly traded crops with and offered shelter to traveling merchants","best":"Offering shelter to merchants during harsh weather"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('first_mate', '{"Captain":{"aff":75,"type":"professional","relation":"superior officer","note":"Serves with unwavering loyalty as second-in-command aboard the Dainty Sload","best":"Earned the captain''s trust through proven combat and leadership"},"Crew Members":{"aff":15,"type":"professional","relation":"subordinates","note":"Keeps discipline through intimidation and harsh enforcement","worst":"Regularly resorts to threats of violence to maintain order"},"Solitude Guards":{"aff":-45,"type":"enemy","relation":"law enforcement","note":"Antagonistic relationship managed through careful avoidance and bribery","worst":"Constant threat of arrest forces cautious operations near Solitude"},"Local Fence Network":{"aff":35,"type":"transactional","relation":"business contacts","note":"Professional contacts for disposing of pirated goods"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fisherman', '{"Local Guards":{"aff":-35,"type":"suspicious","relation":"law enforcement","note":"Tense relationship due to poaching activities","worst":"Caught and fined for poaching"},"Fellow Fishermen":{"aff":45,"type":"platonic","relation":"peer network","note":"Loose network of mutual support and information sharing","best":"Sharing fishing spots and techniques"},"Wealthy Landowners":{"aff":-55,"type":"contempt","relation":"landed elite","note":"Disdain for their claimed exclusive hunting rights","worst":"Denied access to traditional fishing waters"},"Local Tavern Owners":{"aff":25,"type":"transactional","relation":"trade partner","note":"Regular seller of fresh fish and game"},"Poor Villagers":{"aff":55,"type":"protective","relation":"community","note":"Share excess catch with those in need","best":"Giving fish to hungry families"},"Jarl":{"aff":-45,"type":"suspicious","relation":"regional authority","note":"Resists authority restricting common hunting rights","worst":"Jarl''s guards enforcing poaching laws"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fjola', '{"Christer":{"aff":-25,"type":"estranged","relation":"ex-husband","note":"Abandoned him to pursue her own path; doesn''t hate him but refuses to ever return","worst":"Feeling trapped in an unfulfilling conventional marriage"},"Mistwatch Bandits":{"aff":55,"type":"professional","relation":"followers","note":"Proved herself through combat and rose to lead them; commands their loyalty and respect"},"Player":{"aff":45,"type":"grateful","relation":"benefactor","note":"Owes a debt if helped resolve the situation with Christer peacefully","best":"Being freed from Christer''s pursuit and given back her autonomy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fjori', '{"Holgeir":{"aff":100,"type":"romantic","relation":"husband","note":"Beloved warlord whose mutual combat respect blossomed into a legendary romance that transcended death itself.","best":"Their union brokered peace between warring clans and brought them profound happiness.","worst":"Holgeir was felled by a poisonous snake bite, prompting Fjori''s desperate journey to Akavir for a cure."},"Lu''ah Al-Skaven":{"aff":-85,"type":"enemy","relation":"captor","note":"Necromancer who raised Fjori and Holgeir as undead draugr, binding them against their will.","worst":"Forcibly conscripted into undeath and compelled to fight against all she once protected."},"Forest Clans":{"aff":65,"type":"protective","relation":"ward and peacemaker","note":"The warring factions she and Holgeir united through their marriage, whom she still seeks to shield even in death."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fjotra', '{"Enmon":{"aff":85,"type":"familial","relation":"adoptive father","note":"Loving father who supported her divine calling despite it meaning she must leave home","best":"Reuniting after her rescue, hearing him call her his little girl","worst":"Having to leave him and her mother behind for the Temple"},"Mena":{"aff":75,"type":"familial","relation":"adoptive mother","note":"Breton mother who raised her in Karthwasten; parting is bittersweet"},"Forsworn":{"aff":-80,"type":"fearful","relation":"captors","note":"Kidnapped her due to her religious significance and held her at Broken Tower Redoubt","worst":"Being imprisoned and fearing they would hurt her"},"Temple of Dibella Priestesses":{"aff":70,"type":"student","relation":"future mentors","note":"Eager to learn from them and fulfill her role as Sybil","best":"Anticipating the wonders of the great Temple in Markarth"},"Dibella":{"aff":95,"type":"servant","relation":"divine patron","note":"Chosen by divine providence as the next Sybil; deeply honored by the calling","best":"Learning it was true she is touched by the gods"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('florentius_baenius', '{"Arkay":{"aff":95,"type":"fanatical","relation":"deity and divine patron","note":"Claims direct communication with Arkay and attributes all major decisions to divine guidance","best":"Arkay sent a rescuer just when he prayed for deliverance from Ruunvald"},"Isran":{"aff":20,"type":"professional","relation":"Dawnguard leader","note":"Strained working relationship marked by Isran''s mockery and dismissal of his divine claims","worst":"Isran mocked his connection to Arkay and never gave him the respect he felt he deserved"},"Sorine Jurard":{"aff":45,"type":"platonic","relation":"fellow Dawnguard member","note":"Colleague who finds his divine conversations amusing rather than offensive"},"Gunmar":{"aff":45,"type":"platonic","relation":"fellow Dawnguard member","note":"Colleague who frequently discusses his claims of speaking with Arkay"},"Minorne":{"aff":-85,"type":"enemy","relation":"former captor","note":"Warlock who imprisoned him at Ruunvald using enchantments","worst":"Held prisoner at Ruunvald under Minorne''s thrall"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('forsworn', '{"Madanach":{"aff":92,"type":"fanatical","relation":"imprisoned king","note":"Revered leader known as the King in Rags, secretly held in Cidhna Mine by the Silver-Bloods","best":"Ruled the Reach peacefully for two years under his leadership"},"Hagravens":{"aff":65,"type":"awed","relation":"spiritual matriarchs","note":"Revered leaders who guide spiritual practices and perform the Briarheart transformation","worst":"The Briarheart ritual costs warriors their will and humanity"},"Silver-Blood Family":{"aff":-90,"type":"nemesis","relation":"oppressors","note":"Bitter enemies who control Markarth and leverage Madanach''s imprisonment","worst":"Thonar Silver-Blood secretly imprisoned Madanach in Cidhna Mine"},"Ulfric Stormcloak":{"aff":-95,"type":"nemesis","relation":"conqueror","note":"Led the Nord militia that violently retook Markarth and ended Reachmen rule","worst":"Used the Thu''um to shout Reachmen from the walls of Markarth"},"Nords":{"aff":-85,"type":"nemesis","relation":"invaders and occupiers","note":"Hated for centuries of occupation and the brutal atrocities after the Markarth Incident","worst":"Captured Reachmen were tortured and executed regardless of allegiance"},"Empire":{"aff":-75,"type":"enemy","relation":"foreign occupiers","note":"Abandoned the Reach during the Great War, then helped Ulfric retake it"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('forsworn_forager', '{"Local Hagraven":{"aff":45,"type":"professional","relation":"ritual supplier and spiritual guide","note":"Provides gathered ingredients for rituals and receives guidance on sacred plants"},"Forsworn":{"aff":65,"type":"familial","relation":"tribe","note":"Respected for knowledge but kept at arm''s length due to frequent solitary absences"},"Mother":{"aff":80,"type":"familial","relation":"mother and mentor","note":"Skilled herbalist who taught them gathering and foraging traditions","best":"Learning the ways of the Reach''s flora at her side"},"Nords":{"aff":-70,"type":"enemy","relation":"oppressors","note":"Opposes all Nords for the Markarth Incident and ongoing persecution of Reachmen","worst":"The cruelty and displacement following the Markarth Incident"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('forsworn_looter', '{"Madanach":{"aff":85,"type":"fanatical","relation":"imprisoned king","note":"Views the King in Rags with near-religious devotion and seeks his freedom above all"},"Hagravens":{"aff":75,"type":"awed","relation":"spiritual matriarchs","note":"Revered leaders who provide magical enhancement and guide the camp''s rituals"},"Forsworn Camp":{"aff":65,"type":"platonic","relation":"warrior band","note":"Tight-knit comrades bound by shared trauma and commitment to the cause"},"Nords":{"aff":-85,"type":"enemy","relation":"invaders","note":"Hated occupiers to be driven from the Reach at any cost","worst":"Witnessed family executed during the Nord purge of Markarth"},"Ulfric Stormcloak":{"aff":-95,"type":"nemesis","relation":"family''s killer","note":"Personally responsible for the violence that destroyed their family and life","worst":"Led the militia that slaughtered their family during the reclamation of Markarth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('forsworn_pillager', '{"Madanach":{"aff":75,"type":"fanatical","relation":"revered leader","note":"Reveres the King in Rags as the Forsworn''s rightful leader, though direct contact is rare due to his imprisonment."},"Hagraven Matriarch":{"aff":80,"type":"fanatical","relation":"spiritual leader","note":"Devoted follower who reveres the hagravens as matriarchs and sources of dark power and ritual knowledge."},"Fellow Forsworn Raiders":{"aff":85,"type":"platonic","relation":"warrior kin","note":"Close-knit bonds forged through shared hardship and combat against a common enemy."},"Briarheart Warriors":{"aff":55,"type":"awed","relation":"superior warriors","note":"Respects and fears these transformed vengeance spirits who lead individual Forsworn cells."},"Ulfric Stormcloak":{"aff":-100,"type":"nemesis","relation":"sworn enemy","note":"Lost family members during Ulfric''s violent reclamation of Markarth using the Thu''um.","worst":"The slaughter and expulsion from Markarth when Ulfric shouted them from the city walls"},"Silver-Blood Family":{"aff":-90,"type":"enemy","relation":"hated oppressors","note":"Despises the Silver-Bloods for exploiting the Reach''s resources and secretly imprisoning Madanach."},"Nord Settlers":{"aff":-85,"type":"enemy","relation":"invaders","note":"Views all Nords in the Reach as occupiers to be terrorized and driven out."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('forsworn_ravager', '{"Madanach":{"aff":85,"type":"fanatical","relation":"revered leader","note":"Devoted follower who views Madanach as both the spiritual and political soul of the Forsworn cause","best":"Fighting under Madanach''s orders gives purpose to years of suffering","worst":"Knowing Madanach rots in Cidhna Mine while the movement bleeds"},"Hagraven Matriarch":{"aff":70,"type":"mentor","relation":"spiritual advisor","note":"Source of magical enhancement and keeper of the old rites; revered as a living conduit to the Old Gods","best":"Receiving ancient Reach magic and blessings during ritual ceremonies"},"Silver-Blood Family":{"aff":-90,"type":"nemesis","relation":"hated oppressors","note":"Thonar imprisoned Madanach and the Silver-Bloods exploit Reachmen labor in Cidhna Mine","worst":"Parents executed by Nord militia backed by Silver-Blood interests"},"Markarth Guards":{"aff":-80,"type":"enemy","relation":"occupying force","note":"Living symbols of Nord oppression and the violent retaking of the Reach","worst":"Witnessing parents'' execution at the hands of Nord militia"},"Forsworn Brothers and Sisters":{"aff":65,"type":"platonic","relation":"battle companions","note":"Bound by shared trauma, shared struggle, and the dream of a free Reach"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fort_commander', '{"Imperial Legion":{"aff":75,"type":"professional","relation":"sworn faction","note":"Dedicated career soldier who rose through the ranks through loyal service"},"Fort Garrison":{"aff":55,"type":"professional","relation":"subordinates","note":"Maintains strict discipline while showing pragmatic flexibility in command"},"Legate Rikke":{"aff":65,"type":"professional","relation":"superior officer","note":"Reports to her on fort operations and regional security matters"},"General Tullius":{"aff":70,"type":"professional","relation":"supreme commander","note":"Ultimate superior officer in Skyrim, unwavering loyalty to his chain of command"},"Local Civilians":{"aff":25,"type":"neutral","relation":"local population","note":"Maintains formal but fair relationships with nearby settlements"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fox', '{"Spriggans":{"aff":45,"type":"protective","relation":"forest ally","note":"Natural allies who sometimes provide protection in the deepest woods"},"Hunters":{"aff":-65,"type":"fearful","relation":"hunted prey","note":"Cautious adversaries who prize its pelt","worst":"Relentless pursuit by those seeking its lustrous fur"},"Local Children":{"aff":35,"type":"curious","relation":"occasional playmate","note":"Occasionally allows trusted children brief glimpses before vanishing","best":"Playful near-encounters with harmless little ones"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frabbi', '{"Kleppr":{"aff":-20,"type":"rival","relation":"husband","note":"Contentious marriage defined by constant verbal sparring and mutual criticism, yet they maintain the business together","best":"Running the Silver-Blood Inn successfully as partners for years","worst":"Trading insults dailyâ€”''pig-headed oaf'' and ''venomous wife''"},"Hreinn":{"aff":85,"type":"familial","relation":"son","note":"Clearly favored child, frequently praised and held up as superior to his father","best":"Boasting to guests that Hreinn is a good worker, unlike his father"},"Hroki":{"aff":45,"type":"familial","relation":"daughter","note":"More neutral relationship compared to her brother"},"Silver-Blood Family":{"aff":15,"type":"transactional","relation":"landlords","note":"Business associates who own the inn building"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fralia_gray-mane', '{"Eorlund Gray-Mane":{"aff":90,"type":"romantic","relation":"husband","note":"Deeply proud of her husband''s legendary skill at the Skyforge","best":"Hearing Eorlund praised as the finest blacksmith in Skyrim","worst":"Losing Eorlund to death, leaving the Skyforge cold"},"Thorald Gray-Mane":{"aff":95,"type":"familial","relation":"son","note":"Refuses to believe he is dead despite all claims to the contrary","best":"Feeling in her heart that Thorald still lives","worst":"Being told by the Battle-Borns that her son chose poorly and is gone"},"Avulstein Gray-Mane":{"aff":80,"type":"familial","relation":"son","note":"Her son who remains in hiding during the civil war"},"Olfina Gray-Mane":{"aff":75,"type":"familial","relation":"daughter","note":"Helps maintain the family''s standing in Whiterun"},"Battle-Born Clan":{"aff":-70,"type":"enemy","relation":"bitter rivals","note":"Despises their arrogance and their dismissal of Thorald''s fate","worst":"Olfrid and Idolaf mocking her grief and telling her to accept Thorald''s death"},"Companions":{"aff":45,"type":"professional","relation":"respected associates","note":"Connected through Eorlund''s work at the Skyforge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('francois_beaufort', '{"Grelod the Kind":{"aff":-85,"type":"enemy","relation":"headmistress","note":"Abusive caretaker he fears and despises","worst":"Daily verbal and physical abuse, crushing any hope of adoption"},"Constance Michel":{"aff":65,"type":"protective","relation":"caretaker","note":"The only kind adult at the orphanage who offers what protection she can"},"Aventus Aretino":{"aff":55,"type":"platonic","relation":"fellow orphan","note":"Supports his dark plan to eliminate Grelod","best":"Aventus summoned the Dark Brotherhood and actually pulled it off"},"Runa":{"aff":45,"type":"platonic","relation":"fellow orphan","note":"Bonded through shared hardship under Grelod''s cruelty"},"Hroar":{"aff":45,"type":"platonic","relation":"fellow orphan","note":"Bonded through shared hardship under Grelod''s cruelty"},"Samuel":{"aff":45,"type":"platonic","relation":"fellow orphan","note":"Bonded through shared hardship under Grelod''s cruelty"},"Parents":{"aff":30,"type":"estranged","relation":"parents","note":"Still clings to hope they will return as promised despite likely abandonment","worst":"Left him at Honorhall and never came back"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frea', '{"Storn Crag-Strider":{"aff":90,"type":"familial","relation":"father and mentor","note":"Beloved father training her to succeed him as Skaal shaman","best":"Learning the spiritual and warrior traditions under his guidance","worst":"Eventually losing him and bearing the weight of his mantle"},"Skaal Villagers":{"aff":75,"type":"protective","relation":"protector and future shaman","note":"Deeply committed to defending her people and preserving their way of life","best":"Fashioning her amulet to resist Miraak''s influence","worst":"Watching her people enslaved to Miraak''s will at the Stones"},"Miraak":{"aff":-90,"type":"nemesis","relation":"sworn enemy","note":"Seeks to destroy his influence and free Solstheim from his corruption","worst":"His enslavement of the Skaal and corruption of the All-Maker''s Stones"},"Last Dragonborn":{"aff":55,"type":"platonic","relation":"ally","note":"Potential ally who must prove themselves trustworthy against Miraak","best":"Joining forces to uncover and oppose Miraak''s power"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('freir', '{"Rorlund":{"aff":85,"type":"romantic","relation":"husband","note":"Beloved husband and high priest; they share both marriage and ministerial duties at the Temple of the Divines","best":"Rising together through religious training to prominent positions within the Temple"},"Silana Petreia":{"aff":65,"type":"mentor","relation":"acolyte","note":"Mentors the younger priestess with patience and wisdom, encouraging her compassion for the poor","best":"Affirming Silana''s compassion as a blessing from Kynareth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frida', '{"Thoring":{"aff":65,"type":"platonic","relation":"old friend","note":"Trusted confidant at the Windpeak Inn who shares memories of her late husband","best":"Shared a toast to her husband''s memory together"},"Karita":{"aff":45,"type":"platonic","relation":"evening companion","note":"Bard at the Windpeak Inn who provides news and entertainment during Frida''s nightly visits"},"Brina Merilis":{"aff":70,"type":"professional","relation":"political ally","note":"Actively supports her as the right leader for Dawnstar over Skald","best":"Brina became Jarl and brought stability to Dawnstar"},"Deceased Husband":{"aff":90,"type":"romantic","relation":"late husband","note":"Died searching for the Ring of Pure Mixtures; she honors his memory through the shop","best":"Called me his pretty Juniper while gathering ingredients together","worst":"Frost took him before he could find the ring"},"Skald the Elder":{"aff":-35,"type":"contempt","relation":"Jarl of Dawnstar","note":"Considers him a fool for blindly worshipping Ulfric Stormcloak"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fridrika', '{"Geimund":{"aff":75,"type":"romantic","relation":"husband","note":"She deeply respects him and defers to him in all business matters."},"Horm":{"aff":80,"type":"familial","relation":"son","note":"She works to secure a stable future for him in the family business."},"Legate Rikke":{"aff":35,"type":"platonic","relation":"friend","note":"Marked as a friend in official records, though the connection remains unexplained."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frightened_woman', '{"Mistwatch Bandits":{"aff":-85,"type":"enemy","relation":"captors","note":"Held her captive for weeks at Mistwatch; she escaped by picking the lock while the guard slept","worst":"Weeks of imprisonment and fear at their hands"},"Player":{"aff":45,"type":"grateful","relation":"benefactor","note":"Grateful stranger who pointed her toward safety; she asked them to stop the bandits","best":"Showed her the way to town when she was lost and desperate"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frodnar', '{"Gerdur":{"aff":70,"type":"familial","relation":"mother","note":"Loves her but resents being told to work at the mill","best":"She provides a secure home and cares for him","worst":"She hushes him and tries to make him work at the mill"},"Hod":{"aff":80,"type":"familial","relation":"father","note":"Warm relationship; Hod actively encourages his pranks and mischief","best":"Hod laughs at his pranks and says ''That''s my boy!''"},"Ralof":{"aff":90,"type":"admirer","relation":"uncle","note":"Idolizes Ralof and dreams of joining the Stormcloaks like him","best":"Ralof tells him he''ll soon be old enough to join the fight himself"},"Dorthe":{"aff":55,"type":"platonic","relation":"best friend","note":"Close friends but she disapproves of his mean pranks","best":"Playing tag and adventuring together around Riverwood","worst":"She calls him mean and refuses his prank ideas"},"Stump":{"aff":85,"type":"protective","relation":"pet dog","note":"Loyal companion who follows him everywhere and joins his adventures"},"Hadvar":{"aff":-25,"type":"suspicious","relation":"Imperial soldier","note":"Distrusts him as an enemy of the Stormcloak cause his family supports"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frofnir_trollsbane', '{"Trolls":{"aff":-100,"type":"nemesis","relation":"sworn enemies","note":"Fanatical obsession drove his entire life after losing family to a troll attack","best":"Numerous successful troll hunts across Skyrim''s wilderness","worst":"Killed by trolls in their den near Cradle Stone Tower"},"Fellow Bandits":{"aff":35,"type":"professional","relation":"bandit comrades","note":"Respected his combat prowess but considered him unstable due to his troll obsession"},"Local Settlements":{"aff":15,"type":"transactional","relation":"protector and extortionist","note":"Offered troll protection services but demanded steep payment"},"Hunters Guild":{"aff":25,"type":"professional","relation":"occasional collaborator","note":"Worked together on occasion but never officially joined"},"Family":{"aff":80,"type":"familial","relation":"lost kin","worst":"Family members killed by a troll attack in his youth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('froki_whetted-blade', '{"Haming":{"aff":90,"type":"protective","relation":"grandson","note":"Raised after Helgen; Froki sees him as a second chance at fatherhood","best":"Haming survived Helgen and came to live with him","worst":"The boy lost his parents because Froki couldn''t protect them"},"Torolf":{"aff":55,"type":"estranged","relation":"deceased son","note":"Died at Helgen; Froki admits he wasn''t a great father the first time","worst":"Never made things right before Torolf was killed"},"Matlara":{"aff":40,"type":"familial","relation":"deceased daughter-in-law","note":"Haming''s mother, perished at Helgen alongside Torolf"},"Kyne":{"aff":100,"type":"fanatical","relation":"patron deity","note":"Devoted keeper of Kyne''s Sacred Trials; refuses the Imperial Kynareth as a pale shadow","best":"Preserving her Sacred Trials and passing them to worthy hunters"},"Temple Priests":{"aff":-70,"type":"contempt","relation":"religious opponents","note":"Views them as sycophants promoting stolen idols and imposter gods","worst":"Their false worship erodes the old Nordic traditions"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('from-deepest-fathoms', '{"Watches-The-Roots":{"aff":15,"type":"professional","relation":"expedition leader","note":"Followed him into Avanchnzel; his obsession with the Lexicon led the group to ruin","best":"Trusted him enough to join the expedition for the pay","worst":"His fixation on the Lexicon cost them everything"},"Drennen":{"aff":-25,"type":"contempt","relation":"former companion","note":"Dismissed him as a coward when he fled Avanchnzel","worst":"Called him a fool and a field mouse for wanting to turn back"},"Breya":{"aff":20,"type":"professional","relation":"former companion","note":"Bickered during the expedition but shared the same doomed fate","best":"Fought alongside her deeper into the ruin","worst":"Dismissed her fear that they would die in Avanchnzel"},"Riften Fishery Workers":{"aff":5,"type":"neutral","relation":"dockside acquaintances","note":"Barely interacts; too consumed by trauma to connect"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frorkmar_banner-torn', '{"Ulfric Stormcloak":{"aff":92,"type":"fanatical","relation":"revered commander","note":"Views Ulfric as the only true High King and the truest of all Nords; absolute zealous devotion to his cause.","best":"Hearing Ulfric''s call to arms and finding purpose in the Stormcloak rebellion."},"Skald the Elder":{"aff":58,"type":"professional","relation":"Jarl and civil superior","note":"Serves as military advisor and commander under Skald''s civil authority in The Pale."},"Brina Merilis":{"aff":-68,"type":"rival","relation":"rival for Dawnstar","note":"Imperial-aligned veteran who would replace Skald and displace Stormcloak control if the Pale falls."},"Thalmor":{"aff":-96,"type":"nemesis","relation":"hated oppressors","note":"Sees the Thalmor as oppressors of Nordic culture and religion; vows to rid Skyrim of them and their Justiciars.","worst":"The White-Gold Concordat banning Talos worship, which shattered his world."},"Imperial Legion":{"aff":-78,"type":"enemy","relation":"opposing army","note":"Despises the Empire for surrendering to the Thalmor and selling out Nordic gods; his epithet ''Banner-Torn'' marks his severance from their ranks.","worst":"Witnessing the Empire capitulate to the Thalmor and outlaw Talos worship."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frost', '{"Maven Black-Briar":{"aff":-15,"type":"transactional","relation":"former owner","note":"Valued him only as a status symbol and possession"},"Sibbi Black-Briar":{"aff":-45,"type":"contempt","relation":"legal owner","note":"Never appreciated his true worth or noble heritage","worst":"Passed around by a family that saw him as chattel"},"Louis Letrush":{"aff":-65,"type":"enemy","relation":"would-be thief","note":"Attempted to steal ownership through underhanded dealing","worst":"A thief posing as a buyer"},"Hofgrir Horse-Crusher":{"aff":50,"type":"professional","relation":"trainer","note":"One of few who recognized and respected his exceptional breeding","best":"A human who saw his true potential"},"Grane":{"aff":70,"type":"familial","relation":"sire","note":"Noble sire whose legendary bloodline he carries proudly"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('frothar', '{"Balgruuf the Greater":{"aff":80,"type":"familial","relation":"father","note":"Role model whom he seeks to emulate and whose legacy he aims to uphold","best":"Father''s lessons on patience and duty shaping his mature outlook"},"Dagny":{"aff":25,"type":"familial","relation":"younger sister","note":"Strained relationship due to her spoiled and impatient nature","worst":"Calling her a spoiled baby after she complained about a delayed dress"},"Nelkir":{"aff":35,"type":"familial","relation":"younger brother","note":"Distant sibling who shares the castle but little closeness"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fruki', '{"Leigelf":{"aff":65,"type":"professional","relation":"employer","note":"Loyal miner who defends Leigelf against criticism despite working in declining conditions","best":"Steadfastly refused to abandon him when Irgnir urged her to quit"},"Irgnir":{"aff":60,"type":"platonic","relation":"friend and fellow miner","note":"Close friendship that crosses mine rivalries, sharing drinks and banter at the Windpeak Inn","best":"Tried to calm Irgnir''s fears about the nightmares with reassurance","worst":"Endured teasing about a supposed romantic interest in Leigelf"},"Erandur":{"aff":35,"type":"suspicious","relation":"spiritual advisor","note":"Wants to trust his guidance on the nightmares but openly questions whether his reassurances are adequate","best":"Turned to him for help calming Irgnir","worst":"Challenged his claim that the dreams are harmless, pressing him for real answers"},"Thoring":{"aff":40,"type":"platonic","relation":"townsfolk","note":"Regular companion at the Windpeak Inn who shares community concerns"},"Lady Mara":{"aff":75,"type":"fanatical","relation":"patron deity","note":"Devoted worshipper whose faith in Lady Mara sustains her through the nightmare plague","best":"Declared steadfast belief that Mara would save them from the nightmares"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fultheim', '{"Hadring":{"aff":20,"type":"transactional","relation":"innkeeper","note":"Tolerates Fultheim''s permanent residence and heavy drinking with quiet resignation"},"Balagog gro-Nolob":{"aff":10,"type":"pitying","relation":"fellow resident","note":"Observes the Orc''s isolation with rare empathy, recognizing a kindred spirit"},"Thalmor":{"aff":-80,"type":"fearful","relation":"possible pursuers","note":"If his Blades sword hints at former allegiance, his isolation may be survival"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fultheim_the_fearless', '{"Holgrim":{"aff":-20,"type":"professional","relation":"fellow mercenary","note":"Followed his orders during a raid but morally opposed killing sleeping men","worst":"Holgrim ignored his plea to spare sleeping victims"},"Astrid":{"aff":-85,"type":"enemy","relation":"captor","note":"Held bound and hooded by her for Dark Brotherhood initiation"},"Dark Brotherhood":{"aff":-75,"type":"fearful","relation":"captors","note":"Kidnapped as potential sacrifice for their initiation ritual"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('fura_bloodmouth', '{"Lord Harkon":{"aff":45,"type":"servant","relation":"master","note":"Pragmatic loyalty stemming from power and convenience rather than devotion","best":"Personally selected to join his inner circle of vampire warriors","worst":"Would switch allegiances if her survival demanded it"},"Volkihar Clan":{"aff":20,"type":"professional","relation":"clan member","note":"Tolerates fellow vampires but maintains distance from court politics"},"Dawnguard":{"aff":-80,"type":"enemy","relation":"sworn enemy","note":"Actively hunts them and leads missions to eliminate their leaders","worst":"They will fight hard to obtain Auriel''s Bow and must be struck first"},"Thin-blooded Vampires":{"aff":-55,"type":"contempt","relation":"lesser kin","note":"Views them as weak creatures to be culled before they upset the herd","best":"Disposing of a few makes you realize they aren''t worth the worry"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gabriella', '{"Dark Brotherhood":{"aff":85,"type":"fanatical","relation":"family","note":"Found acceptance, love, and her life''s true purpose within the Brotherhood"},"Night Mother":{"aff":95,"type":"fanatical","relation":"unholy matron","note":"Believes without the Night Mother there is no Dark Brotherhood; deserves unwavering support"},"Cicero":{"aff":35,"type":"professional","relation":"Keeper","note":"Respects his position but finds his demeanor too exuberant for her liking"},"Astrid":{"aff":55,"type":"professional","relation":"sanctuary leader","note":"Follows her leadership while privately valuing traditional Brotherhood ways over Astrid''s approach"},"Babette":{"aff":65,"type":"platonic","relation":"sister","note":"Shares warm family banter and appreciates her wicked sense of humor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gadba_gro-largash', '{"Mul gro-Largash":{"aff":85,"type":"familial","relation":"brother","note":"Defers to Mul''s judgment though conversations suggest Gadba is often the more practical one","best":"Working side by side toward their shared ambition of becoming chiefs","worst":"The unspoken reality that only one of them can actually be chief"},"Largashbur Stronghold":{"aff":30,"type":"estranged","relation":"former home","note":"Left to pursue ambitions; no one there acknowledges them or mentions them at all","best":"Growing up with traditional Orcish values and customs","worst":"Having no standing or family recognition in the stronghold"},"Chief Mauhulakh":{"aff":15,"type":"professional","relation":"host chief","note":"Works in his mine; Mauhulakh dismisses the brothers as harmless miners","worst":"Being written off as no threat to his position"},"Dushnamub":{"aff":-10,"type":"suspicious","relation":"chief''s son","note":"Dushnamub openly worries the brothers might challenge his father","worst":"Being watched and reported on as a potential usurper"},"Narzulbur Community":{"aff":35,"type":"platonic","relation":"current home","note":"Secretly likes Narzulbur but won''t admit it to Mul","best":"Finding the mine work satisfying and the community tolerable"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gadnor', '{"Dervenin":{"aff":25,"type":"curious","relation":"fellow Sheogorath affiliate","note":"Connected through Sheogorath''s realm; Gadnor was originally meant to fill Dervenin''s role seeking aid from travelers","best":"Sharing knowledge of Sheogorath''s domain","worst":"Being replaced by Dervenin in pleading for help"},"Sheogorath":{"aff":50,"type":"obsessed","relation":"Daedric obsession","note":"Drawn to Sheogorath''s realm and artifacts, ultimately died pursuing Nerveshatter","best":"Discovering connections to the Mad God''s realm","worst":"Dying in Crystaldrift Cave while pursuing Daedric artifacts"},"Solitude Guards":{"aff":-25,"type":"suspicious","relation":"harassing authorities","note":"Tense relationship due to his begging activities in Solitude","worst":"Being driven away or harassed while begging"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gaius_maro', '{"Commander Maro":{"aff":85,"type":"familial","relation":"father and superior officer","note":"Close bond blending family affection with military respect","best":"Father''s trust in assigning him the critical security inspection","worst":"Father''s worried farewell before his solitary journey"},"Faida":{"aff":92,"type":"romantic","relation":"lover","note":"Deeply tender connection; she runs Four Shields Tavern in Dragon Bridge","best":"Promised he carries her always in his heart before departing","worst":"Painful parting as duty forces them apart"},"Titus Mede II":{"aff":75,"type":"protective","relation":"sworn charge","note":"Ultimate authority figure whose safety defines Gaius''s purpose","best":"Entrusted with verifying security across all of Skyrim for the Emperor''s visit"},"Penitus Oculatus":{"aff":60,"type":"professional","relation":"brotherhood","note":"Elite force united in purpose to protect the Emperor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('galathil', '{"Thieves Guild":{"aff":15,"type":"transactional","relation":"reluctant host","note":"Tenuous arrangement allowing her to operate in the Ragged Flagon; she resents the circumstances","worst":"Reduced to working in the sewers among the scum of Skyrim"},"Faculty of Chirurgeons":{"aff":55,"type":"estranged","relation":"former student","note":"Proud of her training in Cloudrest but fallen from their esteemed circles","best":"Mastered the art of flesh sculpture under their tutelage"},"Hollow-Faced Men of Nohotogrha":{"aff":40,"type":"mentor","relation":"former student","note":"Walked with them for three years learning their mysterious techniques","best":"Gained esoteric knowledge of flesh sculpting from their secretive order"},"Former Noble Clients":{"aff":30,"type":"estranged","relation":"former patron","note":"Once served the nobility of both the Empire and the Dominion; those connections are now severed","best":"Counted the great and good of Tamriel among her clientele","worst":"Fell from grace and lost all her aristocratic patrons"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('galdrus_hlervu', '{"Elder Othreloth":{"aff":65,"type":"mentor","relation":"mentor and superior","note":"Being groomed as successor but eager to run the temple his own way","best":"Praised by Othreloth for progressing well in his lessons","worst":"Corrected sharply for using the old term Anticipations instead of Reclamations"},"Glover Mallory":{"aff":15,"type":"transactional","relation":"handyman contact","note":"Contacts him for temple maintenance issues like stuck doors"},"Non-believers":{"aff":-45,"type":"contempt","relation":"unwelcome outsiders","note":"Views outsiders with suspicion and refuses them entry to the temple","worst":"Accuses visitors of being motivated by gold like scurrying rats"},"Temple Faithful":{"aff":25,"type":"professional","relation":"congregants","note":"Maintains formal relationships but expects financial contributions from worshippers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('galmar_stone-fist', '{"Ulfric Stormcloak":{"aff":95,"type":"protective","relation":"housecarl and sworn brother","note":"Brotherhood forged in the Great War; bound by shared vision for Skyrim''s freedom","best":"Fighting side by side in the Great War"},"Legate Rikke":{"aff":-45,"type":"enemy","relation":"former comrade","note":"Fought together in the Imperial Legion; now stands on opposite sides of the civil war","best":"Serving together in the Great War","worst":"Facing each other as enemies across Skyrim''s battlefields"},"General Tullius":{"aff":-80,"type":"enemy","relation":"military adversary","note":"Embodies everything Galmar despises about the Empire''s capitulation and occupation","worst":"Tullius leading the Imperial war effort against Skyrim''s freedom"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"existential enemy","note":"White-hot hatred for those who banned Talos worship and subjugated Nordic culture","worst":"The White-Gold Concordat outlawing Talos worship"},"Stormcloak Soldiers":{"aff":55,"type":"professional","relation":"commander","note":"Respects those who bleed for Skyrim''s freedom; leads by example from the front"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gambler', '{"Cragslane Gamblers":{"aff":10,"type":"platonic","relation":"fellow gamblers","note":"Uneasy alliance born of shared vices and proximity","best":"Winning a big payout alongside the regulars","worst":"Violent outburst turning camaraderie to bloodshed"},"Pit Wolf Handlers":{"aff":15,"type":"transactional","relation":"betting contacts","note":"Regular betting customers and information sources for fight odds"},"Skooma Dealers":{"aff":-15,"type":"indebted","relation":"suppliers","note":"Tense but necessary relationship driven by crippling addiction","worst":"Debt collection threats when coin runs dry"},"Riften Guards":{"aff":-75,"type":"enemy","relation":"law enforcement","note":"Hostile enemies who occasionally raid the cavern","worst":"Narrow escape during a guard raid on Cragslane"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ganna_uriel', '{"Gemma Uriel":{"aff":70,"type":"familial","relation":"sister and business partner","note":"Bonded through shared ruin, though Ganna''s bitterness clashes with Gemma''s stubborn optimism","best":"Left Cyrodiil together to chase a shared dream of independence","worst":"Lost everything together when the sacred grove made their mill worthless"},"Kjeld":{"aff":15,"type":"transactional","relation":"customer and mayor","note":"Buys their firewood and mine timbers but leverages their desperation for discounts","worst":"Always asks for the usual discount knowing they can''t refuse"},"Kynesgrove Nords":{"aff":-25,"type":"suspicious","relation":"neighbors","note":"Resents the cultural barrier that destroyed their venture but must coexist carefully","worst":"Built the entire mill before learning the trees were sacred to Kyne"},"Ulfric Stormcloak":{"aff":-15,"type":"transactional","relation":"rejected business prospect","note":"Sought a lumber contract but was politely declined by his housecarl","worst":"Hoped for a major deal only to receive a form-letter rejection"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('garakh', '{"Lob":{"aff":65,"type":"mentor","relation":"apprentice and chosen successor","note":"Garakh trains Lob in sacred smithing traditions and trusts him to carry on her legacy","best":"Seeing Lob progress in mastering Orichalcum techniques"},"Chief Yamarz":{"aff":30,"type":"professional","relation":"tribal chief","note":"Serves him as stronghold blacksmith but harbors concerns about his leadership","worst":"Watching Yamarz fail to address Malacath''s displeasure"},"Malacath":{"aff":95,"type":"fanatical","relation":"patron deity","note":"Views every creation as a religious offering and accepts the curse as righteous punishment","best":"Completing a blade that truly honors Malacath"},"Atub":{"aff":50,"type":"platonic","relation":"fellow tribe member","note":"Shares concerns about the curse afflicting Largashbur","worst":"Discussing the curse that has fallen upon their stronghold"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('garan_marethi', '{"Lord Harkon":{"aff":65,"type":"professional","relation":"advisor","note":"Serves with calculated loyalty as a high-ranking court advisor and taskmaster","best":"Harkon''s order to retrieve the Bloodstone Chalice signaled grander things afoot"},"Vingalmo":{"aff":-25,"type":"rival","relation":"rival advisor","note":"Views him with contempt but maintains diplomatic relations","worst":"Vingalmo''s constant suspicion and questioning of his activities in court"},"Orthjolf":{"aff":-35,"type":"rival","relation":"rival advisor","note":"Considers him intellectually inferior and beneath him","worst":"Orthjolf''s blunt interference and lack of subtlety in court politics"},"House Dres":{"aff":-55,"type":"estranged","relation":"former house","note":"Abandoned his noble house due to their anti-necromancy policies and racial purity obsession","worst":"Being forced from his prestigious birthright over ideological differences"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('garthar', '{"Vex":{"aff":78,"type":"crush","relation":"recruiter","note":"Has romantic feelings for Vex since their roadside encounter and scuffle","best":"Fought off wolves alongside her and held his own in combat","worst":"She tried to rob him immediately after they finished fighting wolves together"},"Mercer Frey":{"aff":-85,"type":"enemy","relation":"former guildmaster","note":"Furious about Mercer''s betrayal of the Guild","worst":"Mercer''s betrayal of the Thieves Guild"},"Brynjolf":{"aff":55,"type":"professional","relation":"guild leader","note":"Respectful of Brynjolf''s leadership and eager to prove himself"},"Thieves Guild":{"aff":72,"type":"protective","relation":"guild member","note":"Strongly loyal to the Guild and its members, sees it as his path to success"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('garvey', '{"Weylin":{"aff":25,"type":"protective","relation":"former resident","note":"Guarded access to Weylin''s room even after death during the Forsworn Conspiracy","worst":"Weylin died violently in the market, another soul lost to Markarth''s troubles"},"Mulush gro-Shugurz":{"aff":-55,"type":"contempt","relation":"detractor","note":"Mulush openly disparages him as a disease-riddled native barely good for anything","worst":"Called disease-riddled and dismissed as nearly worthless by the Orc"},"Warren Residents":{"aff":55,"type":"protective","relation":"charges","note":"Unofficial custodian who manages keys and watches over the poor and sick","best":"Keeps the vulnerable safe and housed as best he can"},"Markarth Guards":{"aff":-25,"type":"suspicious","relation":"authorities","note":"Maintains cautious distance, keenly aware of their corruption"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('garyn_ienth', '{"Milore Ienth":{"aff":90,"type":"romantic","relation":"wife","note":"Beloved wife and alchemist whose work improves his crop yields","best":"Promised she''d never have to eat horrid turnips again after a strong ash yam harvest","worst":"Nearly lost her when she was hunting netch for jelly"},"Councilor Morvayn":{"aff":65,"type":"professional","relation":"respected leader","note":"Trusts Morvayn''s leadership and feels valued by his recognition of the farm''s importance","best":"Morvayn publicly acknowledged Garyn supplies most of the town''s food"},"Captain Veleth":{"aff":50,"type":"professional","relation":"town guard captain","note":"Appreciates Veleth''s efforts to protect the farm area despite limited resources","best":"Veleth promised a permanent foot patrol near the farm after Garyn raised security concerns"},"House Telvanni":{"aff":-15,"type":"dismissive","relation":"rival tradition","note":"Skeptical of their magical farming methods and prefers traditional Dunmer techniques","worst":"Dismisses Telvanni magic as unnecessary when patience and proper tools suffice"},"Miraak":{"aff":-85,"type":"enemy","relation":"oppressor","note":"Resents Miraak for the mind control that left his hands scraped and raw","worst":"Woke every morning with hands raw from Miraak''s compulsion over the Earth Stone"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gaston_bellefort', '{"Dark Brotherhood":{"aff":-95,"type":"nemesis","relation":"mortal enemy and research target","note":"Devoted his life to exposing their secrets; they killed him for infiltrating their sanctuary.","worst":"Being slain in the Dark Brotherhood Sanctuary after his infiltration attempt"},"Night Mother":{"aff":-20,"type":"obsessed","relation":"subject of investigation","note":"Consumed by uncovering the truth about her existence and nature; wrote The Night Mother''s Truth.","best":"Completing his manuscript exposing her secrets"},"Academic Circles":{"aff":50,"type":"professional","relation":"peer community","note":"Respected author and researcher among scholars of forbidden knowledge."},"Informants":{"aff":35,"type":"transactional","relation":"intelligence network","note":"Network of sources who provided information about the Brotherhood''s activities."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gat_gro-shargakh', '{"Pavo Attius":{"aff":78,"type":"platonic","relation":"fellow survivor","note":"Fought their way out of Kolskeggr Mine together; Gat deeply admires Pavo''s courage","best":"Surviving the Forsworn attack side by side"},"Forsworn":{"aff":-85,"type":"enemy","relation":"attackers","note":"Slaughtered all other miners at Kolskeggr Mine; Gat and Pavo barely escaped with their lives","worst":"The massacre at Kolskeggr Mine"},"Skaggi Scar-Face":{"aff":35,"type":"grateful","relation":"shelter provider","note":"Took in Gat and Pavo at Left Hand Mine after they fled Kolskeggr"},"Stronghold Family":{"aff":10,"type":"estranged","relation":"estranged kin","note":"Left the stronghold voluntarily; would have to kill his brother to return","worst":"Knowing return requires fratricide"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gauldur', '{"Jyrik Gauldurson":{"aff":-45,"type":"betrayed","relation":"eldest son","note":"Murdered by Jyrik for his amulet, yet holds no anger","worst":"Slain by his eldest son''s hand for power"},"Mikrul Gauldurson":{"aff":-45,"type":"betrayed","relation":"middle son","note":"Participated in his father''s murder alongside his brothers","worst":"Betrayed by Mikrul in the patricide"},"Sigdis Gauldurson":{"aff":-45,"type":"betrayed","relation":"youngest son","note":"Joined his brothers in murdering their father","worst":"Even his youngest son turned against him"},"Lord Geirmund":{"aff":75,"type":"platonic","relation":"trusted friend","note":"Pursued and defeated Gauldur''s sons after the murder","best":"Geirmund avenged his death and brought his sons to justice"},"High King of Skyrim":{"aff":-15,"type":"neutral","relation":"ruler who suppressed his tale","note":"Ordered the suppression of Gauldur''s murder story"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gavros_plinius', '{"Paratus Decimius":{"aff":25,"type":"rival","relation":"fellow researcher","note":"Complicated colleague dynamic; Gavros stole credit for Paratus''s crystal focusing idea","best":"Trusted Paratus enough to direct others to find him in the Oculory with his dying breath","worst":"Appropriated Paratus''s crystal concept as his own discovery"},"Synod Council":{"aff":55,"type":"patron","relation":"superiors","note":"Ambitiously sought their approval and advancement through groundbreaking discoveries","best":"Rose quickly through their ranks through dedication to dangerous research expeditions"},"College of Winterhold":{"aff":-25,"type":"rival","relation":"competing institution","note":"Synod competed with them for magical knowledge and influence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('geimund', '{"Fridrika":{"aff":90,"type":"romantic","relation":"wife","note":"Beloved wife who helps manage the stables and household","best":"Building a peaceful life together at Solitude Stables"},"Horm":{"aff":85,"type":"familial","relation":"son","note":"Cherished son and heir to the family business","best":"Watching him grow into the future of the stables"},"Fihada":{"aff":40,"type":"platonic","relation":"friend","note":"Marked as friends though they never meet and the connection is unexplained"},"Legate Rikke":{"aff":45,"type":"platonic","relation":"friend","note":"Friendship possibly dating back to his mercenary days, though never explained"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('geirlund', '{"Thorald Gray-Mane":{"aff":90,"type":"indebted","relation":"life-savior","note":"Thorald saved his life, creating a debt Geirlund is determined to repay","best":"Was saved by Thorald when his life hung in the balance","worst":"Could not prevent Thorald''s capture and imprisonment by the Thalmor"},"Vidrald":{"aff":75,"type":"platonic","relation":"fighting companion","note":"Close friend who fights alongside him and remains at Northwatch Keep together after the rescue"},"Avulstein Gray-Mane":{"aff":65,"type":"professional","relation":"resistance ally","note":"Trusted ally who called upon Geirlund to help rescue Thorald from the Thalmor"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Deep-seated hatred drives him to actively oppose their presence and rescue their prisoners","worst":"Witnessed the Thalmor''s cruelty firsthand, fueling his determination to fight them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('geldis_sadri', '{"Drovas Relvi":{"aff":55,"type":"mentor","relation":"apprentice","note":"Maintains a complex mentoring relationship with his apprentice at the Retching Netch"},"Bralsa Drel":{"aff":-30,"type":"neutral","relation":"banned patron","note":"Banned from the inn due to excessive and troublesome drinking"},"Councilor Morvayn":{"aff":65,"type":"protective","relation":"councilor","note":"Respects and politically supports Raven Rock''s leader, vigilant about threats to him"},"Ulen Family":{"aff":-60,"type":"suspicious","relation":"would-be assassins","note":"Aware of their Hlaalu-backed assassination plots against Councilor Morvayn"},"Captain Veleth":{"aff":45,"type":"platonic","relation":"guard captain","note":"Friendly professional relationship with the Redoran Guard captain"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gelebros', '{"Quaranir":{"aff":65,"type":"professional","relation":"fellow Psijic","note":"Mission leader during the Eye of Magnus crisis"},"Tandil":{"aff":55,"type":"professional","relation":"fellow operative","note":"Colleague in the Psijic Order"},"Ancano":{"aff":-80,"type":"enemy","relation":"magical threat","note":"Viewed as a dangerous threat to magical stability"},"Savos Aren":{"aff":40,"type":"professional","relation":"Arch-Mage","note":"Respected but kept at professional distance"},"Player":{"aff":55,"type":"grateful","relation":"acknowledged ally","note":"Recognized for role in securing the Eye of Magnus","best":"Our order will not forget your deeds"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gemma_uriel', '{"Ganna Uriel":{"aff":35,"type":"familial","relation":"sister","note":"Blames Ganna for dragging her to Skyrim but remains loyal and works alongside her to pay off shared debts","best":"Still working together to find a way to harvest lumber legally","worst":"Lost everything in Cyrodiil following Ganna''s venture to Kynesgrove"},"Ulfric Stormcloak":{"aff":-25,"type":"professional","relation":"rejected business contact","note":"Attempted to secure a lumber contract through his housecarl but was politely declined","worst":"Received rejection letter dashing hopes of a major lumber order"},"Kjeld":{"aff":10,"type":"transactional","relation":"client, mayor","note":"Orders support timbers for the mine but leverages his position as mayor to demand discounts","best":"Provides regular orders for mine support timbers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('general_falx_carius', '{"Ildari Sarothril":{"aff":-90,"type":"enemy","relation":"would-be master","note":"Reanimated and experimented on him with heartstone necromancy but failed to break his will","worst":"She bound me with dark magic and sought to make me her puppet"},"Ash Spawn":{"aff":35,"type":"professional","relation":"commanded troops","note":"Leads them with tactical precision as his undead legion"},"Raven Rock Settlement":{"aff":-55,"type":"enemy","relation":"military target","note":"Ordered ash spawn attacks against the settlement as strategic opposition"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('general_tullius', '{"Legate Rikke":{"aff":65,"type":"professional","relation":"trusted second-in-command","note":"Relies on her counsel regarding Nord culture and military strategy","best":"Her steadfast loyalty and invaluable insight into Nordic ways"},"Ulfric Stormcloak":{"aff":-85,"type":"nemesis","relation":"rebel leader","note":"Views him as a power-hungry usurper who murdered his king and plunged Skyrim into chaos","worst":"Ulfric using the Voice to murder High King Torygg and usurp his throne"},"Emperor Titus Mede II":{"aff":55,"type":"professional","relation":"emperor and superior","note":"Appointed Tullius as Military Governor; source of his authority and mission","best":"Being entrusted with the Skyrim campaign"},"Thalmor":{"aff":-70,"type":"contempt","relation":"distrusted foreign power","note":"Despises them as the true threat to the Empire and blames them for engineering the rebellion","worst":"Their manipulation forcing the Empire to bleed resources on a needless civil war"},"Elisif the Fair":{"aff":45,"type":"protective","relation":"protectorate","note":"Supports her as the legitimate Jarl of Solitude and widow of the murdered High King"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gerda', '{"Fianna":{"aff":70,"type":"platonic","relation":"fellow maid","note":"Close colleague who shares daily sweeping duties and living quarters"},"Jarl Balgruuf":{"aff":60,"type":"professional","relation":"employer","note":"Respected lord she serves with loyalty and discretion"},"Farengar Secret-Fire":{"aff":35,"type":"professional","relation":"court wizard","note":"Maintains professional distance while cleaning his study"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gerdur', '{"Hod":{"aff":85,"type":"romantic","relation":"husband and business partner","note":"Runs the lumber mill together in a strong working and personal partnership"},"Frodnar":{"aff":90,"type":"protective","relation":"son","note":"Fiercely protective, raising him to carry on the family legacy"},"Ralof":{"aff":90,"type":"familial","relation":"brother","note":"Close bond since childhood with shared Stormcloak allegiance","best":"Reunion after his escape from Helgen"},"Alvor":{"aff":55,"type":"platonic","relation":"neighbor and blacksmith","note":"Respected despite political differences, visits him daily"},"Jarl Balgruuf":{"aff":30,"type":"suspicious","relation":"Jarl of Whiterun","note":"Respects his past rule but disappointed by his neutrality, fears he will side with the Empire"},"Ulfric Stormcloak":{"aff":75,"type":"admirer","relation":"Stormcloak leader","note":"Devoted supporter who believes he is Skyrim''s rightful High King"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gestur_rockbreaker', '{"Bryling":{"aff":80,"type":"grateful","relation":"employer","note":"Credits her with giving his life meaning after unknown hardships","best":"Was offered the foreman position at Rockwallow Mine"},"Swanhvir":{"aff":35,"type":"professional","relation":"subordinate miner","note":"Reliable worker who responds well to his oversight"},"Jesper":{"aff":30,"type":"professional","relation":"subordinate miner","note":"Shows proper deference and works hard under his management"},"Teeba-Ei":{"aff":25,"type":"professional","relation":"subordinate miner","note":"Treats the Argonian with slightly awkward but fair consideration"},"Talib":{"aff":50,"type":"estranged","relation":"son","note":"Redguard son from a past family life, now lost or separated","best":"Shared honest working moments together at the mine","worst":"Unknown hardships led to loss or separation from his son"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ghak', '{"Malacath":{"aff":95,"type":"fanatical","relation":"divine patron","note":"Views her mining as sacred worship and purpose bestowed by Malacath","best":"Every swing of the pickaxe honors Malacath''s challenge"},"Burguk":{"aff":75,"type":"servant","relation":"chief","note":"Serves with unwavering loyalty and carries the key to his longhouse"},"Dulug":{"aff":40,"type":"platonic","relation":"fellow miner","note":"Works alongside in Dushnikh Mine"},"Mahk":{"aff":40,"type":"platonic","relation":"fellow miner","note":"Works alongside in Dushnikh Mine"},"Oglub":{"aff":40,"type":"platonic","relation":"fellow miner","note":"Works alongside in Dushnikh Mine"}}')
