INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ghamorz', '{"Gul":{"aff":25,"type":"professional","relation":"fellow miner","note":"Shares daily mining duties in Mor Khazgur Mine"},"Olur":{"aff":25,"type":"professional","relation":"fellow miner","note":"Works alongside in the orichalcum mine"},"Chief Larak":{"aff":45,"type":"professional","relation":"stronghold chief","note":"Serves through mining labor; trusted with key to Larak''s Longhouse"},"Malacath":{"aff":85,"type":"fanatical","relation":"patron deity","note":"Views every strike of the pickaxe as sacred service to Malacath","best":"Malacath rewards those who rise to the challenge of the mines"}}')
