INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gharol', '{"Chief Burguk":{"aff":30,"type":"familial","relation":"husband","note":"His second wife who vies for his attention against Shel","best":"He noticed her strong muscles at the forge and praised her","worst":"He deflects her plea to replace Shel at the feast"},"Shel":{"aff":-50,"type":"jealous","relation":"rival wife","note":"Burguk''s first wife who holds his primary affection"},"Lash":{"aff":70,"type":"estranged","relation":"daughter","note":"Left the stronghold for Karthwasten''s mines against tradition","best":"Forged a special sword channeling all her love and grief for Lash"},"Umurn":{"aff":65,"type":"familial","relation":"son and apprentice","note":"Strictly trains him in smithing with tough love","best":"Teaches him to channel hatred and emotion into the steel"}}')
