INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ghorbash_the_iron_hand', '{"Chief Burguk":{"aff":65,"type":"familial","relation":"brother and chief","note":"Burguk welcomed him home as family rather than a rival, breaking tradition","best":"Welcomed home as family instead of a rival to the chief''s seat"},"Imperial Legion":{"aff":55,"type":"professional","relation":"former brothers-in-arms","note":"Served with distinction for years and still speaks fondly of the experience","best":"Earned his epithet through exceptional martial prowess in the Legion"},"Dushnikh Yal Clan":{"aff":60,"type":"protective","relation":"clan and family","note":"Torn between duty to the stronghold and longing for the freedom of the road","worst":"Fears dishonoring the clan by leaving again like some young pup"},"Nagrub":{"aff":40,"type":"platonic","relation":"fellow warrior","note":"Shares training duties at the stronghold"},"Oglub":{"aff":45,"type":"familial","relation":"brother","note":"Brother in the stronghold, though they rarely cross paths"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ghorza_gra-bagol', '{"Moth gro-Bagol":{"aff":75,"type":"familial","relation":"brother","note":"Close sibling bond; they live and work together in Markarth","best":"Left the stronghold together to build a new life in the city"},"Tacitus Sallustius":{"aff":30,"type":"mentor","relation":"apprentice","note":"Stern and often frustrated with his slow progress, but genuinely invested in his training","best":"Sought out a smithing book to help him learn when example wasn''t enough","worst":"Constantly disappointed by his brittle nails and skipped steps at the forge"},"Orc Strongholds":{"aff":25,"type":"estranged","relation":"former home","note":"Left by choice refusing to become a chieftain''s third wife, but still maintains connections and pride in Orcish craft"},"The Legion":{"aff":50,"type":"professional","relation":"former service","note":"Mastered her trade there and references their methods and standards proudly"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ghost_of_old_hroldan', '{"Tiber Septim":{"aff":95,"type":"platonic","relation":"sworn brother and commander","note":"Waited centuries for a promised sword and brotherhood oath to be fulfilled","best":"Hjalti saving my life time and time again across two campaigns","worst":"Dying with arrows in my chest before the promise could be kept"},"Dragonborn":{"aff":85,"type":"platonic","relation":"mistaken commander","note":"Mistakes the Dragonborn for Hjalti and treats them as his long-awaited commander","best":"Receiving the promised sword and sharing final combat lessons"},"Eydis":{"aff":10,"type":"neutral","relation":"innkeeper","note":"Tolerates her presence at the inn where his spirit is bound"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ghunzul', '{"Cracked Tusk Bandits":{"aff":65,"type":"professional","relation":"followers","note":"Loyal outlaws who respect his strength and leadership at Cracked Tusk Keep"},"Ancestor Line":{"aff":80,"type":"familial","relation":"ancestors","note":"Seven generations of guardians before him; he strives to prove worthy of their legacy","best":"Inheriting leadership and the sacred duty from his father"},"Rival Bandits":{"aff":-40,"type":"rival","relation":"competitors","note":"Competing groups who have repeatedly tried to steal the blade fragments"},"Mehrunes Dagon Cultists":{"aff":-70,"type":"enemy","relation":"threats","note":"Seek to reclaim the Razor shards for their Daedric Prince","worst":"Repelling cultist attempts to seize the family''s sacred charge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gian_the_fist', '{"Ratway Dwellers":{"aff":-40,"type":"suspicious","relation":"territorial rival","note":"Attacks anyone who ventures too close to his claimed domain"},"Thieves Guild":{"aff":-15,"type":"suspicious","relation":"unwelcome neighbor","note":"Tolerated but not welcomed; keeps to himself in the Ratway"},"Riften Guards":{"aff":-75,"type":"enemy","relation":"wanted fugitive","note":"Wanted for assault; avoids them at all costs","worst":"Fled Cyrodiil after killing a noble''s son in a tavern brawl"},"Local Merchants":{"aff":10,"type":"transactional","relation":"occasional customer","note":"Trades for supplies through intermediaries only"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gianna', '{"The Gourmet":{"aff":88,"type":"admirer","relation":"culinary idol","note":"Reveres the Gourmet above all culinary authority and is deeply honored to assist them","best":"Being chosen to assist the Gourmet in preparing the Potage le Magnifique for the Emperor"},"Titus Mede II":{"aff":50,"type":"professional","relation":"emperor","note":"Aims to impress him with her cooking and takes immense pride in serving him","worst":"Witnessing the assassination attack during the feast she helped prepare"},"Commander Maro":{"aff":35,"type":"professional","relation":"superior officer","note":"Oversees Castle Dour security; she answers to his authority"},"Castle Dour Staff":{"aff":45,"type":"platonic","relation":"colleagues","note":"Fellow staff who respect her culinary expertise and leadership in the kitchen"}}')
