INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gilfre', '{"Former Mill Workers":{"aff":-25,"type":"estranged","relation":"former employees","note":"Five men who left the mill to fight in the civil war, abandoning her to run it alone","worst":"Coming out one morning to find they had all gone off to fight"},"Gemma Uriel":{"aff":10,"type":"neutral","relation":"acquaintance","note":"Occasionally mentions Gilfre in conversation"},"Ganna Uriel":{"aff":10,"type":"neutral","relation":"acquaintance","note":"Occasionally mentions Gilfre in conversation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gimvar_cruel-sea', '{"Torsten Cruel-Sea":{"aff":45,"type":"familial","relation":"father","note":"Loves his father but resents pressure to follow maritime tradition","worst":"Father dismisses his warrior dreams"},"Hillevi Cruel-Sea":{"aff":65,"type":"familial","relation":"mother","note":"Supportive presence in his upbringing"},"Idesa Sadri":{"aff":75,"type":"protective","relation":"caretaker","note":"Dark Elf caretaker who shaped his tolerant worldview","best":"Learned to see beyond racial prejudice through her care"},"Aventus Aretino":{"aff":15,"type":"curious","relation":"neighborhood child","note":"Fascinated by rumors of the Black Sacrament surrounding him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('giraud_gemane', '{"Viarmo":{"aff":65,"type":"professional","relation":"superior and colleague","note":"Respects Viarmo greatly as head of the Bards College"},"Pantea Ateia":{"aff":45,"type":"platonic","relation":"fellow instructor","note":"Shares academic discussions and scholarly interests"},"Inge Six-Fingers":{"aff":45,"type":"professional","relation":"colleague","note":"Shares dedication to preserving bardic traditions"},"Corpulus Vinius":{"aff":55,"type":"platonic","relation":"friend","note":"Regular patron of the Winking Skeever"},"Adonato Leotelli":{"aff":35,"type":"professional","relation":"associate","note":"Receives and reviews Adonato''s written works"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('girduin', '{"Atmah":{"aff":70,"type":"mentor","relation":"expedition leader and mentor","note":"Selected him for the Labyrinthian expedition, recognizing his talent","best":"Being chosen for the expedition validated his skill and potential","worst":"She declared there wasn''t enough of him left to recover after the dragon attack"},"Savos Aren":{"aff":60,"type":"platonic","relation":"fellow student","note":"Shared youthful optimism about the expedition''s promise","best":"Joked together about the treasures they might find","worst":"Savos witnessed him ripped apart by the skeletal dragon"},"Elvali Veren":{"aff":65,"type":"platonic","relation":"close colleague","note":"She desperately advocated returning for his remains","best":"Her bond was strong enough that she refused to abandon him","worst":"Her pleas to recover his body were overruled"},"Takes-In-Light":{"aff":55,"type":"platonic","relation":"colleague","note":"Teased her about being the Arch-Mage''s favorite; she was devastated by his death","best":"Friendly banter showed easy camaraderie","worst":"Her fears about the dangers proved justified when he died"},"Hafnar Ice-Fist":{"aff":45,"type":"professional","relation":"fellow mage","note":"Acknowledged the tragedy but prioritized the living","best":"Fought alongside him in the expedition","worst":"Argued against going back for his remains"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gisli', '{"Erikur":{"aff":-55,"type":"estranged","relation":"brother","note":"Resents his arrogance and her unacknowledged dependency while managing his affairs","best":"He didn''t deserve to die","worst":"Being reduced to his unacknowledged errand runner and rent collector"},"Falk Firebeard":{"aff":40,"type":"admirer","relation":"court official","note":"Respects his genuine authority in court, contrasting with her brother''s inflated ego"},"Evette San":{"aff":35,"type":"platonic","relation":"comforting merchant","note":"Seeks out her spiced wine as a rare source of comfort and small pleasure"},"Noster One-Eye":{"aff":30,"type":"platonic","relation":"respected acquaintance","note":"Values his honest perspective on life as a rare truth in Solitude"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gissur', '{"Rulindil":{"aff":-15,"type":"servant","relation":"Thalmor handler","note":"Submissive toward Rulindil but privately resents his contemptuous treatment","worst":"Silence! Do not presume, Gissur. We have other informants who are less... offensive."},"Etienne Rarnis":{"aff":-30,"type":"betrayed","relation":"betrayed source","note":"Exploited Etienne''s trust to extract information for the Thalmor","best":"He trusts me. He''d talk to me."},"Thalmor":{"aff":15,"type":"transactional","relation":"employer","note":"Provides intelligence for coin but is viewed as a disposable, offensive asset"},"Player":{"aff":-70,"type":"enemy","relation":"target","note":"Attacks on sight at the embassy; later alerts Thalmor soldiers to kill the player","worst":"That''s the one asking about Esbern! Kill them!"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gjak', '{"Beitild":{"aff":45,"type":"professional","relation":"employer","note":"Serves her with loyal dedication as a miner at Iron-Breaker Mine"},"Bodil":{"aff":35,"type":"platonic","relation":"colleague","note":"Fellow miner who shares Gjak''s devotion to never leaving the mine"},"Father":{"aff":65,"type":"familial","relation":"father","note":"Taught Gjak the mining trade as a boy and instilled Nordic pride in the craft","best":"Learning the miner''s trade at his father''s side"}}')
