INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gjalund_salt-sage', '{"Sogrlaf":{"aff":55,"type":"professional","relation":"crewman","note":"Loyal crewman serving aboard the Northern Maiden under Gjalund''s command."},"Lygrleid":{"aff":55,"type":"professional","relation":"crew member","note":"Trusted longtime shipmate and crew member of the Northern Maiden."},"Raven Rock":{"aff":25,"type":"professional","relation":"client settlement","note":"Primary destination for his supply runs and ferry service, though he finds the place increasingly unsettling.","worst":"The ash from Red Mountain poisoned the fishing waters that once made him a good living."}}')
