INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('glover_mallory', '{"Delvin Mallory":{"aff":45,"type":"familial","relation":"brother","note":"Distant but loyal family ties; both share Thieves Guild background"},"Vanryth":{"aff":65,"type":"mentor","relation":"former mentor","note":"Dunmer armorsmith who taught him Bonemold crafting techniques","best":"Learned unique Bonemold armor techniques from him"},"Thieves Guild":{"aff":20,"type":"estranged","relation":"passive member","note":"Only guild member on Solstheim; avoids active participation and keeps past hidden"},"Miraak":{"aff":-75,"type":"enemy","relation":"former controller","note":"Was enslaved by Miraak''s mind control, forced to build shrine at the Earth Stone","worst":"Mind controlled against his will to serve Miraak"}}')
