SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('goat', '{"Mountain Goat Herds":{"aff":20,"type":"platonic","relation":"herd associate","note":"Loose social bonds maintained alongside fierce independence"},"Farmers":{"aff":15,"type":"transactional","relation":"salt provider","note":"Cautiously tolerated as a source of salt licks"},"Wolves and Sabre Cats":{"aff":-75,"type":"enemy","relation":"natural predator","note":"Constant threat to be avoided or confronted depending on mood","worst":"Narrow escape from predation on the mountain slopes"},"Adventurers":{"aff":-20,"type":"contempt","relation":"clumsy intruders","note":"Viewed with mild contempt, especially those who struggle on paths"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('golldir', '{"Agna":{"aff":90,"type":"familial","relation":"aunt and caretaker","note":"Raised him after his father''s abandonment; her death haunts him with guilt","best":"Rescued him from the crypt after three days of terror","worst":"Died alone in the tomb because he was too afraid to go in with her"},"Father":{"aff":-85,"type":"estranged","relation":"estranged father","note":"Abandoned the family after traumatizing his son","worst":"Locked him in the family crypt for three days in a drunken rage"},"Vals Veran":{"aff":-95,"type":"nemesis","relation":"defiler of family tomb","note":"Necromancer who desecrated his ancestors'' remains and caused Agna''s death","worst":"Defiled the family tomb and killed Aunt Agna"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gonnar_oath-giver', '{"Ulfric Stormcloak":{"aff":92,"type":"fanatical","relation":"commander-in-chief","note":"Reveres Ulfric as the truest son of Skyrim and the only rightful High King","best":"Ulfric did right killing Torygg for selling out our people"},"Laila Law-Giver":{"aff":60,"type":"professional","relation":"Jarl he advises","note":"Serves as military advisor while stationed in the Rift"},"Maven Black-Briar":{"aff":-55,"type":"contempt","relation":"political adversary","note":"Distrusts her Imperial connections and corrupt influence in Riften"},"Imperial Legion":{"aff":-85,"type":"enemy","relation":"enemy faction","note":"Views them as cowards who sold Skyrim''s gods for a slave master''s peace","worst":"The Emperor sold Talos to the damn elves"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"hated occupiers","note":"Vows to rid Skyrim of elves and their bloody Justiciars","worst":"Talos worship outlawed by elven decree"},"Stormcloak Brotherhood":{"aff":75,"type":"platonic","relation":"brothers-in-arms","note":"Shares a cloak of true brotherhood with all who fight for Skyrim''s freedom","best":"Standing together as true sons and daughters of Skyrim"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gorm', '{"Jarl Idgrod Ravencrone":{"aff":70,"type":"protective","relation":"liege","note":"Deeply loyal but increasingly troubled by her worsening visions and ability to rule","best":"She calls him friend and reassures him all is well","worst":"She can no longer distinguish vision from reality, undermining her leadership"},"Joric":{"aff":35,"type":"pitying","relation":"ward","note":"Watches over the boy with concern that he may share his mother''s affliction","worst":"Joric senses Gorm thinks him mad"},"Idgrod the Younger":{"aff":45,"type":"protective","relation":"ward","note":"Protects the Jarl''s daughter as part of his sworn duty"},"Aslfur":{"aff":40,"type":"professional","relation":"colleague","note":"Maintains a working relationship with the Jarl''s husband and steward"},"Captain Aldis":{"aff":40,"type":"professional","relation":"secret correspondent","note":"Sends private letters to Solitude regarding Morthal''s leadership concerns","worst":"Must secretly act behind his Jarl''s back for what he believes is her good"},"Benor":{"aff":55,"type":"platonic","relation":"confidant","note":"Shares concerns about the Jarl''s condition and discusses taking action","best":"Trusts Benor enough to confide his worries freely"},"Alva":{"aff":-15,"type":"dismissive","relation":"townsfolk","note":"Rebuffs her advances and disapproves of her disloyalty to Hroggar"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gormlaith_golden-hilt', '{"Hakon One-Eye":{"aff":85,"type":"familial","relation":"brother","note":"Fellow warrior against Alduin; close despite her recklessness and his caution","best":"Slaying dragons together in glorious battle","worst":"Falling in battle against Alduin while he could not save her"},"Felldir the Old":{"aff":70,"type":"platonic","relation":"companion","note":"Trusted ally though sometimes at odds over his strategic caution and the Elder Scroll","best":"Standing together against dragon rule","worst":"Disagreement over the Elder Scroll''s use"},"Alduin":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Killed four of his kin; was slain by him in turn at the Throat of the World","best":"Bringing down four dragons with her blade alone","worst":"Being seized in Alduin''s teeth and flung to death"},"Dragonborn":{"aff":80,"type":"protective","relation":"ally","note":"Respects the Dragonborn as the one who can finish what she started","best":"Fighting alongside the Dragonborn to finally defeat Alduin in Sovngarde"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gort', '{"Thoring":{"aff":40,"type":"professional","relation":"business contact","note":"Regular contact at the Windpeak Inn in Dawnstar for ferry business"},"Windhelm Dock Workers":{"aff":35,"type":"professional","relation":"coworkers","note":"Cooperative working relationship with fellow maritime workers"},"Local Merchants":{"aff":30,"type":"transactional","relation":"customers","note":"Regular customers who rely on his ferry service for coastal transport"},"Sailors'' Guild":{"aff":45,"type":"professional","relation":"respected member","note":"Holds good standing among fellow captains and sailors"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gralnach', '{"Grosta":{"aff":70,"type":"familial","relation":"mother","note":"Loving but strained by disagreement over his father''s memory and disappearance","best":"She finally acknowledges his father was a hero and apologizes for dismissing his questions","worst":"She shuts down his questions about his father, insisting he abandoned them"},"Leifnarr":{"aff":85,"type":"familial","relation":"deceased father","note":"Deeply admires his father and desperately seeks to understand him despite his absence","best":"Learning his father died heroically rather than abandoning the family","worst":"Growing up fatherless with no explanation for his disappearance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gregor', '{"Jarl Skald the Elder":{"aff":60,"type":"servant","relation":"appointing liege","note":"Appointed Gregor as housecarl to the Thane of the Pale"},"Thane of the Pale":{"aff":85,"type":"protective","relation":"housecarl","note":"Sworn protector and personal bodyguard at Heljarchen Hall","best":"Being appointed as personal housecarl","worst":"Being ordered to wait apart from his Thane''s side"},"Jod":{"aff":45,"type":"professional","relation":"fellow housecarl","note":"Professional relationship as fellow housecarl serving in the White Hall"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('grelka', '{"Solaf":{"aff":40,"type":"familial","relation":"brother","note":"Learned the merchant trade alongside him in Falkreath"},"Bolund":{"aff":35,"type":"familial","relation":"brother","note":"Grew up together in Falkreath; he works at the mill"},"Haelga":{"aff":10,"type":"transactional","relation":"landlord","note":"Rents a room at the Bunkhouse; no warmth between them"},"Bolli":{"aff":5,"type":"professional","relation":"customer","note":"Complains about shoddy merchandise; she reluctantly fixes it","worst":"Demanded free repairs on armor with loose fasteners"},"Thieves Guild":{"aff":-55,"type":"contempt","relation":"despised faction","note":"Publicly scorns them as scum despite possible indirect dealings","worst":"They''d take your last bit of food if that''s all you had"},"Mjoll":{"aff":-25,"type":"suspicious","relation":"watcher","note":"Accused of arms dealing; dismissive of her threats","worst":"Threatened to report her to the guards over suspected Guild ties"},"Maven Black-Briar":{"aff":15,"type":"transactional","relation":"client","note":"Procures weapons and supplies through her contacts for Maven","best":"Lucrative rush order for longbows and arrows"},"Shadr":{"aff":20,"type":"transactional","relation":"courier","note":"Uses him for package deliveries; pays him to not ask questions","best":"Paid him for a smooth package handoff at noon"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('grelod_the_kind', '{"Constance Michel":{"aff":-35,"type":"contempt","relation":"assistant","note":"Bullies and berates her constantly, issuing threats about the children if demands aren''t met"},"Orphaned Children":{"aff":-85,"type":"contempt","relation":"wards","note":"Actively abuses them and crushes all hope of adoption to maintain control","worst":"Tells them nobody needs or wants them and beats them for any infraction"},"Aventus Aretino":{"aff":-60,"type":"contempt","relation":"escaped ward","note":"Former orphan who fled and is now attempting to contract the Dark Brotherhood to assassinate her"},"Riften Guards":{"aff":15,"type":"transactional","relation":"enablers","note":"Turn a blind eye to her abuses, likely due to bribes or political connections"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('greta', '{"Addvar":{"aff":85,"type":"romantic","relation":"husband","note":"Loving husband who runs the fish stall; they endure hardship together","best":"We''ll make it, Greta. We always have so far..."},"Svari":{"aff":90,"type":"protective","relation":"daughter","note":"Beloved daughter she shields from political turmoil and grief"},"Roggvir":{"aff":95,"type":"familial","relation":"brother","note":"Deceased brother whose memory she fiercely honors; believes he did the honorable thing","worst":"Watching his execution in the courtyard"},"Captain Aldis":{"aff":15,"type":"neutral","note":"Acknowledges his understanding nature despite his role in Roggvir''s execution","best":"I think Aldis understands"},"Temple of the Divines":{"aff":25,"type":"estranged","relation":"former congregant","note":"Left after Roggvir''s death; returns only when she has a Talos amulet for comfort"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('griefstricken_chef', '{"Thoring":{"aff":25,"type":"professional","relation":"employer","note":"Provides him shelter and employment at Windpeak Inn during his darkest hours"},"Dark Brotherhood":{"aff":40,"type":"transactional","relation":"client","note":"Desperately sought their services through the Black Sacrament to achieve vengeance"},"Night Mother":{"aff":60,"type":"fanatical","relation":"object of prayers","note":"Focus of his dark rituals and desperate pleas for the contract to be answered","best":"Night Mother finally chose him as a contract giver"},"Heljarchen Community":{"aff":30,"type":"estranged","relation":"former neighbors","note":"Lost connections when the settlement was abandoned and he was forced to relocate"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('grim_shieldmaiden', '{"Markarth Guard":{"aff":35,"type":"transactional","relation":"client","note":"Professional respect for her quality weapon craftsmanship"},"Silver-Blood Family":{"aff":25,"type":"transactional","relation":"contractor","note":"Business association through smithing contracts"},"Dark Brotherhood":{"aff":-90,"type":"enemy","relation":"assassination target","note":"Named as a recurring target in Dark Brotherhood contracts","worst":"Marked for death by the Brotherhood"},"Blacksmiths Guild":{"aff":15,"type":"professional","relation":"distant colleague","note":"Distant professional connections maintained through trade"}}')
