INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('grisvar_the_unlucky', '{"Madanach":{"aff":-85,"type":"fearful","relation":"prison boss","note":"Lives in constant fear that Madanach will order his death","worst":"Madanach orders him killed as a show of loyalty"},"Braig":{"aff":15,"type":"platonic","relation":"fellow prisoner","note":"Shares cautious conversation and reminiscences about other inmates"},"Duach":{"aff":10,"type":"transactional","relation":"skooma source","note":"Desperately relies on Duach''s skooma supply to feed his addiction"}}')
