INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('grogmar_gro-burzag', '{"Odfel":{"aff":65,"type":"rival","relation":"roommate and fellow miner","note":"Friendly rival sharing cramped quarters; constant bickering over cleanliness but mutual respect for mining skill","best":"Betting on who can haul more iron in a day","worst":"Endless arguments about cleaning up their divided house"},"Filnjar":{"aff":45,"type":"professional","relation":"employer","note":"Respects Filnjar''s authority but tensions flare over disagreements about the mine''s future","worst":"Tense confrontation about whether Redbelly Mine is drying up"}}')
