INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('grosta', '{"Leifnarr":{"aff":40,"type":"familial","relation":"husband","note":"Loved him deeply but spent months believing he abandoned her for another woman, masking pain with bitterness","best":"Building Heartwood Mill and a family together in the wilderness","worst":"Learning he was dead after assuming he had been unfaithful"},"Gralnach":{"aff":85,"type":"protective","relation":"son","note":"Fiercely protective of her son while raising him alone and training him in the family trade","best":"Watching him grow capable and help run the mill","worst":"Catching him going through his father''s things and confronting his grief"},"Broken Helm Hollow traders":{"aff":-65,"type":"suspicious","relation":"suspected killers","note":"Believes they lured Leifnarr with false promises of double prices, likely orchestrating his death","worst":"Realizing their offer was a trap that cost her husband his life"}}')
