INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('guardian_saerek', '{"Otar the Mad":{"aff":70,"type":"professional","relation":"fellow guardian","note":"Served alongside Otar defending Ragnvald in life and continues their shared eternal duty in death","best":"Standing together as honored warriors chosen for Ragnvald''s sacred guard","worst":"Neither could prevent Otar''s descent into madness"},"Ragnvald Draugr":{"aff":30,"type":"professional","relation":"commander","note":"Commands lesser undead defenders within the crypt hierarchy"},"Ancient Nord Priests":{"aff":55,"type":"servant","relation":"subordinate warrior","note":"Served under priest authority in life and maintains their sacred charge in undeath"}}')
