INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gul', '{"Ghamorz":{"aff":45,"type":"platonic","relation":"fellow miner","note":"Daily work companion in the orichalcum mines"},"Olur":{"aff":40,"type":"professional","relation":"mining colleague","note":"Shares dedication to the mining craft"},"Chief Larak":{"aff":55,"type":"professional","relation":"stronghold chief","note":"Serves through her mining work; trusted with longhouse key"},"Malacath":{"aff":85,"type":"fanatical","relation":"revered deity","note":"Views mining as sacred duty blessed by Malacath","best":"Every swing of the pickaxe honors Malacath''s will"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gularzob', '{"Atub":{"aff":75,"type":"mentor","relation":"wise woman and advisor","note":"He takes her counsel seriously and defers to her wisdom in leading the stronghold","best":"Her guidance helped him transition from guard to chieftain"},"Malacath":{"aff":90,"type":"fanatical","relation":"patron deity","note":"Divinely chosen to lead Largashbur, he is honored but humbled by the selection","best":"Malacath personally named him chieftain, seeing true Orcish leadership in him"},"Yamarz":{"aff":-80,"type":"contempt","relation":"failed predecessor","note":"His betrayal of the tribe serves as a permanent cautionary lesson for Gularzob''s rule","worst":"Yamarz betrayed all of Largashbur, weakening the stronghold under his cowardly leadership"},"Largashbur Tribe":{"aff":70,"type":"protective","relation":"chieftain","note":"He maintains hands-on leadership, continuing guard patrols despite his elevated status","best":"Vows to never allow another betrayal like Yamarz''s so long as he rules"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gulum-ei', '{"East Empire Company":{"aff":15,"type":"transactional","relation":"employer","note":"Provides his livelihood and cover while he systematically steals from their inventory","best":"Secured a stable position with warehouse access","worst":"Constant risk of discovery for his ongoing theft"},"Thieves Guild":{"aff":35,"type":"professional","relation":"criminal associate","note":"Former close partner who cut ties out of greed, later reconciled and resumed fencing stolen goods","best":"Re-established profitable partnership with Guild protection and influence in Solitude","worst":"Betrayed the Guild by cutting them out of deals for personal profit"},"Mercer Frey":{"aff":-25,"type":"suspicious","relation":"former guildmaster","note":"Mutual distrust after Gulum-Ei stopped dealing with the Guild and Mercer suspected his involvement in the Goldenglow sale","best":"Initially profitable working arrangement","worst":"Told Mercer he would no longer deal with the Guild"},"Deeja":{"aff":25,"type":"familial","relation":"sister","note":"Criminal siblings who coordinate smuggling opportunities but compete for profit","best":"Collaborates on dockside theft schemes","worst":"Competing criminal interests strain family loyalty"},"Jaree-Ra":{"aff":25,"type":"familial","relation":"brother","note":"Criminal siblings who share information about incoming cargo but have diverging ambitions","best":"Shares intelligence on valuable shipments like Hammerfell steel","worst":"Jaree-Ra''s impatience and Deeja''s greed create tension"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
