INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gunjar', '{"Ralof":{"aff":85,"type":"platonic","relation":"brother-in-arms","note":"Close friend who fought alongside him and mourned his death at Helgen Keep","best":"Fighting side by side in numerous battles before their capture","worst":"Dying before Ralof could reach him in Helgen Keep"},"Ulfric Stormcloak":{"aff":70,"type":"fanatical","relation":"commander","note":"Devoted follower who served under Ulfric in the rebellion"},"Imperial Legion":{"aff":-85,"type":"enemy","relation":"captors","note":"Captured near Pale Pass and sentenced him to execution at Helgen","worst":"Capture and death sentence at Helgen"},"Stormcloaks":{"aff":75,"type":"platonic","relation":"faction","note":"Brothers and sisters in arms united for Skyrim''s independence"}}')
