INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gunmar', '{"Isran":{"aff":65,"type":"professional","relation":"commander","note":"Respects his leadership despite personality clashes and Isran''s stubborn independence","best":"Agreed to rejoin Dawnguard upon hearing about the vampire threat","worst":"Isran previously insisted he could handle everything alone and kept others out of Fort Dawnguard"},"Sorine Jurard":{"aff":55,"type":"professional","relation":"colleague","note":"Shares mutual respect grounded in each other''s technical expertise"},"Florentius Baenius":{"aff":25,"type":"professional","relation":"colleague","note":"Tolerates his eccentricities only for the sake of the Dawnguard''s mission"},"Vampires":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Deep hatred rooted in the loss of loved ones to vampire attacks","worst":"Lost loved ones to vampire attacks"}}')
ON CONFLICT (npc_name) DO UPDATE
