INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gunnar_stone-eye', '{"Haming":{"aff":85,"type":"protective","relation":"ward","note":"Entrusted with Haming''s safety during Alduin''s attack and kept the boy alive","best":"Fulfilled his promise to Hadvar by protecting Haming through the dragon attack","worst":"The terror of watching Helgen burn while trying to shield a child"},"Hadvar":{"aff":65,"type":"professional","relation":"trusted ally","note":"Hadvar entrusted Haming''s safety to Gunnar before going to find General Tullius","best":"Being deemed trustworthy enough to protect a child during the end of the world"},"Lod":{"aff":70,"type":"familial","relation":"brother","note":"Creation Kit data identifies Lod as Gunnar''s brother"},"Torolf":{"aff":55,"type":"platonic","relation":"neighbor","note":"Respects Torolf as Haming''s father and fellow townsman of Helgen"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('guthrum', '{"Captain Wayfinder":{"aff":45,"type":"mentor","relation":"captain","note":"Respects his position but sees him as inexperienced and still learning the ways of command","best":"Watching the young captain finally grasp a difficult seamanship lesson","worst":"Bitting his tongue when Wayfinder makes an obvious novice mistake"},"Sea Squall Crew":{"aff":35,"type":"platonic","relation":"fellow crew","note":"Shares the bond of lifelong sailors who understand the sea in their blood"}}')
