INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('gwilin', '{"Temba Wide-Arm":{"aff":25,"type":"professional","relation":"employer","note":"She is harsh and critical but he tolerates her temper with philosophical patience","worst":"Being publicly berated for cutting boards to the wrong length"},"Wilhelm":{"aff":45,"type":"platonic","relation":"innkeeper","note":"Wilhelm expresses concern about how Temba treats him"},"His Father":{"aff":75,"type":"familial","relation":"father","note":"His teachings about finding joy and contentment guide Gwilin''s entire outlook","best":"Receiving the life lesson to go out and experience the world"},"Klimmek":{"aff":30,"type":"platonic","relation":"neighbor","note":"Casual acquaintance who chats about the 7,000 Steps"}}')
