INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('haafingar_guard', '{"Captain Aldis":{"aff":45,"type":"professional","relation":"commanding officer","note":"Direct superior who oversees training and deployment"},"Fellow Haafingar Guards":{"aff":65,"type":"platonic","relation":"comrades","note":"Close-knit brotherhood forged through shared duty and patrol"},"Imperial Legion":{"aff":55,"type":"professional","relation":"former unit","note":"Served in Legion during youth, maintains cooperative ties with local garrison"},"Bandits":{"aff":-75,"type":"enemy","relation":"adversaries","note":"Persistent threats to road safety and settlements"}}')
