INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hadvar', '{"Alvor":{"aff":85,"type":"familial","relation":"uncle","note":"Raised Hadvar and taught him smithing fundamentals","best":"Learning the forge alongside his uncle in Riverwood"},"General Tullius":{"aff":60,"type":"professional","relation":"commanding officer","note":"Respects Tullius as a capable leader worth following"},"Ralof":{"aff":25,"type":"rival","relation":"former childhood friend","note":"Once close friends, now divided by opposing sides in the Civil War","best":"Growing up together in Riverwood","worst":"Facing each other as enemies at Helgen"},"Imperial Legion":{"aff":75,"type":"professional","relation":"military faction","note":"Loyal and dedicated soldier who believes in the Empire''s mission"}}')
