INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('haelga', '{"Svana Far-Shield":{"aff":30,"type":"familial","relation":"niece","note":"Took her in after bandits killed her parents, but Svana resents being worked like a servant and disapproves of her Dibellan practices","best":"Saved her from the orphanage after her parents died","worst":"Svana conspired to collect marks of Dibella to shame her"},"Bolli":{"aff":65,"type":"romantic","relation":"lover","note":"Regular companion who meets her for drinks at the Bee and Barb each evening","best":"Their nightly meetings at the Bee and Barb"},"Indaryn":{"aff":45,"type":"romantic","relation":"lover","note":"One of her partners in the Dibellan Arts who carries her mark"},"Hofgrir Horse-Crusher":{"aff":45,"type":"romantic","relation":"lover","note":"One of her partners in the Dibellan Arts who carries her mark"},"Madesi":{"aff":25,"type":"transactional","relation":"craftsman","note":"Crafts her Marks of Dibella without knowing their true intimate purpose"}}')
