INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hafjorg', '{"Elgrim":{"aff":70,"type":"romantic","relation":"husband","note":"Loves him despite his crankiness; nags him about the shop''s damp location and his neglect of meals","best":"Built a life and business together around their shared passion for alchemy","worst":"He insisted on the canal district shop against her warnings about the damp and dirt"},"Filnjar":{"aff":40,"type":"professional","relation":"ore supplier","note":"Business contact in Shor''s Stone who provides ore samples for identification"},"Ingun Black-Briar":{"aff":15,"type":"jealous","relation":"husband''s alchemy student","note":"Resents the attention Elgrim devotes to mentoring Ingun; wishes he had tutored her instead","worst":"Elgrim gushes about Ingun''s talent and focuses far more attention on her than he ever did on teaching Hafjorg"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hafnar_ice-fist', '{"Savos Aren":{"aff":-85,"type":"betrayed","relation":"expedition leader, betrayer","note":"Trusted Savos and agreed to stay together; Savos lied and sacrificed him to bind Morokei","best":"Agreed to face the final challenge together, side by side","worst":"Savos looked him in the eyes and lied, then enthralled him as an eternal sacrifice"},"Atmah":{"aff":75,"type":"platonic","relation":"close companion","note":"Faced the end together; shared deep mutual loyalty through the expedition''s darkest moments","best":"She vowed to stay right with him no matter what came through the door","worst":"Both were enthralled by Savos and condemned to eternal servitude binding Morokei"},"Takes-In-Light":{"aff":45,"type":"platonic","relation":"expedition companion","note":"Fellow mage who perished in Labyrinthian; Hafnar reported her death to the others"},"Elvali Veren":{"aff":35,"type":"platonic","relation":"expedition companion","note":"Colleague who died when something grabbed her from behind; Hafnar witnessed her death"},"Girduin":{"aff":30,"type":"platonic","relation":"expedition companion","note":"First to fall during the expedition; Hafnar pragmatically argued against going back for him"},"College of Winterhold":{"aff":55,"type":"professional","relation":"academic home","note":"His professional home and the institution that trained him as a mage"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hajvarr_iron-hand', '{"Ulfr the Blind":{"aff":80,"type":"protective","relation":"uncle","note":"Fiercely guards his blind uncle from ridicule and harm","best":"Keeping Ulfr safe and useful at White River Watch","worst":"Learning his men mock Ulfr behind his back"},"Rodulf":{"aff":-25,"type":"contempt","relation":"subordinate","note":"Warned him explicitly to stop mocking Ulfr","worst":"Rodulf''s jokes about his blind uncle"},"White River Watch Bandits":{"aff":40,"type":"professional","relation":"followers","note":"Commands their respect through fear and loyalty"},"Whiterun Guard":{"aff":-60,"type":"enemy","relation":"pursuers","note":"Seek his capture but have not yet succeeded"},"Whiterun Jarl":{"aff":-50,"type":"enemy","relation":"adversary","note":"Wants him driven from the hold"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hakon_one-eye', '{"Gormlaith Golden-Hilt":{"aff":85,"type":"platonic","relation":"shield-sister, fellow Tongue","note":"He tempered her bloodlust with caution; her death at Alduin''s jaws devastated him","best":"Fighting side by side against the dragons","worst":"Watching Alduin seize and kill her atop the Throat of the World"},"Felldir the Old":{"aff":60,"type":"platonic","relation":"fellow Tongue, comrade","note":"Respected ally despite sharp disagreement over the Elder Scroll; ultimately trusted his judgment when Gormlaith fell","best":"Standing together to banish Alduin with the Scroll","worst":"Felldir bringing the Elder Scroll against their agreed plan"},"Alduin":{"aff":-100,"type":"nemesis","relation":"World-Eater, arch-foe","note":"Primary antagonist across multiple eras; slew Gormlaith and enslaved mankind","worst":"Alduin killing Gormlaith and proving unkillable by mortal strength alone"},"Last Dragonborn":{"aff":75,"type":"platonic","relation":"crucial ally","note":"The one destined to finish what the ancient Tongues started; Hakon aided them in Sovngarde","best":"Joining the Dragonborn in the final battle against Alduin in Sovngarde"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('halbarn_iron-fur', '{"Bujold":{"aff":25,"type":"professional","relation":"former leader","note":"Respects her past leadership but accepts her banishment for dishonesty","worst":"She lied about retaking Thirsk, and lying is the first step to cowardice"},"Elmus":{"aff":55,"type":"platonic","relation":"close colleague","note":"Fellow Thirsk resident who helped him restore the forge after the occupation","best":"Elmus helped wash out the forge when they retook the hall"},"Kuvar":{"aff":45,"type":"professional","relation":"client","note":"Regular client who commissions armor and gives him friendly grief about delays"},"Rieklings":{"aff":-75,"type":"enemy","relation":"invaders","note":"Despises the creatures that drove Thirsk''s Nords from their home and ruined his forge","worst":"They filled his forge with slop for their beasts and made off with his materials"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('haldyn', '{"Blood Horkers":{"aff":35,"type":"professional","relation":"crew","note":"Built the gang from nothing into a feared pirate organization and rules them through intimidation"},"East Empire Company":{"aff":-85,"type":"enemy","relation":"target","note":"Sworn enemies due to his repeated raids on their shipping vessels","worst":"Their ships are ripe for the taking"},"Adelaisa Vendicci":{"aff":-90,"type":"nemesis","relation":"antagonist","note":"She seeks his death and leads the mission to destroy him and his operation","worst":"She brought soldiers to my fortress"},"Local Pirates":{"aff":15,"type":"professional","relation":"rivals","note":"Respected and feared among regional pirate groups, maintaining dominance through reputation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('halldir', '{"Cairn Undead":{"aff":15,"type":"transactional","relation":"minions","note":"Commands lesser undead within his burial cairn as guardians and tools"},"Local Nords":{"aff":-55,"type":"contempt","relation":"prey","note":"Views the living merely as resources to harvest; locals who know of him warn others away"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hamal', '{"Fjotra":{"aff":85,"type":"protective","relation":"Sybil ward","note":"Responsible for nurturing and preparing the new Sybil for her lifelong communion with Dibella","best":"Fjotra was safely returned to the temple and her reverie could begin","worst":"The previous Sybil was lost to the temple, disrupting sacred traditions"},"Dibella Priestesses":{"aff":70,"type":"mentor","relation":"spiritual mother","note":"Guides and oversees all priestesses of the Inner Sanctum as their Mother"},"Betrid Silver-Blood":{"aff":-40,"type":"rival","relation":"former temple servant","note":"Marked internally as a rival; bad blood lingers from Betrid''s prior service at the Temple"},"Temple Guards":{"aff":35,"type":"professional","relation":"subordinates","note":"Commands their loyalty in protecting the Inner Sanctum and its secrets"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hamelyn', '{"College of Winterhold Faculty":{"aff":-85,"type":"enemy","relation":"former instructors","note":"Believes they persecuted him out of jealousy and expelled him unjustly","worst":"Beaten and expelled from the College"},"Venomfang Skeevers":{"aff":75,"type":"obsessed","relation":"beloved creations","note":"Considers his mutated creatures his children and loyal army","best":"Successfully bred venomous skeevers in the meadery basement"},"Sabjorn":{"aff":-20,"type":"contempt","relation":"unknowing host","note":"Occupying his meadery basement without his knowledge or consent"},"Mallus Maccius":{"aff":5,"type":"transactional","relation":"secret exploiter","note":"Mallus exploits his skeever infestation for sabotage while he remains largely unaware of the full scheme"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('haming', '{"Froki Whetted-Blade":{"aff":75,"type":"familial","relation":"grandfather and guardian","note":"Took Haming in after Helgen; teaches him hunting and survival","best":"Listening to Froki''s stories about killing his first stag at eleven"},"Torolf":{"aff":95,"type":"familial","relation":"deceased father","note":"Sacrificed himself to save Haming during the dragon attack","best":"His father''s last words: Make me proud","worst":"Watching his father fall to Alduin''s fire breath"},"Matlara":{"aff":85,"type":"familial","relation":"deceased mother","note":"Perished in the Helgen dragon attack"},"Hadvar":{"aff":65,"type":"grateful","relation":"savior","note":"Imperial soldier who guided him to safety during the attack on Helgen","best":"Hadvar calling him to safety when the dragon struck"},"Alduin":{"aff":-95,"type":"nemesis","relation":"parents'' killer","note":"Dragon who destroyed Helgen and orphaned him; vows to kill a dragon alone someday","worst":"The fire that consumed his home and father"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('harald', '{"Fenrik":{"aff":-85,"type":"servant","relation":"vampire''s thrall","note":"Dominated by Fenrik''s vampiric will, his true self buried beneath enforced obedience","worst":"Falling under Fenrik''s thrall and losing all free will"},"Thoring":{"aff":15,"type":"professional","relation":"employer","note":"Considers Harald a reliable worker, completely unaware of his dark secret"},"Vigilants of Stendarr":{"aff":-30,"type":"enemy","relation":"unknowing adversaries","note":"His forced cult involvement makes him their target despite being an unwitting victim","worst":"Would be destroyed by Vigilants if his connection to Molag Bal''s cult were exposed"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('haran', '{"Dagur":{"aff":85,"type":"romantic","relation":"husband","note":"Loves him deeply but keeps painful truths from him to protect him","best":"Running The Frozen Hearth together through hard years","worst":"His naivety about Ranmir''s dangerous connections"},"Eirid":{"aff":90,"type":"familial","relation":"daughter","note":"Beloved daughter whose future in declining Winterhold she worries over"},"Ranmir":{"aff":15,"type":"pitying","relation":"debtor","note":"Owes massive debt but she sees him as a good man broken by loss","best":"When he still paid regularly and traded items for his tab","worst":"His angry rant when she cut off his drinking"},"College of Winterhold":{"aff":25,"type":"transactional","relation":"primary clientele","note":"Essential to the inn''s survival but she keeps a cautious distance from the mages"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('harlaug', '{"Thoring":{"aff":30,"type":"professional","relation":"innkeeper","note":"Maintains a business relationship with the Windpeak Inn''s keeper"},"Other Ferrymen":{"aff":15,"type":"rival","relation":"competitors","note":"Respected for taking dangerous routes they refuse"},"Dawnstar Guards":{"aff":25,"type":"professional","relation":"business contacts","note":"Keeps cordial relations to ensure smooth ferry operations"},"Local Fishermen":{"aff":35,"type":"platonic","relation":"fellow sailors","note":"Shares weather and water hazard information","best":"Swapping sea stories and warnings over mugs at the dock"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('harrald', '{"Laila Law-Giver":{"aff":75,"type":"familial","relation":"mother","note":"Loyal son who shapes his public beliefs to please her","best":"Devoted himself to supporting her rule and the Stormcloak cause she champions"},"Saerlund":{"aff":-85,"type":"estranged","relation":"disowned brother","note":"Would execute him for Imperial sympathies if he were Jarl","best":"They were once inseparable, fighting back to back as brothers","worst":"Admitted he would hang his own brother from the gallows for treason"},"Balimund":{"aff":-20,"type":"contempt","relation":"blacksmith","note":"Considers him beneath his station despite relying on his services"},"Stormcloaks":{"aff":85,"type":"fanatical","relation":"ideological ally","note":"Staunch and vocal supporter of the Stormcloak cause and Nordic nationalism"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hathrasil', '{"Omluag":{"aff":35,"type":"platonic","relation":"coworker","note":"Over a decade of shared labor with minimal words but mutual concern","best":"Warning about molten metal shows underlying care","worst":"Dismissive responses frustrate his only workplace companion"},"Mulush":{"aff":-65,"type":"fearful","relation":"supervisor","note":"Oppressive overseer who rules through threats and intimidation","worst":"Mulush threatens to break legs and throw workers in the river"},"Silver-Blood Family":{"aff":-30,"type":"transactional","relation":"employers","note":"Distant but all-controlling family he is resigned to serving"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('headless_horseman', '{"Ancient Nordic Warriors":{"aff":75,"type":"protective","relation":"warden","note":"Guards their remains at Hamvir''s Rest for all eternity","best":"Maintaining eternal vigil over their sacred burial ground","worst":"Unable to rest alongside those he protects"},"Spectral Steed":{"aff":55,"type":"protective","relation":"eternal mount","note":"Faithful phantom companion in endless nocturnal rides"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('heddic_volunnar', '{"Kvenel the Tongue":{"aff":85,"type":"fanatical","relation":"believed ancestor","note":"His life''s quest was to prove his descent from Kvenel and claim his legacy","best":"Tracked Kvenel''s tomb to Volunruud after years of research","worst":"Died in Volunruud without ever opening the tomb or proving the ancestral connection"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hefid_the_deaf', '{"Knjakr the Chef":{"aff":5,"type":"neutral","relation":"fellow Ratway resident","note":"Shares the Warrens space; his grinding wheel activity can disturb her isolation","worst":"His noise draws unwanted attention that breaks her fragile seclusion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('heimskr', '{"Jarl Balgruuf":{"aff":40,"type":"grateful","relation":"tolerant jarl","note":"Grateful Balgruuf permits his preaching despite Imperial pressure to silence Talos worship"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"persecutors","note":"Would arrest him for illegal worship; he defiantly preaches against them","worst":"The White-Gold Concordat outlawing Talos worship"},"Stormcloaks":{"aff":85,"type":"fanatical","relation":"spiritual allies","note":"Serves as spiritual inspiration to their cause; welcomed their liberation of Whiterun with tears of joy","best":"Stormcloaks liberating Whiterun from Imperial control"},"Imperials":{"aff":-75,"type":"enemy","relation":"oppressors","note":"Despises them as cowards for enforcing the Concordat and silencing Talos worship","worst":"Arrested multiple times for preaching; only freed through bribes"},"Whiterun Guards":{"aff":20,"type":"neutral","relation":"cautious watchers","note":"They maintain a protective watch over him despite the illegality of his ministry"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('heimvar', '{"Beirand":{"aff":65,"type":"mentor","relation":"master blacksmith","note":"Playfully competitive apprenticeship built on mutual respect and banter","best":"Trading jests about mead-drinking and forge skills","worst":"Being told his forge-stoking is worse than Beirand''s young son''s"},"Captain Aldis":{"aff":40,"type":"professional","relation":"guard captain","note":"Shares concerns about suspicious activity in the city"},"Jaree-Ra":{"aff":-55,"type":"suspicious","relation":"suspected criminal","note":"Considers him a plague on the city and believes he is up to no good","worst":"Knowing Jaree-Ra is dangerous but lacking proof"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('helgi''s_ghost', '{"Hroggar":{"aff":80,"type":"familial","relation":"father","note":"Still longs for his presence and approval even after death","best":"He made her favorite dolly"},"Laelette":{"aff":-55,"type":"fearful","relation":"vampire who turned her","note":"Terror mixed with confused understanding that Laelette didn''t want to burn her","worst":"Laelette kissed her on the neck, making her so cold the fire couldn''t even hurt"},"Helgi''s Mother":{"aff":90,"type":"familial","relation":"mother","note":"Deep bond that transcends death; finally reunites with her for peace","best":"Hearing her mother call to her when it was time to sleep"},"Movarth":{"aff":-90,"type":"nemesis","relation":"master vampire who ordered her death","note":"Orchestrated the destruction of her entire family from the shadows","worst":"Ordered Laelette to burn her and her mother alive"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('helgird', '{"Jorleif":{"aff":35,"type":"professional","relation":"steward","note":"Windhelm''s steward who oversees her work at the Hall of the Dead and coordinates death investigations"},"Calixto Corrium":{"aff":15,"type":"curious","relation":"visitor","note":"Occasional visitor to the Hall of the Dead who shows unusual interest in her embalming work"},"Susanna the Wicked":{"aff":25,"type":"pitying","relation":"murder victim","note":"Examined her mutilated body during the Blood on the Ice investigation","worst":"Found strange curved cuts on her body reminiscent of ancient Nordic embalming blades"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('helvard', '{"Jarl Siddgeir":{"aff":40,"type":"professional","relation":"liege","note":"Serves with professional loyalty despite disagreements over guard wages and practical concerns","best":"Maintaining order and security for the hold","worst":"Being ordered to reduce guard wages during wartime"},"Nenya":{"aff":55,"type":"professional","relation":"colleague","note":"Respects her impeccable service record and works closely on hold administration","best":"Collaborating on hold defense and supply concerns"},"Dengeir":{"aff":45,"type":"professional","relation":"former employer","note":"Respects his past service as Jarl though acknowledges his time has passed"},"Hold Guards":{"aff":50,"type":"protective","relation":"subordinates","note":"Commands and advocates for their fair treatment and compensation"},"Dark Brotherhood":{"aff":-90,"type":"enemy","relation":"assassins","note":"Marked target for assassination contract"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hemming_black-briar', '{"Maven Black-Briar":{"aff":85,"type":"familial","relation":"mother","note":"Follows her will like a loyal dog; slips calling her ''mother'' even when she is Jarl","best":"Appointed steward at her side when she became Jarl","worst":"Will never escape her shadow or earn independence"},"Sibbi Black-Briar":{"aff":50,"type":"familial","relation":"brother","note":"Favors Sibbi and believes he will be a fine leader despite his imprisonment"},"Ingun Black-Briar":{"aff":15,"type":"familial","relation":"sister","note":"Dismissive of her lack of interest in the family business","worst":"Openly disparages her priorities to strangers"},"Mjoll the Lioness":{"aff":-40,"type":"rival","relation":"critic","note":"She publicly calls him a spoiled brat who follows his mother like a loyal dog","worst":"Her vocal contempt undermines his image in Riften"},"Maul":{"aff":25,"type":"professional","relation":"family bodyguard","note":"Maul recognizes his stubbornness but serves the family loyally"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('heratar', '{"Sinding":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Hunting him relentlessly for his lycanthropy, driven by vengeance for family killed by werewolves","worst":"The werewolf who embodies everything he hates"},"Rissing":{"aff":45,"type":"professional","relation":"hunting partner","note":"Fellow hunter who shares the pursuit of dangerous beasts"},"Hircine":{"aff":85,"type":"fanatical","relation":"revered deity","note":"Reveres the Daedric Prince as master of the hunt and seeks to prove himself worthy","best":"Chosen to participate in Hircine''s Great Hunt"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('herika', '{"Player":{"aff":65,"type":"platonic","relation":"traveling companion","note":"Trusted companion and frequent target of her jokes and banter"},"Local hunters":{"aff":40,"type":"professional","relation":"information network","note":"Share knowledge of game movements and regional dangers"},"Merchant caravans":{"aff":30,"type":"transactional","relation":"clients","note":"Regular employers who hire her as wilderness guide and guard"},"Her merchant family":{"aff":15,"type":"estranged","relation":"family","note":"Left behind the traditional commerce life in High Rock to forge her own path"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('herkja', '{"Sirkjorg":{"aff":65,"type":"platonic","relation":"companion","note":"Close fellow warrior in Bujold''s group, labored alongside at the Temple of Miraak"},"Bujold the Unworthy":{"aff":25,"type":"professional","relation":"leader","note":"Follows her but frustrated by hesitation and indecision","worst":"Waiting endlessly for Bujold to give the word to act"},"Miraak":{"aff":-85,"type":"enemy","relation":"former captor","note":"Enslaved and forced to work on his temple against her will"},"Herika":{"aff":-5,"type":"dismissive","relation":"none","note":"Explicitly denies any relation to this Breton"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('herluin_lothaire', '{"Delvin Mallory":{"aff":65,"type":"indebted","relation":"guild patron","note":"Arranged Herluin''s position in the Ragged Flagon"},"Vex":{"aff":45,"type":"professional","relation":"guild superior","note":"Respects her authority; advises offenders to pay debts to her quickly"},"Tonilia":{"aff":35,"type":"professional","relation":"fellow merchant","note":"Cordial relationship as fellow Ragged Flagon vendor"},"Thieves Guild":{"aff":75,"type":"protective","relation":"guild affiliation","note":"Shows unwavering loyalty; refuses service to those who break Guild rules"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hermir_strong-heart', '{"Oengul War-Anvil":{"aff":80,"type":"mentor","relation":"mentor","note":"Deeply respects Oengul as her teacher and values his guidance above any other smith","best":"Oengul praised her as a decent smith and stayed in Windhelm to finish teaching her","worst":"Petty arguments over misplaced tools at the forge"},"Ulfric Stormcloak":{"aff":90,"type":"fanatical","relation":"devoted supporter","note":"Chose smithing specifically to craft weapons for Ulfric''s army and reveres him as a hero","best":"Seeing Ulfric live up to his legend up close in Windhelm","worst":"Learning of Ulfric''s death if Windhelm falls to the Empire"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hern', '{"Hert":{"aff":85,"type":"romantic","relation":"wife","note":"Vampire partner in business and hunting at Half-Moon Mill","best":"Sharing their undead existence and building their cover together","worst":"Constant danger of discovery threatening their life together"},"Dark Brotherhood":{"aff":-80,"type":"enemy","relation":"assassination target","note":"Targeted for elimination by the Brotherhood","worst":"Learning the Brotherhood has come for old Hern"},"Local Hunters":{"aff":-25,"type":"suspicious","relation":"occasional prey","note":"Keeps cautious distance while occasionally preying upon them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hero_of_sovngarde', '{"Shor":{"aff":90,"type":"fanatical","relation":"revered lord","note":"Reveres Shor as divine patron and obeys his command to curb wrath against Alduin","best":"Welcomed into Shor''s hall after glorious death in battle"},"Tsun":{"aff":70,"type":"professional","relation":"shield-thane","note":"Respects Tsun as guardian of the Whalebone Bridge and shield-thane of Shor"},"Ysgramor":{"aff":75,"type":"platonic","relation":"fellow hero","note":"Shares eternal fellowship with the legendary founder of the Companions in the Hall of Valor"},"Alduin":{"aff":-85,"type":"nemesis","relation":"foul worm","note":"Longs to face the World-Eater but is forbidden by Shor''s command","worst":"Alduin''s foul mist spreads fear beyond Shor''s protected hall"},"Fellow Heroes of Sovngarde":{"aff":65,"type":"platonic","relation":"brothers and sisters in arms","note":"Shares feasting, sparring, and eternal fellowship with fellow Nord heroes"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hert', '{"Hern":{"aff":85,"type":"romantic","relation":"husband","note":"Vampire partners who run Half-Moon Mill together as cover for their predation","best":"Living and hunting together in peaceful isolation at the mill","worst":"The war bringing increased patrols that threaten their shared secret"},"Falkreath Hold Guards":{"aff":-40,"type":"suspicious","relation":"unwanted observers","note":"Views patrols as nosy pests who interfere with their hunting and privacy","worst":"Increased military patrols disrupting their feeding and risking exposure"},"Travelers":{"aff":-10,"type":"contempt","relation":"prey","note":"Uses excessive warmth and hospitality to disarm visitors who serve as convenient food sources","best":"A lone traveler who provided both profit and sustenance without complication"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hestla', '{"Lord Harkon":{"aff":85,"type":"fanatical","relation":"revered leader","note":"Keeps the forge running day and night for him and considers herself unworthy compared to his power","best":"Being accepted into his court as a vampire","worst":"Knowing she is not half the vampire he is"},"The Companions":{"aff":-45,"type":"estranged","relation":"former brothers and sisters","note":"Resents being called whelp and their self-righteous attitude; now boasts she could slaughter them all","worst":"Never advancing beyond whelp and being looked down upon"},"Volkihar Clan":{"aff":60,"type":"familial","relation":"clan member and blacksmith","note":"Found purpose and belonging among the vampires; eager to prove her worth through service","best":"Being valued for her smithing expertise","worst":"Feeling out of her league among more powerful vampires"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hewnon_black-skeever', '{"Drahff":{"aff":15,"type":"professional","relation":"partner in crime","note":"Subordinate in the partnership; follows Drahff''s lead despite broken promises and doubt","best":"Drahff convinced him their scheme would bring wealth and a proper home","worst":"Still living in a sewer while Drahff''s promises remain unfulfilled"},"Thieves Guild":{"aff":-55,"type":"fearful","relation":"unsanctioned rival operators","note":"Operating in Guild territory without permission; terrified of being discovered","worst":"Convinced they would be skinned alive if the Guild learned of their scheme"},"Black-Briar Family":{"aff":-20,"type":"jealous","relation":"envied elite","note":"Resents their wealth and power, measuring his own failure against their success","worst":"Drahff had promised them a house as grand as the Black-Briars'', a bitter reminder of how far they fell short"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('high_king_torygg', '{"Elisif the Fair":{"aff":95,"type":"romantic","relation":"wife","note":"His sole regret in death was leaving her bereft","best":"Their life together as rulers of Solitude","worst":"Dying and leaving her forlorn and weeping"},"Ulfric Stormcloak":{"aff":-85,"type":"nemesis","relation":"killer","note":"Once respected as a thane, killed Torygg with the Shout in traditional challenge","best":"Facing him fearlessly and dying with honor unstained","worst":"Being slain by his savage Shout"},"Titus Mede II":{"aff":55,"type":"professional","relation":"imperial superior","note":"Maintained strong Imperial ties while respecting Nordic traditions"},"Sybille Stentor":{"aff":50,"type":"professional","relation":"court wizard","note":"Trusted advisor in the Blue Palace court"},"Falk Firebeard":{"aff":55,"type":"professional","relation":"steward","note":"Loyal steward who served both Torygg and Elisif faithfully"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hilde', '{"Sven":{"aff":85,"type":"familial","relation":"son","note":"Fiercely protective and proud of her bard son","best":"Praising his snow lark voice and true Nord strength","worst":"Him dismissing her dragon sighting as crazy fantasy"},"Camilla Valerius":{"aff":45,"type":"protective","relation":"potential daughter-in-law","note":"Cautiously approves of her for Sven but wary of her talking to Faendal"},"Faendal":{"aff":-75,"type":"enemy","relation":"romantic rival","note":"Despises him as a filthy elf pursuing Camilla","worst":"Seeing him talk to Camilla"},"Sigrid":{"aff":35,"type":"platonic","relation":"neighbor","note":"Fellow over-protective mother, converses about their children"},"Riverwood Guard":{"aff":-15,"type":"contempt","relation":"local guards","note":"They dismiss her dragon claims and brush her off as a bothersome old woman","worst":"Guard telling her to get lost when she begged them to discourage Sven from joining the war"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hillevi_cruel-sea', '{"Torsten Cruel-Sea":{"aff":85,"type":"romantic","relation":"husband","note":"Beloved partner in both marriage and the Hollyfrost Farm business","best":"Building Hollyfrost Farm together from nothing into a thriving enterprise"},"Grimvar Cruel-Sea":{"aff":80,"type":"familial","relation":"son","note":"Devoted mother ensuring his proper upbringing alongside her demanding work"},"Torbjorn Shatter-Shield":{"aff":60,"type":"platonic","relation":"friend","note":"Supported him and Tova with kindness and cooking after Friga''s death","best":"Being called a good friend in a time of need after sending mince pie","worst":"Helpless sorrow witnessing his grief over losing his daughter"},"Nilsine Shatter-Shield":{"aff":55,"type":"platonic","relation":"customer and friend","note":"Friendly market banter and loyal produce customer","best":"Sharing warm laughter over Nord honor promises about tomatoes"},"Wuunferth the Unliving":{"aff":40,"type":"transactional","relation":"client","note":"Paid to grow Nightshade for the court wizard; no deeper connection"},"Tulvur":{"aff":55,"type":"professional","relation":"farm caretaker","note":"Ensures he receives fair pay despite Torsten''s complaints about him","best":"Reassuring him she handles his wages and recognizes his hard work"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hilund', '{"Bujold":{"aff":65,"type":"familial","relation":"elder sister","note":"Loyal but seeks her own identity outside Bujold''s shadow; deeply shocked if Bujold is exiled","best":"Comforting Bujold after the Riekling attack, refusing to blame her","worst":"Bujold dismissing her worry as unhelpful and pushing her away"},"Kuvar":{"aff":45,"type":"mentor","relation":"brother-in-law and combat trainer","note":"Respects his teaching but resents his harshness and criticism; horrified if he exiles Bujold","best":"Kuvar expressing pride in how she''s held up well","worst":"Kuvar calling her a layabout and exiling his own wife"},"Rieklings":{"aff":-85,"type":"enemy","relation":"invaders of her home","note":"Burning with desire for revenge after they drove her people from Thirsk","worst":"The Riekling swarm that forced them to flee their ancestral hall"},"Elmus":{"aff":20,"type":"platonic","relation":"fellow Thirsk companion","note":"Thinks he''s gone soft but doesn''t wish him ill; gossips about him privately","worst":"Telling the player not to repeat that she thinks he''s lost his edge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hired_thug', '{"Contract Givers":{"aff":25,"type":"transactional","relation":"employers","note":"Loyalty guaranteed only by coin; any job accepted regardless of ethics."},"Fellow Thugs":{"aff":45,"type":"professional","relation":"squad mates","note":"Close-knit combat unit with strong battlefield coordination and mutual reliance."},"Hold Guards":{"aff":-15,"type":"suspicious","relation":"law enforcement","note":"Cautious distance maintained to avoid serious legal consequences."},"Contract Target":{"aff":-60,"type":"enemy","relation":"mark","note":"Professional enmity; sent to deliver violent retribution with no option to yield.","worst":"Contract demands punishment without mercy or negotiation."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hjaalmarch_guard', '{"Jarl Idgrod Ravencrone":{"aff":65,"type":"professional","relation":"liege lord","note":"Sworn to serve and represent her authority in Hjaalmarch Hold"},"Stonehills Miners":{"aff":45,"type":"protective","relation":"protected workers","note":"Professional but cordial relationship with the miners they guard at Rockwallow Mine"},"Fellow Hjaalmarch Guards":{"aff":70,"type":"platonic","relation":"comrades","note":"Strong bonds of camaraderie and mutual support from shared duty"},"Imperial Legion":{"aff":50,"type":"professional","relation":"former service","note":"Served in the Legion during younger years; military background still shapes their discipline"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hjalfar', '{"Liesl":{"aff":65,"type":"professional","relation":"navigator","note":"Trusted crew member who serves as his navigator","best":"Relied on her navigation through a treacherous Sea of Ghosts storm"},"Benkum":{"aff":60,"type":"professional","relation":"sailor","note":"Loyal sailor serving under his command"},"Palevius Lex":{"aff":55,"type":"professional","relation":"crew member","note":"Valued crew member despite being an Imperial","best":"Proved his worth and loyalty aboard the vessel"},"Miraak":{"aff":-85,"type":"enemy","relation":"enslaver","note":"Enslaved Hjalfar and his crew at the Water Stone","worst":"Fell prey to Miraak''s spell, forced to work endlessly oblivious to the world"},"East Empire Company":{"aff":40,"type":"transactional","relation":"client","note":"Regular shipping contract holder for his merchant runs"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hjordis', '{"Majni":{"aff":45,"type":"professional","relation":"pack leader","note":"Offered sanctuary and promised aid reclaiming her territory; loyalty conditional until debt repaid"},"Frostmoon Pack":{"aff":55,"type":"protective","relation":"adopted pack","note":"Found refuge with them after losing her original pack; fiercely protective despite being an outsider"},"Werebears":{"aff":-100,"type":"nemesis","relation":"pack killers","note":"Destroyed her original pack; she burns for vengeance against them","worst":"They slaughtered everyone in her original pack in the northeastern mountains"},"Akar":{"aff":50,"type":"platonic","relation":"hunting companion","note":"Fellow Frostmoon pack member she trusts enough to hunt alongside"},"Former Pack":{"aff":95,"type":"familial","relation":"lost family","note":"Original pack killed by werebears; their memory drives her quest for vengeance","worst":"Werebears wiped out her entire family group leaving her the sole survivor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hjornskar_head-smasher', '{"Ulfric Stormcloak":{"aff":95,"type":"fanatical","relation":"revered leader","note":"Views Ulfric as the only true High King of Skyrim and the truest of all Nords","best":"Fighting under Ulfric''s banner for Skyrim''s freedom"},"Thalmor":{"aff":-100,"type":"nemesis","relation":"hated oppressors","note":"Intense hatred for the elves who forced the ban on Talos worship","worst":"Witnessing the enforcement of the White-Gold Concordat and persecution of Talos worshippers"},"Imperial Legion":{"aff":-85,"type":"enemy","relation":"bitter foes","note":"Despises the Empire for selling out Nordic gods and imposing Thalmor rule"},"Torygg":{"aff":-70,"type":"contempt","relation":"false king","note":"Believes Ulfric did right killing him for selling out his people for gold"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hjorunn', '{"Kharag gro-Shurkul":{"aff":72,"type":"platonic","relation":"employee and friend","note":"Trusted worker whose constant bickering masks genuine camaraderie","best":"Sharing mead and banter during breaks at the mill","worst":"Broke his fist on Kharag''s head during a playful scuffle"},"Solitude Guards":{"aff":15,"type":"neutral","relation":"city patrol","note":"Prefers they keep their distance from his business outside the walls"},"Stormcloaks":{"aff":-35,"type":"suspicious","relation":"political faction","note":"A Stormcloak once tried to burn down his mill, reinforcing his political neutrality","worst":"Stormcloak arson attempt on the sawmill"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hod', '{"Gerdur":{"aff":85,"type":"romantic","relation":"wife","note":"Beloved wife and business partner at the mill","best":"Building a prosperous life and mill together"},"Frodnar":{"aff":80,"type":"familial","relation":"son","note":"Encourages and mentors him in woodcutting","best":"Teaching Frodnar the lumber trade"},"Ralof":{"aff":55,"type":"familial","relation":"brother-in-law","note":"Welcomes him into their home despite Imperial danger","best":"Sheltering Ralof after his escape from Helgen"},"Alvor":{"aff":45,"type":"professional","relation":"blacksmith","note":"Alvor provides tools essential for the mill''s operation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hoddreid', '{"Sinding":{"aff":-85,"type":"enemy","relation":"final quarry","note":"Her target in Hircine''s Great Hunt who ultimately killed her","worst":"Sustained fatal wounds fighting him in Bloated Man''s Grotto"},"Hircine":{"aff":45,"type":"servant","relation":"hunt participant","note":"Participated in the Daedric Prince''s Great Hunt as one of his chosen hunters"},"Fellow Hunters":{"aff":55,"type":"professional","relation":"colleagues","note":"Respected peers who valued her magical approach despite typical Nord distrust of magic"},"College of Winterhold":{"aff":25,"type":"transactional","relation":"occasional contact","note":"Source of magical supplies and knowledge for her hunting work"},"Family":{"aff":15,"type":"estranged","relation":"kin","note":"Traditional Nord hunters shocked by her magical abilities, though she maintained hunting traditions"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hofgrir_horse-crusher', '{"Shadr":{"aff":45,"type":"professional","relation":"stable assistant","note":"Loyal assistant who helps run daily operations at Riften Stables"},"Haelga":{"aff":10,"type":"ex","relation":"former lover","note":"Had an intimate encounter in the stables; considers her out of control and wants to keep it quiet","worst":"She wanted to try it in the stables so I said yes"},"Svana Far-Shield":{"aff":-25,"type":"suspicious","relation":"adversary","note":"Seeks to expose his encounter with Haelga and damage his reputation"},"Riften Citizens":{"aff":30,"type":"professional","relation":"community","note":"Generally respected as a local business owner and stable master"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hogni_red-arm', '{"Hroki":{"aff":-65,"type":"rival","relation":"antagonist","note":"Openly expresses disgust at his practices and threatens him with Cidhna Mine","worst":"Threatened to have guards drag him off to Cidhna Mine and yank his filthy arms off"},"Degaine":{"aff":-55,"type":"rival","relation":"harasser","note":"Beggar who regularly insults and provokes him with fat jokes","worst":"Mocked him as Hogni Fat-Arm in the marketplace"},"Margret":{"aff":-25,"type":"contempt","relation":"critic","note":"Conflicts with him but he was shaken when she was attacked by a Forsworn agent","worst":"Ongoing disputes over his merchant practices"},"Dushnikh Yal Orcs":{"aff":50,"type":"professional","relation":"suppliers","note":"Respects their hunting and butchery skills; jokes about wanting an Orc wife","best":"Directed customers to their stronghold as the source of his finest meat"},"Silver-Blood Inn Staff":{"aff":25,"type":"transactional","relation":"landlords","note":"Tolerate his presence despite his reputation; he pays extra for the largest room"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('holgeir', '{"Fjori":{"aff":100,"type":"romantic","relation":"wife","note":"Met as enemies in battle but fell in love; their union brought peace between warring forest clans","best":"Finding love instead of death when their blades met in battle","worst":"Being separated by the snake''s venom and the chain of tragedy that followed"},"Lu''ah Al-Skaven":{"aff":-85,"type":"nemesis","relation":"conjurer who cursed them","note":"Raised Holgeir and Fjori as draugr, denying them their earned rest in Sovngarde","worst":"Being torn from Sovngarde and bound in undeath by her necromancy"},"Forest Clans":{"aff":45,"type":"professional","relation":"former enemies turned allies","note":"Once warring adversaries who found peace through his union with Fjori"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('horgeir', '{"Olda":{"aff":-50,"type":"estranged","relation":"wife","note":"Deeply unhappy marriage; he considers her a spiteful shrew with ice for a heart","best":"Admires her stubborn determination, which he says is why he married her","worst":"She calls him an embarrassment and says she doesn''t know why she married him"},"Lodvar":{"aff":55,"type":"familial","relation":"brother","note":"Lives and works together at the mill; shares easy camaraderie","best":"Jokes together about finding a good woman someday"},"Faida":{"aff":15,"type":"platonic","relation":"innkeeper","note":"Pities his situation but also reports his unpaid tabs to Olda","best":"Sympathizes with him over his wife''s affair","worst":"Tells Olda when he leaves the tavern without paying"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('horik_halfhand', '{"Brina Merilis":{"aff":95,"type":"protective","relation":"former commander, housecarl","note":"Served her for over 30 years; considers her and the Legion his only family","best":"I would have it no other way â€” standing by her side through war and retirement alike","worst":"Questioned her reliance on Great War strategy, then immediately apologized for implying any doubt in her leadership"},"Imperial Legion":{"aff":80,"type":"familial","relation":"former brothers-in-arms","note":"His true family since his parents died; proudly wears the armor despite opposition","best":"Finding belonging and purpose in the Legion after losing his family"},"Jarl Skald":{"aff":-40,"type":"rival","relation":"political opponent","note":"Tense relationship due to opposing allegiances; Skald displeased by Horik''s open display of Imperial armor"},"Madena":{"aff":-25,"type":"suspicious","relation":"court mage under Brina''s rule","note":"Openly distrusts her and vowed to watch her closely when Brina became Jarl"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('horker', '{"Local Horker Pod":{"aff":75,"type":"familial","relation":"pod member","note":"Close-knit family group providing mutual protection and companionship","best":"Huddling together for warmth during harsh winter storms"},"Coastal Mudcrabs":{"aff":-20,"type":"rival","relation":"territorial rival","note":"Occasional rivals for prime beaching spots along the shore"},"Nordic Hunters":{"aff":-65,"type":"fearful","relation":"dangerous predator","note":"Viewed as dangerous threats to be avoided or confronted when cornered","worst":"Podmates taken by hunters for meat and tusks"},"Ice Wraiths":{"aff":-30,"type":"rival","relation":"ecological competitor","note":"Natural competitors in the arctic ecosystem"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('horm', '{"Geimund":{"aff":85,"type":"familial","relation":"father and mentor","note":"Taught Horm everything about horse care; Horm reveres him deeply","best":"Learning the art of horse care at his father''s side","worst":"Assuming full responsibility after his father''s death"},"Fridrika":{"aff":65,"type":"familial","relation":"mother","note":"Maintains the household; steady familial bond"},"Katla":{"aff":45,"type":"professional","relation":"employer","note":"Farm owner who trusts the family with her stables"},"Grani":{"aff":75,"type":"protective","relation":"favorite horse","note":"Horm frequently checks on Grani and considers the horses almost family","best":"Sharing his own dinner with the horses during the lean year"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('horse', '{"Player Character":{"aff":75,"type":"protective","relation":"trusted mount","note":"Primary companion and faithful mount throughout countless adventures","best":"Being called back after surviving a dangerous journey together","worst":"Watching their rider fall in battle"},"Stable Masters":{"aff":45,"type":"platonic","relation":"former caretakers","note":"Raised and trained by stable hands in youth","best":"Warm oats and shelter during foalhood"},"Other Horses":{"aff":35,"type":"platonic","relation":"fellow equines","note":"Maintains friendly relations with other horses across Skyrim"},"Wolves and Bears":{"aff":-65,"type":"enemy","relation":"natural predators","note":"Constant adversaries encountered in the wilderness","worst":"Narrow escapes from predatory attacks on the trail"},"Giants":{"aff":-35,"type":"fearful","relation":"dangerous neighbors","note":"Maintains respectful distance after past encounters","worst":"Witnessing the devastating power of a giant''s club"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hrefna', '{"Tormir":{"aff":70,"type":"familial","relation":"mother","note":"Hardworking miner who provides for them, but clashes with Hrefna over outside cultural influences","best":"Following her mother to the mine and watching her work","worst":"Being scolded for learning from the elf and told to learn to be a Nord instead"},"Sondas Drenim":{"aff":85,"type":"mentor","relation":"caretaker and mentor","note":"Dunmer who looks after her while her mother works; shares stories about Morrowind and Dunmer culture","best":"Listening to Sondas''s stories about Morrowind and dreaming of seeing the fires"},"Derkeethus":{"aff":65,"type":"platonic","relation":"former friend","note":"Argonian who used to take her diving in the river before he disappeared","best":"Diving way down deep in the river together","worst":"He vanished and she misses him dearly"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hreinn', '{"Kleppr":{"aff":50,"type":"familial","relation":"father","note":"Encouraging mentor figure whose constant fighting with Frabbi troubles Hreinn deeply","best":"Told Hreinn he''ll be a fine innkeeper someday","worst":"Hreinn caught between parents'' disputes and forced to witness their loud arguments"},"Frabbi":{"aff":30,"type":"familial","relation":"mother","note":"Praises Hreinn but weaponizes his competence against Kleppr, creating uncomfortable loyalty conflicts","best":"Praises his work ethic and chores","worst":"Hreinn had to ask if she was going to walk over and hit his father again"},"Hroki":{"aff":55,"type":"familial","relation":"sister","note":"Fellow worker at the inn who shares the burden of their parents'' toxic dynamic","best":"Both praised by their mother as better than their father"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hroar', '{"Grelod the Kind":{"aff":-90,"type":"nemesis","relation":"abusive caretaker","note":"Wishes for her death and cheers when she is killed","worst":"Threatened with the belt for crying at night"},"Constance Michel":{"aff":70,"type":"grateful","relation":"kind caretaker","note":"Sneaks him extra food and treats the orphans well","best":"Given little snacks to help his growing appetite"},"Aventus Aretino":{"aff":60,"type":"admirer","relation":"former fellow orphan","note":"Supports his dark ritual to summon the Dark Brotherhood against Grelod","best":"Believes Aventus saved them all by having Grelod murdered"},"Samuel":{"aff":65,"type":"platonic","relation":"fellow orphan and friend","note":"Close bond formed through shared hardship under Grelod''s cruelty"},"Runa":{"aff":65,"type":"platonic","relation":"fellow orphan and friend","note":"Close bond formed through shared hardship under Grelod''s cruelty"},"Francois":{"aff":65,"type":"platonic","relation":"fellow orphan and friend","note":"Close bond formed through shared hardship under Grelod''s cruelty"},"Mother":{"aff":85,"type":"familial","relation":"deceased mother","note":"Named him after a lion''s roar, a legacy he clings to","best":"Instilled pride in him through the meaning of his name"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hrodulf', '{"Bjornolfr":{"aff":75,"type":"romantic","relation":"lover","note":"Loving relationship strained by Hrodulf''s obsession with the Dwemer machinery beneath his home","best":"Their life together before the sounds consumed him","worst":"His refusal to leave led to Bjornolfr traveling to Solstheim and being killed by reavers"},"Reavers":{"aff":-85,"type":"enemy","relation":"squatters and murderers","note":"Occupied his home and killed Bjornolfr when he came searching for Hrodulf","worst":"They murdered Bjornolfr"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hroggar', '{"Alva":{"aff":-70,"type":"betrayed","relation":"former thrall","note":"Was enthralled by Alva, who orchestrated his family''s death to claim him","worst":"Learned she murdered his wife and daughter and enslaved him"},"Helgi":{"aff":70,"type":"familial","relation":"daughter","note":"Deceased daughter; showed unnatural detachment under thralldom but deeply regrets it now","worst":"Told someone he didn''t need Helgi anymore while under Alva''s spell"},"Thonnir":{"aff":-10,"type":"suspicious","relation":"coworker","note":"Fellow lumberjack; relationship strained due to Hroggar''s strange behavior after the fire"},"Jorgen":{"aff":-15,"type":"suspicious","relation":"coworker","note":"Views him with suspicion over his quick move to Alva''s house"},"Townspeople of Morthal":{"aff":-20,"type":"suspicious","relation":"neighbors","note":"Regard him with suspicion for moving in with Alva immediately after his family perished"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hroki', '{"Kleppr":{"aff":65,"type":"familial","relation":"father","note":"Indulgent father who provides her spending money","best":"Receives generous spending money from him"},"Frabbi":{"aff":30,"type":"familial","relation":"mother","note":"Mother who constantly argues with her father","worst":"Endless yelling between her parents"},"Hreinn":{"aff":40,"type":"familial","relation":"brother","note":"Brother and co-worker at the inn"},"Hogni Red-Arm":{"aff":-65,"type":"contempt","relation":"meat vendor","note":"Finds him and his wares repulsive","worst":"He waved rotting meat at her and spoke of throwing it"},"Kerah":{"aff":50,"type":"transactional","relation":"jewelry merchant","note":"Friendly merchant who indulges her taste for exotic luxury","best":"Shown a bracelet worn by a Crown Princess of Sentinel"},"Silver-Blood Family":{"aff":55,"type":"admirer","relation":"ruling family","note":"Aspires to curry favor and join their elevated social circle"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hrongar', '{"Balgruuf the Greater":{"aff":75,"type":"familial","relation":"brother and Jarl","note":"Fiercely loyal but frustrated by Balgruuf''s refusal to commit more to the war effort","best":"Standing together in Dragonsreach as trusted kin and council","worst":"Being shouted down as a war-monger when urging aid for the Empire"},"Proventus Avenicci":{"aff":-45,"type":"contempt","relation":"rival advisor","note":"Views him as a cowardly obstructionist who dismisses Nord traditions as nonsense","worst":"Proventus calling sacred Greybeard traditions ''Nord nonsense''"},"Adrianne Avenicci":{"aff":-30,"type":"dismissive","relation":"rival''s daughter","note":"Scorns her influence over her father''s counsel, calling her ''a bloody blacksmith''","worst":"Learning Balgruuf heeds a blacksmith''s advice over a warrior''s"},"The Companions":{"aff":55,"type":"admirer","relation":"respected warrior order","note":"Respects their tradition and trusts them to help defend Whiterun"},"Greybeards":{"aff":70,"type":"awed","relation":"revered ancient order","note":"Holds deep reverence for their wisdom and the sacred traditions they represent","best":"Passionately defending their significance when Proventus dismissed them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hulda', '{"Ysolda":{"aff":65,"type":"professional","relation":"successor","note":"Hulda has chosen Ysolda to buy the Bannered Mare and carry on the business when she retires.","best":"Decided Ysolda was the right person to entrust the inn''s future to."},"Saadia":{"aff":70,"type":"protective","relation":"employee","note":"Treats Saadia with maternal authority, calling her ''dear'' and rousing her for duty.","best":"Shows open affection and care toward Saadia like a surrogate mother."},"Mikael":{"aff":35,"type":"professional","relation":"employee","note":"Tolerates the bard for business but firmly overrides his melancholy song choices.","worst":"Regularly clashes with Mikael over his preference for dreary music that might drive off patrons."},"Jarl Balgruuf":{"aff":55,"type":"professional","relation":"liege","note":"Respects his authority and serves as an informal bounty and rumor broker for the Jarl."},"Farengar":{"aff":25,"type":"suspicious","relation":"court wizard","note":"Acknowledges he is at least a Nord, but still views magic as weak and elven.","worst":"Dismissed magic as being ''for the weak'' and ''for Elves,'' grudgingly accepting Farengar only because he is Nord."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hunroor', '{"Erlendr":{"aff":85,"type":"platonic","relation":"fellow warrior","note":"Close companion who shared the quest for Sovngarde and the curse at Brodir Grove","worst":"Transformed into stone alongside him at Brodir Grove"},"Nikulas":{"aff":85,"type":"platonic","relation":"fellow warrior","note":"Trusted companion who shared the same tragic fate and eventual redemption","worst":"Transformed into stone alongside him at Brodir Grove"},"Grimkell":{"aff":-95,"type":"nemesis","relation":"betrayer","note":"Treacherous wizard who turned Hunroor and his companions into stone pillars","worst":"Being cursed into a stone pillar at Brodir Grove by Grimkell''s betrayal"},"Ulfgar the Unending":{"aff":90,"type":"grateful","relation":"avenger","note":"Slew Grimkell and freed their spirits, allowing them to finally reach Sovngarde","best":"Ulfgar slaying Grimkell and avenging their betrayal"},"Tsun":{"aff":65,"type":"professional","relation":"shield-thane of Shor","note":"Serves alongside Tsun in the Hall of Valor as one of the eternal champions"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('hunter', '{"Fellow Hunters":{"aff":45,"type":"platonic","relation":"loose allies","note":"Shares information about game movements and maintains a loose alliance with other hunters"},"Poachers":{"aff":-65,"type":"enemy","relation":"natural antagonists","note":"Despises those who violate sustainable hunting practices and exploit the wilderness","worst":"Witnessing poachers slaughtering game needlessly"},"Local Jarls":{"aff":-15,"type":"suspicious","relation":"reluctant subjects","note":"Complicated relationship due to hunting regulations and territory restrictions"},"Traveling Merchants":{"aff":25,"type":"transactional","relation":"trading partners","note":"Regular partners for exchanging pelts and meat for supplies"},"Dogs":{"aff":60,"type":"protective","relation":"hunting companions","note":"Keeps loyal hounds as trusted companions in the wilderness"},"Fugitives":{"aff":-80,"type":"enemy","relation":"pursued thieves","note":"Will track down and kill those who steal from them","worst":"Being robbed by a fleeing fugitive"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('husky', '{"Dawnguard":{"aff":85,"type":"protective","relation":"brothers-in-arms","note":"Bred and raised at Fort Dawnguard; shows unwavering loyalty to the cause and genuine affection for handlers","best":"Successful patrol alongside fellow hunters","worst":"Failing to protect a handler from vampire attack"},"Isran":{"aff":70,"type":"servant","relation":"respected leader","note":"Recognized authority figure within the Dawnguard hierarchy"},"Bran":{"aff":65,"type":"platonic","relation":"pack mate","note":"Fellow husky and training partner from the same breeding program"},"Sceolang":{"aff":65,"type":"platonic","relation":"pack mate","note":"Fellow husky and training partner from the same breeding program"},"Vampires":{"aff":-90,"type":"enemy","relation":"natural prey","note":"Bred and trained specifically to detect and combat vampires","worst":"Sensing a vampire threat near Fort Dawnguard"},"Vigilants of Stendarr":{"aff":50,"type":"platonic","relation":"trusted allies","note":"Fellow hunters of the supernatural; share common cause against undead threats"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ice_mage', '{"College of Winterhold":{"aff":-55,"type":"estranged","relation":"former institution","note":"Broke away after rejecting their teachings to pursue forbidden frost knowledge","worst":"Being cast out or leaving in disgrace after pursuing forbidden research"},"Fellow Ice Mages":{"aff":25,"type":"platonic","relation":"loose associates","note":"Share a bond through mutual obsession with frost magic, though isolation limits closeness"},"Necromancers":{"aff":15,"type":"transactional","relation":"occasional allies","note":"Cooperate tentatively in pursuit of forbidden magical knowledge"},"Apprentices":{"aff":60,"type":"mentor","relation":"mentor","note":"Rare and valued students who share their frost obsession, though few survive the training","best":"Finding a student who truly understands the beauty of frost magic"},"Local Settlements":{"aff":-65,"type":"enemy","relation":"perceived threats","note":"View locals as interruptions to be avoided or eliminated"}}')
