INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ice_mage_adept', '{"Warlock Coven Leaders":{"aff":65,"type":"professional","relation":"superiors","note":"Fiercely loyal to coven leadership that provided belonging after exile"},"Lesser Ice Mages":{"aff":35,"type":"mentor","relation":"subordinates","note":"Trains junior mages but views them as inferior","best":"Watching a student finally master Ice Spike","worst":"Enduring clumsy ward failures during drills"},"Fellow Adepts":{"aff":30,"type":"rival","relation":"rivals","note":"Competitive rivalry tempered by grudging professional respect"},"Local Nordic Villages":{"aff":-75,"type":"enemy","relation":"persecutors","note":"Exiled them due to superstitious fear of frost magic","worst":"Being driven from home by frightened neighbors"},"Fire Mage Covens":{"aff":-90,"type":"nemesis","relation":"elemental rivals","note":"Seeks to eliminate rival fire mages from their territory"},"Traveling Merchants":{"aff":15,"type":"transactional","relation":"suppliers","note":"Cautious trade for rare magical supplies and reagents"}}')
ON CONFLICT (npc_name) DO UPDATE
