INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ice_wolf', '{"Pack Members":{"aff":75,"type":"protective","relation":"packmate","note":"Forms strong bonds with small pack for coordinated hunting and survival"},"Common Wolves":{"aff":-20,"type":"contempt","relation":"lesser kin","note":"Generally avoided as inferior, occasionally tolerated"},"Frost Trolls":{"aff":-65,"type":"rival","relation":"territorial rival","note":"Frequently engaged in violent confrontations over territory"},"Dragons":{"aff":-15,"type":"fearful","relation":"apex competitor","note":"Respects their dominance but will defend territory if threatened"},"Humans":{"aff":-50,"type":"contempt","relation":"prey","note":"Views as prey, particularly targeting isolated travelers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('iddra', '{"Kjeld":{"aff":70,"type":"familial","relation":"husband","note":"Runs the inn together; she apologizes for his rough demeanor to guests"},"Kjeld the Younger":{"aff":75,"type":"protective","relation":"son","note":"Protective but firm; tries to teach him responsibility and care for his sister","worst":"He threw Froa into a goat pen and called her stupid"},"Froa":{"aff":78,"type":"protective","relation":"daughter","note":"Quiet child who takes after Iddra''s temperament"},"Roggi Knot-Beard":{"aff":45,"type":"platonic","relation":"regular customer","note":"Values his storytelling but troubled by his endless debt cycle","best":"His stories keep everyone''s spirits up","worst":"His stubborn worrying over his unpaid tab creates a frustrating cycle"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('idesa_sadri', '{"Grimvar Cruel-Sea":{"aff":85,"type":"protective","relation":"ward","note":"Deeply devoted nanny who shields him from negative influences and teaches him humility","best":"Telling Grimvar she is the only friend he needs","worst":"Unable to stop him learning about the Black Sacrament"},"Revyn Sadri":{"aff":75,"type":"familial","relation":"brother","note":"Fellow Dunmer refugee who came to Windhelm together during the exodus from Morrowind"},"Torsten Cruel-Sea":{"aff":55,"type":"professional","relation":"employer","note":"Trusts her with his son''s care and upbringing"},"Hillevi Cruel-Sea":{"aff":55,"type":"professional","relation":"employer","note":"Trusts her with her son''s care and upbringing"},"Aventus Aretino":{"aff":-35,"type":"suspicious","relation":"dangerous influence","note":"Views him as cursed and a threat to Grimvar''s moral development","worst":"Discovering he is performing the Black Sacrament"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('idgrod_the_younger', '{"Idgrod Ravencrone":{"aff":78,"type":"familial","relation":"mother and mentor","note":"Shares the burden of prophetic sight and learns leadership from her mother","best":"Mother''s assurance that she has it within her to succeed as Jarl","worst":"Bearing the headaches and visions her mother insists they must endure without remedy"},"Joric":{"aff":88,"type":"protective","relation":"brother","note":"Fiercely protective of her troubled younger brother who shares their gift but cannot control it","best":"The private bond they share over visions no one else understands","worst":"Watching him struggle to focus and knowing the town sees him as mad"},"Aslfur":{"aff":62,"type":"familial","relation":"father","note":"Provides practical governance guidance though less present in her mystical development"},"Lami":{"aff":72,"type":"platonic","relation":"friend and confidante","note":"Regular visitor to Thaumaturgist''s Hut who offers gentle counsel and herbal wisdom","best":"Lami''s patient understanding when she struggles to articulate her visions"},"Danica Pure-Spring":{"aff":48,"type":"grateful","relation":"healer","note":"Corresponds about Joric''s health and relies on her assessment of his condition"},"Citizens of Morthal":{"aff":42,"type":"neutral","relation":"future subjects","note":"Hopes to earn their full trust despite their wariness of her family''s mystical reputation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('idolaf_battle-born', '{"Olfrid Battle-Born":{"aff":80,"type":"familial","relation":"father","note":"Fiercely loyal to his father and clan patriarch"},"Avulstein Gray-Mane":{"aff":-75,"type":"enemy","relation":"former best friend","note":"Childhood best friends torn apart by the Civil War","best":"Growing up together in Whiterun''s upper district","worst":"Avulstein chose the Stormcloaks and became a traitor"},"Thorald Gray-Mane":{"aff":-40,"type":"enemy","relation":"former friend","note":"Former friends divided by war; Idolaf still investigated his disappearance","best":"Their friendship before the war","worst":"Thorald chose the Stormcloak side and was captured by the Thalmor"},"Fralia Gray-Mane":{"aff":-65,"type":"contempt","relation":"enemy matriarch","note":"Dismissive of her grief and insistence that Thorald lives"},"Imperial Legion":{"aff":80,"type":"fanatical","relation":"unofficial representative","note":"Vocal advocate who arranges weapons shipments and wears their armor proudly"},"Jon Battle-Born":{"aff":50,"type":"familial","relation":"cousin","note":"Family loyalty despite Jon''s secret courtship of a Gray-Mane"},"Adrianne Avenicci":{"aff":25,"type":"transactional","relation":"weapons supplier","note":"Demands she fill Imperial sword orders rather than ask Gray-Mane smiths"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('igmund', '{"Raerek":{"aff":65,"type":"familial","relation":"uncle and steward","note":"Trusted advisor in matters of court and family"},"Faleen":{"aff":55,"type":"protective","relation":"housecarl","note":"Loyal defender of his court and person"},"Thongvor Silver-Blood":{"aff":-45,"type":"rival","relation":"political rival","note":"Seeks to replace him as Jarl of Markarth"},"Forsworn":{"aff":-90,"type":"nemesis","relation":"murderers of his father","note":"Bitter enemies who killed his father and threaten his hold","worst":"Father Hrolfdir murdered by Forsworn"},"Imperial Legion":{"aff":70,"type":"professional","relation":"key allies","note":"Essential to maintaining power and defending the Reach"},"Thalmor":{"aff":-25,"type":"suspicious","relation":"diplomatic pressure","note":"Forced his father to arrest Ulfric under the White-Gold Concordat","worst":"Forced arrest of Ulfric''s militia to preserve the peace"},"Ulfric Stormcloak":{"aff":-35,"type":"rival","relation":"former militia leader","note":"His arrest sparked the Stormcloak rebellion; now threatens the fragile peace","worst":"Used the Markarth Incident to ignite the rebellion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ilas-tei', '{"Phinis Gestor":{"aff":65,"type":"mentor","relation":"mentor","note":"Phinis had particularly high hopes for his promising Conjuration apprentice","best":"Recognized as having great potential in Conjuration magic","worst":"Died from a failed creature control experiment under Phinis''s tutelage"},"College of Winterhold":{"aff":45,"type":"professional","relation":"apprentice member","note":"Member in good standing until his fatal experiment and disappearance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ildari_sarothril', '{"Neloth":{"aff":-95,"type":"nemesis","relation":"former master","note":"Blames him for abandoning her after the heartstone experiment that nearly killed her and left her scarred","worst":"Left for dead after the failed heartstone experiment"},"Tel Mithryn":{"aff":-70,"type":"enemy","relation":"vengeance target","note":"Sends ash spawn attacks and withers the tower to destroy what Neloth built"},"Player":{"aff":-60,"type":"contempt","relation":"Neloth''s pawn","note":"Dismisses the player as a lowlife tool too cowardly to face her himself"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('illdi', '{"Inge Six Fingers":{"aff":45,"type":"mentor","relation":"dean and instructor","note":"Respects her deeply but constantly fears disappointing her","best":"Inge said she''s quite good with the flute","worst":"Dreads whether her original composition will stand up to the classics"},"Giraud Gemane":{"aff":30,"type":"mentor","relation":"teacher","note":"Appreciates his guidance but chafes at the focus on classical tradition over new works","best":"His patient explanation about studying past heroes to understand present ones","worst":"Frustration at always being assigned retellings of old stories"},"Evette San":{"aff":55,"type":"platonic","relation":"friend","note":"Warm acquaintance who looks out for her comfort and shares wine","best":"Offering warming wine and genuine concern for her wellbeing"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('illia', '{"Silvia":{"aff":-25,"type":"estranged","relation":"mother","note":"Killed her to prevent her transformation into a hagraven","worst":"Striking down her own mother during the interrupted ritual"},"Darklight Coven":{"aff":-70,"type":"enemy","relation":"former coven","note":"Turned against the coven and their evil practices","worst":"Years of complicity in their dark rituals"},"Hagravens":{"aff":-80,"type":"fearful","relation":"former masters","note":"Once served them but now opposes their corruption"},"The Dragonborn":{"aff":55,"type":"grateful","relation":"ally","note":"Helped her stop her mother''s transformation and offered a new path","best":"Fought alongside her to end the coven''s evil"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imedhnain', '{"Lisbet":{"aff":40,"type":"professional","relation":"employer","note":"Respectful but tense working relationship; she tolerates Cosnach only for Imedhnain''s sake","best":"She agreed not to fire Cosnach for his sake","worst":"Her harsh criticism of Cosnach and accusations that he covers for him"},"Cosnach":{"aff":65,"type":"familial","relation":"cousin","note":"Protective of his cousin despite his drinking habits; brought him in to help with shipments","best":"Stood up to Lisbet to defend his job","worst":"Repeatedly covering for his drinking and laziness at work"},"Old Arnleif":{"aff":75,"type":"mentor","relation":"mentor","note":"Learned the trade directly from the original owner; holds his memory in high regard","best":"Old Arnleif building each shelf himself and teaching him the trade"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_archer', '{"Imperial Legion":{"aff":85,"type":"professional","relation":"sworn faction","note":"Unwavering loyalty to the Empire and its military order."},"General Tullius":{"aff":65,"type":"professional","relation":"respected commander","note":"Holds deep respect for Tullius as a strategic leader of the Legion in Skyrim."},"Fellow Archers":{"aff":60,"type":"platonic","relation":"brotherhood","note":"Close-knit bond with fellow ranged specialists in the archer corps."},"Stormcloaks":{"aff":-75,"type":"enemy","relation":"rebel insurgents","note":"Views them as dangerous threats to Imperial stability and order.","worst":"Deployed to Skyrim specifically to fight the rebellion they caused."},"Local Imperial Garrisons":{"aff":40,"type":"professional","relation":"garrison comrades","note":"Maintains professional working relationships with fellow Imperial soldiers."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_captain', '{"General Tullius":{"aff":80,"type":"professional","relation":"superior officer","note":"Serves with unwavering loyalty and immediate obedience to his orders","best":"Acknowledged his command without hesitation during the execution"},"Hadvar":{"aff":35,"type":"professional","relation":"subordinate officer","note":"Routinely dismisses his concerns about protocol and procedure","worst":"Dismissed his objection about the unlisted prisoner with ''Forget the list''"},"Ulfric Stormcloak":{"aff":-85,"type":"enemy","relation":"condemned prisoner","note":"Views him as a traitor deserving swift Imperial justice"},"Player":{"aff":-75,"type":"enemy","relation":"condemned prisoner","note":"Ordered execution despite name not appearing on the list","worst":"Sentenced to death without due process or hesitation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_courier', '{"General Tullius":{"aff":65,"type":"professional","relation":"commanding officer","note":"Assigned sensitive communications and answers directly to him","best":"Selected for Skyrim operations by Tullius''s command"},"Imperial Legion":{"aff":75,"type":"protective","relation":"sworn faction","note":"Deeply loyal institution they serve and protect with their life","best":"Earned position through demonstrated reliability"},"Stormcloaks":{"aff":-70,"type":"enemy","relation":"hostile faction","note":"Will be attacked on sight in Stormcloak-held holds","worst":"Hunted and targeted for carrying Imperial documents"},"Fellow Imperial Couriers":{"aff":45,"type":"professional","relation":"colleagues","note":"Share route intelligence and safe passage information","best":"Shared knowledge of safe routes through dangerous territory"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_deserter', '{"Imperial Legion":{"aff":-70,"type":"estranged","relation":"former employer","note":"Abandoned his post after Helgen; now hunted as a deserter","worst":"Deserted his unit, losing all honor and becoming a fugitive"},"Redwater Den Dealers":{"aff":15,"type":"transactional","relation":"skooma suppliers","note":"Depends on them entirely for his Redwater Skooma supply"},"Player Character":{"aff":-25,"type":"fearful","relation":"fellow Helgen survivor","note":"Recognizes them from Helgen and fears exposure as a deserter","worst":"Recognized by someone who could reveal his desertion"},"Fellow Skooma Addicts":{"aff":10,"type":"platonic","relation":"fellow addicts","note":"Loose bonds formed through shared addiction at Redwater Den"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_general', '{"General Tullius":{"aff":65,"type":"professional","relation":"superior officer","note":"Reports directly to Tullius and serves as his tactical advisor"},"Legate Rikke":{"aff":55,"type":"professional","relation":"trusted subordinate","note":"Values her expertise on Nord culture and trusts her judgment"},"Stormcloak Leaders":{"aff":-35,"type":"rival","relation":"military opponents","note":"Regards them as misguided but worthy opponents"},"Aldmeri Dominion":{"aff":-55,"type":"enemy","relation":"wartime enemy","note":"Fought against them in the Great War; privately struggles with the Concordat terms","worst":"The signing of the White-Gold Concordat"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_guard', '{"Imperial Legion":{"aff":85,"type":"servant","relation":"commanding organization","note":"Strong loyalty and operational subordination to Legion command"},"Stormcloaks":{"aff":-85,"type":"enemy","relation":"military enemy","note":"View them as rebels and savages threatening Imperial order","worst":"Stormcloaks killing Torygg and threatening Imperial holds"},"Fellow Guards":{"aff":70,"type":"platonic","relation":"brotherhood in arms","note":"Close bond forged through shared duty and training"},"Local Jarls":{"aff":50,"type":"professional","relation":"superiors in Imperial holds","note":"Professional working relationship maintaining order in Imperial-held territories"},"Stormcloak Sympathizers":{"aff":-60,"type":"suspicious","relation":"suspected dissidents","note":"Constant vigilance required against hidden rebel sympathies"},"Local Citizens":{"aff":40,"type":"protective","relation":"protected populace","note":"Professional duty to protect law-abiding residents of Imperial holds"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_mage', '{"Imperial Legion":{"aff":70,"type":"professional","relation":"military service","note":"Deeply committed to the Legion, valuing the structure and purpose it provides for their magical talents.","best":"Authorized expanded use of battlemages under Tullius''s command","worst":"Helgen garrison annihilated by dragon attack"},"General Tullius":{"aff":55,"type":"professional","relation":"commanding general","note":"Respects Tullius for authorizing expanded battlemage deployment in Skyrim operations."},"Fellow Legion Mages":{"aff":65,"type":"platonic","relation":"brotherhood of spellcasters","note":"Tight-knit group sharing techniques and mutual understanding of the battlemage''s unique role.","best":"Sharing destructive magic techniques refined for combat"},"Helgen Garrison":{"aff":50,"type":"platonic","relation":"fallen comrades","note":"Comrades stationed at the outpost during the dragon attack; survival of most is unknown.","worst":"Watching the garrison fall to the dragon''s assault"},"Synod":{"aff":25,"type":"estranged","relation":"former academy","note":"Left the Synod''s academic path for practical military application, a choice that still carries some tension."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_quartermaster', '{"General Tullius":{"aff":65,"type":"professional","relation":"commanding officer","note":"Direct superior overseeing all Imperial military operations in Skyrim"},"Legate Rikke":{"aff":55,"type":"professional","relation":"coordination partner","note":"Regular liaison for troop supply requirements and logistics"},"Imperial Legion":{"aff":80,"type":"fanatical","relation":"faction","note":"Fifteen years as a legionnaire before reassignment; maintains absolute loyalty despite cynical view of war","best":"Transferred expertise to Skyrim campaign when civil war began"},"Stormcloaks":{"aff":-60,"type":"enemy","relation":"enemy faction","note":"Determined to defeat the rebellion through superior logistics and supply chain management"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('imperial_soldier', '{"General Tullius":{"aff":75,"type":"professional","relation":"supreme commander","note":"Serves with utmost loyalty and respects his leadership of the Legion in Skyrim"},"Legate Rikke":{"aff":65,"type":"professional","relation":"direct superior officer","note":"Follows her orders in field operations with professional trust"},"Imperial Legion":{"aff":80,"type":"protective","relation":"brothers and sisters in arms","note":"Tight bonds forged through shared combat and garrison duty","best":"Holding the line together at a besieged outpost","worst":"Losing a comrade in a Stormcloak ambush"},"Stormcloaks":{"aff":-85,"type":"enemy","relation":"sworn enemies","note":"Faces them regularly in battle across Skyrim","worst":"Bloody skirmishes with rebel fighters in the frozen wilds"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('indara_caerellia', '{"Mathies":{"aff":95,"type":"romantic","relation":"husband","note":"Beloved husband and farming partner who shares her devastating grief over Lavinia''s death.","best":"Building Corpselight Farm together and raising their daughter in peace.","worst":"Standing together at Lavinia''s grave, both shattered by her murder."},"Lavinia":{"aff":100,"type":"familial","relation":"deceased daughter","note":"Her young daughter killed by Sinding, whose memory she honors daily at the cemetery.","best":"Every moment of raising Lavinia before the tragedy.","worst":"Learning of her daughter''s brutal death by werewolf attack."},"Sinding":{"aff":-100,"type":"nemesis","relation":"daughter''s killer","note":"The werewolf who murdered Lavinia and destroyed their family''s happiness.","worst":"Sinding in werewolf form killing her innocent daughter."},"Runil":{"aff":65,"type":"platonic","relation":"priest","note":"Town priest of Arkay who provided last rites for Lavinia and spiritual comfort to the family.","best":"Runil''s blessing and kind words at Lavinia''s funeral."},"Falkreath Community":{"aff":30,"type":"neutral","relation":"neighbors","note":"Generally sympathetic community that respects the family''s loss but offers limited solace."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('indaryn', '{"Maven Black-Briar":{"aff":25,"type":"professional","relation":"employer","note":"Appointed him brewmaster but keeps him as a powerless figurehead, undermining what little authority he has.","best":"Given the brewmaster position despite being an outsider","worst":"Left a note dismissing his authority in front of his own staff"},"Haelga":{"aff":45,"type":"romantic","relation":"lover","note":"Provides comfort and validation away from his professional misery, though the affair is indiscreet.","best":"Found solace in her arms after endless meadery stress"},"Ungrien":{"aff":-15,"type":"professional","relation":"subordinate","note":"Incompetent tasting room worker who spoils kegs and costs Maven gold, making Indaryn look bad.","worst":"Found yet another spoiled keg Ungrien failed to seal properly"},"Romlyn Dreth":{"aff":-30,"type":"suspicious","relation":"suspected thief","note":"Illegally sells Black-Briar Mead behind his back, but Indaryn cannot prove it or stop him.","worst":"Knows Romlyn is smuggling mead but gets defied to his face"},"Keerava":{"aff":30,"type":"platonic","relation":"confidante","note":"Innkeeper who listens to his complaints about staff and his doubts about his own leadership.","best":"Someone who actually listens when he vents about his failures"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('indolent_farmer', '{"Wilhelm":{"aff":15,"type":"transactional","relation":"innkeeper","note":"Regular patron who spends considerable time at Vilemyr Inn avoiding farm duties"},"Dark Brotherhood":{"aff":25,"type":"client","relation":"contracted assassins","note":"Performed the Black Sacrament and pays gold to arrange a murder"},"Unknown Target":{"aff":-90,"type":"nemesis","relation":"target of vengeance","note":"Wronged him severely enough to warrant contracting assassination","worst":"The betrayal or wrong that drove him to the Black Sacrament"},"Local Farmers":{"aff":-15,"type":"dismissive","relation":"neighbors","note":"Strained relationships due to his reputation for laziness"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('inge_six_fingers', '{"Viarmo":{"aff":45,"type":"professional","relation":"headmaster","note":"Respects his authority; he trusts her teaching and praises her hand with students"},"Pantea Ateia":{"aff":35,"type":"professional","relation":"colleague","note":"Fellow instructor whose classes she observes; shared dedication to the college"},"Giraud Gemane":{"aff":30,"type":"professional","relation":"colleague","note":"Dean of History; co-teaches the afternoon library class with him"},"Aia Arria":{"aff":20,"type":"mentor","relation":"student","note":"Demanding of her progress; privately considers her passable","worst":"Aia''s overconfidence in her flawless solo grated on her"},"Illdi":{"aff":25,"type":"mentor","relation":"student","note":"Appreciates her eagerness and original composition efforts"},"Jorn":{"aff":25,"type":"mentor","relation":"student","note":"Stern about upcoming solo but acknowledges his creative drum arrangement"},"Ataf":{"aff":20,"type":"mentor","relation":"student","note":"One of her regular pupils held to her strict standards"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ingjard', '{"Isran":{"aff":65,"type":"professional","relation":"commander","note":"Respects Isran as leader of the Dawnguard and follows his direction"},"Dawnguard":{"aff":75,"type":"professional","relation":"faction","note":"Dedicated member united with comrades against the vampire threat"},"Vampires":{"aff":-85,"type":"enemy","relation":"sworn enemies","note":"Joined Dawnguard specifically to hunt and destroy vampires after hearing rumors of attacks"},"Dragonborn":{"aff":45,"type":"professional","relation":"potential ally","note":"Offers aid after hearing of their accomplishments tracking down vampires"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ingrid', '{"Hert":{"aff":85,"type":"romantic","relation":"husband","note":"Beloved husband who works at the Helgen mill"},"Sonir":{"aff":95,"type":"protective","relation":"son","note":"Fiercely protects her young son and desires Imperial stability for his future"},"Imperial Guards":{"aff":60,"type":"professional","relation":"allies and customers","note":"Regular customers at her food stall and fellow Imperial loyalists"},"Stormcloak Sympathizers":{"aff":-75,"type":"enemy","relation":"political opponents","note":"Openly hostile toward the Stormcloak cause and those who support it","worst":"Shouted ''Death to the Stormcloaks!'' after a rebel execution"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ingun_black-briar', '{"Maven Black-Briar":{"aff":35,"type":"familial","relation":"mother","note":"Ingun craves Maven''s approval but chafes under her constraints on pursuing darker circles","best":"Hopes to make her mother proud through alchemical achievement","worst":"Maven disapproves of her pursuits and won''t let her follow her true ambitions"},"Hemming Black-Briar":{"aff":15,"type":"familial","relation":"brother","note":"Dismissive of his focus on the family''s foolish ventures and political schemes"},"Sibbi Black-Briar":{"aff":5,"type":"estranged","relation":"brother","note":"Imprisoned brother with whom she has little contact"},"Elgrim":{"aff":60,"type":"mentor","relation":"alchemy master","note":"Recognizes her natural talent but she fears his tolerance for her costly mistakes is thin","best":"He calls her a natural with unique talent","worst":"Her errant formulas have cost him a fortune in rare ingredients"},"Hafjorg":{"aff":40,"type":"platonic","relation":"mentor''s wife","note":"Assists in her alchemy training at Elgrim''s Elixirs"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('iona', '{"Jarl of the Rift":{"aff":65,"type":"professional","relation":"liege lord","note":"Appointed Iona as housecarl, trusting her with the Thane''s protection"},"Thane of the Rift":{"aff":75,"type":"protective","relation":"sworn housecarl","note":"Bound by oath to protect and serve with her life","best":"Sworn herself to the Thane''s service upon their appointment"},"Riften Guard":{"aff":45,"type":"platonic","relation":"former comrades","note":"Served alongside them before her elevation to housecarl"},"Maven Black-Briar":{"aff":20,"type":"suspicious","relation":"wary acquaintance","note":"Acknowledges Maven''s influence but remains watchful of her motives"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('irgnir', '{"Karl":{"aff":75,"type":"platonic","relation":"confidant","note":"Her most trusted friend, the one she confides in above all others."},"Fruki":{"aff":65,"type":"platonic","relation":"friend","note":"Close friend despite working at the competing Quicksilver Mine; they share evenings at the Windpeak Inn.","best":"Teasing Fruki about her supposed interest in Leigelf","worst":"Fruki dismissing her nightmare fears as just dreams"},"Beitild":{"aff":20,"type":"professional","relation":"employer","note":"Works under her at Iron-Breaker Mine but finds her bossy and overbearing."},"Erandur":{"aff":40,"type":"grateful","relation":"priest","note":"Initially distrustful and panicked, but ultimately placed faith in him to end the nightmares.","best":"Accepted his reassurance and pledged to trust in Lady Mara","worst":"Feared he was dismissing the nightmares as normal dreams"},"Jarl of Dawnstar":{"aff":-15,"type":"suspicious","relation":"authority figure","note":"Skeptical and distrustful of the Jarl, typical of her working-class distrust of authority."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('irileth', '{"Jarl Balgruuf the Greater":{"aff":90,"type":"protective","relation":"housecarl and former battle-companion","note":"Fought alongside him for years before he became Jarl; she demanded the housecarl role out of deep loyalty forged in battle.","best":"Standing beside Balgruuf through countless battles in their youth","worst":"Any moment she must watch him face danger she cannot shield him from"},"Proventus Avenicci":{"aff":15,"type":"professional","relation":"court colleague","note":"Frequently clashes with him over security matters; she advocates action while he urges caution.","best":"Working together when Balgruuf finally agrees to send troops to Riverwood","worst":"Endless arguments over whether walls and caution are sufficient defense"},"Farengar Secret-Fire":{"aff":30,"type":"professional","relation":"court colleague","note":"Maintains a cordial working relationship as fellow members of the Jarl''s court."},"Whiterun Guards":{"aff":45,"type":"professional","relation":"subordinate soldiers","note":"Commands their respect as their superior officer; expects them to do their duty even against impossible odds.","best":"Briefing the Riverwood detachment with clear, honest orders","worst":"Hearing guards express fear about facing a dragon with inadequate numbers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('irlof', '{"Stig Salt-Plank":{"aff":80,"type":"professional","relation":"captain","note":"Trusted inner circle member with unwavering loyalty, willing to follow Stig even when operations are compromised","best":"Chosen to accompany the captain during sensitive shore operations","worst":"Forced to abandon Skyrim operations and retreat to Hammerfell"},"Alding":{"aff":60,"type":"platonic","relation":"crew mate, drinking companion","note":"Fellow Blood Horker and regular partner in crew festivities"},"Gjuk":{"aff":60,"type":"platonic","relation":"crew mate, drinking companion","note":"Fellow Blood Horker and partner in revelry"},"East Empire Company":{"aff":-40,"type":"enemy","relation":"adversary","note":"Professional adversaries through piracy activities along Skyrim''s northern coast"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('irnskar_ironhand', '{"Bryling":{"aff":65,"type":"protective","relation":"protected charge","note":"Serves as her personal protector with unwavering dedication, though unafraid to disagree with her lenient approaches","best":"Delivered reassuring news that Haafingar remains secure during the civil war","worst":"Clashes with her over her leniency toward debtors and rent discrepancies"},"Octieve San":{"aff":-45,"type":"rival","relation":"debtor","note":"Owes a substantial gambling debt; Irnskar is unyielding about collecting it","worst":"Dismissed him with contempt, saying debts must be paid or his kind will pay"},"Endarie":{"aff":25,"type":"professional","relation":"clothier","note":"Visits Radiant Raiment regularly; handles transactions for Bryling''s clothing","best":"Secured a free gown from Endarie for Bryling as thanks for her lenience on rent"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('isabelle_rolaine', '{"Ranmir":{"aff":90,"type":"romantic","relation":"lover","note":"Left on a desperate heist to solve their shared financial troubles, never returning","best":"Building a life together in Winterhold before money troubles strained them","worst":"Dying in Hob''s Fall Cave before her letter explaining everything could reach him"},"Vex":{"aff":45,"type":"platonic","relation":"old friend","note":"Thieves Guild contact who tipped Isabelle off to the Hob''s Fall Cave job","best":"Gave her a lead that could have solved all her and Ranmir''s problems","worst":"The tip led Isabelle to her death in the cave"},"Thieves Guild":{"aff":15,"type":"transactional","relation":"past associate","note":"Not a full member but had history with them through Vex and occasional thievery"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('isran', '{"Vigilants of Stendarr":{"aff":-20,"type":"estranged","relation":"former order","note":"Left over methods and complacency; vindicated by their destruction but took no joy in it","worst":"Keeper Carcette dismissed his warnings as not worth the expense"},"Celann":{"aff":45,"type":"professional","relation":"old companion","note":"Former Vigilant who rejoined him to rebuild the Dawnguard","best":"Returned to fight alongside him when the Dawnguard was reformed"},"Gunmar":{"aff":35,"type":"professional","relation":"recruited ally","note":"Beast expert and valued Dawnguard member"},"Sorine Jurard":{"aff":30,"type":"professional","relation":"recruited specialist","note":"Dwemer technology expert recruited to the Dawnguard cause"},"Florentius Baenius":{"aff":15,"type":"professional","relation":"recruited healer","note":"Useful to the cause but his religious fervor tries Isran''s patience"},"Vampires":{"aff":-100,"type":"nemesis","relation":"sworn enemies","note":"Dedicated his entire life to eradicating them from Skyrim and beyond"},"Tolan":{"aff":5,"type":"estranged","relation":"surviving Vigilant","note":"Came seeking protection after the Hall fell; Isran showed reluctant sympathy amid bitterness","best":"Admitted sorrow and that he never wanted the Vigilants'' destruction"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('istar_cairn-breaker', '{"Ulfric Stormcloak":{"aff":95,"type":"fanatical","relation":"revered leader","note":"Devotion approaching religious fervor; views him as the only true High King","best":"Earned Ulfric''s trust to command the crucial Haafingar camp"},"Galmar Stone-Fist":{"aff":65,"type":"professional","relation":"superior officer","note":"Respected military commander above him in the chain of command"},"Haafingar Stormcloak Soldiers":{"aff":60,"type":"protective","relation":"troops under command","note":"Maintains strong Nord honor in treating his soldiers with respect"},"Imperial Legion":{"aff":-85,"type":"enemy","relation":"sworn enemy","note":"Viewed as betrayers of Skyrim who sold out to the Thalmor","worst":"Imperials renounced honor by laying down before the Thalmor"},"Thalmor":{"aff":-98,"type":"nemesis","relation":"despised enemy","note":"Represents everything he fights against; wants them eliminated from Skyrim entirely","worst":"The Emperor sold Talos to the damn elves"},"Torygg":{"aff":-70,"type":"contempt","relation":"former High King","note":"Viewed as a traitor who sold out his people for Imperial gold","worst":"Took the Emperor''s gold and sold out his people for a slave master''s peace treaty"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('itinerant_lumberjack', '{"Dark Brotherhood":{"aff":-85,"type":"fearful","relation":"marked target","note":"Someone has placed a contract on his life, making him a recurring potential victim","worst":"Learning he was marked for assassination by the Brotherhood"},"Morthal Guards":{"aff":-30,"type":"suspicious","relation":"local authorities","note":"Deliberately works in areas guards rarely patrol; his behavior draws their suspicion"},"Jorgen and Lami":{"aff":5,"type":"neutral","relation":"neighbors","note":"Works across from their house but maintains minimal contact"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ivarstead_guard', '{"Fellow Guards":{"aff":45,"type":"platonic","relation":"fellow patrol members","note":"Close working bonds forged through shared duty and rotating patrols"},"Wilhelm":{"aff":30,"type":"professional","relation":"local innkeeper","note":"Coordinates on traveler activity and town happenings"},"Klimmek":{"aff":35,"type":"professional","relation":"pilgrim supplier","note":"Respects the old man''s dedication to supplying the Greybeards"},"Gwilin":{"aff":25,"type":"protective","relation":"town resident","note":"Keeps watch over the wood elf during his lumber work outside town"},"Stormcloaks":{"aff":40,"type":"professional","relation":"serving faction","note":"Serves under Stormcloak authority but prioritizes citizen safety over politics"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('j''darr', '{"J''zhar":{"aff":-25,"type":"familial","relation":"brother","note":"J''zhar brought J''darr on the expedition to force his sobriety; now J''darr rages at his corpse, convinced J''zhar hid skooma from him","best":"Brother signed us both up for the expedition to help me quit","worst":"You always try to keep it for yourself, J''zhar!"},"Sulla Trebatius":{"aff":-75,"type":"betrayed","relation":"former expedition leader","note":"Sulla abandoned the Khajiit brothers after the Dwarven automaton attack, leaving them to die in Alftand","worst":"Left us behind when the automatons came"},"Umana":{"aff":-55,"type":"betrayed","relation":"former expedition member","note":"Another expedition member who left the brothers behind after the automaton attack","worst":"They all abandoned us in the ruins"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('j''datharr', '{"Thalmor":{"aff":80,"type":"fanatical","relation":"masters","note":"Serves the Thalmor with ruthless devotion as a covert assassin","best":"Valued and trusted with high-profile eliminations across Tamriel"},"Malborn":{"aff":-85,"type":"enemy","relation":"target","note":"Marked for elimination as a Thalmor-designated traitor","worst":"Dispatched specifically to hunt down and kill Malborn"},"Ri''saad":{"aff":-15,"type":"suspicious","relation":"caravan leader","note":"Ri''saad tolerates his presence but distrusts him","worst":"Viewed with suspicion for standing apart from the caravan"},"Khajiit Caravans":{"aff":-25,"type":"estranged","relation":"estranged kin","note":"Deliberately distances himself from fellow Khajiit despite racial kinship","worst":"Willing to betray fellow Khajiit to serve Thalmor interests"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('j''kier', '{"Hircine":{"aff":95,"type":"fanatical","relation":"deity and master","note":"Serves with unwavering devotion, viewing the Great Hunt as sacred duty","best":"Earned the right to participate in Hircine''s Great Hunt after years of proving himself"},"Sinding":{"aff":-25,"type":"rival","relation":"designated prey","note":"Respects the werewolf''s strength but is bound by sacred duty to bring him down","worst":"Mortally wounded by Sinding''s superior strength in Bloated Man''s Grotto"},"Fellow Hunters":{"aff":65,"type":"platonic","relation":"brothers and sisters in the Hunt","note":"United in purpose and devotion to Hircine''s sacred hunt"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('j''zargo', '{"Tolfdir":{"aff":50,"type":"student","relation":"instructor","note":"Respects Tolfdir despite competitive nature; struggles with ward spells"},"Onmund":{"aff":20,"type":"rival","relation":"fellow apprentice","note":"Views fellow apprentices as competition for magical supremacy","worst":"Onmund dismissed J''zargo''s request to practice wards together"},"Brelyna Maryon":{"aff":20,"type":"rival","relation":"fellow apprentice","note":"Views fellow apprentices as competition for magical supremacy"},"Dragonborn":{"aff":40,"type":"rival","relation":"fellow apprentice","note":"Initially competitive; respects those who prove themselves equals; possibly attempted to eliminate rival via spell experiment","best":"Dragonborn survived experiment and earned J''zargo''s respect as a worthy competitor","worst":"J''zargo''s flame cloak spell experiment nearly killed the Dragonborn"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('j''zhar', '{"J''darr":{"aff":55,"type":"familial","relation":"younger brother","note":"Protective and patient despite J''darr''s skooma addiction; ultimately died due to circumstances involving his brother''s deteriorating mental state","best":"Traveled together seeking adventure and Dwemer knowledge","worst":"J''darr''s skooma withdrawal and delusions contributed to his death"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jala', '{"Evette San":{"aff":55,"type":"platonic","relation":"friend and fellow merchant","note":"Fellow vendor in Solitude''s marketplace who shares the daily grind"},"Addvar":{"aff":40,"type":"professional","relation":"neighboring vendor","note":"Fish merchant and business associate with adjacent stands"},"Jaree-Ra":{"aff":-25,"type":"suspicious","relation":"unwelcome visitor","note":"Argonian who asked her to watch for newcomers; she finds him shady","worst":"He told me to keep an eye out for him, see if any new people arrived in the city"},"Stormcloaks":{"aff":-90,"type":"enemy","relation":"brother''s killers","note":"Deep hatred for murdering her brother in Whiterun","worst":"They did the same to my brother in Whiterun"},"Blackblood Marauders":{"aff":-65,"type":"enemy","relation":"pirates plaguing her shipments","note":"Their raids on coastal shipping disrupted her produce supply and hurt business","best":"The Blackbloods were dispatched and my shipments have been more regular"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('japhet', '{"Followers":{"aff":-65,"type":"betrayed","relation":"former followers","note":"Abandoned Japhet and the fortress project when conditions worsened","worst":"Left him alone on the island to starve"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jaree-ra', '{"Deeja":{"aff":75,"type":"familial","relation":"sister and criminal partner","note":"Trusted partner in smuggling and maritime theft operations","best":"Running successful heists together as self-styled treasure hunters"},"Gulum-Ei":{"aff":55,"type":"familial","relation":"brother","note":"Brother who fences goods through the Thieves Guild","best":"Having a reliable family fence for stolen cargo"},"Blackblood Marauders":{"aff":45,"type":"professional","relation":"criminal allies","note":"Established racket coordinating ship robberies and smuggling","best":"Profitable alliance orchestrating maritime theft"},"Vittoria Vici":{"aff":10,"type":"transactional","relation":"unwitting employer","note":"East Empire Company employer completely unaware of his criminal double life","worst":"Maintaining a deceptive facade to exploit her trust"},"Sorex Vinius":{"aff":-15,"type":"suspicious","relation":"rejected recruit","note":"Repeatedly tried and failed to recruit him for criminal work","worst":"Being dismissed and refused at every attempt"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jarl_elisif_the_fair', '{"Torygg":{"aff":95,"type":"romantic","relation":"late husband","note":"Deeply loved and still mourns his death","best":"Their years together as king and queen of Skyrim","worst":"His death at Ulfric''s hands in the duel"},"Ulfric Stormcloak":{"aff":-90,"type":"nemesis","relation":"husband''s killer","note":"Considers him a traitorous coward who murdered Torygg for power","worst":"When he shouted her husband to death with the Thu''um"},"General Tullius":{"aff":40,"type":"professional","relation":"military ally","note":"Relies on him but harbors misgivings about entrusting him with the war effort"},"Falk Firebeard":{"aff":55,"type":"professional","relation":"steward and advisor","note":"Trusted primary advisor she frequently defers to on matters of governance"},"Erikur":{"aff":20,"type":"professional","relation":"thane","note":"Their relationship is sometimes strained"},"Bryling":{"aff":15,"type":"professional","relation":"thane","note":"Often disagrees with Elisif''s cautious approach"},"Sybille Stentor":{"aff":35,"type":"professional","relation":"court wizard","note":"Magical advisor at the Blue Palace court"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jarl_idgrod_ravencrone', '{"Aslfur":{"aff":85,"type":"romantic","relation":"husband and steward","note":"Devoted partner who manages daily hold operations alongside her"},"Idgrod the Younger":{"aff":75,"type":"familial","relation":"daughter","note":"Shares her gift of foresight and carries on the family''s mystical traditions"},"Joric":{"aff":80,"type":"protective","relation":"son","note":"Struggles with inherited prophetic visions; she seeks to guide him through them"},"Imperial Legion":{"aff":45,"type":"professional","relation":"allies","note":"Cautious alliance in the civil war, though she senses bigger concerns beyond the conflict"},"Citizens of Morthal":{"aff":40,"type":"protective","relation":"constituents","note":"She cares deeply for their wellbeing despite widespread skepticism toward her mystical methods"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jawanan', '{"Fihada":{"aff":80,"type":"mentor","relation":"master fletcher","note":"Left Hammerfell specifically to apprentice under him","best":"Fihada encourages him and shares ranger stories"},"Vivienne Onis":{"aff":-15,"type":"crush","relation":"rejected suitor","note":"Attempted to court her at the Winking Skeever but was brutally rebuffed","worst":"She refused a drink saying not if he were the last man in the Empire"},"Erdi":{"aff":40,"type":"platonic","relation":"friendly acquaintance","note":"Receptive to his attempts at conversation where others are not","best":"She warmly accepted his offer to buy her a drink"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jayri', '{"Dawnguard":{"aff":-20,"type":"suspicious","relation":"denied refuge","note":"Came seeking protection but was denied fortress entry, yet remains nearby relying on their presence","worst":"Left standing outside the fortress gates while vampires terrorize the countryside"},"Fellow Refugees":{"aff":40,"type":"platonic","relation":"fellow displaced","note":"Shares common cause and mutual support with others sheltering in Dayspring Canyon"},"Vampires":{"aff":-90,"type":"fearful","relation":"existential threat","note":"Lost her home and likely loved ones to vampire raids, now lives in constant terror","worst":"Witnessing horrific nighttime raids on nearby villages"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jenassa', '{"Elrindir":{"aff":35,"type":"transactional","relation":"business host","note":"Permits her to operate from the Drunken Huntsman to seek mercenary contracts"},"Player":{"aff":55,"type":"romantic","relation":"patron, potential spouse","note":"Hires her for gold; can earn her loyalty and eventually marry her","best":"Proved a worthy patron deserving of free service and devotion","worst":"Dismissed me to face Skyrim''s dangers alone"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jervar', '{"Skulvar Sable-Hilt":{"aff":-30,"type":"familial","relation":"father","note":"Strained relationship defined by constant criticism and belittlement from Skulvar","best":"Brief shared excitement over spotting a wild mare outside the walls","worst":"Called a half-wit by his own father for dreaming of dragon hunting"},"Lillith Maiden-Loom":{"aff":5,"type":"transactional","relation":"stable owner","note":"Distant business relationship; she owns the stables but Jervar and his father run things"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jesper', '{"Gestur Rockbreaker":{"aff":45,"type":"professional","relation":"supervisor","note":"Treats Gestur with clear respect and deference as his employer at Rockwallow Mine","best":"Gestur checked on him and encouraged him: ''Keep up the hard work. It''ll all pay off.''"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jiub', '{"Cliff Racers":{"aff":-100,"type":"nemesis","relation":"eradicated prey","note":"Dedicated his life to wiping the species from Vvardenfell, earning his sainthood","worst":"Their endless screeching and sneak attacks plagued the skies of Morrowind"},"Dremora":{"aff":-90,"type":"enemy","relation":"killer","note":"Soul trapped and killed him during the siege of Kvatch without giving him a chance to explain who he was","worst":"Burst into his home and cast a soul trap spell from a black crystal"},"Tribunal Temple":{"aff":70,"type":"patron","relation":"canonizer","note":"Recognized his eradication campaign by granting him sainthood","best":"Bestowed the title of Saint Jiub the Eradicator of the Winged Menace"},"Soul Cairn Inhabitants":{"aff":-10,"type":"neutral","relation":"fellow trapped souls","note":"Largely avoids them to focus on his writing uninterrupted"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jod', '{"Jarl Skald":{"aff":40,"type":"professional","relation":"housecarl","note":"Loyal but frequently frustrated by Skald''s aggressive anti-Imperial rhetoric and dismissal of his counsel","best":"Maintained unwavering dedication to his duties as housecarl and guard captain","worst":"Counsel repeatedly ignored, especially warnings about Dawnstar''s vulnerability"},"Citizens of Dawnstar":{"aff":65,"type":"protective","relation":"protector","note":"Prioritizes their safety over ideology, argues against throwing untrained citizens at Legionnaires"},"Imperial Legion":{"aff":30,"type":"admirer","relation":"former enemy","note":"Respects their fighting capability from Great War experience, not eager to fight them again","best":"Witnessed the courage of Imperial Legionnaires firsthand in the Great War"},"Dawnstar Guard Force":{"aff":55,"type":"professional","relation":"commander","note":"Commands and trains the local guards with respected authority"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jofthor', '{"Boti":{"aff":65,"type":"familial","relation":"wife","note":"Partners on the farm but she mediates between his sternness and their daughter''s dreams","best":"Built a life and home together in Ivarstead","worst":"Clashes over how to handle Fastred''s rebelliousness"},"Fastred":{"aff":70,"type":"protective","relation":"daughter","note":"His only child; his overbearing control stems from terror of losing her","best":"She is his entire world and he cannot bear the thought of her gone","worst":"Drove her away by forbidding her choices and refusing to listen"},"Bassianus Axius":{"aff":-55,"type":"contempt","relation":"daughter''s suitor","note":"Views him as spineless and a passing fancy, not a real match","worst":"Called him a bastard when Fastred eloped with him to Riften"},"Klimmek":{"aff":25,"type":"neutral","relation":"daughter''s former interest","note":"Preferred him over Bassianus as a more suitable match for Fastred"},"Wilhelm":{"aff":30,"type":"transactional","relation":"informant","note":"Innkeeper who keeps watch over Fastred''s activities for him","best":"Reports on Fastred''s whereabouts so Jofthor can keep her safe"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jon_battle-born', '{"Olfina Gray-Mane":{"aff":85,"type":"romantic","relation":"secret lover","note":"Forbidden romance across feuding family lines; wishes to escape Whiterun with her","best":"Receiving her letter, dreaming of a life together free from clan feuds","worst":"Fear of discovery that could destroy both their families'' fragile peace"},"Battle-Born Clan":{"aff":55,"type":"familial","relation":"family","note":"Loves his family but rejects their feud mentality and disapproves of their pressure to conform","best":"Growing up amid wealth and privilege in Whiterun''s merchant district","worst":"Parents hesitant to let him attend the Bards College, disapproval of his artistic aspirations"},"Mikael":{"aff":-40,"type":"contempt","relation":"fellow bard","note":"Believes Mikael dishonors Nordic bardic traditions by singing only for gold and wooing women","worst":"Watching Mikael reduce their proud warrior-poet heritage to a cheap hustle for coin and wenches"},"Gray-Mane Clan":{"aff":15,"type":"neutral","relation":"rival clan","note":"Technically rivals by blood feud but personally rejects the conflict and sees its futility"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jonna', '{"Falion":{"aff":85,"type":"protective","relation":"brother","note":"Followed him from Hammerfell to Morthal; defends him against hostile locals","best":"Left Hammerfell together to build a new life","worst":"Townspeople whisper about his magical practices"},"Lurbuk":{"aff":15,"type":"transactional","relation":"tenant","note":"Tolerates his awful singing only because he pays rent","worst":"His serenades would drive away customers if she had any"},"Alva":{"aff":5,"type":"suspicious","relation":"customer","note":"Unsettled by Alva''s strange manner and odd comments about not being hungry"},"Aslfur":{"aff":15,"type":"professional","relation":"steward","note":"Frustrated he won''t intervene to stop townspeople''s harassment of Falion","worst":"He dismissed her plea to help protect Falion"},"Jarl Idgrod Ravencrone":{"aff":25,"type":"professional","relation":"jarl","note":"Acknowledges the Jarl was accepted by the people unlike her brother"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jora', '{"Lortheim":{"aff":45,"type":"romantic","relation":"husband","note":"Fellow priest at the Temple of Talos, though their marriage shows signs of strain"},"Ulfric Stormcloak":{"aff":80,"type":"admirer","relation":"protector","note":"Views him as Skyrim''s greatest hero and the shield safeguarding Talos worship in Windhelm","worst":"His death would mean the end of open Talos worship and Thalmor victory"},"Hillevi Cruel-Sea":{"aff":55,"type":"platonic","relation":"confidante","note":"Regular temple visitor and trusted friend among the faithful"},"Shatter-Shield Family":{"aff":40,"type":"platonic","relation":"parishioners","note":"Frequent visitors seeking solace after the loss of their daughter"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"persecutors","note":"Despised enemies who outlaw Talos worship and hunt the faithful","worst":"The White-Gold Concordat and its devastating impact on Talos worship"},"Niranye":{"aff":35,"type":"platonic","relation":"well-wisher","note":"Expresses concern for Jora''s safety under Thalmor threat and offers help"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jordis_the_sword-maiden', '{"Elisif the Fair":{"aff":75,"type":"protective","relation":"Jarl","note":"Selected by Elisif''s court as housecarl; serves with unwavering loyalty"},"Thane of Solitude":{"aff":70,"type":"protective","relation":"housecarl charge","note":"Sworn to protect and serve with her life upon their appointment as Thane"},"Solitude Guard":{"aff":60,"type":"platonic","relation":"former comrades","note":"Maintains strong ties with brothers and sisters in arms from her service"},"Falk Firebeard":{"aff":40,"type":"professional","relation":"steward","note":"Professional relationship through court duties and appointments"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jorgen', '{"Lami":{"aff":75,"type":"romantic","relation":"wife","note":"Runs the alchemy shop; they stand together during town crises","best":"She stood with him against the vampire threat","worst":"Even she hesitated outside Movarth''s Lair"},"Clan Axe-Bearer":{"aff":50,"type":"familial","relation":"ancestral clan","note":"Carries their sacred duty to protect the Razor''s hilt for eight generations","best":"Honoring the oath by keeping the hilt hidden","worst":"The burden of secrecy with no clan nearby for support"},"Idgrod Ravencrone":{"aff":-45,"type":"suspicious","relation":"Jarl","note":"Distrusts her leadership and dismisses her visions as useless mysticism","worst":"She hides with her visions while the town faces real dangers"},"Falion":{"aff":-35,"type":"suspicious","relation":"town wizard","note":"Openly opposes his presence in Morthal","worst":"The Jarl allows him to practice gods-know-what in their midst"},"Hroggar":{"aff":-25,"type":"suspicious","relation":"townsman","note":"Distrusts him after the suspicious house fire","worst":"The peculiar burning of his house went unaddressed"},"Thonnir":{"aff":20,"type":"platonic","relation":"fellow citizen","note":"Shares concerns about town safety and confronted the Jarl together","best":"Joined the mob to hunt the vampire","worst":"Both retreated outside the lair, leaving the fight to others"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('joric', '{"Idgrod Ravencrone":{"aff":55,"type":"familial","relation":"mother","note":"Shares the inherited gift of sight, but her own episodes sometimes leave her unable to see him at all","best":"She understands what it is to see things others cannot","worst":"Only sometimes, she doesn''t see me at all"},"Aslfur":{"aff":70,"type":"familial","relation":"father","note":"Protective and concerned for his troubled son''s well-being"},"Idgrod the Younger":{"aff":75,"type":"familial","relation":"sister","note":"Shares the family gift and watches over him daily, keeping him company around town","best":"She stays by my side when I wander"},"Gorm":{"aff":-15,"type":"suspicious","relation":"household steward","note":"Doubts Joric''s sanity without saying it outright, which Joric senses acutely","worst":"Gorm thinks I''m mad. He doesn''t say it, but I know he thinks it"},"Falion":{"aff":-25,"type":"suspicious","relation":"mysterious outsider","note":"Joric''s visions reveal something dark about Falion that he cannot fully articulate","worst":"It''s Falion. He did it. I don''t know what it was, but he did it"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jorleif', '{"Ulfric Stormcloak":{"aff":50,"type":"professional","relation":"steward and advisor","note":"Long-serving steward whose counsel Ulfric values despite his lack of military mind","best":"Ulfric listens to his counsel and seems to genuinely value his perspective","worst":"Enduring Ulfric''s harsh temper as a taskmaster"},"Galmar Stone-Fist":{"aff":25,"type":"professional","relation":"fellow advisor","note":"Professional associate serving alongside as co-advisor to Ulfric"},"Brunwulf Free-Winter":{"aff":15,"type":"transactional","relation":"replacement employer","note":"Pragmatically continues steward duties under Imperial rule, relieved the war is over","best":"Glad the rebellion is finished regardless of which side won"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jorn', '{"Viarmo":{"aff":40,"type":"mentor","relation":"drumming instructor","note":"Respects Viarmo but frustrated by his reserved, precision-focused teaching style","worst":"Viarmo''s emphasis on precision over instinct and passion grates on Jorn"},"Illdi":{"aff":65,"type":"crush","relation":"fellow student","note":"Secretly admires Illdi and hopes to win her affections","best":"Dreams of winning Illdi''s heart someday"},"Pantea Ateia":{"aff":50,"type":"mentor","relation":"demanding dean and instructor","note":"Eager to impress Dean Pantea and prove his vocal prowess","best":"Proudly declared his voice strong as a Dragonborn''s to earn her approval"},"Inge Six-Fingers":{"aff":35,"type":"mentor","relation":"performance evaluator","note":"Strict professor who demands early renditions and judges his work rigorously"},"Giraud Gemane":{"aff":50,"type":"mentor","relation":"classical studies professor","note":"Respectful and enthusiastic about completing his war epic assignments"},"Ataf":{"aff":55,"type":"platonic","relation":"fellow student and confidant","note":"Friendly banter and shared observations about college life"},"Lisette":{"aff":25,"type":"admirer","relation":"fellow bard","note":"Finds her attractive but believes she wouldn''t wait for a Legion soldier","worst":"Dismissed the idea of pursuing Lisette since she wouldn''t endure his absence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jouane_manette', '{"Rorik":{"aff":88,"type":"platonic","relation":"closest friend","note":"Saved his life during the Great War; they became as close as kinsmen and settled together in Rorikstead","best":"Keeping Rorik alive after his grievous battlefield wounds"},"Sissel":{"aff":72,"type":"mentor","relation":"secret apprentice","note":"Clandestinely teaches her magic while protecting her from village scrutiny and her father''s neglect","best":"Seeing Sissel''s excitement when learning new spells","worst":"The constant fear that their secret will be discovered"},"Lemkil":{"aff":-35,"type":"contempt","relation":"Sissel''s father","note":"Tense relationship stemming from Lemkil''s mistreatment of Sissel","worst":"Witnessing how poorly Lemkil treats his daughter"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('julienne_lylvieve', '{"Faida":{"aff":75,"type":"mentor","relation":"mentor and employer","note":"Learning the innkeeper''s trade under her guidance at the Four Shields Inn","best":"Faida told her she''d make a fine innkeeper someday"},"Azzada Lylvieve":{"aff":70,"type":"familial","relation":"father","note":"Supports her career aspirations in hospitality"},"Michel Lylvieve":{"aff":70,"type":"familial","relation":"mother","note":"Taught her household management skills"},"Clinton Lylvieve":{"aff":55,"type":"familial","relation":"brother","note":"Shares family duties at the Lylvieve household"},"Tasius Tragus":{"aff":40,"type":"crush","relation":"secret lover","note":"Cut content; marked as his secret lover in Creation Kit, part of a love triangle with Faida"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jurgen_windcaller', '{"Greybeards":{"aff":90,"type":"mentor","relation":"founder and first master","note":"Founded the order and devoted his life to teaching them the Way of the Voice","best":"Established the Greybeards at High Hrothgar"},"Kyne":{"aff":100,"type":"awed","relation":"divine patron","note":"Received divine inspiration about the true purpose of the Voice after seven years of meditation","best":"Divine revelation at the end of seven years of meditation"},"Paarthurnax":{"aff":70,"type":"student","relation":"early teacher of the Thu''um","note":"Likely learned the Thu''um from Paarthurnax before developing the Way of the Voice"},"Last Dragonborn":{"aff":55,"type":"mentor","relation":"spiritual successor","note":"Offered wisdom and guidance in Sovngarde","best":"Shared wisdom about the Way of the Voice in Sovngarde"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('jyrik_gauldurson', '{"Gauldur":{"aff":-85,"type":"betrayed","relation":"father","note":"Murdered him to seize the source of his power, the amulet","best":"Discovered the amulet''s power within his father''s possession","worst":"Orchestrated his father''s assassination for the amulet"},"Sigdis Gauldurson":{"aff":65,"type":"familial","relation":"brother","note":"Co-conspirator in patricide and the reign of terror that followed","best":"Fought together terrorizing Nordic villages"},"Mikrul Gauldurson":{"aff":65,"type":"familial","relation":"brother","note":"Co-conspirator in patricide and the reign of terror that followed","best":"Fought together terrorizing Nordic villages"},"Arch-Mage Geirmund":{"aff":-95,"type":"nemesis","relation":"vanquisher","note":"Defeated and sealed him and his brothers away in undeath","worst":"Sealed away for millennia after crushing defeat"},"Tolfdir":{"aff":-70,"type":"enemy","relation":"adversary","note":"Aided in his defeat at Saarthal in the Fourth Era","worst":"Helped destroy him and claim the amulet fragment"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kai_wet-pommel', '{"Ulfric Stormcloak":{"aff":95,"type":"fanatical","relation":"revered leader","note":"Views Ulfric as the only true High King and the truest of all Nords","best":"Swearing allegiance to Ulfric''s cause and rising through Stormcloak ranks"},"Galmar Stone-Fist":{"aff":70,"type":"professional","relation":"superior officer","note":"Serves under Galmar''s military command with disciplined loyalty"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"despised enemy","note":"Represents everything he fights against; wants to rid Skyrim of them entirely","worst":"The White-Gold Concordat selling out Talos worship to the elves"},"Imperial Legion":{"aff":-80,"type":"enemy","relation":"bitter foe","note":"Views them as cowards who laid down before the Thalmor and sold out Nord gods","worst":"The Empire renouncing honor by submitting to the Thalmor"},"Torygg":{"aff":-70,"type":"contempt","relation":"false king","note":"Believes Ulfric did right killing him for selling out his people"},"Winterhold Guards":{"aff":50,"type":"professional","relation":"subordinates","note":"Commands their loyalty while stationed in Winterhold"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kaie', '{"Madanach":{"aff":88,"type":"professional","relation":"trusted operative","note":"Serves as one of Madanach''s most trusted operatives with absolute loyalty","best":"Successfully delivered equipment for the Cidhna Mine escape"},"Druadach Redoubt Forsworn":{"aff":65,"type":"familial","relation":"tribal kin","note":"Fellow tribal members she lives and fights alongside"},"Markarth Guard":{"aff":-75,"type":"enemy","relation":"occupying adversaries","note":"Actively works against Nordic authorities controlling the Reach","worst":"Slit guards'' throats to procure escape equipment"},"Ulfric Stormcloak":{"aff":-85,"type":"nemesis","relation":"oppressor of her people","note":"His violent suppression of the Reach solidified her dedication to the Forsworn cause"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('karita', '{"Hodor":{"aff":92,"type":"romantic","relation":"husband","note":"Beloved husband and business partner who inspired her to settle in Whiterun"},"Lars":{"aff":95,"type":"familial","relation":"son","note":"Young child she dotes on and seeks to provide a prosperous future for"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('karl', '{"Beitild":{"aff":-35,"type":"contempt","relation":"employer","note":"Openly dismissive of her authority and her petty war against Leigelf","worst":"Threatened with termination if he didn''t shut his mouth and work harder"},"Leigelf":{"aff":5,"type":"neutral","relation":"rival mine owner","note":"Unwillingly drafted into Beitild''s feud against him","worst":"Dragged into a war he never asked for"},"Irgnir":{"aff":25,"type":"platonic","relation":"fellow miner","note":"Shares living quarters and works alongside her at Iron-Breaker Mine"},"Thoring":{"aff":15,"type":"transactional","relation":"innkeeper","note":"Serves him drinks every evening at Windpeak Inn"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('karliah', '{"Gallus Desidenius":{"aff":92,"type":"romantic","relation":"lover","note":"Former lover and Nightingale mentor murdered by Mercer Frey","best":"Being inducted into the Nightingales by Gallus himself","worst":"Discovering Gallus murdered by Mercer''s blade"},"Mercer Frey":{"aff":-97,"type":"nemesis","relation":"betrayer","note":"Murdered Gallus, framed Karliah, and forced her into 25 years of exile","worst":"Finding Gallus dead and realizing Mercer had betrayed them all"},"Dralsi Indoril":{"aff":78,"type":"familial","relation":"mother","note":"Taught Karliah thievery and survival but died before inducting her into the Nightingales","best":"Learning the art of thievery at her mother''s side"},"Nocturnal":{"aff":70,"type":"servant","relation":"Daedric Prince","note":"Serves as a Nightingale sworn to protect the Twilight Sepulcher and the Skeleton Key","best":"Taking the Nightingale oath alongside Gallus"},"Thieves Guild":{"aff":55,"type":"protective","relation":"framed exile","note":"Believed her a murderer for 25 years, yet she protected them from afar and seeks to restore their honor","best":"Working to clear her name and return the Guild to glory","worst":"Being cast out as Gallus''s supposed killer"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('katla', '{"Snilling":{"aff":65,"type":"romantic","relation":"husband","note":"Loving marriage marked by mutual understanding and gentle humor about his physical limitations","best":"Sharing quiet moments together despite the cold","worst":"His inability to help with farm work"},"Knud":{"aff":80,"type":"familial","relation":"son","note":"Beloved son who aspires to become a farmer like her","best":"His desire to follow in her footsteps","worst":"Him stomping on the crops while playing soldier"},"Solitude":{"aff":55,"type":"professional","relation":"food supplier","note":"Takes immense pride in keeping the capital fed and wouldn''t trust any other family to do it"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('katria', '{"Unnamed Apprentice":{"aff":-95,"type":"betrayed","relation":"former apprentice","note":"Stole her life''s research and published it under his own name","worst":"Discovering her apprentice had stolen everything she''d worked for"},"The Last Dragonborn":{"aff":70,"type":"professional","relation":"ally","note":"Helped her complete her life''s work and prove her theories","best":"Watching the Aetherium Forge discovered and her research vindicated"},"Skeptical Scholars":{"aff":-30,"type":"contempt","relation":"academic peers","note":"Dismissed her theories about the Aetherium Forge as fantasy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kayd', '{"Sayma":{"aff":75,"type":"familial","relation":"mother","note":"Helps her at Bits and Pieces after being banned from the forge","best":"Getting to help mother with the shop"},"Beirand":{"aff":90,"type":"familial","relation":"father","note":"Idolizes his strength and boasts about him to strangers","best":"Watching papa work the forge, stronger than anyone","worst":"Tried to use the forge and was never allowed to help papa again"},"Minette Vinius":{"aff":65,"type":"platonic","relation":"playmate","note":"Close friend and constant companion running around Solitude","best":"Playing tag together through the streets"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('keeper_carcette', '{"Vigilant Tolan":{"aff":65,"type":"professional","relation":"trusted subordinate","note":"Veteran Vigilant who served faithfully under her command and later reported her death at the Hall"},"Brother Adalvald":{"aff":55,"type":"professional","relation":"respected scholar","note":"Valued order member whose scholarly work supported the Vigilant mission"},"Volkihar Vampires":{"aff":-95,"type":"nemesis","relation":"destroyers of the Hall","note":"Launched the devastating attack that destroyed the Hall of the Vigilant and killed her","worst":"The vampire assault that annihilated the Hall and her order in Skyrim"},"Daedra Worshippers":{"aff":-85,"type":"enemy","relation":"sworn foes","note":"Targets for conversion or justice under Stendarr''s will"},"College of Winterhold":{"aff":15,"type":"suspicious","relation":"cautious diplomatic contact","note":"Maintains wary relations regarding magical matters while distrusting their practices"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('keerava', '{"Talen-Jei":{"aff":85,"type":"romantic","relation":"partner","note":"Shares her dream of leaving Riften; she softens only around him","best":"dreaming together of a life beyond Riften","worst":"his family in Morrowind used as leverage against her"},"Thieves Guild":{"aff":-65,"type":"enemy","relation":"extortion target","note":"Refuses to pay their debts until physically beaten or Talen-Jei''s family is threatened","worst":"beaten into submission to pay Brynjolf''s debt"},"Brynjolf":{"aff":-60,"type":"enemy","relation":"extortionist","note":"Repeatedly refused his debt demands; calls him a buffoon to his face"},"Maven Black-Briar":{"aff":-25,"type":"suspicious","relation":"mead supplier","note":"Resents her rising prices and unchecked influence over Riften''s economy","worst":"forced to consider watering down mead just to survive her price hikes"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kematu', '{"Alik''r Warriors":{"aff":75,"type":"professional","relation":"loyal subordinates","note":"They follow his command without question; he values discipline and avoids unnecessary bloodshed on their behalf"},"Noble Houses of Taneth":{"aff":60,"type":"patron","relation":"employers","note":"Entrusted him with the crucial mission to capture Saadia and restore justice to Taneth"},"Saadia":{"aff":-75,"type":"nemesis","relation":"fugitive target","note":"Alleged traitor who sold Taneth to the Aldmeri Dominion; he pursues her to bring her back alive for trial","best":"Finally cornering her at Whiterun Stables after a long hunt","worst":"Her betrayal cost Taneth its stand against the Dominion"},"Whiterun Guards":{"aff":-20,"type":"suspicious","relation":"foreign law enforcement","note":"Tense standoff over Alik''r presence in the hold; neither side trusts the other"},"Aldmeri Dominion":{"aff":-90,"type":"enemy","relation":"wartime adversary","note":"Fought against them during Hammerfell''s resistance; their influence drove Saadia''s betrayal"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kerah', '{"Endon":{"aff":85,"type":"romantic","relation":"husband","note":"Beloved partner in both marriage and business; he crafts the silver jewelry she sells.","best":"Building their reputation and livelihood together in Markarth","worst":"Watching the diverse clientele that once made their trade flourish disappear from the city"},"Adara":{"aff":80,"type":"familial","relation":"daughter","note":"Proud of her daughter''s progress learning the family silversmithing trade.","best":"Seeing Adara craft rings on her own for the first time"},"Cade":{"aff":75,"type":"familial","relation":"son","note":"Son fighting with the Stormcloaks; she hopes for his safe return.","worst":"Cade leaving to fight in the civil war"},"Calcelmo":{"aff":45,"type":"professional","relation":"client","note":"Regular customer and respected scholar she speaks highly of to visitors.","best":"Completing a ring delivery to him, earning his trust"},"Silver-Blood Family":{"aff":-35,"type":"rival","relation":"oppressive trade rivals","note":"Resents their stranglehold on Markarth''s silver trade and rising taxation.","worst":"Their tightening control over the city''s commerce and daily life"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kesh_the_clean', '{"Peryite":{"aff":95,"type":"fanatical","relation":"devoted priest","note":"Survived plague interpreted as Peryite''s favor and has served as the Daedric Prince''s shrine keeper ever since","best":"awakened to Peryite''s purpose after surviving the plague that killed his caravan companions","worst":"endures years of isolation at the remote shrine with no place to sleep"},"Orchendor":{"aff":-40,"type":"contempt","relation":"apostate overseer","note":"Knew Orchendor as a shepherd of the Afflicted who betrayed Peryite''s trust","worst":"learned Orchendor abandoned his duty as Overseer and led the Afflicted astray"},"Afflicted":{"aff":55,"type":"protective","relation":"spiritual charges","note":"Views the diseased followers as blessed by Peryite and meant to spread his Blessing"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kharag_gro-shurkul', '{"Hjorunn":{"aff":30,"type":"professional","relation":"employer","note":"Strained but functional working relationship with grudging mutual respect beneath the bickering","best":"Treats me like an equal out here at work","worst":"Drinks up our profits while I work twice as hard"},"Solitude Guards":{"aff":-15,"type":"suspicious","relation":"local authorities","note":"Cautious distance and unwarranted suspicion toward an Orc who keeps to himself"},"Stronghold Family":{"aff":15,"type":"estranged","relation":"clan","note":"Left seeking independence from rigid tribal hierarchy but ties not entirely severed"},"Local Wood Elves":{"aff":5,"type":"transactional","relation":"trading partners","note":"Occasional lumber-related trade"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kharjo', '{"Ahkari":{"aff":75,"type":"indebted","relation":"employer and savior","note":"Freed Kharjo from a Cyrodiil prison; he now serves loyally to repay this life debt","best":"Was freed from imprisonment","worst":"Bound by debt of honor, unable to return to Elsweyr until repaid"},"Mother":{"aff":70,"type":"familial","relation":"mother","note":"Gave him the Moon Amulet as a cub; his only memory of home in cold Skyrim","best":"Gifted the treasured Moon Amulet"},"Zaynabi":{"aff":35,"type":"platonic","relation":"fellow caravan member","note":"Trusted traveling companion sharing the dangerous roads between Dawnstar and Riften"},"Bandits":{"aff":-70,"type":"enemy","relation":"persistent threat","note":"Harass the caravans and stole his precious Moon Amulet","worst":"Stole the Moon Amulet given by his mother"},"Player":{"aff":60,"type":"grateful","relation":"follower","note":"Offers loyal service after the Moon Amulet is recovered from bandits","best":"Recovered the Moon Amulet from bandits"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('khayla', '{"Ri''saad":{"aff":65,"type":"professional","relation":"employer","note":"Respected caravan leader she serves as protector and trainer","best":"Proved herself capable and earned his trust as caravan guardian"},"Khajiit Traders":{"aff":60,"type":"protective","relation":"caravan family","note":"Close-knit bond built on mutual trust and shared survival","best":"Years of keeping the caravan safe through Skyrim''s harsh roads"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kibell', '{"Forsworn":{"aff":-55,"type":"fearful","relation":"regional threat","note":"Witnessed their uprising firsthand; describes them as wild as wolves and strategically avoids them on the roads","worst":"Witnessed the Forsworn Uprising and the violence it brought to Markarth"},"Calcelmo":{"aff":40,"type":"admirer","relation":"respected scholar","note":"Directs travelers to Calcelmo for Dwemer knowledge and speaks respectfully of his expertise","best":"Recommends Calcelmo''s books and scholarship to curious travelers"},"Ulfric Stormcloak":{"aff":-10,"type":"neutral","relation":"historical figure he witnessed","note":"Witnessed Ulfric''s violent reclamation of Markarth; maintains diplomatic neutrality despite the memory","worst":"Watched Ulfric shout people to death during the retaking of Markarth"},"Markarth Guards":{"aff":25,"type":"professional","relation":"cooperative partners","note":"Works with guards to ensure traveler safety on the dangerous Reach roads"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('king_olaf_one-eye', '{"Svaknir":{"aff":-95,"type":"nemesis","relation":"detractor","note":"Bard who exposed Olaf''s treachery through scathing poetry","worst":"His verses destroyed my heroic legacy and branded me a deceiver"},"Numinex":{"aff":-70,"type":"rival","relation":"captive dragon","note":"Dragon Olaf claimed to defeat in single combat but likely trapped through treachery","best":"I caged the beast and claimed the High King''s throne through its capture"},"Bards College":{"aff":-65,"type":"enemy","relation":"legacy underminers","note":"Preserves Svaknir''s unflattering verses that contradict Olaf''s heroic narrative","worst":"They keep alive the lies that stain my reign across generations"},"Citizens of Whiterun":{"aff":15,"type":"estranged","relation":"former subjects","note":"Ruled as Jarl before claiming the High King''s throne, though his legacy remains deeply contested","best":"They bowed before me as their Jarl and I delivered them from the dragon"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kjar', '{"Former Crew Member":{"aff":-85,"type":"betrayed","relation":"traitor, former sailor","note":"Abandoned ship duties to lead a gang of thieves rather than haul cargo","worst":"Chose thievery over honest work and loyalty"},"Windhelm Dock Workers":{"aff":35,"type":"professional","relation":"dock colleagues","note":"Respect his authority as captain on the docks"},"Local Merchants":{"aff":25,"type":"transactional","relation":"business contacts","note":"Cargo hauling trade connections"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kjeld', '{"Iddra":{"aff":15,"type":"estranged","relation":"wife","note":"Marriage strained by his infidelity and dismissive attitude","best":"Acknowledged she is a good woman","worst":"Publicly stated every man needs variety and that she wastes time"},"Kjeld the Younger":{"aff":40,"type":"familial","relation":"son","note":"Tries to raise him with Nordic toughness but also calls him a brat","best":"Showed interest when his son wanted to visit the mine","worst":"Dismissed him as sitting around wasting time"},"Roggi Knot-Beard":{"aff":35,"type":"platonic","relation":"fellow miner, reluctant confidant","note":"Work companion who disapproves of his infidelity but stays friendly","best":"Shared mead and mine work camaraderie","worst":"Roggi called out that his talk wouldn''t make his wife happy"},"Dravynea":{"aff":20,"type":"professional","relation":"mine consultant","note":"Relies on her expertise but bristles at her authority over mine safety","worst":"Nearly lost eyebrows ignoring her wards about the steam channels"},"Kynesgrove Residents":{"aff":-35,"type":"contempt","relation":"townspeople he leads","note":"Views them as lazy rabble and superstitious milk-drinkers","worst":"Openly dismissed them as afraid of a dead dragon tomb"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kjeld_the_younger', '{"Kjeld":{"aff":50,"type":"familial","relation":"father","note":"Admires his father''s authority and craves his approval, but struggles to prove himself worthy","best":"Father agreeing to take him hunting","worst":"Feeling overshadowed by his father''s success and status"},"Iddra":{"aff":25,"type":"familial","relation":"mother","note":"Constantly clashes over chores and domestic responsibilities he considers beneath him","best":"Mother''s concern keeping him from danger near soldiers","worst":"Being forced to do kitchen work instead of hunting"},"Froa":{"aff":-15,"type":"familial","relation":"sister","note":"Bullies and torments her, calling her stupid and throwing her into a goat pen","worst":"Told her vampires would pay him for her until she cried"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kleppr', '{"Frabbi":{"aff":-65,"type":"estranged","relation":"wife","note":"Notoriously antagonistic marriage defined by constant public bickering and mutual insults","best":"Not a day goes by I don''t ask that question myself, my dear","worst":"You''re an idiot, Kleppr. Why did I ever marry you?"},"Hroki":{"aff":60,"type":"protective","relation":"daughter","note":"Tries to shield her from the worst of his marital strife"},"Hreinn":{"aff":65,"type":"protective","relation":"son","note":"Earnestly encourages him to become a better man and innkeeper than himself","best":"You listen to me, and you''ll be a great man one day"},"Silver-Blood Family":{"aff":20,"type":"professional","relation":"employers","note":"Owns the inn he manages, adding pressure to maintain high standards"},"Ogmund":{"aff":35,"type":"professional","relation":"skald","note":"Friendly working relationship with the inn''s resident bard"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('klimmek', '{"Bassianus Axius":{"aff":-25,"type":"rival","relation":"housemate and business partner","note":"Strained cohabitation; Klimmek resents his laziness and unprofitable schemes","worst":"Reminded Bassianus that he showed up on his doorstep looking for a job and a place to live"},"Fastred":{"aff":55,"type":"crush","relation":"unrequited love interest","note":"Convinced himself he isn''t good enough for her; she is involved with Bassianus","best":"Dared to hope she might stay in Ivarstead with him"},"Lynly Star-Sung":{"aff":25,"type":"crush","relation":"would-be suitor","note":"Awkwardly attempts to court her at the inn; consistently and gently rejected","worst":"Fumbled asking her out and was told she wasn''t ready for that sort of thing"},"Greybeards":{"aff":60,"type":"servant","relation":"supplier","note":"Has delivered supplies up the 7,000 Steps for years despite never seeing them","best":"Faithfully maintained the supply runs that keep the monastery provisioned","worst":"The climb has become too dangerous for his aging body"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('knight-paladin_gelebor', '{"Arch-Curate Vyrthur":{"aff":-35,"type":"estranged","relation":"brother","note":"Once close kin, now corrupted beyond recognition; Gelebor must oppose him despite their bond","best":"Standing together as faithful servants of Auri-El in the Chantry","worst":"Watching his brother become something unknowable after the Betrayed corrupted him"},"The Betrayed":{"aff":-25,"type":"pitying","relation":"fallen kin","note":"Sees the Falmer as corrupted victims rather than mere monsters, yet they destroyed everything he loved","worst":"Their invasion that slaughtered his fellow priests and paladins"},"Auri-El":{"aff":95,"type":"servant","relation":"devoted guardian","note":"Has maintained faithful service for millennia as Knight-Paladin of the Chantry","best":"A lifetime of sacred duty and divine purpose sustaining him through solitude"},"Fellow Paladins":{"aff":80,"type":"familial","relation":"fallen brothers-in-arms","note":"His fellow guardians who perished defending the Chantry against the Betrayed","worst":"Their slaughter during the Falmer invasion he was powerless to prevent"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('knjakr', '{"Ratway Dwellers":{"aff":-15,"type":"suspicious","relation":"neighbors","note":"Keeps cautious distance to avoid drawing attention to his cannibalism"},"Thieves Guild":{"aff":-10,"type":"suspicious","relation":"wary cohabitants","note":"Mutual avoidance due to his disturbing reputation"},"Namira Cultists":{"aff":20,"type":"fanatical","relation":"kindred devotees","note":"Possible loose association through shared cannibalistic practices, though he operates independently"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('knud', '{"Katla":{"aff":85,"type":"familial","relation":"mother","note":"Patient and encouraging mother who nurtures his farming skills","best":"Mama said I could help with the goats!"},"Snilling":{"aff":70,"type":"familial","relation":"father","note":"Loving but doubts his academic abilities, accepts his farming future","worst":"Father says I don''t have the knack for reading"},"Solitude Guards":{"aff":45,"type":"admirer","relation":"role models","note":"Fascinated by soldiers, pretends to be one during play","best":"I''m gonna go play soldier with a tree!"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('knud_repeated', '{"Katla":{"aff":80,"type":"familial","relation":"mother","note":"Guides him in learning farm management and daily duties","best":"Learning farm work alongside her each day"},"Snilling":{"aff":70,"type":"familial","relation":"father","note":"Oversees his development but worries about his reading aptitude","worst":"Father''s disappointment over his struggles with reading"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kodlak_whitemane', '{"Vilkas":{"aff":85,"type":"familial","relation":"surrogate son","note":"Helped raise him and counsels him on resisting the call of the blood","best":"Watching him grow into a strong warrior of the Circle","worst":"Seeing him struggle with the burden of lycanthropy"},"Farkas":{"aff":85,"type":"familial","relation":"surrogate son","note":"Helped raise and train him alongside his twin brother Vilkas"},"Askar":{"aff":75,"type":"grateful","relation":"predecessor and recruiter","note":"Previous Harbinger who found him in Hammerfell and brought him home to the Companions","best":"Being found and brought to Jorrvaskr, realizing he was coming home"},"Silver Hand":{"aff":-80,"type":"enemy","relation":"sworn enemy","note":"Hunt werewolves and threaten the Circle''s members"},"Hircine":{"aff":-70,"type":"fearful","relation":"Daedric Lord claiming werewolf souls","note":"Fears his soul will be trapped in Hircine''s Hunting Grounds instead of reaching Sovngarde","worst":"The curse of lycanthropy binding his soul to Hircine upon death"},"The Companions":{"aff":90,"type":"protective","relation":"Harbinger and spiritual leader","note":"Dedicated to maintaining their honor and guiding them on a noble path","best":"Holding the Companions to the right path of honor and glory","worst":"Fearing the difference between noble warriors and assassins is thin as a blade''s edge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kodrir', '{"Aeri":{"aff":-35,"type":"professional","relation":"employer","note":"Openly resents Aeri for not appreciating his work at the mill"},"Leifur":{"aff":-45,"type":"rival","relation":"coworker","note":"Hostile exchanges and mutual mockery between coworkers","worst":"Leifur mocked his faithlessness and implied he could do Kodrir''s job better"},"Ennodius Papius":{"aff":-75,"type":"enemy","relation":"former coworker","note":"Deeply despised the Imperial and was glad when he left or was killed","best":"Glad that damn Imperial was gone"},"The Divines":{"aff":-50,"type":"contempt","relation":"deities","note":"Curses the Divines and shows disdain for religion, particularly Lady Mara"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kolbjorn_guard', '{"Ralis Sedarys":{"aff":35,"type":"professional","relation":"employer","note":"Assigned to protect the expedition leader at Kolbjorn Barrow","worst":"Died under his watch during the ill-fated excavation"},"Captain Veleth":{"aff":55,"type":"professional","relation":"commanding officer","note":"Direct superior in the Redoran Guard who assigned him to Kolbjorn"},"Fellow Kolbjorn Guards":{"aff":60,"type":"platonic","relation":"comrades","note":"Close-knit unit sharing dangerous duties at the barrow","worst":"All perished together in the ruins"},"Second Councilor Arano":{"aff":20,"type":"professional","relation":"authorizing official","note":"Authority figure who approved the guard detail for the excavation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('korir', '{"Thaena":{"aff":80,"type":"romantic","relation":"wife","note":"Staunch supporter who shares his hatred of the College"},"Assur":{"aff":85,"type":"protective","relation":"son and heir","note":"Takes him to The Frozen Hearth in the evenings","best":"Spending evenings at The Frozen Hearth together"},"College of Winterhold":{"aff":-95,"type":"nemesis","relation":"blamed institution","note":"Holds them responsible for the Great Collapse that destroyed Winterhold","worst":"Watching most of his city plunge into the sea while the College remained untouched"},"Kraldar":{"aff":-60,"type":"rival","relation":"political replacement","note":"Replaces him as Jarl if the Imperials take control","worst":"Being exiled from his own hold while Kraldar takes his seat"},"Stormcloaks":{"aff":55,"type":"professional","relation":"allied faction","note":"Supports them to preserve Winterhold''s sovereignty and Nordic traditions"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kornalus', '{"College of Winterhold":{"aff":-70,"type":"estranged","relation":"former institution","note":"Expelled for forbidden experiments; obsessively seeks to prove them wrong","worst":"Expelled in disgrace for unethical experimentation on living subjects"},"Frostbite Spiders":{"aff":40,"type":"obsessed","relation":"experimental subjects","note":"Twisted companions and sole focus of his research, though they resist control","best":"Breakthrough moments when specimens respond to his commands","worst":"Constant escapes and failures to maintain control over his creations"},"Local Bandits":{"aff":-45,"type":"enemy","relation":"hostile intruders","note":"Violent territorial disputes with groups attempting to claim Harmugstahl"},"Traveling Merchants":{"aff":5,"type":"suspicious","relation":"potential test subjects","note":"Valued only as supply sources and unwitting experimental material"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kottir_red-shoal', '{"Ulfric Stormcloak":{"aff":92,"type":"fanatical","relation":"supreme commander","note":"Kottir''s unwavering devotion to Ulfric defines his entire purpose and worldview","best":"Appointed commander of the Reach campaign by Ulfric himself"},"Galmar Stone-Fist":{"aff":65,"type":"professional","relation":"superior officer","note":"Strategic coordinator within the Stormcloak military hierarchy"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"hated enemy","note":"Passionate hatred for the Thalmor and their Justiciars drives his every action","worst":"The White-Gold Concordat selling out Talos worship to the elves"},"Imperial Legion":{"aff":-80,"type":"enemy","relation":"military opposition","note":"Views the Legion as cowards who sold out Skyrim for a slave master''s peace treaty","worst":"Torygg and the Jarls taking the Emperor''s gold to betray their own people"},"Reachmen":{"aff":-40,"type":"suspicious","relation":"territorial rivals","note":"Tense relationship due to ongoing territorial conflicts in the Reach"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('krag', '{"College of Winterhold":{"aff":-45,"type":"estranged","relation":"former student","note":"Left due to restrictions on magical research; deliberately severed ties","worst":"Condemned the College''s restrictions as stifling true magical advancement"},"Markarth Guards":{"aff":-30,"type":"suspicious","relation":"avoided authority","note":"Avoided all contact, viewed them as a threat to his unsanctioned research"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kraldar', '{"Thonjolf":{"aff":65,"type":"servant","relation":"loyal servant","note":"Faithful attendant who remains with Kraldar even in exile","best":"Stayed by my side when we were driven from Winterhold"},"Savos Aren":{"aff":55,"type":"admirer","relation":"claimed friend","note":"Claims close friendship but Aren never mentions him and repeatedly ignores dinner invitations","worst":"Yet another meal invitation left unanswered"},"Korir":{"aff":-45,"type":"rival","relation":"political rival","note":"Opposing views on the College; predecessor as Jarl who blames mages for the Collapse"},"College of Winterhold":{"aff":75,"type":"patron","relation":"defender and ally","note":"Uniquely sympathetic toward the College among Winterhold Nords; defends them against Collapse accusations"},"Imperial Legion":{"aff":55,"type":"professional","relation":"political patron","note":"Loyal Imperial supporter installed as Jarl under their governance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('krev_the_skinner', '{"Silver Hand":{"aff":70,"type":"professional","relation":"followers","note":"Commands fierce loyalty as the legendary hunter who united scattered werewolf hunters."},"The Companions":{"aff":-95,"type":"nemesis","relation":"sworn enemies","note":"Obsessively dedicated to destroying the Circle and eradicating their lycanthropy.","worst":"The Companions'' Circle represents everything Krev has sworn to annihilate."},"Vigilants of Stendarr":{"aff":25,"type":"professional","relation":"occasional allies","note":"Cooperates against shared supernatural threats despite differing methods."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kust', '{"Runil":{"aff":45,"type":"professional","relation":"superior","note":"Respects but maintains professional distance from the senior priest of Arkay","worst":"Learned Runil was once Thalmor"},"Lod":{"aff":-40,"type":"suspicious","relation":"rival","note":"Suspicious of the blacksmith''s activities near the graveyard","worst":"Discovered Lod stole a book from a grave"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kuvar', '{"Bujold":{"aff":45,"type":"romantic","relation":"wife","note":"Married but deeply strained by shame over their defeat and frustration with her hesitant leadership","best":"Shared a prosperous life together at Thirsk before the Rieklings came","worst":"Told her he couldn''t even look at her in his shame and told her to run to the wilds"},"Thirsk Warriors":{"aff":55,"type":"platonic","relation":"fellow warriors","note":"Pushes them to toughen up and reclaim their warrior tradition, frustrated by their complacency","worst":"Ashamed of how soft they grew before the Riekling attack"},"Rieklings":{"aff":-85,"type":"enemy","relation":"invaders","note":"Despises them for driving his people from their home in overwhelming numbers","worst":"Waves of Rieklings overwhelmed Thirsk and forced them into shameful exile"},"Skaal":{"aff":15,"type":"dismissive","relation":"distant cultural kin","note":"Considers their nature-worship nonsense despite shared Nord heritage"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kvenel_the_tongue', '{"Ancient Dragons":{"aff":55,"type":"mentor","relation":"teachers of the Voice","note":"Studied under the Dragons before their downfall, learning the Way of the Voice"},"Ancient Nord Warriors":{"aff":70,"type":"protective","relation":"his warriors and followers","note":"Led them as warrior-chief in successful campaigns during the Merethic Era"},"Modern Adventurers":{"aff":-80,"type":"enemy","relation":"trespassers","note":"Views all who enter Volunruud as desecrators to be destroyed without mercy"},"Other Draugr":{"aff":30,"type":"professional","relation":"subordinate guardians","note":"Commands the lesser draugr within his burial chamber in undeath"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('kyr', '{"Ra''jirr":{"aff":-95,"type":"nemesis","relation":"killer","note":"Treacherous recruit who stole the sword and mortally wounded Kyr in an ambush","worst":"Ambushed and fatally wounded him while trying to return the sword to the Pale Lady"},"Eisa Blackthorn":{"aff":-45,"type":"betrayed","relation":"suspected co-conspirator","note":"Initially trusted recruit placed in charge of excavation, later assumed she helped Ra''jirr steal the sword","best":"Trusted her enough to put her in charge of the dig that uncovered the underground forest","worst":"Put a bounty on her, believing she conspired with Ra''jirr"},"The Pale Lady":{"aff":-40,"type":"fearful","relation":"cursed entity","note":"Mysterious being connected to the sword whose influence drove Ra''jirr to betrayal and murder","worst":"Her influence over Ra''jirr led directly to Kyr''s death"},"Bandit Group":{"aff":50,"type":"professional","relation":"his band","note":"Led a struggling group of raiders through lean times, maintaining cohesion until the sword incident"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('laelette_the_vampire', '{"Thonnir":{"aff":-35,"type":"estranged","relation":"abandoned husband","note":"Left him when turned by Alva; he believes she joined the Stormcloaks","worst":"Abandoned her family without explanation under Alva''s control"},"Virkmund":{"aff":-25,"type":"estranged","relation":"abandoned son","note":"Disconnected from former maternal bond; he still waits hopefully for her return"},"Alva":{"aff":30,"type":"servant","relation":"vampire master","note":"Turned and bound as handmaiden; serves Alva''s commands despite occasional disobedience","worst":"Failed to follow orders properly by burning Hroggar''s family alive instead of making it look accidental"},"Helgi":{"aff":55,"type":"obsessed","relation":"obsessive fixation","note":"Tried to turn the child into a vampire companion; now haunts her grave in delusion","best":"Believes Helgi could be brought back as a companion to end her loneliness","worst":"Arrived too late to turn Helgi before the girl died from her injuries"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('laila_law-giver', '{"Anuriel":{"aff":45,"type":"professional","relation":"steward","note":"Trusts her steward completely, unaware she is a Thieves Guild infiltrator manipulating her decisions"},"Maven Black-Briar":{"aff":15,"type":"suspicious","relation":"rival power","note":"Senses something amiss but cannot fathom the true extent of Maven''s control over Riften"},"Harrald":{"aff":75,"type":"familial","relation":"elder son","note":"Shares her political views and Stormcloak sympathies"},"Saerlund":{"aff":60,"type":"familial","relation":"younger son","note":"Believes he is mentally ill for opposing the Stormcloaks and seeks a cure","worst":"His anti-Stormcloak views convinced her he had lost his mind"},"Unmid Snow-Shod":{"aff":55,"type":"professional","relation":"housecarl","note":"Loyal protector and staunch Stormcloak supporter whose zeal exceeds her own"},"Wylandriah":{"aff":35,"type":"professional","relation":"court wizard","note":"Tasked with finding a cure for Saerlund''s supposed illness"},"Ulfric Stormcloak":{"aff":25,"type":"suspicious","relation":"rebellion leader","note":"Publicly supports his cause but privately doubts his motivations are selfless","best":"His cause aligns with her desire for Skyrim''s independence","worst":"Privately believes he uses the holy war as leverage to pursue the throne"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lami', '{"Jorgen":{"aff":85,"type":"romantic","relation":"husband","note":"Loving couple who share dedication to Morthal and work hard together","best":"Standing side by side in defense of Morthal against the vampire threat","worst":"Shared fear upon arriving at Movarth''s Lair realizing the danger"},"Idgrod the Younger":{"aff":65,"type":"protective","relation":"caring friend","note":"Shows patient concern for her wellbeing and offers remedies for her headaches","best":"Gently offering to brew something to help with her vision-related headaches","worst":"Idgrod refusing help because her mother says the headaches are a burden to bear"},"Temple Healer":{"aff":70,"type":"mentor","relation":"former mentor","note":"Taught Lami the basics of alchemy during a pilgrimage through Morthal","best":"Sharing the Song of the Alchemists book that inspired her life''s work","worst":"Departing before Lami could finish learning, leaving her to teach herself"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('larina', '{"Pantea Ateia":{"aff":-55,"type":"betrayed","relation":"instructor","note":"Stole and sold Pantea''s Flute to necromancers out of desperation for tuition money","worst":"Stealing her mentor''s prized flute and selling it to fund her studies"},"Necromancers of Hob''s Fall Cave":{"aff":-95,"type":"fearful","relation":"captors","note":"Sold them the flute, then was captured and murdered by them for a dark ritual","worst":"Being caged and prepared for sacrificial ritual"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lars_battle-born', '{"Braith":{"aff":-85,"type":"enemy","relation":"bully","note":"Daily tormentor who extorts money and threatens violence","worst":"Being forced to promise ten septims to avoid a bloody nose"},"Bergritte Battle-Born":{"aff":75,"type":"protective","relation":"grandmother","note":"Offers understanding and shelter when others dismiss him","best":"Grandmother''s comfort and willingness to confront Braith''s mother on his behalf"},"Idolaf Battle-Born":{"aff":25,"type":"familial","relation":"father","note":"Father who shows open disappointment in Lars''s lack of warrior spirit","worst":"Father catching him sneaking out and punishing him"},"Alfhild Battle-Born":{"aff":45,"type":"familial","relation":"mother","note":"Mother who struggles to understand her sensitive son"},"Mila Valentia":{"aff":50,"type":"platonic","relation":"former playmate","note":"Used to adventure together before Lars stopped sneaking out","best":"Climbing onto Dragonsreach''s roof to look for birds'' eggs"},"Olava the Feeble":{"aff":55,"type":"platonic","relation":"friend","note":"Visits her regularly; she encouraged him to stand up for himself","best":"Olava''s reassurance that things will get better"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lash_gra-dushnikh', '{"Gharol":{"aff":-40,"type":"estranged","relation":"mother","note":"Left Dushnikh Yal on bad terms; interprets Gharol''s sword gift as a final rejection","worst":"Receiving her mother''s sword as a message meaning ''don''t come back''"},"Ragnar":{"aff":45,"type":"crush","relation":"fellow miner","note":"Respects his strength and work ethic; invites him hunting; flirts awkwardly","best":"Telling Ragnar he has strong arms and would make a good Orc"},"Belchimac":{"aff":-55,"type":"enemy","relation":"coworker","note":"Bigoted Reachman who insults Orcs; she threatens him with violence","worst":"Belchimac calling Orcs unclean and too stupid for politics"},"Ainethach":{"aff":35,"type":"professional","relation":"employer","note":"Mine owner who treats her fairly despite local prejudices against Orcs","best":"Ainethach standing against Silver-Blood mercenaries to reclaim the mine"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_adventus_caesennius', '{"General Tullius":{"aff":75,"type":"professional","relation":"commanding officer","note":"One of Tullius''s most trusted commanders; serves him with unwavering loyalty"},"Legate Rikke":{"aff":55,"type":"professional","relation":"fellow legate","note":"Colleague in the Imperial command structure; defers to her on local recruiting"},"Captain Aldis":{"aff":40,"type":"professional","relation":"fellow officer","note":"Fellow Imperial officer stationed at Castle Dour; Aldis handles recruit training"},"Ulfric Stormcloak":{"aff":-85,"type":"enemy","relation":"rebel leader","note":"Views him as a dangerous rebel who must be brought to justice","worst":"Ulfric''s so-called rebellion threatens the Empire''s lawful order"},"Imperial Legion":{"aff":90,"type":"fanatical","relation":"sworn brotherhood","note":"Devoted his life to the Legion; values its discipline and cause above all else"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_constantius_tituleius', '{"General Tullius":{"aff":70,"type":"professional","relation":"superior officer","note":"Respects and loyally serves his commanding general in Skyrim"},"Legate Rikke":{"aff":45,"type":"professional","relation":"fellow legate","note":"Colleague in the Imperial command structure who handles local recruiting"},"Skald the Elder":{"aff":-55,"type":"rival","relation":"opposing jarl","note":"Antagonistic relationship with the Stormcloak-aligned Jarl of Dawnstar"},"Stormcloak Forces":{"aff":-75,"type":"enemy","relation":"rebel opposition","note":"Views them as misguided rebels threatening Imperial order"},"Imperial Soldiers":{"aff":35,"type":"professional","relation":"subordinates","note":"Commands with professional but firm leadership in The Pale"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_emmanuel_admand', '{"General Tullius":{"aff":70,"type":"professional","relation":"commanding officer","note":"Respects and loyally serves his direct superior in the Skyrim campaign","best":"Received his Legate commission through Tullius''s endorsement"},"Jarl Igmund":{"aff":45,"type":"professional","relation":"political ally","note":"Coordinates with the Jarl to maintain Imperial control of Markarth and the Reach"},"Forsworn":{"aff":-80,"type":"enemy","relation":"insurgents","note":"Views them as dangerous threats to stability and order in the Reach","worst":"Forsworn attacks undermine Imperial authority he is sworn to uphold"},"Stormcloaks":{"aff":-65,"type":"enemy","relation":"rebels","note":"Considers them misguided rebels whose defeat is necessary to restore peace","worst":"Rebellion fragments the Empire he bled to preserve"},"Aldmeri Dominion":{"aff":-85,"type":"enemy","relation":"wartime enemy","note":"Fought against them in the Great War; the White-Gold Concordat fuels his determination to prevent further Imperial decline","worst":"Witnessed the Empire''s capitulation after the Great War"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_fasendil', '{"Thalmor":{"aff":-90,"type":"nemesis","relation":"sworn adversary","note":"Witnessed the Night of Green Fire massacre of Altmer refugees in Sentinel and requested his Skyrim posting specifically to monitor them.","worst":"Seeing the refugee quarter in Sentinel reduced to a smoking ruin with everyone dead at Thalmor hands"},"General Tullius":{"aff":55,"type":"professional","relation":"commanding officer","note":"Direct superior in the Imperial Legion whose strategic direction Fasendil follows dutifully."},"Altmer Refugees":{"aff":65,"type":"protective","relation":"persecuted kin","note":"Shares their heritage and was searching for refugee relatives in Sentinel when the Thalmor attacked.","worst":"Arriving too late to save refugee relatives during the Night of Green Fire"},"Imperial Soldiers":{"aff":50,"type":"professional","relation":"subordinates","note":"Commands the Legion forces in the Rift and feels a solemn duty to protect both them and the citizens under Imperial rule."},"Maven Black-Briar":{"aff":20,"type":"transactional","relation":"strategic ally","note":"Forms a pragmatic alliance if the Legion takes control of Riften."},"Laila Law-Giver":{"aff":-15,"type":"rival","relation":"opposing authority","note":"Stormcloak-aligned Jarl whose authority in the Rift conflicts with Imperial operations."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_hrollod', '{"General Tullius":{"aff":75,"type":"professional","relation":"superior officer","note":"Commands unwavering loyalty as Hrollod''s supreme commander in Skyrim"},"Legate Rikke":{"aff":65,"type":"professional","relation":"fellow legate","note":"Fellow Nord serving the Empire; directs recruits to her specifically"},"Ulfric Stormcloak":{"aff":-85,"type":"enemy","relation":"military target","note":"Views him as leader of a illegitimate rebellion disrupting proper order","worst":"Dismisses Ulfric''s uprising as a so-called rebellion"},"Brunwulf Free-Winter":{"aff":45,"type":"professional","relation":"future Jarl","note":"Expected to serve in his court at the Palace of the Kings after Imperial victory"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_quentin_cipius', '{"Jarl Balgruuf the Greater":{"aff":35,"type":"professional","relation":"military ally","note":"Tense alliance during the siege of Whiterun, with cultural friction but mutual respect for efficiency","best":"Balgruuf acknowledged Imperial efficiency when Cipius had water brigades already organized","worst":"Balgruuf''s ''Imperial milk drinkers'' slight prompted a pointed offer to withdraw Legion support"},"General Tullius":{"aff":55,"type":"professional","relation":"commanding general","note":"Direct superior in the Imperial Legion chain of command"},"Irileth":{"aff":30,"type":"professional","relation":"fellow advisor","note":"Collaborative relationship as co-advisors to Jarl Balgruuf on military defense"},"Imperial Soldiers":{"aff":45,"type":"protective","relation":"commanding officer","note":"Strict disciplinarian who nonetheless takes practical measures for troop survival","best":"Proactively organized water brigades to protect soldiers fighting in flames"},"Ulfric Stormcloak":{"aff":-85,"type":"enemy","relation":"rebel leader","note":"Views the Stormcloak rebellion as treason against the Empire"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_rikke', '{"General Tullius":{"aff":80,"type":"professional","relation":"commanding officer","note":"Serves as his second-in-command and chief military advisor with deep respect despite cultural differences","best":"Fighting alongside him through the campaign to reunify Skyrim"},"Ulfric Stormcloak":{"aff":-75,"type":"enemy","relation":"former comrade turned rebel leader","note":"Once fought beside him in the Great War but now sees him as a self-serving egomaniac endangering Skyrim","best":"Fighting side by side against the Aldmeri Dominion in the Great War","worst":"Leading the rebellion that fractures Skyrim and weakens the Empire"},"Galmar Stone-Fist":{"aff":-65,"type":"enemy","relation":"former companion turned adversary","note":"Once-close companion from the Great War now serving as Ulfric''s right hand","best":"Shared hardships and camaraderie during the Great War","worst":"Facing him across the battlefield as enemies in the civil war"},"Imperial Legion":{"aff":90,"type":"protective","relation":"lifelong institution","note":"Born to Legion parents and wholly devoted to the Empire as Skyrim''s best hope against the Dominion"},"Thalmor":{"aff":-90,"type":"enemy","relation":"existential threat","note":"Refuses to even discuss them, seeing the Dominion as the true enemy that only a united Empire can defeat","worst":"The Great War and the suffering inflicted on Skyrim and the Empire"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_sevan_telendas', '{"General Tullius":{"aff":70,"type":"professional","relation":"commanding officer","note":"Direct superior overseeing all Legion operations in Skyrim; Sevan''s loyalty is unwavering"},"Legate Rikke":{"aff":55,"type":"professional","relation":"fellow legate","note":"Colleague in the Imperial command structure who handles local recruiting"},"Korir":{"aff":-50,"type":"rival","relation":"opposing jarl","note":"Stormcloak-aligned Jarl of Winterhold; adversarial relationship across enemy lines"},"Ulfric Stormcloak":{"aff":-75,"type":"enemy","relation":"rebel leader","note":"Views Ulfric''s rebellion as a lawless disruption of Imperial order","worst":"Started the so-called rebellion that plunged Skyrim into chaos"},"Imperial Legion":{"aff":85,"type":"fanatical","relation":"sworn faction","note":"Devoted his life to Legion service after leaving Morrowind; determined to prove Dunmer loyalty through merit"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_skulnar', '{"General Tullius":{"aff":65,"type":"professional","relation":"commanding officer","note":"Loyal subordinate who directs recruits to Solitude and trusts Tullius''s leadership"},"Legate Rikke":{"aff":60,"type":"professional","relation":"fellow legate","note":"Fellow Nord in Imperial service who shares similar views on Skyrim''s place in the Empire"},"Siddgeir":{"aff":40,"type":"professional","relation":"jarl","note":"Maintains professional relationship as military governor of Falkreath under his rule"},"Ulfric Stormcloak":{"aff":-75,"type":"enemy","relation":"rebel leader","note":"Views his rebellion as a dangerous disruption to peace and stability","worst":"His so-called rebellion has plunged Skyrim into chaos"},"Imperial Soldiers":{"aff":55,"type":"protective","relation":"subordinates","note":"Commands their respect through fair leadership and experience"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('legate_taurinus_duilis', '{"General Tullius":{"aff":70,"type":"professional","relation":"commanding officer","note":"Serves under Tullius with unwavering loyalty and directs recruits to Solitude"},"Legate Rikke":{"aff":55,"type":"professional","relation":"fellow legate","note":"Colleague in the Imperial command structure who handles local recruiting"},"Jarl Idgrod Ravencrone":{"aff":35,"type":"professional","relation":"local jarl","note":"Must coordinate with her as the civil authority in Hjaalmarch while operating from Highmoon Hall"},"Stormcloak Forces":{"aff":-75,"type":"enemy","relation":"rebel insurgents","note":"Views them as Ulfric''s so-called rebellion that the Legion will put down","worst":"Empire stretched thin fighting this uprising across Skyrim"},"Imperial Soldiers":{"aff":60,"type":"protective","relation":"troops under command","note":"Responsible for their welfare and effectiveness in maintaining Imperial control in Hjaalmarch"}}')
