INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('leifnarr', '{"Grosta":{"aff":85,"type":"romantic","relation":"wife","note":"Devoted husband who left Grosta to run Heartwood Mill alone after his death","best":"Building their life together at Heartwood Mill","worst":"Never returning from Broken Helm Hollow"}}')
