INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('leifur', '{"Aeri":{"aff":50,"type":"professional","relation":"employer","note":"Aeri trusts him as a reliable worker and he respects her authority at the mill"},"Kodrir":{"aff":20,"type":"platonic","relation":"co-worker","note":"Shares living quarters and work with the grumpy Kodrir, using dry wit to deflect his complaints","worst":"Endured yet another of Kodrir''s tirades about how unappreciated he is"},"Ennodius Papius":{"aff":15,"type":"curious","relation":"former co-worker","note":"Occasionally wonders what happened to the Imperial who vanished from the mill"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('leigelf', '{"Beitild":{"aff":-35,"type":"estranged","relation":"estranged wife","note":"Bitter feud over competing mines masks unresolved feelings and wounded pride","best":"Private journal admissions that he still misses her","worst":"She kicked him out and began driving him out of business"},"Lond":{"aff":40,"type":"professional","relation":"employee","note":"Values Lond''s loyalty and genuine concern for his wellbeing","best":"Thank you for sticking by me"},"Skald the Elder":{"aff":15,"type":"professional","relation":"Jarl","note":"Acknowledges his authority but views him as immature","worst":"Never lost that brat''s attitude"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lemkil', '{"Sissel":{"aff":-80,"type":"estranged","relation":"daughter","note":"Blames her for his wife''s death, beats and neglects her","worst":"Cursed her as a waste of her mother''s life"},"Britte":{"aff":-70,"type":"estranged","relation":"daughter","note":"Dismisses her as lazy and stupid despite her adopting his cruel nature","worst":"Called her lazier and more stupid as she grew"},"Jouane Manette":{"aff":-25,"type":"suspicious","relation":"neighbor","note":"Rejects her charity offers with hostility","worst":"Snapped that he doesn''t need Breton charity"},"Rorik":{"aff":-10,"type":"transactional","relation":"landlord","note":"Tense interactions due to Rorik''s concern for his daughters"},"Mralki":{"aff":-35,"type":"contempt","relation":"innkeeper","note":"Resents Mralki''s criticism of his parenting"},"Erik":{"aff":-45,"type":"contempt","relation":"villager","note":"Dismissed as a witless oaf for questioning his cruelty","worst":"Told to keep his nose out of Lemkil''s business"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('leonara_arius', '{"Addvild":{"aff":95,"type":"romantic","relation":"husband","note":"Deeply devoted to him; he answered the first door she knocked on in Skyrim","best":"He promised never to let anything happen to us","worst":"Fears losing him like she lost her family"},"Snow-Shod Family":{"aff":45,"type":"professional","relation":"employers","note":"Employ her and Addvild; Addvild trusts they would defend the farm if needed"},"Cyrodiil Family":{"aff":-50,"type":"estranged","relation":"estranged family","note":"Left Cyrodiil after a significant falling out with them","worst":"The falling out that drove me from my homeland"},"Local Guards":{"aff":15,"type":"fearful","relation":"protectors","note":"Doubts their limited numbers can reach the farm in time during danger"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('leontius_salvius', '{"Eydis":{"aff":65,"type":"mentor","relation":"employer and mentor","note":"Trained him in innkeeping; he honors her memory after her death","best":"Trusted to take over the inn she built","worst":"Lost his mentor when she passed away"},"Skuli":{"aff":45,"type":"professional","relation":"co-worker","note":"Manages daily operations under Skuli''s ownership after Eydis''s death"},"Rogatus":{"aff":55,"type":"familial","relation":"father","note":"Left the farm but maintains ties through letters","best":"Father still writes to him","worst":"Disappointed by leaving the family trade"},"Vigdis":{"aff":50,"type":"familial","relation":"mother","note":"Runs Salvius Farm with Rogatus; Leontius chose a different path"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lieutenant_salvarus', '{"Emperor Titus Mede II":{"aff":85,"type":"protective","relation":"protectee","note":"Primary protection responsibility and object of unwavering loyalty"},"Commander Maro":{"aff":65,"type":"professional","relation":"superior officer","note":"Respected superior in the Penitus Oculatus chain of command"},"Ship''s Captain":{"aff":55,"type":"professional","relation":"colleague","note":"Coordinates security measures aboard The Katariah"},"Penitus Oculatus":{"aff":75,"type":"professional","relation":"faction","note":"Loyal member dedicated to upholding the organization''s honor and reputation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lillith_maiden-loom', '{"Skulvar Sable-Hilt":{"aff":60,"type":"professional","relation":"employee","note":"Trusted stable master who handles daily operations and horse sales","best":"Four more geldings sold during wartimeâ€”good news they could share"},"Fralia Gray-Mane":{"aff":72,"type":"platonic","relation":"close friend","note":"Marketplace confidante with warm, familiar rapport","best":"Fralia arranging a custom silver locket from Eorlund, no questions asked"},"Gray-Mane Family":{"aff":40,"type":"transactional","relation":"long-standing customers","note":"Profitable relationship maintained alongside Battle-Born ties without taking sides"},"Battle-Born Family":{"aff":35,"type":"transactional","relation":"business associates","note":"Regular horse buyers; kept at careful arm''s length politically"},"Maven Black-Briar":{"aff":25,"type":"admirer","relation":"claimed friend","note":"Lillith boasts of their friendship, but Maven never acknowledges her","best":"Name-dropping Maven as proof she knows her place in the world"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('linwe', '{"Niranye":{"aff":35,"type":"transactional","relation":"fence","note":"Business partner who fences goods for the Summerset Shadows, though they rarely meet in person"},"Summerset Shadows":{"aff":55,"type":"professional","relation":"criminal organization","note":"Founded and leads the guild, orchestrating their grave-robbing operations from Uttering Hills Cave"},"Thieves Guild":{"aff":-50,"type":"rival","relation":"rival guild","note":"Competing criminal organization whose territory and methods conflict with the Shadows","worst":"The Guild sends agents to eliminate the Summerset Shadows as a threat"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lisbet', '{"Gunnar":{"aff":75,"type":"romantic","relation":"late husband","note":"Inherited the store from him after his death; misses him dearly","best":"Calling him her stubborn oaf with clear affection","worst":"Losing him to a Forsworn attack five years ago"},"Imedhnain":{"aff":20,"type":"professional","relation":"employee","note":"Frequently scolds him but keeps his cousin employed for his sake","best":"Agreeing not to fire Cosnach for Imedhnain''s sake","worst":"Constant criticism of his performance and covering for Cosnach"},"Cosnach":{"aff":-30,"type":"contempt","relation":"employee","note":"Views him as a lazy drunk who contributes nothing to the business","worst":"Discovering him drinking at the Silver-Blood Inn on her coin again"},"Ogmund":{"aff":40,"type":"admirer","relation":"favorite skald","note":"Loves hearing him sing at the inn and considers him a true skald"},"Eola":{"aff":55,"type":"fanatical","relation":"fellow cultist","note":"Participates in cannibalistic feasts with her; praises her preparations","best":"Complimenting Eola''s feast as lovely, as always"},"Forsworn":{"aff":-90,"type":"enemy","relation":"husband''s killers","note":"Lost her husband and countless shipments to their attacks","worst":"The Forsworn attack that killed Gunnar"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lisette', '{"Corpulus Vinius":{"aff":65,"type":"professional","relation":"employer","note":"She speaks warmly of his inn and recommends staying there."},"Vivienne Onis":{"aff":50,"type":"platonic","relation":"college associate","note":"They discuss music and events, though Lisette is candidly critical of fellow bards'' performances."},"Una":{"aff":25,"type":"platonic","relation":"acquaintance","note":"Una dismisses bardic arts as frivolity; Lisette finds her hard to please."},"Viarmo":{"aff":55,"type":"mentor","relation":"former instructor","note":"She respects him enough to direct prospective students his way."}}')
