INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lleril_morvayn', '{"Adril Arano":{"aff":85,"type":"platonic","relation":"trusted second councilor and friend","note":"Relies on Adril for governance and shares daily meals with his family","best":"Adril''s unwavering counsel and loyalty through Raven Rock''s darkest times"},"Cindiri Arano":{"aff":65,"type":"platonic","relation":"close associate","note":"Wife of Adril and part of his trusted inner circle at Morvayn Manor"},"House Hlaalu":{"aff":-85,"type":"enemy","relation":"would-be assassins","note":"Plotted his assassination","worst":"Survived their assassination plot revealed during the Served Cold affair"},"Brara Morvayn":{"aff":80,"type":"familial","relation":"mother and predecessor","note":"Inherited her position as Councilor in 4E 65 and continues her legacy of leadership"},"Citizens of Raven Rock":{"aff":70,"type":"protective","relation":"his people","note":"Depletes his personal treasury to cover settlement expenses and keep them alive"}}')
