INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('llewellyn_the_nightingale', '{"The Dragonborn":{"aff":60,"type":"patron","relation":"employer and patron","note":"Serves with loyalty and respect; forgiving of dismissal","best":"Hired to serve as resident bard at Lakeview Manor","worst":"Dismissed from service, though bore no grudge"},"Lakeview Manor Steward":{"aff":45,"type":"professional","relation":"fellow servant","note":"Professional colleague in household service; arranged his hiring"},"Bards College":{"aff":65,"type":"student","relation":"alma mater","note":"Excelled in training; maintains connections with fellow graduates","best":"Graduated with distinction in performance and storytelling"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lob', '{"Garakh":{"aff":75,"type":"mentor","relation":"metalworking mentor","note":"Lob learns from Garakh daily and aspires to take her place as stronghold craftsman","best":"Learning new metalworking techniques each day"},"Chief Yamarz":{"aff":50,"type":"professional","relation":"tribal chief","note":"Serves with loyalty despite the curse plaguing the stronghold under Yamarz''s leadership","worst":"Enduring Malacath''s curse while serving a struggling chief"},"Malacath":{"aff":85,"type":"fanatical","relation":"revered deity","note":"Strives to please Malacath through craftsmanship and faithful devotion","best":"Hope that his weapons will someday earn Malacath''s approval","worst":"The curse placed upon Largashbur testing the stronghold''s worth"},"Mother":{"aff":75,"type":"familial","relation":"mother","note":"Aspires to craft weapons as strong as his mother''s to honor her skill and legacy","best":"Remembering her craftsmanship as the standard he strives toward"}}')
