SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lod', '{"Dengeir of Stuhn":{"aff":90,"type":"platonic","relation":"former personal guard and close friend","note":"Risked his life multiple times protecting Dengeir; places loyalty to him above all else, even the Empire","best":"Served faithfully as personal guard for years and earned a bond deeper than oath or coin","worst":"Political shifts forced distance between them as Dengeir lost the jarlship"},"Siddgeir":{"aff":20,"type":"professional","relation":"current Jarl","note":"Maintains a professional but distant relationship with the Jarl who replaced Dengeir","worst":"Siddgeir''s rise displaced Dengeir, forcing Lod into a delicate political position"},"Imperial Legion":{"aff":35,"type":"transactional","relation":"weapons supplier","note":"Supplies arms and armor out of duty despite weariness with the war''s bloodshed","best":"Steady work and purpose for his forge","worst":"Each weapon forged contributes to a war he wishes would end"},"Tekla":{"aff":30,"type":"crush","relation":"unrequited interest","note":"Flirts with her but is consistently rebuffed","worst":"She coldly rejects his advances"},"Mathies":{"aff":45,"type":"platonic","relation":"grieving neighbor","note":"Expressed sympathy for the tragedy that befell Mathies''s family","best":"Offered genuine condolences for his loss"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lodi', '{"Pantea Ateia":{"aff":65,"type":"mentor","relation":"instructor","note":"Trained Lodi at the Bards College and helped develop his flute mastery"},"Vittoria Vici":{"aff":20,"type":"client","relation":"employer","note":"Hired Lodi to perform at her wedding in Solitude","worst":"Witnessed her assassination during the reception"},"Bards College":{"aff":45,"type":"professional","relation":"alumnus","note":"Graduate and affiliated performer providing music at high-society events"}}')
