INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('logrolf_the_willful', '{"Boethiah":{"aff":95,"type":"fanatical","relation":"patron deity","note":"Devoted priest who spreads her influence through defiance of her enemies","best":"Successfully performed Boethiah''s sacraments at Molag Bal''s own altar","worst":"Was broken under torture and forced to forsake her"},"Molag Bal":{"aff":-100,"type":"nemesis","relation":"archenemy","note":"Deliberately provokes by defiling his shrine with rival rituals","best":"Mocked and defied the King of Corruption to his face","worst":"Tortured into submission and forced to pledge his soul"},"Vigilants of Stendarr":{"aff":-70,"type":"enemy","relation":"hunters","note":"Seek to kill him for his Daedric worship","worst":"Their investigation alerted Molag Bal to his provocations"}}')
