INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lokil', '{"Lord Harkon":{"aff":75,"type":"servant","relation":"master","note":"Serves with absolute loyalty and seeks to prove his worth through the Dimhollow mission","best":"Entrusted with leading the Dimhollow expedition"},"Vingalmo":{"aff":-45,"type":"rival","relation":"court rival","note":"Political rival in Harkon''s court whom he intends to supersede"},"Orthjolf":{"aff":-45,"type":"rival","relation":"court rival","note":"Political rival in Harkon''s court whom he intends to supersede"},"Vigilant Adalvald":{"aff":-80,"type":"contempt","relation":"interrogation victim","note":"Interrogated and killed at Dimhollow Crypt after deeming him useless","worst":"The Vigilant knew nothing and could not aid the mission"}}')
