INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lokir', '{"Imperial Legion":{"aff":-80,"type":"enemy","relation":"captors and executioners","note":"Captured alongside Stormcloaks and executed despite desperate pleas of innocence","worst":"Shot down by Imperial archers while fleeing the execution block"},"Ulfric Stormcloak":{"aff":-50,"type":"contempt","relation":"blamed rebel leader","note":"Blames Ulfric''s rebellion for the Imperial crackdown that led to his capture","worst":"Cursed the Stormcloaks for ruining his chance to escape to Hammerfell"},"Ralof":{"aff":-5,"type":"neutral","relation":"fellow prisoner","note":"Shared the prison cart but dismissed Ralof''s attempts at stoic comfort"},"Player":{"aff":15,"type":"neutral","relation":"fellow prisoner","note":"Saw the player as a fellow innocent caught in the Imperial ambush","best":"Reached out to the player as a potential ally in their shared predicament"}}')
