INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lond', '{"Leigelf":{"aff":65,"type":"professional","relation":"employer","note":"Unwaveringly loyal miner who serves as Leigelf''s voice of reason","best":"Leigelf thanked him for sticking by him through the mine''s struggles","worst":"Leigelf compared him unfavorably to his estranged wife, calling him simple"},"Fruki":{"aff":20,"type":"platonic","relation":"fellow miner","note":"Was meant to share living quarters with her but chose the mine instead"},"Beitild":{"aff":-15,"type":"neutral","relation":"employer''s rival","note":"Indirectly opposes her as Leigelf''s loyal employee in the mine feud"}}')
ON CONFLICT (npc_name) DO UPDATE
