INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lord_harkon', '{"Serana":{"aff":-40,"type":"familial","relation":"daughter","note":"Views her primarily as a tool for fulfilling the prophecy rather than as family","worst":"Willing to sacrifice her to complete the Tyranny of the Sun"},"Valerica":{"aff":-75,"type":"estranged","relation":"estranged wife","note":"She betrayed him to protect Serana and hid the elder scroll; he seeks revenge","worst":"Her betrayal denied him the prophecy''s completion and stole his daughter away"},"Volkihar Clan":{"aff":40,"type":"professional","relation":"followers","note":"Rules them as lord and master through power, manipulation, and aristocratic authority"},"Dawnguard":{"aff":-85,"type":"enemy","relation":"enemy faction","note":"Sworn enemies who seek to prevent the Tyranny of the Sun prophecy"},"Molag Bal":{"aff":70,"type":"fanatical","relation":"patron","note":"Granted him pure-blood vampirism after he sacrificed a thousand innocents","best":"Blessed with immortality and the power of the vampire lord"}}')
