INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lortheim', '{"Jora":{"aff":90,"type":"romantic","relation":"wife","note":"Fellow priest and devoted partner serving together at the Temple of Talos"},"Ulfric Stormcloak":{"aff":65,"type":"grateful","relation":"protector of the faith","note":"Views Ulfric''s cause as a holy war for Talos worship","best":"Ulfric''s protection allows open Talos worship in Windhelm","worst":"Fears for Talos worship''s future if Ulfric falls"},"Imperial Authority":{"aff":-55,"type":"rival","relation":"religious oppressor","note":"Peacefully resists the Empire''s ban on Talos worship"},"Temple Worshippers":{"aff":60,"type":"mentor","relation":"congregation","note":"Spiritual guide and counselor to the faithful of Windhelm"}}')
