INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('louis_letrush', '{"Sibbi Black-Briar":{"aff":-50,"type":"betrayed","relation":"reneged business partner","note":"Paid half upfront for Frost but Sibbi refused to honor deal after being jailed","worst":"Sibbi used his imprisonment as excuse to void their horse purchase agreement"},"Maven Black-Briar":{"aff":-35,"type":"fearful","relation":"power figure he avoids","note":"Carefully avoids directly crossing her due to her influence over Riften","worst":"Her authority imprisoned Sibbi and disrupted his business deal"},"Player":{"aff":30,"type":"patron","relation":"hired agent","note":"Recruited player to deliver message to Sibbi and retrieve Frost","best":"Player successfully delivered message and brought Frost with lineage papers"}}')
