INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lu''ah_al-skaven', '{"Saeel":{"aff":95,"type":"romantic","relation":"husband","note":"His death retaking the Imperial City drove her into necromancy and obsession with resurrection","best":"Their life together in Hammerfell before the war","worst":"The Empire burned his body before she could raise him"},"Imperial Legion":{"aff":-80,"type":"betrayed","relation":"former ally","note":"Sent Saeel to die and burned his body rather than returning him to her","worst":"They burned Saeel''s body, destroying her only chance to resurrect him"},"Stormcloaks":{"aff":-70,"type":"enemy","relation":"enemy","note":"Equally blamed for the pointless war that widowed her"}}')
