INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('luaffyn', '{"Elda Early-Dawn":{"aff":45,"type":"professional","relation":"employer","note":"Values Luaffyn''s talent enough to employ her despite local prejudice against Dunmer"},"Susanna the Wicked":{"aff":40,"type":"platonic","relation":"colleague","note":"Fellow employee at Candlehearth Hall with friendly rapport"},"Malthyr Elenil":{"aff":65,"type":"platonic","relation":"friend and confidant","note":"Fellow Dunmer in Windhelm''s Gray Quarter who shares cultural understanding and trust"},"Revyn Sadri":{"aff":45,"type":"platonic","relation":"patron","note":"Regular listener who appreciates her preservation of Dunmer musical traditions"}}')
