INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lucan_valerius', '{"Camilla Valerius":{"aff":65,"type":"familial","relation":"sister","note":"Protective but sometimes controlling; disagrees with her ideas about running the store and wants her to settle down","best":"Built the Riverwood Trader together after emigrating from Cyrodiil","worst":"Constant arguments about store management and her romantic pursuits"},"Arvel the Swift":{"aff":-85,"type":"enemy","relation":"thief","note":"Stole the prized Golden Claw and fled to Bleak Falls Barrow","worst":"The robbery that violated his home and business"},"Sven":{"aff":-15,"type":"suspicious","relation":"sister''s suitor","note":"Views him with suspicion due to his interest in Camilla"},"Faendal":{"aff":10,"type":"transactional","relation":"business acquaintance","note":"Maintains neutral business relations despite his pursuit of Camilla"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lucia', '{"Brenuin":{"aff":65,"type":"mentor","relation":"survival mentor","note":"The only person who showed her kindness after her mother''s death","best":"Taught her how to survive on the streets of Whiterun"},"Mother":{"aff":90,"type":"familial","relation":"deceased mother","note":"Deeply missed; her death triggered Lucia''s downward spiral","best":"Provided a loving upbringing on the family farm","worst":"Died, leaving Lucia vulnerable and alone"},"Aunt and Uncle":{"aff":-80,"type":"estranged","relation":"cruel relatives","note":"Inherited the farm and expelled Lucia, calling her worthless","worst":"Thrown her out of her home after her mother''s death"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lucky_lorenz', '{"Dibella":{"aff":55,"type":"fanatical","relation":"patron goddess","note":"Maintained a shrine to Dibella in his home, suggesting sincere devotion uncommon for a bandit.","best":"Felt beauty and peace while praying at his shrine","worst":"Died before he could deepen his devotion further"}}')
ON CONFLICT (npc_name) DO UPDATE
