INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lurbuk', '{"Jonna":{"aff":-15,"type":"transactional","relation":"landlady","note":"Tolerates his presence only because he pays for his room; he delusionally believes she supports his art","best":"Allows him to perform and lodge at the Moorside Inn","worst":"Told him she''d have thrown him out long ago if not for payment"},"Chief Burguk":{"aff":-60,"type":"estranged","relation":"father","note":"Marked as rivals; Lurbuk rejected Orsimer warrior culture his father embodies","worst":"Abandoned his father''s traditions and the stronghold"},"Dark Brotherhood":{"aff":-100,"type":"nemesis","relation":"assassins","note":"Contract taken out on his life due to his atrocious performances; he remains completely oblivious","worst":"Someone hated his music enough to pay for his murder"},"Bards College":{"aff":-30,"type":"estranged","relation":"former school","note":"Asked to leave the College but still claims the association proudly","worst":"Was expelled or rejected from formal bardic training"},"Morthal Townsfolk":{"aff":-25,"type":"dismissive","relation":"audience","note":"Collectively annoyed by his performances; avoid him and refuse to acknowledge him","best":"Joined the mob against Movarth showing some civic spirit","worst":"Won''t even say good day, just walk away"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lydia', '{"Dragonborn":{"aff":80,"type":"protective","relation":"housecarl","note":"Sworn to serve and protect with her life after Jarl Balgruuf appointed her","best":"Proudly accepting the housecarl oath and standing at their side","worst":"Enduring bizarre dangers and carrying endless burdens with stoic resignation"},"Jarl Balgruuf":{"aff":65,"type":"professional","relation":"Jarl and appointer","note":"Personally selected her for the housecarl role; she serves his hold with pride"},"Irileth":{"aff":45,"type":"professional","relation":"fellow housecarl","note":"Likely trained together in combat and household duties at Dragonsreach"}}')
