INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lynea', '{"Riften Fishery":{"aff":15,"type":"transactional","relation":"instruction seeker","note":"Contacted them seeking a fishing instructor"},"Temple of Dibella":{"aff":40,"type":"platonic","relation":"devotee","note":"Possesses an Amulet of Dibella, suggesting religious devotion"},"Player":{"aff":55,"type":"student","relation":"fishing student","note":"Grateful for fishing lessons, rewards instructor with her Amulet of Dibella","best":"Caught three fish during the lesson and expressed genuine pleasure"}}')
