INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('lynly_star-sung', '{"Wilhelm":{"aff":75,"type":"protective","relation":"protector and employer","note":"Innkeeper who shelters her and promised to keep her safe","best":"He promised to keep her safe and swore not to break his word"},"Sibbi Black-Briar":{"aff":-95,"type":"nemesis","relation":"former fiancÃ©","note":"Murdered her unarmed brother and now hunts her to silence her","worst":"He killed Wulfur in cold blood after she discovered his affair"},"Wulfur":{"aff":85,"type":"familial","relation":"brother","note":"Murdered by Sibbi while unarmed after confronting him on her behalf","worst":"He died defending her honor against Sibbi"},"Klimmek":{"aff":25,"type":"admirer","relation":"admirer","note":"She finds him sweet but keeps him at arm''s length, not ready for romance"},"Maven Black-Briar":{"aff":-70,"type":"fearful","relation":"matriarch of enemy family","note":"Fears her power and influence; the reason she must remain hidden"},"Svana Far-Shield":{"aff":-55,"type":"contempt","relation":"rival","note":"Her affair with Sibbi triggered the chain of events that destroyed Lynly''s life"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
