INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('m''aiq_the_liar', '{"Other M''aiqs":{"aff":55,"type":"familial","relation":"ancestors or descendants","note":"May share name and wandering role across generations of Khajiit philosophers"},"Khajiit":{"aff":40,"type":"platonic","relation":"kinsmen","note":"Comments on the strange fate of Khajiit in Skyrim, suggesting lingering concern for his people"}}')
