INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ma''dran', '{"Ri''saad":{"aff":80,"type":"mentor","relation":"benefactor and mentor","note":"Ri''saad saved him from servitude aboard a trading ship and funded his caravan; Ma''dran pays a percentage of profits and considers the debt unrepayable","best":"Being given charge of his own caravan instead of facing a life of servitude"},"Ma''jhad":{"aff":45,"type":"professional","relation":"caravan guard","note":"Trusted guard and traveling companion in Ma''dran''s small three-member caravan"},"Ra''zhinda":{"aff":40,"type":"professional","relation":"caravan trader","note":"Loyal fellow trader traveling the Windhelm-Solitude route"},"Ysolda":{"aff":15,"type":"neutral","relation":"business acquaintance","note":"Claims to have met him, though his route does not pass through Whiterun"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ma''jhad', '{"Ma''dran":{"aff":65,"type":"professional","relation":"employer","note":"Caravan leader who Ma''jhad has served since young adulthood","best":"Years of profitable travel and mutual survival on Skyrim''s roads"},"Thieves Guild":{"aff":45,"type":"transactional","relation":"fence","note":"Trusted fence who buys stolen goods for the Guild after proving his reliability","best":"Accepted as a trusted fence within the Guild''s network"},"Ri''saad":{"aff":35,"type":"professional","relation":"fellow caravan fence","note":"Connected through the Thieves Guild''s caravan fence network"}}')
ON CONFLICT (npc_name) DO UPDATE
