INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ma''randru-jo', '{"Ri''saad":{"aff":65,"type":"professional","relation":"caravan leader and mentor","note":"Provided refuge and opportunity in Skyrim after Ma''randru-jo fled unknown circumstances in Elsweyr","best":"Accepted into the caravan when he had nowhere else to go"},"Atahbah":{"aff":35,"type":"professional","relation":"fellow caravan merchant","note":"Maintains a working rapport though keeps emotional distance"},"Khayla":{"aff":30,"type":"professional","relation":"caravan guard","note":"Mutual respect grounded in shared combat capability"},"Dark Brotherhood":{"aff":-80,"type":"fearful","relation":"contracted enemy","note":"An assassination contract on his life was given to Nazir; the client''s identity remains unknown","worst":"Someone paid gold to see him dead"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ma''tasarr', '{"Sinding":{"aff":-80,"type":"enemy","relation":"quarry","note":"The werewolf he was tasked to hunt in Hircine''s Great Hunt","worst":"Slain by Sinding in Bloated Man''s Grotto"},"Hircine":{"aff":85,"type":"fanatical","relation":"devotee","note":"Sought to prove himself worthy of Hircine''s favor through the Great Hunt","best":"Chosen to participate in Hircine''s Great Hunt"},"Khajiit Caravans":{"aff":30,"type":"familial","relation":"kin","note":"Distant but maintained connections with his nomadic people"},"Fellow Hunters":{"aff":40,"type":"professional","relation":"peers","note":"Held professional respect for others who pursue dangerous prey"}}')
