INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ma''zaka', '{"Solitude Guard":{"aff":35,"type":"professional","relation":"colleague","note":"City employee who was originally intended to cooperate with guards against marauder threats"},"Local sailors":{"aff":55,"type":"protective","relation":"guardian","note":"Maintains the lighthouse beacon specifically for their safety, respected elder among the maritime community","best":"Guiding ships safely through stormy nights into Solitude harbor"},"Blackblood Marauders":{"aff":-60,"type":"enemy","relation":"enemy","note":"Pirates and marauders who threaten the shipping lanes he once sailed and now protects","worst":"Knowing marauders prey on the very sailors he keeps the light burning for"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('madanach', '{"Borkul the Beast":{"aff":75,"type":"protective","relation":"bodyguard","note":"Loyal guardian who protects Madanach''s private cell in Cidhna Mine"},"Braig":{"aff":70,"type":"platonic","relation":"trusted follower","note":"Long-imprisoned Forsworn whom Madanach uses to demonstrate Markarth''s injustice to outsiders"},"Uraccen":{"aff":60,"type":"platonic","relation":"loyal follower","note":"Forsworn member imprisoned alongside him in Cidhna Mine"},"Jarl Igmund":{"aff":-80,"type":"enemy","relation":"oppressor","note":"Continues his father Hrolfdir''s opposition to the Forsworn cause"},"Thonar Silver-Blood":{"aff":-75,"type":"rival","relation":"jailer and manipulator","note":"Stayed Madanach''s execution to weaponize the Forsworn; Madanach bides his time waiting for Thonar to lower his guard","worst":"Forced to point Forsworn rage at Thonar''s enemies while sparing his allies"},"Ulfric Stormcloak":{"aff":-90,"type":"nemesis","relation":"conqueror","note":"Hired militia leader who retook Markarth and captured Madanach, ending Reachman independence","worst":"Besieged Markarth in 4E 176 and ended Madanach''s brief kingdom"},"Forsworn":{"aff":85,"type":"protective","relation":"his people","note":"Spiritual and political leader coordinating the rebellion from prison","best":"Led the Forsworn to independence in 4E 174"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('madena', '{"Jarl Skald the Elder":{"aff":25,"type":"professional","relation":"employer","note":"Serves as his court wizard but refuses his demands to fight, opposing his warmongering","worst":"He demands she take the battlefield; she refuses point-blank"},"Horik":{"aff":-20,"type":"suspicious","relation":"distrustful guard","note":"Horik openly distrusts her and says he will be watching her","worst":"He told her to her face he doesn''t trust her and will watch her"},"Aldmeri Dominion":{"aff":-70,"type":"enemy","relation":"wartime enemy","note":"Fought against them in the Great War; the killing still haunts her","worst":"Blasting apart young Elven soldiers at the Imperial City, the blood and burned flesh"},"Imperial Legion":{"aff":30,"type":"estranged","relation":"former employer","note":"Served as a battlemage but left due to trauma; has no desire to return","best":"Fought bravely in defense of the Imperial City","worst":"The carnage she caused in their service scarred her permanently"},"College of Winterhold":{"aff":10,"type":"professional","relation":"unresponsive ally","note":"She directs aspiring mages there and has sought their help with Dawnstar''s nightmares, but they ignore her pleas","worst":"Her pleas to the College about the nightmares go unheard"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('madesi', '{"Brynjolf":{"aff":-55,"type":"rival","relation":"business competitor","note":"Brynjolf''s miracle cures draw customers away from Madesi''s stall, and his Thieves Guild connections make him untouchable","worst":"Watching customers flock to Brynjolf''s snake oil while his honest craft goes ignored"},"Brand-Shei":{"aff":35,"type":"platonic","relation":"fellow merchant","note":"Occasional ally in marketplace politics, both struggling against Riften''s corruption"},"Haelga":{"aff":15,"type":"transactional","relation":"bunkhouse owner","note":"Takes his evening meals at her bunkhouse each night"},"Shadr":{"aff":20,"type":"client","relation":"customer","note":"Paying off jewelry in installments, a few septims at a time"},"Thieves Guild":{"aff":-40,"type":"suspicious","relation":"oppressive presence","note":"Their influence over Riften''s marketplace makes honest business nearly impossible","worst":"Knowing the Guild protects Brynjolf''s schemes while honest merchants suffer"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('madman', '{"Hermaeus Mora":{"aff":-90,"type":"fearful","relation":"unwilling vessel","note":"Mind shattered by reading a Black Book, desperately seeks escape from his influence","worst":"The Black Book shoved forbidden knowledge into his mind with black slick fingers"},"Fellow Bandits":{"aff":0,"type":"estranged","relation":"former associates","note":"Was a simple Nordic bandit on Solstheim before his encounter with the Black Book"}}')
