INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('majni', '{"Akar":{"aff":75,"type":"familial","relation":"younger brother and pack member","note":"Akar follows Majni''s leadership as part of the Frostmoon Pack"},"Frostmoon Pack":{"aff":80,"type":"protective","relation":"alpha and custodian","note":"Majni leads, protects, and preserves the pack''s ancient traditions and artifacts"},"Hircine":{"aff":95,"type":"fanatical","relation":"divine patron","note":"Reveres Hircine''s blessing as sacred and views lycanthropy as divine purpose","best":"Inherited the Alpha role and sacred rings blessed by Lord Hircine"}}')
ON CONFLICT (npc_name) DO UPDATE
