INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('malborn', '{"Delphine":{"aff":25,"type":"professional","relation":"Blades handler","note":"Coordinates his intelligence work; he resents her after the embassy operation exposes him","best":"Gave him purpose and means to strike at the Thalmor","worst":"The embassy infiltration destroyed his cover and turned him into a fugitive"},"Elenwen":{"aff":-85,"type":"enemy","relation":"Thalmor Ambassador, false employer","note":"Maintains servile facade while despising her as the face of his family''s killers","worst":"Must feign obedience while she represents everything he hates"},"Thalmor":{"aff":-100,"type":"nemesis","relation":"family''s murderers","note":"Murdered his entire family in Valenwood purges; he dedicates his life to their downfall","worst":"Purges in Valenwood killed his entire family"},"Player":{"aff":10,"type":"professional","relation":"reluctant ally","note":"Helped smuggle them into the embassy; later berates them for ruining his life but still seeks their help","best":"Successfully smuggled equipment into the embassy","worst":"Infiltration led to his cover being blown"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('malkoran', '{"Meridia":{"aff":-95,"type":"nemesis","relation":"temple desecrator","note":"Deliberately defiled Meridia''s temple and created undead shades in a place sacred to a Daedric Prince who loathes the undead","worst":"Corrupted her abandoned temple into a necromantic laboratory as a symbol of his power over death"}}')
