SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('malkus', '{"Lord Harkon":{"aff":80,"type":"servant","relation":"master","note":"Serves Lord Harkon''s court with unwavering dedication to the vampire cause"},"Dexion Evicus":{"aff":-70,"type":"enemy","relation":"captive","note":"Ambushed and attempted to enthrall the Moth Priest for vampire interests","worst":"The more you fight me, the more you will suffer, mortal"},"Vanik":{"aff":-80,"type":"enemy","relation":"slayer","note":"Dawnguard agent who kills Malkus at Forebears'' Holdout"},"Volkihar Vampire Court":{"aff":55,"type":"professional","relation":"faction","note":"Fellow servants of Lord Harkon''s vampire court"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mallus_maccius', '{"Sabjorn":{"aff":-85,"type":"enemy","relation":"former employer","note":"Held Mallus''s debt over him, reducing him to indentured servitude","worst":"Forced into servitude and treated like a slave under Sabjorn''s ownership"},"Maven Black-Briar":{"aff":65,"type":"patron","relation":"employer and patron","note":"Orchestrated Sabjorn''s downfall together; rewarded Mallus with meadery management","best":"Elevated him from Sabjorn''s lackey to one of the wealthiest merchants in Whiterun"},"Thieves Guild":{"aff":45,"type":"professional","relation":"criminal associates","note":"Collaborated on the Honningbrew plot; now serves as their fence in Whiterun Hold"},"Player":{"aff":55,"type":"grateful","relation":"ally and fence client","note":"Executed the poisoning plan that ruined Sabjorn and secured Mallus''s promotion","best":"Dumped poison into the brewing vat and eliminated the pest infestation on his behalf"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('malthyr_elenil', '{"Ambarys Rendar":{"aff":65,"type":"professional","relation":"employer and friend","note":"Trusted employee and designated successor to the cornerclub; Malthyr stays partly out of loyalty to him","best":"Named as the one Ambarys trusts to take over the cornerclub","worst":"Resigned to propping up a struggling business in a slum"},"Brunwulf Free-Winter":{"aff":55,"type":"platonic","relation":"advocate for Dunmer rights","note":"Appeals to him as a war hero who might influence Ulfric to improve conditions in the Gray Quarter","best":"Brunwulf agreed to speak to Ulfric on the Dunmer''s behalf"},"Ulfric Stormcloak":{"aff":-85,"type":"enemy","relation":"oppressor","note":"Views him as the architect of Dunmer marginalization; called his death ''justice''","worst":"Blames Ulfric for forcing Dunmer to live in squalor with open disdain for non-Nords"},"Gray Quarter Dunmer":{"aff":60,"type":"protective","relation":"community","note":"Shares a bond of mutual hardship and feels responsible for their collective dignity"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('malur_seloth', '{"Korir":{"aff":35,"type":"professional","relation":"employer","note":"Exploits the Jarl''s false belief in his College connections to avoid real work","best":"Jarl goes easy on him, expecting little from a supposed College agent","worst":"Deception could collapse if Jarl ever questions the connection"},"Nelacar":{"aff":-40,"type":"rival","relation":"theft target","note":"Schemes to steal Nelacar''s Staff of Arcane Authority to bolster his false reputation","worst":"Plans to rob him of his staff to maintain his facade"},"Thonjolf":{"aff":20,"type":"professional","relation":"housecarl","note":"Thonjolf gives him special treatment due to assumed College connections; Malur routinely dismisses his requests","best":"Goes easy on him believing he has College ties","worst":"Bluntly refuses even simple tasks Thonjolf assigns"},"College of Winterhold":{"aff":10,"type":"suspicious","relation":"fabricated association","note":"Has no actual connection but cultivates the town''s assumption that he does"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('maluril', '{"Bandit Guards":{"aff":25,"type":"transactional","relation":"bodyguards","note":"Hired muscle protecting his research in Mzinchaleft; he resents relying on them","worst":"Angry note chastising guards for failing their duties"},"Dark Brotherhood":{"aff":-90,"type":"nemesis","relation":"assassins","note":"Marked by a Dark Brotherhood contract; past transgressions made him a target","worst":"Contract issued for his death"},"Rival Scholars":{"aff":-50,"type":"rival","relation":"competitors","note":"Hostile competition with other Dwemer researchers over artifacts and discoveries"},"Former Academic Colleagues":{"aff":-60,"type":"estranged","relation":"former colleagues","note":"Burned bridges forced his exile from traditional academic institutions to Mzinchaleft"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('malyn_varen', '{"Azura":{"aff":-100,"type":"nemesis","relation":"cursed by","note":"Cursed him for defiling her Star, driving him insane","worst":"Azura''s curse shattered his mind and doomed him to eternal hunger"},"College of Winterhold":{"aff":-65,"type":"enemy","relation":"former employer","note":"Expelled him after he killed a student and his research was exposed","worst":"Cast him out for his crimes"},"Nelacar":{"aff":-35,"type":"estranged","relation":"former colleague","note":"Knows the truth about his forbidden experiments and likely opposed him"},"Loyal Followers":{"aff":15,"type":"servant","relation":"followers","note":"Devoted disciples who provided black souls to sustain his existence in the Star"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mammoth', '{"Giants":{"aff":75,"type":"protective","relation":"shepherds","note":"Symbiotic bond; mammoths defend their giant and turn passive once the giant falls","best":"grazing peacefully under giant''s watchful care","worst":"giant shepherd killed by attackers"},"Mammoth Herd":{"aff":90,"type":"familial","relation":"herd family","note":"Deep social bonds and coordinated protection of young and each other"},"Sabre Cats":{"aff":-45,"type":"enemy","relation":"predator","note":"Hunt young or isolated mammoths; herds rally against them"},"Dragons":{"aff":-35,"type":"fearful","relation":"aerial threat","note":"Occasional danger that mammoths will defend against if attacked"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mani', '{"Habd":{"aff":40,"type":"familial","relation":"father","note":"Loyal but resentful over the relocation; was waiting for Habd''s return before leaving for Hammerfell","worst":"Being uprooted from Hammerfell to frozen Skyrim"},"Ramati":{"aff":65,"type":"familial","relation":"mother","note":"Loved his mother, who was killed instantly in the Falmer attack"},"Sudi":{"aff":75,"type":"protective","relation":"younger sister","note":"Felt protective toward Sudi; both were dragged into the Abyss and killed","worst":"Dragged into Frostflow Abyss together and slain by Falmer"},"Falmer":{"aff":-100,"type":"nemesis","relation":"killers","note":"Falmer tunneled into the lighthouse cellar, slaughtered his family, and impaled him on a sword"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('maramal', '{"Dinya Balu":{"aff":92,"type":"romantic","relation":"wife","note":"Beloved wife and fellow priest devoted to Mara''s service","best":"Sharing their faith and life together at the Temple of Mara"},"Temple Initiates":{"aff":65,"type":"mentor","relation":"spiritual guide","note":"Patiently mentors new priests in Mara''s teachings and temple duties"},"Maven Black-Briar":{"aff":10,"type":"suspicious","relation":"diplomatic necessity","note":"Maintains cautious diplomacy with Riften''s true power behind the corruption he opposes","worst":"Navigating her shadow influence over the city he tries to heal"},"Laila Law-Giver":{"aff":45,"type":"professional","relation":"court advisor","note":"Serves as official religious advisor to the Jarl''s court"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('marcurio', '{"Keerava":{"aff":20,"type":"transactional","relation":"innkeeper","note":"Provides his lodging at the Bee and Barb in Riften"},"Talen-Jei":{"aff":35,"type":"platonic","relation":"drinking companion","note":"Friendly acquaintance and fellow regular at the Bee and Barb"},"College of Winterhold":{"aff":-10,"type":"dismissive","relation":"avoided institution","note":"Chose mercenary work over academic study despite ample magical ability"},"Thieves Guild":{"aff":5,"type":"neutral","relation":"cautious neighbors","note":"Cautious coexistence in Riften, neither antagonistic nor cooperative"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('margret', '{"General Tullius":{"aff":55,"type":"professional","relation":"commander","note":"Direct superior who assigned her the Markarth intelligence mission"},"Silver-Blood Family":{"aff":-65,"type":"enemy","relation":"investigation target","note":"Believes Thonar Silver-Blood orchestrated the assassination attempt on her","worst":"Nearly killed by an attack she believes Thonar arranged"},"Weylin":{"aff":-85,"type":"enemy","relation":"attempted murderer","note":"Forsworn agent who grabbed and tried to kill her in the market","worst":"Seized and nearly murdered in broad daylight"},"Player":{"aff":45,"type":"grateful","relation":"savior","note":"Gives necklace and reveals Imperial identity if rescued from Weylin","best":"Saved my life in the Markarth market"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('marise_aravel', '{"Thieves Guild":{"aff":-80,"type":"enemy","relation":"criminal organization","note":"Despises them as vermin who make decent living difficult in Riften","worst":"They live in the Ratway like dirty animals and harass honest shopkeepers"},"Maven Black-Briar":{"aff":-5,"type":"suspicious","relation":"powerful business figure","note":"Maintains cautiously respectful relations as required for survival in Riften"},"Drifa":{"aff":40,"type":"professional","relation":"customer and fellow vendor","note":"Regular market interaction with mutual appreciation","best":"Drifa praised her preserved apples and promised to be a customer for life"},"Shadr":{"aff":45,"type":"platonic","relation":"drinking companion","note":"Friendly interest, shares drinks at the Bee and Barb"},"Tythis":{"aff":35,"type":"professional","relation":"fellow shopkeeper","note":"Looks out for fellow merchants against Thieves Guild harassment","best":"Tythis warned her about the Thieves Guild harassing shopkeepers again"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('markarth_city_guard', '{"Jarl Igmund":{"aff":45,"type":"professional","relation":"official superior","note":"Serves under Igmund''s authority with pragmatic loyalty to the existing power structure"},"Thonar Silver-Blood":{"aff":30,"type":"transactional","relation":"secret paymaster","note":"Corrupt arrangement where Silver-Blood coin ensures guard complicity in Markarth''s hidden order"},"Madanach":{"aff":-45,"type":"suspicious","relation":"covert arrangement","note":"Complicated relationship mediated through the Silver-Bloods despite his role as Forsworn leader"},"Fellow Guards":{"aff":75,"type":"platonic","relation":"brotherhood","note":"Strong bond forged through shared secrets and survival in the Reach","best":"Standing together through Forsworn attacks and keeping the city''s dark truths buried"},"Forsworn":{"aff":-70,"type":"enemy","relation":"hostile faction","note":"Bitter enemies despite the corrupt arrangement with their imprisoned leader","worst":"Forsworn raids leaving guards scarred and comrades dead"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('markus', '{"Player":{"aff":55,"type":"professional","relation":"employer","note":"Primary employer who hires Markus as carriage driver at Heljarchen Hall"},"Stormcloak Comrades":{"aff":40,"type":"platonic","relation":"former comrades","note":"Occasional contacts from his military service days in the Stormcloak army"},"Heljarchen Hall Staff":{"aff":35,"type":"professional","relation":"colleagues","note":"Cooperative working relationship with fellow homestead workers"},"Local Merchants":{"aff":25,"type":"transactional","relation":"suppliers","note":"Friendly connections maintained for horse supplies and carriage maintenance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('master_conjurer', '{"Fellow Conjurers":{"aff":35,"type":"professional","relation":"loose allies","note":"Maintains loose alliance with other warlock lair inhabitants","best":"Shared research and mutual defense of lair territory","worst":"Competition over rare artifacts and summoning knowledge"},"College of Winterhold":{"aff":-45,"type":"suspicious","relation":"suspicious institution","note":"Strained relations due to controversial summoning practices","worst":"College scrutinizes their increasingly ambitious Daedric experiments"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"hostile hunters","note":"Actively hunt conjurers as Daedra summoners","worst":"Vigilants would kill them on sight if discovered"},"Summoned Daedra":{"aff":-10,"type":"transactional","relation":"bound servants","note":"Commands loyalty through magical binding; would turn on master if freed","best":"Daedra serve effectively when properly bound","worst":"Bound entities resent servitude and seek any chance to turn"},"Apprentices":{"aff":40,"type":"mentor","relation":"students","note":"Maintains a small collection of apprentices in the warlock lair","best":"Passing down conjuration knowledge to worthy students"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('master_cultist', '{"Miraak":{"aff":95,"type":"fanatical","relation":"revered master","note":"Absolute devotion driving their rise through the cult hierarchy","best":"First experiencing Miraak''s presence through the hidden texts"},"Hermaeus Mora":{"aff":25,"type":"fearful","relation":"forbidden knowledge source","note":"Respected but feared; prolonged exposure has left its mark on body and mind"},"Last Dragonborn":{"aff":-85,"type":"nemesis","relation":"false pretender","note":"Viewed as an illegitimate challenger who must be eliminated for Miraak''s supremacy","worst":"Learning another Dragonborn threatens the master''s rightful place"},"Lesser Cultists":{"aff":35,"type":"professional","relation":"subordinates","note":"Guided with stern authority in service to Miraak''s will"},"Fellow Master Cultists":{"aff":50,"type":"professional","relation":"peers","note":"Respected equals sharing the burden of leadership within the Temple"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('master_necromancer', '{"College of Winterhold":{"aff":-65,"type":"estranged","relation":"expelled former member","note":"Expelled for forbidden necromantic research; resents their restrictions and hopes to eventually challenge them","worst":"Dragged before the Arch-Mage and formally banished from the College"},"Vigilants of Stendarr":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Actively hunted by the Vigilants for practicing necromancy","worst":"Narrowly escaped a Vigilant raid that destroyed months of research"},"Other Necromancers":{"aff":10,"type":"suspicious","relation":"unreliable allies","note":"Loose alliance of convenience with rare trust between parties"},"Local Nord Population":{"aff":-70,"type":"contempt","relation":"research subjects","note":"Viewed primarily as future corpses and sources of reanimation materials"},"Ritual Master":{"aff":25,"type":"transactional","relation":"occasional collaborator","note":"Occasionally collaborate on larger necromantic rituals"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mathies', '{"Indara Caerellia":{"aff":85,"type":"romantic","relation":"wife","note":"Beloved farming partner who shares his grief; their union embodies Nord-Imperial cooperation","best":"Building a life and farm together in Falkreath","worst":"Mourning their daughter side by side at the graveyard"},"Lavinia":{"aff":95,"type":"familial","relation":"daughter","note":"Deceased daughter killed before her tenth winter; her memory drives his perseverance","best":"The happiness of their family before the tragedy","worst":"Finding her ripped apart, barely enough to bury"},"Sinding":{"aff":-95,"type":"enemy","relation":"daughter''s murderer","note":"A laborer who seemed decent before brutally murdering Lavinia; Mathies cannot comprehend the act","worst":"Discovering what Sinding did to his little girl"},"Runil":{"aff":70,"type":"platonic","relation":"spiritual advisor","note":"True friend who has helped both Mathies and Indara cope with their loss","best":"Providing sanctuary and comfort in their darkest time"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('matlara', '{"Torolf":{"aff":90,"type":"romantic","relation":"husband","note":"Beloved husband who died alongside her in the dragon attack","best":"Building a life together in Helgen","worst":"Dying together in Alduin''s attack"},"Haming":{"aff":95,"type":"protective","relation":"son","note":"Young son who survived the attack on Helgen","best":"Raising and protecting him in Helgen","worst":"Unable to survive to continue protecting him"},"Helgen Townspeople":{"aff":45,"type":"platonic","relation":"community","note":"Part of the close-knit community before its destruction"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('maul', '{"Maven Black-Briar":{"aff":90,"type":"professional","relation":"right-hand enforcer","note":"Fiercely loyal personal enforcer and confidant; elevated to housecarl if Maven becomes Jarl","best":"Promoted from common thief to Maven''s most trusted enforcer"},"Dirge":{"aff":70,"type":"familial","relation":"brother","note":"Close bond as fellow enforcers who came up together in Riften''s underworld"},"Brynjolf":{"aff":45,"type":"professional","relation":"former colleague","note":"Knows Brynjolf from Thieves Guild days and directs potential recruits his way"},"Thieves Guild":{"aff":35,"type":"professional","relation":"former member","note":"Maintains valuable connections though no longer an active member"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('maurice_jondrelle', '{"Danica Pure-Spring":{"aff":25,"type":"professional","relation":"fellow priest of Kynareth","note":"Shares faith but clashes over her neglect of the Gildergreen","worst":"Angry confrontation about the tree''s disgraceful state and her misplaced priorities"},"The Dragonborn":{"aff":55,"type":"platonic","relation":"traveling companion","note":"Grateful if peaceful path chosen; appalled if violence used against Eldergleam","best":"Communed with the Eldergleam to provide a sapling after Dragonborn accepted his peaceful way","worst":"Witnessed Dragonborn cut roots with Nettlebane, calling it barbaric and abominable"},"Eldergleam Sanctuary Pilgrims":{"aff":65,"type":"platonic","relation":"fellow worshippers","note":"Chose to remain at the sanctuary permanently if peaceful solution achieved"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('maven_black-briar', '{"Hemming Black-Briar":{"aff":55,"type":"familial","relation":"eldest son and heir","note":"Groomed to continue the Black-Briar legacy; her chosen instrument for the family''s future"},"Sibbi Black-Briar":{"aff":25,"type":"familial","relation":"imprisoned son","note":"His violent tendencies are a liability she manages rather than excuses"},"Ingun Black-Briar":{"aff":15,"type":"familial","relation":"daughter","note":"Tolerates her alchemical pursuits with dismissive indifference"},"Jarl Laila Law-Giver":{"aff":40,"type":"professional","relation":"political ally","note":"Personal friend despite ideological differences, yet Maven easily manipulates her"},"Thieves Guild":{"aff":60,"type":"professional","relation":"patron","note":"Strategic criminal partners who help maintain her grip on Riften","best":"The Guild eliminated her competition and secured her economic dominance"},"Dark Brotherhood":{"aff":10,"type":"fearful","relation":"associate","note":"Handles her permanent problems, but she fears their reach as much as she values their service"},"Maul":{"aff":65,"type":"professional","relation":"enforcer","note":"Trusted right-hand man who enforces her will throughout Riften"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('maximian_axius', '{"Selina Axius":{"aff":95,"type":"romantic","relation":"wife","note":"Beloved wife to whom he wrote tender final letters before the eruption claimed him","best":"Writing letters home filled with love and hope of reunion","worst":"Dying at Fort Frostmoth knowing he would never see her again"},"Siricus Axius":{"aff":85,"type":"familial","relation":"son","note":"Deeply loved son he longed to return to"},"Atia Axius":{"aff":85,"type":"familial","relation":"daughter","note":"Deeply loved daughter he longed to return to"},"Falx Carius":{"aff":65,"type":"professional","relation":"commanding officer","note":"Respected general under whom he served with distinction at Fort Frostmoth"},"Fort Frostmoth Garrison":{"aff":55,"type":"platonic","relation":"brothers-in-arms","note":"Fellow soldiers he served alongside until the end"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('meden_maren', '{"House Redoran":{"aff":75,"type":"grateful","relation":"patron","note":"Loyal supporter who credits House Redoran for reopening the mine and restoring his livelihood","best":"Mine reopened allowing him to provide for his family again"},"Crescius Caerellius":{"aff":45,"type":"admirer","relation":"mine elder","note":"Respects the former mine owner''s family legacy and long dedication to the mine"},"Family":{"aff":85,"type":"familial","relation":"dependents","note":"Primary motivation is providing stable income for his family through honest work"},"Fellow Miners":{"aff":55,"type":"platonic","relation":"colleagues","note":"Maintains positive working relationships and often lifts their spirits"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('medresi_dran', '{"Hired Workers":{"aff":-40,"type":"contempt","relation":"former employees","note":"Views them as cowardly tools who fled the excavation at the first sign of danger","worst":"They abandoned the dig after discovering draugr in the chamber"},"Player Character":{"aff":15,"type":"transactional","relation":"temporary ally","note":"Saw them as useful muscle to clear the ruins, never intended to honor the split","best":"Agreed to split the treasure if they cleared the draugr","worst":"Sprinted ahead screaming the treasure is all mine, leaving them behind"},"Nordic Scholars":{"aff":20,"type":"transactional","relation":"information sources","note":"Provided research and legends about Angarvunde in exchange for compensation"},"Rival Treasure Hunters":{"aff":-25,"type":"rival","relation":"competitors","note":"Views other artifact seekers as obstacles to her ambitions and wealth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('meeko', '{"Former Nord Master":{"aff":95,"type":"familial","relation":"deceased master","note":"Meeko loyally guarded his master''s body and shack after death, refusing to leave","worst":"Finding his master dead in the shack"},"Dragonborn":{"aff":70,"type":"protective","relation":"new companion","note":"Potential new master Meeko seeks out, leading travelers to his shack","best":"Being chosen as a new companion and given purpose again"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('melka', '{"Petra":{"aff":-95,"type":"nemesis","relation":"usurper","note":"Betrayed and imprisoned Melka, stealing Blind Cliff Bastion from her","worst":"Woke in a cage while Petra claimed her tower and poisons"},"The Last Dragonborn":{"aff":25,"type":"transactional","relation":"liberator","note":"Cooperates honorably but still views them as a useful morsel","best":"Accepted her word and freed her from Petra''s cage"},"Other Hagravens":{"aff":-20,"type":"neutral","relation":"kin","note":"Prefers solitary existence and keeps distance from others of her kind"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mena', '{"Enmon":{"aff":85,"type":"romantic","relation":"husband","note":"Beloved husband and emotional anchor through their family''s crisis","best":"His steady comfort when the house felt empty and quiet","worst":"Helplessly watching him search for answers about Fjotra"},"Fjotra":{"aff":95,"type":"familial","relation":"daughter","note":"Cherished daughter now serving as the Sybil of Dibella","best":"Knowing she will be a great Sybil and help all of Skyrim","worst":"The Forsworn taking her from their home"},"Forsworn":{"aff":-95,"type":"nemesis","relation":"daughter''s kidnappers","note":"Shattered her family by abducting Fjotra","worst":"The day they stole her little girl"},"Temple of Dibella":{"aff":40,"type":"grateful","relation":"daughter''s caretakers","note":"Bittersweet acceptance; they protect Fjotra but took her away","best":"Knowing Fjotra is safe and cared for at the temple"},"Ainethach":{"aff":15,"type":"neutral","relation":"town leader","note":"Deflects strangers to him as Karthwasten''s authority"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mercer_frey', '{"Gallus":{"aff":-85,"type":"betrayed","relation":"former fellow Nightingale","note":"Murdered Gallus to conceal his theft of the Skeleton Key from the Twilight Sepulcher","worst":"Slaying his mentor and comrade to protect his crimes"},"Karliah":{"aff":-90,"type":"nemesis","relation":"framed fellow Nightingale","note":"Betrayed and framed Karliah for Gallus''s murder; seeks to eliminate her before she exposes him","worst":"Framing an innocent comrade for his own crime"},"Brynjolf":{"aff":-30,"type":"contempt","relation":"trusted lieutenant","note":"Maintains a professional facade while secretly viewing Brynjolf as a gullible tool","worst":"Exploiting genuine loyalty he holds in complete disdain"},"Maven Black-Briar":{"aff":15,"type":"transactional","relation":"business associate","note":"Mutually beneficial arrangement that maintains the Guild''s relevance in Riften"},"Vald":{"aff":5,"type":"professional","relation":"personal bodyguard","note":"Assigned to guard Riftweald Manor; valued only for his utility"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('merilar_rendas', '{"Servos Rendas":{"aff":-85,"type":"betrayed","relation":"brother and former research partner","note":"Imprisoned him and left him to die after her descent into madness","worst":"Locked her own brother in a cage to die"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('michel_lylvieve', '{"Azzada Lylvieve":{"aff":85,"type":"romantic","relation":"husband","note":"Loving husband and farming partner who shares her worries about old friends"},"Clinton Lylvieve":{"aff":80,"type":"familial","relation":"son","note":"Son she helps raise on the family farm"},"Julienne Lylvieve":{"aff":80,"type":"familial","relation":"daughter","note":"Daughter she nurtures and teaches household skills"},"Logrolf":{"aff":55,"type":"platonic","relation":"old family friend","note":"Worrying about his well-being in Markarth","worst":"Learning he sleeps on the street believing his house is haunted"},"Dragon Bridge Community":{"aff":60,"type":"platonic","relation":"neighbors","note":"Respected member known for generosity during hard times"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mikael', '{"Carlotta Valentia":{"aff":55,"type":"crush","relation":"romantic target","note":"Obsessively pursues her despite her firm and repeated rejections","best":"She finally looked my way today","worst":"She sent someone to tell me to back off"},"Hulda":{"aff":30,"type":"professional","relation":"employer","note":"Tolerates his behavior as long as he keeps patrons entertained","best":"She agreed to ''Mogo''s Mead'' for once","worst":"She shot down my Argonian ballad again"},"Bards College":{"aff":-25,"type":"estranged","relation":"former school","note":"Forced to leave after a scandal involving the headmistress and her husband","worst":"That misunderstanding with the headmistress''s husband"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mikrul_gauldurson', '{"Gauldur":{"aff":-85,"type":"betrayed","relation":"father and murder victim","note":"Slew him out of greed and jealousy to steal his amulet","worst":"Murdered his own father and divided his stolen amulet among the brothers"},"Jyrik Gauldurson":{"aff":25,"type":"platonic","relation":"eldest brother and co-conspirator","note":"United in patricide and dividing the amulet, though corruption likely strained their bond","best":"Conspired together to seize their father''s power"},"Sigdis Gauldurson":{"aff":25,"type":"platonic","relation":"middle brother and co-conspirator","note":"Shared in the treachery against their father and the division of the amulet","best":"Conspired together to seize their father''s power"},"Archmage Geirmund":{"aff":-95,"type":"nemesis","relation":"vanquisher","note":"Defeated and entombed Mikrul in Folgunthur for his crimes","worst":"Was struck down and sealed in undead bondage by Geirmund"},"High King Harald":{"aff":-70,"type":"enemy","relation":"ruler who erased his legacy","note":"Ordered all records of the Gauldursons'' treachery destroyed","worst":"Had their names and deeds stricken from history"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mila_valentia', '{"Carlotta Valentia":{"aff":95,"type":"familial","relation":"mother","note":"Raised solely by Carlotta; exceptionally close bond and deep admiration","best":"Going to the tavern for supper together after a long day at the stall","worst":"Being told they can''t close the stand early because the fruit will spoil"},"Lars Battle-Born":{"aff":55,"type":"platonic","relation":"playmate","note":"Daily playmate from a prominent Whiterun family"},"Braith":{"aff":25,"type":"platonic","relation":"playmate","note":"Fellow child playmate, but relationship complicated by Braith''s bullying tendencies","worst":"Being bullied by Braith during playtime"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('millius', '{"Gratian Caerellius":{"aff":65,"type":"mentor","relation":"mentor and superior","note":"Served as his research assistant; his prudent warnings about the ruins went unheeded","best":"Stood and fought alongside him against the draugr rather than flee","worst":"Gratian ignored his advice to leave the artifact, triggering the deadly attack"},"East Empire Company":{"aff":40,"type":"patron","relation":"employer","note":"Funded the archaeological expeditions in Raven Rock Mine"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('milore_ienth', '{"Garyn Ienth":{"aff":90,"type":"romantic","relation":"husband","note":"Beloved husband and farming partner who supplies her ingredients and keeps Raven Rock fed.","best":"Building a life and farm together on Solstheim after fleeing Morrowind"},"Lami":{"aff":75,"type":"mentor","relation":"former alchemy teacher","note":"Took Milore in after the eruption and taught her alchemy over several years in Morthal.","best":"Years of patient alchemical training that shaped her career"},"Raven Rock Residents":{"aff":60,"type":"professional","relation":"community she serves","note":"Respected apothecary essential to the settlement''s survival and wellbeing.","best":"Providing vital potions and ingredients through harsh conditions"},"Miraak":{"aff":-85,"type":"fearful","relation":"former mind-controller","note":"Enslaved her mind through the Earth Stone; she is deeply disturbed by the violation.","worst":"Being entranced and forced to serve against her will at the Earth Stone"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mineete_vinius', '{"Corpulus Vinius":{"aff":88,"type":"familial","relation":"father and mentor","note":"Beloved father who teaches her innkeeping and vocabulary","best":"Learning sophisticated words and business skills from him"},"Sorex Vinius":{"aff":68,"type":"familial","relation":"older brother","note":"Works alongside her at the family inn"},"Svari":{"aff":72,"type":"platonic","relation":"close friend and playmate","note":"Regular playmate in Solitude"},"Kayd":{"aff":60,"type":"platonic","relation":"childhood friend","note":"Joins in games with Minette and Svari"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('miner', '{"Ralis Sedarys":{"aff":-25,"type":"suspicious","relation":"employer","note":"Recruited by Ralis for the Kolbjorn excavation, but growing distrust over the dangerous conditions and his handling of the situation.","worst":"Watching colleagues die while Ralis kept pushing the excavation forward"},"Bradyn":{"aff":45,"type":"platonic","relation":"fellow miner","note":"Worried about Bradyn''s fate as the Kolbjorn excavation turned deadly.","best":"Working alongside each other before the draugr overwhelmed them","worst":"Losing contact when the undead rose inside the barrow"},"Mireli":{"aff":45,"type":"platonic","relation":"fellow miner","note":"Worried about Mireli''s fate as the Kolbjorn excavation turned deadly.","best":"Sharing the labor and dangers of the dig together","worst":"Fearing Mireli may have fallen to the draugr"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('miraak', '{"Hermaeus Mora":{"aff":-80,"type":"betrayed","relation":"former patron","note":"Sought forbidden knowledge from Mora then betrayed him, yet remains trapped in his realm","worst":"Imprisoned in Apocrypha for millennia as punishment"},"Vahlok the Jailor":{"aff":-70,"type":"rival","relation":"ancient foe","note":"The dragon priest who defeated him and forced his retreat to Apocrypha","worst":"Defeated in combat and driven into exile"},"Dragons":{"aff":-90,"type":"betrayed","relation":"former masters","note":"Turned against the dragons who once ruled him after discovering his Dragonborn power","best":"Enslaved dragons using Bend Will"},"Last Dragonborn":{"aff":-60,"type":"rival","relation":"rival Dragonborn","note":"Views them as an inferior usurper threatening his unique status as first Dragonborn","worst":"Their existence challenges his supremacy"},"Cultists":{"aff":20,"type":"fanatical","relation":"worshipers","note":"Fanatical followers who revere him as a god and carry out his will from Apocrypha","best":"Their unwavering devotion across millennia of isolation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mirabelle_ervine', '{"Savos Aren":{"aff":65,"type":"professional","relation":"superior","note":"She serves as his second-in-command and shields him from unnecessary interruptions","best":"Appointed her as Master Wizard, placing full trust in her ability"},"Sergius Turrianus":{"aff":55,"type":"platonic","relation":"close colleague","note":"Shares daily dinner with him, suggesting friendship beyond duty"},"Faralda":{"aff":45,"type":"professional","relation":"trusted colleague","note":"Relies on her to screen new applicants at the College entrance"},"Ancano":{"aff":-50,"type":"suspicious","relation":"Thalmor advisor","note":"Keeps him under careful observation and coldly rebuffs his interference","worst":"His constant probing into College decisions she must repeatedly shut down"},"Citizens of Winterhold":{"aff":-25,"type":"suspicious","relation":"local populace","note":"Tense relationship due to longstanding mistrust of the College"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mirmulnir', '{"Alduin":{"aff":85,"type":"fanatical","relation":"master","note":"Survived millennia in hiding and emerged only to serve upon Alduin''s return","best":"Answering the call when Alduin returned to Tamriel"},"Dovahkiin":{"aff":-90,"type":"nemesis","relation":"slayer","note":"Recognized the Dragonborn only in his final moments","worst":"Slain at the Western Watchtower outside Whiterun"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mirri_severin', '{"Vendil Severin":{"aff":75,"type":"romantic","relation":"lover and co-conspirator posing as father","note":"They have maintained a romantic relationship while posing as father and daughter for a decade-long assassination plot","best":"Ten years of intimate partnership working toward their shared goal","worst":"Vendil''s fear that Tilisu''s jealousy could expose them all"},"Tilisu Severin":{"aff":-20,"type":"rival","relation":"fellow conspirator posing as mother","note":"Tilisu is openly jealous of Mirri''s relationship with Vendil, creating tension within their conspiracy","worst":"Tilisu''s bitter suggestion that Mirri find someone else to sleep with"},"Councilor Morvayn":{"aff":-85,"type":"enemy","relation":"assassination target","note":"The Severins have spent ten years plotting to kill him and end his rule","worst":"A decade of hiding her hatred while waiting to strike"},"Raven Rock Citizens":{"aff":-30,"type":"contempt","relation":"marks for deception","note":"She views the townspeople with disgust while maintaining a facade of nobility","worst":"Being forced to live among people she considers beneath her"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mjoll_the_lioness', '{"Aerin":{"aff":92,"type":"platonic","relation":"savior and constant companion","note":"Rescued her from near death in a Dwemer ruin; the only person in Riften she fully trusts","best":"He pulled me from the ruins when I was bleeding and near death"},"Maven Black-Briar":{"aff":-85,"type":"enemy","relation":"corrupt matriarch","note":"Despises Maven as the embodiment of everything wrong with Riften","worst":"She has bribed countless officials and strangles the city with her influence"},"Thieves Guild":{"aff":-90,"type":"nemesis","relation":"sworn enemy","note":"Vocally opposes the Guild and considers them rabble worse than the Dark Brotherhood","worst":"They would betray one another over a single gold coin"},"Citizens of Riften":{"aff":65,"type":"protective","relation":"self-appointed guardian","note":"Patrols the streets nightly to protect common folk from corruption and crime"},"The Jarl of Riften":{"aff":-15,"type":"suspicious","relation":"authority figure","note":"Respects the position but frustrated by inaction against Riften''s corruption"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mogdurz', '{"Chief Mauhulakh":{"aff":55,"type":"professional","relation":"chief","note":"Respects and serves the stronghold leader without question"},"Dushnamub":{"aff":35,"type":"platonic","relation":"fellow miner","note":"Shares a mutual devotion to mining work and Orcish discipline"},"Malacath":{"aff":90,"type":"fanatical","relation":"patron deity","note":"Views her daily mining labor as sacred worship","best":"Every vein of ore is Malacath''s gift to our people"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mogrul', '{"Mages Guild":{"aff":75,"type":"professional","relation":"local representative","note":"Respected member who advances Guild influence in outlying settlements"},"Apprentice Mages":{"aff":60,"type":"mentor","relation":"mentor","note":"Takes genuine pleasure in sharing alchemical knowledge with seekers"},"Local Traders":{"aff":40,"type":"transactional","relation":"business contacts","note":"Professional relationships maintained for acquiring rare ingredients"},"Traveling Merchants":{"aff":35,"type":"transactional","relation":"suppliers","note":"Regular contacts for sourcing exotic alchemical components"},"Town Residents":{"aff":50,"type":"platonic","relation":"community","note":"Generally well-regarded as a reliable source of magical knowledge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('moira', '{"Dragonborn":{"aff":90,"type":"obsessed","relation":"delusional spouse","note":"Believes they are married after a drunken encounter; violently possessive and refuses to accept rejection.","best":"The night we pledged our eternal love and exchanged rings","worst":"When my beloved tried to leave and demanded the ring back"},"Esmerelda":{"aff":-45,"type":"jealous","relation":"perceived rival","note":"Views her as a threat to her supposed romance with the Dragonborn.","worst":"Daring to come between me and my beloved"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('molgrom_twice-killed', '{"Brynjolf":{"aff":-75,"type":"rival","relation":"former superior","note":"Resents Brynjolf for arranging his imprisonment over his violent methods","worst":"Being thrown in jail through Brynjolf''s connections with Maven"},"Vex":{"aff":80,"type":"crush","relation":"savior and close friend","note":"Vex saved his life at the Ragged Flagon; he harbors romantic interest in her","best":"Vex tearing apart his attacker and giving him a healing potion"},"Maven Black-Briar":{"aff":-60,"type":"enemy","relation":"indirect adversary","note":"Used her connections to facilitate his imprisonment on Brynjolf''s behalf"},"Thieves Guild":{"aff":-20,"type":"estranged","relation":"former member","note":"Views the Guild with mixed contempt and longing after his expulsion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('moric_sidrey', '{"Minorne":{"aff":90,"type":"fanatical","relation":"enchantress","note":"Fell under her enchanting influence at Ruunvald and composed scripture devoted to her","best":"Composing scripture in her honor after being charmed","worst":"Surrendering his free will and former vows to her influence"},"Vigilants of Stendarr":{"aff":-50,"type":"estranged","relation":"former order","note":"Abandoned his lifelong vows and mission after falling under Minorne''s enchantment","best":"Years of faithful scholarly service before Ruunvald","worst":"Leading fellow Vigilants into the enchantment that claimed them all"},"Florentius Baenius":{"aff":-20,"type":"suspicious","relation":"dissenting colleague","note":"Florentius reportedly warned against the excavation Moric championed","worst":"Dismissing Florentius''s warnings about Ruunvald"},"Excavation Team":{"aff":40,"type":"platonic","relation":"fellow enchanted","note":"Led them at Ruunvald before they all fell under Minorne''s spell together","best":"Shared discovery and scholarly pursuit at Ruunvald","worst":"Leading his own team into the enchantment that consumed them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('morthal_guard', '{"Jarl Idgrod Ravencrone":{"aff":65,"type":"professional","relation":"jarl","note":"Respects her leadership and has learned to trust her prophetic visions"},"Aslfur":{"aff":45,"type":"professional","relation":"steward","note":"Handles their pay and duty assignments as the Jarl''s husband"},"Fellow Guards":{"aff":70,"type":"platonic","relation":"comrades","note":"Close-knit brotherhood forged through shared danger in the marshes"},"Morthal Citizens":{"aff":55,"type":"protective","relation":"townspeople","note":"Feels duty-bound to protect locals, especially during supernatural threats"},"Benor":{"aff":55,"type":"rival","relation":"friendly rival","note":"Fellow warrior who helps maintain town security; competitive but mutual respect"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('morven', '{"Nepos the Nose":{"aff":85,"type":"protective","relation":"bodyguard and servant","note":"Deeply loyal to Nepos as both employer and Forsworn superior, willing to sacrifice his life protecting him","best":"Years of trusted service maintaining Nepos''s household and security","worst":"Failing to protect Nepos when their operation is exposed"},"Uaile":{"aff":55,"type":"professional","relation":"fellow agent","note":"Fellow undercover Forsworn operative sharing the same dangerous mission in Nepos''s household"},"Tynan":{"aff":45,"type":"professional","relation":"colleague","note":"Works together maintaining Nepos''s household cover and Forsworn operations"},"Forsworn":{"aff":90,"type":"fanatical","relation":"devoted operative","note":"Born among the Forsworn and trained from youth to serve their cause of reclaiming the Reach","best":"Being selected and trained for this critical infiltration mission","worst":"The inevitable exposure and failure of the Markarth operation"},"Markarth Guard":{"aff":-15,"type":"suspicious","relation":"avoided authority","note":"Maintains cautious distance to preserve his cover identity as a humble servant"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('morven_stroud', '{"Necromancer Coven":{"aff":-90,"type":"nemesis","relation":"murderers","note":"Killed him and trapped his soul after he unknowingly sold them counterfeit ingredients","worst":"Murdered and soul-trapped over an honest merchant''s mistake"},"Ideal Masters":{"aff":-50,"type":"fearful","relation":"overlords of his prison","note":"Indirect rulers of the Soul Cairn where his soul remains imprisoned"},"Soul Cairn Inhabitants":{"aff":25,"type":"platonic","relation":"fellow trapped souls","note":"Maintains casual trading relationships with other souls in the Soul Cairn"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('morwen', '{"Baldor Iron-Shaper":{"aff":78,"type":"mentor","relation":"master smith","note":"Her mentor in Skaal smithing; she was relieved when he was saved, admitting she wasn''t ready to replace him","best":"Learning the ways of iron-shaping from a patient teacher","worst":"Nearly losing Baldor and facing becoming smith before she was ready"},"Bera":{"aff":90,"type":"familial","relation":"mother","note":"Her deceased Skaal mother whose memory she honors; returning her necklace meant more than anyone could know","best":"Her mother''s love and Skaal heritage passed down to her","worst":"Losing her mother and the amulet that connected her to that memory"},"Nikulas":{"aff":50,"type":"protective","relation":"village youth","note":"Counsels him about the outside world but doubts he has the patience for the forge"},"Runil":{"aff":45,"type":"grateful","relation":"priest","note":"The Falkreath priest who safeguarded her mother''s amulet","best":"Receiving her mother''s amulet back through his keeping of it"},"Skaal People":{"aff":70,"type":"platonic","relation":"community","note":"Her chosen people whom she serves and protects with her warrior skills and smithing craft","best":"Finding belonging and purpose among her mother''s people","worst":"Watching them fall under the dark power of the Wind Stone"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('moth_gro-bagol', '{"Ghorza gra-Bagol":{"aff":80,"type":"familial","relation":"sister","note":"Served together in the Imperial Legion for over ten years and both now work as blacksmiths in Markarth","best":"Fighting alongside Ghorza in the Legion for a decade"},"Jarl Igmund":{"aff":55,"type":"professional","relation":"employer","note":"Serves as his personal blacksmith and fulfills specific requests like cooling blades in Daedra blood"},"Thongvor Silver-Blood":{"aff":65,"type":"platonic","relation":"fellow legionnaire","note":"Served together in the Imperial Legion and maintains a friendly rapport with teasing banter","best":"Sharing Legion days and mutual respect as soldiers"},"Imperial Legion":{"aff":45,"type":"professional","relation":"former service","note":"Grateful for how the Empire treated Orcs but considers the current war none of his concern","best":"Mastering the forge during Legion service"},"Tacitus Sallustius":{"aff":-15,"type":"contempt","relation":"sister''s apprentice","note":"Dismisses him as talentless and tells people not to bother with him","worst":"Watching him fail to show any real smithing aptitude"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('movarth_piquine', '{"Alva":{"aff":40,"type":"servant","relation":"thrall and agent","note":"Key instrument in his plot to control Morthal through her manipulation of locals","best":"Alva successfully infiltrated Morthal and secured Hroggar as a pawn"},"Jarl Idgrod Ravencrone":{"aff":-70,"type":"enemy","relation":"target of schemes","note":"Primary obstacle to his control over Morthal and Hjaalmarch","worst":"Her awareness of dark forces in her hold threatens his operations"},"Unnamed Priest":{"aff":15,"type":"estranged","relation":"former mentor","note":"Guided his vampire hunting expeditions before his obsession led to his own transformation","best":"Their collaboration across Tamriel yielded countless vampire kills","worst":"His unbound curiosity betrayed their shared mission and led to his downfall"},"Hroggar":{"aff":-15,"type":"contempt","relation":"indirect pawn","note":"Barely registers as an individual, merely a tool accessed through Alva"},"Morthal Citizens":{"aff":-30,"type":"contempt","relation":"prey and potential thralls","note":"Viewed as cattle for feeding and recruitment into his coven"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mralki', '{"Erik":{"aff":80,"type":"protective","relation":"son","note":"Overprotective father who fears losing his only remaining family to the dangers of adventuring","best":"Erik is all the family I have left","worst":"Erik sneaking downstairs to try on his old armor against his wishes"},"Lemkil":{"aff":-25,"type":"contempt","relation":"neighbor","note":"Disapproves of Lemkil''s cold and harsh treatment of his own daughters","worst":"Calling Lemkil the coldest man in Skyrim for speaking ill of his own flesh and blood"},"Rorik":{"aff":35,"type":"professional","relation":"town founder","note":"Respects Rorik as the founder of Rorikstead where he rebuilt his life after the Legion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mudcrab', '{"Slaughterfish":{"aff":-70,"type":"enemy","relation":"natural predator","note":"Constant threat in shared waterways","worst":"Surviving numerous encounters with slaughterfish"},"Fellow Mudcrabs":{"aff":10,"type":"rival","relation":"territorial competitors","note":"Compete for territory but occasionally ally against larger threats"},"Local Fishermen":{"aff":-80,"type":"enemy","relation":"hunters","note":"Frequent antagonists who harvest mudcrabs for meat and chitin","worst":"Narrowly avoiding becoming someone''s dinner"},"Horkers":{"aff":0,"type":"neutral","relation":"distant cousins","note":"Share the coastline but generally ignore each other"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('muiri', '{"Alain Dufont":{"aff":-100,"type":"betrayed","relation":"ex-lover","note":"Manipulated Muiri to steal from the Shatter-Shields, then abandoned her","worst":"Used her to rob her oldest friends and discarded her without a second thought"},"Nilsine Shatter-Shield":{"aff":-80,"type":"betrayed","relation":"former best friend","note":"Abandoned Muiri when she needed support most; Muiri now wants her dead","worst":"Turned her back on their lifelong friendship after the Aegisbane theft"},"Bothela":{"aff":55,"type":"mentor","relation":"employer","note":"Took Muiri in and trained her in alchemy at the Hag''s Cure","best":"Gave her refuge and a new trade when she had nothing"},"Tova Shatter-Shield":{"aff":-60,"type":"estranged","relation":"former maternal figure","note":"Once a surrogate mother who cast Muiri out alongside the rest of the clan","worst":"Banished her from the only home and family she had known"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mul_gro-largash', '{"Gadba gro-Largash":{"aff":75,"type":"familial","relation":"brother","note":"Beloved brother and partner in their shared dream of becoming chiefs","best":"Working the mine together toward their shared future","worst":"Realizing only one of them can actually be chief"},"Chief Mauhulakh":{"aff":35,"type":"professional","relation":"employer","note":"Hired them to work Gloombound Mine when Narzulbur lacked miners","best":"Being given the opportunity to mine ebony for wealth"},"Dushnamub":{"aff":-15,"type":"suspicious","relation":"employer''s son","note":"Dushnamub distrusts the brothers and fears they may challenge his father","worst":"Dushnamub voicing suspicion about them to Chief Mauhulakh"},"Largashbur clan":{"aff":-20,"type":"estranged","relation":"former stronghold","note":"Left to seek fortune; no one at Largashbur mentions them or claims any connection","worst":"Being completely forgotten by their original stronghold"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('mulush_gro-shugurz', '{"Urzoga gra-Shugurz":{"aff":60,"type":"familial","relation":"sister","note":"Shares his stern worldview; she guards Cidhna Mine while he oversees the smelter"},"Thonar Silver-Blood":{"aff":45,"type":"professional","relation":"patron","note":"Owns the smelter and everything in Markarth; Mulush strives to meet his quotas"},"Omluag":{"aff":-50,"type":"contempt","relation":"subordinate","note":"Complaining worker who talks back and demands breaks","worst":"Omluag had the gall to ask for a break from the smelter heat"},"Hathrasil":{"aff":-30,"type":"contempt","relation":"subordinate","note":"Cowed worker Mulush threatens with violence over potential silver theft"},"Nepos the Nose":{"aff":-20,"type":"contempt","relation":"colleague","note":"Mulush publicly blames him for falling behind on silver shipments"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('murbul', '{"Burguk":{"aff":75,"type":"familial","relation":"son","note":"She raised him to become Chief and continues to advise him on leadership and Malacath''s will.","best":"Seeing Burguk ascend to Chief of Dushnikh Yal"},"Malacath":{"aff":90,"type":"fanatical","relation":"patron deity","note":"Serves as his priestess and interpreter of his will for the stronghold.","best":"Discerning that Malacath is pleased with their tribe''s strength"},"Dushnikh Yal":{"aff":65,"type":"protective","relation":"her tribe","note":"Serves as wise woman, healer, and spiritual guide; particularly concerned for young Orcs'' health."},"Other Orc Strongholds":{"aff":30,"type":"professional","relation":"diplomatic contacts","note":"Maintains connections with wise women of other strongholds."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nagrub', '{"Arob":{"aff":85,"type":"familial","relation":"mother and mentor","note":"Close hunting companion who guides his development and teaches him patience","best":"Sharing the hunt together and welcoming the day''s prey","worst":"Her constant presence means he has no choice but to follow her example"},"Chief Burguk":{"aff":55,"type":"familial","relation":"father and chief","note":"Respected authority figure whom he will eventually challenge for chiefdom as tradition demands","best":"Learning leadership from observing his father''s rule","worst":"Knowing he must one day fight his own father for leadership"},"Umurn":{"aff":40,"type":"rival","relation":"brother and future rival","note":"Acknowledges him as a strong warrior and looks forward to fighting him for chiefdom","best":"Mutual respect as warriors of the stronghold","worst":"The inevitable combat between them for the right to rule"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('namasur', '{"Lord Harkon":{"aff":75,"type":"servant","relation":"master","note":"Serves with absolute loyalty and finds contentment in his subordinate role"},"Volkihar Vampires":{"aff":55,"type":"platonic","relation":"clan mates","note":"Considers them his eternal family and dining companions"},"Dawnguard":{"aff":-70,"type":"enemy","relation":"enemy faction","note":"Threaten his peaceful existence at Castle Volkihar"},"Castle Volkihar Thralls":{"aff":10,"type":"contempt","relation":"livestock","note":"Views them as necessary resources for sustaining the castle''s lifestyle"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nana_ildene', '{"Betrid Silver-Blood":{"aff":-90,"type":"enemy","relation":"assassination target","note":"Primary target of her long-term Forsworn mission; murders her without hesitation when the order comes","worst":"Killed Betrid in cold blood shouting ''For the Forsworn!''"},"Thonar Silver-Blood":{"aff":-80,"type":"enemy","relation":"deceptive employer","note":"Manipulates his trust for twenty years while plotting his family''s destruction","best":"Thonar praises her loyalty, completely unaware of her true nature"},"Donnel":{"aff":65,"type":"professional","relation":"fellow Forsworn agent","note":"Co-conspirator embedded in the Treasury House; together they await the signal to strike"},"Madanach":{"aff":85,"type":"fanatical","relation":"Forsworn king","note":"Serves the King in Rags with unwavering ideological commitment built over a lifetime of resistance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('narfi', '{"Reyda":{"aff":95,"type":"familial","relation":"sister","note":"Central figure in his life; lives in denial about her disappearance","best":"Reyda caring for him after their parents died","worst":"Reyda disappearing while gathering ingredients by the river"},"Wilhelm":{"aff":50,"type":"grateful","relation":"innkeeper","note":"Shows occasional kindness and maintains false hope about Reyda''s return","best":"Wilhelm telling him Reyda would come back"},"Parents":{"aff":80,"type":"familial","relation":"parents","note":"Deceased; he was able to say goodbye to them unlike Reyda"},"Ivarstead Residents":{"aff":10,"type":"neutral","relation":"townspeople","note":"Tolerate his presence but keep their distance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('naris_mavani', '{"Crescius Caerellius":{"aff":60,"type":"professional","relation":"mine supervisor","note":"Shows respect for Crescius as the mine''s supervisor"},"House Redoran":{"aff":70,"type":"grateful","relation":"benefactor","note":"Thanks them for reopening the mines so he can provide for his family again"},"Family":{"aff":90,"type":"familial","relation":"wife and children","note":"Deeply committed to providing for his family through mining work"},"Fellow Miners":{"aff":55,"type":"platonic","relation":"coworkers","note":"Maintains positive working relationships with other miners in Raven Rock"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('naris_the_wicked', '{"Test Subjects":{"aff":-95,"type":"contempt","relation":"victims","note":"Views them as expendable research material for his cruel experiments","worst":"Wishes they survived longer so he could prolong their suffering"},"College of Winterhold":{"aff":-55,"type":"estranged","relation":"former institution","note":"Expelled for conducting forbidden experiments on fellow students","worst":"Exiled from the College for his cruel research on peers"},"Local Bandits":{"aff":10,"type":"transactional","relation":"suppliers","note":"Occasional suppliers of fresh test subjects for his experiments"},"Necromancers":{"aff":15,"type":"transactional","relation":"contacts","note":"Loose network for exchanging forbidden magical knowledge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('narri', '{"Valga Vinicia":{"aff":75,"type":"professional","relation":"employer and friend","note":"Narri''s most trusted employer; refuses to leave her despite yearning for adventure","best":"Being trusted as Valga''s unofficial successor for the inn"},"Tekla":{"aff":55,"type":"mentor","relation":"fellow server","note":"Sympathizes with Tekla and advocates for hiring her at the inn","best":"Advocating for Tekla''s employment to Valga"},"Dengeir":{"aff":-10,"type":"rival","relation":"grumpy regular patron","note":"Recurring weekly arguments about service quality; Narri responds with wit","worst":"Same argument every week even when he was Jarl"},"Bolund":{"aff":-15,"type":"contempt","relation":"difficult customer","note":"Resents being called ''gossip'' and threatens to let him die of thirst","worst":"Being repeatedly called ''gossip''"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nazeem', '{"Ahlam":{"aff":15,"type":"estranged","relation":"wife","note":"Marriage of social convenience; she openly resents his arrogance and neglect","best":"Marriage elevated his standing in Whiterun society","worst":"Her constant expressions of dissatisfaction with him"},"Wilmuth":{"aff":5,"type":"transactional","relation":"farm manager","note":"Delegates all actual labor while collecting the profits"},"Carlotta Valentia":{"aff":-10,"type":"contempt","relation":"market vendor","note":"Regularly criticizes her produce as inferior to his farm''s"},"Anoriath":{"aff":-15,"type":"dismissive","relation":"hunter and vendor","note":"Publicly disparages his game and meat quality as beneath him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nazir', '{"Astrid":{"aff":80,"type":"professional","relation":"superior","note":"Nazir worships the ground she walks on and declares her the only mistress he serves.","best":"The Dark Brotherhood saved me from myself, and I have never looked back."},"Cicero":{"aff":-55,"type":"contempt","relation":"fellow Brother","note":"Despises jesters and entertainers; deeply distrusts Cicero''s unstable zealotry.","worst":"I particularly hate jesters."},"Babette":{"aff":50,"type":"platonic","relation":"fellow assassin","note":"Mutual respect between long-standing Brotherhood members; survived the sanctuary attack together."},"Night Mother":{"aff":10,"type":"suspicious","relation":"sacred corpse","note":"Makes an exception for the Night Mother but rejects her authority over Astrid''s leadership.","worst":"Not crazy about the corpses of old women."},"The Listener":{"aff":45,"type":"professional","relation":"fellow assassin","note":"Professional respect that grows as the Listener proves themselves; provides contracts with dry humor."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('necromage', '{"Reanimated Servants":{"aff":55,"type":"protective","relation":"undead servants","note":"Treated as precious possessions and prized tools, cared for more than the living","best":"Each successful reanimation feels like a triumph over death itself"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"hunters","note":"Sworn enemies who relentlessly hunt necromancers and the undead","worst":"Forced to flee lairs and abandon research when Vigilant patrols close in"},"Local Necromancer Coven":{"aff":25,"type":"transactional","relation":"allies","note":"Loose alliance for trading knowledge, specimens, and rare components"},"College of Winterhold":{"aff":-45,"type":"estranged","relation":"former institution","note":"Rejected membership due to forbidden necromantic practices","worst":"Expelled and shunned for pursuing resurrection magic"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('necromancer_adept', '{"College of Winterhold":{"aff":-75,"type":"enemy","relation":"former institution","note":"Expelled for pursuing necromantic research beyond acceptable boundaries","worst":"Cast out and branded an outcast for forbidden studies"},"Fellow Necromancers":{"aff":35,"type":"professional","relation":"allies","note":"Loose alliance of convenience and shared dark knowledge","best":"Finding kinship among fellow outcast mages after years of isolation"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"hunters","note":"Active enemies who relentlessly hunt practitioners of necromancy","worst":"Living under constant threat of zealous persecution"},"Local Nord Populations":{"aff":-55,"type":"contempt","relation":"victims","note":"Viewed as hostile superstitious folk and convenient sources of research materials"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('neetrenaza', '{"Scouts-Many-Marshes":{"aff":65,"type":"platonic","relation":"egg-brother","note":"Fellow dock worker who shares the daily struggle of Argonian life in Windhelm"},"Stands-In-Shallows":{"aff":70,"type":"platonic","relation":"confidant","note":"Close coworker and trusted confidant within the dock community"},"Shahvee":{"aff":40,"type":"platonic","relation":"neighbor","note":"Assemblage neighbor whose optimism clashes with his bitter outlook"},"Torbjorn Shatter-Shield":{"aff":-55,"type":"contempt","relation":"employer","note":"Deeply resents him for unfair treatment of Argonian dock workers","worst":"Enduring another day of unequal pay and harsh conditions under his watch"},"Nordic Dock Supervisors":{"aff":-65,"type":"rival","relation":"overseers","note":"Mutual distrust and antagonism define this oppressive working relationship","worst":"Being dismissed and demeaned by overseers who see Argonians as disposable labor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nelacar', '{"Dagur":{"aff":25,"type":"transactional","relation":"landlord","note":"Tolerates Nelacar''s room-renting and experiments in exchange for safety assurances","best":"We have an understanding about my privacy and research","worst":"That horrible smell and the explosion sounds from failed experiments"},"College of Winterhold":{"aff":10,"type":"estranged","relation":"former institution","note":"Was forced to leave after failed experiments but stays nearby for colleague access","best":"Former colleagues still consult with me on soul gems and enchanting","worst":"Being asked to leave the College over my experimental mishaps"},"Malyn Varen":{"aff":-15,"type":"pitying","relation":"former colleague","note":"Witnessed his descent into madness and pursuit of immortality through Azura''s Star","worst":"Watching him sacrifice everything chasing immortality through the Star"},"Azura":{"aff":-75,"type":"contempt","relation":"Daedric Prince","note":"Views Daedra as evil after seeing what the Star did to Malyn Varen","worst":"Her artifact drove Malyn to madness and ruin"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nelkir', '{"Balgruuf the Greater":{"aff":-75,"type":"estranged","relation":"father","note":"Harbors intense violent resentment toward his father, who knows nothing about him","worst":"One day, I''ll tear his face apart so he can leave me alone"},"Whispering Lady":{"aff":45,"type":"mentor","relation":"secret confidant","note":"Mysterious entity who shares dark secrets with him through the basement door, likely manipulating him","best":"She started telling me even more secrets"},"Frothar":{"aff":-10,"type":"estranged","relation":"half-brother","note":"Shares his father but not his mother, creating emotional distance"},"Dagny":{"aff":-10,"type":"estranged","relation":"half-sister","note":"Shares his father but not his mother, creating emotional distance"},"Farengar":{"aff":-25,"type":"contempt","relation":"court wizard","note":"Dismissively suggested nobody would notice if he went missing","worst":"Nobody would notice if Farengar went missing, I promise you"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('neloth', '{"Talvas Fathryon":{"aff":15,"type":"mentor","relation":"apprentice","note":"Regularly berates him yet sees magical potential worth cultivating","best":"Acknowledges Talvas has some talent beneath his incompetence","worst":"Casts Calm spells on him rather than dealing with his complaints"},"Ildari Sarothril":{"aff":-85,"type":"nemesis","relation":"former apprentice","note":"His failed heart stone experiment drove her mad and she tried to kill him","worst":"She attempted to murder him after he replaced her heart with a heart stone"},"Varona Nelas":{"aff":-5,"type":"neutral","relation":"steward","note":"Viewed her as a replaceable tool; her death was merely an inconvenience"},"Elynea Mothren":{"aff":5,"type":"transactional","relation":"mycologist","note":"Values her work maintaining the tower''s fungal growth but nothing more"},"House Telvanni":{"aff":30,"type":"professional","relation":"political faction","note":"Maintains his rank as Master Wizard but has minimal contact with the mainland"},"Hermaeus Mora":{"aff":45,"type":"curious","relation":"Daedric Prince of Knowledge","note":"Seeks out Black Books and Apocryphic knowledge with eager fascination"},"Miraak":{"aff":-10,"type":"neutral","relation":"would-be rival","note":"Considers him a nuisance rather than a genuine threat"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nenya', '{"Jarl Siddgeir":{"aff":30,"type":"professional","relation":"Jarl she serves","note":"Quietly manages his responsibilities due to his negligent leadership","best":"He occasionally listens to her counsel alongside Helvard''s","worst":"His capricious nature and disinterest in governance force her to compensate constantly"},"Dengeir of Stuhn":{"aff":60,"type":"professional","relation":"former Jarl and employer","note":"Appointed her steward in his youth and entrusted her with the hold''s administration","best":"He recognized her competence and gave her the stewardship"},"Helvard":{"aff":40,"type":"professional","relation":"fellow advisor","note":"Collaborates on hold security and logistics despite occasional professional friction","worst":"He cautioned her about merchants potentially selling weapons to invading forces"},"Citizens of Falkreath":{"aff":55,"type":"protective","relation":"charges","note":"Ensures fair treatment of all residents regardless of race or political affiliation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nepos_the_nose', '{"Madanach":{"aff":90,"type":"fanatical","relation":"king and master","note":"Serves as Madanach''s most trusted agent in Markarth, receiving and executing his orders without question for nearly 20 years","best":"Receiving his king''s messages and carrying out his will","worst":"The weariness of sending the young to their deaths in his king''s name"},"Thonar Silver-Blood":{"aff":-40,"type":"contempt","relation":"employer","note":"Uses Thonar as unwitting cover for Forsworn operations while officially handling worker relations for the Silver-Blood family","worst":"Deceiving a man who trusts him with business affairs"},"Uaile":{"aff":55,"type":"professional","relation":"bodyguard and servant","note":"Trusted Forsworn agent masquerading as his protective housekeeper"},"Tynan":{"aff":45,"type":"professional","relation":"house guard","note":"Loyal Forsworn servant providing security"},"Morven":{"aff":45,"type":"professional","relation":"servant and conspirator","note":"Dedicated Forsworn agent within his household"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nerien', '{"Psijic Order":{"aff":85,"type":"professional","relation":"loyal member and emissary","note":"Devoted servant who carries out the Order''s will through subtle intervention"},"Ancano":{"aff":-55,"type":"suspicious","relation":"subject of observation","note":"Monitored as a dangerous threat to the College and magical balance","worst":"Foreseeing the catastrophe Ancano''s ambitions would unleash"},"The Last Dragonborn":{"aff":70,"type":"mentor","relation":"chosen guide","note":"Selected by the Psijic Order as the only one with potential to prevent disaster","best":"Declaring belief in their potential to prevail against the coming danger"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nervous_patron', '{"Thoring":{"aff":15,"type":"transactional","relation":"innkeeper","note":"Provides refuge at Candlehearth Hall while he awaits the Dark Brotherhood"},"Contract Target":{"aff":-95,"type":"nemesis","relation":"assassination target","note":"Wronged him severely enough to warrant the Black Sacrament","worst":"Whatever drove him to seek murder as his only solution"},"Dark Brotherhood":{"aff":20,"type":"fearful","relation":"client","note":"Performed the Black Sacrament seeking their services despite evident dread","best":"Hope that they will end his torment by eliminating the target"},"Windhelm Guards":{"aff":-30,"type":"fearful","relation":"authorities to avoid","note":"Keeps distance to avoid drawing attention to his dark dealings"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('niels', '{"Valdr":{"aff":75,"type":"platonic","relation":"hunting party leader","note":"Respected leader and longtime companion in the hunting party","best":"Tracking and hunting dangerous prey together across Falkreath Hold","worst":"Killed by spriggans on the hunt where Valdr survived"},"Ari":{"aff":60,"type":"platonic","relation":"fellow hunter","note":"Companion in Valdr''s party who died alongside Niels","best":"Hunting together as part of Valdr''s renowned party","worst":"Both killed by spriggans in Moss Mother Cavern"},"Falkreath Merchants":{"aff":25,"type":"transactional","relation":"pelt buyers","note":"Regular business contacts who purchased bear pelts and animal products"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nightlord_vampire', '{"Lesser Vampires":{"aff":45,"type":"protective","relation":"coven subordinates","note":"Rules as master and spiritual guide, maintaining order among their followers"},"Thralls":{"aff":10,"type":"transactional","relation":"enslaved agents","note":"Network of enthralled mortals serving as spies and daylight operatives"},"Vigilants of Stendarr":{"aff":-85,"type":"nemesis","relation":"hunters","note":"Bitter enemies who actively hunt vampire kind","worst":"Endless persecution by those who would see our kind extinguished"},"Volkihar Clan":{"aff":15,"type":"suspicious","relation":"rival clan","note":"Cautious diplomatic relations maintained while preserving independence"},"Local Jarls":{"aff":-10,"type":"contempt","relation":"manipulation targets","note":"Manipulated through proxies and thralls to protect vampire interests"},"Molag Bal":{"aff":55,"type":"indebted","relation":"creator","note":"Underwent transformation through direct communion with the Daedric Prince","best":"The gift of eternal night bestowed through sacred communion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nikulas', '{"Erlendr":{"aff":75,"type":"platonic","relation":"shield-brother","note":"Fellow companion who shared the doomed quest and petrification at Brodir Grove"},"Hunroor":{"aff":75,"type":"platonic","relation":"shield-brother","note":"Fellow companion who shared the doomed quest and petrification at Brodir Grove"},"Grimkell":{"aff":-90,"type":"nemesis","relation":"betrayer","note":"Treacherous wizard who petrified Nikulas and his companions at Brodir Grove","worst":"Turned us to stone when we trusted him"},"Ulfgar the Unending":{"aff":85,"type":"grateful","relation":"avenger","note":"Honored ally who slew Grimkell and later joined them in Sovngarde","best":"Avenged our betrayal by slaying the wizard"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nils', '{"Elda Early-Dawn":{"aff":45,"type":"professional","relation":"employer","note":"Values his work ethic but doubts his management capability","best":"Considered as potential successor to run Candlehearth Hall","worst":"Elda publicly expressed doubt about trusting him to run things"},"Revyn Sadri":{"aff":15,"type":"transactional","relation":"wood delivery client","note":"Receives daily wood deliveries at Sadri''s Used Wares"},"Oengul War-Anvil":{"aff":15,"type":"transactional","relation":"wood delivery client","note":"Receives regular wood deliveries at the forge"},"Imperial Legion":{"aff":-75,"type":"enemy","relation":"ideological opponent","note":"Deep anti-Imperial sentiments shaped by the Great War era","worst":"Pretends Imperial soldiers'' heads are on his chopping block"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nilsine_shatter-shield', '{"Friga Shatter-Shield":{"aff":95,"type":"familial","relation":"twin sister","note":"Inseparable until Friga''s murder; Nilsine is consumed by grief and survivor''s guilt","best":"Growing up inseparable, never apart","worst":"Friga''s murder by the Butcher"},"Tova Shatter-Shield":{"aff":80,"type":"familial","relation":"mother","note":"Bound by shared grief over Friga''s death","best":"Supporting each other through mourning","worst":"Watching her mother drown in grief"},"Torbjorn Shatter-Shield":{"aff":55,"type":"familial","relation":"father","note":"Loves him but strained by his insistence the family move past Friga''s death","worst":"His dismissive attitude toward her grief"},"Muiri":{"aff":-85,"type":"enemy","relation":"former friend","note":"Once like a sister, now called a backstabbing strumpet and dead to the family","best":"When Muiri was like a sister to her","worst":"The betrayal and bitter falling out"},"Hillevi Cruel-Sea":{"aff":40,"type":"platonic","relation":"market acquaintance","note":"One of the few who brings out Nilsine''s rare lighthearted moments","best":"Sharing laughs over tomato purchases"},"Helgird":{"aff":35,"type":"platonic","relation":"priest","note":"Seeks comfort in her quarters at the Hall of the Dead while grieving"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('niluva_hlaalu', '{"Indaryn":{"aff":-40,"type":"professional","relation":"supervisor","note":"Threatens to fire her for poor performance and suspects her addiction","worst":"Told her if she''s late one more time he''ll kick her right out the door"},"Haelga":{"aff":-55,"type":"transactional","relation":"landlord","note":"Increasingly hostile over late rent, calls her a skooma-addled idiot","worst":"Ranted to Svana about Niluva wasting money on Dark Elf garbage"},"Svana Far-Shield":{"aff":10,"type":"neutral","relation":"landlord''s niece","note":"Minimally defends her to Haelga but shows little personal warmth"},"Romlyn Dreth":{"aff":50,"type":"platonic","relation":"coworker","note":"Understands her struggles and shows her genuine kindness","best":"Sympathized with her about Indaryn''s bullying and predicted he''d push someone too far one day"},"House Hlaalu":{"aff":-30,"type":"estranged","relation":"estranged family","note":"Rejected her father''s expectations and left the family tradition behind","worst":"Called her father a n''wah for trying to control her life"},"Tythis Ulen":{"aff":-25,"type":"indebted","relation":"creditor","note":"Owes him money and keeps making excuses about repayment","worst":"Confronted her about broken repayment promises and skooma spending"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nimphaneth', '{"Eola":{"aff":75,"type":"mentor","relation":"cult leader","note":"Deeply respects Eola as the spiritual and operational leader of the Reachcliff Cave cult"},"Sanyon":{"aff":45,"type":"platonic","relation":"fellow cultist","note":"Cave companion and fellow cannibal who shares her dietary practices"},"Namira":{"aff":95,"type":"fanatical","relation":"worshipped deity","note":"Devoted worshipper who serves the Lady of Decay through ritual cannibalism","best":"Participating in the feast that honored Namira''s hunger"},"Namira Cult":{"aff":60,"type":"platonic","relation":"spiritual family","note":"Views fellow cultists as refined dining companions and kindred spirits"}}')
