INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nimriel', '{"Severio Pelagia":{"aff":75,"type":"romantic","relation":"former employer and lover","note":"Game data lists relationship rank 4 (lovers), though neither spoke of it; she honors his memory by maintaining the farm","best":"trusted her with increasing responsibility and ultimately the farm''s future","worst":"his death during the Battle for Whiterun"},"Carlotta Valentia":{"aff":40,"type":"platonic","relation":"fellow vendor and friend","note":"Trades goods and farming advice with her in Whiterun"},"Gloth":{"aff":25,"type":"professional","relation":"co-worker","note":"Fellow farmhand living and working at Pelagia Farm"}}')
