INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('niranye', '{"Thieves Guild":{"aff":50,"type":"professional","relation":"former fence","note":"Former fence eager to reestablish profitable connections after guild''s decline","best":"Profitable fencing arrangement during the Guild''s golden age"},"Summerset Shadows":{"aff":-30,"type":"rival","relation":"rival fence","note":"Altmer criminal organization competing for fencing operations in Windhelm","worst":"Their presence threatens her monopoly on underground trade"},"Dunmer Community":{"aff":-25,"type":"dismissive","note":"Views them as too proud and naive to overcome Nordic prejudice"},"Torsten Cruel-Sea":{"aff":10,"type":"suspicious","relation":"acquaintance","note":"Knows her name and underworld connections enough to direct investigators her way"},"Torbjorn Shatter-Shield":{"aff":20,"type":"professional","relation":"business acquaintance","note":"Carefully maintained business relationship in Windhelm"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('niruin', '{"Mercer Frey":{"aff":-70,"type":"enemy","relation":"former guildmaster","note":"Enraged by Mercer''s betrayal of the Thieves Guild","worst":"Mercer''s betrayal and murder of Gallus"},"Brynjolf":{"aff":60,"type":"professional","relation":"guild superior","note":"Respects his leadership and judgment within the Guild"},"Delvin Mallory":{"aff":65,"type":"platonic","relation":"guild contact","note":"Delvin connected him to the Skyrim Guild after he left Valenwood","best":"Delvin introducing him to Gallus and the Guild"},"Gallus":{"aff":55,"type":"platonic","relation":"former guildmaster","note":"Gallus welcomed him into the Skyrim Guild"},"Father":{"aff":-20,"type":"estranged","relation":"father","note":"Rejected his carpenter trade; father ultimatum forced him to leave Valenwood","worst":"Father confronting him and forcing exile under threat of jail"},"Thieves Guild":{"aff":75,"type":"platonic","relation":"guild family","note":"Found belonging and excitement among fellow guild members"},"Maven Black-Briar":{"aff":30,"type":"transactional","relation":"business associate","note":"Connected through wine knowledge and Guild activities"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nirya', '{"Faralda":{"aff":-65,"type":"rival","relation":"bitter rival","note":"Paranoid about Faralda spreading lies about her; both compete for influence and share a rivalry over Sergius.","worst":"Faralda spreading lies about her and trying to undermine her position"},"Sergius Turrianus":{"aff":35,"type":"romantic","relation":"secret lover","note":"Uses the relationship for political information and advantage; genuine affection is questionable given her manipulative nature."},"Ancano":{"aff":-15,"type":"suspicious","relation":"suspicious colleague","note":"Distrusts him and correctly suspects he is up to something, though she finds him handsome.","worst":"Ancano''s betrayal and near-destruction of the College"},"Arch-Mage":{"aff":55,"type":"transactional","relation":"sycophantic subordinate","note":"Excessively deferential once the player becomes Arch-Mage, angling for favor and recognition.","best":"The player becoming Arch-Mage and saving the College"},"Nelacar":{"aff":-25,"type":"contempt","relation":"disgraced former colleague","note":"Views his exile as justified and his current work in town as disgraceful."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nivenor', '{"Bolli":{"aff":-45,"type":"contempt","relation":"husband","note":"Marriage of convenience for wealth; she cheats on him and resents his charitable donations","best":"Access to his fortune and the Riften Fishery''s income","worst":"Confronted him about donating gold to the Temple of Mara"},"Haelga":{"aff":-30,"type":"rival","relation":"husband''s paramour","note":"Bolli''s affair with Haelga creates implied rivalry between the women"},"Maramal":{"aff":-40,"type":"dismissive","relation":"husband''s spiritual advisor","note":"Views his religious influence on Bolli as foolishness that drains her wealth","worst":"Called someone ''as crazy as Maramal'' when offered a Mara pamphlet"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('niyya', '{"Ildari Sarothril":{"aff":-100,"type":"nemesis","relation":"torturer","note":"Nursed her back to health; she betrayed the crew, killed most, and experimented on survivors","worst":"Witnessed all her companions die in Ildari''s horrific experiments"},"Mining Crew Companions":{"aff":70,"type":"platonic","relation":"fallen companions","note":"Deceased crew who shared her ordeal before being killed or experimented on","worst":"Watching them die one by one under Ildari''s torture"},"Geldis Sadri":{"aff":35,"type":"grateful","relation":"sanctuary provider","note":"Sheltered her at The Retching Netch after her escape from Highpoint Tower"},"Player":{"aff":55,"type":"grateful","relation":"rescuer","best":"Being freed from Ildari''s prison at Highpoint Tower"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('njada_stonearm', '{"Athis":{"aff":25,"type":"rival","relation":"sparring partner","note":"Regular sparring partner she consistently defeats in their public brawls at Jorrvaskr.","best":"Beating him in their brawl in front of the Companions"},"Skjor":{"aff":65,"type":"professional","relation":"respected sparring partner","note":"Deeply respected training partner whose death she sincerely mourned.","best":"Skjor praising her defensive prowess as a worthy path to glory","worst":"Learning of his death at the hands of the Silver Hand"},"Aela":{"aff":15,"type":"suspicious","relation":"fellow Companion","note":"Tense relationship marked by Aela''s threat when Njada pried about her and Skjor.","best":"Aela genuinely seeking her advice on shield techniques","worst":"Aela threatening to cut off her ears for asking about her and Skjor"},"The Circle":{"aff":45,"type":"professional","relation":"authority","note":"Respects their authority and follows their judgment without question, but maintains emotional distance."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('noble', '{"Imperial Soldier Guard":{"aff":10,"type":"transactional","relation":"hired bodyguard","note":"Views guard as a necessary tool rather than a person","worst":"Relies on guard for survival but offers no genuine respect"},"Imperial City Nobility":{"aff":65,"type":"platonic","relation":"social peers","note":"Maintains connections with other wealthy Cyrodiilic families"},"Skyrim''s Jarls":{"aff":30,"type":"professional","relation":"business associates","note":"Conducts trade with provincial leaders he views as beneath Imperial nobility"},"East Empire Company":{"aff":45,"type":"professional","relation":"trade associates","note":"Likely business connections through commercial ventures in Skyrim"}}')
