INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nobleman', '{"East Empire Company":{"aff":65,"type":"transactional","relation":"major trading partner","note":"Primary source of steady income through generational trade investments"},"Erikur":{"aff":40,"type":"professional","relation":"business associate","note":"Fellow Solitude noble with shared financial interests"},"Vittoria Vici":{"aff":45,"type":"professional","relation":"social connection","note":"Important contact for facilitating Imperial trade dealings"},"Common merchants":{"aff":-15,"type":"contempt","relation":"inferior contacts","note":"Viewed as useful tools but socially beneath notice"}}')
