INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('noblewoman', '{"Titus Mede II":{"aff":55,"type":"professional","relation":"dinner guest","note":"Attends private dinners with the Emperor and voices genuine concern for his safety amid recent violence","best":"Being invited to dine privately with the Emperor","worst":"His dismissive response to her worried questions about assassination attempts"},"Vittoria Vici":{"aff":40,"type":"platonic","relation":"social acquaintance","note":"Former social connection whose murder at her wedding deeply troubled her","worst":"Learning of Vittoria''s murder"}}')
ON CONFLICT (npc_name) DO UPDATE
