INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nocturnal', '{"Nightingales":{"aff":60,"type":"servant","relation":"sworn protectors","note":"Agents who serve in both life and death in exchange for luck and power","best":"Faithful guardians maintaining the Twilight Sepulcher through ages","worst":"Mercer Frey''s betrayal and theft of the Skeleton Key"},"Thieves Guild":{"aff":50,"type":"patron","relation":"patron deity","note":"Influences their luck and success from the Twilight Sepulcher","best":"Guild flourishing under her subtle favor","worst":"Guild''s decline after the Skeleton Key was stolen"},"Karliah":{"aff":70,"type":"servant","relation":"loyal Nightingale","note":"Restored Nocturnal''s influence by recruiting new Nightingales after failure","best":"Karliah bringing new servants to restore the Oath","worst":"Karliah''s failure to prevent the Skeleton Key''s theft"},"Gallus Desidenius":{"aff":65,"type":"servant","relation":"faithful Nightingale","note":"Served faithfully as Nightingale until his murder by Mercer Frey","best":"Lifelong faithful service as a Nightingale guardian"},"Mercer Frey":{"aff":-90,"type":"betrayed","relation":"traitorous Nightingale","note":"Stole the Skeleton Key and broke his oath, severing Nocturnal''s influence over the Guild","worst":"Stole the Skeleton Key and defiled the Twilight Sepulcher"},"Brynjolf":{"aff":40,"type":"servant","relation":"new Nightingale","note":"Recently inducted as a Nightingale to serve in life and death","best":"Accepted the Nightingale Oath willingly"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('northwatch_guard', '{"Thalmor Leadership":{"aff":75,"type":"fanatical","relation":"commanding organization","note":"Unwavering loyalty born from lifelong indoctrination into Altmer supremacy ideology"},"Fellow Northwatch Guards":{"aff":35,"type":"professional","relation":"colleagues","note":"Professional working relationship based on shared duty and protocol adherence"},"Imperial Legion":{"aff":-5,"type":"suspicious","relation":"reluctant authority","note":"Recognizes their authority only when presented with proper documentation like a decree from General Tullius","worst":"Forced to yield to Imperial paperwork releasing a prisoner"},"Prisoners":{"aff":-75,"type":"contempt","relation":"warden","note":"Views them as mere objects of Thalmor interest, entirely beneath his concern"},"Local Nords":{"aff":-65,"type":"contempt","relation":"racial inferiors","note":"Holds particular disdain for Nords who question Thalmor authority or interfere with operations"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('northwatch_interrogator', '{"Thalmor":{"aff":90,"type":"fanatical","relation":"servant","note":"Views his interrogation work as sacred duty to the Thalmor cause"},"Elenwen":{"aff":65,"type":"professional","relation":"subordinate","note":"Reports significant findings to the First Emissary"},"Northwatch Guards":{"aff":35,"type":"professional","relation":"colleagues","note":"Professional relationships through mutual dedication to the cause"},"Prisoners":{"aff":-85,"type":"contempt","relation":"interrogator","note":"Views them as lesser beings worthy only of suffering until broken","worst":"Desiccated remains on torture tables attest to his brutal methods"}}')
ON CONFLICT (npc_name) DO UPDATE
