INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('northwatch_prisoner', '{"Thalmor":{"aff":-95,"type":"enemy","relation":"captors","note":"Cruel jailers who subject the prisoner to brutal interrogations and confinement","worst":"Extended torture sessions in the Northwatch interrogation chamber"},"Thorald Gray-Mane":{"aff":45,"type":"platonic","relation":"fellow prisoner","note":"Shared captivity confirms the political nature of their imprisonment","best":"Silent solidarity enduring Thalmor captivity together"},"Fellow Prisoners":{"aff":30,"type":"platonic","relation":"cell mates","note":"Shared suffering creates a quiet bond though interaction is severely limited"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('noster_eagle-eye', '{"Imperial Legion":{"aff":-65,"type":"betrayed","relation":"former comrades","note":"Served with distinction but was abandoned wounded at Anvil","worst":"Left for dead on the battlefield at Anvil"},"Aldmeri Dominion":{"aff":-85,"type":"enemy","relation":"wartime enemy","note":"Fought against them at Anvil where he lost his eye","worst":"Struck down during the Battle of Anvil"},"Angeline Morrard":{"aff":35,"type":"grateful","relation":"kind shopkeeper","note":"Allows him to beg near her shop during late hours","best":"Given a place to beg outside Angeline''s Aromatics"},"General Tullius":{"aff":-30,"type":"contempt","relation":"symbol of betrayal","note":"Represents the military structure that defined and then abandoned him"},"Solitude Guards":{"aff":10,"type":"neutral","relation":"local guards","note":"Maintain respectful distance due to his veteran status"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('novice_conjurer', '{"Fellow Conjurers":{"aff":55,"type":"platonic","relation":"fellow practitioners","note":"Found kinship among this loose association after rejection from formal institutions","best":"Accepted into the group despite lacking formal training"},"College of Winterhold":{"aff":-35,"type":"estranged","relation":"rejected applicant","note":"Denied entry due to insufficient aptitude; harbors mild resentment","worst":"Rejected and dismissed as lacking magical potential"},"Local Villagers":{"aff":-20,"type":"suspicious","relation":"wary neighbors","note":"Mutual distrust; villagers fear their conjuration practices"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('novice_fire_mage', '{"Fellow Warlocks":{"aff":-15,"type":"rival","relation":"coven members","note":"Competitive relationships marked by constant attempts to prove superiority","worst":"Humiliated when a rival''s spell outperformed theirs"},"College of Winterhold":{"aff":-70,"type":"estranged","relation":"former school","note":"Left in bitter frustration over the institution''s cautious approach to destructive magic","worst":"Teachers refused to teach advanced fire spells"},"Local Settlements":{"aff":-85,"type":"contempt","relation":"raiding targets","note":"Viewed as sources of supplies and potential victims to terrorize"},"Senior Fire Mages":{"aff":40,"type":"admirer","relation":"aspirational figures","note":"Looked up to with a mixture of respect and envy","best":"Witnessed a master''s devastating fire magic firsthand"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('novice_ice_mage', '{"Warlock Coven":{"aff":35,"type":"professional","relation":"coven member","note":"Found acceptance among outcast warlocks after College rejection, trades loyalty for frost magic training","best":"welcomed into the coven when no one else would have them"},"College of Winterhold":{"aff":-65,"type":"estranged","relation":"rejected applicant","note":"Denied admission due to insufficient aptitude; bitterness has curdled into resentment and hostility","worst":"turned away from the College gates as lacking magical potential"},"Senior Ice Mages":{"aff":55,"type":"mentor","relation":"aspiring student","note":"Idolizes advanced frost mages and hungers for their recognition and teachings","best":"first successful Ice Spike cast under a senior mage''s guidance"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('novice_necromancer', '{"College of Winterhold":{"aff":-55,"type":"estranged","relation":"former institution","note":"Expelled for conducting unauthorized necromantic experiments on deceased animals","worst":"Caught and expelled for forbidden research"},"Local Bandits":{"aff":15,"type":"transactional","relation":"corpse suppliers","note":"Occasionally provide fresh bodies for necromantic study"},"Fellow Necromancers":{"aff":25,"type":"professional","relation":"cautious allies","note":"Share pursuit of dark knowledge but maintain wary distance"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"hunters","note":"Seek to destroy all practitioners of necromancy","worst":"Constant threat of being hunted and killed for practicing the dark arts"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('novice_storm_mage', '{"College of Winterhold":{"aff":-75,"type":"enemy","relation":"former institution","note":"Bitterly seeks revenge after expulsion for reckless lightning experiments","worst":"Dismissed for endangering fellow apprentices with uncontrolled spells"},"Fellow Warlocks":{"aff":35,"type":"rival","relation":"coven peers","note":"Found kinship among outcast mages but competes for standing within the coven","best":"Accepted into the coven after College rejection"},"Storm Atronachs":{"aff":60,"type":"curious","relation":"aspirational mentors","note":"Views these beings as potential teachers and the purest expression of storm power"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nura_snow-shod', '{"Vulwulf Snow-Shod":{"aff":85,"type":"romantic","relation":"husband","note":"Beloved husband who shares her anti-Imperial sentiments and grief over Lilija","best":"Daily breakfast together, united in faith and fury"},"Lilija Snow-Shod":{"aff":95,"type":"familial","relation":"deceased daughter","note":"Trained her as healer and priestess; her death fuels Nura''s devotion and hatred of the Empire","worst":"The Empire burned all the dead; we never recovered her body"},"Asgeir Snow-Shod":{"aff":75,"type":"familial","relation":"son","note":"Defends him against Vulwulf''s criticism; conflicted about his Imperial marriage","best":"Telling herself she''s gaining a daughter, not losing a son"},"Unmid Snow-Shod":{"aff":70,"type":"familial","relation":"son"},"Maven Black-Briar":{"aff":15,"type":"suspicious","relation":"business partner of son","note":"Tolerates the connection for Asgeir''s sake despite Vulwulf''s contempt"},"Vittoria Vici":{"aff":20,"type":"estranged","relation":"daughter-in-law","note":"Uncomfortable with Imperial bride but never wished her dead","worst":"By Ysmir, this is horrible! I never wanted the girl dead, I swear!"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('nurelion', '{"Quintus Navale":{"aff":15,"type":"mentor","relation":"apprentice","note":"Treats him harshly and dismisses him as useless, yet relies on him completely and chose him as successor","best":"Chose him to carry on his life''s work at The White Phial","worst":"Called him a doting busybody and useless while refusing his help during a violent coughing fit"},"Local Nords":{"aff":-20,"type":"contempt","relation":"neighbors","note":"Mutual distrust born of racial prejudice and his own antisocial, condescending nature"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('octieve_san', '{"Evette San":{"aff":20,"type":"familial","relation":"daughter","note":"Strained by his drinking and dependency, but bound by duty and underlying care","best":"Acknowledges she''s the brains of the family and keeps him fed","worst":"Demands mead when she barely earns enough for them to eat"},"Irnskar Ironhand":{"aff":-40,"type":"contempt","relation":"creditor","note":"Gambling debts cause him ongoing stress and shame","worst":"In debt up to his eyes from too many drinking games and bets"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('odahviing', '{"Alduin":{"aff":-55,"type":"estranged","relation":"former master","note":"Once a trusted lieutenant who came to question Alduin''s strength and abandoned his cause","worst":"Witnessed Alduin flee from the Dragonborn, proving his doubts about the World-Eater''s power"},"The Last Dragonborn":{"aff":72,"type":"servant","relation":"sworn ally","note":"Chose to follow after recognizing the Dragonborn''s superior Thu''um and strength","best":"Allowed himself to be captured at Dragonsreach to test the Dragonborn, finding a worthy master"},"Paarthurnax":{"aff":35,"type":"platonic","relation":"fellow defector","note":"Both broke from Alduin''s leadership, sharing an understanding of choosing a new path"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('odar', '{"Sybille Stentor":{"aff":-55,"type":"fearful","relation":"court wizard","note":"Deeply unsettled by her unnatural habits and the dread she inspires among staff","worst":"Never seen her eat a thingâ€”finds it unnatural"},"Jarl Elisif":{"aff":20,"type":"professional","relation":"employer","note":"Serves her dutifully but privately dismisses her as a powerless figurehead","worst":"Openly calls her a puppet"},"General Tullius":{"aff":35,"type":"neutral","relation":"true power in Solitude","note":"Recognizes and respects that he actually holds authority in the city"},"Jorn":{"aff":65,"type":"platonic","relation":"bard friend","note":"Bonded over shared appreciation of cooking as art","best":"Jorn declared his cooking better than most songs"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('odfel', '{"Grogmar gro-Burzag":{"aff":-35,"type":"rival","relation":"housemate","note":"Constantly argues over cleanliness and domestic order","best":"Bet Grogmar he could out-mine him and still keep a clean house","worst":"Enduring Grogmar''s squalid half of their shared dwelling"},"Grelka":{"aff":55,"type":"crush","relation":"unrequited love interest","note":"Persistently pursues Grelka despite her clear rejections","best":"Working up courage to ask her for a walk","worst":"Being told he cares more about himself than anyone else"},"Filnjar":{"aff":-5,"type":"professional","relation":"town mediator","note":"Filnjar mediates disputes between Odfel and Grogmar with little patience for complaints","worst":"Being told to quit bellyaching when pleading for a new house"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('odvan', '{"Bothela":{"aff":75,"type":"familial","relation":"grandmother or aunt","note":"He worries about her constantly while imprisoned and wonders if she''s sick with worry","best":"Sleeping off mead at her house","worst":"Being arrested while under her roof"},"Duach":{"aff":45,"type":"platonic","relation":"fellow prisoner","note":"Conspires with him about escape plans and attacking guards","best":"Discussing ways to fight back against the guards"},"Forsworn":{"aff":35,"type":"protective","relation":"adopted brothers-in-arms","note":"Joined them for survival after imprisonment, not out of prior ideology","best":"Finding protection and belonging in Cidhna Mine"},"Markarth Guards":{"aff":-75,"type":"enemy","relation":"jailers","note":"Framed him for murder and wrongfully imprisoned him","worst":"Being arrested for a murder he didn''t commit while sleeping off mead"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('oengul_war-anvil', '{"Hermir Strong-Heart":{"aff":72,"type":"mentor","relation":"apprentice","note":"Stern but caring mentor who stayed in Windhelm after Ulfric''s fall specifically to finish training her","best":"She said she only wanted to learn from the best smith in Skyrim"},"Ulfric Stormcloak":{"aff":88,"type":"fanatical","relation":"jarl and cause leader","note":"Serves with unwavering loyalty, views his smithing as a labor of honor for Ulfric''s glory","best":"To bring Ulfric his rightful glory, I would hammer a thousand shields","worst":"Can''t believe Ulfric''s gone"},"Eorlund Gray-Mane":{"aff":25,"type":"rival","relation":"rival smith","note":"Respects his skill but is consumed by the need to prove himself superior","best":"I respect Eorlund, but he has the good fortune to work the Skyforge","worst":"I couldn''t let her run off to that pretender Eorlund Gray-Mane"},"Imperial Legion":{"aff":-72,"type":"enemy","relation":"occupying force","note":"Views them as enemies of true Nordic traditions and despises their rule","worst":"Wasn''t sure I could stomach having some Imperial tell me how to live my life"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('oglub', '{"Ghorbash the Iron Hand":{"aff":65,"type":"familial","relation":"younger brother","note":"Respects his enduring spirit but wishes he would accept his age and place","best":"Acknowledging Ghorbash''s stronger swordarm, believing he could challenge for chief","worst":"Watching his brother refuse to settle down as he himself has done"},"Chief Burguk":{"aff":55,"type":"servant","relation":"chief","note":"Serves with unwavering loyalty, having accepted Burguk''s authority without challenge","best":"Trusted with the key to Burguk''s Longhouse"},"Ghak":{"aff":30,"type":"platonic","relation":"fellow miner","note":"Shares daily labor in the orichalcum mines"},"Mahk":{"aff":30,"type":"platonic","relation":"fellow miner","note":"Shares daily labor in the orichalcum mines"},"Dulug":{"aff":30,"type":"platonic","relation":"fellow miner","note":"Shares daily labor in the orichalcum mines"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ogmund', '{"Kleppr":{"aff":35,"type":"professional","relation":"innkeeper and host","note":"Friendly working arrangement at the Silver-Blood Inn with mutual respect","best":"Kleppr hails him as the True Skald of the Reach before patrons"},"Ondolemar":{"aff":-85,"type":"enemy","relation":"Thalmor persecutor","note":"Ondolemar targeted Ogmund for his Talos worship, leading to his public humiliation","worst":"Dragged to the stocks in Understone Keep for worshipping Talos"},"Bards College":{"aff":55,"type":"mentor","relation":"esteemed alumnus and living curriculum","note":"His compositions and techniques are still taught to students as standard material"},"Thalmor":{"aff":-90,"type":"nemesis","relation":"persecutors","note":"Deeply resents the Thalmor for banning Talos worship and hunting devotees","worst":"Their inquisition forced him to hide his faith or face the stocks"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ogol', '{"Chief Gularzob":{"aff":55,"type":"professional","relation":"chief","note":"Serves loyally despite being Gularzob''s elder and initial surprise at his ascension","best":"Accepted his new chief with humility for the tribe''s sake","worst":"Caught off guard by the younger Orc''s unexpected rise to leadership"},"Largashbur Tribe":{"aff":75,"type":"familial","relation":"tribe member","note":"Considers all tribe members blood family and defends them steadfastly","best":"Remained steadfast defending Largashbur through Malacath''s curse"},"Malacath":{"aff":80,"type":"fanatical","relation":"devotee","note":"Devoted follower who endured the deity''s curse without losing faith"},"Yamarz":{"aff":20,"type":"suspicious","relation":"former chief","note":"Yamarz''s failure and death brought the curse''s full weight upon the tribe","worst":"Witnessed his former chief''s downfall and the tribe''s suffering under the curse"},"The Dragonborn":{"aff":50,"type":"grateful","relation":"ally","note":"Initially hostile but grew respectful after the curse was lifted","best":"Lifted Malacath''s curse and saved the tribe","worst":"Dismissed as an interfering outsider before proving worth"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('olaf_one-eye', '{"Numinex":{"aff":-90,"type":"nemesis","relation":"captured dragon","note":"Defeating and imprisoning Numinex became the cornerstone of his legend, though bards later claimed the tale was fabricated","best":"Imprisoned the dragon within Dragonsreach as a trophy of victory","worst":"Bards alleged the victory was a fraud invented to secure the throne"},"Svaknir":{"aff":15,"type":"rival","relation":"honest enemy turned respected peer","note":"Imprisoned the bard and destroyed his scathing verse, but in Sovngarde came to respect him as an honest opponent","best":"Acknowledged Svaknir as an honest enemy who earned his respect in the afterlife","worst":"Imprisoned Svaknir and burned every copy of his accusatory verse"},"Citizens of Solitude":{"aff":-40,"type":"contempt","relation":"ritual detractors","note":"They ritually burn his effigy each year in the Burning of King Olaf festival, remembering him as a tyrant and fraud","worst":"His effigy is burned annually in Solitude as mockery of his legacy"},"Last Dragonborn":{"aff":55,"type":"protective","relation":"ally against Alduin","note":"Aids the Dragonborn in Sovngarde against the World-Eater, grateful if Svaknir was freed from the soul-snaring mist","best":"Fought alongside the Dragonborn to defeat Alduin and save Svaknir''s soul"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('olava_the_feeble', '{"Dark Brotherhood":{"aff":60,"type":"professional","relation":"seer and mystic advisor","note":"Maintains secretive connection as their prophetic advisor, invokes Sithis and recognizes their tokens","best":"Provided prophetic guidance leading Brotherhood members to their destinies","worst":"Carries the burden of dark visions and the weight of their secrets"},"Gabriella":{"aff":45,"type":"professional","relation":"Brotherhood contact","note":"Directly recognized through her token, suggesting established prior dealings"},"Ahkari":{"aff":25,"type":"transactional","relation":"smuggling associate","note":"Allegedly in league with Khajiit caravans, using her seer status as cover"},"Whiterun Guards":{"aff":10,"type":"neutral","relation":"local authorities","note":"Maintain respectful distance, viewing her with fear and reverence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('old_orc', '{"Malacath":{"aff":85,"type":"fanatical","relation":"deity and spiritual guide","note":"Received a vision from Malacath promising a glorious death in battle","best":"Malacath granted him a vision of his destined end"},"Former Stronghold Members":{"aff":25,"type":"estranged","relation":"former kin","note":"Left his stronghold behind to seek his final battle alone","best":"Earned respect among his kin as a warrior","worst":"Never achieved the position of chief"},"Player":{"aff":15,"type":"curious","relation":"potential deliverer of good death","note":"Sees the player as a possible worthy opponent for his final battle"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('olda', '{"Horgeir":{"aff":-65,"type":"estranged","relation":"husband","note":"Marriage strained to breaking point by his alcoholism and broken promises","worst":"Discovered he stashed mead in a cave after swearing on his ancestors to quit"},"Lodvar":{"aff":65,"type":"romantic","relation":"brother-in-law","note":"Developed romantic feelings; affair known throughout town but hidden from Horgeir","best":"Accepted his invitation for a mountain walk with wine and a blanket"},"Dragon Bridge Guards":{"aff":-35,"type":"suspicious","relation":"occupying force","note":"Fears they will seize the mill and eventually their homes in the name of the war effort"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('olfina_gray-mane', '{"Jon Battle-Born":{"aff":85,"type":"romantic","relation":"secret lover","note":"Forbidden romance across the Gray-Mane/Battle-Born feud","best":"Cooking him special breakfasts with his favorite sausages","worst":"Hiding their love from both families"},"Vignar Gray-Mane":{"aff":75,"type":"protective","relation":"uncle","note":"Serves as his housecarl if Stormcloaks take Whiterun","best":"Proudly protecting him as Jarl","worst":"Fleeing from combat when he needed her most"},"Eorlund Gray-Mane":{"aff":70,"type":"familial","relation":"father","note":"Proud of his Skyforge steel craftsmanship and family legacy"},"Thorald Gray-Mane":{"aff":65,"type":"familial","relation":"missing brother","note":"Misses him but believes he knew what he was getting into","worst":"His disappearance and presumed death in the war"},"Battle-Born Clan":{"aff":-40,"type":"rival","relation":"rival family","note":"Bitter feud complicated by her secret love for Jon"},"Hulda":{"aff":35,"type":"professional","relation":"employer","note":"Works as barmaid at the Bannered Mare"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('olfrid_battle-born', '{"Idolaf Battle-Born":{"aff":85,"type":"familial","relation":"son","note":"Fiercely proud of Idolaf''s service fighting for the Empire","best":"Boasting that his son carries the Battle-Born name into battle for Skyrim"},"Jon Battle-Born":{"aff":65,"type":"familial","relation":"son","note":"Would be furious if he learned of Jon''s secret romance with Olfina Gray-Mane","worst":"Discovering his son courting a Gray-Mane would be an unforgivable betrayal"},"Bergritte Battle-Born":{"aff":70,"type":"familial","relation":"wife"},"Eorlund Gray-Mane":{"aff":-65,"type":"estranged","relation":"former friend","note":"Friendship ended when Eorlund turned his back on the Emperor","best":"Once shared a bond before the Civil War divided them","worst":"Eorlund chose Stormcloak allegiance over their friendship"},"Vignar Gray-Mane":{"aff":-70,"type":"rival","relation":"rival patriarch","note":"Blames Vignar for denying justice when Stormcloaks robbed him twice","worst":"Stormcloaks threatened to exile his entire family as Imperial spies"},"Maven Black-Briar":{"aff":45,"type":"professional","relation":"business associate","note":"Connected through shared Thieves Guild dealings"},"Imperial Legion":{"aff":85,"type":"fanatical","relation":"staunch supporter","note":"Open and unwavering loyalist despite danger from Stormcloak rule","best":"Proudly declaring his loyalty even under Stormcloak occupation"},"Thieves Guild":{"aff":55,"type":"grateful","relation":"client","note":"Helped spread their influence in Whiterun after they saved a friend","best":"The Guild came through when he needed a convicted friend freed"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('olur', '{"Chief Larak":{"aff":55,"type":"familial","relation":"father and chief","note":"Respects his father''s authority and Legion past, though their exchanges are formal","best":"Father praised his smithing and offered to share Legion techniques someday","worst":"Formality of calling him ''my chief'' suggests emotional distance"},"Shuftharz":{"aff":80,"type":"familial","relation":"mother and forge mentor","note":"Works alongside her daily at the forge and seeks to please her","best":"Learning traditional Orcish smithing at her side each day"},"Gul":{"aff":40,"type":"platonic","relation":"fellow miner","note":"Shares night shifts and meals in the mine","best":"Nightly meals together underground"},"Ghamorz":{"aff":35,"type":"platonic","relation":"mining colleague","note":"Occasional meal companion during long night shifts"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('omluag', '{"Hathrasil":{"aff":35,"type":"platonic","relation":"roommate and coworker","note":"Shares quarters and labor; bristles at warnings but bonds over shared hardship","best":"Hathrasil expressed concern after Mulush nearly broke his arm"},"Mulush":{"aff":-70,"type":"enemy","relation":"overseer","note":"Abusive Orc boss who threatens violence and denies rest","worst":"Mulush threatened to take spilled silver out of his hide and nearly broke his arm"},"Silver-Blood Family":{"aff":-75,"type":"contempt","relation":"oppressors","note":"Secretly despises the family exploiting Reach workers through the smelter"},"Forsworn":{"aff":45,"type":"admirer","relation":"sympathized cause","note":"Quietly supports their resistance against Nord rule but never joined"},"Weylin":{"aff":25,"type":"admirer","relation":"fellow Warrens resident","note":"Mourned him as an honest man lost to the madness"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ondolemar', '{"Jarl Igmund":{"aff":15,"type":"professional","relation":"reluctant host","note":"Mutual necessity binds them; Igmund''s hesitation to arrest Ogmund frustrates Ondolemar"},"Ogmund":{"aff":-75,"type":"enemy","relation":"investigation target","note":"Suspected Talos worshipper Ondolemar is determined to expose and have arrested","worst":"The Jarl shields this heretic from justice"},"Elenwen":{"aff":60,"type":"professional","relation":"ambassador and superior","note":"Regular correspondence with the Thalmor Ambassador; attends her party at the Embassy"},"Thalmor Soldiers":{"aff":35,"type":"professional","relation":"subordinate guards","note":"Two soldiers under his command who accompany him constantly"},"Galmar":{"aff":-90,"type":"nemesis","relation":"executioner","note":"Stormcloak who orders him to his knees and kills him when the city falls","worst":"On your knees, Elf!"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('onmund', '{"Family":{"aff":-55,"type":"estranged","relation":"family","note":"Left them behind to pursue magic against their strong disapproval","worst":"They called coming to the College a death sentence or worse"},"Tolfdir":{"aff":65,"type":"mentor","relation":"mentor","note":"Respected teacher whose wisdom Onmund trusts deeply","best":"Tolfdir''s warnings about magic''s dangers proved right"},"Enthir":{"aff":-25,"type":"suspicious","relation":"shady dealer","note":"Regrets trading away his cherished family amulet to him","worst":"Traded ancestral amulet for magical knowledge and wants it back"},"Brelyna":{"aff":45,"type":"platonic","relation":"fellow apprentice","note":"Friendly academic rival among the new apprentices"},"J''zargo":{"aff":35,"type":"platonic","relation":"fellow apprentice","note":"Friendly academic rival with competitive streak"},"Ancano":{"aff":-50,"type":"suspicious","relation":"Thalmor advisor","note":"Deeply distrusts his presence at the College and avoids him","worst":"No one believes Ancano is just an advisor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orc_hunter', '{"Fellow Orc Hunters":{"aff":60,"type":"platonic","relation":"hunting band member","note":"Fierce loyalty within the loose collective, though quick to turn violent if accidentally struck","best":"Sharing a successful hunt and dividing the spoils fairly","worst":"Turning on each other over an accidental blow during a hunt"},"Traveling Merchants":{"aff":25,"type":"transactional","relation":"trading partner","note":"Regular exchange of meat and pelts for gold and supplies"},"Local Nordic Hunters":{"aff":-20,"type":"rival","relation":"territorial rival","note":"Occasional conflict over hunting grounds and game rights"},"Original Stronghold":{"aff":20,"type":"estranged","relation":"former home","note":"Left the rigid hierarchy but maintains Orcish cultural respect","best":"Proving Orcs can thrive outside the stronghold system","worst":"Choosing exile over submission to stronghold hierarchy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orchendor', '{"Peryite":{"aff":-85,"type":"nemesis","relation":"former master","note":"Betrayed Peryite after prolonged exposure to plague and Dwemer ruins twisted his mind into megalomania","worst":"Corrupted the Afflicted into his personal army instead of shepherding them as tasked"},"The Afflicted":{"aff":60,"type":"protective","relation":"followers","note":"Commands the Afflicted as his personal army within Bthardamz Arcanex","best":"Established himself as their autonomous leader and protector"},"Kesh the Clean":{"aff":-25,"type":"estranged","relation":"former fellow servant","note":"Once fellow servants of Peryite, now divided by Orchendor''s apostasy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orcish_invader', '{"Fellow Orcish Warriors":{"aff":80,"type":"platonic","relation":"war brothers","note":"Led war party together in assault on Nightcaller Temple","best":"Fighting side by side to end their people''s torment"},"Vaermina Devotees":{"aff":-95,"type":"nemesis","relation":"tormentors","note":"Inflicted supernatural nightmares on Orcish people driving them to invade","worst":"Watching kin suffer sleep deprivation and mental anguish from the nightmares"},"Erandur":{"aff":-70,"type":"enemy","relation":"former cultist","note":"Viewed as enemy due to his past as a Vaermina devotee"},"Stronghold Clan":{"aff":85,"type":"familial","relation":"kin","note":"Community that suffered from Vaermina''s nightmares and motivated the invasion","best":"Swearing vengeance for their suffering"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orgnar', '{"Delphine":{"aff":60,"type":"professional","relation":"employer","note":"Gruff but loyal barkeeper who keeps her secrets without question; she ultimately leaves him the inn","best":"She entrusted him with ownership of the Sleeping Giant Inn before departing","worst":"Endless needling from Delphine over ale, potatoes, and sweeping"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('oriella', '{"Player":{"aff":45,"type":"professional","relation":"employer","note":"Hired through the steward to serve as resident bard at Heljarchen Hall","best":"Being welcomed as the household bard","worst":"Being dismissed from service"},"Bards College":{"aff":60,"type":"professional","relation":"alma mater","note":"Graduated and maintains connections with fellow alumni"},"Heljarchen Hall Steward":{"aff":40,"type":"professional","relation":"colleague","note":"Professional relationship based on mutual respect"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orini_dral', '{"Sarthis Idren":{"aff":75,"type":"protective","relation":"employer","note":"Serves as his bodyguard with loyalty that exceeds mere employment","best":"Recruited by Sarthis based on his reputation for reliability and discretion"},"Riften Guards":{"aff":-35,"type":"suspicious","relation":"law enforcement","note":"Mutual distrust and occasional bribery","worst":"Constant tension and threat of raid on the operation"},"Thieves Guild":{"aff":-10,"type":"rival","relation":"territorial rivals","note":"Professional rivalry with grudging territorial respect"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orla', '{"Senna":{"aff":45,"type":"platonic","relation":"fellow priestess","note":"Shares daily temple duties and religious observations with Orla"},"Hamal":{"aff":75,"type":"mentor","relation":"temple mother","note":"Orla deeply respects and obeys Hamal as the Mother of the Temple"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orthjolf', '{"Vingalmo":{"aff":-80,"type":"rival","relation":"bitter rival for clan leadership","note":"Obsessively distrusts Vingalmo and warns others against his schemes; their feud defines Volkihar court politics","worst":"Publicly mocked and outmaneuvered in witty banter by the elf he despises"},"Lord Harkon":{"aff":40,"type":"professional","relation":"liege and aspiring successor","note":"Serves as loyal lieutenant while secretly coveting the throne for himself"},"Stalf":{"aff":55,"type":"professional","relation":"loyal subordinate","note":"Trusted agent who carries out Orthjolf''s schemes and errands within the clan"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orthorn', '{"College of Winterhold":{"aff":45,"type":"betrayed","relation":"former institution","note":"Stole books from the library but desperately seeks readmission and redemption","worst":"Betrayed the College by stealing valuable books"},"Urag gro-Shub":{"aff":-15,"type":"betrayed","relation":"wronged librarian","note":"Stole books from his library and deeply regrets it","worst":"Took books entrusted to Urag''s care"},"The Caller":{"aff":-75,"type":"betrayed","relation":"former ally turned captor","note":"Joined her group seeking acceptance but was imprisoned for magical experiments","worst":"Locked him in a cage to use as a test subject"},"Savos Aren":{"aff":55,"type":"admirer","relation":"former arch-mage","note":"Hoped Aren cared enough to send someone to rescue him","best":"Clung to hope that the Arch-Mage would not abandon him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('orthus_endario', '{"Adelaisa Vendicci":{"aff":45,"type":"professional","relation":"superior","note":"His company overseer whose trust he works to maintain despite deteriorating operations"},"Suvaris Atheron":{"aff":-40,"type":"rival","relation":"rival shipping clerk","note":"Suspects her logbook contains proof of Shatter-Shield collusion with pirates","worst":"She facilitates shipments while his own company''s vessels are raided"},"Shatter-Shield Clan":{"aff":-60,"type":"suspicious","relation":"suspected conspirators","note":"Believes they are in league with the Blood Horkers to monopolize Windhelm docks","worst":"Their ships remain untouched while East Empire vessels are systematically targeted"},"Blood Horkers":{"aff":-75,"type":"enemy","relation":"pirate threat","note":"Clever and shrewd pirates who have crippled East Empire shipping from Hammerfell to Vvardenfell","worst":"Their raids forced the Company to stop docking ships in Windhelm entirely"},"East Empire Company":{"aff":70,"type":"professional","relation":"employer","note":"Dedicated career bureaucrat determined to restore company operations despite impossible odds","best":"Earned the Windhelm office manager posting through years of loyal service"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('oslaf', '{"Finna":{"aff":65,"type":"romantic","relation":"wife","note":"Practical but caring marriage built on shared labor and Skaal traditions","best":"Banter over crops and meals shows comfortable companionship"},"Aeta":{"aff":80,"type":"protective","relation":"daughter","note":"Stern but deeply loving father who shields her from premature danger","best":"Called her little cub and acknowledged her brave she-wolf heart"},"Yrsa":{"aff":40,"type":"platonic","relation":"village friend","note":"Friendly banter over her snowberry pie","best":"Teased her about making more pie and ate a whole one himself"},"Storn":{"aff":55,"type":"grateful","relation":"village elder","note":"Respected the old shaman who protected the Skaal","best":"Paid respects at his death, wishing him peace in the next life","worst":"Watched him die after the Dragonborn brought danger to the village"},"Miraak":{"aff":-90,"type":"enemy","relation":"former enslaver","note":"Was forced to labor under mind control at the Temple of Miraak","worst":"Enslaved and forced to work at the temple against his will"},"Last Dragonborn":{"aff":10,"type":"suspicious","relation":"outsider","note":"Acknowledges others call them friend but still sees an outsider","best":"Was freed from Miraak''s control by them","worst":"Blames them for bringing danger that led to Storn''s death"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('otar_the_mad', '{"Torsten":{"aff":5,"type":"servant","relation":"bound guardian","note":"Eternally bound to guard his tomb with a skull key"},"Saerek":{"aff":5,"type":"servant","relation":"bound guardian","note":"Eternally bound to guard his tomb with a skull key"},"Dragons":{"aff":95,"type":"fanatical","relation":"ancient masters","note":"Served with absolute devotion as a high priest of the Dragon Cult"},"Dragon Cult":{"aff":85,"type":"fanatical","relation":"zealous servant","note":"High-ranking member who embodied the cult''s worst tyrannies"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('paarthurnax', '{"Alduin":{"aff":-70,"type":"nemesis","relation":"brother and former master","note":"Once Alduin''s most trusted general, now his adversary after betraying him to aid mortals","worst":"The schism that turned him against his own brother during the Dragon War"},"Greybeards":{"aff":85,"type":"mentor","relation":"grandmaster","note":"Founded and guides the order in the Way of the Voice across millennia","best":"Thousands of years of patient teaching and spiritual guidance"},"Last Dragonborn":{"aff":65,"type":"mentor","relation":"pupil","note":"Sees the Dragonborn as the fulfillment of prophecy and key to defeating Alduin","best":"Revealing the Dragonrend shout through the Time Wound"},"Blades":{"aff":-75,"type":"enemy","relation":"ancient enemies","note":"They demand his death for atrocities committed during the Dragon War","worst":"Their ultimatum forcing the Dragonborn to choose between loyalty to them or his life"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pactur', '{"Sorli the Builder":{"aff":80,"type":"romantic","relation":"wife","note":"His life revolves around her; he does the work she doesn''t care to and feeds her ambitions","best":"Supporting Sorli''s rise to Jarl of Morthal"},"Sirgar":{"aff":60,"type":"familial","relation":"son","note":"Trusts him to oversee the mine but worries about leaving him in charge","best":"Entrusting Sirgar with running Stonehills","worst":"Fearing leaving Sirgar in charge may have been a mistake"},"Bryling":{"aff":5,"type":"professional","relation":"employer","note":"Tense dynamic; she owns the mine and comes down hard on them for late shipments","worst":"Bryling breathing fire over missed shipments"},"Gestur Rockbreaker":{"aff":40,"type":"professional","relation":"employee","note":"Trusted mine supervisor who actually runs the workers day-to-day"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pale_hold_guard', '{"Jarl Skald the Elder":{"aff":55,"type":"professional","relation":"liege lord","note":"Serves loyally as a hold guard under the Jarl''s authority"},"Vantus Loreius":{"aff":35,"type":"protective","relation":"citizen under his patrol","note":"Regularly checks on the farmer during route patrols","worst":"Discovered Loreius and his wife slaughtered after Cicero''s arrest"},"Cicero":{"aff":-55,"type":"suspicious","relation":"suspected criminal","note":"Views him as a crazy man hiding something in the coffin","worst":"Arrested him on fabricated charges, unwittingly enabling murder"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('palevius_lex', '{"Miraak":{"aff":-85,"type":"enemy","relation":"enslaver","note":"Fell under Miraak''s spell while anchored off Solstheim''s coast","worst":"Losing his free will and being forced to work endlessly at the Water Stone"},"Liesl":{"aff":70,"type":"professional","relation":"trusted navigator","note":"Trusted crew member and navigator of his vessel","best":"Relying on her navigation through the treacherous Sea of Ghosts"},"Hjalfar":{"aff":65,"type":"professional","relation":"loyal sailor","note":"Long-serving crew member who has remained devoted for many years"},"Benkum":{"aff":55,"type":"professional","relation":"crew member","note":"Newest crew member but equally devoted to their captain"},"East Empire Company":{"aff":35,"type":"transactional","relation":"business contact","note":"Regular trading partners on the Windhelm-Solstheim route"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pantea_ateia', '{"Aia Arria":{"aff":65,"type":"mentor","relation":"favored student","note":"Pantea''s star pupil whom she considers the only student with potential for greatness.","best":"Praised Aia''s dedication and performance, telling her she would one day make an adequate singer."},"Larina":{"aff":-85,"type":"betrayed","relation":"thief","note":"Former student who stole Pantea''s ancestral flute and sold it to a necromancer.","worst":"Discovered Larina stole her flute passed down for seventeen generations and ransomed it to a necromancer."},"Illdi":{"aff":-35,"type":"dismissive","relation":"dismissed student","note":"Student Pantea openly considers wretched and untalented, using her as an example of wasted time."},"Viarmo":{"aff":30,"type":"professional","relation":"headmaster","note":"Colleague who challenges her favoritism toward students, creating mild professional tension."},"Elisif the Fair":{"aff":35,"type":"professional","relation":"patron","note":"Regular performer at the Blue Palace with a respected professional connection."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('paratus_decimius', '{"Gavros Plinius":{"aff":25,"type":"professional","relation":"research colleague","note":"Disputed credit for the Oculory project but relied on him completely","best":"Collaborated on the focusing array concept at Mzulft","worst":"Gavros took credit for Paratus''s idea before dying with the crystal"},"College of Winterhold":{"aff":-40,"type":"rival","relation":"rival institution","note":"Deeply disdainful and suspicious of the College''s motives","worst":"Arch-Mage Savos refused the Synod an audience when they sought help"},"Synod Council":{"aff":55,"type":"professional","relation":"superiors","note":"Seeks recognition and advancement within the Synod hierarchy","best":"Conceived the Mzulft expedition to prove the Synod''s magical supremacy"},"Falmer":{"aff":-80,"type":"enemy","relation":"hostile creatures","note":"Blames them for the expedition''s devastation and Gavros''s death","worst":"Killed Gavros and drove the Mzulft expedition to the brink of failure"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pavo_attius', '{"Gat gro-Shargakh":{"aff":75,"type":"platonic","relation":"fellow miner, survivor companion","note":"Escaped the Forsworn attack together; share deep mutual trust and concern for each other''s wellbeing","best":"Survived the Forsworn attack side by side at Kolskeggr","worst":"The night the Forsworn overran the mine and killed everyone else"},"Skaggi Scar-Face":{"aff":45,"type":"professional","relation":"refuge provider, mine boss","note":"Skaggi took Pavo and Gat in at Left Hand Mine after they fled Kolskeggr","best":"Offered shelter and work at Left Hand Mine after the attack"},"Forsworn":{"aff":-90,"type":"enemy","relation":"attackers, usurpers","note":"Slaughtered Pavo''s co-workers and seized his home and livelihood","worst":"The night raid that killed every other miner at Kolskeggr"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('peddler', '{"Forsworn":{"aff":-80,"type":"enemy","relation":"frequent attackers","note":"Hostile Reach natives who regularly ambush traveling merchants","worst":"Constantly attacked while traveling through the Reach"},"Bandits":{"aff":-75,"type":"enemy","relation":"constant threat","note":"Regular assailants on Skyrim''s roads","worst":"Frequently forced to fight for survival against bandit assaults"},"Khajiit Caravans":{"aff":35,"type":"transactional","relation":"trading partners","note":"Occasional trading partners and sources of road condition information"},"Other Peddlers":{"aff":30,"type":"professional","relation":"fellow merchants","note":"Loose network sharing intelligence on safe routes and dangers"},"Player":{"aff":45,"type":"grateful","relation":"rescuer","note":"Offers merchant services to those who save them from attackers","best":"Saved from certain death by a passing traveler"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pelagius_the_suspicious', '{"Sheogorath":{"aff":-70,"type":"fearful","relation":"captor","note":"Views the Daedric Prince as both captor and tormentor within the Mind of Madman realm.","worst":"Trapped as a permanent fixture in a mind controlled by the Madgod"},"Pelagius the Trusting":{"aff":-60,"type":"suspicious","relation":"fellow mental aspect","note":"Distrusts this opposing aspect as a dangerous naivety that invites betrayal."},"Pelagius the Confident":{"aff":-45,"type":"suspicious","relation":"fellow mental aspect","note":"Views the confidence aspect as foolish complacency in the face of countless threats."},"Pelagius the Coward":{"aff":-30,"type":"contempt","relation":"fellow mental aspect","note":"Dismisses the cowardly aspect''s fear as directionless while his own vigilance is purposeful."},"The Dragonborn":{"aff":-50,"type":"suspicious","relation":"intruder","note":"Regards the intruder in Pelagius''s mind as yet another potential threat to his safety.","worst":"An unknown outsider entering the mind uninvited"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pelagius_the_tormented', '{"Sheogorath":{"aff":-85,"type":"fearful","relation":"captor","note":"Trapped within the Daedric Prince''s realm of madness, perpetually tormented under his dominion.","worst":"Consigned to endless torment in Sheogorath''s twisted realm"},"Night Terrors":{"aff":-95,"type":"enemy","relation":"tormentors","note":"Manifestations of his deepest fears that endlessly assault him in his sleep.","worst":"Cannot find peace even in sleep, hunted by his own nightmares"},"Pelagius III":{"aff":40,"type":"familial","relation":"original self","note":"A fractured aspect of the Mad Emperor''s psyche, longing for wholeness and peace."},"Dragonborn":{"aff":60,"type":"grateful","relation":"liberator","note":"Potential savior who can destroy the night terrors and bring relief from endless suffering.","best":"Destroyed my night terrors and granted me peace at last"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('penitus_oculatus_agent', '{"Commander Maro":{"aff":80,"type":"professional","relation":"commanding officer","note":"Deeply respected superior; agents defend his honor even in private conversation","best":"Hearing him called the best the Penitus Oculatus ever produced","worst":"Watching him carry on after his son''s death and family''s ruin"},"Emperor Titus Mede II":{"aff":85,"type":"protective","relation":"sworn protector","note":"Ultimate duty is ensuring the Emperor''s absolute safety"},"Dark Brotherhood":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Greatest threat to the Emperor; assaulted their sanctuary and burned it to the ground","worst":"Failing to prevent the assassination of the Emperor''s decoy"},"Imperial Legion":{"aff":25,"type":"dismissive","relation":"allied force","note":"Viewed as lazy and useless; not trusted with the Emperor''s safety despite alliance","worst":"Legion''s inability to keep Stormcloaks in line undermining security"},"Local Guards":{"aff":15,"type":"transactional","relation":"local security","note":"Professional working relationship with strict operational independence maintained"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('perth', '{"Tuthul":{"aff":30,"type":"platonic","relation":"fellow miner and housemate","note":"Perth tolerates Tuthul''s cowardice but grows impatient with his constant fear of draugr","worst":"Tuthul''s endless worrying and talk of returning draugr tests his patience"},"Player":{"aff":65,"type":"grateful","relation":"mine savior and potential spouse","note":"Deeply grateful for clearing the draugr threat and open to marriage afterward","best":"Cleared Soljund''s Sinkhole of draugr when the Jarl''s regiment never came"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('petra', '{"Melka":{"aff":-75,"type":"rival","relation":"imprisoned predecessor","note":"Petra defeated Melka and claimed Blind Cliff Bastion, keeping her caged rather than killing her","best":"Overtaking the tower and caging her rival","worst":"Melka''s continued existence as a potential threat"},"Forsworn":{"aff":15,"type":"transactional","relation":"uneasy allies","note":"Mutual wariness tempered by her utility in creating Briarhearts for their camps"},"Reachmen":{"aff":-40,"type":"contempt","relation":"prey","note":"Viewed primarily as subjects for magical experiments and ritual sacrifices"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('phinis_gestor', '{"Falion":{"aff":45,"type":"mentor","relation":"former mentor","note":"Trained under Falion at the College; maintains professional respect despite his departure"},"Savos Aren":{"aff":25,"type":"professional","relation":"arch-mage","note":"Serves under Aren with professional but distant deference"},"Missing Apprentices":{"aff":5,"type":"dismissive","relation":"former students","note":"Shows concerning detachment regarding their deaths","worst":"Accepted news of Yisra, Rundi, Borvir, and Ilas-Tei''s deaths with unsettling calm"},"Morthal Guards":{"aff":-35,"type":"suspicious","relation":"local guards","note":"Strained relationship due to past incident he dismisses as misunderstanding","worst":"Incident in Morthal left guards hostile toward him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pirate', '{"Pirate Captain":{"aff":35,"type":"professional","relation":"crew captain","note":"Serves under the captain at Haknir''s Shoal but dismisses concerns about curses","best":"Found treasure right where the map said it would be","worst":"Captain''s superstitious doubts about the haul"},"Pirate Mage":{"aff":-30,"type":"rival","relation":"crew mate turned enemy","note":"Can turn deadly when disputes over treasure or orders arise","worst":"Mage threatened to bring back corpse instead of compliance, leading to mortal combat"},"Raven Rock Guards":{"aff":-70,"type":"enemy","relation":"adversaries","note":"Constant opposition patrolling the coastline the pirates raid"},"East Empire Company":{"aff":-60,"type":"rival","relation":"raid targets","note":"Primary prey for raids and ambushes on shipping routes"},"Tel Mithryn":{"aff":-15,"type":"suspicious","relation":"wary neighbors","note":"Maintain cautious distance from the powerful Telvanni wizards"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pit_wolf', '{"Handler":{"aff":-85,"type":"fearful","relation":"abusive handler","note":"Conditions the wolf through starvation and punishment; obedience driven by fear of reprisal","worst":"Years of brutal conditioning and forced fights under harsh discipline"},"Other Pit Wolves":{"aff":15,"type":"rival","relation":"fellow captives","note":"Buried pack instinct conflicts with conditioned arena opposition","best":"Quiet moments between fights when natural wolf instinct briefly surfaces"},"Arena Spectators":{"aff":-60,"type":"contempt","relation":"spectators","note":"Associated with pain and the frenzy of combat; triggers aggressive response"},"Cragslane Cavern Operators":{"aff":-80,"type":"contempt","relation":"overseers","note":"Cruel profiteers who exploit the wolf''s suffering for gambling revenue","worst":"Deliberate starvation and forced combat for profit"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('plautis_carvain', '{"Salonia Carvain":{"aff":25,"type":"romantic","relation":"wife","note":"Strained marriage worsened by their disastrous journey through Skyrim","best":"Genuine concern for her safety despite their bickering","worst":"Endless nagging and misplaced priorities after losing everything"},"Bodyguard":{"aff":15,"type":"servant","relation":"hired bodyguard","note":"Hired protection who died defending them, eaten by a dragon","worst":"Bodyguard killed by dragon during the ill-fated journey"},"Vittoria Vici":{"aff":30,"type":"curious","relation":"aspiring connection","note":"Never met her; sought her favor to secure an East Empire Company import deal","best":"Carried expensive gifts intended to win her good graces","worst":"Missed the wedding entirely after getting lost in Skyrim"},"East Empire Company":{"aff":25,"type":"transactional","relation":"target business partner","note":"Sought a lucrative import deal through social connections at the wedding"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('poacher', '{"Hold Guards":{"aff":-85,"type":"enemy","relation":"law enforcement","note":"Mortal enemies who would arrest or kill them on sight","worst":"Years of evading capture have made them constantly vigilant against patrols"},"Fence Networks":{"aff":35,"type":"transactional","relation":"criminal buyers","note":"Essential contacts who purchase illegal pelts and stolen goods","best":"A successful sale of rare mammoth ivory at a good price"},"Loreius Farm Residents":{"aff":-40,"type":"suspicious","relation":"nearby settlers","note":"Potential threats to operations who must be avoided or eliminated","worst":"Spotting farm residents too close to poaching grounds"},"Other Bandits":{"aff":-10,"type":"rival","relation":"competitors","note":"Occasional allies but more often competitors for territory and resources"},"Travelers":{"aff":-50,"type":"suspicious","relation":"potential witnesses","note":"Viewed as threats to be robbed or silenced","worst":"A traveler spotting a fresh mammoth kill"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('poor_fishwife', '{"Maven Black-Briar":{"aff":-65,"type":"contempt","relation":"extortion victim","note":"Forced to pay protection fees to maintain her fishing business","worst":"Another payment demanded, another day''s catch stolen by her thugs"},"Bolli":{"aff":-10,"type":"rival","relation":"competitor","note":"Fellow fisher competing for business at the Fishery"},"Thieves Guild":{"aff":-45,"type":"suspicious","relation":"wary observer","note":"Keeps her distance, aware of their influence over Riften''s docks","worst":"Coin gone missing from the stall, knowing who likely took it"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('prelate_athring', '{"Arch-Curate Vyrthur":{"aff":45,"type":"professional","relation":"arch-curate","note":"Served under his authority within the Chantry of Auri-El hierarchy"},"Knight-Paladin Gelebor":{"aff":65,"type":"platonic","relation":"fellow servant","note":"Brother in devotion who continues the Chantry''s sacred vigil"},"Wayshrine Prelates":{"aff":55,"type":"platonic","relation":"spirit brothers","note":"Fellow ghostly guardians bound by eternal service to the wayshrines"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('prelate_celegriath', '{"Arch-Curate Vyrthur":{"aff":-40,"type":"estranged","relation":"former superior","note":"Vyrthur fell to vampiric corruption, betraying the faith they both served"},"Other Wayshrine Prelates":{"aff":50,"type":"platonic","relation":"fellow guardians","note":"Share eternal vigil over the Wayshrines of the Forgotten Vale"},"Auri-El":{"aff":95,"type":"fanatical","relation":"divine patron","note":"Celegriath dedicated his life and afterlife to Auri-El''s service"},"Initiates and Pilgrims":{"aff":45,"type":"mentor","relation":"spiritual guide","note":"Guides seekers toward enlightenment with patience and compassion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('prelate_edhelbor', '{"Arch-Curate Vyrthur":{"aff":70,"type":"servant","relation":"superior in Chantry","note":"Serves faithfully within the Chantry hierarchy"},"Knight-Paladin Gelebor":{"aff":55,"type":"platonic","relation":"fellow guardian","note":"Fellow guardian of the wayshrines and occasional confidant"},"Auri-El":{"aff":95,"type":"fanatical","relation":"deity","note":"Abandoned privilege after a profound spiritual calling to serve Auri-El"},"Initiate Pilgrims":{"aff":50,"type":"mentor","relation":"spiritual guide","note":"Views guiding seekers of enlightenment as a sacred duty"},"Ancient Snow Elf Spirits":{"aff":40,"type":"awed","relation":"honored ancestors","note":"Honors departed souls through daily prayer and ritual"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('prelate_nirilor', '{"Auri-El":{"aff":100,"type":"fanatical","relation":"divine patron","note":"Devotion so profound his spirit remained bound to the Wayshrine beyond physical death","best":"Chosen to maintain the sacred wayshrines during the height of Snow Elf civilization","worst":"Witnessed the fall of his civilization yet could not abandon his eternal vigil"},"Knight-Paladin Gelebor":{"aff":55,"type":"professional","relation":"fellow servant of Auri-El","note":"Brothers in devotion though they rarely interact directly across the vast Chantry"},"Wayshrine Prelates":{"aff":50,"type":"professional","relation":"former colleagues","note":"Shared sacred duty maintaining the pilgrim''s path and wayshrines of the Chantry"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('prelate_sidanyis', '{"Arch-Curate Vyrthur":{"aff":55,"type":"servant","relation":"religious superior","note":"Serves under Vyrthur within the Chantry of Auri-El''s hierarchy"},"Initiates":{"aff":50,"type":"mentor","relation":"spiritual guide","note":"Guides initiates seeking Auri-El''s wisdom at the Wayshrine"},"Ancient Falmer":{"aff":-15,"type":"pitying","relation":"corrupted kin","note":"Mourns their tragic fate while maintaining vigilance against their presence","worst":"Witnessed the corruption of his people into the twisted Falmer"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('priestess_of_arkay', '{"Temple of Arkay":{"aff":90,"type":"servant","relation":"devoted servant","note":"Serves with unwavering dedication as Arkay''s representative in Helgen"},"Captain Aldis":{"aff":45,"type":"professional","relation":"execution liaison","note":"Coordinates execution procedures and last rites for the condemned"},"Helgen Guards":{"aff":40,"type":"professional","relation":"ceremonial partners","note":"Cooperative working relationship for ceremonial duties"},"Local Nords":{"aff":30,"type":"curious","relation":"cultural bridge","note":"Respects Nordic customs while maintaining Imperial traditions","worst":"Viewed with suspicion by some who prefer Nordic burial customs"},"Stormcloak rebels":{"aff":20,"type":"pitying","relation":"condemned souls","note":"Attempts to deliver last rites despite their defiance","worst":"Interrupted and dismissed by defiant soldier during last rites"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('proventus_avenicci', '{"Balgruuf":{"aff":75,"type":"professional","relation":"liege lord","note":"Serves as steward with unwavering loyalty, though they frequently argue over policy and caution","best":"Years of trusted service earned him a position of confidence in Dragonsreach","worst":"Counsel of caution repeatedly dismissed in favor of bolder action"},"Adrianne Avenicci":{"aff":80,"type":"familial","relation":"daughter","note":"Proud of her skill as a blacksmith but laments not seeing her enough","best":"Speaks fondly of her to visitors, eager to share her accomplishments"},"Irileth":{"aff":25,"type":"professional","relation":"fellow advisor","note":"Colleagues who regularly clash over counsel given to the Jarl","worst":"His caution and her decisiveness make them natural adversaries in court"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('pyromancer', '{"Warlock Coven":{"aff":65,"type":"professional","relation":"covenant member","note":"Rose through ranks by pursuing unrestricted fire magic research alongside fellow dark practitioners","best":"Accepted into the covenant after proving mastery of destructive spells"},"College of Winterhold":{"aff":-75,"type":"enemy","relation":"rejected institution","note":"Hostile since rejecting their regulations and structured approach to magic","worst":"Abandoned the College and its restrictive teachings"},"Frost Mages":{"aff":-65,"type":"rival","relation":"elemental rivals","note":"Fierce rivalry with practitioners of frost magic, obsessed with proving fire''s superiority","worst":"Humiliated in magical combat by a frost mage"},"Local Settlements":{"aff":-85,"type":"contempt","relation":"raiding targets","note":"Raids nearby settlements for supplies and test subjects, feared by common folk","best":"Successful raid yielding rare alchemical ingredients"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('quaranir', '{"Psijic Order":{"aff":80,"type":"professional","relation":"emissary","note":"Loyal member who nonetheless overstepped Order policy to intervene directly","worst":"His personal arrival was seen as an affront by some within the Order"},"Ancano":{"aff":-65,"type":"rival","relation":"adversary","note":"Mutual distrust; Ancano sees the Psijic Order as a threat to Thalmor interests","worst":"Confronted by a hostile Ancano demanding answers after the frozen-time conversation"},"College of Winterhold":{"aff":45,"type":"protective","relation":"cautious ally","note":"Intervened to warn of the Eye''s danger despite the Order''s non-intervention policies"},"The Last Dragonborn":{"aff":70,"type":"protective","relation":"chosen confidant","note":"Selected the Dragonborn to address the Eye crisis and expressed faith in their success","best":"Affirmed belief in the Dragonborn''s ability to succeed against the Eye''s threat"},"Savos Aren":{"aff":40,"type":"professional","relation":"respected colleague","note":"Holds professional respect for the Arch-Mage but maintains careful distance per Order custom"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('quintus_navale', '{"Nurelion":{"aff":70,"type":"mentor","relation":"master","note":"Traveled from Cyrodiil specifically to study under him; remains devoted despite frequent harsh treatment","best":"Nurelion''s rare apologies and vulnerable admission that he worries about having little time left","worst":"Constant criticism and dismissal of his own alchemical projects as wasting time"},"Sondas Drenim":{"aff":25,"type":"client","relation":"customer","note":"Regular customer who trusts his medicinal expertise"},"Windhelm Merchants":{"aff":20,"type":"professional","relation":"colleagues","note":"Maintains cordial professional relationships with local shopkeepers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ra''jirr', '{"Kyr":{"aff":30,"type":"professional","relation":"superior","note":"Recruited Ra''jirr for the Frostmere operation, but his claiming of the Pale Blade triggered the haunting"},"Eisa Blackthorn":{"aff":55,"type":"platonic","relation":"partner","note":"Close partner in criminal activities at Frostmere Crypt"},"The Pale Lady":{"aff":-85,"type":"fearful","relation":"tormentor","note":"Supernatural entity whose visions drove him to madness and ultimately his death","worst":"Her appearance made him scream in despair as she attacked"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ra''kheran', '{"Sinding":{"aff":-35,"type":"rival","relation":"prey","note":"Primary target in Hircine''s Great Hunt, pursued with both respect and lethal determination","best":"Tracking the werewolf through Bloated Man''s Grotto under the Bloodmoon","worst":"Sinding escaping or being denied the kill"},"Hircine":{"aff":90,"type":"fanatical","relation":"patron deity","note":"Spiritually devoted hunter who sees himself as an instrument of the Daedric Prince''s will","best":"Being chosen to participate in the sacred Great Hunt","worst":"Failing to prove his worth and earn Hircine''s favor"},"Fellow Hunters":{"aff":55,"type":"professional","relation":"followers","note":"Leads a band of skilled hunters who follow his command during the Great Hunt"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ra''zhinda', '{"Ma''dran":{"aff":75,"type":"professional","relation":"employer","note":"Respected caravan leader who trusts her judgment as his primary guard","best":"Ma''dran entrusted her as sole protector of his caravan"},"Ma''jhad":{"aff":55,"type":"platonic","relation":"caravan mate and sparring partner","note":"Fellow Khajiit traveler she occasionally trains with"},"Bandits":{"aff":-80,"type":"enemy","relation":"persistent threats","note":"Constant danger to the caravan she must deal with firmly","worst":"Witnessed numerous attacks on merchant caravans in Elsweyr"},"Nordic Guards":{"aff":-35,"type":"suspicious","relation":"city guards","note":"Tense relationship due to frequent discrimination against Khajiit","worst":"Subjected to racial prejudice while conducting legitimate trade"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rabbit', '{"Foxes":{"aff":-85,"type":"fearful","relation":"natural predator","note":"Primary ground predator that relentlessly hunts rabbits"},"Hunters":{"aff":-80,"type":"fearful","relation":"predatory threat","note":"Tracked by the Bunnies Slaughtered statistic"},"Predatory Birds":{"aff":-80,"type":"fearful","relation":"aerial predator","note":"Constant danger from above requiring unceasing vigilance"},"Other Rabbits":{"aff":25,"type":"familial","relation":"warren member","note":"Maintain loose social bonds and share danger warnings through foot-thumping"},"Children":{"aff":15,"type":"neutral","relation":"potential companion","note":"Can be domesticated as gentle pets through Hearthfire adoption"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('raen', '{"Vidgrod":{"aff":65,"type":"platonic","relation":"fellow outcast companion","note":"Close companion expelled alongside her from the Knifepoint Gang","worst":"Cast out together into exile"},"Agrius":{"aff":65,"type":"platonic","relation":"fellow outcast companion","note":"Trusted ally who documented their doomed journey in his journal","worst":"Cast out together into exile"},"Knifepoint Gang":{"aff":-55,"type":"estranged","relation":"former gang","note":"Expelled Raen and her companions for unknown reasons","worst":"Kicked out of the gang, losing her livelihood and reputation"},"Halldir":{"aff":50,"type":"obsessed","relation":"corrupting entity","note":"First to embrace Halldir''s influence and willingly sacrifice herself to him","best":"Discovered the promise of arcane power in the cairn","worst":"Consumed body and soul to fuel Halldir''s elemental copies"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('raerek', '{"Jarl Igmund":{"aff":75,"type":"familial","relation":"nephew and liege lord","note":"Serves as both steward and trusted advisor; his first and only loyalties are to Igmund and Markarth","best":"Continuing to guide Igmund as he guided his father","worst":"Being exiled from Markarth when the Stormcloaks take the city"},"Hrolfdir":{"aff":70,"type":"familial","relation":"brother and former Jarl","note":"Served as his steward; together they swore oaths to the Empire to abandon Talos"},"Thalmor":{"aff":-80,"type":"fearful","relation":"secret persecutors","note":"His hidden Talos worship would mean imprisonment and generational stain on family honor if discovered","worst":"Discovery of his Amulet of Talos would destroy everything"},"Bothela":{"aff":30,"type":"transactional","relation":"discreet supplier","note":"Mutually discreet arrangement for personal potion deliveries","best":"Her discretion protects his private affairs from court gossip"},"Ulfric Stormcloak":{"aff":-50,"type":"rival","relation":"political opponent","note":"Acknowledges Ulfric is right about some things but has seen firsthand what he is capable of; considers him no friend to Markarth","worst":"Ulfric''s past actions harmed Markarth deeply"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ragnar', '{"Ainethach":{"aff":75,"type":"professional","relation":"employer and right-hand man","note":"Deeply loyal to his Reachman employer, rare trust across cultural lines","best":"Earned position of trust as Ainethach''s right-hand man","worst":"Fears for Karthwasten''s future if Ainethach dies"},"Lash gra-Dushnikh":{"aff":40,"type":"platonic","relation":"fellow miner","note":"Respectful camaraderie with awkward but genuine mutual appreciation","best":"Lash invited him hunting and called his arms fit for strong prey"},"Belchimac":{"aff":-25,"type":"suspicious","relation":"antagonistic coworker","note":"Tension over anti-Nord remarks and suspected Forsworn sympathies","best":"Apologized immediately after threatening him","worst":"Threatened to cut his throat over an insult"},"Silver-Blood Mercenaries":{"aff":-70,"type":"enemy","relation":"threat to the mine","note":"Views them as worse than Forsworn for disrupting peaceful operations","worst":"Their occupation shut down Sanuarach Mine"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rahd', '{"Bandit Groups":{"aff":50,"type":"professional","relation":"patrons","note":"Respected his neutral ground rules and valued the safe haven he provided"},"Fellow Retreat Staff":{"aff":55,"type":"professional","relation":"coworkers","note":"Trusted staff who helped maintain the Liar''s Retreat together"},"Falmer":{"aff":-100,"type":"enemy","relation":"killers","note":"Raided the Liar''s Retreat and brutally tortured and killed him","worst":"Falmer tunneled in, tortured him, and left a sword thrust into his abdomen"},"Underground Merchants":{"aff":30,"type":"transactional","relation":"suppliers","note":"Kept his establishment stocked through underground trade networks"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rakel', '{"Majni":{"aff":85,"type":"familial","relation":"adoptive father, Alpha","note":"Raised her after her parents died; she respects him deeply but harbors insecurity about not matching his hunting skill"},"Akar":{"aff":75,"type":"familial","relation":"adoptive parent, mentor","note":"Co-raised and trained her alongside Majni after her parents'' death"},"Frostmoon Pack":{"aff":80,"type":"protective","relation":"pack","note":"Fiercely loyal to pack traditions; serves as hunter and sentry to protect their territory and way of life"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('raleth_eldri', '{"College of Winterhold":{"aff":20,"type":"professional","relation":"former associate researcher","note":"Maintained distance from institution politics despite past association"},"Neloth":{"aff":15,"type":"professional","relation":"correspondent","note":"Occasional correspondent on matters of Dwemer research"},"Raven Rock miners":{"aff":10,"type":"transactional","relation":"information source","note":"Consulted for reports of new Dwemer discoveries near the mines"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ralis_sedarys', '{"Ahzidal":{"aff":-90,"type":"nemesis","relation":"possessor","note":"Ancient enchanter who possessed and controlled Ralis, forcing him to commit atrocities","worst":"Lost his will and harmed others under Ahzidal''s influence"},"Unknown Financier":{"aff":25,"type":"transactional","relation":"patron","note":"Wealthy backer who funded the Solstheim expedition, pays only on delivery of relics"},"Hired Miners":{"aff":-15,"type":"professional","relation":"employees","note":"Dig workers who met tragic ends during the Kolbjorn excavation","worst":"Their deaths weigh on his conscience"},"The Last Dragonborn":{"aff":55,"type":"grateful","relation":"benefactor","note":"Funded the dig and ultimately freed Ralis from Ahzidal''s possession","best":"Freed him from Ahzidal''s control and spared his life"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ralof', '{"Gerdur":{"aff":90,"type":"familial","relation":"sister","note":"Beloved sister who shelters him; her family founded Riverwood","best":"Reuniting with her after escaping Helgen","worst":"Being unable to visit freely while hunted by Imperials"},"Frodnar":{"aff":85,"type":"protective","relation":"nephew","note":"Clearly adores his sister''s son"},"Hod":{"aff":60,"type":"familial","relation":"brother-in-law","note":"Works the mill alongside Gerdur; family by marriage"},"Ulfric Stormcloak":{"aff":80,"type":"fanatical","relation":"commander","note":"Serves with unwavering loyalty; calls him the true High King","best":"Fighting under his banner for Skyrim''s freedom"},"Imperial Legion":{"aff":-85,"type":"enemy","relation":"sworn enemy","note":"Hates Imperial oppression; nearly executed at Helgen","worst":"Watching the Empire try to behead Ulfric and his comrades"},"Thalmor":{"aff":-90,"type":"enemy","relation":"hated oppressors","note":"Blames them for the Empire''s ban on Talos worship and the war","worst":"Seeing them alongside Tullius at the execution"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ramati', '{"Habd":{"aff":90,"type":"romantic","relation":"husband","note":"Shared dream of running Frostflow Lighthouse together after years of saving","best":"Years of working together toward their lighthouse dream"},"Sudi":{"aff":70,"type":"familial","relation":"daughter","note":"Loving mother who tragically dismissed Sudi''s warnings about cellar noises","worst":"Ignored her daughter''s reports of scratching sounds from below"},"Mani":{"aff":65,"type":"familial","relation":"son","note":"Son who struggled adjusting to their isolated new home"},"Falmer":{"aff":-100,"type":"enemy","relation":"killers","note":"Invaded through cellar walls and murdered her","worst":"Falmer war axe pierced her body as they emerged from tunnels"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ranmir', '{"Birna":{"aff":20,"type":"familial","relation":"sister","note":"Strained relationship; she supports him despite his dismissiveness and alcoholism","worst":"Constant arguments about money and his drinking"},"Isabelle Rolaine":{"aff":50,"type":"romantic","relation":"former lover","note":"Believed she abandoned him; actually died seeking treasure for them both","best":"Their life together before her disappearance","worst":"Her disappearance, which he interpreted as abandonment"},"Haran":{"aff":-5,"type":"transactional","relation":"innkeeper","note":"Owes her money for unpaid drinks; avoids paying his tab"},"Dagur":{"aff":10,"type":"transactional","relation":"innkeeper","note":"Tolerates his presence despite the unpaid tab"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rargal_thrallmaster', '{"Lord Harkon":{"aff":75,"type":"servant","relation":"master","note":"Serves with unwavering loyalty as Volkihar''s thrallmaster","best":"Appointed as official thrallmaster after catching Harkon''s attention"},"Garan Marethi":{"aff":30,"type":"professional","relation":"colleague","note":"Coordinates feeding schedules and court logistics"},"Volkihar Court":{"aff":40,"type":"professional","relation":"blood supplier","note":"Ensures the vampire nobility never goes hungry"},"Thralls":{"aff":-40,"type":"contempt","relation":"livestock","note":"Views them as cattle to be managed, protective only as valuable resources","worst":"Maintains order through threats and violence with no sympathy"},"Cured Vampires":{"aff":-60,"type":"contempt","relation":"lesser beings","note":"Considers them barely above thralls and a disrespect to Lord Harkon","worst":"Threatens to cage those who walk the keep without vampiric blood"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ravam_verethi', '{"Captain Wayfinder":{"aff":-65,"type":"contempt","relation":"captain","note":"Openly disrespects him as an inexperienced boy and resents serving under him","worst":"Takes orders from a boy who inherited the ship rather than earning command"},"Ship''s Crew":{"aff":10,"type":"transactional","relation":"fellow sailors","note":"Maintains distant, professional relationships with crewmates"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ravyn_imyan', '{"Karliah":{"aff":35,"type":"professional","relation":"guildmate","note":"Initially distrusted her presence, accepted her after Mercer''s betrayal was exposed","best":"Acknowledged her innocence and welcomed her into the Guild","worst":"Confronted her arrival with hostility, expecting no good excuse"},"Morag Tong":{"aff":70,"type":"estranged","relation":"former organization","note":"Deeply loyal to his former brotherhood, hopes for reunification one day","best":"Served with honor as a sanctioned assassin in Mephala''s name","worst":"Scattered by the Red Mountain eruption, the pact of reunion grows distant"},"Dark Brotherhood":{"aff":-75,"type":"enemy","relation":"bitter rivals","note":"Traditional Morag Tong hatred compounded by fear of being targeted if discovered","worst":"Would face a vengeance contract if his Morag Tong past were revealed"},"Mercer Frey":{"aff":-85,"type":"nemesis","relation":"betrayer of the Guild","note":"Considers death the only fitting penalty for his betrayal","worst":"Enraged that punishment is too good for him, only death will suffice"},"Vex":{"aff":45,"type":"professional","relation":"guildmate","note":"Shares her direct, no-nonsense approach and professional attitude"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rayya', '{"Thane of Falkreath":{"aff":80,"type":"protective","relation":"sworn charge","note":"Sworn housecarl dedicated to protecting her Thane''s life and property with unwavering loyalty"},"Jarl of Falkreath":{"aff":55,"type":"professional","relation":"employer","note":"Appointed her as housecarl despite non-Nord heritage, recognizing her exceptional combat skills and honor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('razelan', '{"Elenwen":{"aff":-35,"type":"rival","relation":"antagonistic party host","note":"Regularly attends her parties but resents her attempts to control his drinking and behavior","worst":"She orders waiters to cut off his alcohol and has him forcibly removed from gatherings"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reach_hold_guard', '{"Jarl Igmund":{"aff":55,"type":"servant","relation":"liege lord","note":"Sworn to serve and protect his interests as a Reach Hold Guard"},"Left Hand Mine Workers":{"aff":50,"type":"protective","relation":"charges","note":"Guards the miners faithfully and has earned their respect"},"Fellow Reach Guards":{"aff":60,"type":"platonic","relation":"brothers-in-arms","note":"Strong bonds of mutual support from shared duty"},"Forsworn":{"aff":-80,"type":"enemy","relation":"foes","note":"Vigilantly watched for as dangerous insurgents","worst":"Bears scars from previous Forsworn encounters"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reaver', '{"Fellow Reavers":{"aff":35,"type":"platonic","relation":"band","note":"Bonds of necessity and mutual survival within the tribal bandit group","best":"shared survival against Solstheim''s harsh conditions","worst":"constant tension over scarce loot and territory"},"Skaal Village":{"aff":-40,"type":"enemy","relation":"raiding target","note":"Views as prey but respects their fighting capability","best":"successful raid on isolated Skaal hunters","worst":"losing band members to Skaal resistance"},"Raven Rock Guards":{"aff":-70,"type":"enemy","relation":"natural enemy","note":"Regular violent clashes with the settlement''s armed protectors","best":"ambushing a poorly guarded caravan near Raven Rock","worst":"fellow Reavers killed in direct confrontation with guards"},"Tel Mithryn":{"aff":-20,"type":"fearful","relation":"avoided faction","note":"Steers clear of the powerful mages residing there","best":"salvaging loot from the tower''s outskirts undetected","worst":"nearly losing a patrol to magical retaliation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reaver_highwayman', '{"Fellow Reavers":{"aff":25,"type":"professional","relation":"band allies","note":"Loose alliance of convenience sharing camps and spoils, not deep loyalty"},"Raven Rock Guards":{"aff":-85,"type":"enemy","relation":"pursuers","note":"Sworn enemies who actively hunt and attempt to arrest Reavers"},"Local Dunmer Settlers":{"aff":-15,"type":"contempt","relation":"prey","note":"Shared heritage offers no protection; sometimes traded with, more often robbed"},"Skaal Village":{"aff":-45,"type":"rival","relation":"targets","note":"Viewed as potential victims, though their warriors demand caution"},"Tel Mithryn":{"aff":-20,"type":"fearful","relation":"avoided faction","note":"Steer clear of direct conflict, wisely fearing Telvanni wizard power"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reaver_marauder', '{"Fellow Reavers":{"aff":45,"type":"professional","relation":"fellow reavers","note":"Loose alliance based on mutual benefit and survival in Solstheim''s wastes","best":"Fighting alongside brothers to secure a rich plunder haul","worst":"Being abandoned by allies when a raid went badly"},"Raven Rock Guards":{"aff":-75,"type":"enemy","relation":"sworn enemies","note":"Regularly patrol against Reaver attacks and represent authority they reject","best":"Ambushing a patrol and taking their equipment","worst":"Losing comrades to a guard crackdown"},"Skaal Village":{"aff":-55,"type":"contempt","relation":"raid targets","note":"Viewed as soft and vulnerable, easy pickings for raids","best":"Successful raid on their isolated settlement","worst":"Skaal hunters proving more dangerous than expected"},"Tel Mithryn":{"aff":-30,"type":"fearful","relation":"avoided threat","note":"Keeps distance due to the powerful wizards residing there","best":"Scouting the perimeter and escaping unscathed","worst":"Witnessing Reavers destroyed by magical defenses"},"Other Bandits":{"aff":15,"type":"transactional","relation":"occasional allies","note":"Temporary alliances formed for larger operations, dissolved after","best":"Joint operation that yielded rich plunder for both groups","worst":"Allies turning on them to claim a larger share of loot"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reaver_outlaw', '{"Fellow Reavers":{"aff":15,"type":"transactional","relation":"loose allies","note":"Unstable alliance built on mutual survival and profit, rife with competition and backstabbing","best":"Successful coordinated raid yielding rich plunder","worst":"Betrayed by a fellow Reaver over a valuable haul"},"Raven Rock Guards":{"aff":-85,"type":"enemy","relation":"sworn enemies","note":"Redoran guards who relentlessly hunt Reaver bands across Solstheim","worst":"Ambushed by a patrol that killed close companions"},"Tel Mithryn":{"aff":-30,"type":"fearful","relation":"avoided threat","note":"Deliberately avoided due to the dangerous power of the Telvanni wizards"},"Skaal Village":{"aff":-45,"type":"contempt","relation":"raid targets","note":"Viewed as vulnerable prey when other opportunities run dry","best":"Easy raid on an unprotected Skaal supply cache"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reaver_plunderer', '{"Fellow Reavers":{"aff":35,"type":"professional","relation":"loose allies","note":"Bound by mutual benefit and shared criminal lifestyle rather than loyalty"},"Raven Rock Guard":{"aff":-65,"type":"enemy","relation":"hunters and prey","note":"Natural enemies who patrol against reaver camps"},"Skaal Village":{"aff":-30,"type":"rival","relation":"potential targets","note":"Viewed as prey, though their warriors command grudging respect"},"Neloth":{"aff":-15,"type":"fearful","relation":"avoided target","note":"His supplies are prized but his power keeps reavers at bay"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reaver_thug', '{"Fellow Reavers":{"aff":65,"type":"platonic","relation":"fellow outlaws","note":"Tight-knit band bound by survival and mutual profit","best":"Sharing plunder after a successful raid"},"Raven Rock Guard":{"aff":-80,"type":"enemy","relation":"law enforcement","note":"Sworn enemies who regularly attempt to suppress Reaver activities","worst":"Narrow escape from a Guard ambush"},"Skaal Village":{"aff":-35,"type":"rival","relation":"raid targets","note":"Viewed as potential targets, though their warriors command grudging respect"},"Tel Mithryn":{"aff":-25,"type":"fearful","relation":"avoided faction","note":"Avoided when possible due to the power of its inhabitants"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reburrus_quintilius', '{"Silver-Blood Family":{"aff":55,"type":"professional","relation":"employer","note":"Manages their financial empire from the Treasury House; pragmatic loyalty rooted in wealth and status"},"Thongvor Silver-Blood":{"aff":30,"type":"professional","relation":"direct superior","note":"Serves as his steward under Stormcloak rule; tolerates Thongvor''s dismissiveness to preserve position","worst":"Publicly questioned by Thongvor about whose side he is on after suggesting Ulfric might be too busy for requests"},"Yngvar the Singer":{"aff":-15,"type":"rival","relation":"court colleague","note":"Yngvar mocks his detailed reports and needles him with inconvenient truths about Forsworn attacks","worst":"Cut off mid-report with ''Talos''s breath, skip ahead to the good part''"},"Bothela":{"aff":10,"type":"transactional","relation":"discreet supplier","note":"Recipient of Stallion''s Potion deliveries; relationship is embarrassing and best kept quiet"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reckless_mage', '{"Thoring":{"aff":15,"type":"transactional","relation":"innkeeper","note":"Tolerates his presence at the Frozen Hearth despite occasional magical accidents"},"College of Winterhold":{"aff":20,"type":"curious","relation":"distant observers","note":"Studies their techniques from afar but never formally joined due to uncontrolled casting"},"Local Nords":{"aff":-25,"type":"estranged","relation":"community","note":"Generally avoid him due to his reputation for dangerous spellcasting"},"Dark Brotherhood":{"aff":-80,"type":"enemy","relation":"target","note":"Marked as a potential assassination target in recurring contracts"},"Family":{"aff":-40,"type":"estranged","relation":"family","note":"Ostracized him after a magical accident destroyed their farm","worst":"Magical accident that destroyed the family farm and got him cast out"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('red_eagle', '{"Hagravens":{"aff":-15,"type":"indebted","relation":"dark pact granters","note":"Sought them out and sacrificed his humanity for power to continue his war","worst":"Lost his humanity and became corrupted through their bargain"},"Nordic Invaders":{"aff":-95,"type":"nemesis","relation":"conquerors of the Reach","note":"Bitter enemies who invaded his homeland and ultimately defeated him","worst":"Conquered the Reach and subjugated his people"},"Reachmen":{"aff":85,"type":"protective","relation":"his people","note":"King and unifying leader who sacrificed everything to defend them from Nordic expansion","best":"United the Reachfolk into a fierce resistance against the invaders"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('redoran_guard', '{"Captain Veleth":{"aff":70,"type":"professional","relation":"commanding officer","note":"Respected direct superior whose leadership they trust implicitly"},"Second Councilor Adril Arano":{"aff":50,"type":"protective","relation":"superior and charge","note":"Key authority figure they report to and are duty-bound to protect"},"Councilor Morvayn":{"aff":45,"type":"protective","relation":"supreme authority","note":"Highest authority in Raven Rock they are sworn to defend"},"Fellow Redoran Guards":{"aff":65,"type":"platonic","relation":"brotherhood in arms","note":"Close-knit comrades forged through shared duty and danger"},"Raven Rock Dunmer":{"aff":40,"type":"protective","relation":"protected charges","note":"Cultural kin they are bound to safeguard"},"Non-Dunmer Visitors":{"aff":-15,"type":"suspicious","relation":"potential threats","note":"Outsiders regarded with professional wariness as outlanders"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('redwater_lookout', '{"Redwater Den Leadership":{"aff":45,"type":"professional","relation":"employer","note":"Earned position of trust through reliability and combat prowess","best":"Promoted to exterior guard due to proven vigilance","worst":"Unknowingly serving vampire masters who will eventually enthrall them"},"Fellow Redwater Guards":{"aff":15,"type":"professional","relation":"coworkers","note":"Professional but distant working relationships within the den"},"Rift Guards":{"aff":-45,"type":"enemy","relation":"law enforcement","note":"Adversarial relationship marked by careful avoidance","worst":"Constant threat of arrest forcing paranoid vigilance"},"Skooma Traders":{"aff":10,"type":"transactional","relation":"business contacts","note":"Cautious business associations requiring constant verification","worst":"Never certain if a trader is legitimate or an informant"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reldith', '{"Ennis":{"aff":88,"type":"familial","relation":"adoptive son","note":"She rescued him as an orphan and raised him; she remains protective and delays his travel plans out of worry","best":"Rescued him as an orphan and gave him a life of honest work","worst":"Dreads the thought of him traveling alone amid war and dragons"},"Jouane Manette":{"aff":45,"type":"platonic","relation":"neighbor","note":"Friendly neighbor who brings her small gifts from the city"},"Rorik":{"aff":35,"type":"professional","relation":"local lord","note":"He checks on her planting progress; she reports to him respectfully"},"Erik":{"aff":40,"type":"protective","relation":"neighbor''s son","note":"Worries about his adventuring aspirations the same way she worries about Ennis"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('reveler', '{"Maven Black-Briar":{"aff":-75,"type":"contempt","relation":"rival meadery owner","note":"Despises her and her meadery''s products with passionate intensity","worst":"Refused to speak to someone who offered Black-Briar Mead, calling it swill"},"Sabjorn":{"aff":65,"type":"admirer","relation":"admired meadery owner","note":"Deeply admires though likely never met him","best":"Praises Honningbrew Mead as the finest outside Sovngarde"},"Fellow Revelers":{"aff":80,"type":"platonic","relation":"traveling companions","note":"Roving band of merry-makers united by love of Honningbrew Mead","best":"Sharing drinks and laughter on Skyrim''s roads"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('revus_sarvani', '{"Dusty":{"aff":92,"type":"protective","relation":"beloved silt strider companion","note":"Found her as a larva after Red Mountain''s eruption and has dedicated his life to her care","best":"Discovering her alive in a cave as a larva after the eruption","worst":"Watching her grow too old to travel, knowing her time is short"},"Geldis Sadri":{"aff":25,"type":"professional","relation":"fellow merchant","note":"Raven Rock trader who would handle selling his nix-hound if Revus passed away"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('revyn_sadri', '{"Idesa Sadri":{"aff":70,"type":"familial","relation":"sister","note":"Works for the Cruel-Sea clan; fellow Dunmer establishing themselves in Windhelm"},"Ambarys Rendar":{"aff":45,"type":"platonic","relation":"fellow Dunmer merchant","note":"Regular patron at New Gnisis Cornerclub; shared community in the Grey Quarter"},"Viola Giordano":{"aff":-40,"type":"fearful","relation":"unwitting victim","note":"Accidentally bought her stolen ring; terrified she will report him to the Jarl","worst":"Realized he purchased her stolen gold ring and could be ruined if discovered"},"Grey Quarter Dunmer":{"aff":65,"type":"protective","relation":"community","note":"Shares his good fortune with those he deems deserving","best":"Built a legitimate business to help support his people"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rexus', '{"Amaund Motierre":{"aff":78,"type":"protective","relation":"bodyguard","note":"Vowed to serve until his dying breath with unwavering loyalty","best":"Years of trusted service and mutual respect between protector and charge"},"The Motierre Family":{"aff":50,"type":"patron","relation":"employer family","note":"Long-standing employers who value his discretion and capability"},"Dark Brotherhood":{"aff":10,"type":"suspicious","relation":"cautious contacts","note":"Interacts warily when required by employer''s dealings"},"Imperial Legion":{"aff":25,"type":"neutral","relation":"former service","note":"Former military association from his Cyrodiil days"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rhiada', '{"Eltrys":{"aff":90,"type":"romantic","relation":"husband","note":"Beloved husband and father of her unborn child; she fears for his safety","best":"Their wedding last season","worst":"Anxiety over his dangerous investigation"},"Nana Ildene":{"aff":75,"type":"mentor","relation":"mentor and mother figure","note":"Long-time mentor whose reassurance about the Forsworn she relies on","best":"Ildene comforting her about safety in Markarth"},"Thonar Silver-Blood":{"aff":15,"type":"suspicious","relation":"employer","note":"Employer whose unsettling compliments about her appearance make her uncomfortable","worst":"His pointed remarks about her looks and marriage"},"Betrid Silver-Blood":{"aff":10,"type":"professional","relation":"employer","note":"Harsh and critical employer who belittles her work and calls her useless","worst":"Being told she is useless and made to feel small"},"Yngvar":{"aff":35,"type":"admirer","relation":"fellow resident","note":"Fellow Treasury House resident whose singing she quietly enjoys"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rhorlak', '{"Rigel Strong-Arm":{"aff":35,"type":"professional","relation":"crew leader","note":"Direct superior in the Pinewatch operation; receives written instructions from her","best":"Trusted enough to serve as the operation''s front man","worst":"Loyalty extends only to gold, not to her personally"},"Endon":{"aff":-30,"type":"enemy","relation":"theft victim","note":"Markarth silversmith whose stolen silver mold Rhorlak helps conceal","worst":"Slip of the tongue revealed knowledge of Endon''s profession"},"Pinewatch Bandits":{"aff":20,"type":"professional","relation":"fellow crew","note":"Criminal associates in the Pinewatch gang; loyalty is to profit over comrades"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ri''saad', '{"Atahbah":{"aff":40,"type":"protective","relation":"caravan member","note":"Manages her moon sugar addiction with firm compassion","worst":"Her addiction constantly threatens caravan discipline and reputation"},"Khayla":{"aff":60,"type":"professional","relation":"caravan guard","note":"Trusted protector who helps keep the caravan safe"},"Ma''randru-jo":{"aff":55,"type":"professional","relation":"caravan trader","note":"Loyal and reliable member of the caravan"},"Ma''dran":{"aff":50,"type":"professional","relation":"subordinate caravan leader","note":"Operates a caravan under Ri''saad''s wider trading network"},"Ahkari":{"aff":50,"type":"professional","relation":"subordinate caravan leader","note":"Runs eastern Skyrim caravan operations under Ri''saad''s authority"},"J''datharr":{"aff":-75,"type":"contempt","relation":"Thalmor spy","note":"Despises him as Thalmor filth giving all Khajiit a bad name","worst":"A Thalmor agent hiding among Khajiit and dishonoring their people"},"Tonilia":{"aff":35,"type":"transactional","relation":"Thieves Guild fence","note":"New alliance formed for mutual profit in fencing stolen goods"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ria', '{"Kodlak":{"aff":78,"type":"mentor","relation":"childhood hero and advisor","note":"Grew up on legendary tales of Kodlak''s battles; his stories inspired her to join the Companions.","best":"Hearing tales of Kodlak fighting off a hundred Orc berserkers as a child"},"Skjor":{"aff":72,"type":"mentor","relation":"childhood hero","note":"Admired Skjor''s legendary battles since childhood; devastated by his fall to the Silver Hand.","best":"Skjor modestly downplaying his own legendary feats","worst":"Learning of Skjor''s death at the hands of the Silver Hand"},"Vilkas":{"aff":55,"type":"mentor","relation":"trainer and shield-brother","note":"Vilkas patiently trains her in longer blades; she respects his guidance despite finding the weapons slow.","best":"Vilkas explaining that the greatsword will eventually feel faster with practice"},"Aela":{"aff":50,"type":"curious","relation":"shield-sister","note":"Wants to train with Aela, believing their fighting styles are similar, but is redirected to Vilkas.","best":"Asking to train with Aela out of admiration for her style"},"The Companions":{"aff":85,"type":"fanatical","relation":"shield-family","note":"Views the Companions as her purpose and family; joined as a childhood dream and defines herself through their legacy.","best":"Being accepted as the newest Companion after proving her worth","worst":"Fearing she might never see Sovngarde but still having her place in the line"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('riekling_chief', '{"Riekling Tribe":{"aff":80,"type":"protective","relation":"tribal subjects","note":"Deeply committed to strengthening and protecting his people","best":"Led tribe to conquer Thirsk Mead Hall as permanent home"},"Thirsk Nords":{"aff":-75,"type":"enemy","relation":"displaced foes","note":"Drove the Nord inhabitants from their ancestral hall","worst":"Led the massacre that claimed Thirsk Mead Hall"},"Bilgemuck":{"aff":55,"type":"protective","relation":"prized tribal beast","note":"Values the beast and actively seeks to reclaim it"},"Player Character":{"aff":10,"type":"suspicious","relation":"potential ally","note":"Views outsiders with mixed suspicion and pragmatic respect"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rift_guard', '{"Maven Black-Briar":{"aff":15,"type":"servant","relation":"de facto employer","note":"Serves her preferred status quo; loyalty is pragmatic survival rather than devotion","worst":"Knowing any misstep could end a career or a life at her whim"},"Thieves Guild":{"aff":-10,"type":"transactional","relation":"bribe source","note":"Selective enforcement in exchange for coin and quiet; mutual tolerance rather than trust","best":"Gold passed hands smoothly and both sides kept their distance","worst":"Being forced to ignore a crime that went too far"},"Fellow Guards":{"aff":55,"type":"platonic","relation":"comrades","note":"Strong camaraderie forged through shared hardship and shared compromises","best":"Standing together after a brutal bandit skirmish","worst":"Silently agreeing to look the other way"},"Local Citizens":{"aff":25,"type":"professional","relation":"ward","note":"Respectful distance maintained through regular patrols; genuine concern tempered by cynicism"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('riften_guard', '{"Jarl Laila Law-Giver":{"aff":30,"type":"professional","relation":"Jarl","note":"Ceremonial loyalty to their Jarl, though her actual authority over the guard is limited by Maven''s influence"},"Maven Black-Briar":{"aff":-10,"type":"suspicious","relation":"shadow authority","note":"Cannot ignore her influence; she effectively controls Riften regardless of who holds the Jarl''s seat","worst":"Knowing Maven''s reach makes it impossible to enforce the law impartially"},"Thieves Guild":{"aff":5,"type":"transactional","relation":"criminal organization","note":"Publicly dismissed as vermin, privately tolerated through selective enforcement and bribery","best":"Occasional tips and cooperation that help maintain order","worst":"A guard was revealed to be on the Guild''s payroll during the toll extortion"},"Fellow Guards":{"aff":65,"type":"platonic","relation":"brotherhood","note":"Strong bonds forged through shared duty and danger, despite knowing some are corrupt"},"City Watch Captain":{"aff":45,"type":"professional","relation":"supervisor","note":"Direct supervisor who understands the need for pragmatic law enforcement in Riften"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('riften_guard_jailor', '{"Laila Law-Giver":{"aff":50,"type":"professional","relation":"jarl","note":"Loyal servant to the Jarl, respects her authority"},"Maven Black-Briar":{"aff":-25,"type":"suspicious","relation":"influential citizen","note":"Aware of her corrupting influence but maintains professional distance","worst":"Witnessed Riften''s descent into corruption under her sway"},"Thieves Guild":{"aff":-65,"type":"enemy","relation":"criminal organization","note":"Natural adversaries, though maintains official ignorance of their activities","worst":"Watched the city fall to their corruption"},"Riften Guards":{"aff":45,"type":"professional","relation":"fellow guards","note":"Respected among peers for integrity and incorruptibility"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rigel_strong-arm', '{"Father":{"aff":30,"type":"estranged","relation":"father","note":"Maintains correspondence despite his disapproval of her bandit career","best":"His continued letters showing he still cares about her","worst":"His persistent disapproval of her chosen path"},"Bandit Followers":{"aff":45,"type":"professional","relation":"followers","note":"Commands loyalty through strength, fear, and strategic leadership","best":"Their obedience when her plans succeed and wealth flows","worst":"The constant need to maintain discipline through intimidation"},"Rival Bandit Groups":{"aff":-50,"type":"rival","relation":"competitors","note":"Has displaced or dominated competing bandit operations in the region"},"Law Enforcement":{"aff":-70,"type":"enemy","relation":"adversaries","note":"Active enemies seeking to end her criminal operation at Pinewatch"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rin', '{"Jonquil":{"aff":90,"type":"familial","relation":"mother","note":"His spirit seeks reunion with her in death","best":"Living together at Goldenhills Plantation","worst":"Separated from her by his death at the well"},"Urval":{"aff":90,"type":"familial","relation":"father","note":"His spirit seeks reunion with him in death","best":"Living together at Goldenhills Plantation","worst":"Separated from him by his death at the well"},"Dragonborn":{"aff":75,"type":"grateful","relation":"savior","note":"Returned his wooden sword and laid his family to rest","best":"Being reunited with his parents'' spirits and finding peace"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rirns_llervu', '{"Captain Veleth":{"aff":-25,"type":"estranged","relation":"former commanding officer","note":"Discharged Rirns for abandoning his post during the ash spawn attack","worst":"Being stripped of his guard position for cowardice"},"Councilor Morvayn":{"aff":65,"type":"grateful","relation":"benefactor","note":"Allowed Rirns to remain in Raven Rock despite his disgrace","best":"Being shown mercy and permitted to stay"},"Bralsa Drel":{"aff":55,"type":"platonic","relation":"friend and mentor","note":"Fellow outcast who taught him mining after the mine reopened","best":"Learning to swing a pickaxe and finding purpose again"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rissing', '{"Hircine":{"aff":85,"type":"fanatical","relation":"devotee","note":"Reveres Hircine and seeks validation through the Great Hunt","best":"Chosen to participate in Hircine''s Great Hunt"},"Sinding":{"aff":-95,"type":"nemesis","relation":"quarry","note":"Primary target whose werewolf nature embodies Rissing''s deepest hatred","worst":"Family slaughtered by a werewolf, scarring him for life"},"Fellow Hunters":{"aff":35,"type":"professional","relation":"hunting party","note":"Temporary allies in the Great Hunt, kept at professional distance"},"Bandit Associates":{"aff":15,"type":"transactional","relation":"associates","note":"Loose criminal connections, secondary to his hunting pursuits"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ritual_master', '{"Potema Septim":{"aff":85,"type":"obsessed","relation":"object of devotion","note":"Fanatically devoted to resurrecting the Wolf Queen, bordering on religious fervor","best":"Discovered the ancient texts detailing the ritual to resurrect Potema","worst":"Potema''s spirit rejected the binding, calling them fools and ants"},"Necromancer Followers":{"aff":40,"type":"professional","relation":"cult leader","note":"Maintains iron control over devoted cultists through magical prowess and charisma"},"College of Winterhold":{"aff":-65,"type":"estranged","relation":"former institution","note":"Expelled for forbidden necromantic research, seeks to prove their rejection was a mistake","worst":"Expelled for delving too deeply into forbidden necromancy and Potema''s history"},"Local Nobles":{"aff":15,"type":"transactional","relation":"secret contacts","note":"Provide resources and protection; nature of their exchange remains hidden"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('roadside_guard', '{"Imperial Legion":{"aff":75,"type":"professional","relation":"sworn soldier","note":"Loyal member seeking recognition and advancement through exemplary service"},"Loreius Farm residents":{"aff":15,"type":"protective","relation":"assigned protectees","note":"Maintains professional oversight of their safety along patrol route"},"Stormcloak sympathizers":{"aff":-30,"type":"suspicious","relation":"occupied populace","note":"Tense but professional interactions with former sympathizers in conquered territory"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rochelle_the_red', '{"Bandit Confederates":{"aff":65,"type":"professional","relation":"followers","note":"Loyal network assisting kidnapping operations across multiple holds"},"Local Guards":{"aff":-70,"type":"enemy","relation":"adversaries","note":"Actively hunt her across Skyrim''s holds"},"Fence Contacts":{"aff":25,"type":"transactional","relation":"fences","note":"Launder ransom payments from kidnapping operations"},"Merchant Parents":{"aff":-40,"type":"estranged","relation":"parents","note":"Rejected their legitimate trading business in Hammerfell"},"Player":{"aff":-50,"type":"enemy","relation":"ransom target","note":"Kidnaps player''s spouse demanding 5,000 gold ransom","worst":"Kidnapped my spouse for ransom"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rogatus_salvius', '{"Vigdis":{"aff":60,"type":"familial","relation":"wife","note":"Gruff and dismissive outwardly but fiercely protective; she patiently endures his pessimism after 50 years of marriage","best":"Standing together through decades of hardship on the farm","worst":"Dismissing her attempts at warmth and socializing with his constant gloom"},"Leontius Salvius":{"aff":25,"type":"estranged","relation":"son","note":"Bitterly calls him a drunk and a failure; secretly hopes to reconcile but too proud to reach out directly","best":"Raising him on the family farm before he left","worst":"Leontius leaving for Old Hroldan and never visiting"},"Forsworn":{"aff":-80,"type":"enemy","relation":"raiders","note":"Constant threat to his livelihood; has survived multiple raids over the decades","worst":"Forsworn raids threatening the farm and his family''s safety"},"Markarth merchants":{"aff":10,"type":"transactional","relation":"buyers","note":"Purely business relationships for selling crops; no warmth or trust extended"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('roggi_knot-beard', '{"Iddra":{"aff":25,"type":"indebted","relation":"barkeep, creditor","note":"Friendly but strained due to his substantial unpaid tavern tab at Braidwood Inn","worst":"Watching his debt to her grow with each round of mead"},"Dravynea the Stoneweaver":{"aff":65,"type":"platonic","relation":"close friend, colleague","note":"Deeply respects her for keeping the mine safe and operational","best":"Working alongside her in the mine, trusting her expertise"},"Ganna Uriel":{"aff":55,"type":"platonic","relation":"friend, fellow miner","note":"Friendly colleague at Steamscorch Mine"},"Kjeld":{"aff":45,"type":"professional","relation":"employer, drinking companion","note":"Boss at the mine who tolerates but is sometimes exasperated by Roggi''s mead obsession","best":"Sharing drinks and banter at the inn after work","worst":"Kjeld''s dismissive ''Again with the mead!'' reactions"},"Ancestors":{"aff":70,"type":"familial","relation":"warrior forebears","note":"Maintains strong spiritual connection to his family''s warrior heritage through their ancestral shield","best":"Recovering the ancestral shield and honoring their legacy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('roggvir', '{"Greta":{"aff":80,"type":"familial","relation":"sister","note":"Believed in his innocence and defended his actions to others","best":"She stood by him when no one else would","worst":"Helpless to stop his execution"},"Svari":{"aff":70,"type":"familial","relation":"niece","note":"Young girl who idolized her uncle and couldn''t accept his condemnation","best":"She cried out in his defense at the execution","worst":"Watching him beheaded while the crowd jeered"},"Captain Aldis":{"aff":-15,"type":"professional","relation":"executioner","note":"Carried out the execution with cold duty but allowed Roggvir his dignity","best":"Let him bow his head unassisted","worst":"Condemned him as a traitor before the crowd"},"Ulfric Stormcloak":{"aff":40,"type":"admirer","relation":"man he aided","note":"Roggvir respected Ulfric''s traditional challenge more than the man himself","best":"Believed his duel with Torygg honored Nordic custom","worst":"His escape led directly to Roggvir''s execution"},"Citizens of Solitude":{"aff":-65,"type":"enemy","relation":"former community","note":"Most viewed him as a traitor who betrayed his High King","best":"A few understood his adherence to tradition","worst":"Jeered and booed at his execution, calling him scum and traitor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rolff_stone-fist', '{"Galmar Stone-Fist":{"aff":25,"type":"estranged","relation":"brother","note":"Rarely interacts with his accomplished brother, likely harboring inferiority","worst":"Living in Galmar''s shadow while his brother rose to prominence"},"Angrenor Once-Honored":{"aff":45,"type":"platonic","relation":"drinking companion","note":"Fellow drunk and partner in harassing Dark Elves","best":"Bullying Suvaris Atheron together in the streets of Windhelm"},"Suvaris Atheron":{"aff":-85,"type":"contempt","relation":"harassment target","note":"Primary target of his racist abuse and threats","worst":"Threatening to round up Dunmer for interrogation"},"Dunmer of Windhelm":{"aff":-90,"type":"enemy","relation":"hated outsiders","note":"Views them as parasites and potential Imperial spies","worst":"Suggesting they be thrown into a mass grave with Argonians"},"Argonians":{"aff":-85,"type":"enemy","relation":"hated outsiders","note":"Hates them nearly as much as the Dunmer, calls them scale-backs","worst":"Glad they were kicked outside the city walls"},"Ulfric Stormcloak":{"aff":60,"type":"admirer","relation":"ideological supporter","note":"Strongly supports the Stormcloak cause but has no direct relationship with Ulfric"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('romlyn_dreth', '{"Indaryn":{"aff":-50,"type":"rival","relation":"supervisor","note":"Indaryn suspects Romlyn of theft; Romlyn resents his authority and calls him a s''wit behind his back","worst":"Indaryn confronted him about missing mead cases and threatened Maven''s wrath if proven"},"Wilhelm":{"aff":45,"type":"transactional","relation":"smuggling buyer","note":"Trusted contact in Ivarstead who purchases stolen Black-Briar mead","best":"Successful keg deliveries completed without detection"},"Maven Black-Briar":{"aff":-15,"type":"suspicious","relation":"employer","note":"Steals from her meadery while maintaining a cautiously respectful facade out of fear","worst":"Knowing Maven would have him killed if she discovered his smuggling"},"Niluva Hlaalu":{"aff":25,"type":"platonic","relation":"coworker","note":"Fellow meadery worker who shares grievances about Indaryn''s heavy hand"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rondach', '{"Voada":{"aff":85,"type":"protective","relation":"sister","note":"Fellow kitchen worker whom he fiercely defends against Anton''s abuse","best":"Threatened Anton when he menaced her fingers","worst":"Watching her endure Anton''s daily cruelty and insults"},"Anton Virane":{"aff":-75,"type":"fearful","relation":"abusive superior","note":"Tyrannical kitchen master who rules through threats and verbal abuse","worst":"Anton threatening to cut off Voada''s fingers"},"Ainethach":{"aff":55,"type":"familial","relation":"father","note":"Respected landlord of Karthwasten; Rondach may hope to return near him someday"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ronthil', '{"Feran Sadri":{"aff":45,"type":"servant","relation":"assistant","note":"Eagerly serves Feran despite frequent dismissal and annoyance","best":"Feran is so good to me, allowing me to be his assistant","worst":"Told to stop asking if Feran needs anything"},"Lord Harkon":{"aff":70,"type":"fanatical","relation":"devoted servant","note":"Serves his ultimate master with utmost devotion and reverence"},"Vingalmo":{"aff":10,"type":"servant","relation":"subordinate","note":"Tries to offer service but is treated with open contempt","worst":"Called a worm and told there is no reason for them to speak"},"Garan Marethi":{"aff":30,"type":"professional","relation":"subordinate","note":"Takes on tasks Garan finds beneath him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rorik', '{"Jouane Manette":{"aff":90,"type":"platonic","relation":"closest friend","note":"Healer who saved his life during the Great War; they now share a manor in Rorikstead","best":"Jouane pulled me back from death''s door when an Aldmeri blade ran me through","worst":"Lying near death on the battlefield before Jouane could reach me"},"Erik the Slayer":{"aff":60,"type":"protective","relation":"surrogate ward","note":"Shows paternal concern for the young man''s welfare and future"},"Imperial Legion":{"aff":55,"type":"professional","relation":"former commander","note":"Served with distinction during the Great War; retains loyalty to the Empire"},"Aldmeri Dominion":{"aff":-85,"type":"enemy","relation":"wartime enemy","note":"An Aldmeri soldier nearly killed him, leaving a wound that still affects him","worst":"An Aldmeri soldier ran me through with his blade and left me for dead"},"Rorikstead Farmers":{"aff":45,"type":"protective","relation":"tenants and community","note":"Feels deep responsibility for the people and prosperity of the settlement he built"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rorlund', '{"Freir":{"aff":85,"type":"romantic","relation":"wife","note":"Devoted partner who shares his religious duties and life''s work at the temple"},"Silana Petreia":{"aff":70,"type":"mentor","relation":"adopted ward","note":"Rescued her from the streets; respects her independent views despite philosophical disagreements on charity","best":"Welcomed her into our home and gave her a life beyond the streets","worst":"Her insistence that the wealthy owe more to the poor challenges my convictions on self-reliance"},"Imperial Authority":{"aff":15,"type":"professional","relation":"Imperial oversight","note":"Must carefully navigate Talos worship restrictions while maintaining his position as high priest of the Eight Divines"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ruki', '{"Fenrig":{"aff":100,"type":"romantic","relation":"husband","note":"Eternally devoted, searched for him for centuries after both perished","best":"Reunited and ascended to the stars together forever","worst":"Centuries of agonizing separation searching among the fallen"},"Dragonborn":{"aff":55,"type":"grateful","relation":"reuniter","note":"Asked for help finding Fenrig, initially dismissed uncomfortable truths","best":"Brought Fenrig to her so they could be together","worst":"Questioned her perception and the reality of the bodies around her"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rulindil', '{"Elenwen":{"aff":65,"type":"professional","relation":"superior","note":"Serves the First Emissary with unwavering loyalty as Third Emissary"},"Gissur":{"aff":-25,"type":"transactional","relation":"informant","note":"Finds him useful but personally offensive and disposable","worst":"Threatened to throw Gissur into a cell with his victim when he asked for payment"},"Etienne Rarnis":{"aff":-80,"type":"enemy","relation":"prisoner","note":"Personally and repeatedly tortures him for information on Esbern''s location","worst":"Resumed torture even after Etienne cooperated, expressing disappointment in his lack of further information"},"Embassy Guards":{"aff":25,"type":"professional","relation":"subordinates","note":"Commands guards who assist in interrogations and maintain dungeon security"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rulnik_wind-strider', '{"Danica Pure-Spring":{"aff":75,"type":"indebted","relation":"healer","note":"Primary healer who oversaw his recovery at the Temple of Kynareth","best":"Survived thanks to her dedicated care"},"Temple of Kynareth":{"aff":70,"type":"grateful","relation":"sanctuary","note":"Deeply respects the temple after they saved his life","best":"Given sanctuary and healing when near death"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('runa_fair-shield', '{"Grelod the Kind":{"aff":-95,"type":"fearful","relation":"abusive caretaker","note":"Deeply fears and resents Grelod''s cruelty toward the orphans","best":"Cheered elatedly at Grelod''s assassination","worst":"Received double beatings after Aventus escaped"},"Constance Michel":{"aff":65,"type":"protective","relation":"kind caretaker","note":"The only adult who tries to shield the children from Grelod''s abuse","best":"Constance intervenes when Grelod accuses Runa of stealing"},"Aventus Aretino":{"aff":55,"type":"platonic","relation":"former fellow orphan","note":"Remembers him as nice, quiet, and sad after his mother died","best":"His Dark Brotherhood contract freed the orphans from Grelod"},"Samuel":{"aff":40,"type":"platonic","relation":"fellow orphan","note":"Shared news of Aventus''s plan to have Grelod killed"},"Hroar":{"aff":35,"type":"platonic","relation":"fellow orphan","note":"Shares the harsh daily life at Honorhall"},"Francois":{"aff":35,"type":"platonic","relation":"fellow orphan","note":"Shares the harsh daily life at Honorhall"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rundi', '{"Borvir":{"aff":65,"type":"familial","relation":"twin brother","note":"Business partners who rarely agreed but shared the same dream","best":"Planning Frost River Farm meadery together","worst":"Frequent disagreements over specifics"},"Phinis Gestor":{"aff":20,"type":"professional","relation":"instructor","note":"Skeptical of their frost mead research","worst":"Dismissed their work as a waste"},"Savos Aren":{"aff":70,"type":"grateful","relation":"patron","note":"Supported their research despite faculty doubts","best":"Granted permission to pursue frost mead experiments"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rune', '{"Brynjolf":{"aff":78,"type":"mentor","relation":"recruiter and mentor","note":"Caught Rune pickpocketing him but chose to recruit him instead; Rune is deeply grateful","best":"Given a place and purpose in the Guild after being caught rather than turned in","worst":"The humiliation of failing to pick his pocket"},"Adoptive Father":{"aff":75,"type":"familial","relation":"adoptive father","note":"Fisherman who rescued him from a shipwreck and raised him; Rune stole to support the family","best":"Taken in and cared for as a boy with no identity"},"College of Winterhold":{"aff":15,"type":"transactional","relation":"consulted scholars","note":"Spent countless septims consulting them about the runed stone with no results","worst":"Every coin wasted on scholars who could not decipher the stone"},"Vex":{"aff":45,"type":"professional","relation":"guild colleague","note":"Respects her expertise and takes jobs from her"},"Delvin":{"aff":45,"type":"professional","relation":"guild colleague","note":"Respects his expertise and takes jobs from him"},"Thieves Guild":{"aff":72,"type":"protective","relation":"guild family","note":"Grateful for purpose and belonging; views the Cistern as home","best":"Accepted into a brotherhood that gave his life meaning"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('runil', '{"Kust":{"aff":65,"type":"professional","relation":"assistant","note":"Trusted helper who tends the cemetery alongside Runil and accepted him despite his past","best":"Kust accepted him as one of their own when he came to Falkreath"},"Dengeir":{"aff":55,"type":"admirer","relation":"former Jarl","note":"Respects him far more than the current Jarl and believes he deserves better treatment"},"Jarl Siddgeir":{"aff":-30,"type":"contempt","relation":"Jarl","note":"Disapproves of his leadership and how he treats his uncle Dengeir"},"Thalmor":{"aff":-80,"type":"fearful","relation":"former employers","note":"Former battlemage who fled their cause after witnessing atrocities; now hides from their agents","worst":"Committed unspeakable acts under their banner during the Great War"},"Thadgeir":{"aff":45,"type":"platonic","relation":"townsman","note":"Trusts Runil to perform proper rites for his fallen war companion Berit"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('rustleif', '{"Seren":{"aff":92,"type":"romantic","relation":"wife","note":"Pregnant Redguard wife and co-owner of the forge; he seeks Redguard lore to help their child connect with her heritage","best":"She insists on smithing alongside him even while with child","worst":"She worries about raising their child amid Skyrim''s war and urges moving to Hammerfell"},"Dawnstar Guards":{"aff":45,"type":"professional","relation":"clients","note":"Primary weapons supplier to the local guard force"},"Beitild":{"aff":15,"type":"rival","relation":"business rival","note":"Runs the local iron mine; competitive business relationship in Dawnstar"},"Silus Vesuius":{"aff":-15,"type":"suspicious","relation":"townsman","note":"Disturbed by his collection of Mythic Dawn artifacts in Dawnstar","worst":"Can''t believe Silus displays Mythic Dawn relics right in town"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('saadia', '{"Hulda":{"aff":45,"type":"professional","relation":"employer","note":"Provides sanctuary and employment at The Bannered Mare","best":"Given honest work and a place to hide in Whiterun"},"Alik''r Warriors":{"aff":-85,"type":"enemy","relation":"pursuers","note":"Mercenary soldiers hunting her as a fugitive from Hammerfell","worst":"Forced to flee homeland under threat of capture"},"Kematu":{"aff":-90,"type":"nemesis","relation":"lead pursuer","note":"Leader of the Alik''r seeking her capture for alleged treason","worst":"Hunted across provinces; faces treason charges if caught"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sabine_nytte', '{"Captain of the Red Wave":{"aff":65,"type":"professional","relation":"captain","note":"Rose to first mate through proven loyalty and capability in pirate operations"},"Ship''s Crew":{"aff":20,"type":"contempt","relation":"subordinates","note":"Maintains authority through intimidation and dismissive treatment"},"Erikur":{"aff":35,"type":"transactional","relation":"business contact","note":"Erikur directs buyers to her for Balmora Blue, suggesting an established arrangement"},"Solitude Guard":{"aff":-25,"type":"suspicious","relation":"law enforcement","note":"Mutual distrust likely mitigated by bribery to protect her illegal trade"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sabjorn', '{"Maven Black-Briar":{"aff":-85,"type":"nemesis","relation":"business rival","note":"Refused her buyout offer; she orchestrated his complete downfall through the Thieves Guild","worst":"She destroyed everything he built rather than tolerate competition"},"Mallus Maccius":{"aff":-40,"type":"contempt","relation":"indentured assistant","note":"Keeps Mallus in debt bondage as cheap labor and openly belittles him","worst":"Called him lazy and good-for-nothing while exploiting his unpaid debt"},"Eimar":{"aff":-10,"type":"professional","relation":"assistant","note":"Employee at the meadery; likely subjected to similar dismissive treatment"},"Captain of the Guard":{"aff":30,"type":"transactional","relation":"potential client","note":"Desperate to impress him with the Honningbrew Reserve tasting to secure a lucrative contract","best":"Securing the Captain''s business would validate his meadery against Black-Briar"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sabre_cat', '{}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('saden', '{"Local Sailors":{"aff":-55,"type":"contempt","relation":"prey","note":"Views them solely as marks for magical ambush and robbery near Horker Island."},"Windhelm Guard":{"aff":-40,"type":"fearful","relation":"pursuers","note":"Actively avoids their patrols and investigations into his banditry."},"Fellow Bandits":{"aff":-25,"type":"suspicious","relation":"rejected allies","note":"Refused alliance offers, convinced they would betray him or steal his hoard."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('saerlund', '{"Laila Law-Giver":{"aff":-65,"type":"estranged","relation":"mother","note":"Stripped his inheritance and had him treated for mental illness over his Imperial sympathies","best":"Raised in luxury within Mistveil Keep as a Jarl''s son","worst":"Shunned and incarcerated him like a common criminal for speaking his mind"},"Harrald":{"aff":-50,"type":"estranged","relation":"brother","note":"Once inseparable, now bitterly divided; Harrald calls him traitor yet admits he cares little for the war himself","best":"Used to fight back to back, letting nothing stand in their way","worst":"Harrald said he would have his own flesh and blood hanged to secure his position as next Jarl"},"Ulfric Stormcloak":{"aff":-85,"type":"enemy","relation":"political opponent","note":"Despises Ulfric as a selfish liar who masks his lust for power with a rallying cry of freedom","worst":"Ulfric''s propaganda has turned his own family against him"},"Wylandriah":{"aff":-35,"type":"suspicious","relation":"court wizard","note":"Tasked by Laila to diagnose and treat his supposed illness, complicit in his gaslighting"},"Mistveil Keep Staff":{"aff":-25,"type":"contempt","relation":"keep staff","note":"Hostile toward him and known to push him around"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('saffir', '{"Amren":{"aff":-25,"type":"estranged","relation":"husband","note":"Marriage deeply strained by his costly quest for his father''s sword and their conflicting values","worst":"Gave ultimatum that she would leave if he continued pursuing the sword"},"Braith":{"aff":35,"type":"familial","relation":"daughter","note":"Wishes Braith would read more instead of fighting, but is emotionally distant and dismissive","best":"Wants her daughter to be self-sufficient through education","worst":"Repeatedly dismissed Braith when she tried to talk about a boy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('safia', '{"Red Wave Crew":{"aff":55,"type":"protective","relation":"crew","note":"Commands fierce loyalty through fear, respect, and proven leadership"},"Dorian":{"aff":10,"type":"dismissive","relation":"crew member","note":"New recruit who actively avoids her"},"Dark Brotherhood":{"aff":-70,"type":"contempt","relation":"recurring assassins","note":"Views assassination attempts as predictable occupational hazard","worst":"Yet another contract placed on her life"},"East Empire Company":{"aff":-35,"type":"rival","relation":"smuggling target","note":"Occasional target of her smuggling operations"},"Erikur":{"aff":15,"type":"transactional","relation":"rumored client","note":"Thane rumored to deal with the Red Wave for contraband"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sahloknir', '{"Alduin":{"aff":90,"type":"servant","relation":"master and resurrector","note":"Commands absolute loyalty; Sahloknir responded to resurrection with immediate submission and gratitude","best":"Raised from eternal death by Alduin''s Thu''um"},"Ancient Nordic Heroes":{"aff":-85,"type":"enemy","relation":"slayers","note":"Killed him during the Dragon War; his hatred for mankind stems from this defeat","worst":"Slain and buried near Kynesgrove for millennia"},"Last Dragonborn":{"aff":-75,"type":"enemy","relation":"destined adversary","note":"Fought and was slain by the Dragonborn at Kynesgrove shortly after resurrection","worst":"Cut down by mortal Dragonblood mere moments after being restored to life"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sailor', '{"Ship Captain":{"aff":55,"type":"professional","relation":"commanding officer","note":"Direct superior aboard vessel; respects the chain of command"},"Fellow Sailors":{"aff":60,"type":"platonic","relation":"crewmates","note":"Close-knit bond forged through shared hardship at sea"},"East Empire Company":{"aff":30,"type":"transactional","relation":"employer","note":"Occasional source of maritime work and pay"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('saliah', '{"Isran":{"aff":55,"type":"professional","relation":"commanding officer","note":"Trusts her with vital supply operations; she is driven to prove her worth to him","best":"Being entrusted with the Dawnguard''s covert supply network","worst":"Fearing her bandit past might undermine his confidence in her"},"Dawnguard":{"aff":65,"type":"protective","relation":"faction","note":"Found redemption and purpose through the organization; fiercely loyal to their cause","best":"Being accepted into the Dawnguard despite her bandit origins","worst":"The constant pressure of maintaining a flawless supply network"},"Volkihar Vampires":{"aff":-85,"type":"enemy","relation":"sworn enemy","note":"Will kill on sight; dedicated to their complete eradication from Skyrim"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('salma', '{"Father":{"aff":65,"type":"familial","relation":"father","note":"His warnings about Beem-Ja proved prophetic","best":"Protective parent who tried to steer her right","worst":"She dismissed his warnings in her eagerness for adventure"},"Beem-Ja":{"aff":-50,"type":"betrayed","relation":"former guardian","note":"Looked after her since childhood, then betrayed her at Ironbind Barrow","best":"Cared for her since she was knee-high to him","worst":"Revealed his true colors and attacked after Gathrik''s defeat"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('salonia_caelia', '{"Vingalmo":{"aff":35,"type":"patron","relation":"patron and handler","note":"Serves as his operative in court power struggles, but loyalty is purely transactional","best":"Recruited into Clan Volkihar and given purpose and standing","worst":"Knows her service is merely a tool for his ambition, not genuine regard"},"Stalf":{"aff":-65,"type":"rival","relation":"rival operative","note":"Orthjolf''s agent and direct competitor; both were ordered to eliminate each other","worst":"Betrayed each other at Redwater Den when their mutual duplicity was revealed"},"Orthjolf":{"aff":-45,"type":"rival","relation":"opposing faction leader","note":"Vingalmo''s chief rival; she works to undermine his influence in the court"},"Lord Harkon":{"aff":15,"type":"neutral","relation":"nominal lord","note":"Acknowledges his authority but holds no personal loyalty beyond what serves her interests"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('salonia_carvain', '{"Plautis Carvain":{"aff":-10,"type":"transactional","relation":"husband","note":"Marriage of convenience; she resents being dragged to Skyrim for his business dealings","worst":"Complained about ruined shoes while he reeled off their misfortunes including their bodyguard''s death"},"Vittoria Vici":{"aff":25,"type":"admirer","relation":"social target","note":"Seeks her favor to secure an import deal and audience with the Emperor, but never actually meets her"},"Bodyguard":{"aff":-5,"type":"transactional","relation":"hired protection","note":"Showed no concern whatsoever when the bodyguard was eaten by a dragon","worst":"Bodyguard devoured by dragon; she only mourned her shoes"},"Nords of Skyrim":{"aff":-80,"type":"contempt","relation":"despised locals","note":"Views all Nords and Skyrim itself as barbaric and beneath her station","worst":"Called them Skyrim trash and wished to hire battlemages to burn the entire province"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('salvianus', '{"Unknown Imperial Officer":{"aff":35,"type":"mentor","relation":"commanding officer","note":"Haunting figure who explained everything before his mind fractured; Salvianus still clings to his words","best":"He explained it all to me, when I still understood","worst":"His words now echo only through madness, unreachable"},"Thalmor":{"aff":-85,"type":"fearful","relation":"wartime enemy","note":"Objects of continued paranoid terror from the Great War and fall of the Imperial City","worst":"No, you can''t be here! You''re all dead! I already killed you over and over!"},"Imperial Legion":{"aff":15,"type":"estranged","relation":"former military","note":"Served with distinction but discarded his medal and fled from everything it represented","best":"Received a medal for service in defense of the Imperial City","worst":"Threw away his medal, unable to reconcile honor with trauma"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sam_guevenne', '{"The Last Dragonborn":{"aff":55,"type":"platonic","relation":"drinking companion and test subject","note":"Targeted for a night of debauchery; rewarded with the Sanguine Rose for being entertaining company","best":"Shared a legendary drinking contest and wild night across Skyrim","worst":"Left them with a catastrophic hangover and chaos to clean up across multiple holds"},"Deep-In-His-Cups":{"aff":15,"type":"curious","relation":"pawn in drunken prank","note":"Dared him to steal a hat from a bandit camp during a night of revelry"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('samuel', '{"Grelod the Kind":{"aff":-90,"type":"enemy","relation":"tormentor","note":"Abusive headmistress whom Samuel secretly hopes will be killed","worst":"Forced to declare love and gratitude to the woman who beats and belittles them daily"},"Aventus Aretino":{"aff":75,"type":"platonic","relation":"closest friend","note":"Fellow orphan who escaped to perform the Black Sacrament to summon the Dark Brotherhood against Grelod","best":"Aventus''s daring escape gave Samuel hope that Grelod''s tyranny could end"},"Constance Michel":{"aff":45,"type":"platonic","relation":"caretaker","note":"Kindlier orphanage worker whose protectiveness Samuel grudgingly appreciates","best":"Constance shows the children genuine kindness and concern for their safety"},"Runa":{"aff":60,"type":"platonic","relation":"fellow orphan","note":"Close-knit group of orphans who share hardships and look to Samuel as a leader"},"Hroar":{"aff":60,"type":"platonic","relation":"fellow orphan","note":"Close-knit group of orphans who share hardships and look to Samuel as a leader"},"Francois":{"aff":60,"type":"platonic","relation":"fellow orphan","note":"Close-knit group of orphans who share hardships and look to Samuel as a leader"},"Mother":{"aff":50,"type":"curious","relation":"deceased mother","note":"Died in childbirth at the orphanage; Samuel never knew her but clings to hope about his parentage"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sanctuary_guardian', '{"Sithis":{"aff":95,"type":"fanatical","relation":"divine master","note":"Soul eternally bound through unwavering devotion earned in life"},"Dark Brotherhood":{"aff":80,"type":"familial","relation":"brotherhood","note":"Devoted member in life, eternal guardian in death"},"Cicero":{"aff":40,"type":"servant","relation":"keeper","note":"Obedient to the Keeper''s commands within the sanctuary hierarchy"},"Night Mother":{"aff":75,"type":"awed","relation":"sacred figure","note":"Revered divine presence whose blessing sanctified these halls"},"Player":{"aff":-60,"type":"enemy","relation":"intruder","note":"Duty-bound to repel sanctuary invaders with lethal force","worst":"Forced into combat defending the sanctuary from invasion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sanguine', '{"The Last Dragonborn":{"aff":65,"type":"patron","relation":"chosen bearer","note":"Selected as bearer of the Sanguine Rose after a night of debauchery proved them entertaining","best":"I haven''t been so entertained in at least a hundred years"},"Clavicus Vile":{"aff":35,"type":"rival","relation":"fellow Daedric Prince","note":"Shares an appreciation for manipulating mortals, though their spheres differ in nature"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sanyon', '{"Eola":{"aff":65,"type":"fanatical","relation":"cult leader","note":"Devoted fellow worshipper of Namira who leads their Reachcliff Cave sanctuary"},"Nimphaneth":{"aff":50,"type":"platonic","relation":"fellow cultist","note":"Shares dark devotion and remains together at Reachcliff Cave after the feast"},"Namira":{"aff":85,"type":"fanatical","relation":"worshipped Prince","note":"Daedric Prince of Decay whose forbidden teachings he embraced completely","best":"Initiated into her cannibalistic cult and found purpose in her dark worship"},"Player":{"aff":55,"type":"admirer","relation":"Namira''s champion","note":"Greets with praise after The Taste of Death quest","best":"Welcomed the new disciple as champion of Namira at the feast"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sapphire', '{"Thieves Guild":{"aff":65,"type":"protective","relation":"guild family","note":"Her found family and source of purpose after losing everything"},"Shadr":{"aff":-15,"type":"transactional","relation":"debtor","note":"Owes her coin; she threatened him over the debt but can be persuaded to forgive it"},"Glover Mallory":{"aff":0,"type":"estranged","relation":"unknown father","note":"Her biological father in Raven Rock; she is unaware of the connection"},"Maven Black-Briar":{"aff":35,"type":"professional","relation":"patron","note":"Respects her iron grip on Riften''s underworld and Guild operations"},"Bandits":{"aff":-100,"type":"nemesis","relation":"former captors","worst":"Murdered her family, held her captive for weeks, subjected her to abuse"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sarthis_idren', '{"Maven Black-Briar":{"aff":15,"type":"rival","relation":"rival crime boss","note":"Uneasy mutual tolerance between competing criminal enterprises"},"Jarl of Riften":{"aff":-80,"type":"enemy","relation":"antagonist","note":"Primary opponent seeking to eliminate his skooma operation","worst":"Organizes raids on the warehouse to shut him down"},"Corrupt Riften Guards":{"aff":25,"type":"transactional","relation":"paid informants","note":"Bribed guards who tip him off about incoming raids","best":"Warned him ahead of Jarl-ordered raids"},"Warehouse Workers":{"aff":45,"type":"professional","relation":"employees","note":"Loyal inner circle who help distribute his product"},"Skooma Addicts":{"aff":-5,"type":"contempt","relation":"exploited customers","note":"Dependent addicts he views as revenue sources, not people"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('savos_aren', '{"Mirabelle Ervine":{"aff":65,"type":"professional","relation":"second-in-command","note":"Trusted with daily operations he avoids making decisions on","best":"Relies on her competence without question"},"Ancano":{"aff":15,"type":"professional","relation":"Thalmor advisor","note":"Fails to recognize his true motives until it is too late","worst":"Realized Ancano''s betrayal only as the Eye of Magnus consumed him"},"Tolfdir":{"aff":50,"type":"professional","relation":"senior faculty","note":"Respected colleague and long-standing instructor"},"Former Companions":{"aff":80,"type":"indebted","relation":"sacrificed friends","note":"Haunted by the spirits of those he left behind in Labyrinthian","worst":"Forced to bind their souls to contain the ancient threat"},"College of Winterhold":{"aff":70,"type":"protective","relation":"Arch-Mage","note":"Deeply committed to the institution''s survival despite delegating its management","best":"Hopes his work may one day earn Nords'' acceptance of the College"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sayma', '{"Beirand":{"aff":85,"type":"romantic","relation":"husband","note":"Deeply loving marriage; she speaks of him with pride and warmth to customers","best":"Building their life and business together in Solitude","worst":"Barely seeing him nowadays while he fills army orders at Castle Dour"},"Kayd":{"aff":80,"type":"familial","relation":"son","note":"Young son who spends time in the shop; she wants a stable future for him","best":"His spirited defense of the family business"},"Illdi":{"aff":65,"type":"platonic","relation":"friend","note":"Regular evening companion outside the Bards College after long shop hours"},"Greta":{"aff":65,"type":"platonic","relation":"friend","note":"Regular evening companion outside the Bards College after long shop hours"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('scavenger', '{"Local Bandits":{"aff":15,"type":"transactional","relation":"faction allies and occasional traders","note":"Keeps distance to avoid sharing spoils despite shared faction membership"},"Imperial Patrols":{"aff":-45,"type":"fearful","relation":"avoided authorities","note":"Actively avoids to prevent identification as a battlefield looter"},"Stormcloak Patrols":{"aff":-45,"type":"fearful","relation":"avoided authorities","note":"Actively avoids to prevent identification as a battlefield looter"},"Other Scavengers":{"aff":-65,"type":"rival","relation":"competitors","note":"Viewed as threats to be driven away or eliminated","worst":"Fought off rivals trying to claim his battlefield spoils"},"Local Merchants":{"aff":20,"type":"transactional","relation":"fences","note":"Cautious business relationships for offloading looted goods"}}')
