INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('scheming_servant', '{"Dark Brotherhood":{"aff":35,"type":"transactional","relation":"client","note":"Contracts assassinations through the Black Sacrament, knows little of their true organization"},"Night Mother":{"aff":45,"type":"fanatical","relation":"supplicant","note":"Performs the Black Sacrament ritual with practiced devotion to request kills"},"Understone Keep Staff":{"aff":10,"type":"suspicious","relation":"coworkers","note":"Maintains cordial distance while appearing friendly to preserve his cover"}}')
