INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('scouts-many-marshes', '{"Argonian Assemblage":{"aff":75,"type":"protective","relation":"chosen family","note":"Unofficial leader and advocate for the Argonian dock workers"},"Torbjorn Shatter-Shield":{"aff":-70,"type":"contempt","relation":"employer","note":"Underpays and devalues Argonian labor","worst":"Declared an Argonian''s labor worth a tenth of a proper Nord worker"},"Stands-In-Shallows":{"aff":65,"type":"platonic","relation":"close friend","note":"Fellow dock worker and trusted companion"},"Neetrenaza":{"aff":50,"type":"platonic","relation":"colleague","note":"Shares frustrations with Nordic discrimination"},"Shahvee":{"aff":45,"type":"platonic","relation":"colleague","note":"Fellow dock worker at the Assemblage"},"Ulfric Stormcloak":{"aff":-85,"type":"nemesis","relation":"oppressor","note":"Decreed Argonians forbidden from living inside Windhelm''s walls","worst":"Condemned Argonians to live in slums outside the city"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('seasoned_hunter', '{"Father":{"aff":80,"type":"familial","relation":"father and mentor","note":"Taught him hunting from an early age before being killed in a bandit raid","best":"Learning to track and shoot in Falkreath''s forests at his father''s side","worst":"Losing his father to the bandit raid that claimed his whole family"},"Bandits":{"aff":-95,"type":"nemesis","relation":"family killers","note":"The raid that murdered his family drove him into permanent reclusion","worst":"Returning to find his family slaughtered"},"Local Merchants":{"aff":10,"type":"transactional","relation":"trading partners","note":"Minimal contact for selling pelts and meat, kept brief by choice"},"Falkreath Guards":{"aff":5,"type":"suspicious","relation":"local law","note":"Keeps cautious distance while staying within the law"},"Fellow Hunters":{"aff":15,"type":"neutral","relation":"reluctant peers","note":"Occasionally cooperates during seasonal hunts but prefers solitude"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sebastian_lort', '{"Unnamed Daughter":{"aff":90,"type":"familial","relation":"daughter","note":"Became a werewolf through Hircine worship; Sebastian sought a cure that led to tragedy","best":"Peaceful life together before her transformation","worst":"Given the Rueful Axe by Clavicus Vile to kill her as a cure"},"Clavicus Vile":{"aff":-85,"type":"betrayed","relation":"cursed patron","note":"Answered Sebastian''s plea for a cure with a cruel pact and the Rueful Axe","worst":"Offered the axe to kill his own daughter instead of a true cure"},"Hircine":{"aff":-75,"type":"enemy","relation":"daughter''s corrupter","note":"Bitterly resents the Daedric Prince whose worship transformed his daughter","worst":"Daughter became a werewolf through Hircine''s influence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('self_doubt', '{"Self Doubt":{"aff":-60,"type":"rival","relation":"twin manifestation","note":"Eternally locked in combat with its identical other half","worst":"Endless battle with no resolution possible"},"Confidence":{"aff":-80,"type":"enemy","relation":"natural opponent","note":"Exists to undermine and oppose Confidence within Pelagius''s mind","worst":"Fights against Confidence in the mental arena"},"Anger":{"aff":25,"type":"platonic","relation":"fellow aspect","note":"Coexists as a fellow manifestation of Pelagius''s fractured psyche"},"Pelagius III":{"aff":-50,"type":"enemy","relation":"source mind","note":"Born from his madness and works to perpetuate his torment","best":"Gained strength as Pelagius deteriorated","worst":"Could cease to exist if Pelagius were cured"},"Sheogorath":{"aff":30,"type":"servant","relation":"realm master","note":"Exists within the Daedric Prince''s domain as part of Pelagius''s mental landscape"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('selveni_nethri', '{"Savela":{"aff":95,"type":"familial","relation":"daughter","note":"Taken to Riften orphanage when Selveni was accused of illegal necromancy; now missing","best":"Thought of Savela every day while apart","worst":"Returned to find her gone from the orphanage with no trace"},"Bashnag":{"aff":-75,"type":"enemy","relation":"former coven leader","note":"Accused her of Thalmor collaboration, cursed her, and cast her out to die","best":"Once provided refuge to practice necromancy in peace","worst":"Cursed her and left her to the spiders"},"Bashnag''s Coven":{"aff":-55,"type":"betrayed","relation":"former coven","note":"Chased her out and left her for dead in Southfringe Sanctum","best":"Good company for studying necromancy without persecution","worst":"Turned on her and drove her out to die"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('senna', '{"The Sybil":{"aff":85,"type":"protective","relation":"guardian","note":"Reverent guardian of the young oracle''s safety and spiritual development","best":"Watching the Sybil grow in her divine gifts"},"Fellow Priestesses":{"aff":70,"type":"platonic","relation":"spiritual sisters","note":"Close bond through shared daily duties and devotions to Dibella"},"Degaine":{"aff":-35,"type":"suspicious","relation":"unwanted beggar","note":"Mistrusts his attempts to exploit the temple''s charity","worst":"His persistent demands for coin and disrespect toward the sacred space"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('septimus_signus', '{"Hermaeus Mora":{"aff":55,"type":"obsessed","relation":"Daedric patron","note":"Serves Mora''s will in exchange for forbidden knowledge, unaware of the full extent of manipulation","best":"Granted glimpses of reality-bending knowledge beyond mortal comprehension","worst":"His sanity eroded by the very knowledge he craved"},"College of Winterhold":{"aff":-20,"type":"estranged","relation":"former institution","note":"Abandoned his position as a respected scholar due to his growing obsession"},"Urag gro-Shub":{"aff":35,"type":"professional","relation":"former colleague","note":"Urag still acknowledges his expertise despite his departure and descent into madness"},"The Last Dragonborn":{"aff":25,"type":"transactional","relation":"mutual seeker","note":"Exchanges Elder Scroll knowledge for assistance unlocking the Dwemer lockbox","best":"Brought the knowledge needed to finally open the lockbox","worst":"Witnessed his ultimate fate when the lockbox opened"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('serana', '{"Lord Harkon":{"aff":-85,"type":"nemesis","relation":"father","note":"His obsession with the Tyranny of the Sun prophecy would sacrifice her; she ultimately opposes him","worst":"His willingness to use her blood to block out the sun forever"},"Valerica":{"aff":65,"type":"familial","relation":"mother","note":"Loving but complicated; sealed Serana away to protect her from Harkon''s madness","best":"Reunion in the Soul Cairn after centuries apart","worst":"Being imprisoned in Dimhollow for millennia, even for her own protection"},"The Dragonborn":{"aff":85,"type":"platonic","relation":"closest friend","note":"Trusted companion who freed her and stood by her against her father","best":"Being freed from Dimhollow Crypt after centuries of isolation"},"Volkihar Clan":{"aff":-40,"type":"estranged","relation":"former clan","note":"Former family turned enemy through her opposition to Harkon''s plans"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('seren', '{"Rustleif":{"aff":85,"type":"romantic","relation":"husband","note":"Devoted partner and fellow blacksmith, though tensions exist about relocating to Hammerfell","best":"Romance blossomed during his apprenticeship under her father","worst":"Disagreements about raising their child in Skyrim versus Hammerfell"},"Unborn Child":{"aff":95,"type":"protective","relation":"unborn child","note":"Source of joy and concern about their future in Skyrim''s harsh environment and civil war","best":"Discovering the pregnancy together","worst":"Worrying about raising child during the Nord civil war"},"Father":{"aff":80,"type":"familial","relation":"father and mentor","note":"Master blacksmith in Hammerfell who trained both her and Rustleif","best":"Learning traditional Redguard metalworking from him"},"Dawnstar Residents":{"aff":25,"type":"neutral","relation":"neighbors and clients","note":"Professional but culturally distant relationships due to Redguard heritage"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sergius_turrianus', '{"Nirya":{"aff":55,"type":"romantic","relation":"secret lover","note":"Meets privately with him at night in the Hall of the Elements","best":"Their quiet late-night meetings in the Hall of the Elements"},"Faralda":{"aff":45,"type":"romantic","relation":"secret lover","note":"Rivals with Nirya for his attention, though he remains largely oblivious"},"Savos Aren":{"aff":35,"type":"professional","relation":"Arch-Mage","note":"Respects him professionally but criticizes his political detachment from Skyrim","worst":"Believes Savos would float the College above Skyrim if he could"},"Urag gro-Shub":{"aff":25,"type":"professional","relation":"colleague","note":"Shares occasional small talk about workload and College income"},"College of Winterhold":{"aff":65,"type":"professional","relation":"enchanting instructor","note":"Dedicated to maintaining its reputation and diplomatic bridge with Skyrim through enchanting services"}}')
ON CONFLICT (npc_name) DO UPDATE
