INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sern', '{"Dawnguard":{"aff":-50,"type":"estranged","relation":"rejected refugee","note":"Came seeking protection from vampires but was denied entry to Fort Dawnguard","worst":"Left sitting outside the fortress like cattle while vampires threaten"},"Isran":{"aff":-65,"type":"contempt","relation":"rejected by","note":"Particularly bitter toward the Dawnguard leader for his strict refugee policies","worst":"Realized begging for protection wouldn''t even work with Isran"},"Other Refugees":{"aff":40,"type":"platonic","relation":"fellow refugees","note":"Shares bond of mutual suffering and disappointment with fellow outcasts"}}')
