INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('shadr', '{"Hofgrir Horse-Crusher":{"aff":75,"type":"mentor","relation":"employer and mentor","note":"Took Shadr in upon arriving in Riften and teaches him the stable trade","best":"Took me in when I arrived in Riften about a year ago"},"Sapphire":{"aff":-80,"type":"enemy","relation":"scammer and creditor","note":"Orchestrated a financial scam leaving Shadr in considerable debt","worst":"Fell for her scam and now owes her a fortune he cannot repay"},"Marise":{"aff":65,"type":"crush","relation":"romantic interest","note":"Shadr nervously asked her for a drink at the Bee and Barb and she accepted","best":"She said yes to having a drink with me"},"Madesi":{"aff":35,"type":"platonic","relation":"jeweler and confidant","note":"Shadr is buying jewelry from him for Marise and trusts him to keep it secret"}}')
