INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('shavari', '{"Thalmor":{"aff":85,"type":"fanatical","relation":"covert agent","note":"Recited young and fanatically loyal, willing to sacrifice everything for the cause.","best":"Selected for high-priority elimination missions due to unwavering dedication"},"Elenwen":{"aff":70,"type":"professional","relation":"superior","note":"First Emissary who likely authorized her mission in Riften."},"Dragonborn":{"aff":-90,"type":"enemy","relation":"assassination target","note":"Tasked with eliminating the Dragonborn for meddling in Thalmor affairs.","worst":"Target interfered with Thalmor operations and required elimination"},"Esbern":{"aff":-80,"type":"enemy","relation":"priority target","note":"Determined to prevent Esbern''s rescue and the revival of the Blades.","worst":"Esbern continually eluded Thalmor capture"},"Riften Guards":{"aff":-15,"type":"suspicious","relation":"avoided authorities","note":"Maintains distance to avoid scrutiny while operating undercover."}}')
