INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('shel', '{"Chief Burguk":{"aff":75,"type":"romantic","relation":"husband","note":"His favored wife whom he protects from labor and grants a life of leisure","best":"He defended her against Gharol''s threat to send her to the mines"},"Arob":{"aff":-40,"type":"rival","relation":"co-wife","note":"Arob resents Shel''s privileged status while Shel gloats over her envy"},"Gharol":{"aff":-65,"type":"enemy","relation":"co-wife","note":"Gharol actively threatens Shel''s comfortable position and independence","worst":"Gharol threatened to make her work in the mines"},"Umurn":{"aff":-30,"type":"contempt","relation":"stepson","note":"She considers him inferior to the son she plans to bear"},"Nagrub":{"aff":-30,"type":"contempt","relation":"stepson","note":"She considers him inferior to the son she plans to bear"}}')
