INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sheogorath', '{"Pelagius III":{"aff":75,"type":"platonic","relation":"old friend","note":"Considers the mad emperor a dear friend and vacations in his mind","best":"Enjoying tea parties together in Pelagius''s mindscape for decades"},"Haskill":{"aff":40,"type":"professional","relation":"chamberlain","note":"Ever-present and long-suffering servant who endures his madness"},"Jyggalag":{"aff":-70,"type":"nemesis","relation":"original self","note":"His original identity as Prince of Order, cursed into madness by other Daedric Princes","worst":"The Greymarch when Jyggalag reasserts and destroys the Shivering Isles"},"Dervenin":{"aff":15,"type":"dismissive","relation":"priest","note":"Loyal priest left waiting while Sheogorath vacations in Pelagius''s mind"}}')
