INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('shuftharz', '{"Olur":{"aff":85,"type":"familial","relation":"son and apprentice","note":"Trains him in traditional Orcish smithing methods with evident pride in his progress","best":"His work at the forge brings her pride"},"Chief Larak":{"aff":60,"type":"professional","relation":"stronghold chief","note":"Serves him with loyalty and contentment; he publicly praises her craftsmanship","best":"He complimented her forge work, calling it pleasing"},"Blood-Kin":{"aff":25,"type":"transactional","relation":"qualified trading partners","note":"Only offers her smithing services to those who have earned Blood-Kin status with the Orcs"}}')
