INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sibbi_black-briar', '{"Maven Black-Briar":{"aff":15,"type":"familial","relation":"mother","note":"She imprisoned him to teach him discretion; he resents it but still answers to her","worst":"Being thrown in jail by his own mother for causing public scandal"},"Svidi":{"aff":-85,"type":"nemesis","relation":"ex-fiancÃ©e","note":"Obsessed with finding and killing her for betraying him after his infidelity","best":"Her lovely singing during their courtship","worst":"Her discovering his affair and sending her brother to confront him"},"Hemming Black-Briar":{"aff":25,"type":"familial","relation":"brother"},"Ingun Black-Briar":{"aff":20,"type":"familial","relation":"sister"},"Louis Letrush":{"aff":5,"type":"transactional","relation":"business associate","note":"Involved in the horse trading deal over Frost"}}')
