INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sickly_farmer', '{"Danica Pure-Spring":{"aff":65,"type":"grateful","relation":"primary healer","note":"Depends on Danica for daily healing and care at the Temple of Kynareth","best":"Fever finally broke after one of Danica''s healing sessions"},"Acolyte Jenssen":{"aff":45,"type":"grateful","relation":"secondary caregiver","note":"Assists with daily healing rituals and basic care"},"Former Farmhands":{"aff":15,"type":"estranged","relation":"former workers","note":"Lost all contact after illness forced abandonment of the farm","worst":"Left the farmstead behind with no word reaching her old hands"}}')
