INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('siddgeir', '{"Dengeir of Stuhn":{"aff":-35,"type":"estranged","relation":"deposed uncle","note":"Siddgeir displaced him as Jarl through Imperial maneuvering and falsely claims he stepped down due to age","worst":"Seized his uncle''s throne through political manipulation"},"Nenya":{"aff":25,"type":"professional","relation":"steward","note":"Delegates all actual governance to her while enjoying the privileges of office"},"Helvard":{"aff":15,"type":"professional","relation":"housecarl","note":"Dismissive of his counsel but relies on him for protection and enforcement"},"Imperial Legion":{"aff":50,"type":"patron","relation":"political patron","note":"Imperial support installed him as Jarl and keeps him in power","best":"Secured Imperial backing to claim the Jarl''s throne"},"Local Bandits":{"aff":10,"type":"transactional","relation":"corrupt associates","note":"Maintains illicit dealings with bandits for personal profit"}}')
