INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sigar', '{"Eola":{"aff":15,"type":"platonic","relation":"coven leader","note":"Distant associate through Namira''s cult; rarely attends gatherings","worst":"Panicked and deflected blame when she was killed"},"Namira":{"aff":40,"type":"transactional","relation":"patron deity","note":"Worships out of appetite rather than true devotion"},"Local Guards":{"aff":-70,"type":"fearful","relation":"persecutors","note":"Would execute him if his cannibalism were discovered"},"Player":{"aff":55,"type":"admirer","relation":"fellow cannibal","note":"Hails the Champion of Namira and offers them the first bite from his meals","best":"Recognized as Champion of Namira and offered first bite"}}')
