INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sigdis_gauldurson', '{"Gauldur":{"aff":-95,"type":"betrayed","relation":"father","note":"Murdered him in his sleep alongside his brothers to steal the Gauldur Amulet","worst":"Slaying our own father as he slept for his power"},"Jyrik Gauldurson":{"aff":45,"type":"platonic","relation":"elder brother","note":"Co-conspirator in patricide; seeks to reunite with him in death","best":"Standing together to claim the amulet''s power"},"Mikrul Gauldurson":{"aff":45,"type":"platonic","relation":"younger brother","note":"Co-conspirator in patricide; seeks to reunite with him in death","best":"Standing together to claim the amulet''s power"},"Archmage Geirmund":{"aff":-90,"type":"nemesis","relation":"slayer","note":"Cornered and slew him, then entombed him with powerful binding magic","worst":"Being hunted down and destroyed by Geirmund''s magic"},"High King of Skyrim":{"aff":-75,"type":"enemy","relation":"ruler who ordered his death","note":"Ordered the brothers'' destruction for their crimes against their father","worst":"The decree that sealed our doom"}}')
