INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sigrid', '{"Alvor":{"aff":85,"type":"romantic","relation":"husband","note":"Deeply devoted and fiercely protective of him from other women''s advances","best":"Loving exchanges and shared family life at the forge","worst":"Bickering over chores and his spoiling of Dorthe"},"Dorthe":{"aff":68,"type":"familial","relation":"daughter","note":"Loves her but constantly frustrated by her rejection of traditional feminine pursuits","best":"Trying to bond over gardening and knitting together","worst":"Arguments about being ladylike and preferring the forge"},"Hadvar":{"aff":55,"type":"familial","relation":"nephew by marriage","note":"Treats him as family when he visits Riverwood"},"Hilde":{"aff":45,"type":"platonic","relation":"neighbor","note":"Fellow townswoman who shares child-rearing talk"},"Embry":{"aff":-35,"type":"contempt","relation":"town drunk","note":"Rebuffs his drunken advances and threatens him with Alvor''s wrath","worst":"His constant drunken flirtations"}}')
