SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('silana_petreia', '{"Freir":{"aff":45,"type":"professional","relation":"superior","note":"Respectfully challenges Freir about expanding the temple''s charitable outreach","best":"Freir acknowledged her compassion and encouraged her to find a way","worst":"Freir dismissed her pleas for more active help for the destitute"},"Rorlund":{"aff":35,"type":"professional","relation":"fellow priest","note":"Philosophically at odds over whether the poor should be actively aided","best":"Rorlund allowed her to continue outreach without interference","worst":"Rorlund insisted the poor must raise themselves without temple help"},"Angeline Morrard":{"aff":65,"type":"platonic","relation":"friend","note":"Visits her shop every morning to watch the sunrise in peace","best":"Quiet daily mornings watching the sunrise together"},"Solitude''s poor":{"aff":75,"type":"protective","relation":"advocate","note":"Champions their cause within the temple hierarchy","worst":"Witnessing their starvation while the temple hesitates to act"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sild''s_assistant', '{"Sild the Warlock":{"aff":-75,"type":"betrayed","relation":"former master","note":"Served as his assistant until he found her more useful dead than alive","worst":"Being killed and reanimated by the master she came to learn from"},"College of Winterhold":{"aff":-15,"type":"estranged","relation":"former institution","note":"Left to pursue forbidden necromantic arts outside the College''s restrictions"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sild_the_warlock', '{"Subjugated Ghosts":{"aff":-45,"type":"servant","relation":"bound servants","note":"Enslaved spirits forced to guard Rannveig''s Fast through conjuration","worst":"Ripping their souls from rest to serve eternally"},"College of Winterhold":{"aff":-65,"type":"estranged","relation":"expelled institution","note":"Cast out for unethical experiments; bears lingering resentment","worst":"Being expelled and driven from magical society"},"Morthal Guards":{"aff":-50,"type":"enemy","relation":"would-be captors","note":"Aware of his lair but unable to breach his magical defenses","best":"Watching them fail to penetrate his traps"},"Deceased Assistant":{"aff":-80,"type":"betrayed","relation":"murdered assistant","note":"Killed and kept as a corpse; remarked as more useful dead than alive","worst":"Murdering his own assistant for experimentation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('silda_the_unseen', '{"Susanna the Wicked":{"aff":15,"type":"neutral","relation":"fellow street dweller","note":"Witnessed her murder by the Butcher and was shaken by it","worst":"Found Susanna''s body in the graveyard after hearing her scream"},"Windhelm Guards":{"aff":-40,"type":"suspicious","relation":"avoided authorities","note":"Maintains careful distance to protect her pickpocketing operation"},"Fellow Beggars":{"aff":35,"type":"protective","relation":"cautious allies","note":"Shares mutual protection with other street dwellers in Windhelm"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('silus_vesuius', '{"Madena":{"aff":15,"type":"rival","relation":"opposing resident","note":"Respects her personally but she publicly opposes his museum and legacy","best":"Calls her a good woman despite their disagreements","worst":"Public argument over his museum and family''s past"},"Mehrunes Dagon":{"aff":85,"type":"fanatical","relation":"object of devotion","note":"Obsessed with proving himself worthy, but Dagon contemptuously demands his death","best":"Believes restoring Mehrunes'' Razor will earn Dagon''s recognition","worst":"Dagon reveals no interest in him and demands his life for the Razor''s restoration"},"Mythic Dawn Ancestors":{"aff":75,"type":"familial","relation":"ancestors","note":"Deeply devoted to preserving and proving worthy of their legacy","best":"Dedicated his life and museum to honoring their history","worst":"Their dark legacy brings public scorn and personal danger"},"Dawnstar Citizens":{"aff":-25,"type":"dismissive","relation":"distrustful community","note":"Dismissive of their opposition while they distrust his museum","worst":"Widespread community opposition to his museum''s purpose"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('silver-blood_guard', '{"Silver-Blood Family":{"aff":70,"type":"servant","relation":"employer","note":"Loyal employees well-compensated for unwavering service and moral flexibility"},"Thonar Silver-Blood":{"aff":65,"type":"professional","relation":"direct superior","note":"Issues orders and oversees Cidhna Mine operations"},"Markarth City Guard":{"aff":20,"type":"rival","relation":"jurisdictional rivals","note":"Tense professional relationship due to overlapping authority in Markarth"},"Prisoners":{"aff":-75,"type":"contempt","relation":"inmates","note":"Antagonistic relationship marked by harsh treatment and excessive force","worst":"Relishing opportunities to exercise power over the helpless"},"Fellow Silver-Blood Guards":{"aff":60,"type":"platonic","relation":"comrades","note":"Strong camaraderie built on shared mercenary backgrounds and duties"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('silver-blood_mercenary', '{"Atar":{"aff":45,"type":"professional","relation":"crew leader","note":"Direct superior who trusts him as an enforcer and leads the mercenary band at Sanuarach Mine."},"Silver-Blood Family":{"aff":35,"type":"transactional","relation":"employer","note":"Wealthy patrons who pay well for his intimidation services; loyalty bought with coin."},"Local Miners":{"aff":-50,"type":"enemy","relation":"displaced workers","note":"Actively prevents them from accessing the mine through threats and force.","worst":"Daily intimidation of townsfolk denied their own livelihood"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sinding', '{"Mathies Caerellia":{"aff":-90,"type":"enemy","relation":"victim''s father","note":"Mathies despises Sinding for murdering his daughter and cannot comprehend the horror of it.","worst":"Ripped his daughter apart so badly they barely found enough to bury"},"Indara Caerellia":{"aff":-85,"type":"enemy","relation":"victim''s mother","note":"Shares Mathies'' grief and hatred for the death of their child Lavinia."},"Hircine":{"aff":-70,"type":"nemesis","relation":"cursed by","note":"Hircine cursed the ring Sinding stole, causing his berserk transformations, and later hunts him for sport.","worst":"Cursed the Ring of Hircine so Sinding could never control his transformations"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sinmir', '{"Commander Caius":{"aff":-65,"type":"rival","relation":"predecessor","note":"Vocal critic who considers him incompetent and eventually replaces him","worst":"Watching Caius walk around Dragonsreach like a preening rooster"},"Whiterun Guard":{"aff":25,"type":"professional","relation":"subordinates","note":"Harsh critic of their discipline who later becomes their commander","worst":"Witnessing their lazy and undisciplined performance"},"Stormcloaks":{"aff":75,"type":"fanatical","relation":"faction","note":"Loyal supporter rewarded with command after Whiterun''s capture","best":"Being named guard commander after Stormcloak victory"},"Sabjorn":{"aff":-50,"type":"suspicious","relation":"meadery owner","note":"Patron who was poisoned by his mead and threatened him with imprisonment","worst":"Being poisoned by Honningbrew Reserve"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sirgar', '{"Sorli the Builder":{"aff":75,"type":"familial","relation":"mother and mentor","note":"Taught him mine management; became jarl of Morthal after Stormcloak victory","worst":"Departure to Morthal left him running the mine sooner than expected"},"Pactur":{"aff":70,"type":"familial","relation":"father","note":"Co-manages Rockwallow Mine; relocated to Morthal with Sorli","worst":"Left for Morthal, leaving Sirgar alone to manage operations"},"Mine Workers":{"aff":15,"type":"suspicious","relation":"supervised employees","note":"Keeps a close eye on miners; believes they cannot be trusted too much"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sirkjorg', '{"Herkja":{"aff":65,"type":"romantic","relation":"fellow freed worker","note":"Endured Miraak''s mind control together and relocated as a pair afterward","best":"chose to stay together after breaking free"},"Miraak":{"aff":-90,"type":"nemesis","relation":"former enslaver","note":"Held Sirkjorg under mind control to build at the Temple","worst":"forced into trance-like servitude for unknown period"},"Bujold":{"aff":40,"type":"professional","relation":"possible leader","note":"Potential leader at Bujold''s Retreat if relocated there"},"Thirsk Mead Hall":{"aff":35,"type":"platonic","relation":"community","note":"Welcomed as a contributing member after retaking Thirsk","best":"glad to be back at the Mead Hall"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sissel', '{"Lemkil":{"aff":-80,"type":"fearful","relation":"father","note":"Abusive father who beats her and resents his daughters for their mother''s death in childbirth","worst":"Daily beatings from the man who should protect her"},"Britte":{"aff":-70,"type":"enemy","relation":"twin sister","note":"Twin sister who bullies and torments her relentlessly for twelve hours each day","worst":"Constant taunts, threats, and physical intimidation from her own sister"},"Jouane Manette":{"aff":90,"type":"mentor","relation":"secret teacher","note":"Retired mage who secretly teaches her magic and provides her only safe refuge","best":"Learning spells that give her hope of one day defending herself and escaping"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('skaggi_scar-face', '{"Sosia Tremellia":{"aff":75,"type":"romantic","relation":"wife","note":"Rare Nord-Imperial union in the Reach showing his open-minded nature"},"Pavo Attius":{"aff":55,"type":"protective","relation":"fellow mine operator","note":"Took him in after Forsworn attacked Kolskeggr Mine","best":"Gave immediate shelter without hesitation when Kolskeggr fell"},"Gat gro-Shargakh":{"aff":45,"type":"protective","relation":"sheltered survivor","note":"Provided refuge after Forsworn massacre at Kolskeggr"},"Daighre":{"aff":60,"type":"professional","relation":"trusted worker","note":"Most trusted worker at Left Hand Mine","best":"Told her he''s glad she stayed with the mine"},"Erith":{"aff":-15,"type":"dismissive","relation":"worker''s troublesome daughter","note":"Bored daughter who disrupts mine operations"},"Forsworn":{"aff":-85,"type":"fearful","relation":"threat to mine","note":"Growing menace that massacred Kolskeggr and may hit Left Hand next","worst":"Slaughtered Kolskeggr miners leaving only Pavo and Gat alive"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('skald', '{"Ulfric Stormcloak":{"aff":90,"type":"fanatical","relation":"rebel leader","note":"Fiercely loyal devotee who considers Ulfric the true king of Skyrim"},"Brina Merilis":{"aff":-65,"type":"rival","relation":"political rival","note":"Empire supporter who threatens his jarlship and is preferred by the townsfolk","worst":"Heated public argument outside the White Hall"},"Jod":{"aff":15,"type":"professional","relation":"housecarl","note":"Great War veteran retained for loyalty despite disagreeing with his Stormcloak fanaticism"},"Madena":{"aff":10,"type":"professional","relation":"court wizard","note":"Serves at court despite opposing his political views"},"Bulfrek":{"aff":-25,"type":"contempt","relation":"servant","note":"Life-long servant he routinely belittles","worst":"Daily belittlement in front of the court"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('skeever', '{"Other Skeevers":{"aff":40,"type":"platonic","relation":"pack mates","note":"Form loose packs for mutual hunting and protection"},"Venomfang Skeevers":{"aff":25,"type":"familial","relation":"mutated cousins","note":"Enhanced toxicity variants sharing common ancestry"},"Biter":{"aff":-10,"type":"estranged","relation":"domesticated kin","note":"Abandoned wild instincts to live as a child''s pet"},"Humans":{"aff":-60,"type":"enemy","relation":"hostile species","note":"Universally hostile encounters, though rare taming occurs"},"Vampires":{"aff":0,"type":"neutral","relation":"lair cohabitants","note":"Found in vampire lairs as unwitting scavengers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('skjor', '{"Aela the Huntress":{"aff":88,"type":"romantic","relation":"fellow Circle member and hunting partner","note":"Shares his embrace of lycanthropy; they hunt together under Hircine''s blessing.","best":"Running together beneath the moon, fur and fang, the thrill of the hunt shared.","worst":"Her caution about discretion when he wanted to hunt freely and without restraint."},"Kodlak Whitemane":{"aff":45,"type":"platonic","relation":"Harbinger","note":"Respects his leadership but fundamentally disagrees with his desire to cure lycanthropy.","best":"Serving the Companions under a Harbinger of undeniable honor and wisdom.","worst":"Knowing the Harbinger wants to cast aside the gift Hircine bestowed upon them."},"Njada Stonearm":{"aff":-10,"type":"rival","relation":"fellow Companion","note":"Frequent friction and clashing personalities despite fighting under the same roof.","best":"Grudging respect for her skill when she bests Athis in the brawl.","worst":"Another sharp word exchanged, another disagreement over what glory means."},"Silver Hand":{"aff":-100,"type":"nemesis","relation":"werewolf hunters","note":"Mortal enemies who hunt his kind; they ultimately kill him at Gallows Rock.","best":"Slashing through their ranks, making them pay for every Companion they''ve harmed.","worst":"Their blades finding him before Aela could reach him, cut down like a beast."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('skuli', '{"Eydis":{"aff":75,"type":"familial","relation":"mother","note":"Runs the inn alongside her but suspects her lies about his father''s whereabouts","best":"Working together managing the Old Hroldan Inn","worst":"Catching her in contradictory stories about where his father went"},"Father":{"aff":50,"type":"estranged","relation":"father","note":"Longs to know the truth about his disappearance and notices his mother''s inconsistent explanations","worst":"His unexplained absence and the mystery surrounding it"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('skulvar_sable-hilt', '{"Jervar":{"aff":45,"type":"familial","relation":"son","note":"Stern but protective father who pushes Jervar hard to learn the stable trade","best":"Pride when Jervar completes his chores properly","worst":"Called him a half-wit for wanting to fight dragons instead of working with horses"},"Lillith Maiden-Loom":{"aff":55,"type":"professional","relation":"employer","note":"Respectful business relationship managing the stables'' success together","best":"Productive discussions about wartime horse sales boosting business"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('slaughterfish', '{"Horkers":{"aff":-40,"type":"enemy","relation":"natural prey","note":"Coastal prey animals targeted by slaughterfish in coastal waters"},"Mudcrabs":{"aff":-25,"type":"rival","relation":"territorial rival","note":"Competes with slaughterfish for shallow water hunting grounds"},"Argonians":{"aff":-50,"type":"fearful","relation":"natural predator","note":"Only race capable of effectively hunting slaughterfish underwater"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('slitter', '{"Mogrul":{"aff":75,"type":"servant","relation":"right-hand man and enforcer","note":"Unwavering loyalty suggests either deep personal debt or shared history forged by the Red Year","best":"Earned Mogrul''s absolute trust as his most reliable enforcer","worst":"Continues serving even beyond reason, hinting at an unbreakable obligation"},"Raven Rock Guards":{"aff":-15,"type":"suspicious","relation":"uneasy coexistence","note":"Tense but careful mutual avoidance of direct confrontation"},"Geldis Sadri":{"aff":10,"type":"transactional","relation":"patron of his establishment","note":"Regular presence at the Retching Netch with minimal personal interaction"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('smaref_ice-blade', '{"Pjofr Ice-Blade":{"aff":70,"type":"familial","relation":"uncle and protector","note":"Arrived in Riften to reveal Smaref''s heritage and restore his birthright","best":"Uncle Pjofr came to tell me who I truly am"},"Mother":{"aff":50,"type":"familial","relation":"mother","note":"Assassinated in political plot when Smaref was young; he lives unaware of her fate"},"Erikur":{"aff":-80,"type":"enemy","relation":"hidden enemy","note":"Orchestrated mother''s assassination and seizure of clan lands; Smaref unaware"},"Gisli":{"aff":-80,"type":"enemy","relation":"hidden enemy","note":"Co-conspirator in plot against Clan Ice-Blade; Smaref unaware of her role"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('snilf', '{"Edda":{"aff":45,"type":"protective","relation":"fellow beggar","note":"Shows rare compassion toward her, seeing her madness as a mercy","best":"Sharing what little he has to keep her safe on Beggar''s Row","worst":"Watching her suffer the streets while powerless to truly help"},"Marise Aravel":{"aff":20,"type":"transactional","relation":"charitable vendor","note":"Begs near her stall daily; she shows genuine kindness among callous citizens","best":"Her wish that she could provide more than just coin"},"Unknown Brigands":{"aff":-100,"type":"nemesis","relation":"family''s killers","note":"Destroyed his life by ravaging and burning his wife and daughter before his eyes","worst":"Watching his family burn alive after being violated"},"Maven Black-Briar":{"aff":-60,"type":"contempt","relation":"callous noble","note":"Her cold dismissal embodies the cruelty of Riften''s wealthy"},"Sibbi Black-Briar":{"aff":-70,"type":"fearful","relation":"threatening noble","note":"Threatened him with death if he approached again"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('snilling', '{"Katla":{"aff":85,"type":"romantic","relation":"wife","note":"Deeply appreciative of her capability; proud rather than ashamed of being outdone by her","best":"Katla stepping up to manage the farm when he became unable"},"Knud":{"aff":70,"type":"familial","relation":"son","note":"Watches over him from indoors; hopes he will one day take over the farm"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('snorreid', '{"East Empire Company":{"aff":45,"type":"professional","relation":"employer","note":"Values their reliable arrangement though his position is unofficial"},"Gulum-Ei":{"aff":-25,"type":"suspicious","relation":"watched suspect","note":"Keeps a watchful eye on the Argonian merchant''s activities"},"Deeja":{"aff":15,"type":"neutral","relation":"coworker","note":"Occasional minimal interaction at the warehouse"}}')
