INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('snow_bear', '{"Other Snow Bears":{"aff":-55,"type":"rival","relation":"territorial competitor","note":"Tolerates only during mating season; otherwise aggressively drives off intruders"},"Human Hunters":{"aff":-70,"type":"enemy","relation":"prey that fights back","note":"Views as threats and competitors; known for unusual persistence in pursuing them","worst":"Scarred by hunters who entered its territory"},"Frost Trolls":{"aff":-35,"type":"rival","relation":"territorial disputant","note":"Occasional clashes over territory, usually ending in the bear''s favor"}}')
ON CONFLICT (npc_name) DO UPDATE
