INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('snowy_sabre_cat', '{"Sabre Cats":{"aff":15,"type":"neutral","relation":"same species","note":"Tolerates during mating season but otherwise maintains strict territorial boundaries"},"Frost Trolls":{"aff":-35,"type":"rival","relation":"territorial competitor","note":"Natural competitors for territory and prey in northern Skyrim"},"Dragons":{"aff":-5,"type":"dismissive","relation":"coexisting apex predator","note":"Neither fears nor actively seeks conflict with them"},"Wolves":{"aff":-25,"type":"contempt","relation":"inferior predator","note":"Views as lesser predators, occasionally preys upon them"},"Humans":{"aff":-50,"type":"contempt","relation":"potential prey","note":"Sees as potential prey especially when food is scarce"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sofie', '{"Niranye":{"aff":15,"type":"neutral","relation":"reluctant shelter provider","note":"Tolerates Sofie sleeping behind her house","best":"Allows her a place to sleep out of the cold"},"Father":{"aff":35,"type":"familial","relation":"father","note":"Stormcloak soldier who raised her alone, then never returned from battle","best":"Raised her after her mother died","worst":"Left for war and never came back"},"Mother":{"aff":20,"type":"familial","relation":"mother","note":"Died when Sofie was very young; barely remembers her"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sogrlaf', '{"Captain Gjalund":{"aff":65,"type":"professional","relation":"captain","note":"Trusted crewman who serves loyally and defers all business matters to his captain''s authority","best":"Earned a place aboard the Northern Maiden through unwavering dedication"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('solaf', '{"Bolund":{"aff":65,"type":"familial","relation":"younger brother","note":"Close but tense due to differing views on the war; Bolund wants to fight while Solaf prefers stability","best":"Running the family business together in Falkreath","worst":"Arguing about whether to stay put or join the fighting"},"Tekla":{"aff":55,"type":"romantic","relation":"courtship interest","note":"Apparently courting her, though only discoverable via console commands"},"Valga Vinicia":{"aff":35,"type":"platonic","relation":"tavern keeper","note":"Regular evening patron at Dead Man''s Drink who favors strong drinks"},"Ulfric Stormcloak":{"aff":60,"type":"admirer","relation":"ideological leader","note":"Still holds with Ulfric''s ideals though no longer fights in his name","best":"Serving in the Stormcloak rebellion for Nordic independence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('solitude_guard', '{"Captain Aldis":{"aff":75,"type":"mentor","relation":"commanding officer and combat trainer","note":"Trained under Aldis during Imperial Legion basic training and holds him in high regard."},"Jarl Elisif":{"aff":85,"type":"protective","relation":"sworn protector","note":"Developed unwavering loyalty to Elisif after witnessing High King Torygg''s death."},"Fellow Guards":{"aff":65,"type":"platonic","relation":"brotherhood in arms","note":"Shares close camaraderie forged through shared duties and dangers patrolling Solitude."},"General Tullius":{"aff":45,"type":"professional","relation":"ultimate superior officer","note":"Respects Tullius as the head of the Imperial chain of command but has no personal connection."},"Stormcloak Sympathizers":{"aff":-65,"type":"suspicious","relation":"potential threats","note":"Views with deep suspicion as dangers to city security and the Imperial cause they serve."}}')
ON CONFLICT (npc_name) DO UPDATE
