INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sond', '{"Bottar":{"aff":80,"type":"platonic","relation":"friend and business partner","note":"Close companion who shares wilderness exploration and entrepreneurial ventures","best":"Discovered Deep Folk Crossing together"}}')
ON CONFLICT (npc_name) DO UPDATE
