INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sondas_drenim', '{"Hrefna":{"aff":75,"type":"protective","relation":"caretaker","note":"Acts as her caretaker when Tormir is away; she thinks the world of him","best":"She thinks the world of him and he strives to be a good influence"},"Tormir":{"aff":65,"type":"platonic","relation":"trusted friend","note":"Mutual support and shared concern for Hrefna''s wellbeing","best":"Thanks him for looking after Hrefna and values his judgment"},"Derkeethus":{"aff":45,"type":"platonic","relation":"fellow miner","note":"Speaks of him with concern after his disappearance near the falls","worst":"Hasn''t heard from him since he went fishing near the dangerous falls"},"Quintus Navale":{"aff":25,"type":"transactional","relation":"medical supplier","note":"Sends requests for mining medicine to him at the White Phial"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sonir', '{"Dragonborn":{"aff":40,"type":"professional","relation":"employer","note":"Hired as household bard at Windstad Manor; maintains polite professional courtesy","worst":"Dismissal she diplomatically called an unfortunate misunderstanding"},"Windstad Manor Steward":{"aff":35,"type":"professional","relation":"colleague","note":"Coordinates household matters; was hired through the steward"}}')
ON CONFLICT (npc_name) DO UPDATE
