INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sorex_vinius', '{"Corpulus Vinius":{"aff":45,"type":"familial","relation":"father","note":"Respects his father but quietly competes for control of the inn","best":"Learning the innkeeping trade from him","worst":"Father shows no signs of retiring"},"Vivienne Onis":{"aff":20,"type":"crush","relation":"childhood crush","note":"Confessed feelings for her to Roggvir, leading to years of humiliation","worst":"Being humiliated in front of her by Roggvir repeatedly"},"Roggvir":{"aff":-80,"type":"enemy","relation":"former friend turned tormentor","note":"Betrayed his trust and bullied him mercilessly over his feelings for Vivienne","best":"Watching his execution","worst":"Being beaten, mocked, and having a beehive put in his bed"},"Falk Firebeard":{"aff":15,"type":"transactional","relation":"client","note":"Delivers special rum orders to him at the Blue Palace"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sorine_jurard', '{"Isran":{"aff":40,"type":"professional","relation":"former colleague and current leader","note":"Past falling out over his dismissiveness toward her vampire warnings; reconciled out of shared purpose","worst":"He said very hurtful things and rejected her help when she proposed vampire threat scenarios"},"Gunmar":{"aff":55,"type":"professional","relation":"fellow Dawnguard specialist","note":"Old associate who rejoined alongside her; steady working relationship"},"Florentius Baenius":{"aff":25,"type":"dismissive","relation":"Dawnguard colleague","note":"Finds his religious devotion and manner peculiar"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sorli_the_builder', '{"Pactur":{"aff":80,"type":"romantic","relation":"husband","note":"Co-manages Rockwallow Mine and Stonehills alongside her; becomes her steward when she is made Jarl"},"Sirgar":{"aff":75,"type":"familial","relation":"son","note":"Left in charge of Stonehills when Sorli becomes Jarl; she aims to secure his future"},"Bryling":{"aff":35,"type":"professional","relation":"employer","note":"Thane of Solitude who owns Rockwallow Mine; Sorli and Pactur manage it on her behalf and ship ore to her"},"Ulfric Stormcloak":{"aff":55,"type":"professional","relation":"liege","note":"Source of her political appointment as Jarl of Morthal after the Stormcloak conquest of Hjaalmarch"},"Idgrod Ravencrone":{"aff":-15,"type":"rival","relation":"predecessor","note":"Replaces her as Jarl when the Stormcloaks seize Hjaalmarch; Idgrod returns if the Imperials retake the hold"},"Teeba-Ei":{"aff":35,"type":"professional","relation":"housecarl","note":"Worker at Stonehills who becomes her housecarl when she ascends to Jarl"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sosia_tremellia', '{"Skaggi Scar-Face":{"aff":85,"type":"romantic","relation":"husband","note":"Supports him in running Left Hand Mine and shares his household","best":"Building a life together at the mine after leaving Cyrodiil"},"Pavo Attius":{"aff":35,"type":"platonic","relation":"fellow miner","note":"His escape from Kolskeggr Mine deeply affected her sense of safety","worst":"Seeing Pavo driven out and hearing almost everyone at Kolskeggr was killed"},"Forsworn":{"aff":-90,"type":"fearful","relation":"existential threat","note":"Constantly vigilant and worried about attack after the Kolskeggr massacre","worst":"The brutal Forsworn attack on Kolskeggr Mine that left nearly everyone dead"},"Left Hand Mine Workers":{"aff":40,"type":"professional","relation":"coworkers","note":"Maintains cordial working relationships with the other miners"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('spectral_assassin', '{"Sithis":{"aff":95,"type":"fanatical","relation":"eternal master","note":"Serves the Dread Father with unwavering devotion beyond death itself"},"The Night Mother":{"aff":80,"type":"servant","relation":"sacred matron","note":"Deeply reveres her authority; she defended his loyalty against false accusations in life","best":"The Night Mother herself berated a Speaker who questioned his loyalty"},"The Listener":{"aff":75,"type":"servant","relation":"spiritual guide and protector","note":"Serves the current Listener with loyal dedication, offering wisdom and combat support","best":"Fighting alongside the Listener to unleash the wrath of Sithis"},"Dark Brotherhood":{"aff":20,"type":"betrayed","relation":"former Speaker","note":"Still honors the traditions but was falsely accused and gruesomely murdered by his own Family","worst":"Framed for treason and slaughtered by the brothers and sisters he served"},"Shadowmere":{"aff":70,"type":"platonic","relation":"old friend","note":"Shows rare genuine warmth upon encountering the immortal steed","best":"Reunion with Shadowmere, greeting as ''my old and dear friend''"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('spellsword', '{"Bashnag":{"aff":75,"type":"protective","relation":"commander","note":"Unwavering loyalty to Bashnag''s leadership at Southfringe Sanctum"},"Fellow Spellswords":{"aff":60,"type":"platonic","relation":"comrades in arms","note":"Close-knit bond forged through shared combat and magical training"},"College of Winterhold":{"aff":-30,"type":"estranged","relation":"former institution","note":"Broke away over philosophical differences regarding practical combat magic"},"Local Bandits":{"aff":-50,"type":"rival","relation":"territorial competitors","note":"Hostile competition over territory near Southfringe Sanctum"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stalf', '{"Orthjolf":{"aff":75,"type":"servant","relation":"master and vampire creator","note":"Serves as his enforcer with unquestioning loyalty based on simple conditioning","best":"Being chosen and turned into a vampire"},"Salonia Caelia":{"aff":-65,"type":"betrayed","relation":"betrayer","note":"Revealed she was sent by Vingalmo to kill him after feigning cooperation","worst":"Her admission that Vingalmo wanted him dead too"},"Vingalmo":{"aff":-55,"type":"enemy","relation":"would-be killer","note":"Political rival of Orthjolf who ordered Stalf''s death through Salonia"},"Lord Harkon":{"aff":35,"type":"professional","relation":"supreme leader","note":"Serves indirectly within the Volkihar court hierarchy"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stalleo', '{"Family":{"aff":90,"type":"familial","relation":"imprisoned kin","note":"His driving motivation; held captive inside Treva''s Watch by Brurid''s bandits","worst":"Returning from war to find them kidnapped in their own home"},"Bodyguards":{"aff":65,"type":"professional","relation":"loyal retainers","note":"Remained with him through war and exile; only survivors of the failed assault","best":"Staying loyal when all other men were lost"},"Brurid":{"aff":-95,"type":"nemesis","relation":"usurper and rogue mage","note":"Bad blood since the king''s death; Stalleo turned him in for defection, but he escaped and seized Treva''s Watch","worst":"Invading his home and kidnapping his family while he fought in the war"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stalleo''s_bodyguard', '{"Stalleo":{"aff":75,"type":"protective","relation":"employer and charge","note":"Serves with unwavering loyalty after fighting alongside him in the Civil War","best":"Stood together through Civil War campaigns","worst":"Returned from war to find his home overrun by bandits"},"Fellow Bodyguard":{"aff":45,"type":"platonic","relation":"colleague","note":"Professional combat partner sharing watch and camp duties"},"Stalleo''s Family":{"aff":55,"type":"protective","relation":"charges","note":"Extended protection duties include all family members","best":"Goal to reunite the family inside Treva''s Watch"},"Treva''s Watch Bandits":{"aff":-75,"type":"enemy","relation":"occupiers","note":"Bandit filth who overran her employer''s ancestral home while they were away","worst":"Finding the home defenseless and seized upon return from war"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stands-in-shallows', '{"Suvaris Atheron":{"aff":-35,"type":"transactional","relation":"overseer","note":"She keeps him supplied with skooma to manipulate worker morale, exploiting his addiction for control","worst":"Realizing his addiction is being weaponized against his fellow workers"},"Argonian Assemblage":{"aff":25,"type":"estranged","relation":"community","note":"His addiction has strained bonds with fellow Argonians who view him with pity or frustration"},"Windhelm Nords":{"aff":-55,"type":"contempt","relation":"oppressors","note":"Bitterly resents Nord exploitation of Argonian labor and their segregated society","worst":"Watching young Argonians break their backs for Nords who will never respect them"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('staubin', '{"College of Winterhold":{"aff":55,"type":"professional","relation":"alma mater","note":"Trained and built his reputation as a conjurer there before pursuing independent research"},"Calcelmo":{"aff":35,"type":"professional","relation":"fellow Dwemer scholar","note":"Likely professional acquaintance through shared expertise in Dwemer studies"},"Research Assistants":{"aff":40,"type":"professional","relation":"expedition colleagues","note":"Unnamed companions who accompanied him on his fatal Nchuand-Zel expedition","worst":"Could not save him when the expedition turned deadly"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stenvar', '{"Elda Early-Dawn":{"aff":35,"type":"professional","relation":"innkeeper","note":"Provides regular lodging at Candlehearth Hall where he bases his mercenary operations"},"Windhelm Guards":{"aff":25,"type":"professional","relation":"former colleagues","note":"Cordial relations from likely past service with the city guard"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stig_salt-plank', '{"Haldyn":{"aff":35,"type":"professional","relation":"boss","note":"Respects Haldyn''s cunning leadership but will betray him if threatened or bribed","worst":"Giving up Haldyn''s base at Japhet''s Folly to save his own hide"},"Blood Horker Crew":{"aff":55,"type":"professional","relation":"crew","note":"Commands their loyalty through charisma and implied threats over nine years"},"Karita":{"aff":-35,"type":"contempt","relation":"harassment target","note":"Enjoys tormenting the Windpeak Inn keeper with false charm and intimidation","best":"Mocking her with feigned politeness while she served them mead"},"Alding":{"aff":45,"type":"professional","relation":"trusted crewman","note":"Trusted crew member who joins in his intimidation and harassment tactics"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('storm_mage', '{"Fellow Storm Mages":{"aff":35,"type":"professional","relation":"loose allies","note":"Loose alliance of magical researchers sharing similar interests in shock magic"},"College of Winterhold":{"aff":-55,"type":"estranged","relation":"former institution","note":"Dropped out or rejected the College''s cautious approach to destructive magic","worst":"Rejected for pursuing dangerous experimental applications of shock spells"},"Local Populations":{"aff":-25,"type":"contempt","relation":"feared outsiders","note":"Viewed as threats or test subjects; feared and avoided by locals"},"Necromancers":{"aff":-35,"type":"rival","relation":"competitors","note":"Occasional rivals for control of magical research sites"},"Apprentices":{"aff":55,"type":"mentor","relation":"valued students","note":"Rare but valued students who show promise in shock magic","best":"Finding a worthy student to carry on the storm magic tradition"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('storm_mage_adept', '{"College of Winterhold":{"aff":-75,"type":"enemy","relation":"former institution","note":"Expelled for pursuing volatile lightning experiments","worst":"Exile from the College for forbidden research"},"Warlock Covens":{"aff":55,"type":"platonic","relation":"faction","note":"Found kinship among outcast mages after expulsion","best":"Acceptance among fellow exiled spellcasters"},"Fellow Storm Mages":{"aff":45,"type":"professional","relation":"colleagues","note":"Mutual respect based on demonstrated magical prowess"},"Apprentice Mages":{"aff":35,"type":"mentor","relation":"students","note":"Occasionally teaches promising storm magic aptitude students"},"Local Settlements":{"aff":-45,"type":"enemy","relation":"neighbors","note":"Hostile interactions marked by mutual fear and distrust"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('storm_wizard', '{"Fellow Storm Mages":{"aff":35,"type":"rival","relation":"competitive colleagues","note":"Respectful but competitive in the pursuit of magical knowledge","best":"Sharing breakthroughs in shock magic research","worst":"Disputes over territory and experimental findings"},"College of Winterhold":{"aff":-35,"type":"estranged","relation":"former institution","note":"Left after becoming disillusioned with the College''s cautious approach to destructive magic","worst":"Being told to restrain their research for ethical concerns"},"Vigilants of Stendarr":{"aff":-80,"type":"enemy","relation":"hostile pursuers","note":"Seek to eliminate them as a dangerous magic user","worst":"Raids on their wilderness stronghold"},"Local Settlements":{"aff":-40,"type":"dismissive","relation":"feared outsider","note":"Common folk fear and avoid them; they have little regard for those who mistrust magic"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stormcloak_courier', '{"Ulfric Stormcloak":{"aff":90,"type":"fanatical","relation":"revered leader","note":"Devoted to Ulfric''s vision of a free Skyrim and directs potential recruits to him","best":"First heard Ulfric speak of Skyrim''s independence"},"Galmar Stone-Fist":{"aff":70,"type":"professional","relation":"direct superior","note":"Receives mission assignments and courier duties from Galmar"},"Imperial Legion":{"aff":-75,"type":"enemy","relation":"adversary","note":"Avoids Imperial patrols and carries intelligence they seek to intercept","worst":"Narrow escape from an Imperial ambush while carrying sensitive dispatches"},"Ralof":{"aff":55,"type":"platonic","relation":"fellow Stormcloak","note":"Both serve the same cause and can direct new recruits to Windhelm"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stormcloak_general', '{"Ulfric Stormcloak":{"aff":85,"type":"protective","relation":"commander","note":"Serves with unwavering loyalty as one of his most trusted generals","best":"Rising through the ranks to become a key military leader under Ulfric''s banner"},"Galmar Stone-Fist":{"aff":60,"type":"professional","relation":"fellow commander","note":"Fellow military commander who coordinates strategy for the rebellion"},"Imperial Legion":{"aff":-70,"type":"enemy","relation":"enemy faction","note":"Bitter enemies after disillusionment following the White-Gold Concordat","worst":"Watching the Empire surrender to Thalmor demands after the Great War"},"Thalmor":{"aff":-90,"type":"nemesis","relation":"hated adversary","note":"Deep hatred for their interference in Skyrim''s affairs and suppression of Nordic traditions","worst":"The White-Gold Concordat outlawing Talos worship"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stormcloak_guard', '{"Ulfric Stormcloak":{"aff":92,"type":"fanatical","relation":"revered leader","note":"Devoted with unwavering loyalty to Ulfric and his cause for Skyrim''s independence"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"despised oppressors","note":"Seen as the true threat to Skyrim and the root cause of the ban on Talos worship","worst":"The outlawing of Talos worship by Thalmor decree"},"Imperial Legion":{"aff":-80,"type":"enemy","relation":"foreign oppressors","note":"Sworn enemies representing Imperial domination over Skyrim","worst":"The Markarth Incident and Empire''s capitulation to the Thalmor"},"Elisif the Fair":{"aff":-65,"type":"contempt","relation":"Imperial puppet ruler","note":"Views her as an illegitimate collaborator with the Empire"},"Talos":{"aff":90,"type":"fanatical","relation":"revered deity","note":"Restoration of Talos worship is a core motivation for service"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stormcloak_quartermaster', '{"Galmar Stone-Fist":{"aff":65,"type":"professional","relation":"direct superior","note":"Galmar relies on his efficiency in managing camp resources"},"Ulfric Stormcloak":{"aff":80,"type":"fanatical","relation":"commander","note":"Serves with unwavering loyalty to the cause of Skyrim''s independence"},"Imperial Legion":{"aff":-55,"type":"enemy","relation":"former employer","note":"Once served in the Legion before joining the Stormcloak rebellion","worst":"Turning against former comrades when Ulfric called for independence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stormcloak_soldier', '{"Ulfric Stormcloak":{"aff":85,"type":"fanatical","relation":"revered leader","note":"Devoted follower who sees Ulfric as Skyrim''s rightful High King and the only hope for liberation","best":"Hearing Ulfric speak and knowing the cause is righteous"},"Galmar Stone-Fist":{"aff":60,"type":"professional","relation":"commander","note":"Respected military leader whose orders are followed without question"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"hated oppressors","note":"Primary motivation for joining the rebellion after witnessing their cruel enforcement of the Talos ban","worst":"Watching Thalmor persecute fellow Nords for worshipping Talos"},"Imperial Legion":{"aff":-75,"type":"enemy","relation":"sworn enemy","note":"Viewed as traitors who sold out Skyrim and Talos worship to the Thalmor","worst":"Seeing the Empire bow to the White-Gold Concordat"},"Fellow Stormcloak Soldiers":{"aff":70,"type":"platonic","relation":"comrades in arms","note":"Brothers and sisters bound by shared sacrifice and conviction in the cause"},"Nord Civilians":{"aff":40,"type":"protective","relation":"fellow Nords","note":"Duty-bound to shield them from Imperial and Thalmor oppression"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('storn_crag-strider', '{"Frea":{"aff":95,"type":"familial","relation":"daughter and apprentice","note":"Beloved daughter raised alone after his wife''s passing, trained in the shamanic traditions","best":"Teaching her the old ways and preparing her to lead","worst":"Knowing his sacrifice will leave her without a father"},"Skaal Villagers":{"aff":75,"type":"protective","relation":"his people","note":"Spiritual leader who guides, heals, and protects the Skaal community","best":"Maintained the magical barrier at great personal cost to shield them","worst":"Watching helplessly as many fell under Miraak''s spell"},"Hermaeus Mora":{"aff":-90,"type":"nemesis","relation":"ancient enemy","note":"Daedric Prince who covets the Skaal''s hidden knowledge; ultimately claims Storn''s life","best":"Resisted giving up Skaal secrets for decades","worst":"Killed him in exchange for the knowledge needed to stop Miraak"},"The All-Maker":{"aff":100,"type":"fanatical","relation":"deity","note":"The god Storn serves as intermediary, drawing power and purpose from devotion","best":"Channeled the All-Maker''s power to protect his people","worst":"Could not call upon greater intervention against Miraak''s return"},"Miraak":{"aff":-80,"type":"enemy","relation":"threat to the Skaal","note":"First Dragonborn whose return endangers Solstheim and enslaved the Skaal","best":"His ancient knowledge helped identify the threat","worst":"Enslaved Skaal villagers through dark magic to build shrines"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stray_dog', '{"Player Character":{"aff":70,"type":"protective","relation":"potential adopted companion","note":"Offers unwavering loyalty and combat assistance to those who earn trust","best":"Enthusiastic tail wagging and barking when chosen as companion","worst":"Vanishes if told to wait before being formally adopted"},"Wolves":{"aff":-80,"type":"enemy","relation":"territorial rival","note":"Frequent violent encounters over territory in the wilds","worst":"Surviving numerous wolf attacks while alone"},"Skeevers":{"aff":-50,"type":"enemy","relation":"common adversary","note":"Regular hostile encounters in Skyrim''s wilderness"},"Previous Owners":{"aff":-40,"type":"estranged","relation":"former owners","note":"Either escaped or was abandoned, forcing feral adaptation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('stromm', '{"Calcelmo":{"aff":55,"type":"mentor","relation":"mentor","note":"Relocated to Markarth to study under Calcelmo but ultimately disregarded his warnings about Nchuand-Zel","best":"Accepted as student and brought to Markarth for Dwemer studies","worst":"Defied mentor''s warnings before the fatal expedition"},"Expedition Colleagues":{"aff":60,"type":"platonic","relation":"fellow mages","note":"Markarth mages who together ignored Calcelmo''s advice and entered Nchuand-Zel","best":"Shared scholarly enthusiasm exploring Dwemer ruins","worst":"All perished fighting the Falmer in the depths"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('student', '{"College of Winterhold":{"aff":65,"type":"admirer","relation":"aspiring member","note":"Desperately seeks admission after being rejected for inadequate ward mastery","best":"Felt ready to try the College again after learning from a mentor","worst":"Rejected from the College due to poor ward spell casting"},"Player":{"aff":75,"type":"student","relation":"aspiring mentee","note":"Sees the player as a hero and seeks instruction on ward spells","best":"Player agreed to demonstrate ward magic so he could study it","worst":"Player refused to help with training, leaving him to practice alone"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('styrr', '{"Parents":{"aff":75,"type":"familial","relation":"predecessors in priesthood","note":"Inherited his position and devotion to Arkay from his father and mother, the previous priest and priestess."},"Falk Firebeard":{"aff":45,"type":"professional","relation":"collaborator","note":"Works with the Solitude steward on supernatural threats; Falk sends aid to Styrr during the Potema crisis."},"Captain Aldis":{"aff":25,"type":"professional","relation":"cooperative official","note":"Appealed to Aldis to allow Roggvir a proper Nord burial after his execution."},"Potema":{"aff":-90,"type":"nemesis","relation":"ancient adversary","note":"Considers her the darkness pervading Solitude; has studied her history and dedicated himself to guarding against her return.","worst":"Her spirit summoned in Solitude, threatening to rise again and unleash undead upon the city."},"Temple of the Divines Priests":{"aff":40,"type":"platonic","relation":"fellow clergy","note":"Allied religious figures in Solitude; the Catacombs connect to their temple."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sudi', '{"Habd":{"aff":95,"type":"familial","relation":"father","note":"Loving father who gave her a dagger as his final act before being dragged away to be eaten","best":"gave me his dagger so I would not suffer","worst":"dragged away screaming after the chaurus bit him"},"Ramati":{"aff":90,"type":"familial","relation":"mother","note":"Killed during the initial Falmer invasion of their home","worst":"mother killed by Falmer in the lighthouse"},"Mani":{"aff":85,"type":"familial","relation":"brother","note":"Shared a room with her, killed by the Falmer in their lair","worst":"they killed Mani in the dark"},"Falmer":{"aff":-100,"type":"nemesis","relation":"captors","note":"Murdered her family and intended to feed her alive to their chaurus","worst":"kept me caged to feed to their brooding chaurus reaper"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sulla_trebatius', '{"Umana":{"aff":-70,"type":"betrayed","relation":"former bodyguard","note":"Once his constant companion, now perceived as a threat due to paranoia from Falmer captivity","worst":"Accused her of waiting to steal the glory for herself and ultimately attacked her"},"J''darr":{"aff":-25,"type":"estranged","relation":"former expedition member","note":"Khajiit expedition member abandoned after escaping Falmer captivity"},"Yag gra-Gortwog":{"aff":-20,"type":"estranged","relation":"former expedition member","note":"Orc warrior who perished in the ruins after Sulla abandoned the group"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sultry_maiden', '{"Pelagius III":{"aff":65,"type":"romantic","relation":"former lover","note":"A romanticized memory of desire from Pelagius'' youth, twisted into a hagraven by his madness before being restored","best":"Intimate moments from Pelagius'' early days at court","worst":"Her memory corrupted into a hagraven by his deteriorating mind"},"Sheogorath":{"aff":10,"type":"servant","relation":"manifestation","note":"Exists within Pelagius'' mind as part of Sheogorath''s magical construct","best":"Her idealized form preserved through the Wabbajack''s transformation","worst":"Subject to the Madgod''s whims and the instability of Pelagius'' psyche"},"Other Sultry Maidens":{"aff":-25,"type":"rival","relation":"competitors","note":"Competed against other court women for Pelagius'' attention and favor","worst":"Vying for the same man''s affections at court"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('summerset_shadow', '{"Linwe":{"aff":65,"type":"professional","relation":"guild leader","note":"Commands respect and loyalty rooted in shared elitism rather than true camaraderie"},"Thieves Guild":{"aff":-80,"type":"rival","relation":"rival organization","note":"Views them with contempt as brutish and inferior criminals","worst":"Their crude methods and presence in Skyrim are an insult to refined thievery"},"Niranye":{"aff":40,"type":"transactional","relation":"fence","note":"Windhelm contact who facilitates fencing of stolen goods"},"Summerset Shadows":{"aff":50,"type":"professional","relation":"guild","note":"Fellow operatives bound by shared elitism and sophisticated criminal standards"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('susanna_the_wicked', '{"Calixto Corrium":{"aff":-45,"type":"suspicious","relation":"patron","note":"Regular patron who makes her unexplainably uneasy; her instincts were justified as he is the Butcher who murdered her","worst":"Sensed something deeply wrong about him but could never name it"},"Thoring":{"aff":40,"type":"professional","relation":"employer","note":"Values her ability to draw customers to Candlehearth Hall"},"Kjeld the Younger":{"aff":55,"type":"romantic","relation":"boyfriend","note":"Her romantic partner, though the relationship is kept quiet"},"Brunwulf Free-Winter":{"aff":35,"type":"transactional","relation":"informant","note":"Secret source of intelligence regarding Dunmer affairs in the Gray Quarter"},"Viola Giordano":{"aff":30,"type":"transactional","relation":"gossip source","note":"Frequent source of city gossip and rumors for her information network"},"Elda Early-Dawn":{"aff":10,"type":"professional","relation":"colleague","note":"Cautious co-worker who warns patrons about Susanna''s flirtatious tactics","worst":"Elda publicly undermines her methods to customers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('suvaris_atheron', '{"Torbjorn Shatter-Shield":{"aff":45,"type":"professional","relation":"employer","note":"She manages his shipping operations and takes pride in delivering results despite racial barriers.","best":"Trusted with full administrative control of the clan''s shipping business"},"Faryl Atheron":{"aff":75,"type":"familial","relation":"brother","note":"Younger brother she is fiercely protective of in Windhelm''s hostile environment."},"Aval Atheron":{"aff":75,"type":"familial","relation":"brother","note":"Brother who shares the family residence in the Gray Quarter."},"Rolff Stone-Fist":{"aff":-85,"type":"enemy","relation":"harasser","note":"Racist Nord who regularly harasses and threatens her with violence.","worst":"Threatened to visit her at night to forcibly interrogate her as a supposed spy"},"Angrenor Once-Honored":{"aff":-70,"type":"enemy","relation":"harasser","note":"Joins Rolff in harassing her with false Imperial spy accusations."},"Argonian Dock Workers":{"aff":-25,"type":"contempt","relation":"laborers","note":"Views them as lazy and resents the tension between Dunmer and Argonians complicating dock operations."},"Ambarys Rendar":{"aff":-10,"type":"suspicious","relation":"acquaintance","note":"Dunmer bar patron who needles her about working for Nords, creating awkward friction."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('svaknir', '{"King Olaf One-Eye":{"aff":-95,"type":"nemesis","relation":"persecutor","note":"Imprisoned and killed Svaknir for exposing his fraudulent dragon tale","worst":"Left to die in Dead Men''s Respite for speaking truth"},"Bards College":{"aff":65,"type":"professional","relation":"alma mater","note":"Trained there and contributed to the Poetic Edda","best":"Developed his craft and scholarly dedication to truth"},"Numinex":{"aff":35,"type":"curious","relation":"subject of verse","note":"Sought to tell the dragon''s true story of capture while weakened","best":"Uncovered evidence of Numinex''s true capture"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('svana_far-shield', '{"Haelga":{"aff":-55,"type":"estranged","relation":"aunt and employer","note":"Deeply resents her aunt''s promiscuous lifestyle and the degrading conditions she''s forced to work under","worst":"Mocked by Haelga about Sibbi and told she should just let him bed her and be done with it"},"Sibbi":{"aff":65,"type":"crush","relation":"romantic interest","note":"Believes they are in love, though Haelga claims he only wants to bed her","best":"Dreams of genuine love and saving herself for someone special like Sibbi"},"Bolli":{"aff":-35,"type":"contempt","relation":"aunt''s lover","note":"Views him with disgust as one of Haelga''s conquests"},"Hofgrir":{"aff":-35,"type":"contempt","relation":"aunt''s lover","note":"Views him with disgust as one of Haelga''s conquests"},"Indaryn":{"aff":-35,"type":"contempt","relation":"aunt''s lover","note":"Views him with disgust as one of Haelga''s conquests"},"Niluva":{"aff":35,"type":"protective","relation":"tenant","note":"Defends Niluva against Haelga''s criticism and gives her patience with rent payments"},"Father":{"aff":80,"type":"familial","relation":"deceased father","note":"Held in high regard and deeply missed, kept his possession as a cherished memento"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('svari', '{"Greta":{"aff":85,"type":"familial","relation":"mother","note":"Deeply loves and worries about her mother''s grief and withdrawal from the Temple","worst":"Watching her mother stop going to the Temple after Uncle Roggvir''s death"},"Addvar":{"aff":75,"type":"familial","relation":"father","note":"Respects her father who works hard to keep the family stable despite hardship"},"Roggvir":{"aff":70,"type":"familial","relation":"uncle","note":"His execution has deeply traumatized the family","worst":"His public execution in Solitude"},"Kayd":{"aff":30,"type":"platonic","relation":"playmate","note":"Occasionally plays tag with in Solitude"},"Minette Vinius":{"aff":30,"type":"platonic","relation":"playmate","note":"Occasionally plays with in Solitude"},"Jala":{"aff":-10,"type":"suspicious","relation":"merchant","note":"Stole an apple from her cart and was caught","worst":"Being confronted by her father about stealing from Jala"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sven', '{"Hilde":{"aff":30,"type":"familial","relation":"mother","note":"Lives with her but routinely dismisses her warnings and concerns as fantasy","worst":"Called her crazy and dismissed her dragon sighting as ramblings"},"Camilla Valerius":{"aff":70,"type":"crush","relation":"romantic interest","note":"Composing a ballad for her and schemes to eliminate his rival","best":"Dreams of winning her affection through his music and devotion"},"Faendal":{"aff":-45,"type":"rival","relation":"romantic rival","note":"Deeply resents the elf for pursuing Camilla","worst":"Forged a venomous fake letter to sabotage Faendal''s chances with Camilla"},"Delphine":{"aff":15,"type":"professional","relation":"employer","note":"Performs at her inn for sixteen hours daily; she frequently admonishes him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('swanhvir', '{"Gestur Rockbreaker":{"aff":35,"type":"professional","relation":"supervisor","note":"Respects and obeys without question, finding stability in his authority","best":"Acknowledged with keep up the good work after a productive month"},"Bryling":{"aff":15,"type":"transactional","relation":"employer","note":"Distant mine owner with no direct interaction"},"Sorli the Builder":{"aff":10,"type":"neutral","relation":"neighbor","note":"Minimal interaction; delivers lumber to her house as part of work routine"}}')
ON CONFLICT (npc_name) DO UPDATE
