INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('swims-in-deep-water', '{"Viriya":{"aff":65,"type":"professional","relation":"colleague","note":"Close associate and frequent collaborator at the Riften Fishery","best":"Working together to keep the Fishery running"},"Player":{"aff":55,"type":"mentor","relation":"student","note":"Takes promising anglers under his tutelage to master the craft and help with the Fishery","best":"Telling student they are like his brood after completing legendary challenges"},"Maven Black-Briar":{"aff":15,"type":"suspicious","relation":"business associate","note":"Cautious relationship with Riften''s power broker"},"Riften Fishery Workers":{"aff":45,"type":"mentor","relation":"employees","note":"Respected employer and mentor to the fishery workers"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sybille_stentor', '{"Torygg":{"aff":80,"type":"protective","relation":"former ward","note":"Helped raise him and was deeply proud of the king he became","best":"Watching Torygg take the throne as a fine king","worst":"Being present at his gruesome death by Ulfric''s hand"},"Elisif the Fair":{"aff":40,"type":"professional","relation":"liege","note":"Serves as her court wizard, continuing Torygg''s legacy through her"},"Falk Firebeard":{"aff":-25,"type":"rival","relation":"political rival","note":"Mutual distrust and court rivalry at the Blue Palace"},"Ulfric Stormcloak":{"aff":-75,"type":"enemy","relation":"slayer of her ward","note":"Killed Torygg as a political symbol; she views him with contempt"},"General Tullius":{"aff":35,"type":"professional","relation":"fellow Imperial supporter","note":"Professional respect as mutual supporters of the Empire in Solitude"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('sylgja', '{"Verner Rock-Chucker":{"aff":80,"type":"familial","relation":"father","note":"Maintains contact through letters and gifts; unable to visit due to leg injury","best":"Exchanging letters and gifts delivered via satchel","worst":"Unable to make the journey to see him due to her injury"},"Annekke Crag-Jumper":{"aff":80,"type":"familial","relation":"mother","note":"Lives in Darkwater Crossing; stays in touch through correspondence","best":"Receiving letters back from her mother through delivered satchels","worst":"Separated by distance and her limited mobility"},"Filnjar":{"aff":45,"type":"professional","relation":"employer","note":"Local leader of Shor''s Stone and mine operator"},"Erandur":{"aff":65,"type":"grateful","relation":"healer","note":"Traveling priest of Mara who partially healed her after her fall in Redbelly Mine","best":"Healed her when she was badly injured and could barely walk"},"Odfel":{"aff":30,"type":"platonic","relation":"fellow miner","note":"Works alongside him at Redbelly Mine"},"Grogmar gro-Burzag":{"aff":30,"type":"platonic","relation":"fellow miner","note":"Works alongside him at Redbelly Mine"}}')
ON CONFLICT (npc_name) DO UPDATE
