INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('synda_llanith', '{"Dravin Llanith":{"aff":80,"type":"romantic","relation":"husband","note":"Beloved partner she constantly tries to protect from his own rashness and confrontational outbursts","best":"Building a life together on Merryfair Farm through shared hardship","worst":"His bitter threats toward soldiers that could land him in the Riften dungeon"},"Riften Guards":{"aff":25,"type":"professional","relation":"farm protectors","note":"Maintains cautiously cordial relations to ensure continued protection for the farm"},"Marise Aravel":{"aff":35,"type":"platonic","relation":"fellow Dunmer","note":"Fellow Dark Elf in Riften with whom she occasionally trades"}}')
