INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('syndus', '{"Thieves Guild":{"aff":75,"type":"professional","relation":"guild supplier","note":"Loyal merchant affiliate who refuses trade with anyone who crosses the Guild"},"Delvin Mallory":{"aff":70,"type":"grateful","relation":"guild contact","note":"Primary Guild contact who helped establish his business at the Ragged Flagon","best":"Delvin helped him secure his position as the Guild''s premier fletcher"},"Tonilia":{"aff":45,"type":"professional","relation":"fellow merchant","note":"Professional relationship as fellow merchant operating in the Ragged Flagon"},"Vekel the Man":{"aff":40,"type":"professional","relation":"business associate","note":"Business associate at the Ragged Flagon"}}')
ON CONFLICT (npc_name) DO UPDATE
