INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('synod_researcher', '{"Synod Council":{"aff":55,"type":"professional","relation":"employer","note":"Commissioned her Mzulft expedition; she was politically naive about their true motives","worst":"Sent on a fatal expedition with inadequate protection"},"Fellow Researchers":{"aff":65,"type":"platonic","relation":"colleagues","note":"Close academic colleagues who shared her work and fate at Mzulft","worst":"All perished together in the Dwemer ruins"},"College of Winterhold":{"aff":-25,"type":"rival","relation":"rival institution","note":"Viewed with skepticism per Synod policy; sought to prove Imperial research superiority over them"},"Nordic Locals":{"aff":-15,"type":"contempt","relation":"locals","note":"Maintained cautious distance, viewing them as primitive and superstitious"}}')
ON CONFLICT (npc_name) DO UPDATE
