INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('taarie', '{"Endarie":{"aff":65,"type":"familial","relation":"twin sister and business partner","note":"Close but tense working relationship with frequent bickering","best":"Co-own and operate Radiant Raiment together as a pair","worst":"Told her to sew her mouth shut when customers are within earshot"},"Elisif the Fair":{"aff":40,"type":"professional","relation":"aspiring court client","note":"Seeks permanent clothing contract with the Blue Palace","best":"Elisif loved the modeled outfit and promised to place an order"},"Vittoria Vici":{"aff":25,"type":"professional","relation":"regular customer","note":"Business associate and repeat client"},"Erikur":{"aff":15,"type":"professional","relation":"prominent client","note":"Local thane and customer"}}')
