INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('takes-in-light', '{"Savos Aren":{"aff":25,"type":"platonic","relation":"fellow student, expedition leader","note":"Trusted him enough to follow despite her reservations; his leadership led to her death and he left her behind when she couldn''t continue","best":"Shared academic ambitions at the College","worst":"Abandoned her in Labyrinthian when she could no longer go on"},"Atmah":{"aff":60,"type":"platonic","relation":"close friend","note":"Close friend whose expedition idea ultimately doomed them; Atmah protested leaving her behind","best":"Close friendship and mutual support at the College","worst":"Atmah''s idea for the expedition led to everyone''s deaths"},"Elvali Veren":{"aff":40,"type":"platonic","relation":"fellow student","note":"Fellow expedition member who was killed before her, dragged away from behind","worst":"Witnessed her being grabbed and killed in Labyrinthian"},"Hafnar Ice-Fist":{"aff":35,"type":"platonic","relation":"colleague","note":"Pragmatic fellow expedition member who argued against turning back"},"Girduin":{"aff":35,"type":"platonic","relation":"fellow student","note":"First of the group to die in Labyrinthian","worst":"His death was the first sign the expedition was doomed"},"College of Winterhold":{"aff":65,"type":"student","relation":"alma mater","note":"Promising scholar whose magical career was cut tragically short","best":"Thrived in magical studies and earned a place among elite students"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('talen-jei', '{"Keerava":{"aff":90,"type":"romantic","relation":"beloved and employer","note":"Smitten since arriving in Riften; seeks to marry her by Black Marsh tradition","best":"She gave him a home and purpose when he wandered into Riften","worst":"Fears he may never afford the flawless amethysts for her ring"},"Thieves Guild":{"aff":-85,"type":"enemy","relation":"despised organization","note":"Views them as vermin that make Riften horrible","worst":"They extort honest businesses like the Bee and Barb"},"Maven Black-Briar":{"aff":-50,"type":"contempt","relation":"Thieves Guild patron","note":"Tense relationship due to her Guild connections and influence over the city"}}')
ON CONFLICT (npc_name) DO UPDATE
