INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('talsgar_the_wanderer', '{"Bards College":{"aff":40,"type":"professional","relation":"alumnus","note":"Graduated but found the structured academic environment too constraining for his free spirit; still maintains loose ties and contributes new songs"},"Bandits":{"aff":-65,"type":"enemy","relation":"adversary","note":"Frequent attackers who underestimate his combat abilities","worst":"Ambushed on the road by those who saw an easy target in a wandering bard"}}')
