INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('talvas_fathryon', '{"Neloth":{"aff":25,"type":"mentor","relation":"master","note":"Fears and respects his demanding master, endures harsh treatment for the chance to learn","best":"Picks up invaluable knowledge from watching a great Telvanni wizard at work","worst":"Used as a test subject in Neloth''s experiments and subjected to constant cutting remarks"},"Varona Nelas":{"aff":20,"type":"platonic","relation":"fellow resident","note":"She worries about his reckless conjuration; he finds her concern nagging but not malicious","best":"She genuinely cares about his safety and tries to steer him toward caution","worst":"Constant arguments over his dangerous ash guardian experiments"},"Elynea Mothren":{"aff":30,"type":"platonic","relation":"fellow resident","note":"The tower''s mycologist who helps clean up after his magical mishaps","best":"Willingly helps deal with the aftermath of his failed experiments","worst":"His accidents create extra work and mess for her"}}')
