INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('talvur', '{"Karan":{"aff":95,"type":"romantic","relation":"lover","note":"Died alongside her during their attempted elopement from her noble family.","best":"Planning and executing their escape together, risking everything for love.","worst":"Their journey ending in death before reaching freedom."},"Karan''s Father":{"aff":-70,"type":"enemy","relation":"lover''s father","note":"Unnamed Nord nobleman whose opposition forced the couple to flee secretly.","worst":"His disapproval and presumed hostility driving them into the wilderness."}}')
