INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tandil', '{"Quaranir":{"aff":50,"type":"professional","relation":"fellow Psijic, mission superior","note":"Served under Quaranir''s lead during the Eye of Magnus crisis"},"Gelebros":{"aff":40,"type":"professional","relation":"fellow Psijic","note":"Worked together to contain the Eye of Magnus"},"Ancano":{"aff":-85,"type":"enemy","relation":"magical threat","note":"Viewed as a dangerous threat for abusing the Eye of Magnus","worst":"Ancano''s reckless abuse of the Eye destabilized the College"},"College of Winterhold":{"aff":15,"type":"neutral","relation":"magical institution","note":"Maintains professional distance while recognizing their custodial role"}}')
