INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('taron_dreth', '{"Katria":{"aff":-100,"type":"betrayed","relation":"betrayed colleague","note":"Stole her Aetherium research, destroyed her reputation, indirectly caused her death at Arkngthamz","worst":"Her original research threatens to expose his entire fraudulent career"},"Hired Mercenaries":{"aff":15,"type":"transactional","relation":"bodyguards","note":"Three paid mercenaries who protect him and attack on his command"},"Calcelmo":{"aff":5,"type":"transactional","relation":"fraudulently claimed colleague","note":"Falsely claims professional association to bolster his credibility with no evidence of actual relationship"},"Player":{"aff":-80,"type":"suspicious","relation":"potential threat to his fraud","note":"Approaches anyone carrying Aetherium, attacks if they mention Katria","worst":"Learning Katria''s name triggers violent attempt to silence them"}}')
