INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('taunting_adventurer', '{"Local Guards":{"aff":-35,"type":"suspicious","relation":"frequent troublemaker","note":"Guards receive regular complaints about their intimidation of travelers","worst":"Yet another complaint filed against them for harassing citizens"},"Inn Keepers":{"aff":-15,"type":"transactional","relation":"difficult customer","note":"Tolerated only because they pay for rooms and drinks","best":"Coin on the table without breaking anything","worst":"Scaring off other paying patrons with their aggression"},"Fellow Mercenaries":{"aff":20,"type":"professional","relation":"grudging peers","note":"Respected for combat skill but disliked for their attitude","best":"Acknowledged as a capable fighter in the field","worst":"Their arrogance poisoning a job''s morale"},"Common Folk":{"aff":-50,"type":"contempt","relation":"intimidated targets","note":"Viewed as weaklings to be mocked and bullied","best":"A peasant backing down without needing violence","worst":"Someone standing up to them and making them look foolish"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('teeba-ei', '{"Sorli the Builder":{"aff":82,"type":"indebted","relation":"employer and Jarl","note":"Took him in near death without pressing about his past; he serves her loyally in return","best":"Given shelter and a second chance at life when nearly frozen"},"Jesper":{"aff":55,"type":"platonic","relation":"friend and fellow miner","note":"Shares a daily two-hour dinner with Jesper at the mining camp"},"Gestur Rockbreaker":{"aff":30,"type":"professional","relation":"mine boss","note":"Cordial but formal working relationship; Gestur checks on his wellbeing"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tekla', '{"Dengeir of Stuhn":{"aff":40,"type":"professional","relation":"employer","note":"Loyal maid turned steward despite his paranoid accusations; defends him to others","best":"Promoted her to steward immediately upon becoming Jarl again","worst":"Constantly suspects her of spying for his nephew despite her loyalty"},"Narri":{"aff":65,"type":"familial","relation":"sister","note":"Supportive sisters seeking honest work in Falkreath","best":"Narri tried to get her hired at Dead Man''s Drink","worst":"Cannot work together because Valga cannot afford both"},"Solaf":{"aff":70,"type":"romantic","relation":"boyfriend","note":"Romantic partner despite the political tensions in Falkreath"},"Thadgeir":{"aff":55,"type":"protective","relation":"employer''s brother","note":"Offers kindness and encouragement when Dengeir is harsh","best":"Told her not to let Dengeir get to her and that she does fine work"},"Jarl Siddgeir":{"aff":-10,"type":"suspicious","relation":"Dengeir''s nephew","note":"Falsely accused of spying for him by paranoid Dengeir"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('teldryn_sero', '{"Previous Patron":{"aff":15,"type":"professional","relation":"former employer","note":"A traditional Nord warrior who paid extremely well but whose reckless bloodlust led Teldryn to abandon him at a massive bandit encampment","best":"He paid very well for my services","worst":"His menacing grin at that bandit camp told me I''d never see him again"},"Grendis Rolovo":{"aff":65,"type":"professional","relation":"master armorer","note":"One of Morrowind''s finest master armor smiths who crafted Teldryn''s custom chitin armor","best":"He forged my signature chitin armor to my exact specifications"},"Geldis Sadri":{"aff":40,"type":"professional","relation":"cornerclub owner","note":"Proprietor of the Retching Netch where Teldryn bases his mercenary operations"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('telrav', '{"Nilheim Bandits":{"aff":35,"type":"professional","relation":"leader","note":"Coordinates sophisticated ambush operations with his crew at Nilheim tower","best":"Successful ambushes that brought in substantial loot","worst":"Finding all his men slaughtered by an alert traveler"},"Travelers":{"aff":-75,"type":"contempt","relation":"marks","note":"Views compassionate travelers as prey to be exploited and eliminated","worst":"When a mark sees through the ruse and turns the tables"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('temba_wide-arm', '{"Gwilin":{"aff":-15,"type":"professional","relation":"apprentice","note":"Constantly frustrated with his incompetence but keeps him employed and training him","worst":"Yelled at him for cutting boards at the wrong length and dismissed his opinions"},"Wilhelm":{"aff":15,"type":"transactional","relation":"innkeeper","note":"Regular patron of Vilemyr Inn where she lodges and takes all her meals"},"Bears":{"aff":-85,"type":"enemy","relation":"threat to livelihood","note":"Bears scratch trees and ruin her lumber quality, driving her toward financial ruin","worst":"Forced to scour Skyrim for untouched trees, costing time and money"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thadgeir', '{"Dengeir":{"aff":55,"type":"familial","relation":"brother","note":"Supports his brother despite finding his paranoia difficult, tempering his suspicions about Tekla and others.","best":"Standing by Dengeir after he lost the Jarl''s throne","worst":"Enduring Dengeir''s accusation that he might be the one sharing secrets with Siddgeir"},"Siddgeir":{"aff":25,"type":"familial","relation":"nephew","note":"Maintains a diplomatic but distant relationship with the nephew who supplanted his brother as Jarl."},"Tekla":{"aff":60,"type":"protective","relation":"household confidant","note":"Defends Tekla against Dengeir''s suspicions and offers her genuine encouragement.","best":"Telling Tekla not to let his brother get to her and that she''s doing a fine job"},"Berit":{"aff":75,"type":"platonic","relation":"war companion","note":"Deceased friend whose memory he honors with a proper burial by fire, respecting his wishes.","best":"Giving Berit a proper burial by fire as the old warrior would have wanted"},"Runil":{"aff":40,"type":"platonic","relation":"priest of Arkay","note":"Acquaintance who handles burial rites for the fallen Thadgeir brings to him."},"Helvard":{"aff":40,"type":"platonic","relation":"ally","note":"Listed as an ally, likely bonded through shared service to Falkreath."},"Nenya":{"aff":40,"type":"platonic","relation":"ally","note":"Listed as an ally, likely through shared connections to Falkreath''s governance."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thaena', '{"Jarl Korir":{"aff":85,"type":"romantic","relation":"husband and liege","note":"Serves as both wife and housecarl, sharing his hatred for the College and devotion to Winterhold","best":"Their marriage united love and duty in service to Winterhold"},"Assur":{"aff":80,"type":"protective","relation":"son","note":"Determined to raise him strong through hardship, believing it will forge him into a great man","best":"Watching Assur grow resilient despite Winterhold''s hardships"},"Birna":{"aff":15,"type":"neutral","relation":"local merchant","note":"Visits her shop daily but their exchanges are terse and occasionally sharp"},"College of Winterhold":{"aff":-80,"type":"enemy","relation":"hated institution","note":"Blames the College entirely for Winterhold''s destruction and decline","worst":"The Great Collapse that destroyed Winterhold"},"Imperial Legion":{"aff":-70,"type":"enemy","relation":"bitter foe","note":"Would rather see Winterhold swallowed by the sea than ruled by the Empire","worst":"Being exiled from Winterhold under Imperial rule"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thalmor', '{"Empire":{"aff":-35,"type":"rival","relation":"coerced treaty partner","note":"Tense peace maintained through the White-Gold Concordat after devastating the Empire in the Great War","best":"Forcing the White-Gold Concordat and disbanding the Blades","worst":"The Empire''s counter-attack reclaiming the Imperial City"},"Stormcloaks":{"aff":-80,"type":"enemy","relation":"active insurgency target","note":"Violently opposed to the Talos-worshipping rebellion; Justiciars engage Stormcloaks on sight","worst":"Stormcloak defiance spreading across Skyrim"},"Blades":{"aff":-95,"type":"nemesis","relation":"hunted remnants","note":"Sworn enemies disbanded by the Concordat and hunted nearly to extinction","best":"Nearly eradicating the Blades as an order"},"Bosmer":{"aff":25,"type":"protective","relation":"subjugated Dominion ally","note":"Official allies within the Aldmeri Dominion though clearly subordinate to Altmer rule","best":"Bosmer regents joining the Dominion alliance"},"College of Winterhold":{"aff":-20,"type":"suspicious","relation":"monitored institution","note":"Stationed Ancano as advisor to watch magical activities; distrustful of independent mages"},"Talos Worshippers":{"aff":-85,"type":"enemy","relation":"persecuted heretics","note":"Actively hunt and imprison those violating the ban on Talos worship","best":"Outlawing Talos worship across Imperial provinces","worst":"Persistent underground worship despite enforcement"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tharstan', '{"Fanari Strong-Voice":{"aff":65,"type":"platonic","relation":"chieftain and host","note":"Warm professional relationship with mutual respect and friendly banter","best":"Fanari called him sweet as honey from the comb"},"Nikulas":{"aff":55,"type":"platonic","relation":"young friend","note":"Enjoys sharing travel stories and tales with the eager young villager","best":"Sharing stories of his travels across Tamriel with Nikulas"},"Skaal Village":{"aff":40,"type":"neutral","relation":"hosts","note":"One of the rare outsiders accepted by the insular Skaal community","best":"Being welcomed and accommodated despite their usual wariness of outsiders"},"Player":{"aff":50,"type":"professional","relation":"hired protector","note":"Hired the player to watch his back while exploring Vahlok''s Tomb","best":"Witnessing the remarkable discoveries within Vahlok''s Tomb together"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('the_caller', '{"Orthorn":{"aff":-20,"type":"contempt","relation":"former subordinate","note":"Used him to steal College texts; traded him away without hesitation","worst":"Bartered him to the College''s agent in exchange for the books"},"College of Winterhold":{"aff":-65,"type":"rival","relation":"estranged institution","note":"Left over restrictive research protocols; orchestrated theft of their rare volumes","worst":"Their cautious restrictions stifled her research"},"Fellglow Keep Mages":{"aff":40,"type":"professional","relation":"followers","note":"Leads their magical research; they respect her expertise","best":"They followed her to pursue unrestricted magical research"},"Savos Aren":{"aff":-50,"type":"contempt","relation":"former arch-mage","note":"Views him as overcautious; dismisses his followers as lackeys"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

