SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thonar_silver-blood', '{"Thongvor Silver-Blood":{"aff":45,"type":"familial","relation":"older brother and family head","note":"Thonar handles operations while Thongvor pursues politics, but resents being the hands rather than the head","best":"Building the Silver-Blood empire together across Markarth","worst":"Betrid openly questioning which brother truly runs the family"},"Betrid Silver-Blood":{"aff":25,"type":"estranged","relation":"wife","note":"Loveless political marriage; she married only for wealth and mocked his ambition, yet her murder exposed hidden attachment","worst":"Her constant belittlement of his status within the family"},"Madanach":{"aff":-35,"type":"transactional","relation":"secret arrangement partner","note":"Orchestrated a deal to control the Forsworn through Madanach, but the arrangement is built on mutual distrust and coercion","best":"The deal initially kept Markarth''s Forsworn problem manageable","worst":"Madanach''s followers murdered Betrid, shattering the arrangement"},"Rhiada":{"aff":35,"type":"crush","relation":"desk clerk","note":"Makes inappropriate remarks about her appearance despite her marriage to Eltrys"},"Nepos the Nose":{"aff":10,"type":"suspicious","relation":"business associate","note":"Keeps Nepos in line for silver production, unaware or willfully blind to his Forsworn loyalties"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thongvor_silver-blood', '{"Thonar Silver-Blood":{"aff":70,"type":"familial","relation":"brother","note":"Older brother and business partner in the Silver-Blood family enterprises"},"Ulfric Stormcloak":{"aff":85,"type":"fanatical","relation":"rebellion leader","note":"Views Ulfric as a hero who saved Markarth from the Forsworn, compares him to Talos","best":"Ulfric used the Thu''um to shout the Forsworn from the walls and reclaimed the city"},"Jarl Igmund":{"aff":-65,"type":"rival","relation":"political rival","note":"Considers him an Imperial puppet and coward who ignores the Silver-Bloods","worst":"Igmund refuses to grant the Silver-Blood family a say despite their wealth and influence"},"Brother Verulus":{"aff":-50,"type":"suspicious","relation":"priest of Arkay","note":"Suspects him of Imperial sympathies and hiding something in the Hall of the Dead","worst":"Denied access to his honored ancestors'' remains and accused Verulus of desecration"},"Forsworn":{"aff":-90,"type":"nemesis","relation":"enemy insurgents","note":"Considers them heathen criminals deserving violent suppression and enslavement in Cidhna Mine"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thonjolf', '{"Kraldar":{"aff":90,"type":"servant","relation":"housecarl","note":"Serves with unwavering loyalty and genuine belief in his master''s vision for Winterhold","best":"Standing by Kraldar through Winterhold''s decline and into his ascension as Jarl","worst":"Watching Kraldar''s dinner invitations to the Arch-Mage repeatedly go unanswered"},"Malur Seloth":{"aff":-45,"type":"contempt","relation":"fellow servant","note":"Despises his unreliability and lack of pride in his work","worst":"Malur refusing tasks without even hearing what they are"},"Arch-Mage Aren":{"aff":5,"type":"professional","relation":"diplomatic contact","note":"Delivers Kraldar''s invitations on behalf of his master despite repeated refusals","worst":"Delivering yet another dinner invitation that will likely be ignored"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thonnir', '{"Laelette":{"aff":65,"type":"familial","relation":"wife","note":"Loved deeply; turned into a vampire by Alva and ultimately killed","best":"Raising Virkmund together as a family","worst":"Discovering her corpse and realizing she had become a vampire"},"Virkmund":{"aff":85,"type":"protective","relation":"son","note":"Devoted father struggling to shield him from the truth about his mother''s fate","best":"Being there for his boy after Laelette vanished","worst":"Knowing he must eventually tell Virkmund what really happened"},"Alva":{"aff":-90,"type":"nemesis","relation":"wife''s corruptor","note":"Trusted townsperson revealed as the vampire who turned Laelette","worst":"Learning Alva seduced and damned his wife to undeath"},"Jorgen":{"aff":35,"type":"professional","relation":"employer","note":"Works at his mill and stood together against the vampire threat"},"Jarl Idgrod Ravencrone":{"aff":20,"type":"professional","relation":"jarl","note":"Looks to her for protection but frustrated by Morthal''s dangers being ignored"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thorald_gray-mane', '{"Fralia Gray-Mane":{"aff":90,"type":"familial","relation":"mother","note":"Deeply loves and seeks to protect through exile; sends coded message of hope","best":"Sending word that the winter''s cold wind bears aloft next summer''s seeds","worst":"Knowing his captivity causes her endless grief"},"Avulstein Gray-Mane":{"aff":95,"type":"familial","relation":"brother","note":"Closest confidant who orchestrated his rescue from Northwatch Keep","best":"Hearing his brother''s voice in the dungeons and being freed","worst":"Learning Avulstein died to secure his freedom"},"Eorlund Gray-Mane":{"aff":78,"type":"familial","relation":"father","note":"Respected patriarch of the Gray-Mane clan"},"Thalmor":{"aff":-98,"type":"nemesis","relation":"torturers","note":"Endured extensive interrogation at Northwatch Keep without breaking","worst":"Chained and tortured for countless days, nearly broken"},"Battle-Borns":{"aff":-65,"type":"enemy","relation":"rival family","note":"Once-friendly neighbors turned bitter foes over Civil War allegiances"},"Stormcloaks":{"aff":85,"type":"fanatical","relation":"brothers-in-arms","note":"Fought for the cause before capture; plans to rejoin after escape","best":"Fighting alongside fellow Stormcloaks for Skyrim''s freedom"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thorek', '{"Veren Duleri":{"aff":85,"type":"platonic","relation":"brother-in-faith","note":"Close fellow guardian of the Skull of Corruption who shared the fateful decision to release the Miasma","best":"Stood together and agreed to guard the Skull to the death","worst":"Had to release the Miasma knowing few of them remained"},"Erandur":{"aff":-90,"type":"betrayed","relation":"oathbreaker, former brother","note":"Former brother Casimir who fled the temple before the Miasma, abandoning his sworn duty and brethren","worst":"Casimir ran while his brothers stayed to sleep or die"},"Vaermina":{"aff":95,"type":"fanatical","relation":"divine patron","note":"Serves with absolute devotion as priest and guardian of her sacred artifact","best":"Trusted as guardian of the Skull of Corruption","worst":"Failed to prevent the Skull''s destruction, dying with forgiveness on his lips"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thorgar', '{"Former Miners":{"aff":-45,"type":"estranged","relation":"former employees","note":"Resents those who abandoned the mine and mocked his determination to keep it open","worst":"They laughed when I said I wanted to keep the mine open"},"Jarl of Winterhold":{"aff":25,"type":"neutral","relation":"aspiring business partner","note":"Delusionally expects the Jarl will seek his wealth once the mine succeeds","best":"The Jarl will come to me asking for money"},"Local Traders":{"aff":30,"type":"transactional","relation":"business contacts","note":"Essential trading partners for selling ore and obtaining supplies"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thoring', '{"Karita":{"aff":45,"type":"familial","relation":"daughter","note":"Loves her but remains emotionally distant, burying himself in work instead of connecting","best":"Proud that she has her mother''s voice","worst":"Cannot bring himself to talk about her mother with her"},"Late Wife":{"aff":90,"type":"romantic","relation":"late wife","note":"Her death two years ago left him devastated; he avoids processing his grief through obsessive work","best":"Building the Windpeak Inn together into a respected establishment","worst":"Her death, which he still cannot bring himself to discuss"},"Irgnir":{"aff":20,"type":"neutral","relation":"patron","note":"Regular patron with possible romantic interest; he remains completely oblivious"},"Fruki":{"aff":20,"type":"neutral","relation":"patron","note":"Regular patron who may have romantic interest; he remains completely oblivious"},"Erandur":{"aff":45,"type":"professional","relation":"town priest","note":"Respects his efforts to help Dawnstar with the nightmare crisis","best":"Defended him when frightened patrons were demanding answers"},"Frida":{"aff":40,"type":"platonic","relation":"old friend","note":"Shares nostalgic memories of past town events; both widowed","best":"Reminiscing about fighting Hildolf the Skull-Splitter together"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thorygg_sun-killer', '{"Ulfric Stormcloak":{"aff":95,"type":"fanatical","relation":"commander","note":"Serves with absolute loyalty; reveres Ulfric as the truest son of Skyrim and rightful High King","best":"Being appointed to command the Falkreath camp by Ulfric himself"},"Camp Soldiers":{"aff":65,"type":"protective","relation":"commander","note":"Commands nine soldiers including three wounded; stern but genuinely concerned for their welfare"},"Imperial Legion":{"aff":-85,"type":"enemy","relation":"sworn enemy","note":"Despises the Empire as cowards who sold out Skyrim to the Thalmor","worst":"The Empire renouncing honor by laying down before the Thalmor and selling Talos worship"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"existential foe","note":"Objects of deep hatred; vows to rid Skyrim of elves and their Justiciars entirely","worst":"The Thalmor banning Talos worship and enforcing their will through the White-Gold Concordat"},"Torygg":{"aff":-70,"type":"contempt","relation":"traitor king","note":"Views the late High King as a sellout who took Imperial gold and betrayed his people"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('threki_the_innocent', '{"Ulfric Stormcloak":{"aff":-85,"type":"enemy","relation":"political opponent","note":"Imprisoned for calling him a liar who exploits Talos worship to seize the throne","worst":"Jailed after speaking out against his deception of the Nordic people"},"Maven Black-Briar":{"aff":-70,"type":"enemy","relation":"implied persecutor","note":"Likely orchestrated her imprisonment through Riften''s corrupt power structure"},"Thieves Guild":{"aff":-10,"type":"rival","relation":"independent operator","note":"Deliberately works outside their control, targeting the corrupt wealthy they often protect"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('thrynn', '{"Brynjolf":{"aff":75,"type":"professional","relation":"recruiter","note":"Brought Thrynn into the Guild and earned his deep loyalty","best":"Offered him a place in the Guild when he had nowhere else to go"},"Garthek":{"aff":-100,"type":"nemesis","relation":"former bandit chief","note":"Moral conflict over slaughtering innocents ended with Thrynn beheading him","worst":"Ordered the killing of women and children, then ordered the clan to kill Thrynn"},"Mercer Frey":{"aff":-85,"type":"betrayed","relation":"former guild master","note":"Once respected as Guild leader, now despised for murdering Gallus and betraying the Guild","worst":"Discovered he murdered Gallus and betrayed the entire Guild"},"Maven Black-Briar":{"aff":35,"type":"transactional","relation":"employer","note":"Hires Thrynn for muscle work when she needs discretion; pays well"},"Gallus":{"aff":60,"type":"professional","relation":"former guild master","note":"Respected the previous Guild master; enraged by his murder"},"Thieves Guild":{"aff":80,"type":"protective","relation":"family","note":"Considers fellow members his new family and will protect them fiercely"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tilde', '{"Isran":{"aff":80,"type":"professional","relation":"leader","note":"Trusts his leadership and vampire-fighting expertise implicitly","best":"Isran reformed the Dawnguard and gave her purpose after losing her family"},"Dawnguard":{"aff":70,"type":"professional","relation":"fellow members","note":"Close bonds forged through shared duty and combat against vampires"},"Vampires":{"aff":-95,"type":"nemesis","relation":"sworn enemies","note":"Dedicated to their complete destruction after losing family to vampire raids","worst":"Family members killed in vampire raids on settlements"},"Local Settlements":{"aff":55,"type":"protective","relation":"protected communities","note":"Determined to prevent others from suffering the losses she endured"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tilisu_severin', '{"Vendil Severin":{"aff":-60,"type":"betrayed","relation":"fake husband, co-conspirator","note":"A decade of partnership rotted by his affair with Mirri and his dismissive contempt toward her","worst":"He told her to stick to her business when she confronted him about Mirri"},"Mirri Severin":{"aff":-75,"type":"rival","relation":"fake daughter, romantic rival","note":"Forced to pose as her mother while Mirri is actually Vendil''s lover, fueling bitter jealousy","worst":"Sarcastically told Mirri to find someone else to hop into bed with"},"Councilor Morvayn":{"aff":-80,"type":"enemy","relation":"assassination target","note":"The entire purpose of their decade-long cover in Raven Rock is to kill him"},"Raven Rock Townspeople":{"aff":15,"type":"neutral","relation":"cover audience","note":"Maintains cordial but distant interactions to preserve the family facade and avoid suspicion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tilma_the_haggard', '{"The Circle":{"aff":85,"type":"protective","relation":"keeper of secrets","note":"Trusted confidante who knows of their lycanthropy and keeps it without judgment","best":"Entrusted with the Circle''s deepest secret and never wavered in discretion"},"Kodlak Whitemane":{"aff":80,"type":"platonic","relation":"employer and friend","note":"Respected Harbinger she served for many years until his death","best":"Shared decades of quiet camaraderie in Jorrvaskr","worst":"Attended his funeral with genuine grief"},"Skjor":{"aff":65,"type":"platonic","relation":"charge","note":"A rough but kind Companion whose death saddened her deeply","worst":"Received news of his fall to the Silver Hand and quietly prepared his things"},"Vignar Gray-Mane":{"aff":50,"type":"platonic","relation":"old acquaintance","note":"Long-time acquaintance who remembers her from her younger days"},"Eorlund Gray-Mane":{"aff":55,"type":"professional","relation":"fellow servant of the Companions","note":"Mutual respect between two long-serving supporters of the Companions'' traditions"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tolenos_omoren', '{"Crescius Caerellius":{"aff":55,"type":"professional","relation":"fellow miner","note":"Respects him and grateful for the mine''s reopening"},"House Redoran":{"aff":50,"type":"grateful","relation":"benefactor","note":"Grateful for reopening the mine and restoring employment","best":"Thanks to House Redoran getting these mines reopened, I can provide for my family again"},"East Empire Company":{"aff":-25,"type":"suspicious","relation":"former employer","note":"Resents their abandonment of Raven Rock, though lessened since the mine reopened"},"Raven Rock Miners":{"aff":65,"type":"platonic","relation":"colleagues","note":"Strong camaraderie with fellow workers after years of shared hardship"},"Family":{"aff":85,"type":"familial","relation":"wife and children","note":"Dedicated to providing for them through mining work","worst":"Struggled to provide when the mine closed, nearly relocated to Windhelm"},"Player":{"aff":55,"type":"grateful","relation":"mine restorer","note":"Grateful for reopening Raven Rock Mine","best":"Help yourself to as much ore as you like... you''ve earned it"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tolfdir', '{"Mirabelle Ervine":{"aff":65,"type":"professional","relation":"colleague","note":"Respected fellow instructor at the College of Winterhold"},"Savos Aren":{"aff":55,"type":"professional","relation":"arch-mage","note":"Serves under him with loyalty"},"Ancano":{"aff":-25,"type":"suspicious","relation":"Thalmor advisor","note":"Maintains professional distance but clearly wary of his presence"},"J''zargo":{"aff":50,"type":"mentor","relation":"student","note":"Eager Khajiit student whose impatience he tries to temper with caution"},"Onmund":{"aff":50,"type":"mentor","relation":"student","note":"Nord student he guides with patience and care"},"Brelyna Maryon":{"aff":55,"type":"mentor","relation":"student","note":"Dunmer student he affectionately calls ''my dear''"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tonilia', '{"Vekel the Man":{"aff":65,"type":"romantic","relation":"lover","note":"Romantic partner who refuses to marry him, protective of him around others","worst":"Rumored affair with Brynjolf strains their relationship"},"Brynjolf":{"aff":30,"type":"romantic","relation":"rumored lover","note":"Rumored past or ongoing affair, source of tension with Vekel"},"Delvin Mallory":{"aff":45,"type":"professional","relation":"lookout","note":"Serves as his lookout and watches his back during operations"},"Dirge":{"aff":50,"type":"platonic","relation":"friend","note":"Fellow Ragged Flagon resident and trusted companion"},"Thieves Guild":{"aff":40,"type":"professional","relation":"fence","note":"Primary fence and armor supplier but maintains independence as non-member"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torbjorn_shatter-shield', '{"Tova Shatter-Shield":{"aff":85,"type":"romantic","relation":"wife","note":"Shares deep mutual grief over Friga''s murder","best":"Building a life and raising twin daughters together","worst":"Watching Tova suffer without peace after Friga''s death"},"Nilsine Shatter-Shield":{"aff":90,"type":"protective","relation":"daughter","note":"Fiercely protects his surviving twin daughter","worst":"Seeing Nilsine wrecked by her sister''s death"},"Friga Shatter-Shield":{"aff":90,"type":"familial","relation":"deceased daughter","note":"Her murder by the Butcher haunts him daily","best":"Watching her grow alongside her twin sister","worst":"Her brutal murder by the Windhelm Butcher"},"Suvaris Atheron":{"aff":15,"type":"professional","relation":"employee","note":"Dark Elf manager of his shipping operations"},"Argonian Dockworkers":{"aff":-30,"type":"contempt","relation":"laborers","note":"Underpays and mistreats them due to Nord prejudice","worst":"Being confronted about paying Argonians fair wages"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torkild', '{"Wulf Wild-Blood":{"aff":30,"type":"familial","relation":"brother","note":"Torkild carried a letter addressed to Wulf even after his transformation, suggesting some lingering bond despite his estrangement from the Skaal.","best":"Sharing the hunt with his brother in days past","worst":"Abandoning his brother and village to pursue power"},"Skaal Village":{"aff":-15,"type":"estranged","relation":"former community","note":"Torkild never felt the call of the All-Maker and rejected the Skaal''s peaceful ways, leaving to seek dominance and strength.","worst":"Turning his back on Skaal traditions and his people"},"Hircine":{"aff":-60,"type":"betrayed","relation":"cursed by","note":"Torkild''s hunger for unnatural strength led him to Hircine''s curse, which destroyed his humanity and left him a feral werebear.","worst":"The curse that shattered his mind and condemned him to madness"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torkild_the_fearsome', '{"Sinding":{"aff":-85,"type":"enemy","relation":"prey","note":"Active target of his hunt in Bloated Man''s Grotto, driven by hatred of lycanthropes","worst":"A werewolf abomination that must be destroyed"},"Hircine":{"aff":25,"type":"servant","relation":"hunter in the Great Hunt","note":"Participates in Hircine''s Great Hunt as one of the designated hunters"},"Fellow Hunters":{"aff":35,"type":"rival","relation":"competitors in the hunt","note":"Competitive but respectful allies in the pursuit of Sinding"},"Local Jarls":{"aff":20,"type":"transactional","relation":"employers","note":"Occasional contractors for dangerous beast bounties"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tormir', '{"Hrefna":{"aff":90,"type":"protective","relation":"daughter","note":"Fiercely protective single mother determined to raise her with Nord values","best":"Watching her grow into a smart, spirited girl","worst":"Catching her absorbing foreign ideas instead of Nord traditions"},"Sondas Drenim":{"aff":65,"type":"platonic","relation":"fellow miner, trusted friend","note":"Trusted colleague who watches over Hrefna and whose judgment she respects","best":"His reassurance that Derkeethus is a good influence on Hrefna"},"Kjeld":{"aff":-85,"type":"enemy","relation":"foe, possible father of Hrefna","note":"Marked as her foe in game files; likely the snowback who abandoned her and their daughter","worst":"His abandonment left her raising Hrefna alone in a campsite"},"Derkeethus":{"aff":15,"type":"suspicious","relation":"fellow resident","note":"Wary of his Argonian influence on Hrefna but defers to Sondas''s trust in him","worst":"Hrefna repeating things she learned from him instead of Nord ways"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torolf', '{"Haming":{"aff":90,"type":"protective","relation":"son","note":"Raises alone as single father; fiercely protective of him","best":"Calling him ''little cub'' with paternal warmth","worst":"Dying in the dragon attack on Helgen"},"Froki Whetted-Blade":{"aff":50,"type":"familial","relation":"father","note":"Chose lumberjack life over father''s hunting path; Froki lives as a recluse in the Rift"},"Matlara":{"aff":70,"type":"familial","relation":"wife","note":"Listed as his wife; likely deceased or absent given he raises Haming alone"},"Helgen Community":{"aff":45,"type":"professional","relation":"community","note":"Respected lumberjack and essential supplier for the town"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torsten_cruel-sea', '{"Hillevi Cruel-Sea":{"aff":85,"type":"romantic","relation":"wife","note":"Partner in managing family affairs and clan legacy"},"Grimvar Cruel-Sea":{"aff":90,"type":"protective","relation":"son","note":"Fiercely protective of him after Fjotli''s murder"},"Fjotli Cruel-Sea":{"aff":95,"type":"familial","relation":"murdered daughter","note":"Her death devastated him and drove him to pursue vengeance","worst":"Finding her body in a pool of her own blood"},"Tulvur":{"aff":35,"type":"professional","relation":"farm worker","note":"Relies on him to manage Hollyfrost Farm but dismissive of his concerns","best":"Providing wood and timber for farm riggings","worst":"Criticizing the filthy farmhouse conditions"},"Ulfric Stormcloak":{"aff":65,"type":"admirer","relation":"respected leader","note":"Advises him on naval matters for the Stormcloak cause"},"Idesa Sadri":{"aff":45,"type":"professional","relation":"son''s caretaker","note":"Trusts a Dark Elf with Grimvar''s care, showing relatively progressive views"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torture_victim', '{"Dark Brotherhood":{"aff":-95,"type":"fearful","relation":"captors","note":"Held captive and tortured for information about hidden treasures across Skyrim","worst":"The endless sessions of pain and interrogation that broke their spirit"},"Nazir":{"aff":-90,"type":"fearful","relation":"torturer","note":"Primary interrogator who extracts information through pain and duress","worst":"Each session under his blade extracting another secret they never meant to tell"},"Fellow Torture Victims":{"aff":20,"type":"platonic","relation":"fellow prisoners","note":"Shared suffering creates a silent bond of mutual understanding in the darkness","best":"A fleeting moment of eye contact that said someone else understood the pain"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torturer', '{"Imperial Legion":{"aff":20,"type":"professional","relation":"employer","note":"Serves with autonomy but disdains chain of command and avoids oversight"},"Hadvar":{"aff":-35,"type":"contempt","relation":"junior officer","note":"Mutual disrespect; refuses to acknowledge Hadvar''s authority","worst":"Hadvar dismisses him as no real Imperial Legionnaire"},"Torturer''s Assistant":{"aff":5,"type":"dismissive","relation":"subordinate","note":"Views assistant as expendable; assistant abandons him without hesitation","worst":"Assistant leaves him behind during dragon attack"},"Stormcloak Prisoners":{"aff":-85,"type":"enemy","relation":"victims","note":"Views prisoners as objects for sadistic entertainment rather than people"},"General Tullius":{"aff":10,"type":"dismissive","relation":"superior officer","note":"Largely ignores his authority and operates autonomously"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torturer''s_assistant', '{"The Torturer":{"aff":45,"type":"professional","relation":"superior","note":"Serves with pragmatic loyalty, ultimately returning to check on him","best":"Goes back to see to the old man during the dragon attack","worst":"Initially willing to abandon him, saying Forget the old man"},"Hadvar":{"aff":20,"type":"neutral","relation":"temporary ally","note":"Briefly traveled together during the Helgen escape"},"Imperial Legion":{"aff":40,"type":"professional","relation":"employer","note":"Loyal servant of the Imperial military structure"},"Stormcloaks":{"aff":-50,"type":"enemy","relation":"adversary","note":"Faces in combat without hesitation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('torvar', '{"Kodlak Whitemane":{"aff":40,"type":"mentor","relation":"Harbinger","note":"Respects Kodlak but feels intimidated by his judgment and corrections","best":"Kodlak encouraged him to focus on honor rather than rank","worst":"Accidentally called Kodlak ''Master'' and was firmly corrected"},"Farkas":{"aff":55,"type":"mentor","relation":"training mentor","note":"Farkas shows patience with Torvar''s impatience and restlessness","best":"Farkas assured him he would do all right someday","worst":"Farkas repeatedly holds him back from real fighting to train"},"Athis":{"aff":50,"type":"platonic","relation":"sparring partner","note":"Drinking companion and sparring partner with differing weapon preferences","best":"Dreamed together about joining the Circle and changing how things are run","worst":"Athis dismissed his ambitions about how the Circle works"},"Skjor":{"aff":15,"type":"professional","relation":"senior companion","note":"Resents having to follow Skjor''s orders despite Kodlak''s endorsement","worst":"Forced to wait for Skjor''s permission before fighting"},"The Circle":{"aff":10,"type":"jealous","relation":"aspiring member","note":"Desperately wants to join the Circle but resents their authority over lower members","best":"Kodlak told him glory would come if he focused on honor","worst":"Feels they lord it over him and other lower-ranking members"},"Player":{"aff":20,"type":"jealous","relation":"fellow Companion","note":"Initially friendly but grows resentful as the Player advances far faster than him","best":"Eventually accepts the Player as Harbinger and agrees to follow","worst":"Attitude sours as the Player rises through ranks while he stagnates"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tova_shatter-shield', '{"Torbjorn Shatter-Shield":{"aff":65,"type":"familial","relation":"husband","note":"Shares her grief but neither can ease the other''s pain","best":"Raising their twin daughters together in prosperous times","worst":"Both shattered by Friga''s murder and unable to comfort each other"},"Nilsine Shatter-Shield":{"aff":90,"type":"protective","relation":"surviving daughter","note":"Her sole reason to continue living; Nilsine''s death drives her to suicide","best":"Still having one daughter to love and protect","worst":"Constant terror that Nilsine could meet the same fate as Friga"},"Friga Shatter-Shield":{"aff":85,"type":"familial","relation":"murdered daughter","note":"Her death defines Tova''s daily existence and grief","worst":"Losing Friga to the Butcher of Windhelm"},"The Butcher":{"aff":-100,"type":"nemesis","relation":"daughter''s killer","note":"Wants justice more than anything; surrendered Hjerim key to aid investigation","worst":"Murdered Friga and destroyed her family''s happiness"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('traveler', '{"Dawnguard":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Actively hunts Dawnguard members across Skyrim with singular focus","worst":"Each Dawnguard member systematically eliminated"},"Lord Harkon":{"aff":35,"type":"mentor","relation":"possible former mentor","note":"Shares the rare Summon Gargoyle spell otherwise unique to Harkon, suggesting direct training","best":"Mastering the gargoyle summoning technique reserved for vampire lords"},"VampireFaction":{"aff":70,"type":"professional","relation":"covert operative","note":"Serves vampire interests by methodically eliminating threats to their kind"},"Vigilants of Stendarr":{"aff":-55,"type":"enemy","relation":"avoided target","note":"Secondary enemy he avoids engaging unless necessary"}}')
