INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('traveling_bard', '{"Dawnguard":{"aff":75,"type":"professional","relation":"operative","note":"Former training partners and current intelligence network he coordinates with through coded messages and dead drops"},"Vampire Covens":{"aff":-95,"type":"nemesis","relation":"hunted targets","note":"Primary targets of his investigation and elimination efforts after losing family to vampire attacks","worst":"Watched his family fall to vampire attacks in his youth"},"Local Innkeepers":{"aff":35,"type":"transactional","relation":"informants","note":"Contacts who provide information about suspicious travelers passing through their establishments"},"Fellow Bards":{"aff":15,"type":"suspicious","relation":"false colleagues","note":"Kept at arm''s length to avoid exposure of his limited musical knowledge and true identity"}}')
