INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('traveling_merchant', '{"Dawnguard":{"aff":85,"type":"professional","relation":"employer and brotherhood","note":"Deep cover operative selected for his talent in maintaining a convincing merchant persona","best":"Selected for elite deep cover operations after extensive training"},"Vampires":{"aff":-95,"type":"nemesis","relation":"sworn enemies and surveillance targets","note":"Harbors deep-seated hatred but maintains strict emotional control to protect his cover","worst":"Lost his family to a vampire attack in Cyrodiil"},"Merchant''s Guild":{"aff":25,"type":"transactional","relation":"cover organization","note":"Maintains legitimate connections solely to support his disguise and movement between settlements"},"Family":{"aff":90,"type":"familial","relation":"murdered loved ones","note":"Their deaths drive his mission; the reason he joined the Dawnguard and hunts vampires","worst":"Killed by vampires in Cyrodiil"}}')
