INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('traveling_pilgrim', '{"Dawnguard":{"aff":80,"type":"professional","relation":"faction","note":"Active field operative serving as reconnaissance specialist"},"Isran":{"aff":60,"type":"professional","relation":"commander","note":"Reports directly to the Dawnguard leader"},"Gunmar":{"aff":55,"type":"professional","relation":"handler","note":"Receives radiant hunting assignments from him"},"Vigilants of Stendarr":{"aff":45,"type":"estranged","relation":"former order","note":"Former member who left after witnessing comrades fall to vampires","worst":"Watched fellow Vigilants die in vampire attacks"},"Vampires":{"aff":-90,"type":"enemy","relation":"prey","note":"Hunted and eliminated as sacred duty","worst":"Witnessed comrades slaughtered by vampire covens"}}')
