INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tsavani', '{"Malborn":{"aff":-45,"type":"suspicious","relation":"blackmailer","note":"He knows of her moon sugar addiction and leverages it to ensure her silence","worst":"Threatened to expose her addiction to the Ambassador unless she cooperated"},"Elenwen":{"aff":-10,"type":"fearful","relation":"employer","note":"Respects the Ambassador''s authority but lives in dread of her discovering the addiction"},"Kitchen Staff":{"aff":15,"type":"professional","relation":"subordinates","note":"Maintains strict territorial authority over her kitchen domain"},"Local Drug Suppliers":{"aff":5,"type":"transactional","relation":"suppliers","note":"Secret contacts who provide her moon sugar, kept at careful distance"}}')
