INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tsrasuna', '{"Sinding":{"aff":-75,"type":"enemy","relation":"hunt target","note":"Primary prey in Hircine''s Great Hunt at Bloated Man''s Grotto"},"Hircine":{"aff":65,"type":"servant","relation":"Daedric Prince","note":"Serves in the Great Hunt to prove herself worthy in his eyes"},"Fellow Hunters":{"aff":25,"type":"professional","relation":"hunting party","note":"Reliable allies in the pursuit, though she keeps emotional distance"},"Former Caravan Members":{"aff":80,"type":"familial","relation":"lost family","worst":"Bandit raid destroyed her caravan and claimed everyone she loved"}}')
