INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tsun', '{"Shor":{"aff":95,"type":"servant","relation":"Shield-thane","note":"Faithfully serves as Shor''s guardian and gatekeeper, carrying out his decree that none pass without proving their worth."},"Alduin":{"aff":-95,"type":"nemesis","relation":"ancient enemy","note":"Fought and died battling Alduin in the Dragon War; continues to oppose his soul-snare that traps honored dead from reaching Shor''s hall.","worst":"Slain by Alduin during the Dragon War"},"Ysgramor":{"aff":70,"type":"admirer","relation":"honored hero","note":"Holds Ysgramor''s lineage in special regard and eagerly tests the blade of his heirs."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tulvur', '{"Torsten Cruel-Sea":{"aff":-15,"type":"professional","relation":"employer","note":"Strained working relationship marked by Torsten''s constant criticism and unrealistic expectations","worst":"Compared the farmhouse to ship quarters and demanded sailor-level cleanliness"},"Hillevi Cruel-Sea":{"aff":40,"type":"professional","relation":"employer","note":"Sympathetic employer who ensures he gets paid and genuinely asks after his dogs","best":"Reassured him about Torsten''s harangues and confirmed she handles his pay"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tuthul', '{"Perth":{"aff":20,"type":"professional","relation":"employer","note":"Constantly complains about draugr danger but continues working under Perth''s direction","best":"Perth provides steady employment during wartime","worst":"Perth dismisses his fears and calls him a coward"},"Guards":{"aff":-30,"type":"contempt","relation":"mine guards","note":"Views them as useless for standing around instead of eliminating the draugr threat","worst":"Guards just stand around waiting for a full regiment instead of acting"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tynan', '{"Nepos the Nose":{"aff":85,"type":"servant","relation":"master","note":"Devoted bodyguard and henchman trusted with Forsworn secrets","best":"Recruited by Nepos who recognized his exceptional loyalty and discretion","worst":"Will die fighting to protect Nepos when the conspiracy is exposed"},"Uaile":{"aff":50,"type":"professional","relation":"fellow conspirator","note":"Fellow Forsworn operative serving in Nepos''s household"},"Morven":{"aff":45,"type":"professional","relation":"colleague","note":"Fellow Forsworn sympathizer in Nepos''s service"},"Madanach":{"aff":70,"type":"fanatical","relation":"cause leader","note":"Serves the King in Rags by proxy through Nepos","best":"Pledged loyalty to the Forsworn cause and Madanach''s vision for the Reach"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('tythis_ulen', '{"Madesi":{"aff":45,"type":"platonic","relation":"friend","note":"Patiently calms Tythis''s paranoid fears and exaggerations","best":"Madesi reassured me the Imperials weren''t invading and everything would be fine"},"Marise":{"aff":35,"type":"platonic","relation":"confidant","note":"Shares local security concerns and warnings about the Thieves Guild"},"Brand-Shei":{"aff":25,"type":"transactional","relation":"boot supplier","note":"Supplies Tythis''s obsessive boot purchases; puzzled by the quantity"},"Bolli":{"aff":25,"type":"professional","relation":"employer","note":"Employer at the Riften Fishery where Tythis chops and carries wood"},"Haelga":{"aff":15,"type":"transactional","relation":"landlord","note":"Landlord at the Bunkhouse who flirts; Tythis remains oblivious"},"Svana":{"aff":-25,"type":"crush","relation":"rejected suitor","note":"Made crude advances that Svana violently rejected","worst":"Svana threatened to cut off something I can''t live without"},"Niluva":{"aff":-10,"type":"transactional","relation":"debtor","note":"Owes Tythis money; he criticizes her skooma addiction"},"Grelka":{"aff":15,"type":"transactional","relation":"boot repairer","note":"Repairs Tythis''s unusual horker skin boots despite confusion"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('uaile', '{"Nepos the Nose":{"aff":45,"type":"indebted","relation":"superior","note":"Negotiated with Nepos to reduce her father''s sentence from execution to imprisonment; serves as his maid and Forsworn guardian","best":"Nepos reduced her father''s sentence at her request"},"Uraccen":{"aff":85,"type":"familial","relation":"father","note":"Imprisoned in Cidhna Mine for Forsworn activities; Uaile''s devotion to him drives her service to the cause","best":"Convincing Nepos to spare her father''s life"},"Tynan":{"aff":35,"type":"professional","relation":"fellow agent","note":"Fellow Forsworn agent stationed in Nepos''s household"},"Morven":{"aff":35,"type":"professional","relation":"fellow agent","note":"Fellow Forsworn agent stationed in Nepos''s household"},"Markarth Guard":{"aff":-55,"type":"suspicious","relation":"oppressors","note":"Nord authorities she must carefully avoid while maintaining her cover identity"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ugor', '{"Yamarz":{"aff":40,"type":"professional","relation":"former chief","note":"She faithfully obeyed his charge to keep outsiders away, but his failure to protect the tribe from Malacath''s curse tarnished her loyalty."},"Atub":{"aff":55,"type":"protective","relation":"wise-woman","note":"Initially resisted Atub''s call to accept outsider help, but deferred to her judgment and wisdom for the tribe''s sake.","worst":"Argued bitterly at the gate over whether to let outsiders into Largashbur."},"Gularzob":{"aff":60,"type":"professional","relation":"new chief","note":"Pledges to serve him after the curse is lifted, believing he will one day be great despite having much to learn."},"Malacath":{"aff":70,"type":"fanatical","relation":"patron deity","note":"Devoted to proving herself worthy of his favor and determined not to fail him again.","worst":"The curse he placed on the tribe for their perceived failings."},"Giants":{"aff":-80,"type":"enemy","relation":"frequent adversaries","note":"Constant threat to Largashbur that she regularly fights off at the gates."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ulag', '{"Ysolda":{"aff":15,"type":"transactional","relation":"business partner","note":"Purely transactional arrangement for Sleeping Tree Sap trade; she grieved little at his death","worst":"Died on a job for her and she barely cared, immediately offering his cut to someone else"},"Giants of Sleeping Tree Camp":{"aff":-80,"type":"enemy","relation":"killers","note":"Hostile giants whose territory he trespassed in to harvest sap; they killed him","worst":"Slain by giants while harvesting sap from their territory"},"Orc Stronghold":{"aff":-40,"type":"estranged","relation":"former community","note":"Rejected the traditional warrior path of Malacath and left his stronghold for a dishonorable life","worst":"Abandoned his people and their ways for criminal pursuits"}}')
