SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ulfberth_war-bear', '{"Adrianne Avenicci":{"aff":92,"type":"romantic","relation":"wife and business partner","note":"Deeply respects her smithing skill and proudly sells her craftsmanship","best":"Building Warmaiden''s into Whiterun''s premier armory together","worst":"Struggling with the forge and relying on Khajiit caravans after her death"},"Proventus Avenicci":{"aff":55,"type":"familial","relation":"father-in-law","note":"Cordial family relationship through Adrianne"},"Balgruuf the Greater":{"aff":45,"type":"professional","relation":"Jarl","note":"Considers him honorable and fair to his kin","best":"Never done wrong by me or my kin"}}')
