INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ulfr_the_blind', '{"Hajvarr Iron-Hand":{"aff":75,"type":"familial","relation":"nephew","note":"Took Ulfr in when no one else would, giving him purpose and teaching him to adapt to his blindness","best":"Given sanctuary and a meaningful role despite his disability"},"Rodulf":{"aff":45,"type":"platonic","relation":"fellow bandit","note":"Regularly checks on Ulfr; one of the few whose voice he trusts enough to mistake others for"},"White River Watch Bandits":{"aff":10,"type":"professional","relation":"colleagues","note":"Some respect his role while others mock his blindness and conspire against him","worst":"Fellow bandits called him a rheumy-eyed fool and plotted to remove him"}}')
