INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ulfric_stormcloak', '{"Galmar Stone-Fist":{"aff":85,"type":"platonic","relation":"trusted general and friend","note":"His most loyal companion and military commander who shares his vision for Skyrim"},"General Tullius":{"aff":-85,"type":"nemesis","relation":"military adversary","note":"Commands the Imperial forces opposing the Stormcloak Rebellion"},"High King Torygg":{"aff":-55,"type":"rival","relation":"slain rival","note":"Killed him in traditional combat to ignite the rebellion","worst":"Shouting him down with the Thu''um before killing him with his sword"},"Greybeards":{"aff":50,"type":"mentor","relation":"former teachers","note":"Trained him in the Way of the Voice before he left to fight in the Great War"},"Thalmor":{"aff":-95,"type":"enemy","relation":"torturers and oppressors","note":"Captured and tortured him during the Great War; they secretly view him as an unwitting asset","worst":"Being tortured by Thalmor interrogators"}}')
