INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ulves_romoran', '{"Neloth":{"aff":15,"type":"professional","relation":"employer","note":"Serves him with dutiful respect but constant exasperation at his demands","worst":"Threatened to make Ulves part of one of his experiments when a meal was late"},"Varona Nelas":{"aff":50,"type":"platonic","relation":"colleague","note":"Complicated working relationship but genuine care beneath the bickering","best":"Volunteered to prepare her grave after her death","worst":"Her murder on the road to Raven Rock"},"Ildari Sarothril":{"aff":35,"type":"crush","relation":"unrequited love interest","note":"Tried to court her but she only cared about magic and power","best":"Remembering her beauty","worst":"Her rejection and subsequent death in Neloth''s experiment"}}')
