INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('umurn', '{"Gharol":{"aff":65,"type":"familial","relation":"mother and mentor","note":"She pushes him hard at the forge, demanding focus and discipline","best":"Learning the art of blacksmithing at her side","worst":"Her harsh rebukes when he complained about stubborn metal"},"Chief Burguk":{"aff":25,"type":"familial","relation":"father and chief","note":"Distant relationship due to being born to a lesser-ranked wife","worst":"Carrying the key to a longhouse he is not permitted to sleep in"},"Nagrub":{"aff":15,"type":"rival","relation":"brother and rival for chiefdom","note":"Must one day fight him for leadership of the stronghold per Orcish tradition","worst":"The looming necessity of mortal combat between brothers"}}')
