INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('una', '{"Erdi":{"aff":-30,"type":"contempt","relation":"colleague","note":"Views Erdi as lazy and wishes to avoid her","worst":"Erdi''s poor work habits and constant presence"},"Falk Firebeard":{"aff":25,"type":"professional","relation":"superior","note":"Palace steward who oversees her duties and restricts access to the Pelagius Wing"},"Lisette":{"aff":5,"type":"neutral","relation":"acquaintance","note":"Occasionally converses but finds bardic pursuits frivolous","best":"Enjoyed talking more than getting back to work"}}')
