INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('unemployed_laborer', '{"Rorik":{"aff":-35,"type":"estranged","relation":"former employer","note":"Strained relationship after losing his livelihood during the war''s economic downturn","worst":"Lost employment and could not find new work in Rorikstead"},"Mralki":{"aff":15,"type":"indebted","relation":"innkeeper","note":"Tolerates his mounting unpaid tabs at the Frostfruit Inn","best":"Allowed him to stay despite owing considerable gold"},"Jouane Manette":{"aff":30,"type":"grateful","relation":"charitable healer","note":"Provides occasional free care despite his inability to pay"},"Erik the Slayer":{"aff":20,"type":"platonic","relation":"kind acquaintance","note":"Young warrior who shows him occasional kindness during hard times"},"Dark Brotherhood":{"aff":10,"type":"transactional","relation":"contract client","note":"Performed the Black Sacrament seeking revenge against those responsible for his ruin"}}')
ON CONFLICT (npc_name) DO UPDATE
