INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ungrien', '{"Maven Black-Briar":{"aff":-75,"type":"fearful","relation":"employer","note":"Forced to deliver rehearsed praise under threat of death; believes previous tasting counter workers were killed","worst":"Realizing the last three people in his position are at the bottom of Lake Honrich"},"Indaryn":{"aff":-55,"type":"professional","relation":"supervisor","note":"Constantly berated and threatened with dismissal over mistakes","worst":"Being warned he''ll end up in Beggar''s Row if he spoils another keg"},"Tythis Ulen":{"aff":30,"type":"platonic","relation":"confidant","note":"Confides in him at the Bunkhouse about Indaryn''s mistreatment","best":"Having someone who will listen to his frustrations"},"Haelga":{"aff":10,"type":"transactional","relation":"landlord","note":"Resides at her Bunkhouse; relationship limited to lodging arrangement"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('unmid_snow-shod', '{"Jarl Laila Law-Giver":{"aff":92,"type":"protective","relation":"sworn liege","note":"Unwaveringly loyal housecarl who would die before allowing her to fall","best":"Swearing his oath of service as her housecarl","worst":"Forced to surrender on her plea rather than fight to the death"},"Anuriel":{"aff":78,"type":"romantic","relation":"lover","note":"Secret romance with the Jarl''s steward; duty sometimes strains their bond","best":"Private meetings in her chambers","worst":"Clashing over her declarations that the city is safe for the Jarl"},"Vulwulf Snow-Shod":{"aff":35,"type":"estranged","relation":"father","note":"No acknowledged relationship despite shared Stormcloak sympathies"},"Nura Snow-Shod":{"aff":40,"type":"familial","relation":"mother","note":"Distant; he resides at Mistveil Keep while she serves at the temple"},"Asgeir Snow-Shod":{"aff":30,"type":"familial","relation":"brother","note":"No acknowledged interaction; family never names him among their children"},"Thieves Guild":{"aff":-88,"type":"enemy","relation":"sworn enemy","note":"Would burn them out of the Ratway if not for the war demanding resources","worst":"Knowing they operate freely beneath Riften"},"Ulfric Stormcloak":{"aff":80,"type":"admirer","relation":"hero","note":"Views him as the only worthy Nord leader and Skyrim''s rightful king","best":"Ulfric taking the Empire to task for their crimes"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('uraccen', '{"Uaile":{"aff":85,"type":"familial","relation":"daughter","note":"Left her behind when imprisoned; loses track of time wondering about her age","best":"Memories of her before his capture","worst":"Being torn away from her when taken to Cidhna Mine"},"Madanach":{"aff":45,"type":"professional","relation":"prison leader","note":"Respects the King in Rags but access is blocked by Borkul"},"Borkul the Beast":{"aff":-25,"type":"fearful","relation":"Madanach''s enforcer","note":"Cautious of the brutal Orc; warns others about him"},"Forsworn":{"aff":80,"type":"fanatical","relation":"faction","note":"Undiminished commitment; dreams of painting Markarth in Nord blood","best":"Embracing the old ways and fighting for Reach freedom"},"Nords":{"aff":-80,"type":"enemy","relation":"oppressors","note":"Deep resentment over blame for nobleman''s murder and Nord rule","worst":"Being falsely blamed for his Nord master''s murder and forced to flee"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('urag_gro-shub', '{"Savos Aren":{"aff":65,"type":"professional","relation":"superior and Arch-Mage","note":"Respected leader who trusts Urag completely with The Arcanaeum''s operation"},"Tolfdir":{"aff":55,"type":"platonic","relation":"colleague","note":"Fellow scholar who shares his appreciation for preservation of knowledge"},"Enthir":{"aff":30,"type":"transactional","relation":"business contact","note":"Occasional dealings for acquiring rare books through unofficial channels"}}')
