INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('urog', '{"Mauhulakh":{"aff":-55,"type":"contempt","relation":"father","note":"Views him as weak and undeserving chief; suspects involvement in mother''s death","worst":"Accused him of doing nothing while wives get killed and she and Yatul provide for the stronghold"},"Yatul":{"aff":75,"type":"mentor","relation":"great-aunt and hunting teacher","note":"Primary teacher and respected elder who shaped her skills and independence","best":"Learning to track snow cats and hearing tales of Yatul''s hunts"},"Dushnamub":{"aff":-10,"type":"dismissive","relation":"brother","note":"Dismisses his attempts to explain family dynamics as crazy fantasies"}}')
ON CONFLICT (npc_name) DO UPDATE
