INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('urzoga_gra-shugurz', '{"Mulush gro-Shugurz":{"aff":65,"type":"familial","relation":"brother","note":"Both left Shugurz clan to serve the Silver-Bloods in Markarth"},"Silver-Blood Family":{"aff":70,"type":"professional","relation":"employer","note":"Earned overseer position through years of proven loyal service"},"Madanach":{"aff":-85,"type":"enemy","relation":"prison kingpin","note":"Seeks to catch him orchestrating escape plans","worst":"His influence undermines her control over the mine"},"Nepos the Nose":{"aff":-25,"type":"contempt","relation":"mine administrator","note":"Dismisses her warnings about Madanach''s danger"}}')
