INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('usha', '{"Unknown Lover":{"aff":65,"type":"romantic","relation":"lover","note":"Author of a letter found beside his body, suggesting a meaningful emotional bond despite his isolation","best":"receiving a letter declaring their affection","worst":"dying alone without seeing them again"},"East Empire Company":{"aff":30,"type":"professional","relation":"contractor","note":"Presence of their strongbox suggests official mining ties or contracts"},"Skooma Dealers":{"aff":-20,"type":"transactional","relation":"suppliers","note":"Fed his addiction while he slowly withered in isolation","worst":"every bottle drawing him deeper into dependency"}}')
ON CONFLICT (npc_name) DO UPDATE
