INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('uthgerd_the_unbroken', '{"The Companions":{"aff":-30,"type":"estranged","relation":"rejected initiate","note":"Rejected after accidentally killing a young initiate during her trial; still craves their respect despite calling them cowards","worst":"Lost control and killed the young whelp they set against her"},"Mikael":{"aff":-20,"type":"contempt","relation":"irritant","note":"Barely tolerates the bard who plays at the Bannered Mare"},"Hulda":{"aff":15,"type":"transactional","relation":"innkeeper","note":"Regular patron of the Bannered Mare"}}')
