INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vagrant', '{"Fellow Vagrants":{"aff":-25,"type":"rival","relation":"territorial neighbors","note":"Uneasy coexistence with other Ratway dwellers, each defending their own claimed space","worst":"Constant disputes over territory boundaries and scavenging rights"},"Riften Guards":{"aff":-60,"type":"fearful","relation":"threat","note":"Viewed as dangerous authorities who periodically attempt to clear the Ratway","worst":"Guards raiding the vaults and driving out dwellers from their shelters"},"Thieves Guild":{"aff":-10,"type":"suspicious","relation":"wary neighbors","note":"Tolerated presence in the Ratway but kept at a careful distance","best":"Guild largely ignores the vagrants as long as they stay out of Guild business"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vahlok_the_jailor', '{"Miraak":{"aff":-95,"type":"nemesis","relation":"sworn enemy and prisoner","note":"Defeated Miraak in a days-long battle that separated Solstheim from Skyrim and was tasked with ensuring he never escapes","worst":"Miraak''s betrayal of the Dragon Cult and all it stood for"},"Dragons":{"aff":85,"type":"servant","relation":"trusted enforcer","note":"Served the dragons with absolute loyalty and earned their complete trust"},"Dragon Cult":{"aff":80,"type":"fanatical","relation":"devoted champion","note":"Rose through the ranks through steadfast devotion and became an exemplar of Cult loyalty"},"People of Solstheim":{"aff":40,"type":"protective","relation":"ruler","note":"Governed Solstheim and maintained order among its inhabitants as their Dragon Priest"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vald', '{"Maven Black-Briar":{"aff":-65,"type":"indebted","relation":"creditor","note":"Trapped in massive debt after losing the Quill of Gemination, forced into servitude","worst":"Forced into indentured servitude after crashing her cargo into Lake Honrich"},"Mercer Frey":{"aff":-55,"type":"servant","relation":"reluctant guard","note":"Forced to guard Riftweald Manor under coercion, something held over his head","worst":"Trapped as Mercer''s watchdog with no way out"},"Vex":{"aff":-45,"type":"ex","relation":"former lover","note":"Estranged former lover who now despises him","worst":"She calls him ''that pig'' and wouldn''t care if he died"},"Brynjolf":{"aff":-25,"type":"professional","relation":"guild member","note":"Dismissed by Brynjolf as nothing more than Mercer''s trained watchdog"},"Thieves Guild":{"aff":-20,"type":"estranged","relation":"former associates","note":"Former associates who generally look down on him"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('valdar', '{"Hevnoraak":{"aff":-100,"type":"nemesis","relation":"sworn enemy","note":"Dedicated his existence to preventing Hevnoraak''s resurrection and containing his power","worst":"Witnessed Hevnoraak enthrall and twist good men into eternal servitude"},"Last Dragonborn":{"aff":75,"type":"grateful","relation":"ally","note":"Seeks aid from living champions to complete his fading mission","best":"Thanks the hero and finally finds rest after Hevnoraak''s defeat"},"Ancient Nord Warriors":{"aff":-35,"type":"pitying","relation":"fallen brothers-in-arms","note":"Once fought alongside them; now they serve Hevnoraak as twisted draugr"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('valdimar', '{"Jarl Idgrod Ravencrone":{"aff":72,"type":"patron","relation":"liege","note":"Recognized his unique abilities and elevated him from guard captain to housecarl","best":"Appointed housecarl despite breaking from Nordic warrior tradition"},"Falion":{"aff":68,"type":"mentor","relation":"former mentor","note":"Studied magic under Falion''s guidance in Morthal","best":"Taught him to embrace both spell and steel"},"Aslfur":{"aff":40,"type":"professional","relation":"colleague","note":"Professional relationship with the Jarl''s husband and steward"},"Benor":{"aff":48,"type":"rival","relation":"sparring rival","note":"Friendly rival in martial combat training"},"Player":{"aff":70,"type":"protective","relation":"housecarl","note":"Sworn protector upon being named Thane of Hjaalmarch"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('valdr', '{"Niels":{"aff":75,"type":"platonic","relation":"hunting companion","note":"Trusted friend who fell to spriggans before the group could react","worst":"Niels went down before they even knew to run"},"Ari":{"aff":80,"type":"platonic","relation":"hunting companion","note":"Close friend who gave Valdr a lucky dagger when they started hunting together","best":"Ari gave him the lucky dagger when they first started hunting together","worst":"Ari died just inside the cavern"},"Valga Vinicia":{"aff":25,"type":"transactional","relation":"innkeeper","note":"Innkeeper at Dead Man''s Drink where Valdr now resides"},"Player":{"aff":85,"type":"grateful","relation":"savior","note":"Healed Valdr''s wounds and helped avenge his fallen companions","best":"Stranger healed him and helped bring justice for Niels and Ari"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vale_deer', '{"Snow Elves":{"aff":45,"type":"awed","relation":"ancient magical source","note":"Transformed over centuries by Snow Elf magic permeating the Forgotten Vale"},"Spriggans":{"aff":55,"type":"protective","relation":"natural guardians","note":"Spriggans protect and guide the herds through the Vale"},"Frost Giants":{"aff":-55,"type":"fearful","relation":"predators","note":"Occasional hunters of Vale Deer for food"},"Falmer":{"aff":-65,"type":"fearful","relation":"hostile predators","note":"Falmer view Vale Deer as prey in the Forgotten Vale"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vale_sabre_cat', '{"Frost Giants":{"aff":-45,"type":"rival","relation":"territorial competitor","note":"Competes with Frost Giants for territory within the Forgotten Vale","worst":"Lost prime hunting ground to Frost Giant incursion"},"Dragons":{"aff":-25,"type":"rival","relation":"territorial rival","note":"Occasional territorial disputes in the Vale''s open areas","worst":"Driven from open ground by dragon presence"},"Vale Deer":{"aff":10,"type":"dismissive","relation":"primary prey","note":"Primary food source, hunted without consideration","best":"Successful hunt provided days of sustenance"},"Common Sabre Cats":{"aff":5,"type":"neutral","relation":"distant evolutionary cousins","note":"Evolutionarily distinct subspecies with no meaningful interaction"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('valerica', '{"Serana":{"aff":70,"type":"protective","relation":"daughter","note":"Deep love strained by centuries of isolation and questionable choices made to protect her","best":"Reuniting with Serana in the Soul Cairn","worst":"Heated argument where Serana confronted her about hiding her away"},"Lord Harkon":{"aff":-90,"type":"nemesis","relation":"estranged husband","note":"Fled with the Elder Scrolls and sealed herself in the Soul Cairn to prevent him from sacrificing Serana","worst":"Discovering his plan to use their daughter''s blood for the Tyranny of the Sun"},"Ideal Masters":{"aff":-60,"type":"enemy","relation":"captors","note":"Imprisoned her within the Soul Cairn"},"Vampire Court of Castle Volkihar":{"aff":-40,"type":"estranged","relation":"former peers","note":"Now hostile toward her for betraying Harkon and fleeing with the Elder Scrolls"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('valga_vinicia', '{"Narri":{"aff":65,"type":"professional","relation":"employee and confidante","note":"Valued employee whom she wishes she could pay more alongside Tekla"},"Tekla":{"aff":55,"type":"protective","relation":"friend","note":"Shows genuine concern about how Dengeir treats her","worst":"Watching Tekla endure poor treatment from Dengeir"},"Solaf":{"aff":35,"type":"professional","relation":"regular patron","note":"Straightforward patron relationship with easy rapport"},"Zaria":{"aff":45,"type":"platonic","relation":"fellow merchant","note":"Bonds over shared pessimism about the war''s toll","worst":"Discussing how the war might leave no one left to drink"},"Dengeir":{"aff":-25,"type":"suspicious","relation":"former Jarl","note":"Distrusts how he treats Tekla as his servant"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('valie', '{"Sulla Trebatius":{"aff":25,"type":"transactional","relation":"employer","note":"Hired her specifically as a mage unaffiliated with the College of Winterhold for his Alftand expedition"},"J''darr":{"aff":-40,"type":"suspicious","relation":"fellow expedition member","note":"Expedition members suspected he caused Valie''s disappearance","worst":"Suspected of causing her disappearance in the ruins"},"J''zhar":{"aff":15,"type":"neutral","relation":"fellow expedition member","note":"Believed J''darr was not responsible for Valie''s disappearance"},"College of Winterhold":{"aff":-15,"type":"dismissive","relation":"avoided institution","note":"Deliberately maintained distance from the institution, preferring independence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('valindor', '{"Wujeeta":{"aff":45,"type":"protective","relation":"concerned friend","note":"Worries about her skooma addiction and urges her to quit for her health","best":"Expressing genuine care for her well-being","worst":"Hearing her say the skooma won''t let her go and she wishes to die peacefully"},"Svana Far-Shield":{"aff":35,"type":"platonic","relation":"friendly acquaintance","note":"Shares warm conversation at Haelga''s Bunkhouse; she worries about his workload","best":"Finding her concern for his wellbeing flattering"},"Master Armorer of Silvenar":{"aff":65,"type":"mentor","relation":"late mentor","note":"Trained him in the armorer craft; urged him on his deathbed to inherit the business","best":"Being guided by one of Silvenar''s master armorers","worst":"Declining his dying wish to take over the business and leaving Valenwood instead"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vals_veran', '{"Golldir":{"aff":-85,"type":"enemy","relation":"opponent","note":"Nord warrior seeking to stop his necromantic defilement of Hillgrund''s Tomb","worst":"Confronted him in the tomb and vowed to return his ancestors to Sovngarde"},"Aunt Agna":{"aff":-70,"type":"enemy","relation":"opponent","note":"Elderly Nord who went alone to stop him from raising Hillgrund''s ancestors","worst":"She entered the tomb to prevent his resurrection of the dead"},"Hillgrund''s Family":{"aff":-65,"type":"contempt","relation":"desecrated ancestors","note":"Views them as foolish traditionalists and useful corpses for his research","best":"Their well-preserved remains provided excellent necromantic specimens"},"Local Nords":{"aff":-50,"type":"contempt","relation":"cultural opponents","note":"Dismisses their burial traditions as superstition impeding practical use of the dead"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vampire', '{"Molag Bal":{"aff":15,"type":"indebted","relation":"creator","note":"Molag Bal created the first vampire by corrupting Saint Lamae Beolfag, originating the blood curse all vampires bear.","best":"Received the gift of immortality through his curse","worst":"The curse strips away humanity over the centuries"},"Vigilants of Stendarr":{"aff":-80,"type":"enemy","relation":"hunters","note":"Sworn enemies who actively hunt and destroy vampires wherever found.","worst":"Their relentless hunts have destroyed countless vampire covens"},"Dawnguard":{"aff":-85,"type":"enemy","relation":"hunters","note":"Dedicated vampire hunters who pose a significant organized threat.","worst":"Their organized efforts threaten vampire existence across Skyrim"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vampire_fledgling', '{"Master Vampire":{"aff":15,"type":"fearful","relation":"sire","note":"Depends on their sire for survival and guidance but lives in fear of them","best":"Received protection and instruction in vampiric abilities","worst":"Experienced the terror of being turned and the sire''s controlling influence"},"Former Family":{"aff":55,"type":"estranged","relation":"abandoned loved ones","note":"Avoids all contact to protect them from their new predatory nature","best":"Cherished memories of mortal life together","worst":"Had to vanish without explanation, leaving them to wonder"},"Fellow Fledglings":{"aff":25,"type":"platonic","relation":"fellow newly-turned","note":"Shares cautious camaraderie with others struggling through the same transformation","best":"Found understanding in others who share the hunger and guilt","worst":"Witnessed a fellow fledgling lose control and kill indiscriminately"},"Vampire Hunters":{"aff":-60,"type":"fearful","relation":"natural enemies","note":"Fears their stakes and fire but secretly envies their normal mortal lives","worst":"Narrowly escaped a hunter''s ambush that nearly ended their undead existence"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vampire_mistwalker', '{"Vampire Clans":{"aff":-25,"type":"estranged","relation":"rejected kin","note":"Rejected vampire court politics and hierarchies, maintains cautious distance to avoid territorial conflicts","worst":"Centuries of pressure to submit to vampire court hierarchies she despises"},"Vigilants of Stendarr":{"aff":-85,"type":"enemy","relation":"hunters","note":"Active enemies who frequently attempt to track and destroy her","worst":"Constant pursuit forcing relocation of hunting grounds"},"Local Hunters":{"aff":-35,"type":"rival","relation":"competition","note":"Viewed as competition for prey and occasionally hunted themselves","best":"Eliminating a skilled tracker who was closing in on her lair"},"Mortal Settlements":{"aff":-20,"type":"transactional","relation":"feeding grounds","note":"Sources of information and blood, approached with careful planning and charm","best":"Successfully feeding without drawing suspicion for months"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vampire_nighstalker', '{"Vampire Clans":{"aff":-25,"type":"suspicious","relation":"monitored rivals","note":"Maintains cautious distance while observing their activities and politics"},"Morthal Guards":{"aff":-40,"type":"fearful","relation":"law enforcement","note":"Carefully avoids detection while operating in their jurisdiction"},"Fellow Night Hunters":{"aff":15,"type":"transactional","relation":"occasional allies","note":"Forms temporary alliances of convenience with other solitary vampires"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vanik', '{"Dexion Evicus":{"aff":75,"type":"protective","relation":"charge","note":"Guards the Moth Priest with unwavering dedication at Forebears'' Holdout","best":"Successfully kept Dexion alive through vampire assaults","worst":"Uncertainty over whether Dexion may have been turned by vampires"},"Isran":{"aff":60,"type":"professional","relation":"commanding officer","note":"Serves loyally under Isran''s leadership of the reformed Dawnguard"},"Vampires":{"aff":-85,"type":"enemy","relation":"sworn enemy","note":"Actively hunts and combats vampires as a dedicated Dawnguard member","worst":"Witnessed devastation of settlements by vampire attacks"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vanryth_gatharian', '{"Thieves Guild":{"aff":65,"type":"professional","relation":"trusted supplier and member","note":"Essential weaponsmith operating under Guild protection in the Ratway","best":"Earned protected position through discretion and quality craftsmanship","worst":"Refuses all service to those who cross the Guild"},"Maven Black-Briar":{"aff":35,"type":"transactional","relation":"special order client","note":"Cautious business relationship with Riften''s shadow power"},"Glover Mallory":{"aff":50,"type":"mentor","relation":"former student","note":"Implied to have taught Glover bonemold smithing techniques","best":"Passed on specialized Morrowind craft knowledge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vantus_loreius', '{"Curwe":{"aff":85,"type":"romantic","relation":"wife","note":"His Altmer wife and farming partner; shows his softer side only with her","best":"Building a life together on their own farm"},"Cicero":{"aff":-75,"type":"suspicious","relation":"unwanted stranger","note":"Deeply distrusts the jester and suspects his coffin contains contraband","worst":"Cicero''s relentless demands to fix his wagon wheel"},"Guard":{"aff":25,"type":"professional","relation":"local patrol","note":"Knows the guard who patrols the nearby road and relies on him to handle trouble"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('varnius_junius', '{"Jarl Elisif":{"aff":60,"type":"professional","relation":"jarl","note":"Respects her authority and successfully petitioned her for help with Wolfskull Cave","best":"She immediately promised to send a legion to secure Dragon Bridge"},"Falk Firebeard":{"aff":35,"type":"professional","relation":"steward","note":"Views him as practical-minded; Falk initially dismissed his warnings but later admitted he should have listened","worst":"Falk called him jumpy and tempered the Jarl''s response"},"Sybille Stentor":{"aff":-40,"type":"rival","relation":"court wizard","note":"She publicly dismissed his warnings as superstitious nonsense and called him a fool","worst":"She undermined his plea before the Jarl and was proven wrong"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vasha', '{"Astrid":{"aff":-75,"type":"enemy","relation":"captor","note":"Kidnapped him as a potential target for Dark Brotherhood initiation","worst":"Bagged and dragged to the Abandoned Shack to be killed on command"},"Dark Brotherhood":{"aff":-70,"type":"fearful","relation":"captors","note":"Held hostage as part of their initiation ritual"},"Criminal Associates":{"aff":45,"type":"professional","relation":"network","note":"Contacts across multiple provinces who he claims would avenge him","best":"Built a network that spans multiple provinces"},"Rival Crime Lords":{"aff":-30,"type":"rival","relation":"competitors","note":"Both business partners and potential enemies in the underworld"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('veezara', '{"Astrid":{"aff":80,"type":"professional","relation":"leader","note":"Serves Astrid with unwavering loyalty and finds renewed purpose under her leadership","best":"Being given purpose and belonging in the Sanctuary after losing his Shadowscale order"},"Babette":{"aff":65,"type":"platonic","relation":"sister","note":"Shares warm camaraderie and humor with Babette in the Sanctuary","best":"Babette tending to his wounds after Cicero''s attack"},"Arnbjorn":{"aff":55,"type":"platonic","relation":"brother","note":"Enjoys friendly banter and shared laughter with fellow assassin"},"Cicero":{"aff":-40,"type":"suspicious","relation":"fellow brother","note":"Was uncertain about Cicero''s devotion to the old ways, then attacked and wounded by him","worst":"Being attacked and wounded by Cicero in the Sanctuary"},"King of Black Marsh":{"aff":40,"type":"professional","relation":"former employer","note":"Once served as a Shadowscale assassin in service to the King of Black Marsh"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vekel_the_man', '{"Tonilia":{"aff":55,"type":"romantic","relation":"romantic interest","note":"Pursuing marriage despite her repeated refusals and rumors of her infidelity with Brynjolf","best":"The moments she agrees to be with him","worst":"Each time she refuses his marriage proposal"},"Dirge":{"aff":60,"type":"platonic","relation":"close friend and bouncer","note":"Trusted friend who fiercely protects the Flagon and Vekel''s interests"},"Brynjolf":{"aff":-15,"type":"jealous","relation":"suspected rival","note":"Resents the rumors of Brynjolf''s affair with Tonilia","worst":"Hearing the rumors about Tonilia and Brynjolf"},"Maven Black-Briar":{"aff":25,"type":"transactional","relation":"powerful patron","note":"Cautious business relationship through Guild connections"},"Thieves Guild":{"aff":45,"type":"professional","relation":"guild member and operative","note":"Runs the Ragged Flagon as both legitimate business and Guild front, though frustrated by the Guild''s decline"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('velehk_sain', '{"College of Winterhold":{"aff":-70,"type":"enemy","relation":"captors","note":"Mages who bound him beneath the College; their souls were trapped in Oblivion as a result of the binding","worst":"Imprisoned by their spell in the Midden for an unknown duration"},"Mehrunes Dagon":{"aff":-20,"type":"estranged","relation":"former master","note":"Abandoned Dagon''s armies to pursue piracy on the Abecean Sea"},"His Pirate Crew":{"aff":40,"type":"professional","relation":"crew","note":"Led mortal pirates in raids; their fate after his binding is unknown"},"Imperial Navy":{"aff":-55,"type":"rival","relation":"adversaries","note":"Sank Imperial galleons and plundered vessels along the Hammerfell coast","best":"Sunk an Imperial Galleon and secured substantial plunder"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('venarus_vulpin', '{"Solitude Vampire":{"aff":55,"type":"indebted","relation":"informant","note":"Provided the crucial direction that led him to the Bloodspring","best":"She pointed me toward the Rift when all my research had failed"},"Skooma Dealers":{"aff":25,"type":"transactional","relation":"business partners","note":"Distribute his blood-spiked skooma and sustain the feeding operation"},"Redwater Den Addicts":{"aff":-85,"type":"contempt","relation":"prey","note":"Viewed as mere cattle whose addiction ensures a constant food supply"},"Rift Guards":{"aff":15,"type":"transactional","relation":"bribed officials","note":"Paid to maintain distance from Redwater Spring"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vendil_severin', '{"Tilisu Severin":{"aff":20,"type":"professional","relation":"wife and co-conspirator","note":"Marriage is a calculated cover; strained by mutual suspicion and his infidelities","worst":"She accused him of wanting another woman; he coldly told her to mind her own business"},"Mirri Severin":{"aff":30,"type":"professional","relation":"adopted daughter and fellow agent","note":"Functional alliance under the family facade, but she defies him and mocks his caution","worst":"She dismissed his fears of exposure and sarcastically called him father"},"Lleril Morvayn":{"aff":-85,"type":"nemesis","relation":"assassination target","note":"Vendil has spent ten years plotting to kill him to avenge the Ulen family and weaken House Redoran","best":"His plot came within striking distance of success"},"Adril Arano":{"aff":-50,"type":"contempt","relation":"deceived official","note":"Plays the helpful citizen while secretly undermining everything Adril''s faction stands for","best":"Adril thanked him profusely for his family''s contributions to Raven Rock"},"House Hlaalu":{"aff":90,"type":"fanatical","relation":"true allegiance","note":"His entire life on Solstheim is dedicated to restoring their power; he dies shouting their name","best":"Ten years of covert planning in service to the House"},"Ulen Family":{"aff":80,"type":"indebted","relation":"avenged kin","note":"Devoted to avenging Vilur Ulen; his dying words invoke joining his father in death","worst":"Vilur Ulen was killed by House Redoran, fueling his decade-long vendetta"},"Glover Mallory":{"aff":10,"type":"transactional","relation":"business associate","note":"Maintained for appearances; their conversations are cordial but superficial"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('venomfang_skeever', '{"Hamelyn":{"aff":10,"type":"servant","relation":"creation","note":"Created through alchemical experimentation; serves via magical control rather than genuine loyalty"},"Enhanced Skeevers":{"aff":40,"type":"protective","relation":"pack leader","note":"Leads and coordinates the mutated pack in coordinated attacks"},"Maven Black-Briar":{"aff":-25,"type":"enemy","relation":"indirect adversary","note":"Her opposition to Hamelyn''s operation makes her an indirect threat"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('veren_duleri', '{"Vaermina":{"aff":100,"type":"fanatical","relation":"revered Daedric Prince","note":"Absolute devotion to Vaermina''s will, willing to sacrifice everything including his own life"},"Erandur":{"aff":-90,"type":"nemesis","relation":"former brother, now traitor","note":"Despises Erandur for fleeing the temple and betraying their faith","worst":"Watching Casimir run while they remained to face the Miasma"},"Thorek":{"aff":75,"type":"platonic","relation":"fellow priest and companion","note":"Served alongside Thorek for years and stood together defending the Skull to the death","best":"Standing united with Thorek to guard the Skull with their lives"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('verner_rock-chucker', '{"Annekke Crag-Jumper":{"aff":70,"type":"romantic","relation":"wife","note":"Loves her deeply but frustrated by her adventuring instead of helping with the mine","best":"Used to love finding new places together in their early days","worst":"Sometimes feels she cares more about finding new rocks than being with him"},"Sylgja":{"aff":75,"type":"familial","relation":"daughter","note":"Cares for her and worries about her independent streak inherited from her mother","best":"Happy to receive packages from her, glad she still thinks of her parents","worst":"She cannot make the journey to visit them herself"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vex', '{"Brynjolf":{"aff":55,"type":"professional","relation":"trusted colleague","note":"Shares her fierce dedication to the guild''s restoration"},"Delvin Mallory":{"aff":45,"type":"professional","relation":"colleague","note":"Fellow senior member; dismisses his curse theories but respects his work"},"Mercer Frey":{"aff":-30,"type":"betrayed","relation":"former guild master","note":"Served with professional respect until his treachery was revealed","worst":"Discovered his betrayal of the guild"},"Tonilia":{"aff":40,"type":"professional","relation":"fellow guild member","note":"Mutual professional respect as senior guild operatives"},"Thieves Guild":{"aff":75,"type":"protective","relation":"guild","note":"Remained steadfastly loyal through the guild''s darkest period","best":"Witnessed the guild''s golden age prosperity","worst":"Watched the guild''s fall from prominence and exodus of members"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('viarmo', '{"Inge Six Fingers":{"aff":60,"type":"professional","relation":"colleague","note":"Respected master instrumentalist; Viarmo trusts her with students"},"Pantea Ateia":{"aff":55,"type":"professional","relation":"colleague","note":"Valued voice instructor; he gently corrects her favoritism"},"Giraud Gemane":{"aff":50,"type":"professional","relation":"colleague","note":"Trusted historian but grumbles about teaching duties"},"Jarl Elisif the Fair":{"aff":30,"type":"professional","relation":"jarl","note":"Requires careful diplomacy; she banned his cherished festival","worst":"She forbade the Burning of King Olaf after Torygg''s death"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vidgrod', '{"Agrius":{"aff":70,"type":"platonic","relation":"fellow outcast","note":"Close companion who shared exile and final fate in Halldir''s Cairn","best":"Stood together after being cast out from the gang","worst":"Died together under Halldir''s possession"},"Raen":{"aff":70,"type":"platonic","relation":"fellow outcast","note":"Trusted ally who remained loyal through exile and death","best":"Stayed by each other''s side when the gang turned on them","worst":"Perished together under Halldir''s thrall"},"Former Bandit Gang":{"aff":-60,"type":"estranged","relation":"former gang","note":"Expelled for unknown reasons, forcing desperate search for shelter","worst":"Cast out into the wilderness with nothing"},"Halldir":{"aff":-95,"type":"nemesis","relation":"unwilling thrall","note":"Ancient entity who possessed and killed them, then consumed their remains","worst":"Enslaved in death and body used to fuel elemental copies"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vidrald', '{"Avulstein Gray-Mane":{"aff":85,"type":"platonic","relation":"sworn brother","note":"Pledged to aid him and Thorald long ago; nothing could keep him from fulfilling that oath","best":"Grew up alongside the Gray-Mane children forming an unbreakable bond"},"Thorald Gray-Mane":{"aff":85,"type":"platonic","relation":"childhood friend","note":"Determined to rescue him from Thalmor captivity at Northwatch Keep","worst":"Thorald was captured and imprisoned by the Thalmor"},"Geirlund":{"aff":60,"type":"platonic","relation":"shield-sibling","note":"Trusted combat companion who fights alongside him at Northwatch Keep","best":"Fought side by side to rescue Thorald"},"Thalmor":{"aff":-90,"type":"enemy","relation":"bitter enemy","note":"Despises them for their persecution of Nords and imprisonment of Thorald","worst":"They captured and tortured his childhood friend Thorald"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vigdis_salvius', '{"Rogatus Salvius":{"aff":80,"type":"romantic","relation":"husband","note":"Married over 50 years; she patiently counters his chronic pessimism with warmth","best":"Building a life and farm together through decades of hardship","worst":"Enduring his unrelenting gloom and refusal to welcome visitors"},"Leontius Salvius":{"aff":55,"type":"estranged","relation":"son","note":"Left for Old Hroldan nearly 30 years ago; she still misses him and hopes for grandchildren","best":"Raising him before his departure","worst":"His long absence leaving her to wonder if she will ever see him again"},"Local Guards":{"aff":25,"type":"protective","relation":"farm protectors","note":"Keeps cordial ties and suggests inviting them for supper to ensure farm safety"},"Markarth Merchants":{"aff":15,"type":"transactional","relation":"trading partners","note":"Regular buyers of the farm''s potato crop"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vighar', '{"Dengeir of Stuhn":{"aff":-65,"type":"estranged","relation":"distant descendant","note":"Vighar has completely abandoned his mortal family ties and views his lineage with contempt","worst":"His descendant now seeks his death to end the family''s shame"},"Player":{"aff":-85,"type":"contempt","note":"Views the player as another fool to be toyed with and killed","worst":"Dismissed the player as ''this fool'' who would be ''the next act of the show''"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vigil_of_stendar', '{"Keeper Carcette":{"aff":75,"type":"mentor","relation":"respected superior","note":"Looks to Carcette for guidance and leadership within the Hall of the Vigilant."},"Vigilants of Stendarr":{"aff":85,"type":"platonic","relation":"fellow order members","note":"Considers them brothers and sisters united in sacred purpose."},"Daedra worshippers":{"aff":-95,"type":"nemesis","relation":"irredeemable enemies","note":"Views them as the root of all suffering, to be purged without mercy.","worst":"Lost their family to Daedric cultists during the Oblivion Crisis."},"Vampires":{"aff":-100,"type":"enemy","relation":"primary targets for elimination","note":"Dedicated to hunting and eradicating vampiric threats across Skyrim."},"Werewolves":{"aff":-90,"type":"enemy","relation":"hunted abominations","note":"Considered unnatural threats to be destroyed alongside other Daedric creatures."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vigilant_adalvald', '{"Vigilants of Stendarr":{"aff":85,"type":"protective","relation":"brotherhood","note":"Devoted member and respected scholar who served the order until his final breath","best":"Rose through the ranks through scholarly aptitude and combat prowess","worst":"Failed to survive his investigation of Dimhollow Crypt"},"Vigilant Tolan":{"aff":75,"type":"platonic","relation":"colleague","note":"Close colleague who later sought to avenge his death","best":"Shared devotion to Stendarr''s cause and mutual trust","worst":"Tolan discovered his fallen comrade''s body in Dimhollow"},"Keeper Carcette":{"aff":70,"type":"mentor","relation":"superior","note":"Mentor and superior officer within the Vigilants who guided his rise"},"Lokil":{"aff":-95,"type":"enemy","relation":"killer","note":"Vampire who tortured and killed him during interrogation at Dimhollow","worst":"Refused to break under torture but was slain anyway"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vigilant_tolan', '{"Isran":{"aff":25,"type":"professional","relation":"reluctant ally","note":"Seeks aid after the Hall''s destruction; admits Isran was right but resents his dismissiveness toward the Vigilants","best":"Isran expressed genuine sorrow for the Vigilants'' losses","worst":"Isran dismissed the Vigilants as untrained and soft"},"Keeper Carcette":{"aff":80,"type":"mentor","relation":"former superior","note":"Respected leader whose death in the vampire attack deeply affected him","best":"Served under her for many years at the Hall of Vigilants","worst":"She was killed when the Hall was destroyed"},"Brother Adalvald":{"aff":55,"type":"platonic","relation":"fellow Vigilant","note":"Dismissed Adalvald''s warnings about Dimhollow; now regrets not listening","best":"Adalvald''s research provided crucial intelligence on vampire activity","worst":"Ignored his findings before he died at the Hall"},"Vampires":{"aff":-90,"type":"nemesis","relation":"sworn enemies","note":"Destroyed the Hall of Vigilants and killed his comrades; seeks vengeance above all else","worst":"Destroyed the Hall and slaughtered nearly all the Vigilants"},"Remaining Vigilants":{"aff":65,"type":"protective","relation":"surviving brethren","note":"Feels responsible for the scattered survivors of the decimated order"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vigilant_tyranus', '{"Vigil of Stendarr":{"aff":90,"type":"fanatical","relation":"devoted member","note":"Joined after losing family to Daedric cultists; the Vigil is his entire identity and purpose.","best":"Recognition within the Vigil for his combat and restoration aptitude","worst":"Failing his order by falling to Molag Bal''s manipulation"},"Molag Bal":{"aff":-95,"type":"fearful","relation":"victim","note":"The Daedric Prince who psychologically breaks him, forcing him to fight for survival in the Abandoned House.","worst":"Hearing Molag Bal''s voice in his head, realizing he must kill or die"},"Player":{"aff":30,"type":"professional","relation":"reluctant ally turned adversary","note":"Seeks the player''s help investigating the Abandoned House; Molag Bal forces them into mortal combat.","best":"Accepting help to watch his back against Daedric threats","worst":"Drawing his weapon and declaring ''It''s you or me!''"},"Markarth Citizens":{"aff":-10,"type":"suspicious","relation":"distrusted investigator","note":"Locals claim ignorance about the Abandoned House and resent his persistent questioning."}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vignar_gray-mane', '{"Eorlund Gray-Mane":{"aff":78,"type":"familial","relation":"younger brother","note":"Patriarch of the clan while Eorlund works the Skyforge; their bond anchors the family''s prestige"},"Brill":{"aff":65,"type":"protective","relation":"steward","note":"Vignar rehabilitated Brill from a self-destructive lifestyle and trusts him deeply","best":"Helped Brill turn his life around"},"Olfrid Battle-Born":{"aff":-72,"type":"rival","relation":"rival patriarch","note":"Once fast friends, now divided by the Civil War; Vignar patrols Whiterun keeping watch on him","worst":"Families chose opposing sides in the uprising, turning old friendship to bitter enmity"},"Ulfric Stormcloak":{"aff":76,"type":"professional","relation":"rebellion ally","note":"Staunch supporter who shares Vignar''s vision of Nordic independence from the Empire"},"The Companions":{"aff":68,"type":"platonic","relation":"honorary shield-brother","note":"Decades of service earned him lifelong honorary membership; still lives in Jorrvaskr"},"Balgruuf the Greater":{"aff":-45,"type":"rival","relation":"political opponent","note":"Vignar replaces him as Jarl if the Stormcloaks take Whiterun; opposes his Imperial leanings"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('viinturuth', '{"Alduin":{"aff":90,"type":"fanatical","relation":"resurrector and overlord","note":"Serves with unwavering loyalty as one of Alduin''s lieutenants","best":"Resurrected from eternal entombment to serve again"},"Ancient Nordic Heroes":{"aff":-85,"type":"enemy","relation":"former vanquishers","note":"Those who originally defeated and entombed him during the Merethic Era","worst":"Defeated and sealed in a tomb near Lake Yorgrim for millennia"},"Other Dragons":{"aff":45,"type":"platonic","relation":"brothers in conquest","note":"Fellow servants of Alduin viewed as kin in dominance"},"Mortals":{"aff":-70,"type":"contempt","relation":"lesser beings","note":"Views all mortal races as fit only for subjugation or destruction"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vikmund', '{"Thonnir":{"aff":65,"type":"familial","relation":"father","note":"Loves his father but senses he is hiding the truth about his mother","best":"Father trying to comfort him after the disappearance","worst":"Father''s evasive silence when asked about what really happened"},"Agni":{"aff":78,"type":"platonic","relation":"close friend","note":"Relies on Agni for companionship and emotional support through his grief","best":"Playing together and forgetting his sadness for a while"},"Lami":{"aff":45,"type":"platonic","relation":"trusted adult","note":"Regular visitor to her shop, finding comfort in routine and her presence"},"Mother":{"aff":85,"type":"familial","relation":"missing mother","note":"Clinging to hope she will return despite all evidence to the contrary","best":"Memories of her presence before she vanished","worst":"The unexplained disappearance that haunts him daily"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vilkas', '{"Farkas":{"aff":90,"type":"familial","relation":"twin brother","note":"Unshakeable bond despite their contrasting personalities","best":"Raised together in Jorrvaskr since childhood"},"Kodlak Whitemane":{"aff":85,"type":"mentor","relation":"mentor and father figure","note":"Deeply respects his wisdom, especially regarding the beast blood curse","best":"Kodlak vouched for new recruits and guided the Circle with honor","worst":"Could not save Kodlak from the Silver Hand"},"Aela the Huntress":{"aff":45,"type":"professional","relation":"shield-sister","note":"Mutual respect but frequent disagreement over embracing versus curing lycanthropy"},"Skjor":{"aff":35,"type":"professional","relation":"former shield-brother","note":"Helped initiate him into the beast blood, a gift Vilkas now questions"},"Silver Hand":{"aff":-85,"type":"enemy","relation":"sworn enemy","note":"Hunt werewolves and murdered Kodlak","worst":"Killed Kodlak and desecrated his remains"},"Jergen":{"aff":-15,"type":"dismissive","relation":"possible father","note":"Brought the twins to Jorrvaskr then left for the Great War and never returned","worst":"Abandoned them to fight and never came back"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vilod', '{"Ralof":{"aff":65,"type":"platonic","relation":"patron","note":"Fellow Stormcloak sympathizer who fondly remembers Vilod''s juniper berry mead","best":"Sharing drinks and camaraderie at the tavern"},"Family":{"aff":85,"type":"familial","relation":"loved ones","note":"His dying wish was that they be told he fought bravely"},"Imperial Soldiers":{"aff":10,"type":"professional","relation":"customers","note":"Served them despite political opposition; one tried desperately to save his life","best":"An Imperial soldier attempting to stop his bleeding","worst":"Watching Stormcloaks executed at the block"},"Stormcloaks":{"aff":75,"type":"fanatical","relation":"cause supporter","note":"Shouted ''Justice!'' at a Stormcloak execution, unwavering in his loyalty","worst":"Witnessing fellow rebels beheaded"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vingalmo', '{"Lord Harkon":{"aff":-30,"type":"rival","relation":"nominal superior","note":"Outwardly serves while secretly coveting his position and dreaming of usurping control"},"Orthjolf":{"aff":-50,"type":"rival","relation":"court rival","note":"Longstanding rivalry for influence within the Volkihar court","worst":"Orthjolf mocks his scholarly habits and questions his loyalty"},"Salonia Caelia":{"aff":30,"type":"servant","relation":"agent","note":"Subordinate vampire who carries out his tasks and furthers his agenda"},"Serana":{"aff":20,"type":"professional","relation":"lord''s daughter","note":"Treats with careful calculated respect due to her lineage and position"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('viola_giordano', '{"Captain Lonely-Gale":{"aff":72,"type":"crush","relation":"romantic interest","note":"Pines after him obsessively but he consistently spurns her advances, citing his late wife","best":"Mustering courage to invite him to spend time together","worst":"Being rebuffed yet again when he dismisses her invitations"},"Windhelm Guards":{"aff":-25,"type":"contempt","relation":"local law enforcement","note":"Frustrated by their refusal to investigate the Butcher murders, prioritizing the war instead"},"The Butcher":{"aff":-85,"type":"nemesis","relation":"serial killer","note":"Has dedicated herself to finding the murderer the guards won''t pursue","worst":"Women murdered while authorities did nothing"},"Susanna the Wicked":{"aff":30,"type":"pitying","relation":"murder victim","note":"Her death deepened Viola''s resolve to catch the Butcher"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vipir_the_fleet', '{"Sapphire":{"aff":60,"type":"crush","relation":"romantic interest","note":"Persistently courts her despite constant rejection","worst":"Being turned down yet again in front of the whole Guild"},"Mercer Frey":{"aff":-40,"type":"betrayed","relation":"former guild master","note":"Served loyally until discovering Mercer emptied the vault and abandoned them","worst":"Learning Mercer had stolen everything from under their noses"},"Vex":{"aff":55,"type":"professional","relation":"former partner","note":"Partnered on the infamous Windhelm job that earned him his nickname","best":"The legendary escape from Windhelm together"},"Delvin Mallory":{"aff":50,"type":"mentor","relation":"senior guild member","note":"Respects Delvin as a senior member and occasional mentor"},"Niruin":{"aff":40,"type":"rival","relation":"friendly rival","note":"Competes with Niruin in archery on friendly terms"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('viriya', '{"Swims-In-Deep-Water":{"aff":72,"type":"platonic","relation":"colleague","note":"Close fellow fishing expert at the Riften Fishery and partner in managing operations"},"Snippy":{"aff":88,"type":"protective","relation":"pet mudcrab","note":"Beloved pet and the successful result of her breeding program"},"Father":{"aff":80,"type":"familial","relation":"father and mentor","note":"Taught her traditional Alik''r fishing techniques; she treasured his fishing rod","best":"Learning the fishing traditions that shaped her life"},"Player":{"aff":78,"type":"grateful","relation":"trusted ally","note":"Came to rely on them through the fishing questline and gifted her father''s rod","best":"Helped achieve her dream of opening a market stall in the plaza","worst":"Sent into dangerous mudcrab situations on her behalf"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('visiting_advisor', '{"Skyrim Jarls":{"aff":15,"type":"contempt","relation":"manipulated employers","note":"Views them as gullible pawns to be steered toward vampire interests","best":"Swaying a stubborn jarl''s policy with honeyed counsel","worst":"A jarl growing suspicious of his advice"},"Vampire Coven":{"aff":75,"type":"servant","relation":"true masters","note":"Loyal infiltrator executing coven directives across Skyrim''s courts","best":"Delivering intelligence that shifts regional power in the coven''s favor","worst":"Failing a mission and facing coven displeasure"},"Court Wizards":{"aff":-35,"type":"suspicious","relation":"wary adversaries","note":"They often sense something amiss about his presence and motives","best":"Discrediting a wizard''s warnings as mere paranoia","worst":"A wizard convincing a jarl to doubt his counsel"},"Stewards":{"aff":-20,"type":"rival","relation":"political competitors","note":"Competes with them for jarls'' trust and influence over court decisions","best":"Supplanting a steward''s influence with superior rhetoric","worst":"A steward blocking his access to a jarl"},"Dawnguard":{"aff":-85,"type":"enemy","relation":"sworn hunters","note":"Vampire hunters dedicated to rooting out infiltrators like him","best":"Evading their detection while maintaining his cover","worst":"Being cornered by Dawnguard operatives in a jarl''s hall"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('visiting_noble', '{"Jarl Balgruuf":{"aff":25,"type":"professional","relation":"court contact","note":"Regular visitor to Dragonsreach seeking business or political advantage"},"Proventus Avenicci":{"aff":15,"type":"professional","relation":"court steward","note":"Likely contact for court matters and estate business"},"Dark Brotherhood":{"aff":-90,"type":"enemy","relation":"contract target","note":"Named as potential mark for the Dark Brotherhood Forever"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vittoria_vici', '{"Titus Mede II":{"aff":25,"type":"familial","relation":"cousin","note":"Distant relationship; she resents assumptions of nepotism when he has given her nothing","worst":"He can''t even be bothered to attend my wedding"},"Asgeir Snow-Shod":{"aff":70,"type":"romantic","relation":"fiancÃ©","note":"Political match that grew into genuine affection","best":"Practically glowing while planning their wedding"},"Snow-Shod Family":{"aff":35,"type":"familial","relation":"soon-to-be in-laws","note":"Opposing political loyalties but united by the marriage alliance"},"East Empire Company Workers":{"aff":55,"type":"professional","relation":"subordinates","note":"Earned their respect through demonstrated competence rather than family name"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vivienne_onis', '{"Angeline Morrard":{"aff":80,"type":"familial","relation":"aunt and mentor","note":"Works alongside her at Angeline''s Aromatics and is heir apparent to the business"},"Sorex Vinius":{"aff":45,"type":"platonic","relation":"childhood friend","note":"He harbors secret affection for her; their friendship was strained when Roggvir bullied him over it","best":"Growing up together as close friends in Solitude","worst":"Roggvir tormenting Sorex after learning of his feelings for her"},"Roggvir":{"aff":-85,"type":"enemy","relation":"former friend turned traitor","note":"Blames him for her cousin Fura having to fight in the war; approved of his execution","worst":"His betrayal of Solitude by opening the gate for Ulfric"},"Fura":{"aff":70,"type":"protective","relation":"cousin","note":"Cousin serving in the Imperial Legion; worries about her safety because of the war Roggvir enabled"},"Vittoria Vici":{"aff":35,"type":"platonic","relation":"social acquaintance","note":"Attended her wedding and admired her advantageous match"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('voada', '{"Rondach":{"aff":85,"type":"familial","relation":"brother","note":"Fellow kitchen worker who fiercely defends her from Anton''s abuse","best":"Stood up to Anton when he threatened to cut off her fingers","worst":"His confrontations with Anton create more tension she must mediate"},"Anton Virane":{"aff":-45,"type":"professional","relation":"employer","note":"Abusive master chef who berates and threatens her and her brother","worst":"Threatened to cut off her fingers over spilled laundry water"},"Banning":{"aff":30,"type":"transactional","relation":"associate","note":"Provides spiced beef for the keep''s dogs","best":"Sends spiced beef deliveries that keep the dogs fed and calm"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('voldsea_giryon', '{"Captain Kjar":{"aff":65,"type":"professional","relation":"captain","note":"Respects his fair leadership and rewards hard work and loyalty","best":"He never fails to reward hard work and loyalty"},"The North Wind Crew":{"aff":35,"type":"platonic","relation":"crewmates","note":"Shares professional camaraderie with fellow sailors"},"Elda Early-Dawn":{"aff":20,"type":"transactional","relation":"innkeeper","note":"Regular patron at Candlehearth Hall while in port"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('volk', '{"Moric Sidrey":{"aff":45,"type":"professional","relation":"expedition leader","note":"Volunteered to join Sidrey''s excavation team at Ruunvald after he requested assistance"},"Minorne":{"aff":-85,"type":"enemy","relation":"warlock","note":"Resisted her mind domination longer than his companions but ultimately fell to her charms","worst":"Being enthralled by Minorne despite his strong will and devotion"},"Vigilants of Stendarr":{"aff":85,"type":"fanatical","relation":"devoted member","note":"Dedicated his life to the order after witnessing Daedric corruption in his youth"},"Florentius Baenius":{"aff":35,"type":"professional","relation":"fellow Vigilant","note":"Was indirectly seeking his location during the Ruunvald investigation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('volkihar_vampire', '{"Lord Harkon":{"aff":75,"type":"professional","relation":"patriarch and clan leader","note":"Serves under Harkon''s rule in the Volkihar court, bound by loyalty and shared vampiric ambition.","best":"Received the gift of Vampire Lord blood from Harkon''s lineage","worst":"Harkon''s obsessive pursuit of the Tyranny of the Sun puts the clan at risk"},"Serana":{"aff":40,"type":"professional","relation":"clan elder''s daughter","note":"Respects her ancient blood and Elder Scroll knowledge, but her defiance of Harkon creates tension.","best":"Her return with the Elder Scroll promised the clan''s ascendance","worst":"Her opposition to Harkon''s ritual threatens to divide the clan"},"Dawnguard":{"aff":-85,"type":"nemesis","relation":"sworn enemy","note":"The vampire-hunting order is the greatest organized threat to Volkihar existence in Skyrim.","worst":"Dawnguard raids have destroyed vampire lairs and killed clan members"},"Molag Bal":{"aff":60,"type":"fanatical","relation":"dark father and creator","note":"Reveres the Daedric Prince who first bestowed the vampiric curse upon the Volkihar bloodline.","best":"His dark blessing created the pure-blooded Volkihar lineage"},"Vampire''s Thralls":{"aff":-10,"type":"contempt","relation":"enthralled servants and prey","note":"Mortals kept under vampiric domination as obedient servants and convenient blood sources.","best":"Thralls provide willing sustenance without the need to hunt"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vorstag', '{"Player":{"aff":40,"type":"transactional","relation":"hireling","note":"Can be hired for 500 septims; becomes potential marriage candidate after hiring","best":"Offered his blade willingly and fights closely at your side"},"Silver-Blood Inn Staff":{"aff":30,"type":"professional","relation":"patron","note":"Regular tenant using the inn as his base of operations in Markarth"},"Local Miners":{"aff":-20,"type":"suspicious","relation":"avoided acquaintances","note":"Keeps distance due to personal aversion to mines, possibly from past trauma","worst":"Negative experiences in the Reach''s notorious silver mines"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vuljotnaak', '{"Alduin":{"aff":95,"type":"fanatical","relation":"resurrector and master","note":"Serves with absolute and unwavering loyalty as one of his lieutenants","best":"Resurrected from death to serve once more"},"Fellow Dragons":{"aff":55,"type":"platonic","relation":"kindred","note":"Considers them kindred in the divine right to rule over mortals"},"Dragon Priests":{"aff":30,"type":"professional","relation":"former servants","note":"Commanded them as mortal intermediaries during the Merethic Era"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vulthuryol', '{"Dwemer":{"aff":-55,"type":"suspicious","relation":"captor","note":"Bound by their mechanisms in Blackreach, though the true nature of their arrangement remains lost to time","worst":"Sealed underground whether by treachery or bargain, abandoned when the Dwemer vanished"},"Other Dragons":{"aff":-25,"type":"estranged","relation":"outcast","note":"Isolated from dragonkind for millennia, likely forgotten or dismissed by his own kind"},"Falmer":{"aff":-10,"type":"dismissive","relation":"neighbors","note":"Shares the depths of Blackreach but pays the twisted creatures no mind"},"Dragonborn":{"aff":-75,"type":"enemy","relation":"intruder","note":"Attacks any who summon him without hesitation or attempt at dialogue","worst":"An intruder dares disturb his dark domain with the calling orb"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('vulwulf_snow-shod', '{"Nura Snow-Shod":{"aff":85,"type":"familial","relation":"wife","note":"Beloved wife and priestess of Talos, bound together by shared grief over Lilija"},"Asgeir Snow-Shod":{"aff":25,"type":"estranged","relation":"son","note":"Disapproves of his Imperial business ties and marriage to an Imperial woman","worst":"Learning his son intended to marry into an Imperial family"},"Unmid Snow-Shod":{"aff":75,"type":"familial","relation":"son","note":"Proud of him for following Nordic traditions as a city guard"},"Lilija Snow-Shod":{"aff":95,"type":"familial","relation":"deceased daughter","note":"Her death as a battle maiden at Imperial hands shattered him and fuels his hatred","best":"Watching her serve proudly as a Stormcloak battle maiden healing the fallen","worst":"Imperial soldiers cut her down and left her body to rot in the mud"},"Ulfric Stormcloak":{"aff":70,"type":"fanatical","relation":"political leader","note":"Devoted supporter who vows not to rest until Ulfric sits on Skyrim''s throne"},"Maven Black-Briar":{"aff":15,"type":"transactional","relation":"business associate","note":"Connected through Snow-Shod meadery interests in Riften"},"Vittoria Vici":{"aff":-40,"type":"contempt","relation":"daughter-in-law","note":"Despises that his son married a gods-forsaken Imperial","worst":"Attending their wedding in Imperial territory"},"Imperial Legion":{"aff":-95,"type":"nemesis","relation":"sworn enemy","note":"Blames all Imperials for Lilija''s murder and makes no attempt to hide his hatred","worst":"Imperial soldiers killed his unarmed daughter and left her body to rot"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wary_outlaw', '{"Dark Brotherhood":{"aff":70,"type":"client","relation":"assassin guild sought","note":"Performed the Black Sacrament and desperately awaits their arrival to carry out his contract","best":"Completing the Black Sacrament ritual successfully","worst":"The agonizing wait in the tavern not knowing if they will come"},"Keerava":{"aff":10,"type":"transactional","relation":"innkeeper","note":"Tolerates his nervous presence at the Bee and Barb while he lays low"},"Former Bandit Associates":{"aff":-45,"type":"estranged","relation":"former comrades","note":"Relationships likely severed after circumstances drove him into hiding","worst":"Whatever falling out or betrayal endangered his life"},"Intended Contract Target":{"aff":-90,"type":"enemy","relation":"contract target","note":"Subject of his desperate revenge plot through the Dark Brotherhood","worst":"Whatever drove him to perform the Black Sacrament for revenge"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('watches-the-roots', '{"From-Deepest-Fathoms":{"aff":45,"type":"professional","relation":"expedition partner","note":"Shared his obsession with Dwemer artifacts; corrected him when he claimed the Lexicon''s knowledge as his alone","best":"She stood firm when others wavered, affirming the Lexicon''s knowledge would be ours"},"Breya":{"aff":20,"type":"professional","relation":"hired mercenary","note":"Motivated by pay but grew increasingly anxious about the dangers within Avanchnzel","worst":"Ignored her warning that something didn''t feel right before the trapped room"},"Drennen":{"aff":-5,"type":"dismissive","relation":"reluctant recruit","note":"Dismissed his valid fears as mere cowardice; Drennen ultimately fled the expedition","worst":"Called him a field mouse and let him leave rather than address his concerns"},"Dwemer scholars":{"aff":15,"type":"transactional","relation":"informants","note":"Provided information about the Lexicon''s location and the secrets of Dwemer memory storage"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('watchman', '{"Lord Harkon":{"aff":85,"type":"servant","relation":"master","note":"Serves with unquestioning, magically-conditioned loyalty","best":"Praising Lord Harkon as a great man to visitors"},"Lady Serana":{"aff":75,"type":"servant","relation":"master''s daughter","note":"Treats with reverence; overjoyed by her return after centuries","best":"Seeing Lady Serana return after all those years"},"Castle Volkihar Vampires":{"aff":60,"type":"servant","relation":"superiors","note":"Defers to all vampire inhabitants without question"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('weylin', '{"Madanach":{"aff":85,"type":"fanatical","relation":"leader","note":"Serves the Forsworn king in the shadows, fully devoted to his cause and the old gods"},"Nepos the Nose":{"aff":60,"type":"professional","relation":"handler","note":"Receives direct orders from Nepos for Forsworn operations in Markarth"},"Margret":{"aff":-90,"type":"enemy","relation":"assassination target","note":"Imperial spy marked for death to strike fear into the Nords","worst":"Attempted to murder her in the Markarth marketplace"},"Silver-Blood family":{"aff":-75,"type":"contempt","relation":"oppressors","note":"Exploited Reachmen workers and fueled his radicalization"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('whiterun_guard', '{"Jarl Balgruuf":{"aff":65,"type":"professional","relation":"liege lord","note":"Sworn to serve and protect under Balgruuf''s rule"},"Irileth":{"aff":45,"type":"professional","relation":"supervisor","note":"Housecarl who oversees and dispatches the guard force"},"Fellow Whiterun Guards":{"aff":70,"type":"platonic","relation":"brothers-in-arms","note":"Strong bonds forged through shared duty and danger"},"Citizens of Whiterun":{"aff":55,"type":"protective","relation":"wards","note":"Genuinely concerned for the safety of those under their watch"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wilhelm', '{"Lynly Star-Sung":{"aff":70,"type":"protective","relation":"employee","note":"Encourages her bardic performances and promised to keep her safe from the barrow''s ghost","best":"Told her she plays beautifully and it would be a shame if she stopped","worst":"Fearful when she went near the haunted barrow despite his warnings"},"Narfi":{"aff":40,"type":"pitying","relation":"troubled townsman","note":"Concerned for the disturbed resident''s wellbeing"},"Klimmek":{"aff":50,"type":"platonic","relation":"regular patron","note":"Friendly concern about his difficult supply runs to High Hrothgar","best":"Told him to take his time climbing, the Greybeards won''t complain"},"Temba Wide-Arm":{"aff":35,"type":"professional","relation":"fellow business owner","note":"Neighbor merchant in small-town Ivarstead"},"The Greybeards":{"aff":40,"type":"admirer","relation":"pilgrim hosts","note":"Respects their solitude and sustains the pilgrim traffic that passes through his inn"},"Bassianus":{"aff":40,"type":"platonic","relation":"patron","note":"Gives him romantic advice, urging him to follow his heart"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('willem', '{"Left Hand Mine":{"aff":25,"type":"professional","relation":"workplace","note":"Devoted miner who works obsessively but keeps distant from fellow workers"}}')
