INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wilmuth', '{"Nazeem":{"aff":-35,"type":"professional","relation":"employer","note":"Nazeem owns Chillfurrow Farm but rarely visits, leaving Wilmuth to single-handedly maintain it with little recognition or support","worst":"Works twelve-hour days for an absent owner who reaps all profits and ignores the farm"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('windhelm_guard', '{"Jarl Ulfric Stormcloak":{"aff":75,"type":"servant","relation":"Jarl and liege lord","note":"Serves with unwavering loyalty as both superior and symbol of Nordic traditions"},"Fellow Windhelm Guards":{"aff":65,"type":"platonic","relation":"brotherhood in arms","note":"Close-knit bond forged through shared duty and harsh conditions"},"Captain of the Guard":{"aff":55,"type":"professional","relation":"commanding officer","note":"Immediate superior in the guard chain of command"},"Nord Citizens of Windhelm":{"aff":60,"type":"protective","relation":"sworn charges","note":"Bound by duty and shared culture to protect Windhelm''s Nord population"},"Dunmer Residents":{"aff":15,"type":"suspicious","relation":"policed population","note":"Tense but professional; shares city''s prejudices yet maintains duty-bound conduct"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('winterhold_guard', '{"Jarl Korir":{"aff":70,"type":"professional","relation":"jarl","note":"Serves with unwavering loyalty as direct superior and leader of Winterhold"},"College of Winterhold":{"aff":-40,"type":"suspicious","relation":"distrusted institution","note":"Blames the College for the Great Collapse but maintains required professional courtesy","worst":"Lost family in the Great Collapse many locals attribute to College magic"},"Winterhold Citizens":{"aff":55,"type":"protective","relation":"townspeople","note":"Deeply protective of the few remaining residents of the shattered city"},"Fellow Winterhold Guards":{"aff":75,"type":"platonic","relation":"brotherhood","note":"Close-knit bond forged by shared duty in harsh and isolated conditions"},"Birna":{"aff":25,"type":"professional","relation":"merchant","note":"Frequent interaction as one of the few remaining shopkeepers in Winterhold"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wolf', '{"Pack Members":{"aff":85,"type":"protective","relation":"pack kin","note":"Fierce loyalty and coordinated hunting bonds define pack life","best":"Successful pack hunt bringing down large prey together","worst":"Loss of a packmate to hunters or predators"},"Alpha Pair":{"aff":75,"type":"platonic","relation":"pack leaders","note":"Deferred to in hierarchy but respected, not feared"},"Werewolves":{"aff":25,"type":"curious","relation":"kindred spirits","note":"Recognized as kindred and generally avoided unless provoked; will not attack in beast form"},"Humans":{"aff":-60,"type":"fearful","relation":"threats and occasional prey","note":"Viewed as dangerous but also potential food when circumstances allow"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wounded_soldier', '{"Danica Pure-Spring":{"aff":65,"type":"grateful","relation":"primary healer","note":"Deeply appreciative of her tireless efforts despite his unrelenting pain"},"Acolyte Jenssen":{"aff":45,"type":"grateful","relation":"caregiver","note":"Finds comfort in her regular ministrations and gentle presence"},"Commander Caius":{"aff":25,"type":"platonic","relation":"former commander","note":"Appreciates the occasional visits from his old superior"},"Whiterun Guards":{"aff":35,"type":"platonic","relation":"former comrades","note":"Values morale visits from former colleagues, though reminders of the life he lost"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wujeeta', '{"Bolli":{"aff":45,"type":"professional","relation":"employer","note":"Bolli pays well and watches out for his workers, but has threatened to fire Wujeeta over her addiction","best":"Bolli gave her a chance at the fishery after leaving the meadery","worst":"Bolli warned her she''ll lose her job if she shows up in her condition again"},"Sarthis Idren":{"aff":-60,"type":"fearful","relation":"skooma dealer","note":"Wujeeta fears her skooma dealer who supplies her destructive addiction"},"Indaryn":{"aff":-35,"type":"estranged","relation":"former employer","note":"Left Black-Briar Meadery due to conflicts with Indaryn, whom she found impatient","worst":"Indaryn had no patience and they never saw eye-to-eye"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wulf_wild-blood', '{"Torkild Wild-Blood":{"aff":75,"type":"familial","relation":"brother","note":"Disappeared and likely became a werebear; Wulf seeks to find and save him","best":"Growing up together as Skaal brothers","worst":"Torkild''s disappearance and apparent transformation"},"Frea":{"aff":55,"type":"platonic","relation":"fellow Skaal defender","note":"Shares commitment to protecting Skaal traditions and village"},"Storn Crag-Strider":{"aff":65,"type":"mentor","relation":"former shaman","note":"Deeply respected the former Shaman''s wisdom and spiritual leadership"},"Deor Woodcutter":{"aff":45,"type":"platonic","relation":"fellow Skaal villager","note":"Friendly neighbor; mentored him in archery and woodworking","best":"Gifted Deor a bow and praised his growing skill"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wulfgar', '{"Paarthurnax":{"aff":88,"type":"awed","relation":"revered master","note":"Guides the Greybeards from the summit; Wulfgar holds him in deepest spiritual reverence"},"Arngeir":{"aff":78,"type":"mentor","relation":"senior mentor","note":"Studied under Arngeir for decades; respects his leadership among the mortal Greybeards"},"Borri":{"aff":72,"type":"platonic","relation":"brother in the Voice","note":"Close companion in meditation and study; one of only two level 100 NPCs alongside him"},"Einarth":{"aff":68,"type":"platonic","relation":"fellow Greybeard","note":"Longtime companion in the pursuit of the Way of the Voice"},"Dragonborn":{"aff":55,"type":"student","relation":"student","note":"One of the Dragonborn''s initial tutors in the Way of the Voice","best":"Greeting the Dragonborn with recognition of their destiny","worst":"The rumble his Voice causes even in careful greeting"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wuunferth_the_unliving', '{"Ulfric Stormcloak":{"aff":70,"type":"professional","relation":"patron","note":"Serves as his court wizard and trusted magical advisor with evident loyalty"},"Jorleif":{"aff":20,"type":"professional","relation":"colleague","note":"Working relationship strained by Jorleif''s willingness to believe accusations","worst":"Had me dragged to the Bloodworks on false murder charges"},"Calixto Corrium":{"aff":-85,"type":"betrayed","relation":"framer","note":"Calixto deliberately framed Wuunferth for the Butcher murders to conceal his own crimes","worst":"Manipulated evidence to pin his killings on me"},"Viola Giordano":{"aff":-30,"type":"suspicious","relation":"accuser","note":"Spread rumors and directed accusations toward Wuunferth during the Butcher investigation"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wylandriah', '{"Jarl Laila Law-Giver":{"aff":35,"type":"patron","relation":"employer","note":"Wylandriah serves as her court wizard but routinely avoids tedious court duties to focus on research"},"Boti":{"aff":65,"type":"platonic","relation":"dear friend","note":"Friend in Ivarstead who sometimes assists with her experiments and tolerates her absent-minded visits","best":"left her Dwemer Stirring Spoon at Boti''s house, a sign of comfortable familiarity"},"College of Winterhold":{"aff":40,"type":"professional","relation":"alma mater","note":"Trained there and maintains loose connections with former colleagues, still recommends it to aspiring mages"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('wyndelius_gatharian', '{"Wilhelm":{"aff":-20,"type":"contempt","relation":"deception target","note":"Deliberately fools Wilhelm with ghost ruse to keep him away from the barrow","best":"Successfully maintained ghost deception for years"},"Ivarstead Locals":{"aff":-45,"type":"enemy","relation":"unwanted intruders","note":"Views villagers as obstacles to his search, uses ghost deception to scare them away","worst":"Locals keep investigating the barrow despite his haunting act"},"Fellow Scholars":{"aff":-15,"type":"estranged","relation":"former colleagues","note":"Abandoned academic connections in pursuit of the Sapphire Dragon Claw","worst":"Severed all ties when obsession took hold"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('xander', '{"Safia":{"aff":25,"type":"professional","relation":"captain","note":"Serves under her with mixed respect and quiet resentment after his fall from grace","best":"She gave him a berth when he had nothing","worst":"The humiliation of serving as a lowly crewman under another captain"},"Ship''s Crew":{"aff":-15,"type":"rival","relation":"shipmates","note":"Mock his refined tastes; he views their mockery as envy","worst":"Their constant ridicule of his love of finery"},"Angeline":{"aff":20,"type":"transactional","relation":"apothecary","note":"Discreetly treats his romantic misadventures and offers cautionary advice","best":"Her discreet and non-judgmental treatment"},"Taarie":{"aff":5,"type":"transactional","relation":"clothier","note":"Supplies his fine garments; somewhat dismissive of his worn clothing"},"Sayma":{"aff":5,"type":"transactional","relation":"supplier","note":"Provides ship supplies on order"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('yag_gra-gortwog', '{"Sulla Trebatius":{"aff":55,"type":"professional","relation":"employer","note":"Expedition leader who recognized her magical talents and hired her for the Alftand expedition","best":"Being valued for her magical abilities rather than dismissed as an Orc","worst":"The expedition he led ended in her death"},"Endrast":{"aff":85,"type":"protective","relation":"companion","note":"Fellow expedition member she died attempting to save from the Falmer","best":"Forming a close bond during the expedition","worst":"Dying while vainly attempting to cover his escape"},"Stronghold Family":{"aff":25,"type":"estranged","relation":"clan","note":"Left her stronghold to pursue magic, defying Orcish traditions","worst":"Facing cultural pressure and skepticism about pursuing magic instead of combat or smithing"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('yar_gro-gatuk', '{"Sinding":{"aff":-75,"type":"enemy","relation":"prey","note":"Primary target of the Great Hunt in Bloated Man''s Grotto","worst":"Elusive quarry who keeps slipping away"},"Fellow Hunters":{"aff":20,"type":"transactional","relation":"temporary allies","note":"Bound by mutual profit in the hunt for Sinding, not loyalty","best":"Profitable cooperation on the trail","worst":"Would abandon them if the hunt turned unprofitable"},"Former Stronghold":{"aff":-55,"type":"estranged","relation":"exiled clan","note":"Cast out in youth after challenging the chief''s authority","worst":"Stripped of place and kin for his pride"},"Local Bandit Groups":{"aff":-15,"type":"suspicious","relation":"territorial rivals","note":"Uneasy agreements maintained through shows of strength","worst":"Constant tension over territorial boundaries"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('yatul', '{"Mauhulakh":{"aff":75,"type":"obsessed","relation":"nephew","note":"Possessively loves and controls him, orchestrating deaths of his wives to keep him dependent on her","best":"When he comes to her for guidance about taking a new wife","worst":"When he wanders seeking a new woman"},"Bolar":{"aff":30,"type":"professional","relation":"accomplice","note":"Co-conspirator in eliminating Mauhulakh''s wives, though she scorns Bolar''s moral limits","worst":"Bolar''s refusal to harm a pregnant wife"},"Dushnamub":{"aff":-40,"type":"suspicious","relation":"nephew","note":"Distrusted nephew who suspects her involvement in his mothers'' deaths","worst":"His suspicious questions about the deaths"},"Urog":{"aff":40,"type":"mentor","relation":"great-niece","note":"Mentors Urog in tracking while subtly undermining Mauhulakh''s authority to her","best":"Teaching Urog to track snow cats"},"Mauhulakh''s wives":{"aff":-85,"type":"enemy","relation":"victims","note":"Orchestrated the deaths of multiple wives to prevent any from influencing the chief"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('yisra', '{"Phinis Gestor":{"aff":45,"type":"mentor","relation":"instructor","note":"Monitored her rapid progress and expressed genuine regret upon learning of her death","best":"Recognized her exceptional aptitude in destruction magic","worst":"Failed to prevent her fatal solo experiment with Flame Cloak"},"Family in Hammerfell":{"aff":-25,"type":"estranged","relation":"family","note":"Relations strained by her defiance of Redguard cultural skepticism toward magic","worst":"Left home against family wishes to pursue arcane studies"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('yngvar_the_singer', '{"Thongvor Silver-Blood":{"aff":65,"type":"professional","relation":"housecarl","note":"Loyal retainer elevated to trusted housecarl after Stormcloak victory"},"Faleen":{"aff":55,"type":"platonic","relation":"colleague","note":"Respected associate for whom he shows particular understanding in romantic matters"},"Calcelmo":{"aff":35,"type":"platonic","relation":"acquaintance","note":"Friendly connection through mutual link to Faleen"},"Vigilant Tyranus":{"aff":-25,"type":"dismissive","relation":"pest","note":"Annoyed by Tyranus''s persistent questions about the Abandoned House","worst":"Tyranus pestering him with nosy questions outside the Abandoned House"},"Bards College":{"aff":45,"type":"grateful","relation":"alma mater","note":"Educated there, maintains loose connections despite his warrior persona"}}')
