INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('yngvild_ghost', '{"Arondil":{"aff":-90,"type":"servant","relation":"enslaved thrall","note":"Captured, experimented on, killed, and eternally bound to serve the necromancer who destroyed her","worst":"The necromantic experiments that killed her and bound her spirit to his will forever"},"Ghost Maidens":{"aff":20,"type":"platonic","relation":"fellow victims","note":"Other women who share her fate as Arondil''s bound spirits, though none can truly interact"}}')
ON CONFLICT (npc_name) DO UPDATE
