INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('yrsa', '{"Deor Woodcutter":{"aff":85,"type":"romantic","relation":"husband","note":"Beloved husband with warm teasing rapport","best":"Discovered his hidden gift of spiced tea leaves meant to surprise her"},"Oslaf":{"aff":65,"type":"platonic","relation":"friend","note":"Fellow villager who eagerly anticipates her snowberry pies","best":"Friendly banter over his habit of eating an entire pie by himself"},"Fanari Strong-Voice":{"aff":50,"type":"platonic","relation":"village leader","note":"Respects her leadership but privately questions her outspokenness","worst":"Thinks Fanari speaks her mind more than she should"},"Storn Crag-Strider":{"aff":55,"type":"platonic","relation":"village elder","note":"Respected spiritual leader of the Skaal","worst":"Witnessed his sacrificial death and mourned deeply"},"Dark Elves of Raven Rock":{"aff":-25,"type":"suspicious","relation":"distant neighbors","note":"Maintains cautious isolationist attitude toward them","worst":"Believes they should keep to their city while the Skaal keep to their village"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('yrsarald_thrice-pierced', '{"Ulfric Stormcloak":{"aff":90,"type":"fanatical","relation":"supreme commander","note":"Considers Ulfric the only true High King of Skyrim and serves as one of his most trusted military advisors","best":"Being counted among Ulfric''s inner circle at the Palace of the Kings"},"Galmar Stone-Fist":{"aff":65,"type":"professional","relation":"fellow commander","note":"Strategic ally within the Stormcloak military leadership"},"Thalmor":{"aff":-95,"type":"nemesis","relation":"primary antagonist","note":"Intense hatred born from the Great War and the White-Gold Concordat that sold out Talos worship","worst":"Witnessing the Empire capitulate to Thalmor demands at the White-Gold Concordat"},"Imperial Legion":{"aff":-80,"type":"enemy","relation":"sworn enemy","note":"Views them as snowbacked traitors who sold out their people for a slave master''s peace treaty"},"Stormcloak Soldiers":{"aff":55,"type":"protective","relation":"commander","note":"Leads and inspires troops with his battle-hardened reputation and three legendary wounds"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ysgramor', '{"Five Hundred Companions":{"aff":95,"type":"protective","relation":"founder and war-leader","note":"Led the legendary army that drove the Snow Elves from Skyrim during the Return","best":"Standing victorious with his Companions after avenging Saarthal"},"Snow Elves":{"aff":-100,"type":"nemesis","relation":"sworn enemies","note":"Destroyed Saarthal in the Night of Tears; Ysgramor waged genocidal war against them in return","worst":"The Night of Tears and the slaughter at Saarthal"},"Shor":{"aff":90,"type":"servant","relation":"champion and hall-guardian","note":"Guards the Hall of Valor in Sovngarde by Shor''s command"},"Alduin":{"aff":-95,"type":"nemesis","relation":"ancient foe","note":"Alduin''s soul-snare traps honored dead in Sovngarde; Ysgramor aids the Dragonborn against him","worst":"Watching Alduin devour the souls of the honored dead"},"Kodlak Whitemane":{"aff":75,"type":"protective","relation":"spiritual successor","note":"Urges the Dragonborn not to fail Kodlak, who earned his place in Sovngarde"},"Dragonborn":{"aff":70,"type":"platonic","relation":"honored ally","note":"Welcomes the Dragonborn to Sovngarde and provides warriors to fight Alduin","best":"Greeting a worthy hero at the Hall of Valor"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('ysolda', '{"Hulda":{"aff":65,"type":"professional","relation":"role model","note":"Dreams of purchasing the Bannered Mare from her and taking over the inn"},"Mikael":{"aff":55,"type":"crush","relation":"romantic interest","note":"Frequently asks after him and praises his performances to others"},"Ma''dran":{"aff":55,"type":"mentor","relation":"trading mentor","note":"Khajiit caravan leader who promised to help launch her merchant career","best":"Agreed to help her become a caravaneer if she proved herself"},"Ulag":{"aff":25,"type":"transactional","relation":"sap supplier","note":"Secret Sleeping Tree Sap supplier until his death","worst":"Died leaving her without a reliable source for her illicit trade"}}')
ON CONFLICT (npc_name) DO UPDATE
SET relationships = EXCLUDED.relationships;

INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('zaria', '{"Jarl of Falkreath":{"aff":55,"type":"professional","relation":"alchemical advisor","note":"Trusted to handle sensitive matters like guard skooma addiction","best":"Rewarded with the Jarl''s ring for resolving the skooma incident"},"Family in Hammerfell":{"aff":-40,"type":"estranged","relation":"estranged family","note":"Left Hammerfell due to their disapproval of her lethal alchemy interests","worst":"Their rejection of her passion for poisons drove her from home"},"Falkreath Guards":{"aff":25,"type":"professional","relation":"potion supplier","note":"Supplies legitimate potions and occasionally assists with their problems"}}')
ON CONFLICT (npc_name) DO UPDATE
