INSERT INTO public.bio_templates (npc_name, relationships)
VALUES ('zaynabi', '{"Ahkari":{"aff":65,"type":"professional","relation":"employer and caravan leader","note":"Trusted member of Ahkari''s caravan, serves as scout and merchant"},"Dro''marash":{"aff":45,"type":"platonic","relation":"fellow caravan companion","note":"Travels and works alongside as part of the caravan family"},"Kharjo":{"aff":40,"type":"professional","relation":"caravan colleague","note":"Respected warrior of the caravan"},"Thieves Guild":{"aff":35,"type":"transactional","relation":"fence clients","note":"Serves as a fence for stolen goods after establishing contact"},"Maven Black-Briar":{"aff":15,"type":"transactional","relation":"distant business connection","note":"Indirect connection through Thieves Guild ties"}}')
